INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gününü Görmeyeceğim', 'gununu-gormeyecegim-huseyin-sigirtmac-ftxv1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ayrılık kahrına alış ey gönül.

Ayrılığa boyun eğmeyeceğim.

Hasret hüznü ile barış ey gönül.

Artık sana akıl vermeyeceğim.

Yıldızlar kaybolur gündüz olunca.

Şah sultanda gider ömrü dolunca.

Yakınlar uzaksa, yolcu yolunca.

Sahte dost izini sürmeyeceğim.

Dost haberi kesti uzak sevgiden.

Gidenler dönmüyor ne gelir elden.

Duygusuz anlamaz nağmeden telden.

Şiir ve türküyü yormayacağım.

Layık değil isen aşka sevdaya.

Ne efkara yenil, ne dal hülyaya.

Sığırtmaç sitemli dosta, dünyaya.

Anladım gününü görmeyeceğim.', 'Ayrılık kahrına alış ey gönül. Ayrılığa boyun eğmeyeceğim. Hasret hüznü ile barış ey gönül. Artık sana akıl vermeyeceğim. Yıldızlar kaybolur...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gununu-gormeyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nardayım', 'nardayim-huseyin-sigirtmac-6zw3q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gönlüme dost diye meyil verdiğim.

Sırt çevirdi şimdi, yalnız dardayım.

Hasretin kahrıyla yaşam kördüğüm.

Sensizliğe alışmadım zordayım.

Paylaşıp derdimi yalnız bıraktın.

Ben bir garip yolcu sense duraktın.

Düşüp ateşime seni de yaktın.

Külümü savurdun, yine nardayım.

Ben sağa giderken zorladın sola.

Yorulup dalında vermiştim mola.

Benimle dayanmaz gönlün bu yola.

Bazen eşiklerde bazen sırdayım.

Dürüstlük dışında bilmem meziyet.

Gönül söz anlasa çekmez eziyet.

Sığırtmaç uzaktır dosta nihayet.

Yollar engel dolu,bilmem nerdeyim?', 'Gönlüme dost diye meyil verdiğim. Sırt çevirdi şimdi, yalnız dardayım. Hasretin kahrıyla yaşam kördüğüm. Sensizliğe alışmadım zordayım. Payl...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı gülü hiç sevmedim', 'kirmizi-gulu-hic-sevmedim-ahmet-atmaca-vhu1v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ben kırmızıyı hiç sevmedim

yani güldeki  o sihirli  kırmızıyı

yani seni seviyorum demeyi hiç sevmedim

iki kelimelikse aşk; ben hiç aşık olmadım

yani korbir ateş sarmadı hiç yüreğimi

hiç uykusuz kalmadım  geceleri

yada hiç uykumdan uyanmadım

ansızın,

gözlerime, yani bakışlarıma işledim seni

damar -damar,desen -desen işledim

hiç başıboş bakmadım

hiç yok yere yanmadım

ve sensizliğe boşuna dayanmadım

bir güllükmü, sevdim seni

solacağını bile,bile

bir günlükmü sevdim seni

yada iki kelimedenmi ibaret

yüreğimin ansızın vuran sancıları

hayır; 

sancısında kaldım hep 

sana vuslatın

ve ne zor olduğunu öğrendim

sensizliğe dayanmanın

dedimya ben kırmızıyı

hiç sevmedim

yani körolayım

aşkımın kaderi birtek güle kaldıysa eğer

ve iki kelimeye

yani  seni seviyorum.........', 'ben kırmızıyı hiç sevmedim yani güldeki  o sihirli  kırmızıyı yani seni seviyorum demeyi hiç sevmedim iki kelimelikse aşk; ben hiç aşık olma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kirmizi-gulu-hic-sevmedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburmuydun', 'mecburmuydun-murat-demir-caaiu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne dediysen yaptım diye

Öl demeye mecburmuydun

Seni sevip taptım diye

Git demeye mecburmuydun

Bir ateş ki azabım var

Sokak sokak bağırdım yar

Saçlarıma beyaz karlar

Yağdırmaya mecburmuydun

Yaşatmaya böyle sonu

Bitirmeye bu oyunu

Aramıza onu bunu

Sığdırmaya mecburmuydun

Vermiş iken yüreğimi

Sevmiş iken candan seni

Şu sevdamın direğini

Yıktırmaya mecburmuydun

Tutturmayıp ellerinden

Koklatmayıp güllerinden

En sonunda beni senden

Bıktırmaya mecburmuydun!', 'Ne dediysen yaptım diye Öl demeye mecburmuydun Seni sevip taptım diye Git demeye mecburmuydun Bir ateş ki azabım var Sokak sokak bağırdım ya...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mecburmuydun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Olsun', 'benim-olsun-muharrem-ozturk-0azgr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canan’a gül vereyim gönlümün bahçesinden,

Rengi kanımın rengi,kokusu canım olsun.

Yıkılsın meyhaneler senin bülbül sesinden.

Her kadehte içilen bu sevda benim olsun.

Duyulmasın feryadım,sana susayan sesim,

Dudağımda dolaşan soluk,eski bir resim,

Boğazımda kuruyan,boğuklaşan nefesim,

Her busede bir defa,bin defa senin olsun.', 'Canan’a gül vereyim gönlümün bahçesinden, Rengi kanımın rengi,kokusu canım olsun. Yıkılsın meyhaneler senin bülbül sesinden. Her kadehte içi...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Öztürk']::text[], 8.5, '{"poet":"Muharrem Öztürk","poet_slug":"muharrem-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/benim-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin', 'nerdesin-mehmet-selim-togluk-un874', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Youtube Linki:

https://www.youtube.com/watch?v=nNKxRFJATO4

Sen gittin gideli, gülmedi yüzüm

Aylar geçti, yıllar geçti, gelmedin

İçimden hiç, eksilmedi bu hüzün

Kimbilir kiminlesin, nerdesin?

Hasretin içimde, kapanmaz yara

Kime gönül verdin, şimdi kimdesin

Kaç yıl oldu bilmem, ama bak hala

Kulağımda çınlar sesin, nerdesin?

Bir damla gözyaşı, geriye kalan

Unuttum desem de, vallahi yalan

İsmin dudağımdan, düşmedi bir an

Seni sayıklar dururum, nerdesin?

Bir kez daha görsem, güzel yüzünü

Nerelerde bulsam, bilmem izini?

Ömür boyu, çeksem senin nazını

Yüzümde ılık nefesin, nerdesin?

Gözümün pınarı, kurudu bitti

Gözlerimin nuru, sensin nerdesin?

İki ezan arasında, bir ömür bitti

Dediler dönülmeyecek yerdesin

Anladım ki dönülmeyen yerdesin

Sana gelmek benim de tek hevesim

Senden yana bir ses bana gel desin

		(Batman - 15.09.2004)', 'Youtube Linki: https://www.youtube.com/watch?v=nNKxRFJATO4 Sen gittin gideli, gülmedi yüzüm Aylar geçti, yıllar geçti, gelmedin İçimden hiç,...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Selim Toğluk']::text[], 8.5, '{"poet":"Mehmet Selim Toğluk","poet_slug":"mehmet-selim-togluk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/nerdesin-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zannetme', 'zannetme-tayyip-sag-k4go1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Güneşle beraber açılır perde,

Bir alem uyanır vakti seherde,

Herkes bir uğraşta ayrı bir yerde,

Rızkı için koşar gezer zannetme.

Umutlar tükenmez hayat sürdükçe,

Gelişir çoğalır ilgi gördükçe,

Paylaşılır dostça birlik oldukça,

Tükenip de bir gün biter zannetme.

Bu Dünya bir sahne bizler figüran,

Kazanır rolünü iyi oynayan,

Perdeler son defa kapandığı an,

Oyun biter artık açar zannetme.

              14.09.2004', 'Güneşle beraber açılır perde, Bir alem uyanır vakti seherde, Herkes bir uğraşta ayrı bir yerde, Rızkı için koşar gezer zannetme. Umutlar tük...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zannetme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hicret ettiğinde', 'hicret-ettiginde-ahmet-atmaca-invkh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güvercin olsaydım hep sana kanatlanırdım 

uçamazdım özgürce 

yüreğime tutuklu 

bulut olsaydım 

hep rüzgara kapılırdım 

bereketim gönül bahçene yağsın diye 

yeşerecekse umutlarım 

saz olsam 

nağmeler hep sessiz kalırdı 

dilimde 

senden uzaklarda 

dünyaya geldim 

sen galubeladan hicret ettiğinde 

şimdi bülbüller besteliyor en güzel sözlerimi 

sen hep düşlerime geldiğinde.', 'güvercin olsaydım hep sana kanatlanırdım  uçamazdım özgürce  yüreğime tutuklu  bulut olsaydım  hep rüzgara kapılırdım  bereketim gönül bahçe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hicret-ettiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Gibi', 'vatan-gibi-yuksel-kasim-237xy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hudutta nöbet beklerken

Ellerim

Silahımın tetiğinde üşürken

Gözlerin ısıttı beni bir tanem

Kefensiz gömdüler beni

Sen yatağında rahat uyurken

Tez elden gel buraya

Bırakma yalnız beni

Sen ki cennet kokarsın

Annem gibi

Elin elime değmedi

Ama sevdim seni

Vatan gibi...

1 Eylül 1997', 'Hudutta nöbet beklerken Ellerim Silahımın tetiğinde üşürken Gözlerin ısıttı beni bir tanem Kefensiz gömdüler beni Sen yatağında rahat uyurke...', ARRAY['Türk Edebiyatı','Şiir','Yüksel Kasım']::text[], 8.5, '{"poet":"Yüksel Kasım","poet_slug":"yuksel-kasim","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vatan-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akıldan Ziyade Divane Gönül', 'akildan-ziyade-divane-gonul-murat-demir-bk7w6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha çok çekersin sen bu gidişle

Yavaşça sönüyor yıldızın işte

Oysa parlıyordun oysa geçmişte

Akıldan ziyade divane gönül

Ne çiçek bıraktın ne gül ne bahçe

Hepsi birer birer soldu iç içe

Sonunda sen seni düşürdün hiçe

Akıldan ziyade divane gönül

Sanmadın uçarken düşeceğini

Zamanın su gibi geçeceğini

Bilmedin genç yaşta biteceğini

Akıldan ziyade divane gönül

Yara yar demedin cana ise can

Seni dar gününde neylesin insan

Ne çıkar cihanın sahibi olsan

Akıldan ziyade divane gönül

Derde deva desen sende bulunmaz

Eriğip gitsende soranın olmaz

Hayat bağı o ki çeksen kırılmaz

Akıldan ziyade divane gönül!', 'Daha çok çekersin sen bu gidişle Yavaşça sönüyor yıldızın işte Oysa parlıyordun oysa geçmişte Akıldan ziyade divane gönül Ne çiçek bıraktın ...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/akildan-ziyade-divane-gonul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-i-smet-barlioglu-whag4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Neye yarar gülün kırmızısı? 

Bülbülün sesi neye yarar,

Mehtap altındaki mahmur denizin kokusu,

Ormanların karanlık sessizliği,

Güneşlerin yamaçları öpe öpe yükselmesi

Ve yağmurun yağıp durması omuzlarıma? 

Neye yarar, sen olmayınca

Sana gelen yolların uzanıp serilmesi

Ayaklarımın altına

Halılarca? 

Rüzgarlar saçını okşadığında güzel,

Yağmur seni saçaklar altına kaçırdığında güzel,

Kumsal güzel, ayaklarının izini taşıdığında,

Yüzüne vurduğunda güzel mehtap,

Gül senin yanında,

Bülbül senin yanında güzel.

Senin bulunmadığın zaman, her şey

Heykel.

Sen heykele sesler veren dilsin,

Sen taşlara can veren ruhsun,

Sen yosunda, sen çiçekte, sen ormanda kokusun,

Sen gülde renk, bülbülde ahenksin,

Sen canımdan içeri can, yüreğimden içeri yüreksin,

Sana bedenimin tüm kapılarını açtım, anam-babam,

Girersen; 

Göreceksin.

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 29-30/100)', 'Neye yarar gülün kırmızısı?  Bülbülün sesi neye yarar, Mehtap altındaki mahmur denizin kokusu, Ormanların karanlık sessizliği, Güneşlerin ya...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neye-yarar-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölge Etmeyin Eloğulları', 'golge-etmeyin-elogullari-i-smet-barlioglu-pyq0b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölge etmeyin başıma, eloğulları…

Kim çare bulabilmiş ki; 

Siz çare bulabilesiniz gönül yarasına? 

Hiç karışıp durmayın

Şurasına-burasına,

Örselemeyin kanayan yüreğimi

Ve acılarımla baş başa bırakın

Beni.

Bir ben bilirim yüreğimin nasıl cayır cayır yandığını,

Bir ben bilirim nasıl alev aldığını,

Bir ben bilirim nasıl tutuştuğunu,

Bir ben bilirim neden merhem kar etmediğini,

Bir ben bilirim neden ölüp ölüp dirildiğini

Tanrı ‘nın her saati, her günü.

Çünkü ben yaşadım, siz yaşamadınız

Dünü,

Bugünü.

Bir ben yaşadım, ona da yaşamak denirse,

Soğanlara iftira ettim dökülen gözyaşlarım için,

İftiralar ettim kızılcık lerbetlerine,

Kalkıp yaşlılıklara bile yükler oldum sancılarımı,

Peki, ben bilmem de kim bilir

Acılarımı? 

Gölge etmeyin başıma, eloğulları…

Bağışlayın beni kaderimin güneşine,

İşlesin damarlarıma kederlerim hançer gibi,

Dolsun kemiklerim elemlerle ilik ilik

Bir büyük karasevdada yaşayıp gitmekteyim işte,

Şimdilik.

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 31-32/100)', 'Gölge etmeyin başıma, eloğulları… Kim çare bulabilmiş ki;  Siz çare bulabilesiniz gönül yarasına?  Hiç karışıp durmayın Şurasına-burasına, Ö...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/golge-etmeyin-elogullari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla Olmuşum Yağmurlarda', 'damla-olmusum-yagmurlarda-i-smet-barlioglu-v6eoy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Esinti olmuşum sabah rüzgarlarında, anam-babam,

Seni arayıp duruyorum köşe-bucak,

Damla olmuşum yüzümü kırbaçlayan yağmurlarda,

Şırıltı olmuşum taştan taşa atlayan sularda,

Gecekuşlarının gagalarında çığlık olmuşum

Ve bir sinsi feryat olup kalakalmışım ciğerlerimde,

Seni arayıp duruyorum

İki damla kanlı yaş

Gözlerimde.

Günler gelir selamsız-sabahsız, günler geçer önümden,

Karadan denize vurup geçen rüzgarlar misali,

Zamanı dizginlemek isterim, kabul etmez,

Kar etmez aklım başkaldıran yüreğime,

Yüreğim ayaklarıma çarık olmuş, elime değenek,

Ayak basmadığım hayal ülkesi kalmadı evrende,

Ben sıramı çoktan savdım, anam-babam,

Sıra

Sende.

Handiyse çıkacakmış gibisin biryerlerden,

Beni bulacak, bana gelecekmiş gibisin; 

Sesin çok yakınlarımda,

İzlerin var izlerime karışan,

Biryerlerden çıkacakmış gibisin

Sabah,

Akşam.

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 33-34/100)', 'Esinti olmuşum sabah rüzgarlarında, anam-babam, Seni arayıp duruyorum köşe-bucak, Damla olmuşum yüzümü kırbaçlayan yağmurlarda, Şırıltı olmu...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/damla-olmusum-yagmurlarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kâlp Satılık', 'bir-k-lp-satilik-ahmet-refik-tavsanli-1y4ez', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şöyle bi’ kâlp satılık..! 

…ölesiye seve’bilen,	

…canını vere’bilen…

Haraç-mezat giden..! 

…çoook çok ehven,

…hattâ meccânen..! 

Böyle bi’ kâlp satılık..! 

Şöyle bi’ kâlp aranıyor..! 

…duygu’dan yoksun,	 		

…taş gibi bi’ şey olsun...	

         

Yeter ki; Tik-tak vursun..! 	

 		

…aha şuracıkta dursun,		

…bana bi’ yoldaş olsun... 		

Böyle bi’ kâlp aranıyor..! 

07.12.2004

...(22.00) ...

.Karşıyaka.', 'Şöyle bi’ kâlp satılık..!  …ölesiye seve’bilen,	 …canını vere’bilen… Haraç-mezat giden..!  …çoook çok ehven, …hattâ meccânen..!  Böyle bi’ k...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-kalp-satilik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Yolu', 'hayat-yolu-atil-kesmen-0iww7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni 				

Sana tarif etsem				

İnan				

Kendini göremediğin bilemediğin				

Kendi gerçeğinden utanırsın....				

				

Sadece				

Ağız dolusu üç beş tatlı cümlede				

Birkaç dökülen kelime söylemek değildir				

Bu hayat içinde yaşanan cılız insanlık				

Hele hele				

Kunuşmaktan korkan dilin				

Özürlü gibi bakan gözlerin				

Seyir için takılmadı				

Bakıpta dans ettirdiğin yuvalarına......				

				

Bedeli ağırdır ama çok ağırdır				

Bu görülmez yükü taşırken				

Seyir defterine atmış olduğun imzaların				

Çünkü bu yük				

Kalp atışlarında				

Ritmi bozuk hareketlerinin 				

Çıkarmış olduğu seslerdir......				

				

Bırak ne olur bırak				

Kendini beyenmiş insan				

Sen tekmisin bu alemde				

Sen her bir şeyin en iyisini bilenmisin				

Senin bedenin çeliktenmi				

Duyguların rüzğarmı				

Kanın neden kırmızı değil				

Yoksa sen insan değilmisin.....				

				

Yürü yürü biraz olsun				

O nazik bedenine bağlantılı olan ayaklarınla				

Hemde ağır adımlarla				

Aman düşüp tökezlenmiyesin diye				

Korma cesaretli ol				

Silkelen silkelen biraz olsun				

Düşsün önüne düşüncelerindeki kendin				

Al tut kendini				

Sev kokla				

Öyle sevki kendini sever gibi				

Öyle koklaki kendini görür gibi...				

				

Bir  gün göreceksin kendini				

Fırsat kollamayıp kendine şans tanıdığın bu dünyada			

Yaşanılan hayatların acımasız çukurlarında				

Sessiz sessiz yanan ateşin alevlerini				

Utanacaksın				

Kendine alet ettiğin bedeninden				

Benliğinde gönlünde hissedeceksin				

Acı ile sevinci birlikte				

Ellerini açıp ben kimim diyeceksin				

Sende saklı kalmış				

Hiçbir zaman cesaret edip te				

Dil ucuna süremediğin kelimelerinle.....				

				

İşte o zaman göreceğin ışık				

Yüzünü yalayacak 				

Gönlünü dağlayacak				

Hatta dünyanı karartacak				

Hesap vereceksin kendin kendi gerçeğine				

Bir bir tüm beden dilinde.....				

				

Oyuncak edip bencil davrandığın hayatına				

Set kurmuş olsan bile				

Bu yolun sonuna geldiğinde				

Gözlerin kendinde seni görecek seni				

İşte o zaman gönlün buz tutacak				

Tüm hislerin yerlerinden kımıldayacak				

Duyguların ise senin için ağlayacak				

Yanlış seyir halinde olduğun				

Bu hayat yolunda..........', 'Seni 				 Sana tarif etsem				 İnan				 Kendini göremediğin bilemediğin				 Kendi gerçeğinden utanırsın....				 				 Sadece				 Ağız dolusu ...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/hayat-yolu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşe Koşan Pervane', 'atese-kosan-pervane-i-smet-barlioglu-xkoq5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pervaneye dönmüşüm, yavım-yavuklum,

Dolaşıp duruyorum çevrende,

Biliyorum dokundukça yanacağımı,

Kavrulup tutuşacağımı,

Kül kül olup döküleceğimi.

Biliyorum,

Değip dokundukça menzilime

Öleceğimi.

Pervane-mervane değildim seni sevmeden önce,

Günümü gün, yaslarımı düğün ederdim gün içinde,

Var olduğunu bile düşünmezdim bir yüreğimin,

Ateşin yakmayacağını,

Suyun boğmayacağını

Sanırdım.

Zevkle yatar, hazla uyanırdım,

Gülüp geçilecek bir şey olduğuna inanırdım sevdanın,

Meğerse; doğru yanı bu değilmiş

Dünyanın.

Öğrenmekte geç kalmışım Hanya ‘yı-Konya ‘yı,

Ateşe koşan pervanelere dönüverdim bir bakışınla,

Pervane dediğin ateşi yazın da arar, kışın da,

Onun içindir ki; seni arayıp duruyorum yıllardır,

Sana değmek için, sana dokunmak için, sende yanmak için,

Kül kül olup dökülmek için,

Yakmak, mahvetmek için bu günahsız yüreğimi,

Yani kırmak için su testisini su yolunda,

Olup olacağı da bu değil midir

Sonunda? 

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 35-36/100)', 'Pervaneye dönmüşüm, yavım-yavuklum, Dolaşıp duruyorum çevrende, Biliyorum dokundukça yanacağımı, Kavrulup tutuşacağımı, Kül kül olup dökülec...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/atese-kosan-pervane-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-i-smet-barlioglu-0z96p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kefil-mefil istemem, al canımı, alabildiğince,

Sana dağlar kadar güveniyorum,

Gün olur, elin düze çıkar, verirsin,

Çat kapı karşına çıkmam kötü alacaklılar gibi,

Yalanlara soyunmam ‘Darlarda kaldım.’ diye,

Gıdım gıdım ödersin,

Kıymık kıymık ödersin,

Artık paşa gönlün nasıl isterse.

Can üstüne daha da canlar veririm sana,

Gerekirse.

Sen bana can kadar gereklisin, cansız da kalsam,

Pencerelerime, kapılarıma gereklisin,

Halılarıma, kilimlerime gereklisin,

Döşememe, tavanıma gereklisin,

Sandalyeme, masama gereklisin,

Düşlerime, gerçeklerime gereklisin.

Tanrı ‘m yağ mum isteyene yağ mum,

Balmumu isteyene balmumu

Versin.

Sana gerekeceğini bilseydim; 

Can ekerdim tarlalarıma buğday yerine,

Canlar büyütürdüm bahçelerimde, saksılarımda,

Kırlarımı, çayırlarımı canla donatırdım

Ve cümle canlarımla seni beklerdim, gelesin diye,

Canımı beğenesin, alasın diye,

Can can canlar sunardım ellerine, avuçlarına,

Yakından can verir, uzaktan can postalardı

Ve canımı her sevip alışında

Yaşardım.

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 39-40/100) m', 'Kefil-mefil istemem, al canımı, alabildiğince, Sana dağlar kadar güveniyorum, Gün olur, elin düze çıkar, verirsin, Çat kapı karşına çıkmam k...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/can-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Öğretmeni', 'hayat-ogretmeni-mehmet-ozer-bd8gx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün seni rüyamda gördüm figen abla

Benim ablam,mahalledeki tüm gençlerin ablası

Taksiden ne de afilli inmiştin

Herkes birbirine şaşkınlıkla bakakalmıştı

Bu kadar güzel bir kadının 

Bu köhne mahallede ne işi vardı

Kim bilebilirdi ergenlik çağına gelmiş

Delikanlıların hayat öğretmeni olacağını

İlk defa kız arkadaşımla buluşacağımda

Dudaktan öpüşmeyi öğretmiştin ya  bana

Ben hala seninle öpüştüğüm gibi

Kimseyle öpüşmedim hayatımda

Senin verdiğin sıcaklığı 

Hissedemedim dudaklarımda

Daha kaç kişiyle böyle öpüşmüştün acaba

Terk edildiğim gün koşarak gelmiştim ya sana

 Hani göğüslerinin arasında ağladım

Hem de ne ağlamak hıçkıra hıçkıra

Senden sonra kimsenin  göğsünde ağlamadım inan bana

O meşhur gün geldiğinde yine sen vardın yanımda

Erkek olmama rağmen 

Mutluluktan uçmuştum senin kollarında

Hiç zor olmamıştı o zaman

Bekarlığa veda

O günden sonra hiç görmedim seni

Aramadım sormadım

Neredeydin ne yapıyordun nerede yaşıyordun

Hiç merak etmedim aslında

Rüyamda görünce seni

Tekrar görmek için titrek bir heyecan kapladı içimi

Ne bilebilirdim ki mahalleye gidince

Senin öldüğünü söyleyeceklerini

Hüzün kapladı yüreğimi

Oysa ne kadar özlemiştim seni

Bana bu dünyada ki ilklerimi öğreten 

Hayat öğretmenimi.', 'Dün seni rüyamda gördüm figen abla Benim ablam,mahalledeki tüm gençlerin ablası Taksiden ne de afilli inmiştin Herkes birbirine şaşkınlıkla ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Özer']::text[], 8.5, '{"poet":"Mehmet Özer","poet_slug":"mehmet-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/hayat-ogretmeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasevdanın Oyunu', 'karasevdanin-oyunu-i-smet-barlioglu-9nyfm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu da

Bu rüzgar elin gibi okşadı saçlarımı? 

Bu ay senin gibi bakıverdi yüzüme? 

Deniz, gözlerinin içi gibi güldü ışıl ışıl

Ve nasıl oldu da

Bir garip gecekuşu

Senin gibi sesleniverdi bana karanlıklarda? 

Yoksa karasevdanın yeni bir oyunu mu

Bu da? 

Boşuna mı rüzgarın ellerine bırakmışım saçlarımı? 

Ay ışığında sana ulaşan yolları buluşum,

İçimin deniz gibi arı-duru oluşu,

Boşuna mı? 

Ürperişim boşuna mı gecekuşlarının çığlıklarından,

Bir geçmişi bir gelecekmiş gibi bekleyişim yarından? 

Boşuna mı,

Konuşmadıklarını konuşuyormuşsun gibi

Duymam? 

Söz olmazsa; kulak neye yarar, anam-babam? 

Kulak olmazsa; söz neye yarar? 

Neye yarar seni görmeyince gözlerim,

Sana değip dokunmayınca ellerim? 

Bir ömür boyunca yerine ulaşamadıktan sonra

Neye yarar

Dileklerim? 

Dilerlerimi ırmaklar gibi saldım denizlere,

Rüzgarlara bağışladım mutluluklarımı,

Gözlerimin ferini karanlıklara,

Uzaklara sevinçlerimi,

Bıraktım bir acılarımı kendime,

Bir de çilelerimi.

Seni ancak böyle mutlu edebilirim edebilirsem; 

Değil mi? 

(ZAMANIN BİR DAR VAKTİ isimli Serbest Şiirler ''inden > 41-42/100)', 'Nasıl oldu da Bu rüzgar elin gibi okşadı saçlarımı?  Bu ay senin gibi bakıverdi yüzüme?  Deniz, gözlerinin içi gibi güldü ışıl ışıl Ve nasıl...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/karasevdanin-oyunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susuyorum', 'susuyorum-i-brahim-tolga-ozsoy-d2xx1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sesine susuyorum, 

Var mı böyle bir şey? 

Uyanıyorum geç vakitlerde, 

Dilim damağım bir nevi sahra, 

Tenim taklamakan, 

Kana kana içemiyorum dudaklarından. 

Kuruyorum, 

Soluyorum, 

Susuyorum! 

Açıp sayfalar dolusu, 

Sığınıyorum kelimelerine. 

Sen saklanıyorsun, ben teslim oluyorum. 

Geceler zifiri, geceler sıcak! 

Bende teslimiyet sende karanlık, 

Söyle! 

Güneş ne zaman doğacak? 

Yıkılıyor bu şehir, kelimelerin çığlık çığlık. 

Ah nedir bu sefalet, 

Nedir bu kuraklık? 

Gözlerim sağanak, 

Ben, susuyorum..

Eylül 2004 İstanbul', 'Sesine susuyorum,  Var mı böyle bir şey?  Uyanıyorum geç vakitlerde,  Dilim damağım bir nevi sahra,  Tenim taklamakan,  Kana kana içemiyorum...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Tolga Özsoy']::text[], 8.5, '{"poet":"İbrahim Tolga Özsoy","poet_slug":"i-brahim-tolga-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/susuyorum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son...', 'son-i-brahim-ethem-bingul-7n7k4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatıralar kalbe dolar, yığılır

Hasılatlar kasalara yığılır

Sadece bir kefen kalır sonunda

İnsan,düşüp ölür,yere yığılır....', 'Hatıralar kalbe dolar, yığılır Hasılatlar kasalara yığılır Sadece bir kefen kalır sonunda İnsan,düşüp ölür,yere yığılır.......', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-77-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Ve Sen', 'sokak-ve-sen-sirma-mersin-6mt4q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalnızlık kaldırımların

Köşe dönemeçlerinde

Hayalin çıkıyorsa karşıma...

Kesişen yolların 

Uzayan karanlığında

Düşüyorsa sensizliğin gölgesi, yüreğime....

Her çıkmaz sokakta

Hasretliğinle yüzyüze kalıyorsam...

Bu adımların arkasına saklanmış

Bir sevgi kucaklayacaksa, beni...

Bulamalıyım seni! 

13.09.04', 'Yalnızlık kaldırımların Köşe dönemeçlerinde Hayalin çıkıyorsa karşıma... Kesişen yolların  Uzayan karanlığında Düşüyorsa sensizliğin gölgesi...', ARRAY['Türk Edebiyatı','Şiir','Sırma Mersin']::text[], 8.5, '{"poet":"Sırma Mersin","poet_slug":"sirma-mersin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sokak-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçen Zamanlar', 'gecen-zamanlar-volkan-yoruc-2akmi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geçen zamanlardı en güzeli

Şarkılar çalardı kulaklarda

Ve mırıldanırdı insanlar

Tatlı bir melodi ve güzel sözlerle

Bakışırdı gözler öylesine sessizce

Geçen zamanlarda kaldı en duru hayaller

Sabah yıldızı bir başka parıldardı

Ezanlar okunurken

Bir başka kalkılırdı rüyalardan

Geçen zamanlardı en masumu

Utanırdık bakışmalardan

Utanırdık elele dolaşmaktan

Bir kalem bir kağıttı şahidimiz o zamanlar

Aşklara dair yazılarda

Özlem bir başka çekilirdi yürekten

Bambaşkaydı yaşanmış o günler

Mazi dediğimiz sayfalara yazdık artık

Değişti zaman değişti herşey

Aşklar artık solgun

Rüyalar artık durgun

Geçen zamanlardı en yaşanası', 'Geçen zamanlardı en güzeli Şarkılar çalardı kulaklarda Ve mırıldanırdı insanlar Tatlı bir melodi ve güzel sözlerle Bakışırdı gözler öylesine...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gecen-zamanlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelme İsteme Artık', 'gelme-i-steme-artik-hakan-alparslan-5mykh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey gidi, bu denli savurmaya ne hakkın var.

Bu şehri kuşatmaya varlığınla ya da.

Kaçacak yer, pussuz zihin kalmadı benliğimde,

Kauçuk yollarda mecalim de.

Tabulaştıracak bir sözüm yok sana,

Yarın duyuracak adın da.

Melankoli zamanlar ayak ucumda nöbette,

Ben ise sensizlikle volta hayalinde.

Yapraklar firarda,

Renkler kendini şaşırmış, turuncu tomurcuklar hele.

Yine mi ters döngüler, yıkımlar.

Hayatım mevzu-bahis yine, haberim var.

Yağlı ipin parıltısı içimi acıtıyor.

Hayır bu sefer olmayacak.

Yoksun artık, inanamadığım kadar,

Ve olamadığın kadar çoksun.

Gelme, istemem artık...

                                          15.06.04', 'Hey gidi, bu denli savurmaya ne hakkın var. Bu şehri kuşatmaya varlığınla ya da. Kaçacak yer, pussuz zihin kalmadı benliğimde, Kauçuk yollar...', ARRAY['Türk Edebiyatı','Şiir','Hakan Alparslan']::text[], 8.5, '{"poet":"Hakan Alparslan","poet_slug":"hakan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelme-isteme-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Diyemem', 'gel-diyemem-hakan-alparslan-p7c4s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi zaman bir, hiçbir şey için yalnız kalır insan.

Şehrin ıssız kalabalığında boğulası gelir.

Bilinçsiz yollarda, hep aynı simaçlarla; 

Farklı yaşamlar içinde sadece bir dinginlik arar.

İskelede bir balıkçı teknesi düşün,

Işığı, yosun kokusu gözlerimi kamaştırıyor.

Üstüm, başım is kokusu.

Bir nefes alabilsem,

Keşkeler de boğulmasam keşke.

Belki çok yakınsın, bir merhabaya uzak.

Buralarda yollar inadına arnavut kaldırımı,

Çiçekler solgun.

Kardelenler yaz günü, yüzünü gösteriyor.

Bir bu kadar beyaz, bir bu kadar apansız.

Dalgalarla gelmiyor nitekim yalnızlığım,

Ben bu denli savruk olmamalıyım.

Gel diyemem, o kadar kolay değil...

Unut gitsin, geride sırma kaplı bir el emeği.

Kanaviçenin bende anısı neyse,

Bildiğin denli savur sende.

Üşüyorum sadece.

Ben bensizim, şehir ayaklar altında.

Gel diyemem, o kadar kolay değil...

				19.08.04', 'Kimi zaman bir, hiçbir şey için yalnız kalır insan. Şehrin ıssız kalabalığında boğulası gelir. Bilinçsiz yollarda, hep aynı simaçlarla;  Far...', ARRAY['Türk Edebiyatı','Şiir','Hakan Alparslan']::text[], 8.5, '{"poet":"Hakan Alparslan","poet_slug":"hakan-alparslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-diyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyanlar İçindeyim', 'i-syanlar-i-cindeyim-volkan-yoruc-igkk8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İsyanlar içindeyim

Kimbilir ki nerede olduğumu

Belki gökyüzünde belki yerin dibinde

İsyankarlığa yelken açmışım

İsyanlı dalgalar içinde

Uçsuz bucaksız boşluklarda

Zift karası akşamlarda

İsyanlar içindeyim

Aşkadır isyanım

Arkadaşlığa dostluğadır isyanım

Anlaşılması güç durumlardayım

Hayata benim isyanım

Bir şehir içinde yapayalnızım

Duvarlar dizili önümde

Taşlar yığılmış gönlüme

Vurmuşlar sırtımdan sinsice

Ölümüşüm ben buralarda

Loş ve yapayalnız sokaklarda

İsyanlar içindeyim

Çakılı kalmışım bu hayat dallarında', 'İsyanlar içindeyim Kimbilir ki nerede olduğumu Belki gökyüzünde belki yerin dibinde İsyankarlığa yelken açmışım İsyanlı dalgalar içinde Uçsu...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/isyanlar-icindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Beni Unut', 'sen-beni-unut-hifzi-ozbekmez-ttq52', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana yar olamam bunu bilesin

Eğer aklın varsa sen beni unut

Başkasını sevip mutlu olasın

Eğer aklın varsa sen beni unut

Zorla hiç güzellik olmaz bilirsin

Ne diye üstüme böyle gelirsin

Dua et Allah’ım sabırlar versin

Eğer aklın varsa sen beni unut

Sen kendinden nefret ettirme beni

Boşuna sevmişim dedirme  seni

Bulursun sevgili kendine yeni

Eğer aklın varsa sen beni unut

Latifim söylerim bu son sözümdür

Başıma gelenler alın yazımdır

Aklın başa devşir istersen çıldır

Eğer aklın varsa sen beni unut

25  AĞUSTOS 2004 SAAT:08:00', 'Sana yar olamam bunu bilesin Eğer aklın varsa sen beni unut Başkasını sevip mutlu olasın Eğer aklın varsa sen beni unut Zorla hiç güzellik o...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-beni-unut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paratoner', 'paratoner-bunyamin-nesimoglu-0n1t5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gül  benizli gül kokulu yar

senin tadına varmak 

acılaştırıyor bütün zevkleri

kaybedince seni

kaybettim sevgiyi,aşkı, mutluluğu

haylimdeki her karede sen varsın

senin suretin var

izliyorum kopuk şeritli filmi

antik tiyatrolarda

filmin sonunu bilerek

bir daha, bir daha

ruhum mazoşist krizde

ayrılığın cinnetini geçiriyorum 

bağırıp haykırmak istiyorum

tanrım ey tanrım

ben senin bela paratonerin miyim? 

