INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-bunyamin-nesimoglu-ec56s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KİMLİK

Adı: Askerlik

Yer: Gaziemir

ey  beynimin içindeki kurt

kemir yüreğimi kemir

özlemini çekersin 

sarının kırmızının

yeşiller içindeyken

yukarıdan gelen her emir 

içine ürperti verir

hayallere dalarsın

Kösedağın başındaki buzlar

ağustos sıcağında  terlerken

içini  ürpertir,titrersin

tuzlu  suyuyla vücudun 

yaranı dağlarsın

geç olmadan uyanırsın

Adı: Askerlik

Yer: Gaziemir

Ey beynimin içindeki kurt

Kemir yüreğimi kemir

					21.08.98 gaziemir', 'KİMLİK Adı: Askerlik Yer: Gaziemir ey  beynimin içindeki kurt kemir yüreğimi kemir özlemini çekersin  sarının kırmızının yeşiller içindeyken...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Nesimoğlu']::text[], 8.5, '{"poet":"Bünyamin Nesimoğlu","poet_slug":"bunyamin-nesimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kimlik-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancı', 'sanci-bunyamin-nesimoglu-qajy6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sancı

Dikenli tellerle çevrilmiş

Ümidim,aşkım, yarınım

Yaşarken ölmenin tadı

Tek düze her şeyim

Hatta adım

Beynimde sancı

Severken acını

Yarın yeniden doğacağım

Narkozsuz…….

Toplumun rahminde hastalıklı bir cenin

Tatlı günahların yasak meyvası

Beklenen an geldiğin de

Sessiz sessiz ağlarım

Hayat ve ümitlerim son bulurken

Ölü doğum kaderim

Dikenli tellerle çevrilmiş

Ümidim, aşkım, yarınım

Yarın yeni bir gün olacak mı? 

Belki yarın

Beklenen yarın olacak

Yeni bir hayata  başlarken

Ümidin depremi

Ölü doğmuş tür bebeğim……………

									Ağs.98 g.emir', 'Sancı Dikenli tellerle çevrilmiş Ümidim,aşkım, yarınım Yaşarken ölmenin tadı Tek düze her şeyim Hatta adım Beynimde sancı Severken acını Yar...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Nesimoğlu']::text[], 8.5, '{"poet":"Bünyamin Nesimoğlu","poet_slug":"bunyamin-nesimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sanci-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Borcum var', 'borcum-var-mumtaz-biler-jz549', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Giderken kapiyi vurup ciktim,

Sen yoktun o an, habersiz kactim,

Bu ask sayfasini, böylece kapattim,

Karsilasirsak biyerlerde, sana bir veda borcum var,

Bilmemki ne idi alip veremedigimiz,

Sen tamdin amma, bendim eksigimiz,

Deger verip, saygi duymakti bilemedigimiz,

Barisirsak bigün gelirde, sana bir vefa borcum var,

Dügün bayram görüp dolasamadik,

Sen sendin de, insana karisamadik,

Dert kederden basimizi kaldiramadik,

Bulusursak belki ilerde, sana bir sefa borcum var,

Uykular kabustu hep bize,

Sen yari uyaniktin, bense uzak yatagimiza,

Sarilamadik bir türlü sevgimize,

Yorulursak sende veya bende, sana bir rüya borcum var,

Alin terimizdi yeyip ictigimiz,

Sen hep calistin da, ayakta durdu evimiz,

Bikac esya ve yarali gönüllerdi tüm servetimiz,

Oturursak bigün hakim önünde, sana biraz para borcum var,

Yüce bir ask ile sevip basladik,

Sen hep sirindin de, biz ferhati bulamadik,

Ölüm ayirir dedik, hic bitmeyecek sandik,

Kavusursak o gün mahserde, sana bir sevda borcum var.

(Münih/Almanya 31.08.2004)', 'Giderken kapiyi vurup ciktim, Sen yoktun o an, habersiz kactim, Bu ask sayfasini, böylece kapattim, Karsilasirsak biyerlerde, sana bir veda ...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Biler']::text[], 8.5, '{"poet":"Mümtaz Biler","poet_slug":"mumtaz-biler","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/borcum-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ederin', 'ederin-sair-asivan-mouo4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gençmişim....

Toymuş kalbim, 

Boşmuş beynim. 

Beni ağlatmalarına,aşk demişim. 

Şimdi farkettim 

Hakettiğin değeri vermemişim. 

Kaç para üstündeki takım elbise? 

O kadar ederin.', 'Gençmişim.... Toymuş kalbim,  Boşmuş beynim.  Beni ağlatmalarına,aşk demişim.  Şimdi farkettim  Hakettiğin değeri vermemişim.  Kaç para üstü...', ARRAY['Türk Edebiyatı','Şiir','Şair Asivan']::text[], 8.5, '{"poet":"Şair Asivan","poet_slug":"sair-asivan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ederin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Hıçkırıyorum', 'sanki-hickiriyorum-atil-kesmen-hwu9n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dermansız kaldım yıkıldıkça çöküyorum

Acılarımı ateş yaptım yalnız geziyorum

Ağlamak ne kelime sanki hıçkırıyorum

Bu dünyada acı çeken sadece benmi oluyorum

Dizlerim titriyor gözlerim görmüyor

Bu beden benden hesapmı soruyor

Bir yanda acılarım

Bir yanda ateş

Kahroldukça

Bu dünyada nereye gittiğimi bilemiyorum.

Ateş olmuş acılarıma set kuramıyorum

Yalnız kaldım bu dünyada kendimi bulamıyorum

Ağlamak ne kelime sanki hıçkırıyorum

Bu dünyada yanan sadece benmi oluyorum....', 'Dermansız kaldım yıkıldıkça çöküyorum Acılarımı ateş yaptım yalnız geziyorum Ağlamak ne kelime sanki hıçkırıyorum Bu dünyada acı çeken sadec...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sanki-hickiriyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzağındayım', 'uzagindayim-huseyin-sigirtmac-5vhqc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasrete düştüm de uzağındayım.

Gün gelir sevgimi arayacaksın.

Ben zaten efkarın tuzağındayım.

Alevsiz dumansız sen yanacaksın.

Zırhlara bürüdün duygularını.

Kurtardın mı bensiz kaygılarını? 

Dost olan çekmez mi dostun kahrını? 

İlgisiz sevgisiz kuruyacaksın.

Mutluluk diyarın bensizlik ise.

İşte uzaktayım ses vermem asla.

Kayıp diye ilanım ver herkese.

Beni şiirlere hep soracaksın.

Sığırtmaç hasreti yakar sineni.

Ayrılık derdiyle gör ahengini.

Belki ilaç olur sakla sevgini.

Kahrınla dünyayı durduracaksın.', 'Hasrete düştüm de uzağındayım. Gün gelir sevgimi arayacaksın. Ben zaten efkarın tuzağındayım. Alevsiz dumansız sen yanacaksın. Zırhlara bürü...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Sığırtmaç']::text[], 8.5, '{"poet":"Hüseyin Sığırtmaç","poet_slug":"huseyin-sigirtmac","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzagindayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gittin Gideli', 'sen-gittin-gideli-mumtaz-biler-tprp0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Odam karanlik, isigim los,

Birlikte cekildigimiz resim, o cerceve bos,

Aklim karisik, basim sarhos,

Iciyorum sen gittin gideli,

Eski beni, bende bulamiyorum,

Yarim kaldim seniz, tam olamiyorum,

Aynalarda kendimi ariyorum,

Kayboldum sen gittin gideli,

Evim artik soguk, buz kesiyor,

Kis girdi penceremden, yaz girmiyor,

Sobam bile bana küs, hic isitmiyor,

Üsüyorum sen gittin gideli,

Kapimi calan yok, kimse sormuyor,

Vefasizmis dostlar, hicbiri ugramiyor,

Dert sorarsan cok, eksik olmuyor,

Yalniz kaldim sen gittin gideli,

Agzim yemiyor icmiyor, acligi unuttu,

Uykusuzluk bitmiyor, bedenimi kuruttu,

Gönül senden gecmiyor, illede seni tutturdu,

Kuruyorum sen gittin gideli,

Hatiralarindir beni ayakta tutan,

Sensin vefasiz, sensin unutan,

Kiyardim bu canima aslinda coktan,

Hapsoldum sen gittin gideli

Belki gün gelir dönersin diye,

Yumusar tas kalbin, hatirlarsin diye,

Yolun burdan gecer, kapimi calarsin diye,

Bekliyorum sen gittin gideli,

Dünya nimetinden gözümü kestim,

Kevser degil, ben yar askindan ictim,

Seni binbir güzel icinden sectim,

Sevdalandim sen gittin gideli,

Volkanlar neymis, icimde yanan atesi gör,

Gönül öksüzmüs, getirin bana o yari der,

En azindan bir haber sal, bir umut bir isik ver,

Yaniyorum sen gittin gideli.

(Münih/Almanya 02.09.2004)', 'Odam karanlik, isigim los, Birlikte cekildigimiz resim, o cerceve bos, Aklim karisik, basim sarhos, Iciyorum sen gittin gideli, Eski beni, b...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Biler']::text[], 8.5, '{"poet":"Mümtaz Biler","poet_slug":"mumtaz-biler","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-gittin-gideli-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçüğüm', 'kucugum-huseyin-erdogan-be4b7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana hep küçüğüm diyeceğim

Ne olur bana darılma

Seni var gücümle seveceğim

İstemezsen sen bana hiç sarılma

Sen hiç büyüme

Küçüğüm olarak kal yanımda

Bırak ben yaşlanayım sevdanla

Sen hiç arayıp sormasan da

İnan hep sen olacaksın

benim dünyamda

Bak işte

Kalemim bile ağlıyor yokluğunda

Ararsan kendini bulacaksın mısralarımda...', 'Sana hep küçüğüm diyeceğim Ne olur bana darılma Seni var gücümle seveceğim İstemezsen sen bana hiç sarılma Sen hiç büyüme Küçüğüm olarak kal...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kucugum-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarmaşık İle Hanımeli''nin Hazin Aşkı...', 'sarmasik-i-le-hanimeli-nin-hazin-aski-tulay-sustam-aeo5m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hanımeli bahar gelince açar bir sarı, bir beyaz

Durmadan gece ve gündüz  vurur yapraklarına ayaz 

Sevdiği Sarmaşığı ister durur yanar alaz, alaz

Aklı Sarmaşık da bir onsuz yapamaz, onu unutamaz

Oysa Sarmaşık aşıktır içten içe meçhul çiçeğe

Hanımeli aşkını söyler sevdiğine, gökyüzüne

Çaresiz aşkın pençesine düşmüş ne yapsın, neyleye

Her geçen gün biraz daha erir, solar kendi içinde

Onun adı Sarm(aşık) , meçhul çiçeğe daha çok aşık

Hanımeli ömrünce sevip sevilmemeye alışık

Hanımeli görmez, bilmez başkasını aklı karışık 

Her gün sever yine de Sarmaşığı aşkıyla barışık



Her çiçek Sarmaşığın kendisini sarmasını ister

Hanımeli onun bir yaprağına dokunmayı seçer

Sarmaşık; güneşi, suyu,  toprağı yalnız onu bekler

Sarmaşığın sevdiğine kavuşması için duâ eder. 

(Sarmaşık; yüreğimde sevgin, sen yüreğinde ki sevginle kal....)', 'Hanımeli bahar gelince açar bir sarı, bir beyaz Durmadan gece ve gündüz  vurur yapraklarına ayaz  Sevdiği Sarmaşığı ister durur yanar alaz, ...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sarmasik-ile-hanimeli-nin-hazin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Silinen Bakış...', 'silinen-bakis-abir-zaki-8jxix', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gecenin karanlığına teslim olmak için 

devrilirken vakit bir kış akşamında 

sarkmış kirpiğinin ufka uzayan 

okyanusundan bir damla 

akmak ve dökülmek için, yanağında 

bir iz arıyordu 

birdenbire 

bir damla suya hasretiyle bir denizcinin 

kaldırırken bir parmak, çeneni senin 

gözünden süzülen ilk damla yaş 

düşüp toprağa dağılıyordu 

9.9.2004 02:00 

Çeviren: Kadi®Deniz

***************************************************************************************

Muted Gaze... 

when the winter afternoon was suspended 

to surrender itself to the darkness of dusk 

A tear 

……/ from the ocean that stretches to the horizon /…… 

in the lowered eyelashes 

was checking a trace 

and threatened to spill over… 

In a flash 

……/ with a mariner’s thirst for a dropp of water /…… 

a finger 

lifted the chin 

while the pellets that were 

heaved by the world 

from thy eyes 

...................muted... 

August 21, 2004', 'gecenin karanlığına teslim olmak için  devrilirken vakit bir kış akşamında  sarkmış kirpiğinin ufka uzayan  okyanusundan bir damla  akmak ve...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/silinen-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Özledimki', 'oyle-ozledimki-hifzi-ozbekmez-squ6e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gök yüzünde güneş gibi

Yer yüzünde bir eş gibi

Gözümden akan yaş gibi

Seni öyle özledim ki 

Aklımdasın her saniye 

Aşkı oldun bu faniye

Derdinden döndüm deliye

Seni öyle özledim ki 

Geçmez oldu saniyeler

Hasretin bağrımı deler

Dertlerim boynuma biner

Seni öyle özledim ki 

Dayanacak hal kalmadı

Tutunacak dal kalmadı

Gideceğim yol kalmadı

Seni öyle özledim ki 

İşte böyle gülüm halim

Kurudu hep ağzım dilim

Bitsin artık çektiklerim

Seni öyle özledim ki 

Latif böyle söyler gezer

Hasretin gönlünü üzer

Artık hayatından bezer

Seni öyle özledim ki 

28  AĞUSTOS 2004 SAAT:02:00', 'Gök yüzünde güneş gibi Yer yüzünde bir eş gibi Gözümden akan yaş gibi Seni öyle özledim ki  Aklımdasın her saniye  Aşkı oldun bu faniye Derd...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/oyle-ozledimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haramdır', 'haramdir-kemal-sume-7on4x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Haramdır yaşamak; 

Heveslenişlerim..

Hayallerim..

Güzel bir günü sevgilinin dizlerinde bitirmek; 

Özlem duymak, 

Aramak,

Beklemek güzeldir de,

Kavuşmak haramdır...

Uzattığın eller dikenlere takılırken,

Gülü koklamak çok mu görülür dersin? 

Uzaktan bakmak,

Sabır dökmek güzeldir de,

Koklamak; 

Sarmalamak haramdır...

Gülüşleri dudaklarda tüketmek,

''Zordur...''

Belli etmemeye çalışırsın...

Şiir yazamayışlarına üzülmek,

Kavuşamamaya üzülmek gibidir..

Ve dolmuştur yürek; 

Taşıyamazsın...

Bilirsin...

Her gidişin bir dönüşü vardır,

Ama her dönüş bir gidişte saklıdır; 

Bulamazsın yolunu...

Gidişler pek kolay olsa da,

Dönüşler, 

Vazgeçişler,

Haramdır...

E. Kemal Süme / 21,03,2004', 'Haramdır yaşamak;  Heveslenişlerim.. Hayallerim.. Güzel bir günü sevgilinin dizlerinde bitirmek;  Özlem duymak,  Aramak, Beklemek güzeldir d...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/haramdir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanç', 'utanc-ali-gencay-6ty1v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ürpertecek içini

dibini bilmediğin 

kör geceler

gözlerine ışık düşürmeyecek

nikotin kokan 

kararmış perdeler

fahişeler değecek tenine

üstünde yatağın

satılık gülüşler

altında 

hamamdan kaçan böcekler

bitirecek sigaranı

dudakları kırmızıya çalan 

vesikalı bedenler

sahne bildik

ezberinde söylenecekler

telefon zili beklenen

giyilir yüksek topuklar

aşkım hoşça kal

ne kadar çok verirsen

o kadar çok

gömleğinde

rujdan lekeler

o kadar çok

aşk denen 

tek heceler

bu mu

yalnızlığın

bu mu insanlığın

hederin 

kederini yaşayansın

kaç kadın değdi tenine

kaç kez döküldü 

dudaklara kiralık aşk

kırmızıyı şarapta 

tanıyansın

at bahşişini

pezevenkler 

havada kapsın

sokma kafanı

paltonun dik yakalarına

oturmuş seni izleyenler

köşe başına

utanma

gülmezler

onlarda benzer

senden daha çok

sana…', 'ürpertecek içini dibini bilmediğin  kör geceler gözlerine ışık düşürmeyecek nikotin kokan  kararmış perdeler fahişeler değecek tenine üstünd...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/utanc-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kizginim', 'kizginim-ahmet-yilmaz-4gxm9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kızgınım

Yugoslavya Savaşı sonrasında göç eden Bosnalılar''a

Size kızgınım öğretmenlerim 

Bana hep yanlışı öğrettiniz 

Bana hep masallar okudunuz 

Dünyayı barışın kurtaracağını söylediniz 

Sağıma bakıyorum savaş, solumda açlık 

Barış güvercinlerinin uçuştuğu dünya hayal ederken 

Başımın üstünden mermiler geçiyor 

Yanıbaşımda açlıktan ağlayan çocuk duruyor... 

Size, hepinize kızgınım öğretmenlerim... 

Bana çevreyi temiz tut diye öğrettiniz 

Yeşili koru, dünyayı koru dediniz 

Sağıma bakıyorum artıklar, solumda nükler patlamalar 

Temizlikten, çevre korumasından eser yok. 

Size, hepinize inanmıştım 

Barışı sevgiyi ilke edinmiştim 

İnsanlara saygıyı en büyük görev bilmiştim 

Bana masal anlattınız, şimdi anladım, 

Hepinize kızgınım...

Ahmet Yılmaz', 'Kızgınım Yugoslavya Savaşı sonrasında göç eden Bosnalılar''a Size kızgınım öğretmenlerim  Bana hep yanlışı öğrettiniz  Bana hep masallar okud...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kizginim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem', 'annem-ahmet-yilmaz-6jn08', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün anneler günü,

Sana bir demet çiçek veremediğim için

üzgünüm anne! 

Elini öpemediğim için üzgünüm anne! 

Senden uzaklarda olduğum için üzgünüm anne! 

Asıl onemlisi, yüreğine hasret ve

özlem koyduğum için üzgünüm anne! 

Ama uzaklarda da olsam, sen çok yakınımdasın

Çoğu zaman yüreğimdesin

Sana saygım ve sevgim anlatılmaz büyüklükte

Emeğini hiçbir zaman ödeyemeyeceğim annem,

Anneler günün kutlu olsun!', 'Bugün anneler günü, Sana bir demet çiçek veremediğim için üzgünüm anne!  Elini öpemediğim için üzgünüm anne!  Senden uzaklarda olduğum için ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/annem-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haksizlik', 'haksizlik-ahmet-yilmaz-weo8q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Haksızlık

İçimden haykırmak geliyor çok seslice

Dağları yerinden oynatacak, insanları yürekten uyandıracak

Haksızlıklara, zulüm yapanlara korku verecek

Bir haykırış olmasını istiyorum

Yeter bu kadar zulüm, yeter bu haksızlıklar

Şuna göz yummayın be insanlar

Geçmişte belki siz de acısını çektiniz bu haksızlıkların

Neden şimdi susuyorsunuz üç kuruşluk çıkarınız için? 

Ha şöyle bir bakın, kim kimin yurdunu elinden alıyor! 

Şu iğrençliğe bak, kim kime tecavüzde bulunuyor! 

Kim kimin srtına binmiş de eziyor! 

Şunu bir görün de karşı çıkın be insanlar.

Vicdan sahibi olanlar! .', 'Haksızlık İçimden haykırmak geliyor çok seslice Dağları yerinden oynatacak, insanları yürekten uyandıracak Haksızlıklara, zulüm yapanlara ko...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/haksizlik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özleyiş', 'ozleyis-yavuz-i-ren-abvh2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bırakın büyümeyin çocuklar 

gülüp,eğlenmeye devam edin 

korkuyorum sizide bulaştırırlar

                   o çirkefliklerine

varsın büyükleriniz savaşmaya devam etsinler.

siz kardeşce yaşamaya devam edin.

        Lütfen koparmayın çiçekleri 

        serpilip gelişmeye devam etsin

        Üzülüyorum solup gitmelerine 

        varsın çelenkleriniz olmayıversin

       çiçekler özgürlüğün simgesi olsun.

Ne olur güneşi kapamayın bulutlar 

bizi aydınlatmaya devam etsin 

içim kararır,coşkumu yitiririm bozuk havalarda 

olmasın,artık haksız savaşlar 

ölmesin,masum insanlar...! 

        Utanıyorum sizden,utanıyorum

                                           ölüm cellatları....! 

       silelim şu kara bulutları 

       silelim şu nükleer atıkları...

        gülelim artık,gülelim 

                              mutlu geleceğe.', 'Bırakın büyümeyin çocuklar  gülüp,eğlenmeye devam edin  korkuyorum sizide bulaştırırlar                    o çirkefliklerine varsın büyükler...', ARRAY['Türk Edebiyatı','Şiir','Yavuz İren']::text[], 8.5, '{"poet":"Yavuz İren","poet_slug":"yavuz-i-ren","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ozleyis-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuregimin acisi', 'yuregimin-acisi-ahmet-yilmaz-9ev2i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Al beni, yüreğimin acısından al beni

Sevdiklerimi kaybettim birer birer

Kör kör oluyor bu yüreğim

Sıladan kötü haber aldım bugün

Yüreğimin acısından al beni

Al beni, üzüntülü dünyamdan al beni

Dostlarıma, sevdiklerime yetiştir beni

Başlarına oturup da ağıt yakamadığım

Canlarıma, sevdiklerime götür beni

Sevinçli bir akşamın bitiminde

Geç saatlerdeki uğursuz haber

Yüreğime atılan bu kör....

Dağların ötesindeki yarime yetir beni...

Al beni, mutsuz mutluluğumdan al beni

Sevdiklerime götür beni...

Tek tek kötü haber gelmesin artik

Yüregim çok zayif.... gözlerimin yaşlarindan al beni...

kalbimin hıçkırıklarından al beni...', 'Al beni, yüreğimin acısından al beni Sevdiklerimi kaybettim birer birer Kör kör oluyor bu yüreğim Sıladan kötü haber aldım bugün Yüreğimin a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuregimin-acisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Ki Tufandır', 'sanma-ki-tufandir-ali-riza-unal-aoadd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanma ki tufandır şu gördüğün felaketi,

O benim hiç dinmeyen, gözyaşımın seli,

Bir gün koparsa şu Arz-ı Alem kıyameti

Kimsede arama,sensin vebali alâmeti..', 'Sanma ki tufandır şu gördüğün felaketi, O benim hiç dinmeyen, gözyaşımın seli, Bir gün koparsa şu Arz-ı Alem kıyameti Kimsede arama,sensin v...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanma-ki-tufandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupaliyiz', 'avrupaliyiz-ahmet-yilmaz-dhh1h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Avrupalıyız, buralı olduk

Kimimiz bağını, kimimiz bahçesini bıraktı

Kimimiz dağdaki sürüsünü bırakıp da geldi

Buraya geldik Avrupalıyız, buralı olduk

Ha biraz para biriktirip de döneyim

Ha bir traktör parası.. bir çift öküz alayım...

Bir iki sene daha gayret...

Buraya geldik Avrupalıyız, buralı olduk.

Birgün misafir işçi olduk, hoş geldik! 

Bir gün ''pis yabancı'' olduk, ''defolunu'' işittik.

Birgün ''witte illegal'', diğer gün problem olduk

Buraya geldik avrupalıyız, buralı olduk.

Anam yolumu bekler, bende bir özlem, telaş.

Ha bugün ha yarın derken bir de ''pasaport'' aldık.

Biraz garantiye alalım dedik, hadi biraz daha sabret.

Buraya geldik avrupalıyız, buralı olduk.

Bir-iki sene dedik, kimimiz geldi 60''ına

Anamızın gözü yolda, n''apalım biraz daha sabret

Çoluk çocuk büyüdü, torunlara kavuştuk.

Bir traktör parası bir de sahilde bir ev..

Buraya geldik avrupalıyız, buralı olduk.', 'Avrupalıyız, buralı olduk Kimimiz bağını, kimimiz bahçesini bıraktı Kimimiz dağdaki sürüsünü bırakıp da geldi Buraya geldik Avrupalıyız, bur...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/avrupaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-huseyin-cayikli-32py8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dalgalanma bu kadar öksüz kalan ağaç...

dallarını şimdi bükme...

ağır bir kış var önünde...', 'dalgalanma bu kadar öksüz kalan ağaç... dallarını şimdi bükme... ağır bir kış var önünde......', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/agac-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pandomim', 'pandomim-huseyin-cayikli-5fxc9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'hani şimdi sen bırakıp gittin ya beni

üzülmemiş gibiydim,konuştuğumuzda...

aslında ben sana yalan söyledim

benim asıl mesleğim

pandomim...', 'hani şimdi sen bırakıp gittin ya beni üzülmemiş gibiydim,konuştuğumuzda... aslında ben sana yalan söyledim benim asıl mesleğim pandomim......', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/pandomim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olayım', 'olayim-ali-riza-unal-owpsu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dinlemem şikayet, halini arz et, dildar olayım

İstemem bahçende bülbülü, bir  gülzar olayım

Aç sineni cananım, mahremi meşkine, halzar olayım

Her cefan sefadır bana, şevkine hayran, tacizar olayım', 'Dinlemem şikayet, halini arz et, dildar olayım İstemem bahçende bülbülü, bir  gülzar olayım Aç sineni cananım, mahremi meşkine, halzar olayı...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/olayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mahalenin biri', 'mahalenin-biri-ahmet-yilmaz-a55qj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kole John

Herkesin bir rolu vardi mahallemizde

Kole John vardi: cok guzel hizmet eden efendisine

Mubarek gecenin yarisinda karisinin emri üzerine

Hic erinmeden, hic gücenmeden alirdi itini, ver elini disari

Karisi iceri girince el pence gecerdi saygi durusuna

Ve sikiysa eve 3 dakika gec gelsin

Gel de sen gor bu dügünü

Bir de muhtar Rene vardi

Bu da herkesin ne yaptigini, kimin kimle hangi saatte yattigini

Erinmeden not eder rapor halinde beyninde saklardi

Kimin kac misafiri gelir, mahallede kim hasta..

Hepsini cok iyi bilirdi..

Ve birde mahpus Mehmet vardi

Onun da bir ozelligi vardi. Gece gündüz hapisti

Cezasi cünkü müebbetti. Ona disari cikmak omür boyu yasakti

Ne bir geleni vardi ne de sorani, gorüs günlerinde

Disarida hicbir dostu yoktu cünkü.

Tek avuntusu, mutlulugu cok sevdigi iki cicegi idi

Bunlarla mutlu olur, bunlarla güler ve bunlarla gecerdi yasantisi

Aslinda cok mutluydu bu iki cicegiyle

Umrunda degildi hicbir zaman müebbet giydigine

Kendisini öyle alistirmistiki bu hapishaneye, disarisi onun umrunda bile degildi

Ve bir gün yine bir ziyaretci günüydü

Herkesin gozü kapidaydi

Ama bizim mahpus Mehmet ‘in boyle bir sorunu yoktu.

Cunku onu ziyaret edecek hic bir dostu yoktu ki.

Gerci ara sira birkac dost gibi gorunenler ona telefonlar acardi, abur cubur 

Seyler anlatirlardi ve hep kendilerinden bahsederlerdi.

Ama hic bir zaman sormazlardi onun ne halde oldugunu…

Ne sekilde yasadigini..', 'Kole John Herkesin bir rolu vardi mahallemizde Kole John vardi: cok guzel hizmet eden efendisine Mubarek gecenin yarisinda karisinin emri üz...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yilmaz']::text[], 8.5, '{"poet":"Ahmet Yilmaz","poet_slug":"ahmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/mahalenin-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanıyor', 'kaniyor-zafer-zengin-etnika-cfkdc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sürme

yüzünü

ellerime

k a n ı y o r... 

bakışın

aç ellerin ilacı

söyler misin

bu nasıl sancı

yüzüne

takılıyor

ellerim

k a n ı y o r... 

anlatacaklarım

gülümsemene takılıyor

telaşlı adımların

koştukça peşinden

ayaklarım

k a n ı y o r... 

gün batarken

camlara çarpıyor

i ç k a l ı  y o r... 

16.09.2004', 'sürme yüzünü ellerime k a n ı y o r...  bakışın aç ellerin ilacı söyler misin bu nasıl sancı yüzüne takılıyor ellerim k a n ı y o r...  anla...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilekçe', 'dilekce-i-lyas-ozmen-kmx11', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beş nüfus ev kira üç öğrencim var

Gelipte halimi görün müdürüm

Bi zahmet hesabı gözden geçirip

Tez elden paramı verin müdürüm

Bu bir arzuhaldır bu bir dilekçe

Bu nasıl hesapmış sanki bilmece

Tasarruf yapmıştım oldu işkence

Kanayan yaramı sarın müdürüm

Dilekçe yazmaktan usandım bezdim

Evrağı belgeyi sıraya dizdim

Meşgulsünüz diye kısaca yazdım

Acele bir cevap verin müdürüm

(''''İlgili Servisin İlgili Müdürüne'''' diye başlık atmış olduğum 

 şiirimi dikkate alarak bir yılı aşkın süredir düzeltilemeyen 

 hatayı kısa sürede düzeltip tasarruf paramı almamı sağlayan

 sayın ilgili müdüre huzurlarınızda hassasiyetinden ve sanata 

 vermiş olduğu önemden dolayı binlerce kez teşekkür ederim.

 Kendisine kısa süre içinde yazacağım teşekkür şiirimi sizlerle

 çok yakında paylaşacağım.İlginize sunulur.)', 'Beş nüfus ev kira üç öğrencim var Gelipte halimi görün müdürüm Bi zahmet hesabı gözden geçirip Tez elden paramı verin müdürüm Bu bir arzuhal...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dilekce-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veda', 'veda-yavuz-i-ren-doeop', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elveda her şeyiyle benim olupta,                                             

             hiç bir şeyine sahiplenemediğim 

                                         toprağım

sana her zaman ki gibi uzaktan bakacağım 

artık dağlarında kekikler toplayamacağım,derelerinde Alabalık,bağlarında dut''lar yiyemiyeceğim

varsın olsun,ben olmasam da olur....! 

      ne çıkar benim yokluğumdan? 

Dağ -dağ,orman -orman,kıyı -kıyı benim olan 

