INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esin...', 'esin-ahmet-ferit-cosan-4v9do', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çok uğraştım görmeye

kutsal jüpiterin kör sulara düşen yansısını,

bilemedim oysa,

yaşlı tanrının yakamozunun

yüreğimde çoktan

ışıktan çiçekler açtığını...', 'çok uğraştım görmeye kutsal jüpiterin kör sulara düşen yansısını, bilemedim oysa, yaşlı tanrının yakamozunun yüreğimde çoktan ışıktan çiçekl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/esin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşböceği', 'atesbocegi-hulya-koroglu-sns1z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllardır içinde birikenler

Baksana,

Nasıl da çarpıyor duvarlarıma...

Bir fırtına kopsa,

Bir yağmur yağsa mesela

Alıp götürse tüm birikenlerini.

Sonra arıca kalsan bana.

İlk günkü berraklığınla çıksan karşıma,

Tüm yaşama yeniden yaksan ışıklarını.

İçinde; 

Küsmüş duygulardan eser kalmasa...

Sonra da kanatlanıp 

Bir ateşböceği olsan,

Gelip konsan seni bekleyen yollarıma...', 'Yıllardır içinde birikenler Baksana, Nasıl da çarpıyor duvarlarıma... Bir fırtına kopsa, Bir yağmur yağsa mesela Alıp götürse tüm birikenler...', ARRAY['Türk Edebiyatı','Şiir','Hülya Köroğlu']::text[], 8.5, '{"poet":"Hülya Köroğlu","poet_slug":"hulya-koroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/atesbocegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamın Biri*', 'adamin-biri-bir-mim-kemal-ertugrul-mrgza', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben mi 

Kaybetmiştim işimi,

Patron mu beni? 

İşsizdim

Ve beş parasız...

Moralsiz ve halsizdim

Elbet hızır değildi

Yaklaştı adamın biri

Hatırımı sordu 

Ve de halimi

Ve sabırla dinledi 

Hal-i pür melalimi

Teselli verdi

Güç verdi

Ve umut..! 

Sağolsun

Kapısında iş verdi

Çalıştım yıllarca

İşinde köle gibi

Erkek sözü vermişti

Paramı vermedi

Aynı öncekiler gibi..!', 'Ben mi  Kaybetmiştim işimi, Patron mu beni?  İşsizdim Ve beş parasız... Moralsiz ve halsizdim Elbet hızır değildi Yaklaştı adamın biri Hatır...', ARRAY['Türk Edebiyatı','Şiir','Bir Mim Kemal Ertuğrul']::text[], 8.5, '{"poet":"Bir Mim Kemal Ertuğrul","poet_slug":"bir-mim-kemal-ertugrul","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/adamin-biri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elini verir misin?', 'elini-verir-misin-cafer-yurtsever-h0m2w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elini verir misin

elini, ellerini 

başını başıma dayar mısın 

başını, saçlarını; 

kapatır mısın gözlerini 

ve tek söz demeden.

Elini verir misin? 

Bitmesin bu gece, doğmasın güneş,

ellerin hep avucumda kalsın

saçlarını koklamaktan korkuyorum

saçların batıyor omzuma 

elin elimde buz gibi; 

gözlerin kapalı 

seni derin bir uykudan 

uyandırmaktan korkuyorum; 

oysa daha yeni tanıştık 

iki sat olmadı bile; 

ve ağır ağır çıktığımız merdivenleri 

hızla çıkıyoruz ilk kez 

ve geceye küsüyorum

sana küsüyorum ellerin buz gibi; 

düşlerine taşı beni, düşlerinde ol yanımda

yenik düştüğün için utanma 

olaki güneş doğar ve söyleyecek bir çift sözün 

olur ve sen nasıl söyleyeceğini 

bilmezsen, bilesin ki benim de

bir çift sözüm vardır,

nasıl söyleyeceğimi bilemediğim gibi 

ve utanmayacağım.

Dönerdi kazan işçileri ellerinde demir pası 

biz gemilere el sallamaktan yorgun düşerdik

gencecik insanlardı hepsi 

biz o gün de yaşlı ve yorgunduk

ve hiçbir zaman olmadığı gibi

o gün de sevgilimiz yoktu

elinden tutamadık kızların

elinden tutamadık delikanlıların

saçlarını koklamadık, sokulmadık kokularına

dokunmadık tenlerine uzak ve yaşanmamış

sevdaların içinde şair dahi olamadık; 

bir akşamdan diğer akşama 

bir geceden diğer geceye 

böldük sevdaları bizim olmayan

bizim olmayacak sevdaları.

Kapalı gözlerin görebildiği nedir ki? 

Dünyanıza bir kapı açılır; 

kırk anahtar ve bir çığlıkla

ve her kapı yüreğine açılır,

düşündeyim

kraldan daha kral

bedelini ödemeye hazır

bekliyorum, 

az gelir acı çekmek 

zincirlere, rutubetli han

dehlizlerine hapsetsinler 

burdayım, bekliyorum.

Denilmez mi

acılar içindeyim

ve keşke yitip gitmese idi

yollar, gecenin ayazı, merdivenler, 

sigaralar, yüksek topuklar,

üşüyorumlar ve 

ne oldular.

Denilmez mi

yudumladığımız

kendi kanımızdır.

Yarın olmadan

söyler misin

yalnızlığın ne çekilmez 

ve ne ağır geldiğini

düşerken nabzımız 

düşerken içten kalelerimiz.

Kasten vurulmak için 

bağrımı açtım

vuruldukça

açtım

son nefesimde dahi

ellerinden tutmak

varmış.

Bedeller ağır 

bedeller kahredici

bedeller ölümcül

bedeller yürekli

insanlara layık

bir sevda borcum yok

bir de ödenmemiş bedeli.

Elini verir misin,

bir an için

ama bir ömür boyu

şuramda tutmak için; 

gecelere açılan kapılardan

çıkıp gelecek aydınlığa dek

tutacağım ellerini verir misin? 

yalnızlığım, kadınım? 

Ellerini ver,

bir tek söz etmeden

ellerini ver; 

ilk kez kendim için istiyorum

ilk kez kendim için tutacağım

ellerinden

benim olsun ellerin

benim olsun geleceğin

benim olsun mevsimler 

benim olsun

benim olsun

Aralık’95', 'Elini verir misin elini, ellerini  başını başıma dayar mısın  başını, saçlarını;  kapatır mısın gözlerini  ve tek söz demeden. Elini verir m...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yurtsever']::text[], 8.5, '{"poet":"Cafer Yurtsever","poet_slug":"cafer-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/elini-verir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ses yok/ damga /bant /acımak/dilime kan lazım', 'ses-yok-damga-bant-acimak-dilime-kan-lazim-zafer-zengin-etnika-8v0ea', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kör taklidi yapıyorum

Elleri uzatıp ileri

Işık arıyorum

Her yön aynı orada

Tökezlemek değil

Boşluğa el çırpmak

Hava yoksa

Ses de yok

Damga

Yapıyorum  gözlerimi

Bakıyor

Ne görse iyi

Aşk kaçıyor

Bant

Ellerime sardığım

Çektikçe

Tüylerim kopuyor

Sırf acımasın diye derim

Kat kat sarıp

Öyle bırakıyorum

Şimdi acımıyor

Hesap

Yapacağım

Ellerim bağlı

İki elimin sesi yok

Boş ver

Fazla gelmişti

Neyime lazım derken

Hep güldüm kendime

Şimdi

Sabahları kalkıp

Fidayda  dinliyorum

Oh olsun bana

Neden kandım dostlara

Sev sev dediler

İçime açtım yara

- İnecek var  şoför bey

- Karanlıkmış du yolda..Keşke ileride inseydim

Kıskandım

Yaralandım

Acıdım çocuk

Bak dağılmış şaçlarım

-önüne baksana kardeşim

-özür dilerim dalmışım

-her dalan yola böyle çıkarsa..ohooo

-peki..kusura bakma

bu bile olmuyor

şimdi satırlar kesip etlerimle

dolayacağım ellerime

dilime kan lazım

içime can

|||  ne kadar kötü yazarsam o kadar iyi..o kadar kolay bırakırım diyorum..sen ce bir daha sevebilirmiyim..

yemin etmeyeyim diyorum..çok zayıfım aşka ve sevmeye karşı..sürekli yenilgi bel ki..aslında güzel..

sevmesem ölürüm diyorum..sanırım ölüyorum..bahar gelse keşke..ben kış sonbahar hiç sevmedim.. belki de o yüzden üşüdüm..yenildim |||

küsme zamanı geldi artık

şiire güne ve kendime

kolay ölmem

şu bahar erken gelse

ağzım kokuyor

kıskanıyorum

yaralanıyorum

acıyorum

saçlarımda umrumda değil

geceleri hep sana geliyorum

kapında güller

diken sürüyor yüzüme

incinmiyorum

renginden belki de

bakma bana öyle

ben de ölümlüyüm işte

yanağını öpeceğim

sakın ürkme

ürkme

23.09.2004

Yazılanlar Genç ve öyküsü olamayanlar göre değildir..onlar dikkate almasın..önlerine baksınlar

Her şeye rağmen sevmek güzel şey.. lütfen çocukların ulaşamayacağı yerde okuyunuz.. +4 ile –10 arası

Sıcakta saklanırsa gayet uzun süre bozulmadan saklanabilir..

Kendiyle dalga gecemeyen insan bitmiştir.. [ zafer zengin  1967 - !)', 'Kör taklidi yapıyorum Elleri uzatıp ileri Işık arıyorum Her yön aynı orada Tökezlemek değil Boşluğa el çırpmak Hava yoksa Ses de yok Damga Y...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/ses-yok-damga-bant-acimak-dilime-kan-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgili', 'sevgili-sinem-kul-tacg3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O sandal karaya açıkta battı,

Ne sen sağ kaldın içinde, ne de ben

Birer yabancı oldu kurtulanlar

Ne kendini avut artık, ne de beni

Bu akşam, yeniden, adını anmam dediğim sana yazıyorum…! ! ! ! 

Oysa tanıdığım en vefasız sevgilisin

Ama sevgilisin işte

Kimsenin olmadığı kadar sevgili,

Kimsenin olmadığı kadar yakınsın…

Seni düşünmüyorum

Sen hep varsın

Seni koparmak için benden

Yaşamla oyalanıyorum

Beni sensiz bir düşün

İşte öyle bir yaşamla oyalanıyorum

Senin avuçlarındayken 

Değersiz bir kağıt parçası gibi 

Ellerinde buruştuğunu gördüğüm, yaşamımla oyalanıyorum

Müjdeler olsun sana,

Bana yazdığın kader, buna kendinde hak bulduğun kader 

Sonunda beni buldu

Senden başka kim gelse yabancı, derdim 

Yabancıları da sevmeyi öğreniyorum 

Ben senden başka kimleri seveyim

Dedim ya sevgilisin…

İnsan istese biter derler

Demek yeterince istememişim şimdiye kadar

Yine de çok özlüyorum seni

Kötülüklerini de, iyiliklerini de

Bir sandalda iki kişi bütün ve çıplak günleri de

Yine de çok özlüyorum seni 

Yüzüne de ardından da küfretsem de

Oysa dedim ya, tanıdığım en vefasız sevgilisin

Ama sevgilisin işte

Kimsenin olmadığı kadar sevgili,

Kimsenin olmadığı kadar yakınsın…

13 eylül 2004/22:45', 'O sandal karaya açıkta battı, Ne sen sağ kaldın içinde, ne de ben Birer yabancı oldu kurtulanlar Ne kendini avut artık, ne de beni Bu akşam,...', ARRAY['Türk Edebiyatı','Şiir','Sinem Kül']::text[], 8.5, '{"poet":"Sinem Kül","poet_slug":"sinem-kul","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sevgili-59-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
