INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Dünyada Dostu Olmayanın Vay Haline', 'bu-dunyada-dostu-olmayanin-vay-haline-salih-ozalasan-kl6dj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dost ile eyledik bugün sohbet

Ne gam kaldı yüreğimde nede kasvet

Yüreğinin güzelliği verdi bana tarifsiz saadet

Bu dünyada dostu olmayanın vay haline

Nede çokmuş birbirimize edecek sözümüz

Gönlümüz şenlendi, güldü mahzun yüzümüz

Diller söyledi, hasret giderdi iki gözümüz

Bu dünyada dostu olmayanın vay haline

Kâh iki sevgiliydik eyledik lâtife

Söylenenler yürektendi almadık hafife

Gülü sevdik, dikeni battı kanadık

Bu dünyada dostu olmayanın vay haline

Dertlerimiz dağ gibiydi indi tepeye

Yükümüz ağır demedik sorunları attık küfeye

Kimin başı darda olsa hazırdık cefaya

Bu dünyada dostu olmayanın vay haline

Geçmişi irdeledik ne yapmalıyız gelecekte

Ömür kısa her canlı bir gün ölecekse

Ölüm geldiğinde bizi dostlar gömecekse

Bu dünyada dostu olmayanın vay haline

Y tarihi 24-09-04

Salih ÖZALAŞAN', 'Bir dost ile eyledik bugün sohbet Ne gam kaldı yüreğimde nede kasvet Yüreğinin güzelliği verdi bana tarifsiz saadet Bu dünyada dostu olmayan...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bu-dunyada-dostu-olmayanin-vay-haline-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir kez de benim gözlerimle bak', 'bir-kez-de-benim-gozlerimle-bak-salih-ozalasan-xlob2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Senin baktığın yerden baktım bugün

Senin niyetine senin gözlerinle

Boğazıma hıçkırıklar doldu düğüm, düğüm

Karşımda göl benziyordu nazlı bir geline

Erik ağacına yaslandım altında durduğun

Birkaç damla gözyaşı aktı ayak izlerine

Kapadım gözlerimi acılarla burkuldum

Nefesin yüzümde, hayalin sarıldı bedenime

İşte o an can evimden vuruldum

Lânet olsun seni bana yazmayan kaderime

Ben yine sensiz, ben yine çaresiz yoruldum

Ben ne/zaman bakacağım bir daha gözlerine

Ne zaman el ele olacağız durduğum yerde

Bir daha ne zaman eğecek erik dalını

Bir daha ne zaman nasip olacak

Erik ağacından yemek meyve

Doğayı kucaklamak olacak mı nasip? 

İki beden tek yürek

Hayal ağacı tanık olacak mı? 

Tekrar Güneş’in batışını seyredişimize

Yine dolaşacak mıyız göl kıyısında? 

İki gönül dostu el ele göz göze

Benim için hayal bile değildi

Oysa sen çevirdin apansız

Hayal edemediğimi gerçeğe

Bana deme benim gözlerimle bak

Yine sen gel; Akçalar şenlensin

Akçalara yine bak; bu defa

Bir kez de benim gözlerimle

Y tarihi 23-09-04

Salih ÖZALAŞAN', 'Senin baktığın yerden baktım bugün Senin niyetine senin gözlerinle Boğazıma hıçkırıklar doldu düğüm, düğüm Karşımda göl benziyordu nazlı bir...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/bir-kez-de-benim-gozlerimle-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
