INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebeğim', 'kelebegim-oner-ozer-4o1qi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kızıl kanatlı kelebeğim

Hiç büyümeyecek bebeğim

Yüreğin dışarda tutsada

Seni her zaman seveceğim

Birgün yanına geleceğim

Belki derdimi biçeceğim

Ayrılık kader yazıldıysa

Sevdam uğruna öleceğim', 'Kızıl kanatlı kelebeğim Hiç büyümeyecek bebeğim Yüreğin dışarda tutsada Seni her zaman seveceğim Birgün yanına geleceğim Belki derdimi biçec...', ARRAY['Türk Edebiyatı','Şiir','Öner Özer']::text[], 8.5, '{"poet":"Öner Özer","poet_slug":"oner-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kelebegim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Sessizliği', 'olum-sessizligi-zubeyde-yilmaz-j5m69', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ölüm sessizliği yaşanıyor içimde

                           Herşey suskun....

                   Kalp atışlarımda mı matemde ne

                          Hiç bir şey istemiyorum bugün

                   Kahretmişliğime,yalnızlığıma sığınmak

                          Kimseyi görmek istemiyor gözlerim

                   Güzel söz söylemesin hiç biri

                         Kahkalar çınlamasın kulaklarda

                   Neşe  dolmasın insanlar

                         Canımı kaybettim,

                  Bu kanayan gönlümde

                         Ölüm sessizliği var....

       1987........canım arkadaşım hayata veda etti,henüz yaşamadan....', 'Ölüm sessizliği yaşanıyor içimde                            Herşey suskun....                    Kalp atışlarımda mı matemde ne             ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olum-sessizligi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki Bir Düş', 'sanki-bir-dus-guler-ilgaz-llcmp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayallerim var 

Gerçekleşsin istediğim

Beni bana getirecek

Hayallerim var 

Gerçekleşmesinden korktuğum

Beni benden götürecek

Ortasında ben çocuk

Ortasında ben masum

Ortasında ben

Ben gibi

Ortasında ben

Korkularımla, sevgilerimle

Yalnız', 'Hayallerim var  Gerçekleşsin istediğim Beni bana getirecek Hayallerim var  Gerçekleşmesinden korktuğum Beni benden götürecek Ortasında ben ç...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sanki-bir-dus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekim', 'ekim-guler-ilgaz-d8t1m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne zaman bunalsam

Önümü ardımı göremesem

Anlayamasam

Beklentilerimin dışına çıksam

Çeker beni yalnızlığım

İçime

..................

Ne zaman coşsam

Zapta, rapta sığmasam

Deliliğin sınırlarını zorlasam

Ne zaman dalsam

Hülyalara, rüyalara

Gitsem alabildiğince uzaklara

....................

Ne zaman savaşsam

Benle, senle, onla

Sezerim doğasını içimde

Algılayabildiğimce

Düşünebildiğimce

Şükrederim yalnızlığımın içinde

.................................

Şen bir kahkahayı duyabildiği için

Kulaklarıma

Temiz göz yaşlarıma

Başarabildiği için ağlamayı

Direnebildiği için karanlığa karşı

Yüreğime

........................

Koluma, bacağıma, ellerime

Üretime, harekete, dansa, sanata

Yaradılışıma yardımcı oldukları için

Şükrederim

Hatalarıma, günahlarıma, hatıralarıma

Beni yalnızlığıma çeken her şeye

Ne zaman çekilsem içime

Dışımı da, içim gibi bir görebildiğim 

Ana

Sessizce', 'Ne zaman bunalsam Önümü ardımı göremesem Anlayamasam Beklentilerimin dışına çıksam Çeker beni yalnızlığım İçime .................. Ne zaman ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ekim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızda Kalsın', 'aramizda-kalsin-guler-ilgaz-k1kvt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aramızda kalsın

Bu bir sır

Doğduk yeniden biliyor musun? 

Gözlerimizin birleştiği anda

Aramızda kalsın

Bu bir sır

Doğduk yeniden biliyor musun? 

Ten tene dokunduğumuz anda

Aramızda kalsın

Bu bir sır

Doğduk yeniden biliyor musun? 

Evreni titreştiren şarkımızı

Söylerken birlikte

Unutma unutturmayalım

Söylesin herkes kendi şarkısını

Bizimle birlikte

Sır olmaktan çıksın

Yayılsın evrene

Zerre zerre', 'Aramızda kalsın Bu bir sır Doğduk yeniden biliyor musun?  Gözlerimizin birleştiği anda Aramızda kalsın Bu bir sır Doğduk yeniden biliyor mus...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aramizda-kalsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göremezsin', 'goremezsin-mehmet-emin-ozturk-3ksuf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sonbahar rüzgarları esiyor şimdilerde

Ve ben soğukların, 

En sıcaklığını yaşıyorum 

Esen rüzgara rağmen 

Hala sönmemiş alevi ateşliyorum

Söndüremediğim alevi...

Sonbahar yaprakları avuçlarıma düşmekte, 

Az önceki çöpçüler süpürdüler yaprakları, 

Ve umutlarım kaldı ümitsizliğimin eşiğinden,

Bir ay ışığının belirmesiyle birlikte yeniden,

Seni hatırlattı bana,

Unutulmuşluğun sahtekarlığını sunmaktaydım ben

Seni unuttum demelerin sahtekarlığını anlatıyorum 

İnanıyorlar da ama yalan olduğunu bilmiyorlar....

mehtap ve gece birde

Düşünceler ile, sen sanıyor musun

Unutmanın ne denli imkansızlıklar 

İçinde olduğunu bilemezsin 

Çünkü sen benim tarafımdan göremezsin sevmeyi

Ne kadar hayır desende

02:04 suları		15/09/2004', 'Sonbahar rüzgarları esiyor şimdilerde Ve ben soğukların,  En sıcaklığını yaşıyorum  Esen rüzgara rağmen  Hala sönmemiş alevi ateşliyorum Sön...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/goremezsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebabil bir kuştur. Karga Değildir.', 'ebabil-bir-kustur-karga-degildir-erol-dal-sxn8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kargayı boğazlayan adam,

Sana öğretenleri boğazlar mısın hep.

Dağdan kovulan ataların gibi

Kini nefreti saçar mısın hep

Buğday başaklarından çaldığın gibi

İçinde yalan büyütür müsün hep

Sen olsaydın demek ki harpte

Mızrağını saplayan Vahşi’de olurdun.

Sonra pişman olurdun da haliyle

Sattığın ruhundan utanırdın hep.

Kim ne yaparsa kendine yapar 

Sıktığın boğaz da kendine

Akan salyan da kendine.

Bulaşmaz bana kuduz,kunduz

Efsunlu doğdu ruhum; 

Niye, sence…Niye

Ak başım var. 

Kara değil bahtım.

Aşarım denizleri

Bulur seni tahtım.

Bacaklarına iyi bak,

Vurunca fırtına seni,

Düşmesin uçkuruna aklının kesesi.

Değneksiz köy mü burası,

Ömür biçiyorsun kendince.

Madem ölmek bu kadar ince

İnancın nerede öyleyse.

Git be karga katili

Git işine,

Adem benim İçim

de…', 'Kargayı boğazlayan adam, Sana öğretenleri boğazlar mısın hep. Dağdan kovulan ataların gibi Kini nefreti saçar mısın hep Buğday başaklarından...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ebabil-bir-kustur-karga-degildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çalış N''olur', 'calis-n-olur-mustafa-toga-1xlqu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vatan elden gitmeden

Çalış kardeş çalış n’olur.

Soyguncular yer etmeden

Çalış kardeş çalış n’olur.

Kahve köşelerinde gezme

Sakın bu sözüme kızma

Vatan için son bir hızla

Çalış kardeş çalış n’olur.

Yapalım birlikte bir iş

Karıncalar örnek imiş

Teknoloji kenetlenmiş

Çalış kardeş çalış n’olur.

Irz, namusu bilmeyenler

Bu vatana göz dikenler

Çoğalmadan yiyiciler

Çalış kardeş çalış n’olur.

Toga’nın sözünü dinle

Şu toprakta çalış, terle

Devlet millet hep el ele

Çalış kardeş çalış n’olur.

www.togamedya.tr.gg

GÜNÜN SÖZÜ: Unutma ki; şairleri haykırmayan bir millet; sevenleri toprak olmuş öksüz çocuk gibidir. (Mehmet Emin Yurdakul)', 'Vatan elden gitmeden Çalış kardeş çalış n’olur. Soyguncular yer etmeden Çalış kardeş çalış n’olur. Kahve köşelerinde gezme Sakın bu sözüme k...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Toga']::text[], 8.5, '{"poet":"Mustafa Toga","poet_slug":"mustafa-toga","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/calis-n-olur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Çırağı', 'kul-ciragi-metin-dikec-lfgi4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bunca ırmak devrilirken gözlerimin tuzundan

böyle tahriklere kapılmayayım

mushafları geçmeyeyim diye

yahu yüreğim

ey yüreğim

anılar biriktirip eski yüzlerden 

biz değil miydik kanayan çocukluğumuza 

karıncalar basan 

yedi uyur aşkına faşedip  tiranları

değil mi ki  helak olma korkusuyla  her gece 

duayı hısım tutan

git yüreğim

bu kaçıncı patlayışı  dudaklarımızda uçurumların

yorulduk oysa

hem 

küçük düştük ellerimize 

bak

soğuyor çaldığımız ateşler

git

 metin dikeç   Ankara-1994', 'bunca ırmak devrilirken gözlerimin tuzundan böyle tahriklere kapılmayayım mushafları geçmeyeyim diye yahu yüreğim ey yüreğim anılar biriktir...', ARRAY['Türk Edebiyatı','Şiir','Metin Dikeç']::text[], 8.5, '{"poet":"Metin Dikeç","poet_slug":"metin-dikec","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kul-ciragi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevilmeden', 'sevilmeden-baykal-kaanalp-7rn63', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bakınca bahar alınmaz

batınca güneş çalınmaz

basınca yürek dayanmaz

kelimeler oynaşır görünmeden

insancıklar çiftleşir sevilmeden', 'bakınca bahar alınmaz batınca güneş çalınmaz basınca yürek dayanmaz kelimeler oynaşır görünmeden insancıklar çiftleşir sevilmeden...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevilmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bip Sesi', 'bip-sesi-baykal-kaanalp-osvdy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir bip sesi

bir de hoşçakal sesi

en çok kızdıran 

beni

sebepsiz yere

rahatsız edilmek', 'bir bip sesi bir de hoşçakal sesi en çok kızdıran  beni sebepsiz yere rahatsız edilmek...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bip-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse Tutmamalı', 'kimse-tutmamali-baykal-kaanalp-gyydn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kimse tutmamalı

yüreğimi avuçlarında

izin vermemeli

kaçmama

hedeflerimden

kimse tutmamalı

beni her şekilde

başarmanın

başaramamanın

talihsizliğinde

kimse tutmamalı

kaderimi hayalinde

bir parçamı düşünmemeli

etkilenmenin cazibesine

sınırsızca kapılmamalı

kimse tutmamalı

bembeyaz güllerimi

gönüsüz ellerinde

sahip olmanın

sıkıcı,yakıcı boşluğunda', 'kimse tutmamalı yüreğimi avuçlarında izin vermemeli kaçmama hedeflerimden kimse tutmamalı beni her şekilde başarmanın başaramamanın talihsiz...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimse-tutmamali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Sevgimiz', 'elveda-sevgimiz-talip-kaplan-1uc8x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bitti mi artık aşkımız

Son mu buldu bu sevdamız

Kim verecek hakkını

Yaşadığımız o güzel anların

Yalandan ibaret değildi sevgimiz

Böyle basit mi olacaktı hikayemiz

Birbirimize ait değil miydik biz

Neden birdenbire ayrıldık ikimiz

Selam vermiyor

Ne birimiz ne de diğerimiz

Birer yabancıyız artık ikimiz

Elveda yarım kalan sevgimiz

__________________ elveda...

(04 Nisan 1993)', 'Bitti mi artık aşkımız Son mu buldu bu sevdamız Kim verecek hakkını Yaşadığımız o güzel anların Yalandan ibaret değildi sevgimiz Böyle basit...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/elveda-sevgimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlim bilmediğimi sananlar', 'i-lim-bilmedigimi-sananlar-gencay-coskun-vtky1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlim yaratanı anlamaksa

Sonsuza kadar öğrenciyim ben

Her gün yeni bir şeyleri görüp 

Her gün yeniden aşık olurum 

Ona ben.

Gözlerim dolarken 

Gözlerimde Onun izi vardır.

Yazdığım her satırda 

Onun bir sözünün dosdoğru  izi var

İlim benim yüreğimde 

İlim benim beynimdedir 

Tek kılavuzum 

Tek okuduğum 

Biricik Mesaj’ım dır.

İlim Mesaj’ı adam gibi okumaktır. 

Mesaj’ı anlamadan seslendirme yapmak 

Ona hakarettir 

İlim bilmediğimi sananlar 

Yoğun aldanıştadırlar 

Gözleri sadece 

Onlara gösterilen dar pencereyi görüyordur

Sen neyi biliyorsun ve

Ben neyi bilmeden yazmışım 

Kelimelerden deryalarım Ona 

Her satırım ona doğruyken 

Görmezden gelmek niye 

İlim yolunda bir yolcuyum

İçinde geziyorum gariban gariban 

Baş ucundakini okusan 

Ne anlattığını bilerek

Sessizce içine döken garibi anlardın

İki sözü anlamak için 

Temiz bir kalbin olsun yeter....

O yol bizi dosdoğru bulacaktır......

Not: Bilmeden, sevmeden bir şeyi asla yazamam.

Bir günah işledik ve buradayız

Ben gideceğimiz günü iple çekiyorum 

Çünkü oraları özlüyorum 

Buralarda bana göre 

Artık bir şeyler yok......', 'İlim yaratanı anlamaksa Sonsuza kadar öğrenciyim ben Her gün yeni bir şeyleri görüp  Her gün yeniden aşık olurum  Ona ben. Gözlerim dolarken...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ilim-bilmedigimi-sananlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duygusuz Değilim', 'duygusuz-degilim-baykal-kaanalp-ovc5e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'her şeye bir kulpum vardır

hiç eksilmez sözlerim

duygusuz değilim ama

karşımdakine güvenim azdır

zayıf anını gözlerim', 'her şeye bir kulpum vardır hiç eksilmez sözlerim duygusuz değilim ama karşımdakine güvenim azdır zayıf anını gözlerim...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/duygusuz-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüne Severken Vurup da Gittin', 'olumune-severken-vurup-da-gittin-nesrin-gocmen-xx99o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sana ne dedim, ne söyledim ki? 

Mermiyi namluya sürüp gelmissin...

Duydugun ne ise ve diyen kim ki? 

Her sözü kötüye yorup gelmişsin...

.

Tek sevdigim sensin, seni üzemem; 

Sevda süzgecinde hüzün süzemem; 

Ben sensiz olamam, sensiz gezemem; 

Aşkını, dert ile karıp gelmişsin...

.

Oyunu yapanlar fendi de bilir,

Suyu bağlayanlar bendi de bilir,

Sevdayı çekenler, andı da  bilir,

Belli ki, bir yüreği kırıp gelmişsin...

.

Bu sitem benimle ilgili değil,

Yazdığın benimle olgulu degil,

Her siir yazdığın bilgili değil,

Ölürce severken, vurup gitmişsin... 

23/09/2004', 'Ben sana ne dedim, ne söyledim ki?  Mermiyi namluya sürüp gelmissin... Duydugun ne ise ve diyen kim ki?  Her sözü kötüye yorup gelmişsin... ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olumune-severken-vurup-da-gittin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göbeği açık bir masaldı', 'gobegi-acik-bir-masaldi-gencay-coskun-w1kmx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göbeği açık bir masaldı 

Rüzgar aldıkça 

Ben üşürdüm 

Ne tuhaftı 

Hayat üzerindeki 

Mutlak egemenliklerimiz 

Bir saman alevi gibi 

Eser geçerdi 

Elimizde 

Tap taze yeni oldum 

Külleri kalırdı

Birde çekip çıktığın 

Kapının tokmağı

Ben söylemiştim 

Dedirten çıldırmalık 

Uyarılar hiç uyarmazdı

Gönülden uyarılmak istenenleri 

Herkes kendi uyanını arardı 

Seçeneklerde aksine gibi 

Çok fazla değildi 

Göbeği açık bir masaldı

Esmerlikler yanıltırdı 

Öpesin gelirdi 

Başka gözlerinde görmemesi gerekirdi 

Betin benzin atardı

Gözler sözlere değince 

Kıyamet kopardı

İster istemez için hep acırdı 

Başka içlerde barınmak istemezdim

Neyim varsa alır giderdim

Her gidişim 

Asla dönüşü olmazdı 

Her gidiş 

Bir yerlerden 

Tanıdık gibi gelirdi', 'Göbeği açık bir masaldı  Rüzgar aldıkça  Ben üşürdüm  Ne tuhaftı  Hayat üzerindeki  Mutlak egemenliklerimiz  Bir saman alevi gibi  Eser geçe...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gobegi-acik-bir-masaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Seni Yaşa,', 'sen-seni-yasa-hikmet-feridun-demir-9c89j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen seni yaşa, 

Ben, beni yaşiyorum kendimde,

Benim seni yaşamam ne kazandırır sana.

Cehenneti kazanacağını sanıyorsan,

İyi düşün avucunu yalamayasın sonunda….', 'Sen seni yaşa,  Ben, beni yaşiyorum kendimde, Benim seni yaşamam ne kazandırır sana. Cehenneti kazanacağını sanıyorsan, İyi düşün avucunu ya...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sen-seni-yasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gör Güllerini Gözlerinde', 'gor-gullerini-gozlerinde-i-smail-sahin-xvrcf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güzellik gülde,

gül bahçede bulunur,

bahçe insan yüreğinde.

yüreğin bilmeyen kişi; 

aldanıp dikenlere tutunur.

kanar dururken şaşkın eli

çamurlar içinde, 

bahçe diye boğulur.

sen unutma yavrum seni; 

gör güllerini gözlerinde,

önünde elbet birgün

kurulur...

sofralar kurulur.', 'güzellik gülde, gül bahçede bulunur, bahçe insan yüreğinde. yüreğin bilmeyen kişi;  aldanıp dikenlere tutunur. kanar dururken şaşkın eli çam...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gor-gullerini-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Tuğ', 'al-tug-ahmet-hakan-yilmazturk-k70nj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kara çocuk, 

çikolata tadında

kuzgun saçlarında 

deniz kokusu

göz alan dişler, 

gülmeye hesaplı

yumurta akı gözler

bebekler kömürden leke 

ben çocuk, sen çocuk

her yaz tatile soyunduk

oyunlar, sohbetler

balık tutmalar,flörtler

kaymaklı kadayıf

dedikodular…

seneler sonra gördüm

ikiz çikolata babası olmuş

çok zaman sonra duydum

bir kaza fark etmiş gölgesini

bitter çikolata erimiş

akmış gitmiş işte

tamam, bitiriyorum şiiri

gözüme bir şey kaçtı

25.09.2004', 'kara çocuk,  çikolata tadında kuzgun saçlarında  deniz kokusu göz alan dişler,  gülmeye hesaplı yumurta akı gözler bebekler kömürden leke  b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/al-tug-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Flaş Flaş', 'flas-flas-guler-ilgaz-rqyud', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sorular sorayım dedim

Kendi kendime

Kim güler gerçekten

Sevinçle güldüren mi

Kim tanır gerçekten

Kendine korkmadan aynada bakabilen mi

Kim yapar gerçekten

Yapmacıktan uzak

Deneyebilen mi

Yaparmış gibilerden

Kim savaşır gerçekten

Ekmekle

Kim barışır gerçekten

Kendiyle

Flaş flaş patladı

Birbiri ardına

Sorularıma cevap

Bakarken gördüklerim

Kim yaşadı gerçekten

Kimin umurunda

Kimsenin

Ama umurumda benim

Ki

Sorular sorayım dedim işte

Kendi kendime

Kim yaşar gerçekten

Sevinçle güldürebilen mi

Sevinçle gülebilen mi

Flaş flaş patlayan

Bir biri ardına anların içinden

Yaşama hala gülerek bakabilen mi', 'Sorular sorayım dedim Kendi kendime Kim güler gerçekten Sevinçle güldüren mi Kim tanır gerçekten Kendine korkmadan aynada bakabilen mi Kim y...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/flas-flas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsin', 'sahipsin-akin-akca-s65gp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '~~~~~~ Her şeye sahipsin, 

~~~ Artık bulamıyorsan, yitirdiğini: 

~ Kaybolduğunda, 

Birini gerçekten sevdiğinde - 

Kaybetmediğinde! 

* 

Birini gerçekten sevdiğinde - 

(İyiden iyiye sarılırsın) 

(Ve sen)   Eller, (ülser)   üstünde 

- Alırsın onu yanı başına: 

Ve başlar ütülenmesi duyguların; 

Sonra, daha fazla örselenmeye, 

Hissedilen, dem vurur - 

Belirir, belli belirsiz, orda durur 

Belki sinsice: 

Ve her şeye sahipsin, 

Yitirdiğini kaybettiğince. 

Yine de en ince işçiliğidir - 

Örselemesidir 

- Nalbantın 

(Sonradan gelen) 

: Zerafetle, işlenmiş kadife, 

Becerikli ellerden çıkma heykeller üzerine: 

[ Heykeltraşın heykeli - 

traşı, kes (!) 

- Onu oyduğu onun çekici 

Ve dağcının çekici de … 

Ama bırakmaz o(nlar) , 

Yarışı.] 

[Yükselirken burçlar, surlar üzerinde; 

Tapınaklar, devasa kubbeler(dirler) 

Ama zaten işlenen, 

Yine & yine 

Gereksiz örselenince; 

Derin kısmına okyanusun, 

Düşer. ] 

[ At & at: 

Kısrakların engin çayır koşusu; 

(Yaylalar kaldırsa da, 

Dağın eteklerinden doğru dağı … 

: At ve at, işte! 

Düş çıkarma seansları 

Kaldıran topuzlar gökyüzüne, inmek yerine yeraltına; 

Yeleler, dalgalanan, gri kuyuların dibinden) 

İnsana tat verir, tat! 

Neden böyle diyorum? 

Etraf-dönen-lekeleri ile gelen kutsal-baş dönmeleri! 

: Neden ki? 

Ama hissizlik; 

Sen olmasan, 

Belki hoş olabilirdi. 

(Cinsi geçkin-sıcak peçeli rüzgar, 

Tüketen acılarsa da yine aynı tür rüzgarı: 

Acı, ölümdür...

Sevene, 

Koşulsuz, 

Dürüst 

Ve tam 

“İdare”si ne ola? 

“Öyle böyle” olur mu? 

Aşk mı, bu; sevgiden aşağı? 

Yok, yok değil!) 

(Samson tapınaklar taşıyan,

Atlas’ın gözünde -

Ki taşır:

Notre Dame en aşağı inmiş; 

Üzerinde hepsinin,

Bakıyor çatıdan Esmeralda''ya.

Tay, hörgüç koşturan; 

Bu, Quasimodo -

Notre Dame De Paği!)

...

(Başlangıçta ve her zaman - 

Sonsuzca 

- örselenince, gereksiz 

Sahipsin sahip olduğuna 

Ve her şeye sahipsin; 

Elde tuttuğunca, yitirdiğini - 

Bırakmadıkça …) 

* 

(Cin ali, yürüdü pıt pıt; 

Onun aklı biraz kıt, 

Yürüdü ve şekillendi tanrı Set: 

Set çeken bir başkası daha vardı!) 

Geri geleceğini, önemlisi, 

Bilirsin; mekanizma icra - 

Koşmasa da, sezersin: 

Yükseğe, 

Derine de düşsen; 

Sevgiyi kaldırdığında, 

~ - Yitirdiğini kaybettiğinde: 

~~~ Her zaman için 

~~~~~~ Ve her şeye sahipsin. 

- 

Türettiğim kelime öbekleri: 

Etraf-dönen-lekeleri ile gelen kutsal-baş dönmeleri! 

Cinsi geçkin-sıcak peçeli rüzgar 

Düş çıkarma seansları 

- 

Set: yilan tanri, kotuluklerin tanrisi, buyuculerin tanrisi, babadir yani. hyboria caginin en eski tanrisi. kral kull zamaninda bile vardi hesap edin. 

eski bir misir tanrisi. osiris isis ve nephthys kardesleri olur felan.... (www.eksisozluk.com)', '~~~~~~ Her şeye sahipsin,  ~~~ Artık bulamıyorsan, yitirdiğini:  ~ Kaybolduğunda,  Birini gerçekten sevdiğinde -  Kaybetmediğinde!  *  Birin...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/sahipsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün', 'gun-akin-akca-s2vn6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Öldüğün gün 

benden düşmeyeceğini gördüğüm …

Bunu görmüştüm; 

bu kördüğüm sayıklamaları.. 

.. baharın güz yapraklarıydı, 

çünkü yere düşemedi: 

Düş çıkaran seansları, 

bunun sorumlusuydu.', 'Öldüğün gün  benden düşmeyeceğini gördüğüm … Bunu görmüştüm;  bu kördüğüm sayıklamaları..  .. baharın güz yapraklarıydı,  çünkü yere düşemed...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitsem mi', 'gitsem-mi-zafer-zengin-etnika-7i9wb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'her adım bilinirken

hiç çekinmeden güldüm

iki adım 

sol ayak aksıyor biraz

acelesiz

çelimsiz

romatizmal sancılar içinde

çocuk diyelim olmaz mı

saçları sarı çocuk

taraklı

bağ söken

deri patlatan

futbol oynayan

ağaç tırmanan

koşan

kaçan

romatizmal sancılar içinde

| dişin kırıldı..dolgular.. içimize taşıdıklarımız kadar duramadı yerinde

kendine kursun sıkacağına..dolgu yaptır..nasıl yabancı ağzında nasıl.. senden değil

yaptırınca anlayacaksın..hani tad demiştik..kokunun olmadığı yerde tad da alınmıyor işte

dişte sağlam olmalı.. hem yemekte hem dişte..çok şey var ısırmak için |

çabuk dökülür

oyuncak sanırsın

itersin dilinle

sağa

sola

garip iştir

eğri çıkarlar

gülüşünden kaçarlar

bir taraf sağlam olsa

diğer taraf hasta

erken düşünmek zor gence

her adım bilinirken

merak edilmeden

çocuk büyümesi 

gözlendi saat saat

neden bilmem

neye benzerdi

saçları sarı

| ilkin baba sandılar..aslında çözülse ilah yapacaklar..

her çocuk gibi oda farklı oda ulaşılmaz..oda bir dilim ekmekle doyan |

gözlem sonucu; 

tuhaf biri

eriği tuzla yemesinden belli

sen keser misin

ekşiyi

tuzu yalın tadıyla

haylaz

hiç büyümeyen yanıyla

düşünür

hindiler yetişemez peşinden

borcu sevmeyen

sadece ölüme direnen

yalnız mı

yalnız elbet

bazı paylaşır

bazı sataşır

bazı yakışır

| iyi ki var der karıncalar..kırmadan ceviz yiyen bir tek o

beklentisiz üstelik..amaç amaç değil onun için..ebruli şey hayat

deseni güzel değişken..renkli ışık gibi..bakışı dost..incitince serçe |

al işte

neresinden baksan

sadece insan

öyle büyüsü falan da yok

olsa da inanmaz 

karnı tok

| yenildi şimdi..  içinden çıkarır  acısını..dostta var..ne derler bilir..

ulan mutlu olsan sendendi..acı cekiyorsun bizden mi.. şimdi gelde

anlat saçları sarı çocuğa.. büyümen lazım çocuk.. acı ana gibidir

sarar sarmalar..eklemeler alıntılar yapar..sen olursun yontulunca

ağaç sanma..şiir yazanda yontucudur aslında..bir de demişsin adam güzel yazıyor

biraz böbürlensen ben daha iyi yazarım desen..az hırslansan kendini bir şey sansan ne olur

..anladım.. sus..  saçları sarı çocuk boğulur |

oysa açlık var bir yerlerde

biliyorsan yerini

sakın ola

sakın ola

ona söyleme

çekip gider

dönmez geriye

öylesine çocuk

öylesine deli işte

gitsem mi şimdi

kimsenin bilmediği yere

boyatsam saçları

etsem kahverengi

g i t s e m  m i...

23.09.2004', 'her adım bilinirken hiç çekinmeden güldüm iki adım  sol ayak aksıyor biraz acelesiz çelimsiz romatizmal sancılar içinde çocuk diyelim olmaz ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/gitsem-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut perçini', 'umut-percini-akin-akca-8n48b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '.Tüm Gnomlar ve Elfin, 

Bu dünyada. 

İnsanoğlu içinde 

Uçandaireler’se. 

* 

Özünü terk etmek yerine, 

Onu sahiplenmek 

Başaramayacağın anlamına 

Gelmez asla! 

* 

İkiz kule yıkan 

Ve öldüren çocuk, sahasında sporun: 

Ya da Hintli katletti

soykırım, koca bir meydanda! 

Eski geçmişte, sesi kısılmış ve yanık; 

Derileri kızıl veya... 

* 

Oluştuğunca sinsidir,

Bakmaz kendine: 

Bu anlam eşiği, 

cahildir! 

* 

Bireysel olmak, toplumca, 

Sözü geçemese de sözlükte; 

U.K. anayasası, Kral Arthur gibi; 

Ne tam efsun, ne de gerçek bütünüyle: 

Yazılı metinlere istemli kelepçelenmek; 

Duygunun, beyne esir kalışı. 

Dürüst, kendi içinde; 

Yakaramıyor, safsata.', '.Tüm Gnomlar ve Elfin,  Bu dünyada.  İnsanoğlu içinde  Uçandaireler’se.  *  Özünü terk etmek yerine,  Onu sahiplenmek  Başaramayacağın anlam...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/umut-percini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Saatlerinde - 1', 'terk-saatlerinde-1-kemal-sume-r3ze6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sebebiyetsiz bir izdüşüm,

.........................kalbime...

yargısız bir infaz,

hesapsız gidişler...

Hayatın terk saatinde vuran zil sesi,

her defasında çınlatan,

..........................derinden...

''yok oluş...''

Bak! 

Yüreğimin dibinde,

-ki uzansan tutarsın...

Emir Kemal SÜME / 2004', 'Sebebiyetsiz bir izdüşüm, .........................kalbime... yargısız bir infaz, hesapsız gidişler... Hayatın terk saatinde vuran zil sesi,...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/terk-saatlerinde-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni bekledim', 'seni-bekledim-burhan-kucuk-j1158', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni Bekledim

Cebimde şiir saklardım

Seni bekledim

Gelmedin...

Geceye şiirlerimi saçtım

Kuşlara su verdim

Avuç içlerimden	

Seni bekledim

Şehrin dehlizlerinde

Her yana şiir ektim

Karanlıkta parlayan

Düşlerime daldım

Kuşlara su verdim

Avuç içlerimden	

Seni bekledim

Gelmedin.....

Şiirlerim beni affedin

Burhan KÜÇÜK

Kdz.Ereğli-25.09.2004', 'Seni Bekledim Cebimde şiir saklardım Seni bekledim Gelmedin... Geceye şiirlerimi saçtım Kuşlara su verdim Avuç içlerimden	 Seni bekledim Şeh...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-bekledim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-tevfik-mengulluoglu-y2c3p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman gelir kirpiklerimin 

Ucuna tüner

Bir kapasam gözlerimi

Havada uçusacak tüyleri birer Birer...

Sonbaharda yapraklarini 

Döküyor kalbim

Ayin altinda çiplak kaldi dallarim

Ne bir sari agliyor yesiline

Nede bir yaprak kaygilaniyor

düsmekten korkan! 

Sevda gelir kavuguna 

yaslanir yüregimin,

kaç defa ayaza vurulur düslerim

kaç defa seni düsünürken 

yakalanirim kendime? 

Ask  yesili  özlemektir Sonbaharda 

Binlerce hücrenin yalnizliga karsi

Örgütlenmesidir ask..', 'Zaman gelir kirpiklerimin  Ucuna tüner Bir kapasam gözlerimi Havada uçusacak tüyleri birer Birer... Sonbaharda yapraklarini  Döküyor kalbim ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Mengüllüoğlu']::text[], 8.5, '{"poet":"Tevfik Mengüllüoğlu","poet_slug":"tevfik-mengulluoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eylul-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim seni Anne', 'ozledim-seni-anne-harun-kuscu-eop98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İstemeden de olsa gurbete çıktım

Yaramadı bana özledim seni anne

Hergün itilip-kakılmaktan bıktım

Canıma tak dedi özledim seni anne

Bazen kendimi tutamıyor ağlıyorum gizlice

İliğime kadar donuyor kalıyorum öylece

Konuşmak istiyorum dilime gelmiyor hece

Nutkum tutuldu sanki özledim seni anne

Herkes devrenı kendi için döndürüyor

Duygu sömürüsü yapıp hayatı sürdürüyor

Tehlike çanları sonumu bildiriyor

Bana çok dua et özledim seni anne

Kış gelipte akşam olup güneşleri batınca

Zalim gurbet kendini sessizliğe katınca

Memer gibi yatağa kıvrılıpta yatınca

Gel gör halimi özledim seni anne', 'İstemeden de olsa gurbete çıktım Yaramadı bana özledim seni anne Hergün itilip-kakılmaktan bıktım Canıma tak dedi özledim seni anne Bazen ke...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozledim-seni-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '** Gölündeki Sığınak...', 'golundeki-siginak-abir-zaki-rv5xt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeryüzüyle gökyüzü, arasında bir yerde; 

vadilerden yayılıp, tüm kıyılara serilen,

zümrüt yeşili bir yorganla sarılı turkuazdan, 

bir duman yükseliyor...

tatlı bir meltem, okşuyor şimdi beni; 

anıların dalgasıyla savurup...

... bu toprağın göksel mutluluğunun

özlemini yansıtan, billur sularında yüzdüğüm, 

senin, kıyının çiylenmiş alevlerini, 

düşürürken aklıma...

Çeviren: Kadir Deniz               Eylül24, 2004 14:00

***************************************************************************************

Asylum in Your Lake...

Somewhere between the earth and the sky,

A mist rises off the turquoise

Framed between the emeralds

Weaved by a warm quilt through the valleys

Dwelled among the hills on every side…

Now,

Looking back across the waves of my memories

A gentle breeze caresses me

Recapturing the dewy flames of your shore

Where I swam in your crystal waters

Reflecting the longing of this land’s heavenly bliss…

June 2004', 'yeryüzüyle gökyüzü, arasında bir yerde;  vadilerden yayılıp, tüm kıyılara serilen, zümrüt yeşili bir yorganla sarılı turkuazdan,  bir duman ...', ARRAY['Türk Edebiyatı','Şiir','Abir Zaki']::text[], 8.5, '{"poet":"Abir Zaki","poet_slug":"abir-zaki","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/golundeki-siginak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nem kalacak', 'nem-kalacak-harun-kuscu-cbd92', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aç kaldımda aş mı verdin

Ev yaptımda taşmı verdin

Can istedim başmı verdin

Nem kalacak sende benim

Tüccar oldun sattın beni

Ateş olup yaktın beni

Eski deyip sattın beni

kırılacak nem kaldıki', 'Aç kaldımda aş mı verdin Ev yaptımda taşmı verdin Can istedim başmı verdin Nem kalacak sende benim Tüccar oldun sattın beni Ateş olup yaktın...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nem-kalacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-ali-aldemir-zhu34', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sus.......

Hiç olmazsa bu kerelik

Kapat dudaklarını sımsıkı,

Gücü yetmese de dişlerinin

Sus........

Dudaklarında kalsın o son söz.

Bebek gözlerinde görmüştüm ilk kez

Bu kadar güzel,

Bu kadar sıcak olduğunu gülmenin

Gülümsemenin....

Gitme......

Birşeyler eksilir yokluğunda bil ki,

Bir akşam çöker üzerine

Bir yalnızlığım düşer  duvarlara

Tırnağımla kazıdığım adına

Daha kaç kez yanmalı günlerce,

Ağzımda kaç kez çiğnemeliyim adını? 

Ve kaç kez vurmalı yüzüme

Her girişimde duvarda ki yalnızlık? 

Gitme.......

Katili olmalıyım daha kaç gecenin,

Kendi yüreğini avutamayan adam

Bu kenti ve gecelerini  bilmem ki

Ne kadar avutmalıyım gözlerimde? 

Kaç takvim eskitmeliyim daha yokluğunda? 

Bilmiyorsun aaah bilmiyorsun

Yavan pas tadında bir rüzgar eser ki

Ne mümkün yutmak sevdadan uzak bu kentte.

Haziran aaaah ille de haziran

Yanarken ellerim  binlerce güneş saçlarında

Saçlarını yıkardım haziranda,

Haziran ki resmidir gidişinle yıkılışımın.

Yokluğunda birşeyler eksilir

Gitme......

Gözlerinden uzak

Gözlerinden ayrı mavi

Yalnızlığını bırakan bir tren geçerdi,

Unuttu buraları o da geçmez oldu artık

Işıl ışıl gözleri yeşil

Bir çocuk vardı hani gülerdi boyuna

Bilmiyorsun bıraktı çalmıyor  o da

Yorgun baba yadigârı gramofonu,

Ah bu türküler  onlar,

Onlar da avutmaz oldu yokluğunda

Gitme..........

Birşeyler eksilir gidersen

Kaçak gezdiğimiz bu kentte,

Gölgenin düştüğü şu kaldırım

Yürüdüğün şu yol,bu  iskele

Sonra terinin bulaştığı eski kayık,

Tenine dokunan deniz eksilir

Yarım kalır birşeyler,

Sen gidersen soframdaki ekmeğim,

Ekmekteki tuzum eksilir

Tadım eksilir bil ki

Gitme.......

...Gitme n''olur bırak 

.... Bırak şuracık da kalsın gözlerin.', 'Sus....... Hiç olmazsa bu kerelik Kapat dudaklarını sımsıkı, Gücü yetmese de dişlerinin Sus........ Dudaklarında kalsın o son söz. Bebek göz...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/gitme-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Anneme', 'sadece-anneme-harun-kuscu-zocug', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anne sana bu mektubu 

Bir tarafı örümcek ağı

Sökük bir perde,dökülmeye 

Yüz tutmuş sıva

Dağınık kitaplar arsında yazıyorum

Yani bekar odamdan yazıyorum canım annem

Seninle geçen günlerim 

Gözümün önünden filim şeridi gibi 

Geçmeye başladığında

Gözümden akan yaşlara engel olamıyorum

Ne kutsal şeymişsin be anne

Seni şimdi daha iyi anlıyorum

Seni kırdığım zamanlar aklıma geldiğinde

Kafamı bin kere duvara 

vuruyorum

Yinede kendimi sana karşı 

Suçlu hissediyorum

Üstüm açıldığında örtmeni,

Beni uyur sanıp öpmeni

Okuda adam ol oğlum demeni

Sesini

Nefesini

Yaramazlık yaptığımda 

Beni dövdüğüm günleri bileözledim anne

Yaz oğul yaz yeterki senden

Mektup gelsinde ne yazarsan yaz diyorsun

Neyi yazayım be anne

Soğuk kış geceleri ısınmayan odamda

Titreyerek ders çalıştığımı mı? 

Zamanında verdiğin öğütleri tutmayıp

Şimdi pişman olduğumu mu? 

Bir hayırsıza tutulup 

Gençliğimi heba ettiğimi mi? 

Yolların uzun hasretin 

Dayanılmaz olduğunu mu? 

Bu bayramda elini öpme hazzını

Yaşayamamanın verdği acıyı mı? 

Sen aklıma geldiğin de

Dayanamayıp ağladığımı mı? 

Gurbet akşamlarının bitmediğini mi? 

Sabahların bir türlü olmadığını mı? 

Sana olan özlemimin 

Dinmediğini mi? 

Dost sandıklarım tarafından

Ezilmenin ızdırabını mı? 

Yazayım canım anne

Gurbette günler kurşun gibi gelir

Mutlaka bir şeyimi götürüyor benden

Uzun zamandır uzktayım senden

Yani hayat ışığımdan

Belki bunları yüzüne söyleyemedim

Ama şimdi üstüne bastırarak söylüyorum

Seni Seviyorum anne

Hemde uğruna can verircesine

Belki bana hayırsız evlat diyorsun ama

Çocuklarının içinde seni en çok seven bendim

anne bendim

Kırmıştım,üzmüştüm seni

Seni en çok seven bendim anne

bendim...', 'Anne sana bu mektubu  Bir tarafı örümcek ağı Sökük bir perde,dökülmeye  Yüz tutmuş sıva Dağınık kitaplar arsında yazıyorum Yani bekar odamda...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sadece-anneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Panzehir', 'panzehir-guler-ilgaz-umhtb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşkı merhem gibi

Sardım yaralarımın üstüne

Sevgiyi panzehir gibi

İçtim acılarımın üstüne

Aşkı yelken gibi

Sürdüm azgın rüzgarlara karşı

Şişire şişire

Yaşamak için fırtınaların göbeğinde

Göbek bağıyla

Bir olabilmek için

Sevgiyle', 'Aşkı merhem gibi Sardım yaralarımın üstüne Sevgiyi panzehir gibi İçtim acılarımın üstüne Aşkı yelken gibi Sürdüm azgın rüzgarlara karşı Şişi...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/panzehir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hırka Bir Lokma', 'bir-hirka-bir-lokma-guler-ilgaz-lri9m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolaydı yaşamak eskiden

Bir hırka bir lokma

Kolaydı nefes almak

Temizdi

Su gibi

Açıktı kapılar

Yoktu ki çalınacak

Candan başka ardında

........................

Zordu eskiden hayat

Lokma aslanın ağzında

Hırka ateşten bir gömlek

.........................

Zor aşıldı

Emek emek alındı

İlmek ilmek dokundu ardında

........................

Döndü bir anda

Tersine nedense

Yaşamak kolay oldu

Lüks içinde

Zor oldu nefes almak

Temiz bir su gibi

Kilit üstüne kilitler kondu

Kapılara

Çalınacak candan başka ne varsa

Neden böylesine korktu candan

Kolayı zor

Basiti karmaşıklaştırdı da

Zora koştu

Yaşamını neden

Neyine yetmedi

Bir hırka, bir lokma

Temiz bir su damlası gibi

Nefes almak

Neden?', 'Kolaydı yaşamak eskiden Bir hırka bir lokma Kolaydı nefes almak Temizdi Su gibi Açıktı kapılar Yoktu ki çalınacak Candan başka ardında ........', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-hirka-bir-lokma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanırken Dünya', 'uyanirken-dunya-guler-ilgaz-5ydif', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dünya uyanmakta

Güneş doğmakta

Sabah olmakta

Bu kaçıncı sabah

Kaçıncı güneşin doğması ufukta

Kimler uyumakta

Kimler uyanmakta

Üzerinde dünyanın

Kimler doğmakta

Kimler ölmekte

Kimler hayal kurmakta

Kimler rüya görmekte

Uyanırken dünya

Güneşin ışıklarıyla

Kimler düşünmekte

Uyumla bir yaşamayı

Dünyanın içinde

Kimler

Uyanırken dünya', 'Dünya uyanmakta Güneş doğmakta Sabah olmakta Bu kaçıncı sabah Kaçıncı güneşin doğması ufukta Kimler uyumakta Kimler uyanmakta Üzerinde dünya...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/uyanirken-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utku', 'utku-guler-ilgaz-vt2ff', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Zafer benimdir

Diyenlerle başladı

Kuşatıldığı anda

Çıkış yolunu açanların

Ardından yürüdü

Zafer

Bu yollarda

..........................

Zafer benimdir diyenlerin

Dağları delenlerin

Aşkı ile yol açanların

Ardından yürüdü zafer

Bu yollarda

...........................

Zafer bu kahramanların

İsimli isimsiz

Gün ışığını

Karanlıkların içinden

Görebilen

Sezgileri ve bilgileriyle

Açtığı yolda yürüdü

Zafer

Zafer bu mu diye

Savaş alanındaki

Ölü bedenlerin gözlerine bakarken

Yakalayan cesur yüreklerin

Bilinçleriyle

Açtığı yolda yürüdü zafer

.........................

Zafer

Her gün ışığıyla uyanan

Karnı doyan

Tasasız başını yastığa koyan

Yaşamından ödün vermeyen

Koskoca yüreklere sahip olanların

Ardından yürüdü 

Zafer', 'Zafer benimdir Diyenlerle başladı Kuşatıldığı anda Çıkış yolunu açanların Ardından yürüdü Zafer Bu yollarda .......................... Zafer...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/utku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıçım İki Kanat', 'kicim-i-ki-kanat-guler-ilgaz-m1adu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yanım kaç git diyor

Bir yanım dur gitme

Diyorum durma kaçma

Olmuş kıçım iki kanat

Bir o yanıma

Bir bu yanıma bakıp

Bırak beni

Bir başıma diyorum

Kaçmaya meyilli kıçıma

Zorda kaldığında

Gülerek bağışlayarak

Kolay değil elbet

Bir başına kalabilmek

Baş edebilmek

Baş olduğumu başarabilmek

Kıçımı terk edebilmek

İçime sindirebilmek

Kıçsız bu yaşamda

Var olabilmek', 'Bir yanım kaç git diyor Bir yanım dur gitme Diyorum durma kaçma Olmuş kıçım iki kanat Bir o yanıma Bir bu yanıma bakıp Bırak beni Bir başıma...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kicim-iki-kanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arınırken', 'arinirken-guler-ilgaz-92ve8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göz yaşlarımı 

İçtim bu gece

Göz yaşlarımı

Sevdim bu gece

Ben olduklarını bildim

Kim sevmedi demeden

Göz yaşlarım oldum bu gece

Yükledim içine yorgunluğumu

Yükledim sevgilerimi, umutsuzluğumu

Çığlığımı, isyanımı, haksızlıkları yükledim

Yükledim yargıları

Kendimi yargılamalarımı

Göz yaşlarım oldum bu gece

Akarak göz yaşlarımla

Yıkandım arınarak

.................................

Ağlama, bakma için için akan

İçime göz yaşlarımla

Ağlama sen 

İçin için içime aksa da

Göz yaşlarım

Sen gülen gözlerime bak

Yolumu açıyor

Biliyorum

Yolumu aydınlatıyor

Biliyorum

İçime akan göz yaşlarım

Aydınlatıyor yolumu

Gözlerime bak gör bir tanem

Ne olur ağlama

Gül ne olur

Ağlasan da ağla benim gibi

İçin için

Gözlerime bakarken

Gül ne olur

Ağlama sen bir tanem', 'Göz yaşlarımı  İçtim bu gece Göz yaşlarımı Sevdim bu gece Ben olduklarını bildim Kim sevmedi demeden Göz yaşlarım oldum bu gece Yükledim içi...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/arinirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlediğim', 'ozledigim-guler-ilgaz-4cd4w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutar da özlediğim ellerimi

Söylerse dua gibi

Yazarsam ismini

Kumlara bir gün

..............................

Tutar da özlediğim kulaklarıma

Söylerse dua gibi

Rüzgarlarla ismini

Nefes gibi bir gün

Tutar da özlediğim

Bir gün 

Gün ışığı gibi

Dolarsa gözlerime

Karanlıklar içinde

.............................

İsmini görürsem

Ellerimle yazdığım kumlarda

Kum tanesiyken

Duyarsam sesini

Rüzgarların içinde

Nefes gibi çekerken içime

...........................

Tutar da bir gün özlediğim

Nefes almak isterse bende

Yazmak isterse

Görmek isterse

Özledim derse

Derim özledim ben de

............................

İşte

O anda

Anda var oluruz

İsmimizi birlikte kumlarda

Gördüğümüz anda

Birlikte bir oluruz

Hiç ayrılmamışçasına

Ya bir tutarsa

Bu bir dua...

Gücü sararsa özlediğim

Kim engel olabilir ki

Birbirimizle bir olmamıza', 'Tutar da özlediğim ellerimi Söylerse dua gibi Yazarsam ismini Kumlara bir gün .............................. Tutar da özlediğim kulaklarıma ...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ozledigim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önemli Bir Duyuru da Benden! ...', 'onemli-bir-duyuru-da-benden-naime-erlacin-9lvw7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevgili Dostlarım

Son günlerde Abir Zaki’den bana sürekli olarak kabarık dosyalar gelmesi üzerine O’nu uyararak göndermemesi konusunda ricada bulundum. (Aslında tanımadığım birçok adresten de geliyordu.)  Bilgisayarım her nedense son aylarda “attachment”ları açmıyordu ve bu nedenle gönderilenleri okuyamıyordum.  Dostlarım bu durumu biliyorlar zaten. Abir ise bu tip dosyalar göndermediği ve üstelik benden de ona – başlıklarından benim olmadığı belli olan ve muhtemelen virüslü - dosyalar ulaştığı ve onları hemen sildiği hakkında bir açıklamada bulundu. 

Şunu bilmenizi isterim ki, kızım dahil hiç kimseye, uzun zamandır ek dosya yollamıyorum. Dolayısıyla benden sizlere “attachment”li bir mesaj ulaşırsa eğer, onu derhal silmenizi rica ediyorum. Nevin Kalafatoğlu’nun duyurusunu okuyunca sizlere bu notu yazma gereğini duydum.

Ek olarak, son birkaç gündür Windows güncellemelerini yapıp, Service Pack 2’yi yükledikten hemen sonra Antoloji’de artık puanlama yapamadığımı fark ettim. Puanlama penceresini açmaya çalıştığımda, devamlı “sayfada hata” mesajı ile karşılaşıyorum. Aynı sorun posta kutularında – özellikle gereksiz mesajları silerken - de devam ediyor. Şiirlerini okuyup yorum yazdığım şairlerin puan vermediğimi düşünmelerini istemem çünkü beğendiğim her şiir ve yazıyı puanlama adetim vardır. Bu yüzden, sorunum çözümleninceye kadar dostların beni affetmesini rica ediyorum. 

Ayrıca nasıl çözümleneceği hakkında bir fikri olan varsa, onu da memnuniyetle karşılayacağımı bilmenizi isterim :)) 

Sevgi ve saygılarımla.', 'Sevgili Dostlarım Son günlerde Abir Zaki’den bana sürekli olarak kabarık dosyalar gelmesi üzerine O’nu uyararak göndermemesi konusunda ricad...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/onemli-bir-duyuru-da-benden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tembel Aşığın Mecburi Mesaisi', 'tembel-asigin-mecburi-mesaisi-selim-bayrak-ccz81', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gözleri görmeseydim 

Bu sözleri duymasaydım

Bu gülüşe tapmasaydım 

Bu dönüşe sapmasaydım eğer

Kim bilir durgun bir denizdim şimdi ben

Dalgalar arasında kaybolup gitmeyen

Anlıyor muyum diye sorsana aşkı  bana

Anlamıyorum diye bağlanma bir başkasına

Sevgin güçsüz kıldı beni

Yine diriltti  geçmiş kinimi

Ben eski ben olamam artık 

Duyuşum kuzeyden  esen ilham perisi

Kayboldum vücudunun kıvrımlarında

Gelmedi hislerimin gerisi

Almaya hakkın yoktu onları

Hislerimi önüme seriver

Sevmeye hakkım olamaz cicim seni

Hislerimi ruhuma geri ver

Kanıyor yine duygularım  en derinden

Vazgeçemiyorum uğraşsam da sevginden

Bu gözleri görmeseydim

Bu sözleri duymasaydım

Bu gülüşe tapmasaydım eğer

Bu yüzden can nefesim

Senin için mücadele etmek

Her şeye değer

1996 - Bolu', 'Bu gözleri görmeseydim  Bu sözleri duymasaydım Bu gülüşe tapmasaydım  Bu dönüşe sapmasaydım eğer Kim bilir durgun bir denizdim şimdi ben Dal...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tembel-asigin-mecburi-mesaisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Eniği', 'ask-enigi-naime-erlacin-z3aus', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eylemiyle gezer prangalı yolculuklar

ağır kanamalı kefilliğinde gözyaşının

ruh kan ağlar 

yaşmağı inince göğün kalp varoşlarına

haylaz bir yıldız kayar sonsuzdan

ete gömülür ilk 

canhıraş bir feryat yükselir karantinadan 

kendini yazar aşk bir daha 

gülün cinnetinde 

sil baştan

ipotek bilmez 

haciz tanımaz

yok sayar borcu

celallenir hakimiyetinde temel güdünün 

kabarır tüyleri it misali

şahlanır

tırmalar 

celladı kesilir hüzün sarısı eylülün

:

adı 

aşk eniği

(25 Eylül 2004)', 'eylemiyle gezer prangalı yolculuklar ağır kanamalı kefilliğinde gözyaşının ruh kan ağlar  yaşmağı inince göğün kalp varoşlarına haylaz bir y...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-enigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git', 'git-harun-kuscu-crv6s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Git

Aydınlık dünyamı karatmak isiyorsan 

Git

Beni bırakıp gitmek istiyorsan

Git

Benim gibi seveni bulacağını umuyorsan

Git 

Senden başkasına başkasına Gönül nazarıyla baktıysam

Git

Senden başkasını gönlümde bıraktıysam 

Git

Sen gibi birini sevdiysem 

Git

Senden başka kadın eline değdiysem

Git

Senden başka bir kadına 

Boyun eğdiysem

Git', 'Git Aydınlık dünyamı karatmak isiyorsan  Git Beni bırakıp gitmek istiyorsan Git Benim gibi seveni bulacağını umuyorsan Git  Senden başkasına...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/git-80-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-ali-arslan-t6fpc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Başını dalından sarkıtan bir gül ’den,

damla damla damarlarıma 

kan damlaları yayılır.

Neden üzerime düşüyor bu dağlar?

Dans eden yıldızlar mıdır beni avutan?

Düğüm düğüm eklenerek 

kayalardan yuvarlanan Keşiş, 

Ay ışığında yıkanıp seyreder Çukurova’ya.

Balçık kokusunu sarıp bedenine 

neden sancılı akar bu aylarda? 

Ağlar her gece yanarak geçmişine.

Meşe ağaçlarının Ay’dan yansıyarak 

geceye düşen gölgelerinde.

Şimdi çok uzaklarda,

özlemini içine bir su duruluğunda saklayan 

bir sevgilinin gözyaşlarından düşen hüzünlere 

yanar durur benim yüreğim.', 'Başını dalından sarkıtan bir gül ’den, damla damla damarlarıma  kan damlaları yayılır. Neden üzerime düşüyor bu dağlar? Dans eden yıldızlar ...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozlem-185-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Tutsağım! ...''''', 'ask-a-tutsagim-abdusselam-bugur-6x6ey', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biraz canım yanar. Ölmem, hep sağım.

İçinde yangınlar taşiyan, aşk''a tutsağım.

Ya ateş olup yakacak beni aşkım,

Ya kendime yeniden bir ateş yakacağım...', 'Biraz canım yanar. Ölmem, hep sağım. İçinde yangınlar taşiyan, aşk''a tutsağım. Ya ateş olup yakacak beni aşkım, Ya kendime yeniden bir ateş ...', ARRAY['Türk Edebiyatı','Şiir','Abdüsselam Bügür']::text[], 8.5, '{"poet":"Abdüsselam Bügür","poet_slug":"abdusselam-bugur","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-a-tutsagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pir Sultan''sız / Dar''a Çıkmam Ben...', 'pir-sultan-siz-dar-a-cikmam-ben-i-mdat-ozcan-7ihtj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yusuf '' suz kuyuyu neyleyim ben 

Susamadım ki 

Nasıl yaşanır voltasız mahpus 

Tesbihsiz, çaysız, cigarasız 

Gözdeki fer 

Camda buğu 

Deli dolu hoyratlar yürekte 

Kent yüzlü sohbetler 

Islak düş 

Coşkun deniz 

Dolu dizgin kısrak yaylada 

İnadına sevda gülüm 

İnadına 

Pir Sultan '' sız / dar '' a çıkmam ben 

Soğuk olur urgan 

Çiğ düşmüş sabah gibi 

Erciyes gecesi gibi 

Söyleyin affetsin beni 

Gözleri güzel yar 

Yüreği kadar güzel yar 

Gece ayazlarda kaldım 

Sahipsiz gölgeler peşimde 

Pusatlı 

Uykuda karabasan 

Sarmaş dolaş 

Belde silah 

Bağırda hançer 

Talan olmuş ömür 

Zemheriler kuşanmış beden 

Hüseyin '' siz çöle düşmem ben 

Yanarım 

Anam ağlar sonra 

Islatır gözyaşları yüreğimi 

Kanarım ben 

Kuşatılmış gün 

Tutulmuş güneş 

Bilekte kelepçe 

Gözde bant 

Kör bıçak göğüse değende 

Damla damla kan 

Çatlamış toprak 

Sararmış yaprak 

Kınından sıyrılmış öfke 

Yanmakcasına alevin harında 

İnadına kavga dostum 

...İNADINA...', 'Yusuf '' suz kuyuyu neyleyim ben  Susamadım ki  Nasıl yaşanır voltasız mahpus  Tesbihsiz, çaysız, cigarasız  Gözdeki fer  Camda buğu  Deli do...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/pir-sultan-siz-dar-a-cikmam-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Figan Eyler Şimdi Vuslat''ı Canım', 'figan-eyler-simdi-vuslat-i-canim-murat-nail-guney-cz2ke', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çeşm''i cemaline kurban olduğum,

Yadı-ı gurbetlerde koma bu canı,

Tanrım vermiş bana, günahsa günah,

Ben kurban ederim sana bu canı...

Figan eyler şimdi vuslat-ı canım,

Tarumar eyledi felek vatanım,

Bi-derman aşığım yoktur vatanım,

Devran içre kurulmuş tahtım hani...

Katre katre sızdın mekan-ı can''a,

En acı kelamım '' mes''ut ol'' sana,

Hak makamında kavuşulur ama,

Ruz-u  mahşerde ikrar et hatanı...

Sencileyin bende hamdım piş oldum

Yandı sinem od''a, derde düş oldum

Cümle alem bahar eyyamında hep

Lanetledim ben aşka ihanet katanı...

Muradım maşuka eyleme meyil

Bil ki beş parmağın beşi bir değil

Sevdayı bilenin önünde eğil

Ahu zar''da koyma seveni,tanı....

murat nail güney

regulus', 'Çeşm''i cemaline kurban olduğum, Yadı-ı gurbetlerde koma bu canı, Tanrım vermiş bana, günahsa günah, Ben kurban ederim sana bu canı... Figan ...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/figan-eyler-simdi-vuslat-i-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan dünya', 'yalan-dunya-hicabi-ceylan-wkr5y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yolun sonundayım

Artık veda zamanı

Gidiyorum sessiz ve derinden

Sakın ağlama bir tanem 

Yaş düşmesin yosun gözlerinden

Dünya denen, 

bu köhne limandan

yelkensiz gemi gibi ayrılırken

sadece sevgilerimi bırakıyorum sana

sakın ağlama ciğer parem 

dayanamam 

çiçekler at, mendil salla bana

gece oldu sanki 

hani  yıldızlar nerde? Görmüyorum

ne olur söndürmeyin ışıkları, çok korkuyorum

nerde dostlarım nerde?  nerde sevdiğim nerde? 

nerde canımı verdiğim nerde? 

neden?  Kimseler yok yanımda

sıkı örtün, üstümü üşüyorum

yıldızları yok gökyüzünün

sabah olmuyor

güneş doğmuyor buralarda

dertleşiyorum baş ucumda 

boy veren yüce çınarla

bir gece toplayabilseydim yıldızları

hiç üşenmeden getirirdim sana

düşünki beni hiç görmedin

düşünki ben olmadım hayatında

düşünki bir tanem ben seni hiç sevmedim

tanımıyorsun beni ve ben ölmedim

sakın üzülme sen ciğer parem

yaş düşmesin yosun gözlerinden

çiçekler at, mendil salla bana', 'Yolun sonundayım Artık veda zamanı Gidiyorum sessiz ve derinden Sakın ağlama bir tanem  Yaş düşmesin yosun gözlerinden Dünya denen,  bu köhn...', ARRAY['Türk Edebiyatı','Şiir','Hicabi Ceylan']::text[], 8.5, '{"poet":"Hicabi Ceylan","poet_slug":"hicabi-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/yalan-dunya-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülersin', 'gulersin-zeynep-i-mdat-wt38p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülersin...

Ömrünün ilk çeyrek asrında

Beni tanısaydın,

Daha mutlu olurdun.

Hayır,kendimi övmüyorum.

Sadece sevgiyi

''Benimle öğrenmiş olsaydın,

Daha mutlu olacaktın''diyorum.

O zaman; 

Maviye bakınca,

Benim gördüklerimi görür,

Yalandan sevmeyi değil,

Gerçekten sevmeyi bilirdin.

Doğru kalbe güvenir,

Seni seveniböylesine yalandan sevmezdin.

Seni sevdiğimi söylesemde,

Ömrünün bu yarısından sonra; 

Bana güvenmessin biliyorum.

Öylesine savrulmuşki kalbin

Yalan sevdaların peşinden.

Şimdi desem ki sana:

''MAVİM'' sensin

Bana bakıp sadece gülersin...', 'Gülersin... Ömrünün ilk çeyrek asrında Beni tanısaydın, Daha mutlu olurdun. Hayır,kendimi övmüyorum. Sadece sevgiyi ''Benimle öğrenmiş olsayd...', ARRAY['Türk Edebiyatı','Şiir','Zeynep İmdat']::text[], 8.5, '{"poet":"Zeynep İmdat","poet_slug":"zeynep-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamozlar Ağlıyor', 'yakamozlar-agliyor-murat-nail-guney-abr5g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sine-i bi çareme merhem oldu vuslatın,

Bab-ı gönülde şimdi mehteranlar çalıyor.

Kamerin şavkı süzülmüş engindeki sulara,

Emsal-i bahtım gibi yakamozlar ağlıyor...

Maşukun yaresine deva olur mu meylin,

Divaneye döndü aşkına müptela yüreğim.

Tamuya dileklerim ayan olacak elbet,

Kaf dağı ardına varsam kader seni bağlıyor...

Vakt''erüşüp cümle aşıklar dizilse sıraya,

Senden başkası giremez sinemdeki saraya,

Ağu döktüm yürekte göz-göz olmuş yaraya,

Figanı cananın ey dost, yüreğimi dağlıyor...

Muradım bir çift kelamın mazluma ibret olsun,

Sevgiye ihanet eden şol cennetten kovulsun,

Canın yansa da aldırma dosta can feda olsun,

Sevgi varsa yüreklerde mutluluğa bağlıyor...', 'Sine-i bi çareme merhem oldu vuslatın, Bab-ı gönülde şimdi mehteranlar çalıyor. Kamerin şavkı süzülmüş engindeki sulara, Emsal-i bahtım gibi...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yakamozlar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lirik Kavga', 'lirik-kavga-musa-oz-lpige', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Acıları güle daldırır da söyler

Çoğaltır Akdeniz’i şiirleri

Kederleri sevdayla nakışlar

İteler de dalgaları usulca

Okuya okuya Nazım’dan

Geçer hüzünle Kadınyarı köprüsünden

Hançere karşı

Lirik bir kavgaya tutuşur

Maviyi martı düşürür şiirlerine

Çocukla çocuktur

Metin bir meşedir her çağda

Şapkasında gül ve kenger

Su içer Ege’de Yunanlı çocuklarla

Dal altında,ay ve kuş altında

Gözyaşlarından şiir ayıklar

Lacivert bir şehirdir Antalya

Gülüşüyle Metin’in

Asi ve mavidir ala dağlarla yan yana

Mahmur ya da morca

Çoğaltır Antalya’yı şiirleri', 'Acıları güle daldırır da söyler Çoğaltır Akdeniz’i şiirleri Kederleri sevdayla nakışlar İteler de dalgaları usulca Okuya okuya Nazım’dan Geç...', ARRAY['Türk Edebiyatı','Şiir','Musa Öz']::text[], 8.5, '{"poet":"Musa Öz","poet_slug":"musa-oz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/lirik-kavga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul', 'i-stanbul-mustafa-ozke-kuqi8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sabah ezanıyla başlarsın güne

ardından uyanır serçeler kanaryalar

vapurlara martılar konar

bir bir açılır darabalar

tüter fabrika bacaları

işçisi işsizi köylüsü memuru

zengini fiyatını bilmez ekmeğin

fakiri erkenden yoğurur hamuru

yürümek gibisi yoktur açık havada

sabahın köründe kalk

yürü babam yürü yollar senindir

uyandık siperlere dayandık misali

dayanırsın hayata

güneş hep aynı pencereden vurur

hayat dediğin dostun

mengenesini açmış karşında durur

otobüsler dolmuşlar tramvaylar

yollar tıklık tıklım insan kaynar

uçakların biri gider biri iner

vapurların biri gelir biri döner

her memlekete ayrı tren kalkar

böyle geçip gider günler aylar

İstanbul güzel şehir güzel şehir ama

elini cebine attığın an ayrılıyor yollar', 'sabah ezanıyla başlarsın güne ardından uyanır serçeler kanaryalar vapurlara martılar konar bir bir açılır darabalar tüter fabrika bacaları i...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Özke']::text[], 8.5, '{"poet":"Mustafa Özke","poet_slug":"mustafa-ozke","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/istanbul-1289-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü sevdam', 'olu-sevdam-zeynep-i-mdat-05sva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölü sevdam

Günler geceleri,

Geceler ömrümü kovalarken; 

Ben sevdamı kovaladım hep.

Bazen bir dağın zirvesinde,

Bazen bir göl kenarında,

Bazen de bir şelale 

Oldu sevdam...

Dağın zirvesine çıkan sevdam

Kanadı kırık bir kuş olup,

Düştü ovaya.

Göl kenarına inen sevdam

Boğulan hayallerini,

Gömdü toprağa.

Şelaleyi belkide ilk kez

Bulan sevdam,

Çıldırdı mutluluktan.

Ve.......

Günler geceleri,

Geceler ömrümü kovalarken; 

Sevdam yenik düştü insana.', 'Ölü sevdam Günler geceleri, Geceler ömrümü kovalarken;  Ben sevdamı kovaladım hep. Bazen bir dağın zirvesinde, Bazen bir göl kenarında, Baze...', ARRAY['Türk Edebiyatı','Şiir','Zeynep İmdat']::text[], 8.5, '{"poet":"Zeynep İmdat","poet_slug":"zeynep-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/olu-sevdam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-zeynep-i-mdat-8jrv7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlam

Hayatın bir anlamı olmalı...

Güneşin doğması mı? 

Ayın tutulması mı? 

Yoksa; 

Bulutların yeryüzüne bakarak,

Hıçkıra hıçkıra ağlaması mı? 

Hayatın anlamı bir şeyler de

Saklı olmalı...

Gökyüzünde süzülen,

Beyaz bir martının kanadında mı? 

Doğaya bakınca görülen

Yeşilin tatlı huzurunda mı? 

Yoksa; 

Annesini taze kaybetmiş,

Yavru bir hayvanın

Yüreğimizi sızlatan,

Acı feryatlarında mı? ?', 'Anlam Hayatın bir anlamı olmalı... Güneşin doğması mı?  Ayın tutulması mı?  Yoksa;  Bulutların yeryüzüne bakarak, Hıçkıra hıçkıra ağlaması m...', ARRAY['Türk Edebiyatı','Şiir','Zeynep İmdat']::text[], 8.5, '{"poet":"Zeynep İmdat","poet_slug":"zeynep-i-mdat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anlam-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Mektup 2', 'sana-mektup-2-mehmet-emin-ozyon-t1i0f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eğer, seni sevmek

Senin umursamazlığına katlanmak uluyorsa; 

Sana karşı olan Aşkım,

Burun bükmelerle alay konusu ediliyorsa; 

Seni sevdiğimi her söylediğimde,

Sen kendini ulaşılmaz sanıyorsan,

Böylesine uğruna adanmış bir yüreğe,

Kayıtsız kalabiliyorsan,

Bunca, adına yazılmış ve çizilmişlere,

Reaksiyon gösteremiyorsan,

Sana her dokunmak istediğimde,

Ben bir ucube muamelesi görüyorsam,

Seni bir ilahe gibi görüp,

Sevdana secde ederken,

Bir bir mağbetlerimi yıkıyorsan; 

Tınaz tınaz öbeklenen umutlarımı,

Eylül rüzgarlarında savuruyorsan,

Peki ya..! 

Ben neden sevdim seni..? 

Geçeceğin yolda bekledim,

Diz çöküp önünde sevda dilendim,

Vermedin, biliyorum vermeyeceksin,

Öyle ise o da senin olsun,

Gücenmem sana, gücenecek ne yaptın ki? 

Herşeyi ben yarattım beyhude bir Aşk uğruna,

Senaryolar yazdım yüreğimde hayali,

Gül bahçesi yarattım, çölde susuz,

Gülleri sana verdim,

Dikenleri ben topladım.

Koydum yüreğimin sabır torbasına,

Acısını hissettim damarlarımda.

Sonra gidip sana bıraktığım,

Ve...! 

Senin hiç bakmadığın aynaya baktım.

Seni gördüm göz bebeklerimin derinliklerinde.

Arkanı dönmüş gidiyorsun umarsız.

Seslenmedim arkandan,

Seslenmedim,

Seslenmeyeceğim.

Avazım çıktığı kadar bağırmayacağım.

Seni azat ediyorum.

HADİ GİT...

Git ki yokluğuna alışabileyim.

Kandım varlığına,

Varlığım sandım yüreğimdeki acıyı.

Kızılırmak gibi akıttım seni damarlarımda,

Aşınmaz sandım,

Götüreceklerini bildim,

Karım olur sandım,

Yanıldım.

Son güz yağmurlarını bekledim.

Yağmadı, yağmayacak.

Öyle ise bende ağlamayacağım.

Hazal üstüne yağan yağmurdan ne çıkar,

Beklerim.

Ne kaldı ki şurada Zemheriye,

Bembeyaz kar yağacak,

Kapatacak tüm hazalları,

Donacak kızılırmak,

Uyuyacak toprak.

Kardelenler fışkıracak sonra.

Katırtırnakları nispet edecekler kardelenlere.

Gelincik tarlası olmayacak bu yıl,

Nadasa bıraktım.

Bir hoş seda kalacak senden bana,

Sonra kapatıp gözlerimi,

Seni düşüneceğim.

Ne kadarda gerçeğe benziyorsun.

Açmadan gözlerimi,

Hoşça kal diyeceğim.

Hoşça kal,

Tüm güzellikler senin olsun,

Benim kardelenlerim var.

YA DA OLACAK.

HOŞÇA KAL 

MEHTAPSIZ GECELERİMİN

ŞİMAL YILDIZI.', 'Eğer, seni sevmek Senin umursamazlığına katlanmak uluyorsa;  Sana karşı olan Aşkım, Burun bükmelerle alay konusu ediliyorsa;  Seni sevdiğimi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Özyön']::text[], 8.5, '{"poet":"Mehmet Emin Özyön","poet_slug":"mehmet-emin-ozyon","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/sana-mektup-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Papatyam', 'sari-papatyam-i-brahim-dikmen-2-ky1b2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Merhaba sarı papatyam; 

Seni tanıdığımda henüz 15 yaşında,kıvır kıvır sarı saçlı,cadalozmu cadaloz,

uçarı ve bir okadar da şirin ve güzel bir kızdın sen.Sınıfımıza sonradan başka bir şehirden nakil gelmiştin.Okuldaki bütün erkek öğrencilerin gözü sendeydi,tabiki benimde,diğer kızlar seni öyle kıskanıyorlardı ki sorma gülüm,okadar alımlıydın ki sana bakmamak senden hoşlanmamak imkansızdı.seni okula hergün baban getirip götürüyordu,kırmızı şevrole arabasıyla.Benim babamın arabası yoktu,hiç olmadı da.şehrin biraz dışındaydı evimiz,hergün sabah akşam yürüyordum, üç kilometrelik yolu.küçük eski ve köhneydi ama sıcacıktı evimiz,siz ise şehir merkezinde, apartman dairesinde oturuyordunuz,siz yukarıda biz aşağıdaydık anlıyacağın.

                  Artık okulların kapanmasına az bir zaman kalmış ve bahar turnuvaları düzenlenmişti,futbol takımı olarak finale kalmıştık,ben sınıf takımının kaptanıydım,ogün maçta hayatımın golünü atmıştım rakip kaleye,çünki o gol,bir anlamda hayatın kendisine atılmış bir goldü.maç bitmek üzereydiki harika bir gol atmıştım ve maçı kazanarak şampiyon olmuştuk,yanıma yaklaşıp beni tebrik ettin,ellerinin sıcaklığı,yanağıma kondurduğun öpücüğün ateşini hala hissedebiliyorum gülüm.ogün akşama kadar teneffüslere çıkamadım utancımdan,sanki yanağımın kızarıklığı belli olacak diye.akşam okul çıkışı kapıda bekliyordun beni,biraz konuştuk ayaküstü ve pazar günü tepedeki Recep dayının kır kahvesinde buluşmaya karar verdik.öğleden sonra saat üçbuçukta buluşacaktık,iki gün heyecandan titredim adeta,annem,halime bakıp oğlum neyin var senin böyle deyip durdu,hep geçiştirdim onu.pazar günü erkenden kalkıp banyomu yaptım kolonyalar süründüm,kendime ait parfümüm olmamıştı zaten,yeni elbiselerimi giyip yola çıktım,bir saat öncesinden, elimde bir demet sarı papatya ile oradaydım,karalaştırdığımız gibi tam üçbuçukta gelmiştin,giydiğin bahar desenli elbise sana çok yakışmış ve bütün çekiciliğini,güzelliğini gözler önüne sermişti canım.

                   Merhabalaşarak tokalaşıp öpüştük,ben yine utangaç ve çekingendim.ellerimiz hiç ayrılmadı o gün akşama kadar,gelecekten konuştuk bir müddet,sana verdiğim papatyaları koklayıp durdun, tıpkı sana benziyorlardı o sarı papatyalar.akşam yedi otuzda evde olman gerekiyordu kalktık birsüre sonra yolda elele yürüdük sarıldık birbirimize çocukça bir sevdayla.seni eve bıraktığımda yedi onbeşti saat,buluşmalarımız haftalar,aylarca devam etti aşkımız öyle büyümüştü ki! hiç ayrılmayacağız diye yeminler etmiştik ve hatta ölesiye sevmiştik gülüm.hiç bitmeyecek sandığım bir sevdaya kapılmıştım.aradan iki yıl geçti,yine bir pazartesi sabahı okulun kapısında bekliyordum seni,ama boşuna beklemiştim ogün.sen gelmedin sarı papatyam,yağız delikanlı kapıda öylece kalakaldı.günlerce bekledim seni,belki gelirsin diye okulun kapısında bekler oldum,bekleyişlerim hep boşunaydı,oturduğunuz eve gittim bir umutla,ev bomboştu dünyam başıma yıkıldı oracıkta.sonradan okul idaresinden öğrendim başka bir şehire taşındığınızı,baban ilişkimizi öğrenmiş okuldan almıştı seni ve başka bir şehire seni bulamayacağım bir yere kaçırmıştı benden.günler,haftalar,aylar ve yıllar geçti sensiz ve senden habersiz,birkez bile aramadın,nasıl arayacaktınki gülüm.hayallerimle birlikte sende yok olup gittin hayatımdan,ama ben seni her pazar aynı yerde,aynı saatte,aynı masada beklemeye devam ettim,elimdeki öksüz kırçiçekleriyle.

                    Her yıl olduğu gibi,aynı yerde,aynı masada,aynı saatte ve aynı günde bekliyorum seni.rengarenk çiçeklerin açtığı o eski kır kahvesinde.Çiçeklerin içinde bir sen yoktun papatyam.ne yeminler etmiştik değilmi? ölesiye sevmiştik ve ne hayaller kurmuştuk,bak bana,şimdi bir başıma kalakaldım yıkılan hayallerim ve sigaramla.

                     Pembe panjurlu bir evimiz,bahçesinde kasımpatları,mis kokulu fesleğenler,leylaklar açacaktı ve boy boy çocuklarımız olacaktı koşuşturan.hiç ayrılmayacaktık seninle,bir yastıkta kocayacaktık ömürboyu gülüm.bugün yine aynı yerdeyim,seninle buluştuğumuz o ilkgünki gibi

 heyecanlıyım,elimde bir demet sarı papatya ile.aynı masada,aynı sandalyeye oturdum,ama sen yoktun oturduğun yer boştu,Recep dayı yine seni sordu,hatta önceleri seni kıskanan diğer kırçiçekleri bile sordular,gözlerim boş boş bakındı etrafa boğazım düğümlendi saklayamadım gözyaşlarımı, ilk kez ağladım ardından gülüm.bana hep kızardınya,içme şu zıkkımı diye,senin yokluğunda yalnız o vardı yanımda,beni terk etmeyen, sigaram senden vefalı çıktı bir görsen.hava yine karardı dönüş vaktimiz biliyorsun akşam yedi otuzda seni eve bırakmam lazım,ama sen yoksun ki! 

                    Yine boynu bükük ayrılıyorum,sensiz dünyama karanlık gecelerime,hala inatla tüttürdüğüm ama beni terk etmeyen kadim dostum sigaramla başbaşa kalıyorum.gecenin bir yarısında bir ağaç kuytusunda sızıp kalıyorum bazen,üzerime kırağılar yağıyor pamuk gibi,bembeyaz,senli düşlerimle ısınıyor titrek bedenim.koca gözlü,kulaksız baykuşun sesiyle uyanıyorum,sabahın ilk ışıklarında.şimdi neredesin bilemiyorum,hala onyedi yaşında aklı bir karış havada,uçarı ama adamın aklını başından alacak kadar güzelmisin? sarı saçların kıvır kıvırmı hala? benim sevdiğim kadar sevdilermi seni,taptılarmı aşkına, ellerin oldunmu gülüm! bana verdiğin yeminleri unutup sarıldınmı kollarına.

                Canım,sarı papatyam seni eskisi kadar hatta eskisinden de çok seviyorum,biliyormusun? nereden bileceksinki! senden sonra kimseyi sevemediğimi ve hatta senin üstüne başka çiçek koklamadığımı,kendine dikkat et gülüm,sakın ola ki seni seviyorum diyen herkese inanma,koklatma papatya sarısı saçlarını,beyaz bedenine dokundurma kirli ellerini.mazallah,eski bir paçavraya çevirirler seni, saçlarım kırardı artık lakin hala seni unutmadım canım,asla unutmayacağım.

                  Bir melankoli benimkisi,ancak ölünce biter.', 'Merhaba sarı papatyam;  Seni tanıdığımda henüz 15 yaşında,kıvır kıvır sarı saçlı,cadalozmu cadaloz, uçarı ve bir okadar da şirin ve güzel bi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Dikmen 2']::text[], 8.5, '{"poet":"İbrahim Dikmen 2","poet_slug":"i-brahim-dikmen-2","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sari-papatyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Yüce Sanat', 'ey-yuce-sanat-ali-soyyigit-xqsg1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara gözlerinde kendimi gördüm

Sevgimi harflerle bak işte ördüm

E nginler hedefin olsun her zaman

M aziyi unutma atiye revan

R ızay-ı haktan ayrılma aman

E llerini açmış bak sana baban

M alik-el Mülk-ü hiç unutma oğlum.

B ilgini ilerlet her gün her saat

E riş saadete ey taze hayat

N asıl anlatayım gönlümü sana

İ smin yazılı bak satır başına

M eleğim hayatım ey yüce sanat...', 'Kara gözlerinde kendimi gördüm Sevgimi harflerle bak işte ördüm E nginler hedefin olsun her zaman M aziyi unutma atiye revan R ızay-ı haktan...', ARRAY['Türk Edebiyatı','Şiir','Ali Soyyiğit']::text[], 8.5, '{"poet":"Ali Soyyiğit","poet_slug":"ali-soyyigit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ey-yuce-sanat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyüdükçe eşek olmuştuk', 'buyudukce-esek-olmustuk-gencay-coskun-mc713', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şen şakrak günlerdi 

Güneşli masal gibiydi 

Okul yılları 

Lise sıralarına kazılan 

Sevdalarımız vardı 

Duvarlarda resimlerimiz

Tahtada konuşanlar listesinde adımız hep yazılırdı

Hocalarımızdan bir dünya laf işitirdik

O günlerde bugünün aksine konuşmayı çok severdik 

Keşke bugün olsa da saatlerce azar işitseydik 

Öperdim yanaklarından 

Şaşırdı o zaman hocalarım gelecekteki durumumuzu anlamadan 

Canım ciğerparem hocalarım 

Ekmek derdinde olsalar da 

Gülerdi kalpleri bize 

Kızsalar bile haklarıydı 

Eşekliğin büyüğünü biz yapmıştık 

Bugünlerde o günlerimizi çok aramıştık 

Büyüdükçe eşek olmuştuk

Eşeğin bunda en ufak bir suçu yoktu 

Eşek oldukça semer vuranız da çok olmuştu

Tek korkumuz

Geçer notun altındaki 

Stresli dakikalar gelirdi 

Tenler günahı bilmeden 

Gönülden severdi sevdiklerini 

Paramız gene yoktu ama 

Bu kadar acıtmıyordu 

En büyük günah 

Terli ellerdeki kaçamak kavuşmalardı 

Asırlar geçse bile  söylenme cesaretinden uzak  garip sevdalar

Dolup taşardı okul sıralarından 

Top oynamak 

Akabinde cam kırmak 

Paso kaçmak

Duvardan atlarken yakalanmak 

Mahcup oturmak 

Maceranın önde gideniydi 

Ders saatlerinde 

Göz göze gelmek 

En büyük zinamızdı 

Bir başkası asla olmazdı 

Tebeşirle yazılan kelimelerimiz olurdu 

Okul tahtalarına 

Tahtayı silmek için nöbet tutardık

Bugünse hayat silme işlemini kendi yapardı 

Tam otomatik havarileri vardı 

Alır götürüp gediklere 

Sesini keserlerdi küçük insanların 

Sonra küçük insanlar susardı

Anılar cumhuriyetleri 

Yeni vatandaşlarını alırdı koyununa 

Özlerdim

Gençliğe ilk adım atışlarımızı 

Kollar gezilen harbi arkadaşlıklarımı

Paylaşılan simitler

Sıcaklığından ağzımızı yaktığımız çaylar

Okul gezilerindeki büyülerimiz vardı 

Büyümek hiç istemezdik 

Zaman alırdı koynuna 

Büyütürdü bizi 

Diğerlerine sıra gelsin diye 

Derken sıramız savılırdı 

Bizde savrulurduk

Tüylerimiz kıllara dönerken 

Bir şeylerde dökülürdü

Yılanın deri değiştirmesi gibi 

İklim değiştirirdi içimiz 

Okul kokusunu özlerdim 

Nefes alıp hiç bırakmak istemezdim

Ekmek, para derdinde 

Ezilen bedenlerimizden 

Canlarımız süzülürdü 

Bizden çok uzaklara

Günah, Sevap beton gibi karşımızda 

Sokak aralarında top oynamak 

Artık delilik belirtisi sayılırken 

Sevdalar kabuk değiştirip

Gelecek garantisi yapan 

Bir sigorta şeklinde anlaşılırdı 

Yürek bir daha heyecanla atmayacaktı 

Geçmiş üç otuz paraya satılırdı 

Geçmişin canı çok acırdı 

Aynen bizim içimizin acıdığı gibi 

Gözlerimi kapatıp 

Geçmişi özleyecektim 

Her geçmişini özleyen gibi 

Gün geçmeden bile 

Adamakıllı yaşlanacaktım 

Beyazlar düşecekti 

Hikayeler asla beyaz olmayacaktı

Yalanlar, dolanlar 

Para benden uzak olsun artık

Hayatı yaşamanın bedelini 

Ağır ödesek de

Gelecekte bir gün geçmişimizi bulacaktık.

O gün en değerli günümüz olacaktı.

Ne ihanet

Ne yalnızlık 

Ne karanlık olacaktı

Sevdiklerimin elleri elimde 

Özlediklerim hep yanımda olacaktı.

Kabul etmek lazımdı 

Beklenen süre çok uzundu.

Sıkıldığımız zamanlarda olacaktı.

Ama beklemek yinede güzeldi.', 'Şen şakrak günlerdi  Güneşli masal gibiydi  Okul yılları  Lise sıralarına kazılan  Sevdalarımız vardı  Duvarlarda resimlerimiz Tahtada konuş...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":106,"source_url":"https://www.antoloji.com/buyudukce-esek-olmustuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Köroğlu Hocama', 'koroglu-hocama-i-lyas-ozmen-bsihc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kara çalıların dikeni değil 

''''GÜLLÜK'''' bağ içinde süstür Köroğlu 

Sohbeti çekilir sözünde ehil 

Keyifle dinlenen sestir Köroğlu 

Uzun zaman oldu duyulmaz sesi 

Nedendir bilinmez kaçmış neşesi 

Sormaya gerek yok sözün kısası 

Ya çok korktu yada küstür Köroğlu 

ÖZMENEM biçare bak yine coştu 

Ayranı kabardı dolmadan taştı 

Boş buldu meydanı haddini aştı 

İki kelam eyle sustur Köroğlu 

(Rasim KÖROĞLU Hocama Saygılarımla)', 'Kara çalıların dikeni değil  ''''GÜLLÜK'''' bağ içinde süstür Köroğlu  Sohbeti çekilir sözünde ehil  Keyifle dinlenen sestir Köroğlu  Uzun zaman...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koroglu-hocama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kıyametim', 'kiyametim-sermest-capan-v6kip', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kıyametim kendimedir

sildim çocukluğumdaki çiçekleri

bir rüzgardı öteden esen kasıklarıma

uykudaydım yangındaydım 

kıyametim kendimedir

iki aydır soluksuzum

son güneşe bakalı mihrabım harabım

yalandaydım dolandaydım

kıyametim sanadır

sen ki benim güzbaharım

alabey kanatlarında bir şahinim

yalnızım ayaktayım...', 'kıyametim kendimedir sildim çocukluğumdaki çiçekleri bir rüzgardı öteden esen kasıklarıma uykudaydım yangındaydım  kıyametim kendimedir iki ...', ARRAY['Türk Edebiyatı','Şiir','Sermest Çapan']::text[], 8.5, '{"poet":"Sermest Çapan","poet_slug":"sermest-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiyametim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Mektup 3', 'sana-mektup-3-mehmet-emin-ozyon-m10k6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sana mektup yazmanın,

Bir espirisi kalmadı inan.

Daha başka ne yapmamı istersn bilmem ki? 

Eminim ki..! 

Daha önce yazdığım mektupları okumadın.

Yoksa okudun da umursamadın mı? 

Bir insan sevdasını,

Bir sevdalı yüreğini,

Bir yürek aşkını,

Bir aşık vefasını,

Daha nasıl gösterebilir ki? 

Tutuşu el ele, 

Yürümek isterdim seninle,

Atatürk Bulvarı''nda.

Bakmak isterdim sinema afişlerine,

Birlikte seçeceğimiz bir film''i seyretmek,

Sonra da Mado da dondurma yemek isterdim.

Kırmızı ışıklarda durmak,

Hatta beklemek,

Hiç içimden gelmiyor.

Çılgınca yürümek isterdim seninle,

Ankara sokaklarında.

Bulutlu havalar stres yapıyor insana,

Çok özledim Ankara''nın güneşini.

Seni özlediğim gibi.

Hadi birazda Ecevit misali Türkçe parçalayalım,

''Anlayamadım davransal biçimlerini,

Sosyal biçimlenmen,

Uyumsuzluk gösteriyor,

Konjektürel yapıma.

İletişimsel uydularımızın,

Frekansal bağıntıları,

İşlevlerini kaybettiğinden,

Toplumsal davranışlarımızın,

Bireylere yansımasını engelliyor.''

Nedir seni engelleyen, beni sevmen için? 

Yoksa sen de benim gibi,

Beyhude bir Aşk için mi hayaller kuruyorsun? 

Vefasızlıklar deryasının sığ sularında.

Ne kadar acı değil mi? 

Pembe hayallerin siyaha dönüşmesi,

Ne kadar onursuz değil mi? 

Seni sevmediğini söyleyen birinden,

Sevda dilenmek.

Ne kadar boş değil mi? 

Sahte gülücüklrine kanmak.

Ne kadar anlamsız değil mi? 

Sana sevdalanmak,

Sevdalanıp ta hayaller kurmak.

Senin için bir Dünya kurmuştum hayallerimde,

İsmini bir dante gibi işleyip yüreğime,

Katmer katmer saklamıştım, yüreğimin derinliklerinde.

Görüyorsun ya..! 

Hepsi boş.

Zaman olur bir gün,

Beni anlama erdemliliğini gösterebilirsen,

Bana gelme...! 

Git ve...! 

Aynaya bak.

O sana herşeyi anlatacak,

Suratında oluşan her çizginin arasında.

Benim sana olan sevdamı,

Sevdana olan hasretimi,

Hasretinden nara dönen yüreğimi,

Hatta mektuplarımı göreceksin.

Oku onları,

Sakın ola ki,

Duygulanıp ta ağlama satır aralarında.

Gözyaşlarını dökmeyesin mektuplarımın üzerine,

Onlar,

Benim biricik Aşkım,

Onlar,

Benim san söyleyemediğim,

Senin de anlayamadığın,

Her şey.

HOŞÇA KAL

UMUDUMUN GÜL BAHÇESİ

B', 'Sana mektup yazmanın, Bir espirisi kalmadı inan. Daha başka ne yapmamı istersn bilmem ki?  Eminim ki..!  Daha önce yazdığım mektupları okuma...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Özyön']::text[], 8.5, '{"poet":"Mehmet Emin Özyön","poet_slug":"mehmet-emin-ozyon","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/sana-mektup-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ustalar Kayıp', 'ustalar-kayip-i-lyas-ozmen-r6pi3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman mı değişti devran mı döndü 

Çıraklar meydan da ustalar kayıp 

Bir küçük iğneye balonlar söndü 

Çıraklar meydanda ustalar kayıp 

Nice usta vardı ''''GÜLLÜK'''' bağında 

Kimi dublör tutmuş kimi oyunda 

Dünden fark yok gayrı bugünde 

Çıraklar meydanda ustalar kayıp 

Tatlı dili vardı KÖROĞLU nerde 

Sözleri şifaydı onulmaz derde 

Belki uzaklarda seyr-ü seferde 

Çıraklar meydanda ustalar kayıp 

GÜRKANİ korkudan çeker kasveti 

Çetin ceviz çıktı çünki kısmeti 

Narayla gezerdi çekip kıspeti 

Çıraklar meydanda ustalar kayıp 

CEYLAN mazeretli Konya ilinde 

Bolat Ünsal ise onun yanında 

Sesi aranıyor ''''GÜLLÜK'''' bağında 

Çıraklar meydanda ustalar kayıp 

Kopmuş fırtınadan İNCE''nin dalı 

Hiç sesi çıkmıyor bilinmez halı 

Belki yasaklıdır belki cezalı 

Çıraklar meydanda ustalar kayıp 

ÖZMENEM yaralı dinmez acısı 

Yalan yanlış yazar yoktur hocası 

Şiirle doludur gündüz gecesi 

Çıraklar meydanda ustalar kayıp 

Tüm ''''GÜLLÜK'''' ustalarının ellerinden öpüyor saygılar sunuyorum. 

İlyas Özmen', 'Zaman mı değişti devran mı döndü  Çıraklar meydan da ustalar kayıp  Bir küçük iğneye balonlar söndü  Çıraklar meydanda ustalar kayıp  Nice u...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ustalar-kayip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar Kavuşmalar', 'neye-yarar-kavusmalar-melih-coskun-n36fr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir oyunsa tüm bu bekleyişler

Bu giderek ıssızlaşan karanlık gece

Koynumda giderek ağırlaşan şu soğuk namlu 

Bir oyunsa eğer tüm bu yaşanılanlar

Neden gözlerinde buğulanıp durur zaman

Ve neden dönmemek ihtimalinden bahseder şiirler 

Aramızda onca yol 

Onca dağ ve sonsuz düzlükler 

Aramızda dünyalar var sanki 

Uzaktayım yüreğine yüreğimin elleriyle dokunamayacak kadar 

Ve uzaktasın sana yaktığım türküyü duyamayacak kadar

Bir oyunsa herşey 

Neden bu kadar gücüme gider tüm yapılanlar 

Bu hasretlik neden böyle uzayıp gider

Ve neden her gece biraz daha zor geçer bir öncekinden 

Aldırma sürgün yüreğim 

Hasret olmasa neye yarar kavusmalar...

25 Eylül 2004

Şırnak', 'Bir oyunsa tüm bu bekleyişler Bu giderek ıssızlaşan karanlık gece Koynumda giderek ağırlaşan şu soğuk namlu  Bir oyunsa eğer tüm bu yaşanıla...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/neye-yarar-kavusmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanda Sen Bir Yanda Ölüm', 'bir-yanda-sen-bir-yanda-olum-talip-sinecikli-f24lg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizlik çok sinir bozucu

İnsanın çıldırası geliyor

Hasta yatağımda yatıyorum

Tırnaklarımı yemeye başlıyorum

Bakıyorum ölüm gelmiş

İnat ediyorum gitmemek için

Hiçbir şeyi düşünemiyorum

Birden geliveriyorsun aklıma

Sana yazdığım şiirleri okuyorum

Bağıra bağıra türkümüzü söylüyorum

Ölüm sessizliği bozuluyor

Ve karaltı yavaşça kayboluyor

Acaba diyorum gitsemiydim

Bay ölümü bekletmesemiydim

Bir yanda sen 

Bir yanda ölüm

Ölüm beklerde seni bekletemem gülüm', 'Sessizlik çok sinir bozucu İnsanın çıldırası geliyor Hasta yatağımda yatıyorum Tırnaklarımı yemeye başlıyorum Bakıyorum ölüm gelmiş İnat edi...', ARRAY['Türk Edebiyatı','Şiir','Talip Sinecikli']::text[], 8.5, '{"poet":"Talip Sinecikli","poet_slug":"talip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-yanda-sen-bir-yanda-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevap Ver Babacığım', 'cevap-ver-babacigim-galip-sinecikli-thhef', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ah babacığım, çilekeşim,

Ateş adamım benim,

Bana herşeyi öğrettin,

Hayata dair ne varsa,

Herşeyi senden öğrendim,

Bir şeyi öğretmemişsin ama babam,

Onu hayat öğretti babam,

Hemde yapmamı istemediğinbir şeyi,

Hayat öğretti bana,

Bana bu şeyi öğretmediğin için,

Senden öğrenmediğim içinde,

Hayat beni çok zorluyor baba,

Senin söylediğinin tam tersi,

Hayatın bana öğrettiği,

Oysa bana öğrettiğin herşey doğruydu,

Tersini öğrettiğin birşey hariç,

Bana yapmayacaksın dediğin şeyi,

Hayattan öğrendim baba,

Senide gördüm düngece,

Yapmamı istemediğin şeyi yapıyordun,

Gizli gizli yapıyordun,

Önce şaşırdım, sonra içerledim,

Bana yapma dediğin halde,

Gizli gizli kendin yapıyordun,

Benim bu yaşıma kadar,

Birçok defalar ihityacım olduğunda,

Sözlerini hatırlayıpta yapmadığım,

Sana verdiğim sözü hatırlayıp, 

Yapamadığım şeyi sen yapıyordun,

Elimde olmadan bir iki kez yapmıştım,

O zamanlarda utanmıştım,

Sözlerin gelmişti aklıma,

Kendimi kınamıştım, ayıplamıştım,

Oysa şimdi,

Ne diyeceğim bilemiyorum,

Sıkı sıkı tembihlediğin şeyi,

Sen yapıyordun babam, ateş adamım,

Şimdi bana cevap ver çilekeş babam,

Bana öğrettiğin şey neydi,

Cevap ver babam, babacığım,

Hani Erkekler Ağlamazdı?', 'Ah babacığım, çilekeşim, Ateş adamım benim, Bana herşeyi öğrettin, Hayata dair ne varsa, Herşeyi senden öğrendim, Bir şeyi öğretmemişsin ama...', ARRAY['Türk Edebiyatı','Şiir','Galip Sinecikli']::text[], 8.5, '{"poet":"Galip Sinecikli","poet_slug":"galip-sinecikli","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/cevap-ver-babacigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanki', 'sanki-hifzi-ozbekmez-uctfh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu saçıma düşen aklara bakın

Çektiğim çilenin şahidi sanki 

Elbet başa gelir yazdığı hakkın

Ölümden öteye yol var mı sanki

Nice dertler çektim sayısı fazla

Uğraştım ömrümce tafrayla nazla

Gönlüm talan oldu çarçabuk hızla

Benden beter olan hal var mı sanki

Dertler arkadaşım çile yoldaşım

Ne diniyor acım nede göz yaşım

Kader böyle demek rast gitmez işim

Hani tutunacak dal var mı sanki

Latifin içinde yara sızılar

Boşuna yaşanmış bunca maziler

Gönül arı olmuş güle vızılar

Yaptığı bir gram bal var mı sanki

28  AĞUSTOS 2004 SAAT:06:00', 'Şu saçıma düşen aklara bakın Çektiğim çilenin şahidi sanki  Elbet başa gelir yazdığı hakkın Ölümden öteye yol var mı sanki Nice dertler çekt...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sanki-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirim', 'gelirim-hifzi-ozbekmez-j41k1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GELİRİM

Hasreti bitirmek elimde olsa

Gökteki kuş gibi uçar gelirim

Deli gönül eğer yolunu bulsa

Burayı terk edip kaçar gelirim

Elimi kolumu bağlasalar da

Ciğerimi ister dağlasalar da

Gözlerim durmadan ağlasalar da

Kendime yeni yol açar gelirim

Gözüm görmez bir şey başım dönüyor

Sensiz hayatımın ufku sönüyor

Bedenim çürüyor ruhum ölüyor

Versinler zehiri içer gelirim

Latifim yoluna bu canım feda

Belki kavuşturur acırsa hüda

Azrail gelse de verse de nida

Elimle kefenim biçer gelirim

29  AĞUSTOS 2004 SAAT:08:00', 'GELİRİM Hasreti bitirmek elimde olsa Gökteki kuş gibi uçar gelirim Deli gönül eğer yolunu bulsa Burayı terk edip kaçar gelirim Elimi kolumu ...', ARRAY['Türk Edebiyatı','Şiir','Hıfzı Özbekmez']::text[], 8.5, '{"poet":"Hıfzı Özbekmez","poet_slug":"hifzi-ozbekmez","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelirim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Kaldın', 'gec-kaldin-ali-gencay-7rwwu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Okunmaz

Buruşmuş kağıtlar

Okunmadı yazılanlar

Sevdayı yazdılar

Yol uzun muydu

kaç ışık yılı 

Işığını zamana inat

Semaya düşürdü yıldızlar

Parladılar

Geç kaldın

Mürekkep bulaşığı parmaklar

Divitden damlayan acılar

Kirletiyor geceyi

Yüksek bacalı

Ruhların ezildiği fabrikalar

En güzel kağıda

Yazılıyor

Noktalı,virgüllü imlalılar

Yıldız kayıyor

Zaman yarılıyor

Bir yanımda olanlar

Diğer yanım

Yaşanmayanlar

Geç kaldın

Islak parmak uçlarıyla

Söndürüldü mum ateşi 

Paydos borusu çaldı

Vardiya bitti

Yıkadı ellerini işçiler

Gökyüzü nefeslendi

Mürekkep tükendi

Bitmedi yazılacaklar

Güneş 

Dikti yarılan zamanı 

Sardı hasret her yanı

Yol uzun muydu

kaç ışık yılı 

Işığını zamana inat

Semadan söktü yıldızlar

Şimdi yoklar

Geç kaldın', 'Okunmaz Buruşmuş kağıtlar Okunmadı yazılanlar Sevdayı yazdılar Yol uzun muydu kaç ışık yılı  Işığını zamana inat Semaya düşürdü yıldızlar Pa...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gec-kaldin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Eylül', 'son-eylul-sefa-huyuk-gfgpi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Döndüm işte; 

Emperyalizmin eşiğinde ülkem.

Yaşarsak biz yaşarız acısını

Alırsak biz alırız intikamını

Uzun bir yol birlikte yürürüz belki,

Ama zor bu uyku hiç bölünmez

Kaçamak sevişmeler bitmez eylülde

Vuruşmalar kahpece yapılır

Hep ölsemde bugün diriyim

En canlı halimle....

Gel vur şimdi bana tüm hırsınla

Ama ne olur sol yanıma dokunma

Sana karşı koyamam 

Hep pazarlık aşağılanmışlık

Kaldır başını emekçi kardeşim

Yürü şimdi üstüne

Bakamazlar alın terine

Utanırlar.............

Aç kalırsan bir gün hatırlarsın

Uyanabilirsen bırak o zaman polyannanı

Beni o zaman tanı; 

Bak yollarımız hep aynı..............', 'Döndüm işte;  Emperyalizmin eşiğinde ülkem. Yaşarsak biz yaşarız acısını Alırsak biz alırız intikamını Uzun bir yol birlikte yürürüz belki, ...', ARRAY['Türk Edebiyatı','Şiir','Sefa Hüyük']::text[], 8.5, '{"poet":"Sefa Hüyük","poet_slug":"sefa-huyuk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/son-eylul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekler Açmalı Aşkımın Dallarında', 'cicekler-acmali-askimin-dallarinda-kamil-aydemir-2cjkg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'borçlarının üzerine çizgi çekeceğim

iki kişilik bilet ver bana ey hayat

sevdiğimle sevda turuna çıkacağım

ben bu sevdayı yarınlara ekeceğim

ben sevdanım  koynunda

aşk gülleri açarak eksiltmeliyim bu hayatı

ne zaman sevdanım koynundan akşamlara insem

hasretime çarpan yıldızlar akşamlardan kayıyor

ay bile hasretimde parçalanıyor

d ü n y a    k a n ı y o r

sanki madimak öteli içim

içimde yarınlarım yanıyor

gecelerin yakasında hasretimin izleri kalıyor

gözyaşlarımda acılar yıkanıyor

içime yeşil ırmak akıyor suyu sen

yatağın olayım bende büyü sen

insana barışa aşka

düşman oldukları için sevmiyorum onları

istemem sana çıkmayan yolları

aşkı kanatan sonları

ben düşlerimin koynunda

mutlu yarınlar yeşerterek

yürümeliyim günleri ayları yılları

sabahlara dalınca

sana olan sevgimin ışığında

güneş ışığını yitiriyor

çiçekler çocuklar üzülüyor

üzülüyor sevdalı karınca

eteğinde hüzünler dolu çiçeğim

narın gülüşü dudaklarından öpeceğim

           yüreğine varınca

çekilmez ki hayat kararınca

bir başka sevmek benimkisi

yokluğunda sevinçlerim yırtılıyor

olmayasın diye acının hüznün kollarında

hayatın yollarında

sevgi tarlası yüreğim senin için çırpınıyor

bakışlarında kaç çukurova büyüyor

susuşlarında kaç hüzün uyuyor

yaz bahçesinde kışlar nedendir

sevdiğim dudakların gibi güzel

çiçekler açmalı aşkımın dallarında

ben mavinin saçlarında

beyazın saçağında yaşamalıyım

gönül bahçemden her gün sana gülü vermeliyim

hakkım yok

hasretimi başkalarına bulaştırmaya

yıldızları ayı kırmaya

güneşi kıskandırmaya

asi yüreğimi koydum ortaya

kirletilmişliğin inadına varım

sevdamı ak tutmaya

aşklar çiçek açınca ur kalmaz hayatın karnında

ben akşamında sen olmayan sabahlara küsüm

sabahında sen olmayan akşamlara düşman

aşkımın avuçlarına bırak kendini

hayat sevgisizlikten kanattıkça seni 

olursun pişman

istersen acılarını hüzünlerini taşıyan

    hamal olayım yanında

sen benim ak tutmaya çalıştığım sevdamsın

hayatın kirli sokaklarında', 'borçlarının üzerine çizgi çekeceğim iki kişilik bilet ver bana ey hayat sevdiğimle sevda turuna çıkacağım ben bu sevdayı yarınlara ekeceğim ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/cicekler-acmali-askimin-dallarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybolan Çocukluk', 'kaybolan-cocukluk-sahin-yenilmez-9ieo1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçmişti yıllar hiç kimseye hesap vermeden

Zaten kimsenin hesap soracak hali kalmamıştı

Öyle ki saate bakmak bile sıradandı.

Zamanın geçmesi

Günün bitmesi

Yılların geçmesi...

Hiç birisinin önemi yoktu

Kaybetmişti bütün güzelliğini yıllar önce.

Büyümüştük

Ve çocuk olamazdık artık

Zaman en büyük düşman derlerdi

İnanmazdım daha önce

Alıp götürürmüş içindeki çocuğu

Büyütüp salıverirmiş hayatın eline.

Bitti artık çocuksu gülüşler

Hançerler saplandı bütün düşlere

Ve çocuk olmak yasaktı artık bizlere.', 'Geçmişti yıllar hiç kimseye hesap vermeden Zaten kimsenin hesap soracak hali kalmamıştı Öyle ki saate bakmak bile sıradandı. Zamanın geçmesi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kaybolan-cocukluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittikçe Bana Benziyorsun', 'gittikce-bana-benziyorsun-sahin-yenilmez-41hoj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittikçe bana benziyorsun

Tüm olanlar dışında biraz daha bana yaklaşıyorsun

Öyle ki gözyaşlarını bile artık tutamıyorsun.

Takma hayatı kafana eskiden olduğu gibi

Salıver yüreğini gitsin kendi yoluna

Ve artık hiç bir şeyden korkma.

Yüzeysel olarak bak hayata

Sadece kendi pencerenden değil de

Hissedebildiğin bütün yürekleri topla avucuna

Ve bir ışık gibi doğarak yeniden gel dünyaya.

Gittikçe bana benziyorsun

Ben çoğu zaman buradayım bilirsin

Ya oturup şarkı dinlerim yada

Alırım eski hatıra defterlerini okurum tek tek

Atılan imzalar eskimiş ama

Hiç birisi eski tadı vermiyor.

Sende gidiyorsun

Bende bir gün gideceğim buralardan

Bütün korkularımı bırakıp

Bütün halatlarımı toplayıp

Bu limandan da demir alacağım.

Gittikçe bana benziyorsun 

Ve benimde bir gün yapacağım gibi

Sende gidiyorsun.', 'Gittikçe bana benziyorsun Tüm olanlar dışında biraz daha bana yaklaşıyorsun Öyle ki gözyaşlarını bile artık tutamıyorsun. Takma hayatı kafan...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gittikce-bana-benziyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Nokta', 'uc-nokta-ferit-agca-rsea1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Son kez  vedâ ediyorsun,

Güneşe, Kızıllığa ve aydınlığa.

Bundan sonra herşey gölge,

Ve sen ilk defa,

Gölgenin gölgesi, karanlığın satırbaşı.

Ve yalnızlığın bilinmez noktsındasın,

Soru işaretlerinin içinde kaybolmuşsun.

Titrekte olsa bir sese açsın,

düşüncenin üç noktasında', 'Son kez  vedâ ediyorsun, Güneşe, Kızıllığa ve aydınlığa. Bundan sonra herşey gölge, Ve sen ilk defa, Gölgenin gölgesi, karanlığın satırbaşı....', ARRAY['Türk Edebiyatı','Şiir','Ferit Ağca']::text[], 8.5, '{"poet":"Ferit Ağca","poet_slug":"ferit-agca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uc-nokta-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son karede', 'son-karede-gencay-coskun-t452i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Damlaya damlaya 

Yalan oluyordu 

Kimi zaman duygular 

Bir kapıyı beklerken 

Umutların ve kendine güvenin azalıyordu 

Birisi gidiyordu çaktırmadan 

Zaman gibi 

Bir azılı duygu sömürücüsü 

Alıp değerlini götürüyordu 

Senden uzaklara gizliden 

İşin kötüsü

Sömürücünün suçu yoktu

Değerlin gitmek istiyordu 

Sana kızarak 

Ve çaktırmadan gidiyordu 

Tüm iyi niyetiyle 

İçim acıyordu 

Çaresizlik pınarlarında ıslanıyordum

Düşünceler can yakıyordu soğuk soğuk

Zamanın ters tarafında doğmak 

Kimin suçuydu ki

Acılar, Dertler 

Bardaktan boşanırcasına 

Gelirdi insanın üstüne.

O zamanlarda 

Hiç insan olasın gelmezdi

Ama başa gelen çekilecekti

Yada hayat çekicileri çekecekti canını

Dikenden pamuk ayırmak gibi 

Sancılı olacaktı gömülmelerin akşamı 

Aynı kaldırımlardan

Ardı sıra döndükçe

Asfaltlarda patikalar yapmıştım

Beklemek yıllanmaya dönerdi 

Hain binalar türlü entrikalarla 

Oyun oynarlardı bana ve onların yüzünden

Ay gözükmezdi gökyüzünde 

İçim acırdı

Griye çalardı gece 

Hayat siyah beyaz resim gibiydi 

Artık 

Araba köşeden dönerken 

Hayat karelere ayrılırdı 

Ve ben en son karede 

Bilinmeyen, bildirilmeyen boş elemandım.

Ve filmin ilk sezonu biterdi….', 'Damlaya damlaya  Yalan oluyordu  Kimi zaman duygular  Bir kapıyı beklerken  Umutların ve kendine güvenin azalıyordu  Birisi gidiyordu çaktır...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/son-karede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğretmen Olmak', 'ogretmen-olmak-erdogan-ergin-s43pz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem, herhalde, bin saydığım

Her sabah kalktığımda, 

                                 /göreceğim yüz

Her baktığımda, 

                                 /bana gençlik katan iksir

Ve şükrettiğim,

		/ellerimdeki tebeşir

Alınmazsa elimden eğer bu aşk

Mesleğim öğretmek

Sevdam öğretmenlik

Var oldukça bedenim

		/hep buna muhtaç', 'Bilmem, herhalde, bin saydığım Her sabah kalktığımda,                                   /göreceğim yüz Her baktığımda,                      ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ogretmen-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akasyanın Şarkısı', 'akasyanin-sarkisi-meltem-kaya-gkqx6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlkbahar kokan bir sonbahar sabahına uyandı dalgın gözlerin

Sen sonbaharın sarılığını eskiden hiç bilmezdin...

En güzel çiçeklerini uzatmıştı hep pencerendeki akasya

Ondandır sen yaşamın kupkuru dallarını hiç görmedin...

Baharlar upuzun yollar gibi uzansın ömrüne! 

Deniz kokan bir kıyı kasabasında uyandı yorgun gözlerin

Sen fırtınaların ıslığını eskiden hiç bilmezdin...

Sevda çığlıklarıyla en güzel şarkılarını söylemişti hep göğündeki martılar

Ondandır sen yaşamın azgın dalgalarını hiç tanımadın...

Denizler gökyüzü atlası gibi serilsin ömrüne! 

Itır kokan çocukluk şehrinde uyandı dalgın gözlerin

Sen ayrılıkların rengini eskiden hiç bilmezdin...

Annenin üstüne titremesi gibi taze ekmek kokusu taşımıştı hep sokaklar

Ondandır sen yaşamın ayrık otlarını hiç bilmedin...

Sokaklar bayram sabahları gibi uzansın ömrüne! 

Buğusunda hasret tüten bir İstanbul sabahına uyandı yorgun gözlerin

Sen hasretin kokusunu eskiden hiç bilmezdin...

Yedi tepesinin her birinden aşkı büyütmüştü sana hep İstanbul

Ondandır sen yaşamın İstanbul hasreti olduğunu hiç bilmedin...

İstanbul gökkuşağı gibi serilsin ömrüne! 

Gözyaşında keder yüklü bir yalnızlık sabahına uyandı dalgın gözlerin

Sen gözyaşının tuz tadını eskiden hiç bilmezdin...

Matarasında sevinç taşıyan şarkılar sunmuştu sana hep sevdalar

Ondandır sen yaşamın çıkınında yalnızlık da olduğunu hiç bilmedin...

Sevda çocuk gülüşleri gibi uzansın ömrüne! 

Mendiline kan damlayan bir yolculuk sabahına uyandı yorgun gözlerin

Sen dönüşsüz yolculukların acısını eskiden hiç bilmezdin...

Olanca kızıllığıyla kavuşmakları anlatmıştı sana hep güller

Ondandır sen yolculuğun gül dikenleriyle ellerine batacağını hiç bilmedin...

Güller kokusunu hiç yitirmeden kızıl bir gülüşle serilsin ömrüne! 

Mendilindeki kanı gül diye yüreğine taktığın bir sabaha uyandı sonra gözlerin

Sen yalnızlığa çığlık çığlık şarkı söylendiğini eskiden hiç bilmezdin...

Issız şarkısını bir keman sesinin tınısında söyleyip durdu sana oysa yıllar 

Sen uyandığın tüm bu sabahların yaşamın kendisi olduğunu şimdi öğrendin...

Hanımeli kokarken sabah, deniz dingindi...sen miydin uyanan yoksa sabah mıydı...', 'İlkbahar kokan bir sonbahar sabahına uyandı dalgın gözlerin Sen sonbaharın sarılığını eskiden hiç bilmezdin... En güzel çiçeklerini uzatmışt...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/akasyanin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekmiş', 'gercekmis-yusuf-ter-gfsrs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana senden başka dost yoktur

Soyup sövdükleri gerçekmiş

İnsan oğlu çok nankördür

Soyup sövdükleri gerçekmiş

Şu yıllar mevsimleri boğar

Gökten kara, kara taş yağar

Kararma deli gönlüm ağar

Soyup sövdükleri gerçekmiş

Nice melek  iblis yalana

Hile eder sevmiş olana

Dostlukları daim kılana

Soyup sövdükleri gerçekmiş

Zaman su olmuş da akıyor

Sevdiğim  toprakta yatıyor

Yusuf’um bebeler ağlıyor

Soyup sövdükleri gerçekmiş

Dağlar Şahit Aşkıma adlı kitabımdan bir şiir /2004

http://yusufter.tripod.com', 'Sana senden başka dost yoktur Soyup sövdükleri gerçekmiş İnsan oğlu çok nankördür Soyup sövdükleri gerçekmiş Şu yıllar mevsimleri boğar Gökt...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gercekmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gibi', 'sen-gibi-hasan-can-1ab1w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gündüzler geceyi görmez,

Geceler de gündüzleri.

Sen gündüz kadar körsün,

Ben de gece kadar karanlık.

Gece ay ışığı vurur tenime,

Tüm vücudumu aydınlık sarar

Sen gibi...

Sabah olunca güneş vurur tenime,

İçimi bir alev kaplar 

Yine sen gibi...

Bir nefes kadar yakınım da olduğun gibi,

Bir yıldız kadar da uzağımdasın.

Kimbilir ne zaman bitecek bu işkence,

Ve kimbilir hangi kavşakta son bulacak...', 'Gündüzler geceyi görmez, Geceler de gündüzleri. Sen gündüz kadar körsün, Ben de gece kadar karanlık. Gece ay ışığı vurur tenime, Tüm vücudum...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-gibi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın İçi', 'canimin-i-ci-zubeyde-yilmaz-edo3p', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Canımın içi

Nerdesin...

Korkular mı sardı seni

Neden gittin...

Veda bile etmedin...

Beni gülüşlerimle sensiz,

Yollarda yapayalnız

Nasıl  bırakıp gittin...

Hani aşk yolunda 

Biz yeniden yanmıştık

Gecelere gizlemiştik bizi

Göçler olmayacaktı

Gidişler olmayacaktı

Vedalar olmayacaktı

Usanmalar bizden uzak...

Yeminler askıda şimdi

Dağlar mı geçti önüne

Setmi çekti isyanlar...

Canımın içi

Nerdesin...

Ne çabuk yandık

Ne çabuk küllendik biz

İçimde kor ateşsin hala

Tükenmek istemiyorum sensiz...

Sardı korkular dört bir yanımı

Kalbim serçe çırpınışları...

Haykırışlarım  çığlık çığlığa

Anılarım kırık dökük

Güllerim gönlümde boynu bükük...

Sen...........

Saçıldın her yer darmadağınık....

Canımın içi

Nerdesin...

Yollara yenik düşme

Üşüyorum, üşüyorum gitme...

Çözüldüm korkuyorum

Geç değil,dön artık....

Bende ben erimeden 

Gömülden,su olup gitmeden...

Canımın içi...

Nerdesin, arama kendini

Sen bendesin...

Her ayrılık bir başlangıç

Dön artık...

Senden aldığım ne varsa

Senin söz,güneşimi istiyorum

Hadi dön artık.....', 'Canımın içi Nerdesin... Korkular mı sardı seni Neden gittin... Veda bile etmedin... Beni gülüşlerimle sensiz, Yollarda yapayalnız Nasıl  bır...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/canimin-ici-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sorarım', 'sorarim-gulizar-turgut-0vhnw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sorarım 

Neye yarar

Neye benzer

Sararmış solmuş çiçek

Uçsuz bucaksız toprakta

Kim sever

Kim koparıp evine götürmek ister

Vazosuna koyup koklamak...', 'Sorarım  Neye yarar Neye benzer Sararmış solmuş çiçek Uçsuz bucaksız toprakta Kim sever Kim koparıp evine götürmek ister Vazosuna koyup kokl...', ARRAY['Türk Edebiyatı','Şiir','Gülizar Turgut']::text[], 8.5, '{"poet":"Gülizar Turgut","poet_slug":"gulizar-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sorarim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeliyim', 'gitmeliyim-alev-kutluozen-qqag6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'baharları gelişine sakladım

gülüşünü türkülere yazdım

bağışla 

gitmeliyim…

ölürsem / ağıtlanır dağlar

söz / yetim kalır dudaklarında

son kuşlar da göçmez olur

gitmeliyim…

kanarsa yüreğim

yalnızlığa hesap sorduğum için

hani, yağmur olup dökülmek

vardı ya düşlerine

                 kara yazgım,talihsizliğim…', 'baharları gelişine sakladım gülüşünü türkülere yazdım bağışla  gitmeliyim… ölürsem / ağıtlanır dağlar söz / yetim kalır dudaklarında son kuş...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gitmeliyim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kelebeğin Gözlerinden', 'bir-kelebegin-gozlerinden-alev-kutluozen-0rnc5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağla yurdum…

toprağına yetim düşen

yağmurlara ağla

çünkü her aşk 

kendi tanrısını yaratır

suskunum..

ey sonsuz yolculuğum

rüzgarlar mı geçmişimi ansıtan

solgun baharlar mı

kapımı ansızın çalan

saklan..

yüreğim yanıltmasın seni

bu acılar

ömrüne rehin bir kelebeğin 

gözlerinde  kanar

ağla yurdum

toprağına yetim düşen yağmurlara

uzak dağ köylerinde yaşanan

imlası bozuk  aşklara…

ay ışığından süzülüp

dağlara düşen yüzüm.

ağla.. bu acılar

ömrüne rehin bir kelebeğin 

gözlerinde  kanar…', 'ağla yurdum… toprağına yetim düşen yağmurlara ağla çünkü her aşk  kendi tanrısını yaratır suskunum.. ey sonsuz yolculuğum rüzgarlar mı geçmi...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-kelebegin-gozlerinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Söylerdi Babam', 'hep-soylerdi-babam-alev-kutluozen-qu947', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'babamdı..uzanırdı yüreğime

“kestireyim kızım” derdi

hayat zaten kestirmeydi..

çıkmaz yollarındayım ömrümün

dilimde umudun kekremsi tadı

düşürdüm aşkı ellerimden

suçum özrümden büyük

toplarken oyuncaklarımı

karıştırdım / sevda ile yalnızlıkları

takıldı ayağım suçuma / tökezledim

geceler sığmıyor çocuk düşlerime

intihara duruyor adını bildiğim bütün masallar

rapunzel''de yok artık

                    bunu hep söylerdi babam', 'babamdı..uzanırdı yüreğime “kestireyim kızım” derdi hayat zaten kestirmeydi.. çıkmaz yollarındayım ömrümün dilimde umudun kekremsi tadı düşü...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hep-soylerdi-babam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-alev-kutluozen-aktsg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hangi bahçeyi süsleyen

bordo bir gül(dü) 

kim bilir...

kaç sevdalının yüreğini kanatan

kokusu hala üzerimde

haberin var mı?', 'hangi bahçeyi süsleyen bordo bir gül(dü)  kim bilir... kaç sevdalının yüreğini kanatan kokusu hala üzerimde haberin var mı?...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gul-74-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benden uzakta', 'sen-benden-uzakta-adem-gokmen-hi2pi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yarını tükettik inan bugünden,

Esermi bıraktık sevgilim dünden,

Hani o sevdanın büyüklüğünden,

Geride ne kaldı görüyormusun,

Sen benden uzakta gülüyormusun.

Baharı yaşadık ömürde bir an,

Kış çabuk geldi bak yetmedi zaman,

Maziyi bir düşün durupta inan,

Geride ne kaldı görüyormusun,

Sen benden uzakta gülüyormusun.

Bir hasret rüzgarı üzerimizden,

Estide ayırdı bizleri bizden,

Mutluluk okunan gözlerimizden,

Geride ne kaldı görüyormusun,

Sen benden uzakta gülüyormusun.', 'Yarını tükettik inan bugünden, Esermi bıraktık sevgilim dünden, Hani o sevdanın büyüklüğünden, Geride ne kaldı görüyormusun, Sen benden uzak...', ARRAY['Türk Edebiyatı','Şiir','Adem Gökmen']::text[], 8.5, '{"poet":"Adem Gökmen","poet_slug":"adem-gokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-benden-uzakta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalpsizmisin', 'kalpsizmisin-mehmet-aslan-3vqua', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elimde değil, seni sevmemek,

Elimde değil, kalbimi vermemek,

Elimde değil, sana gelmemek,

Elimde değil, yüzünü görmemek.

Senin elinde, beni sevmek,

Senin elinde, kalbini vermek,

Senin elinde, bana gelmek,

Senin elinde, kalbime girmek.

Benim kalbimde, senin sevgin,

Benim kalbimde, aşk ateşin,

Benim kalbimde, batmayan güneşin,

Benim kalbimde, solmayan çiçeğin.

Umurunda değil, benim sevgim,

Umurunda değil, aşk ateşim,

Umurunda değil, batarsa güneşim,

Umurunda değil, solan çiçeğim.

Kalpsizmisin sen, vermiyorsun sevgini,

Kalpsizmisin sen, dinlemiyorsun beni,

Kalpsizmisin sen, anlamıyorsun nedenini,

Kalpsizmisin sen, yakıyorsun sevenini.', 'Elimde değil, seni sevmemek, Elimde değil, kalbimi vermemek, Elimde değil, sana gelmemek, Elimde değil, yüzünü görmemek. Senin elinde, beni ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kalpsizmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari Sevda', 'firari-sevda-alev-kutluozen-j0gho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdilerde sevgili

deli sağanaklar gibi yağmak

ırmaklarca taşmak geliyor içimden

                                          

         ve anladım ki...

                                                  

deli sağanakların / asi ırmakların

özünden geçen

firari bir sevda benimkisi...', 'şimdilerde sevgili deli sağanaklar gibi yağmak ırmaklarca taşmak geliyor içimden                                                     ve anla...', ARRAY['Türk Edebiyatı','Şiir','Alev Kutluözen']::text[], 8.5, '{"poet":"Alev Kutluözen","poet_slug":"alev-kutluozen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/firari-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayaldin', 'bir-hayaldin-mehmet-aslan-b1cfz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana duyduğum sevgi, kardeşlikti ilk başta,	

Aslında, bende vurulmuştum sana ilk bakışta,

Düşünemiyordum bir şey, çok fark vardı yaşta,

Yalnızlığımı paylaştım yorganımla, kara kışta.

Aklımdan geçmezdi, seni bu kadar sevebileceğim,

O kadarda önemli değildi, benim seni sevdiğim,

Bir hayaldin benim için rüyalarımı süslediğim,

Bir karakterdin sadece, geceleri düşlediğim.

Aslında seni, kendimden bile gizli severdim,

Kendi kendime, platoniktir deyip geçerdim,

Ulaşılmaz olmandı, benim en büyük derdim,

Beklentim yoktu, bu yüzden her şeyi boş verdim.

Sevinirdim, görünce yanıma geldiğini,

Anlayamazdım asla, kime gönül verdiğini,

İzin vermezlerdi sana, anlatamazdın derdini,

Bazen sen bile, tanıyamazdın kendini.

Ne olduysa oldu, senin doğum gününde,

Büyüdüğünü anlatıyordun, her sözünde,

Hediyeni verdiğimde sana, kapının önünde,

Beni şaşırtan, duygular okudum gözünde.

Beklemezdim hiç, seninde beni seveceğini,

Ummazdım hiç, beni sevdiğini söyleyeceğini,

Yinede biliyordun, seninkilerin karşı geleceğini,

Bense bilmezdim, bu aşkın ihanetinle biteceğini.', 'Sana duyduğum sevgi, kardeşlikti ilk başta,	 Aslında, bende vurulmuştum sana ilk bakışta, Düşünemiyordum bir şey, çok fark vardı yaşta, Yaln...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bir-hayaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Icq Masalları', 'icq-masallari-mehmet-aslan-rews0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun, yanağına konan kar tanesi hikayesini,

Şimdi döndüm o rüzgara, duyamıyorum sesini

Yakaladım hepsini,hiç birinde bulamadım seni	

Demek ki oda yalanmış, kandırmışsın beni

		

Seni, canımdan çok seviyorum derken bana,	

Enayi gibi, o zaman nasılda inanmıştım sana,

Hayatın palavraymış, hep yalan söylemişsin bana,

Yanılıyorumdur belki, tekrar inanmak isterdim sana.

Seni asla bırakmayacağım demiştin; bıraktın,

Bizi hiç kimse ayıramaz demiştin; ayrıldın,

Çılgınca sevmeye devam edeceğim demiştin; sevmedin

Şimdi dersin, ben bunların hiç birini söylemedim.

	

Hazırlan,seni sabırsızlıkla bekliyorum dedin,

Hazırlandık her türlü şartlara; sen ne halt ettin,

Keder gecesini geçtin, kader geceni mahvettin,

İnan bana o gece dünyamı karartıp, beni kahrettin.', 'Hatırlıyor musun, yanağına konan kar tanesi hikayesini, Şimdi döndüm o rüzgara, duyamıyorum sesini Yakaladım hepsini,hiç birinde bulamadım s...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/icq-masallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'sMS mASALLARI', 'sms-masallari-mehmet-aslan-bb56i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıskanırdın hani toprağın rengini,

Saçlarımın rengini almış diye.

Kıskanırdın hani esen rüzgarı,

Saçlarımı okşuyor diye.

Hani o akşam hayalim,

Canlanmıştı gözlerinde

Işık oluyordum sana hep,

Karanlık gecelerinde,

Hani yıllanmış şarap gibi,

Yanıyordum içinde,

Ölesiye özlemiştin beni,

Hani o gecenin üçünde.

Keşke bugün sana sarıldığım gibi,

Şu anda da sarılıyor olabilsem,

Yalnız kaldığımızda zaman çabuk geçti su gibi

Keşke her zaman senin yanında olabilsem’.

Demiştin ya; bende keşke diyorum,

Seni her zaman yanıma bekliyorum,

Unutamadım, seni hala seviyorum

Fazla değil sadece seni senden istiyorum.

Keşkelerle olmuyor bu işler,

Hayırlı  görünmüyor, senin bu gidişler,

Düşünemiyorlar, onlar nasıl sevmişler,

Mazilerine bak, hepsi ot gibi evlenmişler.

Akşam yalnızlığını İyi bilirdin,

Benim kollarımda olmayınca; 

Dudaklarınla beni beklerdin,

Öpücüklerime doymayınca.

Yanında bir resmim olsun isterdin,

Karanlık gecelerini aydınlatacak; 

Odanda varlığım olsun isterdin,

Soğuk gecelerini ısıtacak.

Güzel gözlerimi isterdin,

Geçmiş yaşantını görebilecek; 

Islak dudaklarımı isterdin,

Seni gizli, gizli öpecek.

Bende çok isterdim ama olmadı,

Onlar seni soğutmaktan doymadı,

Hiç kimse ikimizi bir yastığa koymadı,

Vicdansız sevgilim hiç halimi  sormadı.', 'Kıskanırdın hani toprağın rengini, Saçlarımın rengini almış diye. Kıskanırdın hani esen rüzgarı, Saçlarımı okşuyor diye. Hani o akşam hayali...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sms-masallari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Nefeslik Hayat', 'bir-nefeslik-hayat-salih-ozalasan-njdih', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beyhudeymiş koca bir ömür

Geçti görmeden çarşı pazarı

Aynı tabuta koydular

Kör cahili hem de okur yazarı

Kimimiz uzun yaşadı hayatı

Kimimizin yüzüne örtülmedi duvağı

Kimileri ana rahminde cenin

Görmek nasip olmadı ana kucağı

Veyseller yaşadı iki gözü kapalı

Sadık yar eyledi kara toprağı

Sultanlar yaşadı zaferlere sevdalı

Atların sırtı oldu otağı

Sevdalılar yaşadı aşkları hikaye

Kimi aslı kiminin keremdi adı

Kalmadı dünya kimseye baki

Dünyaya hükmedenlerin 

Gözleri ardında kaldı

Doğumdan ölüme hayat bir nefes

Bir nefes daha almak 

Tüm canlıların tek muradı

İşte geldik, işte gidiyoruz

Girdiğimiz kapı kapanmadan

Açıldı çıkacağımız kapı

Gönüller kırdık yenildik nefsimize

Sorulacak bize bir gün hesabı

Tamah ettik, bize baki sandık

Bir nefeslik kısa hayatı

Y tarihi 20-09-04

Salih ÖZALŞAN', 'Beyhudeymiş koca bir ömür Geçti görmeden çarşı pazarı Aynı tabuta koydular Kör cahili hem de okur yazarı Kimimiz uzun yaşadı hayatı Kimimizi...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bir-nefeslik-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahreden Şarkılar', 'kahreden-sarkilar-mehmet-aslan-zkhjx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beni sana anlatan şarkılar dinliyorum anlıyor musun

Bir gece sana da dinletmiştim bilmem hatırlıyor musun

“Benim bütün derdim, arzum sensin canım sevgilim

Vazgeçemem asla senden haberin olsun”

Böyle diyor sanatçı şarkısının  sözlerinde,

Bir sahte mutluluk görüyorum gözlerinde,

Kendi kendini kandırıyorsun sözlerinde

Gerçekte bir arayış görüyorum gözlerinde

Ayrıldığın günden  beri kalbim perişan gönlüm deli,

Sana yazdım derdimi anlatan aşkımla dolu o sözleri,

Unutamıyorum asla sevgiyle dolu görünen o gözleri,

Unutamazsın asla seninlen geçen o günleri.

Dinlediğin her şarkıda beni duyacak beni hatırlayacaksın,

Her nakaratın arasında bir nefes alıp kahrolacaksın,

Bütün bu yaptıklarına bir gün pişman olacaksın,

Bir gün gelecek utancından ve kahrından öleceksin.

O zaman bilmiyorum ben sensiz ne edeceğim,

Sakın üzülme çünkü peşinden bende geleceğim,

Burada bitmezse hesabı ötede soracağım

Bu gidişle belki de ben senden önce gideceğim.', 'Beni sana anlatan şarkılar dinliyorum anlıyor musun Bir gece sana da dinletmiştim bilmem hatırlıyor musun “Benim bütün derdim, arzum sensin ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kahreden-sarkilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir esir', 'demir-esir-ahmet-hani-9xlkq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ezizim esir oldum

ezildim xemir oldum.

düşmana baş eymedim

daş oldum demir oldum.', 'ezizim esir oldum ezildim xemir oldum. düşmana baş eymedim daş oldum demir oldum....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/demir-esir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Qelem', 'qelem-ahmet-hani-bvhig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'dostun ömrü çox olsun

düşmanları yox olsun

elindeki qelemi

alovlu bir ox olsun.', 'dostun ömrü çox olsun düşmanları yox olsun elindeki qelemi alovlu bir ox olsun....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/qelem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimal yıldızı', 'simal-yildizi-harun-kuscu-ugny6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ey mezapotamyanın sıradışı kızı

seni sana anlatayım nasıl bulduğumu

sen ey gökyüzünün şimal yıldızı

birde benden dinle kim olduğunu 

sen güneşten parlak,aydansa narin

sen yaban dağlarda taze sümbülsün

sen geçmişi-geleceğisin bu diyarın

sen hayatı ta kendisi yaşanmamış ömürsün

sen esaret bahçelerine sığmayan yürek

sen inandığını yaşayansın hemde bilerek

sen ölümü bile karşılarsın gülerek

sen hürriyet dağlarında özgür bülbülsün

sen bir ceylansın kimse vuramaz seni

sen nadide çiçeksin kimse kıramaz seni

sen buraya aitsin kimse ayıramaz seni 

sen bu topraklarda solmayan gülsün', 'Sen ey mezapotamyanın sıradışı kızı seni sana anlatayım nasıl bulduğumu sen ey gökyüzünün şimal yıldızı birde benden dinle kim olduğunu  sen...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/simal-yildizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimse bilmez', 'kimse-bilmez-harun-kuscu-cnlb4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya denen şu alemde 

kavrulurum kimse bilmez

kader denen her kalemde

savrulurum kimse bilmez

ruhlar ülkesinde ruhum

kendime karşı dururum

hiçlik denen kor ateşte

yoğrulurum kimse bilmez

onyedimde düştüm aşka

kadın değil sevdam başka

gece-gündüz rüya düşte

doğrulurum kimse bilmez

gurur kibir bizden geri

gönlümüzde yoktur yeri

bu aşka düşeli beri

vurulurum kimse bilmez', 'Dünya denen şu alemde  kavrulurum kimse bilmez kader denen her kalemde savrulurum kimse bilmez ruhlar ülkesinde ruhum kendime karşı dururum ...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kimse-bilmez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür', 'omur-i-smail-sentekin-ced2t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '************

Üşür ölüm hazanda 

eylül 

eylül gündü gözlerin                       

menekşelerle 

ilkbaharda…', '************ Üşür ölüm hazanda  eylül  eylül gündü gözlerin                        menekşelerle  ilkbaharda…...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şentekin']::text[], 8.5, '{"poet":"İsmail Şentekin","poet_slug":"i-smail-sentekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/omur-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı', 'aci-i-smail-sentekin-rog5a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her şeyden önce düşünüyorum seni

Öncesi olmayansın 

Felsefe insanın,  doğanın tanımıyla başlar

Sen ondan da öncesin

Kurgularım yavaş ve yavan

Hızla büyüyen bir dalgasın

Nasıl olduğunu çözemezken

Birileri ulaşılmaz olduğunu söyler

Tanrı olsan tanırım

Kötülük yapsan bilirim

Sen farklı meridyendesin

Çiçek desem gamzen uçurum

Yıldız desem

Gözlerindeki içtenlik

Mevsim

Tenindeki koku

Rüzgarla evren oluyorsun

Bilmem nasıl anlatmalı seni

Tanıdıklarıma

Fısıltıyla

ilk kez.', 'Her şeyden önce düşünüyorum seni Öncesi olmayansın  Felsefe insanın,  doğanın tanımıyla başlar Sen ondan da öncesin Kurgularım yavaş ve yava...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şentekin']::text[], 8.5, '{"poet":"İsmail Şentekin","poet_slug":"i-smail-sentekin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aci-51-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasihat', 'nasihat-oguz-cevher-p73zs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oğuzlarla başlamış yol

Yürümüşler bak kol kol

Sen dünyaya hep örnek ol

Türklüğünle öğün yavrum

Yasaklara uzanma hiç

Haramlarla bezenme hiç

Batılıya özenme hiç

Türklüğünle öğün yavrum

Yapsalar da binbir oyun

Kimselere eğme boyun

Asalettir senin soyun

Atatürk’ le öğün yavrum

İtler sana dalaşmasın

Yolların hiç dolaşmasın

Aman şeytan bulaşmasın

Kur’ anınla öğün yavrum', 'Oğuzlarla başlamış yol Yürümüşler bak kol kol Sen dünyaya hep örnek ol Türklüğünle öğün yavrum Yasaklara uzanma hiç Haramlarla bezenme hiç B...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Cevher']::text[], 8.5, '{"poet":"Oğuz Cevher","poet_slug":"oguz-cevher","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nasihat-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm, Eylül''de Yakışır Bana', 'olum-eylul-de-yakisir-bana-i-hsan-dinibutun-g587s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm, Eylül''de yakışır bana

Soyunurken ağaçlar

Yapraklar hazırlanırken dansa

Yavru kumrular uçar yuvalarından

Yeni bir hayata gebedir doğa

Serin akşamların dostu

Rüzgarlı sabahların sahibidir

Bir senfonidir Eylül aslında

Eylül, yeniden başlamadır

Ölüm, Eylül''de yakışır bana

Tüm dostlarım hazır olur

Kalabalık olur son yolculuğum

Helallik almadığım kimse kalmaz

Eylül yağmuruyla ıslaktır toprak

Mezarım zor kazılmaz

Hayatımla oynayan felek

Sakın ha! ölümümle oynama

Ölüm, Eylül''de yakışır bana', 'Ölüm, Eylül''de yakışır bana Soyunurken ağaçlar Yapraklar hazırlanırken dansa Yavru kumrular uçar yuvalarından Yeni bir hayata gebedir doğa S...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olum-eylul-de-yakisir-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet Ali', 'mehmet-ali-oguz-cevher-cxdnk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haber verin eşe dosta

Mehmet Ali yine hasta

Paran olsa deste deste

Önce sağlık sonra para

Çalışsan da harıl harıl

Kitabına sıkı sarıl

Uslan artık biraz durul

Önce sağlık sonra para

Ünlü ünsüz ne fark eder

Sıra kimde ise gider

Bir gün herkes borcun öder

Önce sağlık sonra para

Büyük küçük hiç anlamaz

Zengin fakir hiç dinlemez

Şöhret filan hiç tınlamaz

Önce sağlık sonra para

Kuş değilsin uçamazsın

Mümkün değil kaçamazsın

Önüne de geçemezsin

Önce sağlık sonra para', 'Haber verin eşe dosta Mehmet Ali yine hasta Paran olsa deste deste Önce sağlık sonra para Çalışsan da harıl harıl Kitabına sıkı sarıl Uslan ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Cevher']::text[], 8.5, '{"poet":"Oğuz Cevher","poet_slug":"oguz-cevher","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/mehmet-ali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübarek olsun', 'mubarek-olsun-ahmet-hani-2x3mh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir addım

..iki addım

...üç addım

qapı bağlıdır.

bir addım

..iki addım

...üç addım

duvar ucadır.

bir addım

..iki addım

...üç addım

dağlar ucalıb

Eyvaz qocalıb? 

içinde bir nefer

çağırır seni.

yeniden qalxırsan

bir addım

..iki addım

...üç addım

qapını açırsan.

dörd addım

..beş addım

...altı addım

duvarı yıxırsan.

yeddi addım

..sekkiz addım

...doqquz addım

dağları aşırsan.

on addım

mübarek olsun.', 'bir addım ..iki addım ...üç addım qapı bağlıdır. bir addım ..iki addım ...üç addım duvar ucadır. bir addım ..iki addım ...üç addım dağlar uc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mubarek-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amirim', 'amirim-oguz-cevher-4n4x7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hani memur evladındı

Üvey miyiz be amirim

Doğruluk hep yanındaydı

Hiç olmuyor be amirim

Memurunu ayırmazdın

Hiçbirini kayırmazdın

Boş yere laf buyurmazdın

Hiç olmuyor be amirim

Yüzümüze övüyorsun

Arkamızdan sövüyorsun

Yalakayı seviyorsun

Hiç olmuyor be amirim

Gönül dostu değilsin sen

Akil değil cahilsin sen

Kötülere dahilsin sen

Hiç olmuyor be amirim

Kimse seni görmez bir gün

Görse selam vermez bir gün

Hatırını sormaz bir gün

Hiç olmuyor be amirim', 'Hani memur evladındı Üvey miyiz be amirim Doğruluk hep yanındaydı Hiç olmuyor be amirim Memurunu ayırmazdın Hiçbirini kayırmazdın Boş yere l...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Cevher']::text[], 8.5, '{"poet":"Oğuz Cevher","poet_slug":"oguz-cevher","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/amirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unut', 'unut-harun-kuscu-2oz8l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Akmak şimdi sana yol

anlamak zeka

bu yürek şimdi sana kul

buda bana ceza

Ağlama bana dönmesende

dayanamam sana

ipekten mendil değse 

yanağına

onu bile kıskanırım 

anlasana

Yırtık bohçalarda sakladım 

umut

eksiler bana artılar 

sana

ve be seni hiçbir zaman 

unutamasamda

olmamış farzet herşeyi

ve beni unut', 'Akmak şimdi sana yol anlamak zeka bu yürek şimdi sana kul buda bana ceza Ağlama bana dönmesende dayanamam sana ipekten mendil değse  yanağın...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/unut-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demedimmi', 'demedimmi-harun-kuscu-mv2rm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Demedimmi gönlüm bu sevda sana ağır

Demedimmi bu kız sevdana karşı sağır

Demedimmi bundan sonrası senin için hep kahır

Demedimmi gönlüm bu sevda sende paslanır

Demedimmi gönlüm fazla derine inme diye

Demedimmi gönlüm sevda atına binme diye

Demedimmi gönlüm hemen yanıp sönme diye

demedimmi deli gönlüm bu sevda sende yaşlanır

Sen aşk diyorsun o diyor heves

Sen bağırıyorsun o vermiyor ses

Yeter artık benden buraya kadar pes

Bu aşkın biletini sonsuza dek kes

Değerini bilmeyenler gönlümde almasın nefes', 'Demedimmi gönlüm bu sevda sana ağır Demedimmi bu kız sevdana karşı sağır Demedimmi bundan sonrası senin için hep kahır Demedimmi gönlüm bu s...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/demedimmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nü III', 'nu-iii-ahmet-aksoy-6ot9q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dalgaların sonsuz tınısı

açık bir gökyüzü

alabildiğine dingin güneş

suyun ve köpüğün uyumu', 'dalgaların sonsuz tınısı açık bir gökyüzü alabildiğine dingin güneş suyun ve köpüğün uyumu...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nu-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Böyle Yaşanır..!', 'ask-boyle-yasanir-umut-gul-sctx8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''böyle başlar aşk... 

ya...sonra.... 

..............sonrasini yine senden duymak isteriz....''

                                                  Abir Zaki

(Sevgili Abir Zaki ''yi kıramadım ve sonrasınıda yazdım)

Ah..! O ilk öpüş 

İlk heyecan ilk temas

Kavrulur bedenin

Erir için 

Çekilir damarlarından kanın

Duyulur, dünyanın öbür ucundan kalp atışların

Sıtmaya tutulur her yanın…

Dur dokunma derken dilin

Hadi öp diye yakarır için

Bir sen, bir de o vardır koca dünyada

Görmez kimseleri gözün…

Dünya durur öperken 

Güneş söner sararken

Ay bir başka doğar

Bir başka eser rüzgar

Sabahlar bir başkadır, geceler bambaşka

Yaşamak,  bir başka güzeldir  onun yanında…

Onunla yersin her lokmayı 

Onu anlatır tüm şarkılar 

Tüm şiirlerinde onun  adı 

Duyduğun her ses onundur

Gördüğün her canlı sanki o…

Güllerde onun kokusu

Çayında onun tadı

Sigaranın dumanındadır

Aldığın her nefeste  o…

Onunla başlarsın güne

Onunla dalarsın uykuya

Rüyalarını süsleyen odur

Yanağını ıslatan da o…

Kısalır mesafeler

Önemi olmaz

Ne zamanın ne mekanın

Tadı kalır canında

Yalnızca yaşanan anın…

Sadece o vardır

Yoktur ondan ötesi ve öncesi

Aşk böyle yaşanır….

Böyle yaşanır aşk….

Ya..!   Sonra….

(Aşk gibi Aşkı  tadanlara ithaf olunur...)', '''böyle başlar aşk...  ya...sonra....  ..............sonrasini yine senden duymak isteriz....''                                               ...', ARRAY['Türk Edebiyatı','Şiir','Umut Gül']::text[], 8.5, '{"poet":"Umut Gül","poet_slug":"umut-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ask-boyle-yasanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolum Türkiyem', 'anadolum-turkiyem-emin-baydil-ypg6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anadolum, Türkiyem! 

Tam dokuz asırlık tarihim...

Kapısını açtığım Malazgirt

Uğruna can verdiğim, 

Herşeyim...

Anadolum, Türkiyem! 

Dalbudak olmuş genç çınarım...

Selçuklum, Osmanlım, Oğuz neslim

...ve Türklük kokan öz pınarım...

Anadolum, Türkiyem! 

Şu yemyeşil güzel otağım...

Evim-barkım, yediğim-içtiğim,

Türkiyem, biricik dert ortağım...

Anadolum, Türkiyem! 

Her taşına damga vurduğum...

Büyük ülküm, vatanım Türkiyem,

Gece ve gündüz kafa yorduğum...

Türkiyem, herşeyim...', 'Anadolum, Türkiyem!  Tam dokuz asırlık tarihim... Kapısını açtığım Malazgirt Uğruna can verdiğim,  Herşeyim... Anadolum, Türkiyem!  Dalbudak...', ARRAY['Türk Edebiyatı','Şiir','Emin Baydil']::text[], 8.5, '{"poet":"Emin Baydil","poet_slug":"emin-baydil","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/anadolum-turkiyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte benim seccâdem', 'i-ste-benim-secc-dem-sair-ahrazi-180b6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ﺀ 

Kırmalı bu zinciri her mühleti yakmalı,

Dumandaki sır gibi terk etmeli sûreti.

Varmalı da semâya bir buluttan bakmalı,

Kum tanesi görmeli yıkılan esâreti.

ﺀ ٠ ﺀ 

Seyretmeli hicreti,perde çeken nesneden,

Durağanlık yurduna yapayalnız varmalı.

Ayrılsan da maddeden.bırakmayan tek neden; 

Nefsinde ki şeklin ki,isminle yalvarmalı.

ﺀ ٠ ﺀ ٠ 

Ve şeytanda görmeli her nevîden bir hıncı,

Kıpkırmızı bir göz ki,târif etmek ne tuhaf.

Bu kaçıncı hileydi,söyle mel’ûn kaçıncı? 

Her sözünde bir tuzak.her tuzakta bin sahaf.

ﺀ ٠ ٠ ﺀ 

Bırak şimdi bunları,bırak da gel diyen Ses,

Öyle duru ve sakin,nurdan bile daha pak.

Dört yanını sarsa da günâh dolu bu kafes,

O sesteki huzurla her yön ayrı bir sapak.

ْ ْ ْ ْ ْ ٠ ْ 

Ey cehâlet pınarı,akıl dolu son kuyu,

Tapmayacak cihâna,kanmayacak bu âdem.

İhânetin bağrına mesken kuran uykuyu,

Baş koydukça atacak,İşte benim seccâdem; 

ﺀ ﺀ ْ ﺀ', 'ﺀ  Kırmalı bu zinciri her mühleti yakmalı, Dumandaki sır gibi terk etmeli sûreti. Varmalı da semâya bir buluttan bakmalı, Kum tanesi görmeli...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/iste-benim-seccadem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cekmece 3', 'cekmece-3-sair-krieg-0ovyk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'cekmece 3te hayaller, dusler

korkakligin makyajli yuzu bu aldanma

bir yarar saglamiyor

gucten dusuruyor aksine.

yalan oldu maskeler inanma.

vazgecmek, susmaya benziyor; 

kolay ama can sikici..

ruhlar yaniyor, kavruluyor dualar

tanrilarin kanlari tukenmis

onlar bile kayitsiz..

hayranlik sardi bedenleri

sonsuz teslimiyet,

gizli kapakli doguyor gunes,

farkedilmek istemiyor,

kutsal olmayani ariyor sanki..

degi$imin makyajli yuzu bu aldanma

bir yarar saglamiyor

kanini emiyor aksine

cekmece 3e yeni birimler ekliyor sadece...', 'cekmece 3te hayaller, dusler korkakligin makyajli yuzu bu aldanma bir yarar saglamiyor gucten dusuruyor aksine. yalan oldu maskeler inanma. ...', ARRAY['Türk Edebiyatı','Şiir','Şair Krieg']::text[], 8.5, '{"poet":"Şair Krieg","poet_slug":"sair-krieg","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/cekmece-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avaz Avaz Sustum Bugün...', 'avaz-avaz-sustum-bugun-i-mdat-ozcan-nf6rg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Öfkelendim 

Kin güttüm 

Kan kustum bugün 

Delice hoyratça estim bugün 

Boz bulanık sisler bastı hayallerimi 

Katran döktüler geceye 

Umutlarımı yarınlara astım bugün 

Ey karanlığın cellatları 

Gelin üstüme üstüme 

Korkmam gayrı 

Gözlerimi pustum bugün 

Ve oy Güzel kız oy 

Ülkem kadar güzel kız oy 

Çınlıyor hala sesin kulaklarımda 

Dumuyormusun sen 

Dağ doruklarına 

Uçurum kıyılarına 

Kuytu çıkmazlara 

İstanbul '' a, Kartal '' a 

Mührümü bastım bugün 

Ve oy güzel kız oy 

Ülkem kadar güzel kız oy 

Avaz avaz sustum bugün... 

Kendimden geçtim bugün 

Ölümler içtim bugün...', 'Öfkelendim  Kin güttüm  Kan kustum bugün  Delice hoyratça estim bugün  Boz bulanık sisler bastı hayallerimi  Katran döktüler geceye  Umutlar...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/avaz-avaz-sustum-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznü Sevdim', 'huznu-sevdim-cafer-bayar-y5yy5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakışın

Sonbahar; yaprak dökümü

Umudun ölüm mevsimi yani.

Bakışın hüzün

Günbatımında inim inim, 

Taşrada bir mezar

Baştaşsız, yitik

Paslanmış hançer bakışın

Aşkının inlediği,

Aşkının yandığı, yakardığı,

Öksüz kaldığı yerinde yüreğimin

Bu yüzden hüznü sevdim

Paslı hançer yarasını, yüreğimde

Ve yıkılmayı, yüz üstü.

Gülüşün

Gaddar, bir o kadar da mağrur fırtına

Hayal gülünün son anı yani.

Gülüşün hüzün

Ölüm kusar gibi

İdam mahkumuna, gülüşün.

Bu yüzden hüznü sevdim

Seninle gelecek baharı değil, barut kokusunu

Gözümde, bahtın kadar kara bir bant

Bir şafak vakti

Yıkılmayı diz üstü', 'Bakışın Sonbahar; yaprak dökümü Umudun ölüm mevsimi yani. Bakışın hüzün Günbatımında inim inim,  Taşrada bir mezar Baştaşsız, yitik Paslanmı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Bayar']::text[], 8.5, '{"poet":"Cafer Bayar","poet_slug":"cafer-bayar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huznu-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Leğen Tuzlu Su', 'bir-legen-tuzlu-su-baykal-kaanalp-b44gw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çiğnediğinden eminim

gezdiğin yollarda

içinden atamadığın

bir parça yalnızlığını

onun adını bile

hatırlıyamadığı için

içerlediğine hafızana

kızgınlığını göstermeden

umutsuzluğa kapıldığın

saatlerde çıkagelirdi

kapının önüne,tıklatırdı

demir halkasını kalbinin

saatlerce bekletirdin

garibi,gitmesini hiç

istemediğin için mi? 

görünmezdin,hiç bilemedin

sonra üzgün yıldızlar

sabaha kadar başının

etini yerdi,salaş

peluş tazeliğindeki kahve

ya çıkıp gitmek

istediğinde kalbin

yerinden,odadan odaya

koşuştururdu puf terliklerin

ama ayakların seni

terkederdi,buna bir

çözümün yoktu,ancak

bir leğen tuzlu su', 'çiğnediğinden eminim gezdiğin yollarda içinden atamadığın bir parça yalnızlığını onun adını bile hatırlıyamadığı için içerlediğine hafızana ...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bir-legen-tuzlu-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çürük Armut', 'curuk-armut-baykal-kaanalp-ogbgl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'devlet, sorun çıkaran

bir kız çocuğu gibisin

nazın hiç bitmiyor

neden böyle yapıyorsun

anneciğim

eşek kadar kız oldun

hala haydutluk peşindesin

cebimden para aşırıyorsun

hiç utanmıyor musun? 

sana yeterince

harçlık vermiyor muyuz? 

bu gidişle babana

söyleyeceğim tek tek

yaptığın kurnazlıkları

hani olurda

ihtiyaç hissdersin

bi diyeceğim olmaz

ama sen öylemi ya

yediğin önünde

yemediğin ardında

hadi yalan de

neyin eksik? kızım

''ama anne ya

ben istiyor muyum? sanki

bu hayatı böylece

bomboş yaşamayı

her şey var

hiç bir şey yok

yemeğime bi tuz bile

atamıyorum

kendi başıma

sende böyle mi? 

yaşadın,çocukluğuğnu

odun taşımadan

fırına

baban yokken kendi

pişirdiğin ekmekleri

kendin satmadın mı? 

arkadaşlarına

pasta niyetine

kime çekmişim acaba? 

armut dibine düşer tabi

çürük olsa bile', 'devlet, sorun çıkaran bir kız çocuğu gibisin nazın hiç bitmiyor neden böyle yapıyorsun anneciğim eşek kadar kız oldun hala haydutluk peşinde...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/curuk-armut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-baykal-kaanalp-7117m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu şehir insanı acıtıyor

tatsız ekilmiş tohumu

hiç su verilmemiş 

toprağına

bu şehir insanı acıtıyor

bütün yolları kapalı

çıkmaz sokak

her yanı

bu şehir insanı acıtıyor

hiç bir dostluğu

inandırıcı değil

senaryosu eksik

bu şehir insanı acıtıyor

aşkları vurdumduymaz

kavuşma özlemleri

gerçek değil', 'bu şehir insanı acıtıyor tatsız ekilmiş tohumu hiç su verilmemiş  toprağına bu şehir insanı acıtıyor bütün yolları kapalı çıkmaz sokak her y...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sehir-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhtiras', 'i-htiras-erol-dal-uxvft', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey istemezsen

Hiçbir şeye 

İhtiyacın yoktur.

/Mekan', 'Hiç bir şey istemezsen Hiçbir şeye  İhtiyacın yoktur. /Mekan...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ihtiras-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılarım Dillere Düştü Söyleyemem', 'sarkilarim-dillere-dustu-soyleyemem-murat-nail-guney-u8okl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzat deme ellerini uzatamam artık

Bir zamanlar el ele idik deme,

Öylesine yıktın ki gururumu

Öyle uzak çarpıyor ki artık senden kalbim

Ellerim iki yanıma düştü,uzatamam....

Yine senin şarkılarını duymak istiyorum deme

Artık kimse duyamayacak...

Bir zamanlar beraber söylemiş olsak ta

Öylesine küstü ki bana şarkılar,

Öylesine sus-pus oldu ki dudaklarım

Şarkılarım dillere düştü...söyleyemem...

Sana İstanbul geceleri getiremem artık,

Bir zamanlar gece yarıları gelmiş olsam da yanına,

Güneşin doğuşunu beraber görmüş olsak da,

En güzel duyguları tatmış olsam da,

En güzel  günlerimi yetirdim gecelerde,

Sana geceleri getiremem...

Beni yine sımsıcak öp deme, 

Binlerce kez öpüşmüş olsak da

Dudaklarımız kavruluncaya dek,

O dudaklaradan nefret dökülmüş yazık,

O dudaklar buz gibi soğumuş,

O dudaklar kiltlenmiş ne çare,

Öpemem...

Beni eskisi gibi sev deme,

Aylar yıllar saçlarıma ak döktü,

Kalbim tutsak oldu geçmişimize,

Tüm sevgilere yabancıyım artık...

Sevemem.....', 'Uzat deme ellerini uzatamam artık Bir zamanlar el ele idik deme, Öylesine yıktın ki gururumu Öyle uzak çarpıyor ki artık senden kalbim Eller...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sarkilarim-dillere-dustu-soyleyemem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşcakal', 'hoscakal-nazim-ercan-0y48v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '......................................Melek Kızım İmge Selen''e

Titriyor gördüğüm düş

Zamanın yitirildiği gölgelerin sevisi

Merhaba; 

İçinde bin umut gizli tebessümdün sen

Olmadı melek olmadı

Atılamayan o çığlıkların 

Direnişiydin sen 

Gercekliğini yitirmiş tebessümlerin

Kalıntısı yüzlerde

İmgeleri yok

Bu bahar sabahının

Çiy’i yok

Ben yokum

Yoksun sen

O yok

Yokuz biz

Senden arta kalan bir tutam tebessüm

Bir tutam umut

Merhaba; 

Bir garip üçlemenin içinde yitmiş düş

Merhaba; 

Derinlerde bir istridyenin sıcaklığında kaldı düşler

Üşümüş ruhlara

Soğuk tenler eşlikte

Yalnızlığa ise esrik bedenler

İmgeler yok artık

Ben yokum

Bir sen; 

Belki de; 

Puslu sabahların boynuna astığı çiy damlası artık gözlerinde

Hani bazen şiir de tükenir

Çırılcıplak kalırsın

Bir sen bir düşlerin ve yitirişlerin

İşte öyle

İmgeler yok artık

Yokum ben

Zamanın yittiği uçarı yürek

Merhaba; 

Üşüyorum gene

Ruhumu ısıtan tebessüm

Hoşcakal; 

Gidişlerin ardında bıraktığı (iz)     

Yitişlerden arta kalan yalnızca (düş)     

Hoşcakal; 

Bir dahaki merhabaya ceyrek kala

Hoşcakal...

Tüm tonlarını yitirmiş yaşam

Akordu bozuk bir enstruman yürekler

Minik bir dokunuş 

Minik tebessümlerin eşliğinde

İki damla çiy gözlerde

Hoşcakal...', '......................................Melek Kızım İmge Selen''e Titriyor gördüğüm düş Zamanın yitirildiği gölgelerin sevisi Merhaba;  İçinde ...', ARRAY['Türk Edebiyatı','Şiir','Nazım Ercan']::text[], 8.5, '{"poet":"Nazım Ercan","poet_slug":"nazim-ercan","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/hoscakal-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizimki Aşk Değil, Sevda Hiç Değil   ss13', 'bizimki-ask-degil-sevda-hic-degil-ss13-nesrin-gocmen-h0rz8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesini duyarak geçiyor yıllar,

yüzünü görme şansım bile yok.

Son tren gibi kaçıyor bahar, 

kaçan trenlereyse kahrım çok.

.

Geleyim diyorum, 

gelme, diyorsun.

Öyleyse, sen bana gel desem, 

bilmem diyorsun.

Sanki açıkça gülme diyorsun, 

ağlayıp, gezmek senin şansın diyorsun.

. 

Bizimki aşk değil, 

sevda hiç değil. 

Biz bilerek avlandık çıktığımız yolda. 

Zifiri karanlıkta çıktığımız dağda,

bir yol göster diyorum; 

susuyor, susuyorsun. 

Leyla, Mecnuna ne söylemişse, 

ben de sana aynı sözleri dedim. 

Seven sevdiğinden ne istemişse, 

ben de senden aynı şeyi istedim. 

Bilirim, yok benim gönlümün aklı. 

Sitemde mi haklıyım, 

hüzünde mi haklı? 

Maalesef sen, 

düşünemedin beni 

telli duvaklı...

.

Sevgi vefa ister, özveri ister. 

Tapar gibi bakan gözler, 

duymak istediği sözler ister. 

Emek ister, 

mücadele ister, güven ister.

Sana bir söz ver dediğim zaman, 

verdiğin yanıtlar ateşle, duman; 

saçılıyor etrafımda küller her zaman..

Gerçek bir sevgide kavga olur mu? 

Hangimiz aldattık, 

hangimiz ihaneti yaşattık? 

Hangimiz hile sezinledik gözlerimizde? 

Bu nasıl talih, nasıl yazgı böyle? 

.

Ne çok sevdiğimi; 

çağırsan, koşup geleceğimi bilemiyorsun.

Seninim dediğimdeyse, 

gülüp geçiyorsun. 

Sen benim olamazsın, aramızdaki dağlar, kalkmaz diyorsun..

Ben sevda bahçesinde yoluna güller derdim diyorum, 

sense yoluna serilmem diyorsun..

Bir sevda böyle mi yaşar? 

Gönüller hayalle, düşle mi kanar? 

Seven; seve, seve hüzne mi koşar? 

Seven, sevdiğini böyle mi salar? 

Söylüyorum sana son sözümü, 

söylüyorum tüm benliğimi, 

bütün özümü..

.

Ben söylesem de,

bilirim ne diyeceğini,

su getireceğin dere 

geçecek bini.

Onun için sen sus, 

bir şey söyleme... 

Hiçbir şey deme,

sen söyleme.

.

(sen söyleme-13)     

24/09/2004', 'Sesini duyarak geçiyor yıllar, yüzünü görme şansım bile yok. Son tren gibi kaçıyor bahar,  kaçan trenlereyse kahrım çok. . Geleyim diyorum, ...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Göçmen']::text[], 8.5, '{"poet":"Nesrin Göçmen","poet_slug":"nesrin-gocmen","theme":"Türk Şiiri","is_hero":false,"total_lines":69,"source_url":"https://www.antoloji.com/bizimki-ask-degil-sevda-hic-degil-ss13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler', 'sairler-i-smail-sahin-4k7fa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşkı biz yarattık.

haketmese de maşuk,

şiirler yazdık.

sırtta acısıyla,

başta dumanıyla,

bizim olan bizim dedik; 

hergece biz aşkla yattık.

aşkla yattık.

biz...

aşkla...

.....', 'aşkı biz yarattık. haketmese de maşuk, şiirler yazdık. sırtta acısıyla, başta dumanıyla, bizim olan bizim dedik;  hergece biz aşkla yattık. ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sairler-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlar', 'yagmurlar-i-smail-sahin-m8rt9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yağmurlar...

yağar içime.

dolarım,

delinse de tenim

öksüz bir şiirle

taşarım.

ruhum boğulur

bedenimde.', 'yağmurlar... yağar içime. dolarım, delinse de tenim öksüz bir şiirle taşarım. ruhum boğulur bedenimde....', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yagmurlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serüven', 'seruven-akin-akca-3bbur', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekimle bükülen düzlemleri

Geometri kılan; 

Bir çizgi ulaştı karlı yolda,

Üçgenlerin dik yamaçlarına.

Çizgi, eğri uzayda yol almış; 

Hareket dimağına da, 

geometri denmiş.

Bunların benzeşmesi; 

(Eğri uzayla eğri uzayın kesişmesi)

Pekala insana gelebilir,

Sanki bir karmaşa.

Unutulmamalı ki, (ama)

; Bazı, bazı, üçgen; 

sert bir çizgi.

(Yine de)

Tanrı faktörünü icra ediyor gibi; 

Ya da insanı Tanrı’ya,

(Yine de, benziyor

karmaşa sanki, karmaşaya)

*

Eğri düzlenen, ütülenen.. 

Düzlenen eğri, sürüveren...

: Eğri cetveller gibi

Düzlemler -

Ki üçgenler,

pürüzsüz; düzlemler,

gözüken.', 'Çekimle bükülen düzlemleri Geometri kılan;  Bir çizgi ulaştı karlı yolda, Üçgenlerin dik yamaçlarına. Çizgi, eğri uzayda yol almış;  Hareket...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/seruven-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrı En Büyük Ressam', 'tanri-en-buyuk-ressam-halil-pazarli-1jxbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Halbuki kadim bir şehirsin sen

böğründe düşsel tarih öyküleri

ve hala büyüyor fasılasız

annannemin vitayağı kutulu 

pembe fesleğenleri..

Sen görmüyorsun

menevişli parmaklarıyla

kırmızı balon satıcılarını

sütçüyü, yoğurtçuyu

bakkal Hasan amcayı

ve babamın Heybeliada''da 

misket oynarken mızıklayıp 

komşu bahçeden çaldığı 

caneriği beyaz günahları..

Ah! İstanbul..

kadim bir şehirsin sen

kokuşmuşluyla mevsimlerin

yüzüne çalıyorum kirlenmişliğini

geceyi bekliyorsun 

geçmişi özlüyorsun

ve karanlığa gömüyorsun çehreni

oysa sana bulaşmıyor kir

sen görmüyorsun 

sen anlamıyorsun

orada Sadabat''ın sedaları

orada Gülhane''nin ağaçları

orada Göksu''nun sandalları vardı

orada nağmesi buruk saz semaileri

badesi eşraftan nice alemler

makberi hiçe sayan ademler vardı.

Ah! İstanbul..

kadim bir şehirsin sen

utangaç bakışlarınla

en alımlı sen

en bigünah 

en cezbede 

azıcık tamah sensin

neylesen 

meğerki neylemesen 

kirlenmiyorsun.

Sen bilmiyorsun

tutup tutup uğruyorsun izdihamınla bana

dudakların dudaklarıma değiyor

kapanıyor göz kapaklarım

Vefa bozası lezzetinde bir aşk oluyor

kursağım yağlandığı zaman..

Dikine kunduramın tekini bırakıyorum

inadına güneş batımı sona eriyor efsun

ve rayihan sokağıma yaklaşıyor her defasında.

Ve birden 

Süreyya Sineması oluyor ömrüm

vakitlerden ilkbahar

perde de siyah beyaz

Ayla Algan ağlıyor biraz

sen gibi..

arkasını dönmüş Sadri Alışık

en afillisinden bir aşkı hançerleyip

kanatıyor kalbini uzaklaşırken

ben gibi..

Sen görmüyorsun

neresinden baksan

neresinden tutsan 

yitik kunduramın diğeri..

Yalnız senin kaldırımlarında yalnızlıklar

ve yalnız senin gölgenin eşiğinde oturup 

margarin yağına serpiştirilmiş 

toz şekerli ekmeğini yiyor çocuklar

sığınaksız, türbedarsız 

öyle aşikar..

Kendinde kendini bulup

sonrada kaybediyorsun

oysa bilmiyorsun

sen asırlık ve masum

ve çağlar sende suskun..

Hani bir paye alsan

gizlenecek uzaklıklar

mevsim yanaklarında delirecek

gönlünden öyküler sızacak

ağlamayacak Ayla Algan

Sadri Alışık arkasını dönmeyecek

filmin adı ''Ah Güzel İstanbul'' olmayacak.

Ama sen bilmiyorsun

Tanrı en büyük ressam

ama sen görmüyorsun..', 'Halbuki kadim bir şehirsin sen böğründe düşsel tarih öyküleri ve hala büyüyor fasılasız annannemin vitayağı kutulu  pembe fesleğenleri.. Sen...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/tanri-en-buyuk-ressam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beş Yüz On Dördüncü Mektup', 'bes-yuz-on-dorduncu-mektup-halil-pazarli-tf3yo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Canım karım sırdaşım Ayten 

Dışarıda kuzey rüzgarları özgürlüğe kısrak gibi ılgıt ılgıt koşarken 

içeride zaman çemberleri inadına kağnı gibi ağır ağır yürürken 

aşırı yalnızlığıma koyu çaresizliğime yine yetiştin 

514. mektubunla yine sen 

inan mektubun elime geçtiğinde 

bayramı alkışlayan çocuklar kadar şenlendim 

yoğun bir eziklik silindi yüreğimden 

sevinmek şenlenmek neşelenmek güzel şeyler be Ayten 

hele birde on üç yıldır hapisteysen 

Oku bunu mektubumu oku Ayten 

bu bir mahkum yorumudur ta gönülden 

tel diken dört duvar arasında 

zifiri sessizlik ortasında 

hayatın sürekli kavgasında 

ve aşkın en derin yarasında 

acı dolu mevsimlerin 

işkence var hesabında 

Hani zaten buraya düştüğün ilk günden başlayarak 

alev alev kavrulan o keskin duygularını 

ufacık bir odanın hain ve sinsi gölgeleriyle zorunlu paylaşıyorsun 

hani zaten o katran rengi soğuk ve rutubetli gecelerin 

delimtrak kalleşliğine boynun bükük öylece katlanıyorsun 

sonra bunlar yetmiyormuş gibi 

elinde tespih ağzında cigara bağrında ıssızlık 

maltada volta atan müebbet arkadaşlarının 

dalga dalga büyüyen ayak seslerine içerliyorsun 

ve bu kısır döngüyle birlikte 

öyle bir kara koza çevreni ilmek ilmek sarmaya başlıyor ki 

önceleri sessiz sakin dengeli hassas bir insan dahi olsan 

sonraları muştalı hırgürlere taraklı küfürlere 

ve demirli pencerelere katıksız alışıyorsun 

hatta ezgisi ne kadar arabesk olursa olsun 

avazı çıktığı kadar bağırarak türkü söyleyen Garip Osman''a bile 

hafifçe gülümsüyorsun 

Düşün 

düşün ki birde mektubun gelmemiş 

işte o vakit bacakların tutmuyor 

hislerin üşüyor bedenin uyuşuyor 

yani bir mumun dibine akan köpük gibi 

yavaş yavaş eriyip sönüyorsun 

yani Aytenim hapiste mektubun gelmeyince 

ranza komşum Deli Recep gibi yaşayan bir ölü oluyorsun 

Dinle beni hikayemi dinle Ayten 

bu bir mahkum gerçeğidir ta gönülden 

doğrunun kanıtı ne ola ki 

insanın gerçeği bir yorumsa 

iyilik kötülük ne ola ki 

çıkmaza girilmiş bir durumsa 

bizim gibi insanların 

işkence var hesabında 

Neyse sen bunları dert etme kalbini ferah tut 

çünkü ben ayaktayım çünkü ben yaşıyorum 

çünkü sen bana tam on üç yıldır yazdığın her mektupla 

sabır taşının ruhu kadar dayanmanın iksirini 

çifte su verilmiş çelik kadar direnmenin kuvvetini 

mutluluğa kopan çığlık kadar geleceğin ümidini veriyorsun 

Sen beni merak etme ben iyiyim 

parada göndermişsin eline sağlık 

Ayten be çocukları çok özledim 

bu görüş gününe onlarıda getir emi 

ha birde unutmadan 

arasıra gözü yaşlı ihtiyar anacığımı da ziyaret et 

iyi haberler ver ona üzülmesin 

vesselam 

Burada mektubuma son verirken 

katlandığın sıkıntılar için alnından 

çektiğin çileler için yanaklarından 

en önemlisi ise 

sevgin için sevdamız için 

sabahın ayazı sinmiş o karanfil uçuğu dudaklarından 

özlem hasret ve tutkuyla öperim', 'Canım karım sırdaşım Ayten  Dışarıda kuzey rüzgarları özgürlüğe kısrak gibi ılgıt ılgıt koşarken  içeride zaman çemberleri inadına kağnı gib...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/bes-yuz-on-dorduncu-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretim', 'hasretim-osman-ufuk-yildirim-4g6uw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hatırlamıyorum Babamı, yıllar olmuş öleli

Annem var çocuklarına hasret, ta ezelden çileli

Kardeşim var hoş sohbet, kardeşten de sevgili

Ayrıyım onlardan, yalnızım kendimi bildim bileli.

Allahım kavuştur beni! Nedir bu özlem

Hep yalnız kaldım. Yalnızlık büyük bir elem

Duygularım tükendi. Birgün biter diye sabretmekten,

Ağladım da yazdım bu şiiri kalan tek duygum Hasretten..

(1979)', 'Hatırlamıyorum Babamı, yıllar olmuş öleli Annem var çocuklarına hasret, ta ezelden çileli Kardeşim var hoş sohbet, kardeşten de sevgili Ayrı...', ARRAY['Türk Edebiyatı','Şiir','Osman Ufuk Yıldırım']::text[], 8.5, '{"poet":"Osman Ufuk Yıldırım","poet_slug":"osman-ufuk-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hasretim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cinali - Ciainn ile Kahin ''Kamba cini'' ve Alaaddin', 'cinali-ciainn-ile-kahin-kamba-cini-ve-alaaddin-akin-akca-q4gre', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sonradan duyulanlara göre; lambanın esas cini, gökyüzüne çekilmiş bir silindirmiş.

Ve oradan -aşağıdan- duyan (gerek)   olursa diye, uğurböcekliğini sürdürmüş. (akın akça)

-

İlginç bir bilokasyon olayı yaşandı:

bir tavuk gıdaklamıştı, sabahında bir şafağın -

nadir gülü adına, bir gül bahçesinin

- Ve akşamında, o tan ağartısının; 

bir horoz, ötüşmüş.

Birbiriyle örtüşmüş ruhlar:

suflesi olmayan, dekoru bol ama

(böyle bir yaratı ortamında)

*

Cin Ali,

asıl lamba cini-Alaaddin’le buluştuğunda; 

lambadan çıkan lamba cini,

sorar, bunlara -

 “Ciainn”e:

 “Kahin kim? ” 

“Sensin” dediler, Ciainn -

Ciainn, bu tavuk ve horoz,

 Alaaddin ve Cin Ali’ydi.

“Bir dilek tut, Ciainn! ”:

buyurdu, lambadan çıkan lamba cini:

“Üç hakkın var! ”

.. “Dedi, Kahin.” 

Ciainn, sıralamaya başladı:

“İlk dileğimdir, üç dileğin içinde barınan ilki için:

İlk dileğim kapsasın, tam yüz adet dileği.”

“İkinci dileğim: 

İki katıyla artacak ilk dileğimin, ikinci dileğim.”

“Asla lambaya döneme:

Ve işte, bu da üçüncü ve son dileğim.”

Cin, şaşırmıştı, 

ama bozuntuya da vermedi.

“Az yemek yiyip döneceğim, Ciainn! 

Bekleyin, geleceğim ve 

Dileklerinizi gerçekleştireceğim.”

O an, eşi, lambadan çıkacaktı:

yakaladı -lamba cinini lambanın- ensesinden

(fişek yaklaşımında, kendisi 

ve kediye asılır gibiydi, onun ense-tutuş-şekli)

ve ‘cini lambaya çekti yeniden:

cin, sorular sormuş olan.

Cinn Ali’yle 

Alaaddin dans ettiler bir süre -

Sevinç içinde.

(Bir zaferdi sanki bu; 

öte yandan,

istedikleri kadar dilek hakları vardı artık; 

fakat esas önemli kısmı.

Ve bir süre sonra, 

Ciainn’in, uykuları geldi:

uyuduklarında; 

Bir rüya gördüler, uykularında.

Ciainn, bir lambadan çıkıyordu.

Lambanın cini ise; 

gerçek hayatta, sorular sormuş olan; 

o ise, cevaplar Ciainn’e veriyordu -

tuttuğu dilekler adına:

Ama yine kedi gibi ensesinden -

(Lambanın lamba cini)

makus- kavranacaktı.

(Kendi gerçekliklerindeki gerçek

gerçekti Ciainn’in, demek!)

Bunu görüp uyanan,

içli sevindi Ciainn

Ve sarıldı kendisine,

Alaaddin ve şu Ali, birer cin.

-	-

açıklamalar:

“Lambanın lamba cini” yakıştırmasını, Alaaddin hikayesindeki lamba cini anlamında kullandım. “Ciainn”le karıştırılmaması için böyle kullandım. 

Yani formüle indirgediğimizde:

 Lambanın lamba cini=Kamba cini

Kamba cini=Ciainn. (But)   Fakat, Ciainn= akşam öten horozla sabah ciyaklayan tavuğun aşkı 

-

Özel türetilenler:

- Ciainn= Cin Ali ismiyle Alaaddin adından türetilenn. İkinci ''n'' harfi konaklanılan bir han anlamında= (ingilizcede)  inn

- Kamba cini= “Kahin lamba cini” tasvirindeki “ka” + ”mba” 

[ Labamba, lambada ya da lambda v.s. epsilon :)   ] Parantez içi, gırgırına.

- Ciainn: İki kişi var bu oluşumda ve teke indirgenerek, lamba cinini şaşırtıyorlar.

[ Birlikten kuvvet doar! Kuvvetten birlik! Birlikten kuvvet! İki elin (s)  fesi var! (Sadrazamda kalpak)   Bo$ olan bardağın dolu olana alternativitesi, alternatif-yokuş aşağı-vitesi.] Parantez içi espirisine.

Bilokasyon: çift bedenlenme

bilgi edinmek için bir web adres

http://www.gizemli.org/main/path_arastirma/content/bilokasyon.htm

-

 :))   Nerden buldum bilmiyorum bunu. Devam etti gitti. 

Güzel akşamlar…

25.09.2004 18:32', 'Sonradan duyulanlara göre; lambanın esas cini, gökyüzüne çekilmiş bir silindirmiş. Ve oradan -aşağıdan- duyan (gerek)   olursa diye, uğurböc...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":88,"source_url":"https://www.antoloji.com/cinali-ciainn-ile-kahin-kamba-cini-ve-alaaddin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim neyim olursun?', 'sen-benim-neyim-olursun-fevzi-gunenc-uf80e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ey benim sevgili Ef.Em

sevgili Ecem

can bilmecem

aydınlık gecem

tarihin karanlıklarına gömülmüş hüzünlü Cem…

İnanamıyorum

sonunda benim de 

yürekten sevgilim diyebileceğim

bir sevgilim oldu ha

ona sevgili ecem diye seslenebiliyorum ya

ne isterim daha…

Bir sevgilinin bir geceyi

nasıl aydınlattığına kanıtsın sen

temeli yüreğime atılmış

ucu göklere varan

anıtsın sen

yıllardır karşılığını bulamadığım bilmeceme

yanıtsın sen

En zayıf tarafın Cem oluşun

hani şu fatihin oğlu

kara yazısı babasınca yazılmış

yüreği tüm Osmanlıya bedel

sonu yağlı urgan

işi bir çingeneye ait kara bir el.

tarafından bitirilen

sensin Cem

Cem''sin sen…

Ama ben

akışını değiştireceğim tarihin

sen ey yüreğimin Sultan ‘Cem’i

yağlı urganlardan alıp

sıcacık bir tahta oturturacağım seni…

elinde erkinin al başlı asası olacağım

bırakma sıkı sıkı kavradığın o asayı

sana ak edecek odur dünyayı.

Yaşam kaynağım, asam

canım

o benim sana hayatta verip verebileceğim

en güzel armağanım…

Bak bir gemi yaptım senin için

yüreğimden kalkıp yüreğime giden bir gemi

mutluluğa yelken açan bir yelkenli yani

beni sana, seni bana taşıyacak

sen ey güneşten parlak resim

bundan sonra olur ancak

Sesin

sesim.

Seni ben hayatıma

Egemen seçtim ey Ef.Em

Yaşamıma ak seçtim

Seni ben mutluluğumun

paydasına ortak seçtim

Seni ben ey sevgili

Ucu bulunmayacak kadar uzun

Bir iplik yumak seçtim.

Özetle söylemek gerekirse sevgilim

Seni göğsüme uyumak seçtim.', 'Sen ey benim sevgili Ef.Em sevgili Ecem can bilmecem aydınlık gecem tarihin karanlıklarına gömülmüş hüzünlü Cem… İnanamıyorum sonunda benim ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sen-benim-neyim-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Konvoyları', 'kus-konvoylari-halil-pazarli-mav5y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oysa kuş konvoylarımız vardı eskiden,

alkış tutardık avare, bembeyaz bulutlara..

Kıpır kıpırdı içimizdeki yaşam sevinci,

misket oynardık her sokak cebimizde..

Ve akşam ezanıyla yerler mühürlenir,

beyaz bir melek inerdi sessizliğin sesiyle..

Çocuksu yorgunluğumuzu okşardı annem,

o yumuşacık, şefkatli ve tertemiz elleriyle..

Oysa kuş konvoylarımız vardı eskiden,

artık melekler inmiyor mahallemize..', 'Oysa kuş konvoylarımız vardı eskiden, alkış tutardık avare, bembeyaz bulutlara.. Kıpır kıpırdı içimizdeki yaşam sevinci, misket oynardık her...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kus-konvoylari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Yuvası 1', 'kus-yuvasi-1-halil-pazarli-nwmdk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ''kırmızı başlıklı kız'' masallarıyla büyümüşsün Kuş Yuvası

ünlü bir diplomat hastanesinde doğmuşsun özenle itinayla

ve etrafında koşuşmuş hemşireler doktorlar

kibar doğum yapmış sayın hanımefendi anan

teşhis sezeryan

yirmi derece oda sıcaklığı

eczanede satılan vitaminli mamalar

hazır markalı bezler dantelli sarıp sarmalar

pilli bebek oyuncaklar resimli dezektenfe biberonlar

(höllük nedir bilmezsin sen) 

son model yatak odalarında kurulmuşsun kundağına

yeni yetme müzik dinlemişsin kat kat set teypler eşliğinde

taşradan göçmüş az maaşlı al yazmalı gündelikçi bakıcından

(benimse şeytan kulağına kurşun dökülür gibi

yanık güneydoğu ninnisi akıyor yanağımdan) 

Ezan okunmamış kulağına mesela

su çekmemiş anan kara kışta kör kuyudan

sekiz kardeşin hiç olmamış senin

ucunda yarası kabuk tutmuş

kuru memelere saldıran

Bir tek ''kırmızı başlıklı kız'' masallarında

kocaman dişli kurt ısırırmış rüyanda seni

uyandırmışsın tatlı sıcacık uykularından

sözde koşup gelirmiş evin ahalisi

ve bütün gece ah vahlarla

-ateşi çıkmış mı acaba? diye sana ayrılırmış zaman

Dağları ise ilkokulda öğrenmişsindir kesin

duvara asılmış süslü kabartma haritalardan

Bana köylü çocuğu demişler

Atamın -milletin efendisi dediği

sen ise pikniğe gidermişsin okul aile birliğinin

fakir çocuklara düzenlediği lions usulü kokteyl piyangolardan

on beş tatillerde Uludağ sefası oteller kayaklar

yazları Kemer''de kamplar plajlar bikinili mayolar

(ben övendere desem gülecekler en iyisi mi susmak) 

Asla iki köy arası dört kilometre yol yürümemişsin hayatında

otomatik klimalı özel servislerin varmış senin

sabahları götürüp akşamları okuldan alan

Doğum günlerinde ışıltılı gülücükler dağıtırmışsın etrafına

kremalı çikolatalı muzlu yaş pastalar

ince uzun gül kokulu mumlar

gözlerini kapatıp üflemeli dilek tutmalar

Bense tarhana severdim daha çok

pişerse kara ocakta birde ev ekmeği

pırpır yanan kuzinenin yanında iki büklüm

büyük adam olacaktım okuyunca

kırk mumluk kör gözüm ders çalışmalar

Hani bir şairin dizelerindeki gibi

''sen ciğercinin kedisi ben sokak kedisi''

Daha bir çok şey var anlatacak

ama sanırım bu kadarı yeter

sonra bunu okuyanlar bana kızarlar

mülk sahibi zenginler devlet erkanı beyler

yada kara postallı vatansever askerler

Son sözüm şu sana Kuş Yuvası

chatte tanıştık senle sevdim seni yinede

(yüreğinde sanırım hala sevda gibi kırıntılar var) 

ve sanırım artık bende milenyum çocuğu oldum

eskide kaldı her şey

gençliğim idealim yaşadığım acılar

ve geçmişte küflenen sararmış fotoğraflar

Bir özlemim vardı son olarak

keşke Don Kişot olsaydım masallarda

yel değirmenlerine savaş açan

birde sevgilim olsaydı keşke

adı Dulcina', 'Sen ''kırmızı başlıklı kız'' masallarıyla büyümüşsün Kuş Yuvası ünlü bir diplomat hastanesinde doğmuşsun özenle itinayla ve etrafında koşuşmuş...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/kus-yuvasi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuş Yuvası 2', 'kus-yuvasi-2-halil-pazarli-dhwyc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimde kalmasın bari

aklıma gelmişken şunlarıda söylemeliyim sana

kaloriferli evlerde kıtır kıtır ekmek dilimleri kızarmaz Kuş Yuvası

poşetlenmiş az kalorili rejim eti-mekleri vardır sizin

sıcak sulu parlak musluklu gömme dolap mutfaklarınızda

(benimse elim yapışırdı tirşemiş iplerin ucundaki

delik kovaların buz tutmuş kenarlarına) 

Çoğu köyde elektrik yoktu

çamaşır yada kurutma makinalarımız yoktu

şofbenimiz yoktu mesela

kalaylı kazanlarda kaynardı sevişmelerin utangaç temizliği

ve berrak değildi bizim derelerde akan hırçın suların rengi

tahta mandalların gerginliğine dizilirdi soluk çamaşırlarımız

sekiz candı

kilim döşekti

beyaz kerpiç

ve acı kireçti duvarlarımız

Seninse ilkbaharların vardı

sevgililerin vardı dansların vardı

son model arabalı delikanlılar dönerdi etrafında

sonra eylül gelince okullar başlar

keyifle gülerdiniz kızlı erkekli kantinlerde

anı defterlerindeki koleksiyon ayrılmalara

(benimse ayağı kara lastik başı yazmalı

eli kınalı kızlar gezerdi ergenlik rüyalarımda) 

Daha ne diyeyim sana Kuş Yuvası

benim hiç akvaryumda yüzen kırmızı bir balığım olmadı

kedim köpeğim yada oyuncak bir ayım olmadı mesela

(kapıda havlayan çoban köpeğini saymazsan eğer) 

en evcil hayvanlar kuzuydu inekti eşekti benim için

o da bizim değil Himmet Ağa''nın ahırında

Renkli televizyonu ise askerde gördüm

(sakın kimseye söyleme çizgi film seyrediyorum hala bu yaşta) 

Senin anlayacağın yazın yaylalarda yatardık biz

dumanlı gurbet trenleri geçerdi ta uzaklarda

düdükleri yüreğimin baş köşesine otururdu

ve akardı zaman silik suratlı insanlar gibi

usanmazdım çufçuflu kara ve dar pencerelere el sallamakla

bu yerlerde harap bir köprüye umut bağlamak gibi bir şeydir aşk

yada içine akan bir gözyaşıdır gizli gizli

bitmez ki son duraklarda

Sonra kararırdı sisli dağların ufuklarla öpüşen tepeleri

bulutlara dayadığım merdivenle çıkardım parlayan yıldızlara

hasretleri yağmurlardan koparırdım

ellerim bu yüzden yıldız kokar hala

Ve şimdi artık kanadı kırık bir kelebeğim

ruhu militan ayağı demir

Neyse bu sana yazdığım son şeylerdi

bir daha şiir yazmayacağım sana

ama unutma şunu Kuş Yuvası

bir buhran gibi kalacaksın

ruhumun en hassas vuslatında

bir uyku gibi yaşayacaksın

gönlümün en çentik koğuşunda

ve kanırtılmış bir yara gibi kanayacaksın 

devamlı acıtarak

hüzünlü bir akşamın batan güneşi gibi

her şiir yazdığımda

(Bu şiirde adı geçen yer, şahıs ve olayların gerçekle hiç bir alakası yoktur. Şairin kendi dünyasında, hayali olarak kurgulanmıştır)', 'İçimde kalmasın bari aklıma gelmişken şunlarıda söylemeliyim sana kaloriferli evlerde kıtır kıtır ekmek dilimleri kızarmaz Kuş Yuvası poşetl...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/kus-yuvasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Ne..! !', 'bana-ne-hasan-huseyin-ozak-cmns4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben güçlü olmaktan bıktım artık

Her zaman dayanılan omuz olmaktan,

dert dinleyen, dert anlatılan,

her şeye çözüm bulmaktan

Acıları, özlemleri yüreğine gömen,

taş gibi, kaya gibi biri olmaktan..

Yüreğim insan yüreği,

taşdan değil, etten

sayılardan ve harften değil,

duygudan ve özlemden

Ben de insanım bana ne! 

Bir günlük de olsa,

ben de annemin dizlerine yatıp

ağlamak istiyorum...', 'Ben güçlü olmaktan bıktım artık Her zaman dayanılan omuz olmaktan, dert dinleyen, dert anlatılan, her şeye çözüm bulmaktan Acıları, özlemler...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Özak']::text[], 8.5, '{"poet":"Hasan Hüseyin Özak","poet_slug":"hasan-huseyin-ozak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bana-ne-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Yazmak Sanatmış', 'siir-yazmak-sanatmis-zubeyde-yilmaz-pumfg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kızar şimdi bana belki

Büyük üstatlar..

Şiir yazmak sanatmış

Banane...

İçinde ben olayım

İçinde sen ol

Göbeğinde cümle alem...

İnsan koksun buram buram

Vursun beni can evimden

Titretsin benliğimi

Kemiklerimde çınlasın dizelerin nağmeleri...

Kafiye olmasın,tutmasın heceler

Ölçüler olmasın,boğulmasın kelimeler...

Dem vursun gönlüme

Aksın kana kana içine 

bu bana yeter...

Sırtlasın omuzlarına duygularımı

Çeksin çıkarsın en mahrem umutları

Bir çöl ortasına

Bazen bir dağın dumanlı başına.

Limanlara sürüklesin beni

Tılsımlı aşk şarkılarında....

Göklerde gezdirsin kuşlara inat

Toprağa bulasın düşlerimi...

Özlemlerimi getirsin bana

Çoçuksu saflığında

Ellerimi uzattım tutmalı ellerimi...

Yürekten yüreğe,gönülden gönüle

kaldırmalı hazanı akmalı delice...

Şiir yazmak sanatmış

Banane...

İçinde ben olayım

İçinde sen ol

Göbeğinde cümle alem ve tüm evren

Olmasın kafiye,tutmasın heceler

Bizden olsun,bu bana yeter...

       

(24/09/2004      şair olmak...kim şair...şiir yazan mı?  kalıplı,ölçülü,yoksa biz kokan dizelerde akan mı?)   

(Not:büyükler kızar demiştim bşladılar...derdim büyük şairlere ya da tarihe ya da aruz veznine ölçüye zıtlık değil...ŞİİR BİR DUYGU AKIMIYSA.....)', 'Kızar şimdi bana belki Büyük üstatlar.. Şiir yazmak sanatmış Banane... İçinde ben olayım İçinde sen ol Göbeğinde cümle alem... İnsan koksun ...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/siir-yazmak-sanatmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Milli Tencere', 'milli-tencere-halil-pazarli-qu61j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir çay kaşığı bana

bir çay kaşığı sana

bir çay kaşığı ona

Bir çay kaşığı bize

bir çay kaşığı size

bir çay kaşığı onlara

Haaydaaa

ulan bu kepçe kime

hadi gelde küfretme', 'Bir çay kaşığı bana bir çay kaşığı sana bir çay kaşığı ona Bir çay kaşığı bize bir çay kaşığı size bir çay kaşığı onlara Haaydaaa ulan bu ke...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/milli-tencere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuştan Katil', 'dogustan-katil-halil-pazarli-syj2r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kader kelepçe

eller kocaman

önemli bu

altını çizmek gerekiyor

Lime lime bütün vakitler

(bu da önemli) 

anılar can çekişiyor

Şiirse yaşadığın

yamalı tutku

yarası çok kanamıyor

Ve insan

doğuştan katil

hep zaman öldürüyor', 'Kader kelepçe eller kocaman önemli bu altını çizmek gerekiyor Lime lime bütün vakitler (bu da önemli)  anılar can çekişiyor Şiirse yaşadığın...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dogustan-katil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masal', 'masal-nurten-kederoglu-phu86', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masal

Bir masal anlatayimmi gecen yillardan istermisin

Bir eski sarkida olabilir okusam beni dinlermisin

Gecsede Yillar Sönmeyecek atesi askimizin canim

Gecilmez seldir önüne duygularim seninle biricigim 

Yildizlar boldu ay parlakti o gece yine gökyüzünde

Yakamozlar göz kirpiyorlardi ya iste bize denizde

Ben  unutmadimki hatirliyorum birtanem her seyi 

Bende senden ögrenmistim iste o gece sevmeyi

siir_ce', 'Masal Bir masal anlatayimmi gecen yillardan istermisin Bir eski sarkida olabilir okusam beni dinlermisin Gecsede Yillar Sönmeyecek atesi ask...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/masal-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* Var Saydım Hayatı*', 'var-saydim-hayati-nevin-kurular-92jpr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Var saydım hayatı benimdir diye

Varsaydığım Alem beni yok saydı

Gıpta ettim incir çekirdeğine

Keşke!  yerim onun kadar olsaydı.

Güneşi beklerken,  gizlendi hare

Zorlar kader oldu,  kolay biçare

Ayaklar nasırlı,  el pare pare

Mecalsiz dizlerim, dağı yol saydı

Karalar bağladım,  al güldü geçti

Çiçeğe yaş döktüm, dal suyun içti

Yaşam serap mıydı, koca bir hiçti

Üç beş  kıta şiir  olup    kalsaydı.', 'Var saydım hayatı benimdir diye Varsaydığım Alem beni yok saydı Gıpta ettim incir çekirdeğine Keşke!  yerim onun kadar olsaydı. Güneşi bekle...', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/var-saydim-hayati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben.. İçinde Sen', 'ben-i-cinde-sen-nevin-kurular-cmafz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Canım yâr,

Gel canı yar! 

Gör içinde

İki can var.

Ben fani

Sen! baki...', 'Canım yâr, Gel canı yar!  Gör içinde İki can var. Ben fani Sen! baki......', ARRAY['Türk Edebiyatı','Şiir','Nevin Kurular']::text[], 8.5, '{"poet":"Nevin Kurular","poet_slug":"nevin-kurular","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ben-icinde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-harun-kuscu-k6krd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yağmurlu bir günde gördüm seni ben

Tüm varlığımla sevdim seni ben

Bölük bölük yüreğime ördüm seni ben

O zamanlar başıma taçmışsın gülüm

Kurşun gibi gelip geçtin hemde zamansız

gönül ocağım yandı ama dumansız

Hepsini sineme çektim amansız

Yüreğime daha konmadan kaçmışsın gülüm

Seni dünyalara sığdıramazken ben

Sana karşı duygulsarımı durduramazken ben

Şimdi yabancı kollarda mutlumusun? sen

Yazık! hoyrat bahçelerde açmışsın gülüm', 'Yağmurlu bir günde gördüm seni ben Tüm varlığımla sevdim seni ben Bölük bölük yüreğime ördüm seni ben O zamanlar başıma taçmışsın gülüm Kurş...', ARRAY['Türk Edebiyatı','Şiir','Harun Kuşcu']::text[], 8.5, '{"poet":"Harun Kuşcu","poet_slug":"harun-kuscu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulum-97-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Demeli ?', 'ne-demeli-ali-aldemir-dvmso', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Okşadın mı hiç gece yarısında

Böcül böcül bakarak yanına sokulan,

Soğuk ayazında şubatın ıslanmış

Bir sokak köpeğini? 

Isıttın mı hiç yağarken sulu sepken karlar

Uyuşmuş soğuktan buza kesen ellerini

Üşüyen ılık nefesinle.

Oynadın mı hiç

Kartopu kardan adamla

Çocuklar gibi farkında olmayarak üşüdüğünün? 

Sonra düzeltip altını kör bir bıçakla

Yeni aldığın ayakkabının,

Hiç sokaklarda kaydın mı? 

Ya da paylaştın mı parçalayarak

Ufak ufak üşümüş parmaklarınla,

Yağmurdan ıslanan çatıdaki kuşlarla ekmeğini? 

Ve içten öylesine yalansız

Söyleyemediklerini sevdiğine,

Her bakışında sana gülümseyen

Yeni açmış saksıda bir küçük ıtıra,

Begonyaya........

Oldu mu ki ondan öncesi 

Var mı ki ölümden ötesi diyebildin mi? 

Anlattın mı hiç sevdanı? 

Kaç bahar geçti üstünden

Zamanı mı durup dururken habersiz

Alıp başını gitmeye kalkmanın,

Isınmış değil hâla yokluğunda üşüyen odam

Ellerim sonra başını koyduğun yastığım.

Zamansız sayısız baharlar bekledim dönmeni,

Bu gidişine ne demeli? 

Açar mı sanırsın süzülüp mavilikte

Vurur mu boşlukta kanat,

Uçar mı sevinç içinde kırlangıçlar? 

Ya serçeler söyler mi sanırsın

Sevda şarkılarını

Serçelere ne demeli? 

Ya özlemle bekleyen tohumlar, taze filizler

Ne kadar dayanır susuzluğa? 

Toprağa ne demeli? 

Yağar mı sanıyorsun sen gidince yağmurlar? 

Ya sokaklara,ağaçlara,kaldırımlara

Sonra bu kente, ya gecelere,

Gecelere ne demeli yokluğunda? 

Ya son deyip uzun uzun kanatırcasına

Alıp da götüren başımdan aklımı,

Bu öpüşüne ne demeli? 

Nereye koyarım senden sonra

Kanattığın dudaklarımı

Dudaklarıma ne demeli? 

Yeter sanırdım oysa herşeye gücüm,

Sus derim susar konuşmaz dilim

Neyin nesi peki bu yaşlar dersen,

Yakıştıramadığımdan değil hani

Utanıp da erkekliğe,

Kolay mı? 

...Dağ gibi 

.... Deniz gibi 

......Gözüm gibi işte öyle........

Gitmek isterken sevdam.....

Söz geçmiyor gözlerime

...Gözlerime ne demeli?', 'Okşadın mı hiç gece yarısında Böcül böcül bakarak yanına sokulan, Soğuk ayazında şubatın ıslanmış Bir sokak köpeğini?  Isıttın mı hiç yağark...', ARRAY['Türk Edebiyatı','Şiir','Ali Aldemir']::text[], 8.5, '{"poet":"Ali Aldemir","poet_slug":"ali-aldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/ne-demeli-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zavallı Akıl', 'zavalli-akil-talip-kaplan-ftaph', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanız der göğsümüzü gereriz

En şerefli bizleriz deriz

Oysa,

Hepimiz birer hiç değil miyiz

Şeref midir etimizi sermaye etmek

Marifet midir haram yemek

Gurur mudur fayans dizmek

Ne verir fani dünyada gülmek

Hiç orospu bir tavuğa rastladınız mı

Avare avare gezen karınca var mı

Arı, petekler dolusu bala muhtaç mı

Uçkuruna düşkün hayvan tanıdınız mı

Şeref düşünebilme yeteneği değildir

Mesele bu yeteneği kullanabilmektir

Öyle bir unsurdur ki akıl,

Bazen en yücedir bazen de en alçak

Bazen yüceleştirir bazen de yereltir

(28 Nisan 1993)', 'İnsanız der göğsümüzü gereriz En şerefli bizleriz deriz Oysa, Hepimiz birer hiç değil miyiz Şeref midir etimizi sermaye etmek Marifet midir ...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zavalli-akil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Öldüren Yaşatan', 'gozlerin-olduren-yasatan-berna-ocakcioglu-468lf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En küçük bakışanda bir şey var sana hapseden beni

Bir şey var ki dokunamayacağım kadar bana yakın

Demir kafeste  bile olsa koşturur sana yüreğimi

Güneş bile açtırmamıştır böyle ilk çiçeklerini baharın

Yokluğunda bir şey var, içime gömen beni

Aldığım her nefeste öldürüyor uzaklığın.

Yokluğun parmaklıklar ardına hapsediyor yüreğimi

Hücresi karanlık olmamıştır bu kadar en ağır mahkumların.

Adını koyamadım nedir bu sende olan.

Bu her nefeste öldüren, bu yaşatan.

Bilip anladığım tek şey; 

Gizli bir çiçekmiş yüreğim

Bir tek gözlerinin ışığında açan.

Kimsede yok güneşte bile böyle beceri

Bir saniyede açtırsın tüm çiçekleri...

Öldürmekse beni isteğin eğer,

Kaçır gözlerini ışıksız kalayım yeter.', 'En küçük bakışanda bir şey var sana hapseden beni Bir şey var ki dokunamayacağım kadar bana yakın Demir kafeste  bile olsa koşturur sana yür...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-olduren-yasatan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dert Yüklenmiş Yar Düşün', 'dert-yuklenmis-yar-dusun-omer-karakas-8u7sl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dert yüklenmiş yar düşün, yanakları giryeli,

Islatmış, gözlerinden süzülen iki hüzün; 

Dert yüklenmiş yar düşün, gürbet ele düşeli,

Suratı binbir parça, durulmuş sanki güzün.

Dert yüklenmiş yar düşün, kirpikleri sürmeli,

Alev alev saçları, dağılmış omuzuna,

Gamzesi yetmez gibi gül açmış yanağına,

Ah! Ayrılırken buse kondurmadın, kaybana.

Dert yüklenmiş yar düşün, gözü zümrüt yeşili,

Sanki huri parçası, boyu semaya değer,

Hele ten kokusu, misk... kokusuna değer,

Ya! Rab al canımızı, kavuşamazsak eğer.

Dert yüklenmiş yar düşün, sevişi benden deli,

Name atmış geçende, özlemini işlediği,

Bir kaç damla göz yaşı, gözünden akıttığı,

Bir kaç da acı koymuş, hüzününden sağdığı.

Dert yüklenmiş yar düşün, gözünde sevda mili,

Gürbet elde harabım, yar sılada perişan,

Yüreğimiz narada; yok, imdadımıza koşan,

Açtım elim Allah''a; niyazı eyle ihsan.', 'Dert yüklenmiş yar düşün, yanakları giryeli, Islatmış, gözlerinden süzülen iki hüzün;  Dert yüklenmiş yar düşün, gürbet ele düşeli, Suratı b...', ARRAY['Türk Edebiyatı','Şiir','Ömer Karakaş']::text[], 8.5, '{"poet":"Ömer Karakaş","poet_slug":"omer-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dert-yuklenmis-yar-dusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Amentüsü', 'yagmur-amentusu-yasin-mortas-n1kyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu yağmur hıçkırığı nisanda

simyasız bir yüzle direniyorum

müteessir gül dağarcığı

patlıyor ümranlara

bu sağnaktan geçtiğim her demde

berrak bir avuç

ve amentü ile gönlüm

yüzüme yaslanır

ıslanır ruhumda

gönlüm

gözyaşımın amin cenahında

mütevazi bir ırmak daha oluşuyor

kalbimin minberine sığınan

münzevi duyguların

mutlu bir yağmur olduğu denizlerde

bahar''95', 'bu yağmur hıçkırığı nisanda simyasız bir yüzle direniyorum müteessir gül dağarcığı patlıyor ümranlara bu sağnaktan geçtiğim her demde berrak...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmur-amentusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dev', 'dev-i-smet-barlioglu-klgct', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukken elimden kaçırdığım renkli balonlar gibisin

gözyaşlarıma sığınıyorum sana ulaşamayınca,

otobüsler gibisin,

trenler gibisin,

vapurlar gibisin,

uçaklar gibisin vaktinde kavuşamadığım,

Kaf Dağı ‘ndan gelip bir dev gibi dikilmişsin karşıma

savaşamadığım.

Nereden almışsın bu büyülü gücü, bilemiyorum,

kölelere çevirmişsin beni varlığınla,

değip dokunmadan çekiyorsun,

çekmeden sürüklüyorsun ardın sıra

baş edilmez bir güneş gibi yörüngende,

bedenim, canım, ruhum, yüreğim, gönlüm, her şeyim

çevrende.

Körpe bir ömür harcadım sana ulaşmak için,

bedenimi harcadım,

canımı, ruhumu, yüreğimi,

etimi, kemiğimi,

huzurumu, özgürlüğümü,

hücre hücre, lif lif, kemik kemik, ilik ilik.

Sen hala uzaktasın,

ateş bile yakmaz bazen insanı,

sen yakmaktasın.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 7-8/100)', 'Çocukken elimden kaçırdığım renkli balonlar gibisin gözyaşlarıma sığınıyorum sana ulaşamayınca, otobüsler gibisin, trenler gibisin, vapurlar...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/dev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anacağım', 'anacagim-i-smet-barlioglu-78o9m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karasevdana alıştı yüreğim,

azaplarına alıştı,

çektirdiğin acılara, çilelere,

gözümde devleşen özlemine,

öfkene, hışmına, acımasızlığına alıştı yüreğim,

güzele alışan körpeler gibi,

ışığa, suya alışan çiçekler gibi,

kovanına alışan arı, yuvasına alışan kuş gibi,

bir büyük karasevda içinde çırpınır durur yüreğim

sarhoş gibi.

Kadeh kadeh içiyorum sevdanı geceler boyu,

gündüzler boyu,

günler, aylar, yıllar boyu,

bir bitmeye yüz tutmuş ömür boyu.

Ne ben doyup gidiyorum, ne kadehim boşalıyor,

ne bileceksin ki; 

bir sensiz dünyada ancak böyle

yaşanıyor.

Aslında iki elim iki taş altında,

eski tadlar kalmamış tadında ömrümün,

anılarımı yeniden yaşayıp durmak işim-gücüm,

yeniden çekmek çekilmiş acıları,

düşmek yeniden içine eski hüzünlerin,

çekmek çekebildiğimce eski ayrılıkları,

karasevdanın, yaralı yüreğimin üstünde gezindikçe

ayakları.

Sanma ki bir dur-durağı olacak acılarımın,

sanma ki bitecek acılarım bir yerde, bir yerlerde,

sanma ki gün gelip kurtulacağım.

Ölsem, toz-toprak olsam günlerden bir gün,

seni taşımla, toprağımla

arayacağım.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 9-10/100)', 'Karasevdana alıştı yüreğim, azaplarına alıştı, çektirdiğin acılara, çilelere, gözümde devleşen özlemine, öfkene, hışmına, acımasızlığına alı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/anacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-i-smet-barlioglu-0o8v6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gel bugün bir yana bırakalım Kerem ‘le Aslı ‘yı,

ateşle, dumanla, külle uğraşmayalım,

serpelim sevimsiz ayrılıkları dağa, bayıra,

kucaklaşalım.

Sevdiler, sevildiler dedirtelim

eloğullarına, elkızlarına.

Dört yönüne dört gökkuşağı dikelim gökyüzünün,

yağsın diye başımıza renklerin yağmuru,

senin bakışların ve benim gözlerimin nuru

parıldasın güneş yerine

ve dünyaya mutluluk versin,

geçirip gidelim mi bir günü barışlar içinde,

ne dersin? 

Yar olsan yakın olur uzaklar bana,

kalmaz elimi attığım dallar elimde,

rahmetler yağar başımdan aşağı,

olmazlar olurlanır.

Sen bana bir yar olsan var ya,

zerrelerim gururlanır.

Gel gör ki; ben nasıl da bir aldatıyorum kendimi,

nasıl bir boşa umutlar bağlıyorum

elimi attığım dallar nasıl kırılıp kalırken elimde,

nasıl bir karlar yağarken güvendiğim dağlara.

Umuttan başka nedir ki yoksulun ekmeği? 

Elden ne gelir? 

Yüreğimin sevdanla birlikte kesilmiş

göbeği.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 11-12/100)', 'Gel bugün bir yana bırakalım Kerem ‘le Aslı ‘yı, ateşle, dumanla, külle uğraşmayalım, serpelim sevimsiz ayrılıkları dağa, bayıra, kucaklaşal...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/umut-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açmasam', 'acmasam-i-smet-barlioglu-npgxg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anılardan yuva yaptım yüreğime, kuşlar gibi,

rüzgar eser, anılarım canlanır,

yağmur yağar, canlanır,

sabah olur, güneş doğar, tırmanır tepelere,

uzanır gider ikindi gölgeleri,

akşamlar iner çevreme karanlık örtülerce,

geceler gelir, geceler uzanır, geceler biter,

habire canlanır durur anılarım,

kimsesiz bir kuş gibi çekilirim yuvama,

ağlarım.

Anılar var, mızrak misali saplanır yüreğime,

derinlere işler durur yaraları,

yeniden damlar kanım yaralarımdan.

Anılar var öfke gibi, hışım gibi, karabasan gibi,

bir yaptığını bin kere yapan anılar,

hangisine tek kere dokunacak olsam

yaralar.

Kapalı kutular gibidir benim anılarım,

hengisini açsam serapa sen çıkıyorsun karşıma,

ya boynun bükük, gözlerin yaşlı olarak,

ya gülümseyerek büyülercesine,

ya dargın bakışlarla bakarak yeşil yapraklar altında,

veya arkanı dönüp giderek sessizce,

karşıma hep sen çıkıyorsun

hangi kutuyu açsam.

Kalkıp sana ihanet edeceğimden korkuyorum

açmasam.

(Hikmet BARLIOĞLU (1933-2003)   ''nun,

KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 13-14/100)', 'Anılardan yuva yaptım yüreğime, kuşlar gibi, rüzgar eser, anılarım canlanır, yağmur yağar, canlanır, sabah olur, güneş doğar, tırmanır tepel...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/acmasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Balta', 'balta-ahmet-hani-n8ub8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sınacaqsan öleceksen

ağacları kesen balta

gücümüzü göreceksen

ağacları kesen balta.

sınıq saza tel olarıq

el bir olub el olarıq

dağdan gelen sel olarıq

ağacları kesen balta.

qaranlığı ağ eylerik

ölü eli sağ eylerik

quru çölü bağ eylerik

ağacları kesen balta.

dağ üstünde hay salarıq

gecelere ay salarıq

susuz yere çay salarıq

ağacları kesen balta.

26  september   2004', 'sınacaqsan öleceksen ağacları kesen balta gücümüzü göreceksen ağacları kesen balta. sınıq saza tel olarıq el bir olub el olarıq dağdan gelen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/balta-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kervan', 'kervan-i-smet-barlioglu-jrs5x', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her saniye sana doğru geliyorum kervan kervan,

yükler dolusu çilelerim,

kırbalar dolusu acılarım,

heybeler dolusu ayrılıklarım,

hurçlar dolusu özlemlerim

ve bir karasevdaya esir olmuş yüreğiyle

kendim.

Yollarımı kader kesmiş uğru yerine,

rahmet dolu kuyularımı tarumar etmiş nasip,

gölgeliklerimi yakıp bırakmış karasevda,

bana bir tek sevgiliyi bırakmışlar

serapta.

Başımda esen bir çöl rüzgarıdır

söyler durur senin şarkılarını,

rahmete el-avuç açar kumlar, yaralı yüreğim gibi,

ne çevremde bir yağmurun himmeti,

ne başımda gölgesi bir yaprağın,

neden bana karşı bu kadar acelesi var, bilmiyorum,

toprağın.

Sevdam nasıl da çoğalıyor günlerim azaldıkça,

yolum nasıl da bir uzanıyor,

seraplaşmış hayalin nasıl da bir uzaklaşıyor,

yaklaştıkça nasıl da bir kaçıyor,

yine mi kar yağacak umutlarıma çöllerin ortasında,

uzandığım dallar yine mi elimde kalacak? 

Hayallerimden öte neyim kaldı ki

kırılacak.

(KANAMA YÜREĞİM isimli Serbest Şiirler ''inden > 15-16/100)', 'Her saniye sana doğru geliyorum kervan kervan, yükler dolusu çilelerim, kırbalar dolusu acılarım, heybeler dolusu ayrılıklarım, hurçlar dolu...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kervan-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Nehir...', 'nehir-naime-erlacin-r2bcr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“kadından ve nehirden ancak aşkla geçilir”* 

şiirlerde guslettim dün gece

şarkılarda raks 

ruhumdu bedeninde köpüren

sevgimin aksi gözlerinde

o şarkılar ki ah! 

o şiirler 

bizim değildiler

çoktular 

tutsaktılar

nağmelerde yakalandım suçüstü

kızıl bir sevda mülkiyetinde

tarifi olmalı bu heyecanın

geçişini izledim öylece benden

mum adaklı yangındım kara geceye

adı ''aşk'' bir nehir akarken içimden

dün gece asırlar bağışladım sana

bir öpüş kadar hafiftiler

(*)  Abdülkadir Budak

(26 Eylül 2004)', '“kadından ve nehirden ancak aşkla geçilir”*  şiirlerde guslettim dün gece şarkılarda raks  ruhumdu bedeninde köpüren sevgimin aksi gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nehir-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Heyif', 'heyif-ahmet-hani-uahhw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yorulmuşam felekden

ah çekmekden gerekden

bir bir bizi ayırdı

heyif dedim ürekden.', 'yorulmuşam felekden ah çekmekden gerekden bir bir bizi ayırdı heyif dedim ürekden....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/heyif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Olsun Gönlünde', 'gunesin-olsun-gonlunde-hatice-kuzu-0kfmo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Terk ederken güneş gökyüzünü, 

Son tangosunu yapıyordu 

Işıkla ay… 

Bir şarkı çalıyordu gramofonda 

Başkaları için anlam ifade etmeyen bir ezgi belki. 

Ve senin gözlerin hüzünlü,senin gözlerin nemli 

Dudaklarında dökülmemiş sözcüklerin izi 

Bakışında güneşin sıcaklığı. 

Boynunda yıldızlardan bir kolye geceden hediye 

Aklımda kalan bunlardı gidişinden sadece… 

Sıradan bir gündü 

Bakıverdi bulutlar gittiğinde öylesine, 

Öylesine boşandı sağanaklar yeryüzüne. 

Şimdi yeryüzü seninle, gökyüzü yapayalnız, 

Özlüyor kolyendeki yıldızı ay ışığı 

Gece özledi seni,gece özledi sesini 

Bir de ben özledim,diyemedim… 

Öylece kaldım, kalakaldım gecenin karanlığında 

Senin yüreğinde güneş,benimkinde ayaz 

Isınır sevdan yanan duygularımla. 

Bense üşürüm fırtınalardan,tipilerden 

Dokunma çek ellerini,içimde soğuktan ölen biri var 

Ölünün yüreği sıcak,yüzü ayaz. 

Bakışının izi kaldı yüzümde.. 

Yakarım geceleri şiirlerimi, 

Isıtsınlar diye hislerimi 

Az gelir bu yangınlar, bu küller. 

An gelir başkaldırırım dokunmalarına, 

An gelir özlerim gitmelerini. 

Korkarım sensizliğimi haykırmaya 

Susarım…. 

Beni düşünme sen, 

Bakarım başımın çaresine 

Yeter ki, 

Güneş olsun gönlümde, 

İçinden kopar bir tel ışık 

Yolla penceremin pervazına. 

Darmadağın bir bedenden 

Havalansın gökyüzüne yüreğim. 

Kanat çırpsın gecenin içinde 

Çırpınan umutlarım. 

Bu yalnızlık, bu yalnızlık bitsin artık 

Isıt dünyamı gönlü güneşli kız, 

Kalk bize gidelim sessizce 

Sabahlara kadar dans edelim ay ışığında.. 

Maviye çalan gözlerinde boğulayım, 

Yalan da olsa merhaban, 

Gerçek olsun yeter ki vedan… 

Güneşin olsun gönlünde, 

İçinden kopar bir tel ışık, 

Yolla üzerime,yaksın beni 

Savrulayım küllerimin ağırlığınca 

Sana doğru...... 

26.09.2004', 'Terk ederken güneş gökyüzünü,  Son tangosunu yapıyordu  Işıkla ay…  Bir şarkı çalıyordu gramofonda  Başkaları için anlam ifade etmeyen bir e...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kuzu']::text[], 8.5, '{"poet":"Hatice Kuzu","poet_slug":"hatice-kuzu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/gunesin-olsun-gonlunde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sildim Eski Gözlerimi', 'sildim-eski-gozlerimi-fevzi-gunenc-0fry8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sildim eski gözlerimi

gözlerimle birlikte yaşlarını da

yer açabilmek için yenilerine...

Güç topladım bin yıldır

sanırım zamanıdır

             sözü söylemenin

yeniden yanmanın zamanıdır.

Ne acılar çekmişim ömrümce

acıların koruganıyım artık

kanatmak için yeniden tenimi

yeni bir yolcuya gereğim var.

Bedenim kırbaçlandı yüreğimle birlikte

tenim de 

ilk acıda

yirmi yıllık uzun yolun

hem de daha ilk başında.

ikinci yanışım uzun sürmedi neyse ki

bir Nürnberg akşamında başlayan kar

beni ancak ertesi 

öğlene dek üşütebildi.

Merhemler sürüldü üçüncüde 

-iki yıl-

           tenime

rumumun yanması oldu bunun bedeli de.

Bir şair kurtarabilirdi ancak bir şairi

kurtardı o da dördüncü  buluşmamda beni

yangınımı büyütmekten özge bir işe yaramadı

yazık şiiri yanıyordu ama yanmıyordu teni.

En büyük vurgunu beşincide yedim

eli baltalı bir çingenenin

ateş dili yakıyordu bu kez beynimi

üç günde kurtarabildim kendimi…

Şairime döndüm

taze bir umutla.

Oydu beni en iyi anlayan

en iyi seven

olmadı yine de

bitirdi beni altıncı birlikteliğim 

leyl

gece

aşkımın dişi örümceği bile olamadı

öldü böylece

Gizini söyleyeyim

                          eğil

işin aslı

bir şairin ateşinde yanmak

kolay değil.

Artık uzak durmalıydım ateşlerden

fırtınalardan sellerden/yanardağ 

kükremelerinden uzak dumalıydım...

Ama şairim

                dumamam

yanmaya alışmımış yüreğim

                                       beynim

                                              tenim

gel, dilersen yedinci ateşim ol benim.

Biliyorum

ateşlerde yunmuş birisin

sen de

yakmazsın o yüzden beni 

neyse ki biliyorum bunu

o yüzden uzattım 

giyotinine boynumu.

Biliyorum yanmak zamanıdır şimdi

biliyorum bulutlanma yağmurlanma zamanıdır

uzun, korumasız kirpiklerini 

örten iri ela gözlerine

bir kez daha mil çekilme zamanıdır şair

sil eski gözlerini

                       göz yaşlarını yine

yer açılsın diye şair

yenilerine!', 'Sildim eski gözlerimi gözlerimle birlikte yaşlarını da yer açabilmek için yenilerine... Güç topladım bin yıldır sanırım zamanıdır           ...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Günenç']::text[], 8.5, '{"poet":"Fevzi Günenç","poet_slug":"fevzi-gunenc","theme":"Türk Şiiri","is_hero":false,"total_lines":72,"source_url":"https://www.antoloji.com/sildim-eski-gozlerimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kelebek', 'kelebek-yusuf-ter-sor9k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'KELEBEK

Sana  varacak  olsaydım

Ben bir kelebek olurdum

Kanatlanıp da gelseydim

Ben bir kelebek olurdum

Bana yeter derdim desem

Sevdiğimden sana gelsem

Muradıma senle ersem

Ben bir kelebek olurdum

Bu sevdadan bir geçseydim

Derdimi sana açsaydım

Kanadım kırık uçsaydım

Ben bir kelebek olurdum

Olsaydın benim yerimde

Öz kalmadı şu serimde

Uçardı Yusuf Ter’imde

Ben bir kelebek olurdum

Dağlar Şahit Aşkıma adlı kitabımdan bir şiir / 2004

http://yusufter.tripod.com', 'KELEBEK Sana  varacak  olsaydım Ben bir kelebek olurdum Kanatlanıp da gelseydim Ben bir kelebek olurdum Bana yeter derdim desem Sevdiğimden ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kelebek-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül bence', 'gul-bence-halil-pazarli-ustp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu dünyada güle aşık bir benim

dağlar benim, kuşlar benim, gök benim

bunca yıldır şiir yazdım yol gezdim

senin gibi candan gülen görmedim

Güneş doğup dalda kuşlar ötünce

soyunupta çiçek suya girince

hasret kalbe sevda başa düşünce

sen hep böyle ömür boyu gül bence

Ey endamı, zarafeti şahanem

ruhu ekber, güzelliği bahanem

dünya malı neyleyeyim gül bende

hiç kıskanma Allah vermiş be annem

Gece olup kurtlar kuşlar göçünce

soyunupta yâr koynuna girince

hasret kalbe sevda başa düşünce

sen hep böyle ömür boyu gül bence', 'Bu dünyada güle aşık bir benim dağlar benim, kuşlar benim, gök benim bunca yıldır şiir yazdım yol gezdim senin gibi candan gülen görmedim Gü...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gul-bence-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü Türküleri', 'gokyuzu-turkuleri-halil-pazarli-8m0b6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir yanda zehir zıkkım bir yanda acı kahve

Tokat''ta yaşıyorsam hatır kırk yıllık diye

şu Kışla bağlarının gökyüzü türküsüydü

bülbülün güle aşkı yetmezken nefesine

Ruhlarla sevişmeyi aşkı burda öğrendim

bakır dövüp tavında Sulusokağa serdim

gurbeti bulutlardan hasreti yanaklardan

çemeni bahçesinde koca bir ömür verdim', 'Bir yanda zehir zıkkım bir yanda acı kahve Tokat''ta yaşıyorsam hatır kırk yıllık diye şu Kışla bağlarının gökyüzü türküsüydü bülbülün güle a...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gokyuzu-turkuleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '7''ye 7 Var', '7-ye-7-var-erkan-yanarates-n2sk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine bir yaz gecesi feleğin işine bak,

Elim kalem tutmak ister yediye yedi var.

Yedinci yıla yedi gün kalmış takvime bak,

Tevafuk işte, saat de yediye yedi var.

Kayaş’ta esmer bir kız varmış adı Emine,

Güzel mi, hoş mu dedim sordunuz mu birine,

Bildiğin gibi dediler gerek yok yemine,

Kalkın gidelim dedim tam yediye yedi var.

Gözleri mahmur bir kara kız çıktı karşıma,

Ağrıdı, sızladı bir şeyler oldu başıma,

Dedim ortak olur musun soframda aşıma,

Söz almıştım haftaya, gün yediye yedi var.

Bazen çok güzel günler gördük, bazen sıradan,

Günler, aylar derken yıllar da geçmiş aradan,

Çok şükür bu güne erdirdi bizi yaradan,

Baktım ki geçen zamana yediye yedi var.

Haftaya yıldönümü Allah izin verirse,

Sılama döneceğim teskerem bir gelirse,

Uçan takvim yaprakları yüz yıl da devirse,

Hep kalbimde yaşayacak “yediye yedi var”.

On üç uğursuz derler, bana mutluluk verir,

Temmuz sıcaktır ama ayva, kiraz yetirir,

İki bin üç yılı oğlumdan selam getirir,

Son üç satır başlarında yediye yedi var.

(13 Temmuz 2003, Kıbrıs)', 'Yine bir yaz gecesi feleğin işine bak, Elim kalem tutmak ister yediye yedi var. Yedinci yıla yedi gün kalmış takvime bak, Tevafuk işte, saat...', ARRAY['Türk Edebiyatı','Şiir','Erkan Yanarateş']::text[], 8.5, '{"poet":"Erkan Yanarateş","poet_slug":"erkan-yanarates","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/7-ye-7-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaşın Çatanda (Azeri)', 'gasin-catanda-azeri-halil-pazarli-o85n3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Men seni özümden çoktur sevirem

çağırsan gapına gulun gelirem

o közel çehrene gaşın çatanda

üreğimin narına yanabilirem

Çapah közüm açmadan 

seher sözüm gaçmadan

bahar demi çemende 

ganatlanıp uçmadan

gel mene gel közgülüm 

seveceğim söz gülüm

yandı bitti kül oldu 

aşıh düşende könlüm

Ey menim tahtıma gızıl çiçeğim

garanlık bahtıma ışıh böceğim

o közel çehrene gaşın çatanda

yemeden içmeden gahır çekerim

Çapah közüm açmadan

seher sözüm gaçmadan

bahar demi çemende

ganatlanıp uçmadan

gel mene gel közgülüm

seveceğim söz gülüm

yandı bitti kül oldu

aşıh düşende könlüm', 'Men seni özümden çoktur sevirem çağırsan gapına gulun gelirem o közel çehrene gaşın çatanda üreğimin narına yanabilirem Çapah közüm açmadan ...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gasin-catanda-azeri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-ahmet-hani-um1u9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'torpaqda

kökümüz yox idi

yoxsa

qış bahane idi.', 'torpaqda kökümüz yox idi yoxsa qış bahane idi....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bahane-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümden Ötede Yine Sen Varsın', 'olumden-otede-yine-sen-varsin-vahittin-bozgeyik-b9yft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yokluğunu çam ağaçları giderecek gözlerinin

Sensizliği içeceğim sabahçı kahvelerinde

Yudum yudum! 

Ağlamayacağım gidiyorsun diye 

Ağlamak ne ki? 

Anılar yine ılıklaşacak yanaklarımda

Özlemin okyanusların ötesinde kalacak

Sonbahara dönecek tüm mevsimlerin

Umutlarım,tutkularım yine tutsak; 

Ben yine Afrikalı kölesi sevimizin 

Sen,unut unutabildiğin kadar

Unutmak ne ki?', 'Yokluğunu çam ağaçları giderecek gözlerinin Sensizliği içeceğim sabahçı kahvelerinde Yudum yudum!  Ağlamayacağım gidiyorsun diye  Ağlamak ne...', ARRAY['Türk Edebiyatı','Şiir','Vahittin Bozgeyik']::text[], 8.5, '{"poet":"Vahittin Bozgeyik","poet_slug":"vahittin-bozgeyik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olumden-otede-yine-sen-varsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul Beni', 'bul-beni-asli-akcay-md6ek', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıldızlar şahidim ki; 

Her gece sana sarılıp dalıyorum uykuya,

Güneş şahidim ki; 

Her sabah seninle açıyorum yeni güne gözlerimi.

Saymıyorum sensiz geçen günleri geceleri,

Yakıştıramıyorum gece gözlerime ağlamayı,

Sevgiyle bezenmiş yüreğime kederi koyamıyorum.

Sen, bu sabah çıkıp gittin evden.

Ve biliyorum ki her gün olduğu gibi,

Bu akşamda gülümseyerek döneceksin…

Benim acelem yok sevgili…

Ben her mevsim yeniden doğarım.

Belki de bu yazı sevmedin sen,

Belki baharda geleceksin.

Ama geleceksin…

Gözlerin, ellerin, dudakların…

Hepsini alıp yine kapıyı çalacaksın.

Belki bir başka baharda döneceksin.

Sen beni terk etmezsin sevgili.

Unuttun mu? 

Ben prensesim, senin prensesin.

Git diyemezsin bana –kal diyemediğin gibi-

Ben bu aşkın bedelini ödedim,

Ben seninle varım sevgili.

Ben, beni bulduğun yerdeyim.

TURKUAZ’ a büründüm.

Başını kaldırdığın gökteyim,

İçine çektiğin havadayım,

Parmaklarının dokunduğu, gözünün değdiği

Teninle hissettiğin yerdeyim.

Bul beni sevgili…

Ben, beni bulduğun yerdeyim,

Beni unuttuğun  yerde…

Bedeninde, ruhunda, yüreğindeyim.

Dokun bana…

Hasret beni kavurmadan,

Sevdan içimde yok olmadan,

Denizin rengi solmadan bul beni…

Turkuaz yaşama akmadan, insanoğlu onu tanımadan,

Bir masal aralığından sıyrılıp, gerçeğe kavuşmadan,

Aşka çok geç kalmadan

Bul beni…

Ruhum semaya ulaşmadan

Ne olur,

Dön geri….', 'Yıldızlar şahidim ki;  Her gece sana sarılıp dalıyorum uykuya, Güneş şahidim ki;  Her sabah seninle açıyorum yeni güne gözlerimi. Saymıyorum...', ARRAY['Türk Edebiyatı','Şiir','Aslı Akçay']::text[], 8.5, '{"poet":"Aslı Akçay","poet_slug":"asli-akcay","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bul-beni-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acımasız Aşk', 'acimasiz-ask-berna-ocakcioglu-e7wq0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Acımasız Aşk 



Her gece hayalin uzanıyor yanıma 

Yorgun gözlerim uykuya dalamıyor 

Acımasız aşkın saçlarımı kavrayıp 

Her gece aynı nöbeti tutturuyor,

Her gece o çıldırtan soruyu soruyor 

'''' Bu kadar severken razımı gönlün 

Burada yapayalnız uyumaya? '''' 

Ter içinde fırlıyorum, yalınyürek 

Ama sana çıkan yolları bulamıyorum. 

Koşsam, beklesem, 

Olduğun yerlere gelsem boşuna 

Senin suskunluğunu çözemiyorum. 

Sevdanın sokağına dalıyorum 

Dalıyorum da her yer sessiz,ıssız 

Işıklar yanmıyor,kuşlar cıvıldamıyor. 

Acımasız aşkın buyruğuna uyuyor, 

Bu ıssız sokağın nöbetini tutuyorum. 

Berna Ocakçıoğlu', 'Acımasız Aşk  Her gece hayalin uzanıyor yanıma  Yorgun gözlerim uykuya dalamıyor  Acımasız aşkın saçlarımı kavrayıp  Her gece aynı nöbeti tu...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/acimasiz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende ''''manidar'''' Bende ''''ürkek''''', 'sende-manidar-bende-urkek-berna-ocakcioglu-p2wxh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sende ''''Manidar'''' Bende ''''Ürkek'''' 



Saatler bilmem kaçı gösteriyormuş bana ne 

Benim tüm saatlerim sen dolu bilmesen de 

Sen dolu yalnızlığım bitmiyor her nedense 

Oysa tek isteğim bakışlarında kaybolmak 

Hayatı o bakışlarda unutmak, bulmak, yine unutmak. 

Seni  her gördüğümde 

Gönlümden anka kuşları yükseliyor zirvelere 

Çocuksu bir telaşla, uçarı bir neşeyle. 

Bir deli, bir garip, bir hoş oluyorum, 

Geçmesin istiyorum saatler zaman oracıkta donsun, 

Bakışların hep karşımda dursun, yüreğim senin olsun, 

Gözlerim gözlerinin derininde kaybolsun. 

Takılmalarımız olsun gözlerimize 

Bakışlarımız olsun bazen kısa bazen uzun 

Sende''''manidar'''' bende ''''ürkek'''' 

Senin kıs kıs güldüğün, 

Benim her seferinde öldüğüm... 

Kendimi bulup bulup yitirdiğim, delirdiğim 

Baktığım her yere nakış nakış işlediğim... 

Sevdiğim ama söyleyemediğim... 

Ve sonra gözlerini alıp gidiyorsun, 

Bana neler ettiğini bilmiyorsun. 

Hani karabasan çöker ya insanın üstüne, 

Öylesine kalkmaz oluyor elim, kolum. 

Yığılıp kalıyorum olduğum yere. 

Kanat çırpmaz oluyor anka kuşları yüreğimin. 

Neşesi kaçıyor duruluyor. 

Tüm ışıklarım sönüyor, yüreğim buz kesiyor. 

Gözlerin yüreğimi yerinden söküp gidiyor. 

Uzaklaşan her adımda eziyor, çiğniyorsun 

Mutlu ol seven bir yüreği öldürüyorsun. 

Sen ortada pervane, ben ateş böceği 

Etrafında dönüyor, yanıp yanıp sönüyorum 

Görmüyorsun... 

Masum sevgilere uzaksın biliyorum. 

Bildiğim çat pat iki küfürle 

Sayıp sövüyorum masumiyetime, ürkekliğime 

Kendime kızıyorum,yüreğime gözlerime 

Sana kızamıyorum, kıyamıyorum 

Neden sevdiğimi soruyorlar. 

Bilmiyorum... 

Sevgide neden olmaz diyorum. 

Denemedim değil denedim 

Gözlerine hapsettiğim yüreğimi 

Senden alıp başkasına veremedim. 

Ben ömrümü gözlerine hediye ettim gidiyorum. 

Bildiğim tek gerçek... 

Sebepsiz ve beklentisiz 

Seni seviyorum. 

Berna Ocakcıoğlu', 'Sende ''''Manidar'''' Bende ''''Ürkek''''  Saatler bilmem kaçı gösteriyormuş bana ne  Benim tüm saatlerim sen dolu bilmesen de  Sen dolu yalnızlığım...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sende-manidar-bende-urkek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saplantım', 'saplantim-berna-ocakcioglu-ivveu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her akşam senden vazgeçiyor 

Her sabah sevginle uyanıyorum

Trapiye ihtiyacım var

Saplantım oldun kurtulamıyorum.', 'Her akşam senden vazgeçiyor  Her sabah sevginle uyanıyorum Trapiye ihtiyacım var Saplantım oldun kurtulamıyorum....', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saplantim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akdeniz Çamları ve Karların Çığlığı', 'akdeniz-camlari-ve-karlarin-cigligi-berna-ocakcioglu-wzgji', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akdeniz Çamları ve Karların Çığlığı 



Bana yaz diyorsun 

Eskisi gibi şiirler yaz. 

Yazmak savaşmaktır diyorsun. 

Acı yazar mutluluk okur diyorsun. 

Yazmamam mutluluktan sanıyorsun 

Yanılıyorsun... 

İnsana mutluluk da veren garip acılar vardır 

Aşktır, sevdadır, çabadır, yârdır, 

Ya katığı mutluluk olmayan acılara kalmışsan 

Her seferinde kanmış, aldanmış, yıkılmışsan 

Hep  kırılgan çıkmışsa sevdiklerin. 

Sevdanı yağarken sen 

Kar gibi bereketli, sakınmadan 

En beyaz, en saf halinle güvendiğin dallara 

O dallar Akdeniz Çamları gibi devriliveriyorsa 

Burada güvenle tutunurum diye yağdığın dallar 

Kırılıp seni ayaklar altına seriveriyorsa 

Eriyorsun o zaman, çiğneniyorsun, eziliyorsun. 

Sen hiç âşık karların gökten sevgiyle yağışını izledin mi? 

Ya neşeyle Akdeniz Çamlarını sarıp sarmalayışını 

Sen hiç kış geceleri kırılgan Akdeniz çamlarının

 Yerlere serdiği karların çığlığını dinledin mi? 

Karın umudu bütün olmaktır çamla 

Tutunduğu dallarda kalıp bir mevsim 

Baharın açan ilk güneşiyle beslemektir çamı 

Erimek pahasına yine onunladır 

Ve ona karışır erirken de... 

Ama kırılgan çamlar ne yapar? 

Taşıyamaz ve o sevdalı karları 

Dallarını kırıp yerlere atar. 

Karları taşımak gibi yürek ister 

Sevgiyi taşımak. 

Lapa lapa yağan sevdalı karlar yok artık 

Ürkek ürkek sağa sola kaçışıyorlar 

Adına tipi diyorlar bunun. 

Korkak karların yağışı 

Tutunamayan karların dağılışı. 

Üzerine lapa lapa yağacak çamlar yok artık. 

Nasıl savaşırsın, 

Nasıl şiir yazarsın? 

Nasıl seversin, nasıl bağlanırsın, 

Biliyorsun ki tutunamayacaksın. 

Unutma  kış geldiğinde 

Kırılgan Akdeniz çamlarının yere serdiği 

Sevdalı karların çığlığını dinle... 

Berna Ocakcıoğlu', 'Akdeniz Çamları ve Karların Çığlığı  Bana yaz diyorsun  Eskisi gibi şiirler yaz.  Yazmak savaşmaktır diyorsun.  Acı yazar mutluluk okur diyo...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/akdeniz-camlari-ve-karlarin-cigligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ne Zaman Sevsek', 'biz-ne-zaman-sevsek-berna-ocakcioglu-sz3a8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biz Ne Zaman Sevsek 



Biz ne zaman sevsek 

Kar gibi yağdık sevgimizi 

Biz ne zaman sevsek, 

Temizledik, temiz bildik sevdiklerimizi

Biz ne zaman sevsek, 

Yalansız, katıksız, sektik. 

Kendimizi boşluğa bıraktık, 

Hesapsız, plansız, tutunmadan yağdık 

Aldandık...', 'Biz Ne Zaman Sevsek  Biz ne zaman sevsek  Kar gibi yağdık sevgimizi  Biz ne zaman sevsek,  Temizledik, temiz bildik sevdiklerimizi Biz ne za...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/biz-ne-zaman-sevsek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Olsam', 'ben-olsam-berna-ocakcioglu-gy720', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen her gece başka aşka sevdalı,

Koynunda kim varsa en çok sevdiğin o! 

Ben gözlerinin hançeriyle yaralı,

Hasta yatağımda inliyorum.

Bir ömür yanında ben olsam diyorum.', 'Sen her gece başka aşka sevdalı, Koynunda kim varsa en çok sevdiğin o!  Ben gözlerinin hançeriyle yaralı, Hasta yatağımda inliyorum. Bir ömü...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ben-olsam-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Özlemek Nedir Bilirmisin', 'sen-ozlemek-nedir-bilirmisin-mikayil-korkmaz-xmiyb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilirmisin

Sen özlemek nedir bilirmisin? 

Düşündükçe geçmişi yüreğin yanarmı hiç? 

Yada güzelim kalabalıkta kendini yalnız hissettiğin oldumu? 

Elini tutmadığın gözüne  hiç bakmadığıno meçhul sevgiliyi

özlediğin oldumu hiç? 

Kendini sorgulayıp bu nasıl aşk dediğin oldumu hiç? 

Yada vapur dolusu insan varken simidini martılarla paylaşıp sadece onlarla konuştuğun oldumu hiç? 

Ben bir imkansızı seviyorum yinede seveceğim diye

haykırdığın oldumu bebeğim? 

Sevdiğin kişinin bebeğim kelimesinden nefret ettiği

halde ona bebeğim dediğin oldumu hiç? 

Aşktan bedenin ateşler içinde kalıpta sabahlara kadar vücuduyun kavrulduğu oldumu hiç bebeğim? .

Sözlerimi sakın sitem sanma sana olan duygularımdan,sevgimden,çaresizliğimden,

Günah olduğunu bildiğim halde isyanımdan..

Sen benim için özelsin hep öyle kalacaksın.

Sevgiyle kal aşkım görüşmek dileğiyle..12.05.2004/12,30', 'Bilirmisin Sen özlemek nedir bilirmisin?  Düşündükçe geçmişi yüreğin yanarmı hiç?  Yada güzelim kalabalıkta kendini yalnız hissettiğin oldum...', ARRAY['Türk Edebiyatı','Şiir','Mikayil Korkmaz']::text[], 8.5, '{"poet":"Mikayil Korkmaz","poet_slug":"mikayil-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-ozlemek-nedir-bilirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Paylaşamam', 'seni-paylasamam-murat-feza-otmvh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yazmak seni klavye tuşlarıyla

kelime kelime seni anlatmak

aşkımı dökmek mısralara

ama yapamam kıskanırım paylaşamam

 seni hala seviyorum can ışığım

 paylaşamam  paylaşamam seni

ne şiirlerle nede şairlerle

aşkımı anlatamam anlatamam can ışığım

aşk duygularım sensin senin varlığın

senin kokun senin nefesin senin güzelliğin

bende yaşattığım can ışığımınsın

seni şiirlerin mısralarına hapsedemem can ışığım

kelimelerim seninle güzelleşti

seni yazdı seni andı sen vardın

beni kapsayan beni bütünleyen sen

can ışığım diyorsam canımsın cananımsın

 aldığım nefesimdesin ictiğim yudumumda

her saniyemdesin her dakikamda

 günümdesin mutluluğu bana sunan

akaşamlarımdasın akşamlarımda

ah o tükenmek bilmeyen karanlıklarımda

saatları tüketemediğim gecelerimde

bazen sarhoş bazenmelonkolik bazen yakamoz

senli dolu gecelerimde

rüyalarımdasın şafak vakti bitgin düşdüğüm

köz kapaklarıma yenilen sevdan

rüyalarımdasın rüyalarımda

kimi gece ayrılık kabusum oluyorsun

kimigece mutluluk meleğim can ışığım

seni yazamam demiştim   yazamadım

kelimelerim yetersiz kaldı seni anlatmaya

senki 

benim icin benim dünyamda herşeyimsin

seni anlatamadım canışığım us um yetersiz kaldı

affet beni can ışığım affet başaramadım..............', 'yazmak seni klavye tuşlarıyla kelime kelime seni anlatmak aşkımı dökmek mısralara ama yapamam kıskanırım paylaşamam  seni hala seviyorum can...', ARRAY['Türk Edebiyatı','Şiir','Murat Feza']::text[], 8.5, '{"poet":"Murat Feza","poet_slug":"murat-feza","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/seni-paylasamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Türküsü', 'yalnizlik-turkusu-gokhan-karaduman-x0xhu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızlık Türküsü... 

Dün yine bir başınaydım

Odamda 

İntihar kokan bir akşamda.

Öyle bir yalnızlıktı ki yaşadığım.

Şizofren bir eşkıya  gibi Senaryolar üretiyor

Yanımda sen yokken dahi seninle,sevişiyordum.

Ve sen Odamı  ışık yerine bakışların ile aydınlatıyordun

Karanlık odamın yağlı 

Duvarlarındaki tablolar gibi eşsiz ve hoştun 

Ama dokunamıyordum uzandığımda 

Çünkü hayalimde sen 

odamda eskimiş bir kaç eşya 

Ve bende kalmış donuk bir resminle vardı.

Eylül 2004 – Kadıköy

Atalay Yayhan – Gökhan Karaduman', 'Yalnızlık Türküsü...  Dün yine bir başınaydım Odamda  İntihar kokan bir akşamda. Öyle bir yalnızlıktı ki yaşadığım. Şizofren bir eşkıya  gib...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalnizlik-turkusu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerim cok kücüktü', 'ellerim-cok-kucuktu-serpil-maglicoglu-uplys', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dilim dilim, parca parca

Yasam kendini bize sunuyor

Oda bizden korkarmis meger

Bizim ondan korktugumuz kadar

Bana hic kimse anlatmadi

O yüce dagdan söz etmedi

O patika yollar nasil tirmanilir

ögretmedi

Korkularima kimler sahip cikacak

Kaygilarimi kimlere teslim edecegim

Hüzünlerimi hangi irmagin sularina birakmaliyim

Beni hep benden aldilar ama

Hickimse

Bana ben olmayi göstermedi

Kimbilir belkide BEN olmak

Okadar önemli degildi

Bu dünyada

Icimdeki kücük kizin sesi

Bazen icime sigamiyor

Ne yapsam fayda etmiyor

Kulaklarimi tikayamiyorum

Agladigi zamanlar

Gözlerimi kapatamiyorum

Hüzünlü yüzünü görmemek icin 

Kapi bulamiyorum carpayim

Oda disarida kalsin

Gözyaslari avuclarima akiyor bazi günler

Avuclarimin ici islaniyor

Beni benden caldiklarinda

Ben kac yasindaydim

Bilemiyorum hatirlayamiyorumki

Gözlerimi acmistim saskin bir halde

Icime ilk defa korku denilen karanlik düsmüstü

Beni benden aldiklarinda

Ellerim cok kücüktü, iyi biliyorum

Cok ama cok  bebek gibi

(Berlin 8/2004)', 'Dilim dilim, parca parca Yasam kendini bize sunuyor Oda bizden korkarmis meger Bizim ondan korktugumuz kadar Bana hic kimse anlatmadi O yüce...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ellerim-cok-kucuktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce Ve Senden Sonra', 'senden-once-ve-senden-sonra-edip-caki-y8usn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kefen beyazının yüreğinde

Günahlarım yıkanır bir ölümün teninde

Kanımı emen yarasa misali

İsmini sayıklıyorum hüznümün hasta döşeğinde

İki sesin çatışmasında

Çığlığımın zılgıtı kelam döker

Kulaklarım bir güvercin yuvası suretinde

Sesim zülmün soykırım anıtı

Bir kulaktan giren diğer kulakta ağır yaralı

Gönlümün havuzu kaç saatte dolar

Kaç sebepte boşalır yüreğim

Kanımda izinsiz dolaşan eşkiya gibi

Bu can kendini ele verir şimdi

Şimdi kaç ölüm sordu beni

Kaç kere sevmek hakkım var seni

Bir körebe oyununda kaybettim seni

Şimdi yalnızlığın sesi kulağımda

Yırtıcı kuş sürüsü gibi

Ölürsem senin için vurulurum

Adreslerde kayıp kurşun için

Yaşarsam çekerim karanlığa gözümün perdesini

Elleri kayıp gemiler gibi

Herşey senden önce ve senden sonra delim

Tarihsiz bir savaşın ölüm günlüğünde', 'Kefen beyazının yüreğinde Günahlarım yıkanır bir ölümün teninde Kanımı emen yarasa misali İsmini sayıklıyorum hüznümün hasta döşeğinde İki s...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/senden-once-ve-senden-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O senmisin yoksa?', 'o-senmisin-yoksa-serpil-maglicoglu-qb8vx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben sen, sende benmisin yoksa? 

Yoksa ben kendimi sendemi buluyorum? 

Seninde kendini bende buldugun gibi. 

Hangimiz aynadir, hangimiz aynaya bakan? 

Senin yüzünmüdür aynada kendini arayan? 

Yoksa aynadaki yüzmüdür,

Seni gülümseyerek seyre kalan? 

Bir zamanlar aynalarin hepsini,

Örtülerle kapayan ellerime baktigimda

Bana seni hatirlattiklarini biliyormusun.

Ellerime ellerinin ilk degdigi ani hatirlatiyorlar 

Ruhunun ruhumu ilk oksadigi isik vaktini

Sen sonsuzluguma islemissin ben ne yapayimki

Ellerimizinde bir hafizasi var

Gözlerimizinde bir hafizasi oldugu gibi 

Gözlerim seni göremesede

Onlarin hafizasinda gezindigini biliyormusun

Ben sana asirlarin icinden geliyorum

Nice asirlar astim senin ugruna 

Nice yasamlar gördüm yalniz basima

Nice acilar duydu su yüregim her yasantimda

Hep senin icin, hep senin ugruna

Bazi zamanlar erken gelmisim

Bir baska vakit ise cok gec kalmisim

Seni yüzyillardir ruhumda tasidigimi biliyormusun

Ne olur söyle

Benim aradigim isik

Ruhumun tek esi

O senmisin yoksa? 

Bazen hüzün sariyor

Ümitler yollarda yaya kaliyor 

Benim günlerim azaliyor

Yinemi yoksa yinemi gec kaldim

Yinemi erken davrandim

Yinemi sensiz dönecegim

Yinemi yalnizliga bürünecegim



Burasi hicbirsey degilki

Asil gidecegim yerler

Bana benim sensizligimi söyler

Bekliyorum

Ben burdayim 

Sen nerdesin? 

Yoksa 

YOKSA O SENMISIN? 

(Berlin 8/2004)', 'Ben sen, sende benmisin yoksa?  Yoksa ben kendimi sendemi buluyorum?  Seninde kendini bende buldugun gibi.  Hangimiz aynadir, hangimiz aynay...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/o-senmisin-yoksa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzun Yagmurlari', 'huzun-yagmurlari-sair-edta-t0amd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'HUZUN YAĞMURLARI

Hüzünlerin yol aldığı günlerde

Buyuyordun gözlerimde

Küçüldün sonra

Sevgimi anlamadığın günlerde 

Oluyordum ben 

Sensiz aksamların senli sabahlarında

Bir kırlangıç olurdu gözlerim

Uçardı

Gökkuşağının yedi rengine boyanmış gözbebeğinde

Sen sadece ölmeye bile layık olmayan

Bir aşksın

Gözlerim kapanır yokluğunun sisli akşamlarında

Ve 

Bir yerlerde kaybolmuş deli bir nehir misali

Akardın susuzluğuma

Kaldım akşamlarında

Sabahların tükendiği fukara sabahçı kahvelerinde

Mecnun 

Aşksız aksamların günbatımlarında 

Leylasız kaldığında 

Bil ki bir yaprak kaymış aksimizin sonbaharında

Bil ki bir yıldız kaymış saman yolunda 

Bil ki bir deniz kızı düşlemişim

Kalbimdeki okyanusun en sığında 

Ve 

Bil ki yalnızım insanlar aleminde 

Yalnızlık kaderim olmuş 

5 milyar insanin içinde

ama 

sen yetersin

gönlümün sahrasında 

serap gibi denizkızı…..', 'HUZUN YAĞMURLARI Hüzünlerin yol aldığı günlerde Buyuyordun gözlerimde Küçüldün sonra Sevgimi anlamadığın günlerde  Oluyordum ben  Sensiz aks...', ARRAY['Türk Edebiyatı','Şiir','Şair Edta']::text[], 8.5, '{"poet":"Şair Edta","poet_slug":"sair-edta","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/huzun-yagmurlari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölesiye Bir Şiir', 'olesiye-bir-siir-edip-caki-b0wft', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'El ele tutuşma yıldönümümüz 

Duvarlar çekildi tenimize hasret

İçememek seni her suyun günahında

Parlayan ayın yüzü hürmeti için

Çekip gitmek senin için

Adı konulmamış bir sevda ülkesine

Karşıma çıkan her benzerine

Izdıraplar içinde,yüreğimi ısmarlarım yine

En uykusuz zamanlarımda kördüm

Devrilmiş bir saltanatta resmini gördüm

İki gözün şahitliği yalan diyen idin

Pusulalar kuzeyi aldatır,buna tek nedendin

Çalkanır yürek senin için

Aylak zamanların çilingir sofralarında

Kuraklık deminde sevdamız için

Ismarlama yürekler büyüttüm aşkın narında', 'El ele tutuşma yıldönümümüz  Duvarlar çekildi tenimize hasret İçememek seni her suyun günahında Parlayan ayın yüzü hürmeti için Çekip gitmek...', ARRAY['Türk Edebiyatı','Şiir','Edip Çakı']::text[], 8.5, '{"poet":"Edip Çakı","poet_slug":"edip-caki","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olesiye-bir-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Var', 'ask-var-sair-edta-wt7t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yollarda kadın kokusu var 

Bakire bir sabahın akşamında

Yok olmuş umutlar var koylunun hasat yağmurlarında 

Aşk var uzun yollarda, dağlar arkasında 

Sabahı olmayan aksamlar var körpe gönüllerde 

sitem var asığın sazında 

uzun yollarda kavuşan insanlar var 

hayatta neşe var 

ama 

babam yok 

oksuzum,

kalpsizim,

sevgisizim

bir dağ istedim

eteklerinde yattığım 

bir dağ istedim rüzgarlara inat 

bir dağ istedim volkanlarında yandığım

ve 

bir kalp istedim 

pamuktan yumuşak 

nizam var,

terazi var,

denge var,

zamansız yağan yağmurlarda buğu var 

hüzün var 

okyanuslarda aşk var 

denizkızı var ………..

bir kartal uçuyorsa tek başına 

çakal korkuyorsa aslandan sebebi var 

Ayşe biliyorsa alinin sevdiği var 

iste o zaman 

gönüllerde 

gül bahçesi var 

aşk var 

denizkızı var 

……………………….', 'Yollarda kadın kokusu var  Bakire bir sabahın akşamında Yok olmuş umutlar var koylunun hasat yağmurlarında  Aşk var uzun yollarda, dağlar ar...', ARRAY['Türk Edebiyatı','Şiir','Şair Edta']::text[], 8.5, '{"poet":"Şair Edta","poet_slug":"sair-edta","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ask-var-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlar', 'anlar-volkan-yoruc-m0l2l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bizlerin yaşamayı öğrettiği zamanlar

Kimimiz acılar denizinde boğulur

Kimimiz sevgi bulutlarında uçuşurlar

Savruluruz hayat çemberinde

Anlar deriz

Yaşamaya mecbur olduğumuz zamanlar

Hatıralarla gelirler

Acılarla giderler

Ve kalbimizin bir köşeşine yerleşipte

Bize ağlamayı öğretirler

Anlar

Doğumdan ölüme uzanan zamanlar', 'Bizlerin yaşamayı öğrettiği zamanlar Kimimiz acılar denizinde boğulur Kimimiz sevgi bulutlarında uçuşurlar Savruluruz hayat çemberinde Anlar...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zencefil Asklar', 'zencefil-asklar-sair-edta-owpjp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buhranlı günlerde yaptığım tek şey ağlamaktı 

Gözyaşlarımda bir anlam vardı

Yollar uzadıkça anlamını kaybeden sevgi sözcükleriydi belki

Belki de divit ucunda mürekkep 

Aslolan tek şey ihanetin kucağında 

Uçuruma yuvarlanan sevgi kırıntılarıydı belki

Korların eritemediği yüreklerin sesini duyuyordum sanki

Çocuk ağlamasını andıran bir inlemeyle uyandım uykudan

Uyumak daha güzeldi belki 

Rüyaların anlam bulduğu yasamlar varmış 

Yaşamların anlam bulduğu rüyalar da cabası 

Bir rüya görene bir rüya bedava 

Periler ülkesinde melekler kadar güzel 

Anka kuşunun kanadındaki eftelya 

Denizler taştığında 

Gönlümden bir ırmak akar sonsuzluğa 

Aşksız kalanlar kadar rahat 

Aşık olanlarsa mum ışığı satırlarda bir beyit olan sevgilerini 

Haykırıyor………denizkızı………..', 'Buhranlı günlerde yaptığım tek şey ağlamaktı  Gözyaşlarımda bir anlam vardı Yollar uzadıkça anlamını kaybeden sevgi sözcükleriydi belki Belk...', ARRAY['Türk Edebiyatı','Şiir','Şair Edta']::text[], 8.5, '{"poet":"Şair Edta","poet_slug":"sair-edta","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zencefil-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaxta', 'saxta-ahmet-hani-uhsh9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'salam versem ezizim almayandır

meni yade gözel yar salmayandır.

sevinme ey soyuq qış yaz qabaqda

çox aydındır ki şaxta qalmayandır.', 'salam versem ezizim almayandır meni yade gözel yar salmayandır. sevinme ey soyuq qış yaz qabaqda çox aydındır ki şaxta qalmayandır....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/saxta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Rüzgar', 'deli-ruzgar-nesrin-aydin-9swzi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yol tükendi yar,ayaz sardı her yanı

Bir deli rüzgar savurdu yaprakları

Yağmurun yağdı umutsuzca dallarıma

Gitmeler var bundan ötelerde

Kalmalar rüyalarda,uzaklarda

Umut tükenmeye mahkum, direnişte

Ama bitmedi yangınlar,sönmedi hiç

Ama sen,sen öyle yapmadın yar...

Oysa güllerle donatmıştım yollarını

Sen, değerini hiç öğrenemeyeceğin,

Sevgimin sualsiz kurbanı oldun.

Bilmezsin sen,kıymet bilmeyene

Yer yoktur bu yürekte

Hem de hiç bilmezsin

Sızıların hiç dinmediği

Bu yürekteki gururu

Öğrenmeliydin yar,öğrenmeliydin

Kırık kalbin diyetinin olmadığını...

Bitmek üzereyim bu yokuşta

Yoruldum,gidemiyorum...

Dedim ya yar, ayaz sarmış her yanı

Bir deli rüzgar esmekte...

..', 'Yol tükendi yar,ayaz sardı her yanı Bir deli rüzgar savurdu yaprakları Yağmurun yağdı umutsuzca dallarıma Gitmeler var bundan ötelerde Kalma...', ARRAY['Türk Edebiyatı','Şiir','Nesrin Aydın']::text[], 8.5, '{"poet":"Nesrin Aydın","poet_slug":"nesrin-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/deli-ruzgar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkı Yok', 'farki-yok-halil-kesken-c84oi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok garipti benim yaşadıklarım

Saçma bir masaldan bile farkı yok

Terketti aşkına inandıklarım

Koca bir yalandan bile farkı yok

Hayatım boyunca çok kez yanıldım

Bir anlık ilgiyi büyük aşk sandım

Kalbimi hiç sorma, parçaladığım

Kırık bir vazodan bile farkı yok

Poyrazlar değildi beni yıpratan

İlk kez veda ettim sana doymadan

Rengim öylesine soldu ki o an

Kuru bir çiçekten bile farkı yok

Ona her taraftan sevgi gelirmiş

Derler ki gönüller göle benzermiş

Benimki sevmiyor, suyu çekilmiş

Sahra çöllerinden bile farkı yok', 'Çok garipti benim yaşadıklarım Saçma bir masaldan bile farkı yok Terketti aşkına inandıklarım Koca bir yalandan bile farkı yok Hayatım boyun...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/farki-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-serpil-maglicoglu-14ux5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sanki bize uzak dünyalarin

Yabanci bahcelerinde

Bir sonbahar yasaniyor

Solan cicekleri

Ayaklarimin dibine düsüyor

Hersey dökülüyor

Yapraklar düsüyor

Insanlarda...

Hepimizin yolu ayni gibi

Sonsuzluga dogru gidiyor

Her hücrenin icinde ayni gülümseyis

Düserken dahi

Sicak bir kucaga düsecegini

Bilir gibiler

Sona dogru giderken

Basa döndüklerinide

Bildikleri gibi', 'Sanki bize uzak dünyalarin Yabanci bahcelerinde Bir sonbahar yasaniyor Solan cicekleri Ayaklarimin dibine düsüyor Hersey dökülüyor Yapraklar...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sonbahar-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasuh', 'nasuh-sair-ahrazi-eimpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '‘’Mâdem ki dünyâdan evlâdır bu sal,

Terk eyle buhrânı,mahcup durma Nuh’’

Hışmıyla gelmişse tek gerçek misal; 

Buhranlı dünyâyı bir seyret Nasuh….

***', '‘’Mâdem ki dünyâdan evlâdır bu sal, Terk eyle buhrânı,mahcup durma Nuh’’ Hışmıyla gelmişse tek gerçek misal;  Buhranlı dünyâyı bir seyret Na...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/nasuh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ayrılmazdık Ya', 'biz-ayrilmazdik-ya-murat-nail-guney-wammy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün senden uzak seni yaşadım,

Gözlerim doldu da ağlayamadım,

Ardından bir mendil sallayamadım,

Aklım sende kaldı:HATIRAM OLSUN...

Sevgiyi anlatan kelimem sensin,

Şiirim, mısram, satırım, hecemsin,

Hem çektiğim acı, hem de neş''emsin,

Söyle bu şarkımı:GÖNLÜNE DOLSUN...

Yazık olmuş güzel boynun bükülmüş,

Duydum dallarında yaprak dökülmüş,

Yılllarca sevilmiş, şimdi bıkılmış,

Olan olmuş artık: CANIN SAĞ OLSUN...

Muradım anılar kapanmaz yara,

Mutluluk şans işi benzer kumara,

Bu oyunda geçmez saltanat, para

Biz ayrılmazdık ya: EDENLER BULSUN...

MURAT NAİL GÜNEY', 'Bu gün senden uzak seni yaşadım, Gözlerim doldu da ağlayamadım, Ardından bir mendil sallayamadım, Aklım sende kaldı:HATIRAM OLSUN... Sevgiyi...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/biz-ayrilmazdik-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demiştim', 'demistim-zeki-ergin-s32fc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir sen anlarsın demiştim 

duyarsın yeri geldiğinde

yürek sızımı 

çapraz ateşte olduğumda 

yanımda olur

çatlayan dudaklarıma su verir

kabuslarımda elimi tutar

terli alnımı siler

demiştim

şimdi hangi denizleri aşar

hangi limana sığarım

hala şaşar  durur

başımı taşlara vururum

sahte dostluklara

yalan sevdalara 

_erenköy 26eylül2004', 'bir sen anlarsın demiştim  duyarsın yeri geldiğinde yürek sızımı  çapraz ateşte olduğumda  yanımda olur çatlayan dudaklarıma su verir kabusl...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/demistim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşır Dur...', 'sasir-dur-i-brahim-ethem-bingul-fajml', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yalnız olmak,

Yalnız kalmaktan kolaymış...

Kim bilse,duysa

Olup biten herşeye şaşarmış...

Şimdi sen de şaşır dur

Yarınlar kimlerin eline kalmış...

Yâr dediğin

Gün gelir el olurmuş...

www.iebingul.com', 'Yalnız olmak, Yalnız kalmaktan kolaymış... Kim bilse,duysa Olup biten herşeye şaşarmış... Şimdi sen de şaşır dur Yarınlar kimlerin eline kal...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sasir-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ufukta Yeşeren Mavi Sabahta Tanım IV', 'ben-ufukta-yeseren-mavi-sabahta-tanim-iv-sadik-softa-ke8b3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceyi damgalıyor, altın sükûtunda gün,

Gün hesaba çekilir, yargı altındadır dün.

Gizlerinde gezinir, gün boyu yarım düşler,

Bazen de bir fısıltı, senden gelir gülüşler.

Yorgun duygular yürür, düşünceler açılır,

Kainatta dert kalmaz, hep önüme saçılır.

Yürekte harmanlanır,iyi kötü,yaramaz,

Hatıralar  tükenir,  yaraları  saramaz.

Huzur gelen müjdedir, ileri saatlerde,

Uzaktaki sevgili, kaybolur vaatlerde.

Yalnızlık çöker yine, derinleşir düşünce,

Aniden kopar zincir, gün yükü üşüşünce.

Geceyi birden sarsar, gün güneşten dökülür; 

Ceylan bakışlar sarar, gün geceden sökülür.', 'Geceyi damgalıyor, altın sükûtunda gün, Gün hesaba çekilir, yargı altındadır dün. Gizlerinde gezinir, gün boyu yarım düşler, Bazen de bir fı...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-ufukta-yeseren-mavi-sabahta-tanim-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Türkü Yazdım', 'sana-turku-yazdim-murat-nail-guney-vlef6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gayrı bizim elin soldu gülleri,

Sustu bülbülleri, esmez yelleri,

Mevlam mekan etti gurbet elleri,

Artık bir meçhule düştü yolumuz...

Gelinin kınası elinden uçtu,

Mevsim geldi kuşlar yuvadan göçtü,

Senden son hatıra bir tutam saçtı,

Düşürdüm yerlere, tutmaz elimiz...

Masal gibi geçtin ey koca ömür,

Gam''a yiğit, neme dayanmaz demir,

Yazımız böyleymiş elden ne gelir,

Hasretle yoğruldu gönüllerimiz...

Sana türkü yazdım, söylesin diller,

Sazım sustu artık kırıldı teller,

Durgun suya döndü gönülde seller,

Vade dolup, susmadan dillerimiz...

Muradım aşığın çilesi uzun,

Kimine acıdır en doğru sözün,

Dostunu iyi seç görürken gözün,

Sonra ırak olur, tez yollarımız...

murat nail güney', 'Gayrı bizim elin soldu gülleri, Sustu bülbülleri, esmez yelleri, Mevlam mekan etti gurbet elleri, Artık bir meçhule düştü yolumuz... Gelinin...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-turku-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Eller', 'bu-eller-sadik-softa-ddc0e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen gelmedin,buraları bilmezsin; 

Asırlara  kök  salmıştır  bu  eller.

Sen baharda,çiçek çiçek açmadın; 

Çiçeklere kök  salmıştır  bu  eller.

Baharla her gönül sel olur burada,

Mahzunlaşır yüzler gül olur burada,

Gurbet düğüm düğüm yol olur burada,

Gözyaşına  kök  salmıştır  bu  eller.

Çilede, kahırda sonsuzluk akar,

Zaman ta ademden göz olur bakar,

Yanık benizlerde mahzunluk yakar,

Garipliğe  kök  salmıştır bu eller.

Rüzgarında yanık hava savrulur,

Duygu harman olur bir bir devrilir,

Sevdalanan yürek burada kavrulur,

Yoksulluğa kök salmıştır bu eller.

Bozkır’da açan bir çiçeği düşün,

Hayalden öteye, gerçeği düşün,

Ağustosta  terli pürçeği düşün,

Yüreklere kök salmıştır bu eller.

Çankırı-12.06.2004', 'Sen gelmedin,buraları bilmezsin;  Asırlara  kök  salmıştır  bu  eller. Sen baharda,çiçek çiçek açmadın;  Çiçeklere kök  salmıştır  bu  eller...', ARRAY['Türk Edebiyatı','Şiir','Sadık Softa']::text[], 8.5, '{"poet":"Sadık Softa","poet_slug":"sadik-softa","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-eller-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gideceksen Bir Gün Hiç Gelmeseydin', 'gideceksen-bir-gun-hic-gelmeseydin-murat-nail-guney-fk2s8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbimde saklıyken tüm duygularım,

Mutluydum inan ki sen olmasaydın,

Ne aşk, ne hasreti tatmamıştım ben,

Gözümden gönlüme sen dolmasaydın...

Yanmazdı gönlümde sönmeyen ateş,

Akmazdı gözümden bir tek damla yaş,

Saçlarım ağardı bak yavaş yavaş,

Gideceksen bir gün hiç gelmeseydin...

Yollara bakmaktan gözüm yoruldu,

Vefasız bu aşktan gönlüm yoruldu,

Her sözünde,daha beter kırıldı,

Batan güneş gibi hiç doğmasaydın...

Anlamsızca eğer senca aşkımız,

Unutuldu ise artık şarkımız,

Akordu bozulmuş gönül sazımız,

Yazdığım masalda sen olmasaydın....

murat nail güney', 'Kalbimde saklıyken tüm duygularım, Mutluydum inan ki sen olmasaydın, Ne aşk, ne hasreti tatmamıştım ben, Gözümden gönlüme sen dolmasaydın......', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gideceksen-bir-gun-hic-gelmeseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Sevdan Düştü', 'i-cime-sevdan-dustu-yelda-akcos-xquok', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Solunası aşklardır şu bahtsız dünyada keşfettiğim,

Sevmek bilmiyor vurgun yemiş yüreğim,

Kuru yapraklara bir çiğ damlası sevdiğim,

Beyaz güllerime ateş düştü bu akşam.

Çıtası bozuk aşklar serpilmiş gönlüme,

Dört yapraklı yonca düşmüş kedere,

Güneş açmaz artık hüzünlerime,

Dolunayıma kar düştü bu akşam.

Kırık bir sazın tellerinde soğuk bedenler,

Bir avuç çakıl taşında gizli, yıkılası düşler,

Aşkın resmini yapar ölesiye sevenler,

İçime sevdan düştü bu akşam.

				(23.09.2004,Ankara)', 'Solunası aşklardır şu bahtsız dünyada keşfettiğim, Sevmek bilmiyor vurgun yemiş yüreğim, Kuru yapraklara bir çiğ damlası sevdiğim, Beyaz gül...', ARRAY['Türk Edebiyatı','Şiir','Yelda Akcoş']::text[], 8.5, '{"poet":"Yelda Akcoş","poet_slug":"yelda-akcos","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icime-sevdan-dustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Ordusu', 'huzun-ordusu-osman-i-nci-r053u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşandım mutluluk silahlarımla,

Çıktım yola, sevgi küheylanımla,

Karşındayım işte, sabır kılıcımla,

Savaş açtım sana, Hüzün Ordusu..', 'Kuşandım mutluluk silahlarımla, Çıktım yola, sevgi küheylanımla, Karşındayım işte, sabır kılıcımla, Savaş açtım sana, Hüzün Ordusu.....', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/huzun-ordusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terk Edip Gitmiş', 'terk-edip-gitmis-osman-i-nci-w7479', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Rüzgâr esti camdan, tüllerden,

Haber geldi, uzak illerden,

Kan damladı, beyaz güllerden,

Yarim beni, terk edip gitmiş...

Hüzün bana, yine dost olmuş,

Gözler akar, yaş ile dolmuş,

Gönül de hazan, yürek solmuş,

Yarim beni, terk edip gitmiş...

Gülmek haram, ağlarım artık,

Yürek yanar, dağlarım artık,

Derin mezar, sağlarım artık,

Yarim beni, terk edip gitmiş...

Yaşam bu mu, sorarım şimdi,

Bin beddua, salarım şimdi,

Bir de şarap, açarım şimdi,

Yarim beni, terk edip gitmiş...', 'Rüzgâr esti camdan, tüllerden, Haber geldi, uzak illerden, Kan damladı, beyaz güllerden, Yarim beni, terk edip gitmiş... Hüzün bana, yine do...', ARRAY['Türk Edebiyatı','Şiir','Osman İnci']::text[], 8.5, '{"poet":"Osman İnci","poet_slug":"osman-i-nci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/terk-edip-gitmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benide Al Giderken Ecel', 'benide-al-giderken-ecel-murat-nail-guney-07a7h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kar yağar toprağın rengi aklanır,

Altında tazecik canlar saklanır,

Bahar gelsin güneş açsın beklenir,

Çetin geçeceğe benzer bu kışta...

Rüzgar şarkı söyler uçuşur karlar,

Buzların altında çağlar pınarlar,

Akşam köy evinde yanar fenerler,

Yalnız bir kurt uluyor yine dışta...

Gece ayaz olur ocak yakılır,

İçilir kahveler,fallar bakılır,

Kimi gelin olur,kına yakılır,

Kimi güvey olur,sadece düşte...

Dünya bir gemiyse aşktır dümeni,

Belirsiz menzili, yoktur döneni,

Ecel gelip, alır giderse seni,

Bana da uğrasın,söyle dönüşte...

murat nail güney', 'Kar yağar toprağın rengi aklanır, Altında tazecik canlar saklanır, Bahar gelsin güneş açsın beklenir, Çetin geçeceğe benzer bu kışta... Rüzg...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/benide-al-giderken-ecel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gün İçimde Küçülen Bir Alev Bu', 'her-gun-i-cimde-kuculen-bir-alev-bu-selim-bayrak-li6tr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her gün içimde küçülen bir alev bu

Öyle ki yakında benden eser kalmayacak

Her gün içimde azalan bir duygu bu

Öyle ki düşlerim seni asla salmayacak

Dakikalara hapis oldu gençliğim

Yılları saniye (saniye)  sayacak

Hakikatlere ne oldu! Neredeyim

Benliğim ruhumdan kayacak

Bir göktaşı gibi çarpıp varlığına

Paramparça olacak

Sen asla burada olmasan da

Bir tarafım her zaman yanında kalacak! 

1996 - Bolu', 'Her gün içimde küçülen bir alev bu Öyle ki yakında benden eser kalmayacak Her gün içimde azalan bir duygu bu Öyle ki düşlerim seni asla salm...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/her-gun-icimde-kuculen-bir-alev-bu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabrimde İsminle Doğrulacağım', 'kabrimde-i-sminle-dogrulacagim-murat-nail-guney-nvbfi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şiirlerde buldum ben teselliyi,

Yalnızlıkta buldum gerçek sevgiyi,

Dilimden dökülen her kelimeyi,

Sana şarkı yapıp haykıracağım...

Kırdım gönlümdeki paslı zinciri,

Yudum-yudum içtim aşkın zehrini,

Kimi deli dedi, kimi serseri,

Kalbimde sevginle çıldıracağım...

Geceme rüzgarsın, gündüz fırtına,

Dünyanın derdini yıktın sırtıma,

Bunlar yetmez gibi, bir de aşkınla,

Sevdanın selinde boğulacağım...

Sönmeyen ateşim, bağrımda közsün,

Mazimden hatıra en güzel gözsün,

Dilimden düşmeyen en içli sözsün,

Kabrimde isminle doğrulacağım...

murat nail güney', 'Şiirlerde buldum ben teselliyi, Yalnızlıkta buldum gerçek sevgiyi, Dilimden dökülen her kelimeyi, Sana şarkı yapıp haykıracağım... Kırdım gö...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kabrimde-isminle-dogrulacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sızıntı! !', 'sizinti-his-kaybi-mk-wilo2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sızıntı başlar

Yanaklarımdan süzülen! 

Bu Gönlün Verem Yanı Ah! ! ! 

Sen! 

Yorgun gece, Aşikar düşler

Sabırsızdı bak sensiz alınan tüm nefesler

Bir dalga vururdu kıyı’ya Martı kanat çırpardı Umut’la

Bir Resim kayardı, anılar canlanır Yanaklarımdan akardı 

Firar’da bir kaç umut, Gece’ye sitemkar hayallerim

Kızkulesi düşlerinde Aşk’ın mimarı sen 

Gönül’de Beklenen, Beklentilerde Tükenen 

Kolay değildi Hatta Zordu sensizlik; yokluğunu yaşarken 

Sus sus be gözleri kahvem 

Bir ben çığırtkandım bir’de Sokakta İşportacı 

O diliyle Haykırırdı, Aşk elbette gözleriyle 

İkiside çığırtkandı ikiside Tezgahta umutları harcadı 

Şimdi Karanlıksın İstanbul

Aşk’ların Şehri şimdi çığırtkan yanım, sende yalanım

Ey Aşk girdabı, Üsküdar’da kızkulesinde dalga seslerinde

Tükenen Her ulaştığında kıyı’ya, Dağılan Yanım! Ben yaşadım 

Kaldırım taşlarını sayan gözlerim

Tören adımında ardısıra diğerini takip eden adımlarım 

Özlenip her gece arzulanan, Rakının yanında kahrolan umutlarım 

Bak uzağında kaldık hayatın Her gece kayıp bir Yanım: yarım 

Hayatımın ilkleri ve ikincileri arasında 

Her dokunduğumda kızıl saçlarına 

Ve tutarken ellerini titrer bedenim

Bir senin verdiğin heyecani birde azraili hiç unutamadım! Derin; içten nefes alırdım! ! 

Bir soluk’ta yudumladım kadehi ismini sordum 

Adını söyleyemedim kendime

Üsküdar’da Sahil’de ben Hayatımı aradım 

Ey mapus umutlarım Ey yaşamdan afaroz edilmiş, Tebessümlerim

Söyle Şimdi Hangi Sensizliktesin? 

M.K.Versac 26/09/2004 S:18.40', 'Bir sızıntı başlar Yanaklarımdan süzülen!  Bu Gönlün Verem Yanı Ah! ! !  Sen!  Yorgun gece, Aşikar düşler Sabırsızdı bak sensiz alınan tüm n...', ARRAY['Türk Edebiyatı','Şiir','His Kaybı Mk']::text[], 8.5, '{"poet":"His Kaybı Mk","poet_slug":"his-kaybi-mk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sizinti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne yapmaliydim', 'ne-yapmaliydim-salih-dere-5xigr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kadın, o güne kadar nefsimin şehrayini diye olan ben, bu defa adam akıllı sıkıştım. O fazlasıyla usta çıktı ve erkeği mat etmekteki en tesirli silah olarak beni, nefsimle korkunç bir ihtilafa düşürdü. Adeta ikiye bölündüm ve kendi kendimi yemeye başladım. Bu anlatılmaz duygu,

Benim bugünkü dövünüşümdür. Bana mahrumluğumu anlatmaktan başka bir şey getiremiyordu. Aslında aşk çok güzel bir duyguymuş. Ama hakiki sevmek varya işte o beni bitirdi. Seni seviyorum demek ne kadar da kolay bir kelime aslında; Ama sadece seni sevmek seni kandırmak değil(Seni sana anlatabilmektir)  gerçekten, hakikaten sevmektir. İşte aşk, sevgi bu olmalı bence.(Sensizken bile sensizliği yaşamak gibi)  Çünkü ben şu an onu yaşıyorum. Ama asla ve asla kandırmıyorum ne kendimi, nede, O’nu.

Zaten sensiz ve senden habersiz alınan nefes, varlığın değil yokluğun soluğudur. Ben bir sınır aşmak istemiyorum; O nu aşmak için senden izin istiyorum;', 'Kadın, o güne kadar nefsimin şehrayini diye olan ben, bu defa adam akıllı sıkıştım. O fazlasıyla usta çıktı ve erkeği mat etmekteki en tesir...', ARRAY['Türk Edebiyatı','Şiir','Salih Dere']::text[], 8.5, '{"poet":"Salih Dere","poet_slug":"salih-dere","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ne-yapmaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Sevda Ki', 'oyle-bir-sevda-ki-murat-nail-guney-skh3l', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Samanlık içinde iğne misali,

Gönlümün işi ne karanlıklarda,

Öyle bir sevda ki yoktur emsali,

Bazan düşte çıkar,bazan fallarda....

Yağmurca yağar da yere dökülmez,

Delice severde dile dökülmez,

Umarım bu yılda boynum bükülmez,

Bir yıl daha geçti gurbet ellerde...

Yaprağa düşünce çiğ derler ona,

Önüne geçilmez olur sellerde.

Her sevda gönülde kalmasa bile,

Her gönüle akar bazan dillerde...

Çileler katlanır yumak olurmuş,

Kimi kefen, kimi  duvak olurmuş,

Bazan aşıklar da tuhaf olurmuş,

bülbül öter mi hiç solan güllerde...

murat nail güney...', 'Samanlık içinde iğne misali, Gönlümün işi ne karanlıklarda, Öyle bir sevda ki yoktur emsali, Bazan düşte çıkar,bazan fallarda.... Yağmurca y...', ARRAY['Türk Edebiyatı','Şiir','Murat Nail Güney']::text[], 8.5, '{"poet":"Murat Nail Güney","poet_slug":"murat-nail-guney","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/oyle-bir-sevda-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İletişim', 'i-letisim-arslan-alp-2w3kk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanları uzak tutarak kendimizden

Ne kadar karşılayabiliriz

Hayatın zor yanlarını

Tekbaşımıza.

Paylaşmazsak sıkıntılarımızı

Dostlarla, sevgiliyle

Nasıl taşırız

Zor gelen yükleri,

Omuzumuzda

Paylaşmazsak sevinçleri

Dostlarla, sevgiliyle

Nasıl çeviririz

Karamsar düşünceleri

Aydınlığa

Kollarımızı açmazsak

Hayata doğru,

Tutarsak 

Bir tek kendi bedenimizi,

Yalnız yaşarsak hayatı,

Ne katabiliriz hayata? 

Hayat ne katabilir yaşamımıza? 

26 Eylül 2004, İstanbul', 'İnsanları uzak tutarak kendimizden Ne kadar karşılayabiliriz Hayatın zor yanlarını Tekbaşımıza. Paylaşmazsak sıkıntılarımızı Dostlarla, sevg...', ARRAY['Türk Edebiyatı','Şiir','Arslan Alp']::text[], 8.5, '{"poet":"Arslan Alp","poet_slug":"arslan-alp","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/iletisim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Al Beni...', 'gel-al-beni-akin-tekin-1p1u0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ateş çemberindeki bir akrep gibi

       intihar etti düşlerim

Ne gariptir,

Yangınlar içinde geçti de ömrüm,

Kar altında donup kaldı aşklarım

Doruklarına tırmandığım dağlar,

      ne kadar da küçükmüş meğer

Kuyruğunu tutmaya çalışan bir köpek gibi,

     dönüp durmuşum olduğum yerde

Bitsin artık

Şehir meydanında bekleyeceğim seni

Gel al beni yalnızlığım', 'Ateş çemberindeki bir akrep gibi        intihar etti düşlerim Ne gariptir, Yangınlar içinde geçti de ömrüm, Kar altında donup kaldı aşklarım...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gel-al-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık (Hanife Nine)', 'yalnizlik-hanife-nine-akin-tekin-ai641', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim kapıma da gel ne olur

Zil bozukmuş, varsın olsun

Vur tokmağın gözüne

Posta! diye bağır ne olur', 'Benim kapıma da gel ne olur Zil bozukmuş, varsın olsun Vur tokmağın gözüne Posta! diye bağır ne olur...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalnizlik-hanife-nine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terkedilen', 'terkedilen-akin-tekin-5n3fy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gidişin vurdu geçti beni

Ben ki seni, çıldırasıya

Uğruna sigarayı bırakacak kadar

Seviyorken

Sen de gittin ya

Gerisi boş, gerisi hikaye', 'Gidişin vurdu geçti beni Ben ki seni, çıldırasıya Uğruna sigarayı bırakacak kadar Seviyorken Sen de gittin ya Gerisi boş, gerisi hikaye...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/terkedilen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamayız', 'unutamayiz-abdullah-atay-p6ld5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir damla sudan oluşan canı

dokuz ay taşındığımız karnı

damarımızda dolaşan kanı

unutamayız unutamayız...

aldığımız ilk nefesi

kulağımızda ki  ezan sesini

mutlandırdığımız herkesi

unutamayız unutamayız...

anamızın ak sütünü

o sıcacık göğsünü

yüreğinin büyüklüğünü

unutamayız unuatamayız...

bizdik ananın canbebeği

onun verdiği emeği

olduk hayatın gerçeği

unutamayız unutamayız...

uykuları bölüşünü

gözündeki gülüşünü

ananın şefkatli öpüşünü

unutamayız unutamayız...

gittiğimiz okulu

verilen bilgi ve akılı

yaşam has çiçek kokulu

unutamayız unutamayız...

başımızdaki kavak yelini

gönül bahçemizde sevda gülünü

yarin tatlı dilini

unutamayız unutamayız...

hakkınca  yapılan işi

helalden kazanılan aşı

bize canını veren eşi

unutamayız unutamayız...

çiçekle bezenen baharı

güneşle kavrulan yaprağı

kışıyla üşüyen toprağı

unutamayız unutamayız...

sevgilinin sessiz naaşını

o taht misali musalla taşını

akıtılan gözyaşını

unutamayız unutamayız...', 'bir damla sudan oluşan canı dokuz ay taşındığımız karnı damarımızda dolaşan kanı unutamayız unutamayız... aldığımız ilk nefesi kulağımızda k...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/unutamayiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi', 'mavi-akin-tekin-gate5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mavi elbiseli kız

Sen de güzelsin ama

Elbisen daha güzel', 'Mavi elbiseli kız Sen de güzelsin ama Elbisen daha güzel...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mavi-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-semra-dereli-2q54t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'YABANCI

Yüreğinin zincirlerini 

Çözebilir miyim? 

Zaman ellerinde büyüdükçe

Hudutları geçebilir miyim? 

Çarmıha gerersin imgeleri

Pas tutar sevinçler...

Fısıldaşır düşüncemde

Sana özel ihtilaller...

Senden önce öldüm.

Sakladığın kara bir inci

Gömdün pamuk ellerinde

Diri diri gölgemi...

Gözlerimizde iki çiy damlası

Aynı buluttan düşen...

Soğuyup giden bedenlerimiz

Yabancı...', 'YABANCI Yüreğinin zincirlerini  Çözebilir miyim?  Zaman ellerinde büyüdükçe Hudutları geçebilir miyim?  Çarmıha gerersin imgeleri Pas tutar ...', ARRAY['Türk Edebiyatı','Şiir','Semra Dereli']::text[], 8.5, '{"poet":"Semra Dereli","poet_slug":"semra-dereli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yabanci-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşq', 'esq-ahmet-hani-725cy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'güneşe sarı

bir pencere açılsın

yalnız bu

eşq budur.', 'güneşe sarı bir pencere açılsın yalnız bu eşq budur....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/esq-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beter Diyemiyorum', 'beter-diyemiyorum-engin-namli-rbsot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir derdim var benim kimse bilmiyor

İçimden çıkarıp kimse almıyor

Öyle bir dert ki insafa gelmiyor

Ölmekten de  beter diyemiyorum

Her görülen günüm zindan gibidir

Kabuslarım sanki söz sahibidir

Ölüm değilse de buna ne denir

Ölmekten de  beter diyemiyorum

Göçen takvimlerde kaldı sevincim

Şimdi durmadan kan ağlıyor içim

Böyle bir acıya bitmiyor hıncım

Ölmekten de  beter diyemiyorum

Bahtiyar olarak kalmak ukdemdi

Kanımca bu benim için elzemdi

Maksudumu çalan eskiyen demdi

Ölmekten de  beter diyemiyorum

Kuşkusuz sevgiydi tek ihtiyacım

Ezelden beri hep buna muhtacım

Ne yazık ki bir gün dinmiyor acım

Ölmekten de  beter diyemiyorum

Yükledikçe sabrım taşını sırta:

Azalmaz, çoğalır gam arta arta.

Bu gidişle halim olmaz sa orta

Ölmekten de  beter diyemiyorum

Engin NAMLI  19:57 26.09.2004', 'Bir derdim var benim kimse bilmiyor İçimden çıkarıp kimse almıyor Öyle bir dert ki insafa gelmiyor Ölmekten de  beter diyemiyorum Her görüle...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/beter-diyemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Sarkaçları (Tokat Saat Kulesi''nin 100. Yılı Anısına)', 'zamanin-sarkaclari-tokat-saat-kulesi-nin-100-yili-anisina-halil-pazarli-jnt74', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zamanın sarkaçları salkım saçak

dökülürken bu Şehr-i Tokat''ın nasırlı ellerinden

ben hala evde kalmış

kız kurusu sevdalara aşık

başı dik

ve alnı açık

ihtiyar bir delikanlıyım

ve ben hala

kanadı yağmur yüklü

göçmen kuşların tünediği

bir şefkat tapınağıyım

Ancak güneşin ilk ışıkları

okşarken şu hökelek gövdemin

güdük ve fakir gölgesini

ben Behzat Deresi''nin yemyeşil

o kadim sularıyla

her gün yunup yıkanmaktayım

Oysa tam bir asır geçmişti aradan

eskiyen zaman mıydı

bu Şehr-i Tokat mıydı

yoksa günlük sevişen

akreple yelkovan mıydı

Bilmiyorum

inanın bilmiyorum

ama yinede

zamanın o küskün şahitliğine

yitip giden silinen Halkalı Köprüsü''ne

yanımdaki kavağın

çatırdayan sesine

birde Topçam Dağı''nın

soğuk esen yeline

inatla direniyorum

Unutkanlığımı bunaklığıma verin

ne de olsa koca bir yüzyıl geçmiş buradan

ben ki nice depremler yedim

nice yangınlar gördüm

nice selleri savdım

ben ki bütün bunlara rağmen

yıkılmadım sürünmedim küçülmedim

bir onur yarışı gibi

bir zafer savaşı gibi

ve bir İstiklâl Marşı gibi

şimdi bile dimdik

ayakta ve hayattayım

Ya sonrası

kardı kıştı soğuktu

nice kağnılar çöktü önümde

kervanlar geldi geçti usulü aheste

ve nice analar şehit verdi oğlunu

gavurun dölü yedi düvele karşı

Yemen''de Trablusgarp''ta Çanakkale''de

ve ben bir türkü duyardım uzaklarda

'' Hey on beşli on beşli

  Tokat yolları taşlı

  On beşliler gidiyor

  Kızların gözü yaşlı ''

Derler ki

su uyur düşman uyur

ama saatler hiç uyumazmış

kim demiş

ben ki her seher vakti

kardeşim Behzat Camii''nden yükselen

mahmur ezan sesiyle uyanırım

Oysa tam bir asır geçmişti aradan

eskiyen ezan mıydı

bakır bir kazan mıydı

yoksa Şehr-i Tokat''a

düşen son hazan mıydı

O demler bir Mevlevihane vardı tam karşımda

huşu ile dönen semazenlerin

ahenkle çalınan kudümlerin

esrarı oruç nefeslerin

birde yanık neylerin

efkârı bulaşırdı

ya kanıma ya ruhuma

yada damgasız kadranıma

Peki şimdi nerede

o edepli o ahlaklı

naif yüce insanlar

nerede o sema ayinleri

buhur tütsüleri

Allah''a adanmış aşklar

çiçek açmış avuçlar

cennet kokan dualar

peki şimdi nerede

o ince o zarif ve kibar

merhamet dileyen kullar

Allah''a giden yollar

Oysa bir asır geçmişti aradan

eskiyen anılar mıydı

tükenen sayılar mıydı

yoksa Tokat Erenler

darda mezarda mıydı

Sonra hatırlıyorum da

bir Bey Sokağı vardı şuralarda

gerçi hala yerinde

duruyor durmasına da

o renk cümbüşü faytonlar

gelinlik bir kız gibi

artık süzülmüyor

camlarda cumbalarda

nal seslerinin tıkırtısı

tekerleklerin gıcırtısı

ve gizli aşkların

derinden fısıltısı

ne başımda ne taşımda

ne de duvarlarım da

artık yankılanmıyor ki

Ha unutmadan

birde Mevlana Hamamı vardı

canım öyle hamam deyip geçmeyin

efendi babadan kopartılan harçlıklarla

birgün önceden hazırlanıp gidilirdi

keyfi hoş sefalara

çimmeye yıkanmaya

aklanıp paklanmaya

hele o canım el emeği göz nuru

ince nakış dantelli

sandık dibi bohçalar

titiz bakır işçilik

hamamtası kildanlar

o mis gibi tertemiz

bembeyaz çamaşırlar

bir özenle katlanmış

ipekten peştamallar

küçük küçük peşkirler

pamuk gibi havlular

Hele birde ne kadar

kahkahayla gülerdim

- babanı da getirseydin len

diye bağıran o hamamcı karıya

eh gülmemek elde miydi ki

Dudu Ninenin kolundan

zorla çekiştirip

utancından moraran

yere bakan çocuğa

Daha hangisini sayayım

akşamdan yapılan börekleri mi

cevizli çörekleri mi

çemen etli keşkekleri mi

zeytinyağlı dolmaları mı

mahcup gelinleri mi

zarif görümceleri mi

yaşmaklı ve nur yüzlü

şişman kayınvalideleri mi

onlarda tarih oldu

onlarda kalmadı artık

sadece kalan Mevlana Hamamı

kiminin adı dudağında

kiminin tadı damağında

bende son kalan ise

sadece hevesi

o da takılı kaldı

sarkaçlı kursağımda

Eskiyen kapılar mıydı

ahşaptan yapılar mıydı

yoksa Tokat betona

gömülen tapular mıydı

Bilemiyorum

inanın bilemiyorum

ama yinede

zamanın o despot yüzsüzlüğüne

yitip giden silinen Kazova Üzümleri''ne

altımdaki toprağın

kanayan öfkesine

birde Gıjgıj Dağı''nın

o zehir gözlerine

inatla direniyorum

Oysa bir asır geçmişti aradan

ve sadece zamandı yerinde

hırlı mısmıl durmayan

ama naftalin kokuyordu dünya

ben Yüksekkahve''ye baktığım zaman

gerçi Yüksekkahve''de duruyordu yerinde

ama taksici Keçi Tahir''leri

matbaacı Pipo Fethi''leri

Madımağın Celal''leri

hatırlamaz her duyan

Sonra Uzun Tevfik vardı

otobüse bir biner pir binerdi

salepçi Remzi vardı

müteşebbis Vasfi Diren vardı

Nafa''dan emekli Ali Sucu vardı

yani kısaca o zamanlar

vakit bol 

hayat telaşsız 

ömür uzun

sadece kaldırımlar

birde sokaklar dardı

Mesela höllük nedir biliyor muydu

bugünkü yeniden yetme gençlik

bıldırcınbudu armudunu

göğsulu armudunu

kanlı sülük gırtlağını

devenin ham hamutunu

kömeyi pestili tarhanayı

incirlenmiş kara pekmezi bulamayı

Artık odun kömürlü semaverlerde

tavşankanı çaylar demlenmiyordu

ve keskin tömbeki kehribarlığında

aşikâr nargile üflenmiyordu

belkide bu sessizlik

höllüğün kumundandı

isyan ve özgürlükse

cep telefonundandı

Eskiyen zaman mıydı

bu Şehr-i Tokat mıydı

yoksa bacada tüten

küllenmiş duman mıydı

Hazır laf kucağa düşmüş iken

Bulvar Sineması''nı

Zafer Sineması''nı

Ali Sabri''yi de

anlatayım bari size

özel seans matinalar vardı eskiden

yazlık sinemalar tahta sandalyeliydi

kabak çekirdekleri

gözyaşı mendilleri

genç kız fingirdemeleri

kırık leblebi tadında

yerli yersiz filimler

komik ve eğlenceli

hem vurdulu kırdılı

hem romantik hazinkâr

umuma veya bayanlara

Türkan Şoray''lı Ediz Hun''lu

hicranın hıçkırıkları

ya buz kovalarına yatırılmış 

buz gibi Fertek gazozları

patlamış mısırlar

pamuk şekerler

halkalı şekerler

kaynana şekerleri

içinden artist çıkan

balonlu çikletler

gofretler misketler

zagorlar teksaslar tommiksler

ve daha neler neler

onlarda kalmadı artık

onlarda tarih oldu

Nerede o zamanlar renkli televizyonlar

bilgisayarlar şatafatlı reklamlar

bütün yük bar bar bağıran çığırtkanlarda

belkide adını tek unutamadığım

elinde megafonu

kır saçlı tok sesli Bekir Amca

bir bakarsın Horuç Sokağı''nda

bir bakarsın Devegörmez''de

bir bakarsın Behzat''ta

bazen elde yapılmış

bazen klişe baskılı

koca koca afişler

sırtındaki tahtada

Oysa bir asır geçmişti aradan

eskiyen Sultan mıydı

Türkan mı Şoray mıydı

yoksa filmin perdesi

siyah ve beyaz mıydı', 'Zamanın sarkaçları salkım saçak dökülürken bu Şehr-i Tokat''ın nasırlı ellerinden ben hala evde kalmış kız kurusu sevdalara aşık başı dik ve ...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":258,"source_url":"https://www.antoloji.com/zamanin-sarkaclari-tokat-saat-kulesi-nin-100-yili-anisina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küstüm Çiçekleri', 'kustum-cicekleri-halil-pazarli-587te', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen kaybolmuştun hani

çukur gamzeli o şehrin

otel Çağlayan''ında

O gece dolunay vardı

ve küstüm çiçekleri

birde pervaza yakın

pezevenk pencereleri

O gece ölüm vardı

ve balkon korkulukları

Trabya''ya uzaktı

kadın biraz kahraman

erkek biraz korkaktı

Sen kaybolmuştun hani

gemiler tedirgindi

ve balıklar ürkekti

koyu bir maviydi deniz

birazda karanlıktı

Sen kaybolmuştun hani

saat sabahın beşi

ezan okunur gibi

kimse aldırmıyordu

insanlar uyuyordu

ve sabahçı kahvesi

demli çay kaynıyordu

Sen kaybolmuştun hani

küstüm çiçeklerini suluyordu biri', 'Sen kaybolmuştun hani çukur gamzeli o şehrin otel Çağlayan''ında O gece dolunay vardı ve küstüm çiçekleri birde pervaza yakın pezevenk pencer...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kustum-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıyalım', 'aciyalim-ozgen-topcu-lfbsb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yar ne olur inat etme

Bu ayrılıktan cayalım

Kapıyı çarpıpta gitme

Aşkımıza acıyalım

Yalan varsa yok edelim

Düşman varsa kin güdelim

Elele tutuşup gidelim

Mazimize acıyalım

Durduralım hırsımızı

Deneyelim şansımızı

Düşünelim aşkımızı

Sevgimize acıyalım

Biz beraber güleceğiz

Gerekirse öleceğiz

Seviyoruz seveceğiz

Ömrümüze acıyalım

Acıyalım mazimize

Acıyalım sevgimize

Ne geçecek elimize

Kendimize acıyalım', 'Yar ne olur inat etme Bu ayrılıktan cayalım Kapıyı çarpıpta gitme Aşkımıza acıyalım Yalan varsa yok edelim Düşman varsa kin güdelim Elele tu...', ARRAY['Türk Edebiyatı','Şiir','Özgen Topçu']::text[], 8.5, '{"poet":"Özgen Topçu","poet_slug":"ozgen-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aciyalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duman', 'duman-osman-ufuk-yildirim-epwcx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağlamak zaman, zaman hıçkıra, hıçkıra

Sevilmeyip, yanmak O bir alev Sen se çıra

Kömürleşmek; Duygusuz kalıncaya dek o zaman,

kül atmak aşk üstüne, O bir kor, Sen se duman..', 'Ağlamak zaman, zaman hıçkıra, hıçkıra Sevilmeyip, yanmak O bir alev Sen se çıra Kömürleşmek; Duygusuz kalıncaya dek o zaman, kül atmak aşk ü...', ARRAY['Türk Edebiyatı','Şiir','Osman Ufuk Yıldırım']::text[], 8.5, '{"poet":"Osman Ufuk Yıldırım","poet_slug":"osman-ufuk-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/duman-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakal Abi...', 'hoscakal-abi-ugur-deniz-ulkegul-e42cy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“Ama bir şeyler biter…Yoğun da olsa,güçlü de olsa yenilir zamana…Yeni başlangıçlardır tesellimiz..

Eksik yada yarımda kalsa yaşadıklarımız,sonunda,

Hep kendimizi tamamlarız…”

Doğduğun vakit güneş tepedeydi..

Tarlada,aşına su verme telaşındaydı baban..

Vakitsiz geldin çocuk,

Bir ağaç gölgesinde doğurdu seni anan…

Önce tende ki tuz tadını duyumsadın,

Sonra içtiğin sütü doyumsadın..

Öküz yerine insan koşulurdu sabana..

Ocakta pişen ekmeğin yanına,

Kırılan bir baş soğan katılırdı çoğu zaman..

Ve insanlar şükretmesini bilirlerdi bir tas tarhana çorbasına…

Doğduğun vakit,

Yoksulluktan nasır tutan eller okşadı yüzünü önce.

Ve şehirler de ölüm kol geziyordu,

Bir el,bir sırt''a kurşun sıkıyordu arada bir,haince…

Helal süt verdiler sana büyü diye,

Mertliği namusu anlattılar,

Yalana hırsızlığa korkuttular,

Dostunu seçmeyi,yüreğini açmayı öğrettiler..

Yola çıktığın vakit bir avuç yol parası koydular cebine 

Bir de çıkınına az bir erik reçeli,bir somun ekmek yüklediler..

Adam olman değildi muratları,

Giderken tek tek sarıldılar göğsüne,

”Adam kal” dediler..

Ve sen..

Çok genç yaşta..

Böyle girdin kavgaya..

İstanbul’u ilk o zaman gördün..

İlk o zaman gittin Saray Burnu’na

Sahilde uzun uzun yürüdün..

Beş parasız kaldın günlerce,

Açlığını sabırla doyurdun..

Elden ayaktan düşürdü seni yorgunluğun..

Sonra bir gün

Kıyıda rastladığın ihtiyar yetişti imdadına..

Yavaşça yaklaşıp ardı sıra

Elini uzatınca tuttuğu balıkların kovasına,

_______Bir kez çalarsan bir daha hep çalarsın evlat..

Ve bu hayat çok namuslu insanı öğütmüştür değirmeninde..

Gel otur yanıma,derdin neyse söyle..

Demişti…

_______Açım! demiştin..Günlerdir açım..

Sadece..Sadece bir tane çalacaktım…

Bana bir tane verirmi siniz? 

_______Hayır..Sana bir tane balık vermem..

Ama sana bu olta takımlarından birini veririm.. 

Eğer tutmayı öğrenme niyetin varsa..

Yoksa..

Bende sana verecek bir azık da yok derim...

İşte sen,

İstanbul’u bir olta takımıyla yenmeyi böyle öğrendin.

O yaşlı ihtiyarı; baban yoktu belki yanında ama,

Baban kadar severdin..

O Şehir adamıydı..Sen köy çocuğu..

Ve nice dağ gibi adamları rezil ederdi bu şehir sarhoşluğu..

Yıllar geçti aradan..

Dostların oldu,arkadaşların..

İşin gücün oldu,değişti ve olgunlaştı düşüncelerin

Ve yanlış gittiğini,

Haksızca olduğunu fark ettin bir şeylerin…

Bildiklerin ve anladıklarını yazmaya başladın..

Durmadan yazmaya..

Okundukça daha çok insan gelir oldu yanına

Daha çok çalındı kapın

Ve daha çok sigara yakıldı çay içildi arkadaş toplantılarında..

Bir gün

Yazma artık diye bir not atıldı kapı altından..

Düşünme dedi birileri..

Zincire vur zindana kapat beyninde ki düşünceleri..

Her gün sokaklarda yürümeyi istiyorsan,

Seyretmek istiyorsan gökyüzünün alabildiğine maviliğini,

Çakıl taşlarını atabilmek için denize arada bir can sıkıntısından

Düşünme..Kendi iyiliğin için…

Denizde balık düşünmüyordu,

Sokakta köpek,

Ağaçta kuş..

Evet düşünmüyordu ayağına takılan taş,

Yerde biten çimen,

Ve yeri aydınlatan sokak lambaları..

Bir tek insandı..

Bir tek insanlardı bu yeryüzünde düşünebilen…

Ve düşünme demişlerdi sana,

Senin iyiliğini düşünen bir başkaları…

Oturdun bir gece yalnızlığında,

Sabaha kadar düşünmemeyi düşündün..

Olmuyordu,

Durduk yerde balık olamıyordu insan..

Yada bir köpek 

Bir kuş..

İstese de yerde ayak vurulan bir taş bir çimen kalamıyordu 

Düşünmeyince; 

Sokak lambası değildi ki asılı duran,

Kendi varlığını bile aydınlatamıyordu insan..

Sonra kendi insanlığın için vazgeçtin yürümekten,

Vazgeçtin gökyüzünün alabildiğine maviliğinden,

Denize çakıl taşları atmaktan ve….

Ve daha çok düşünür oldun..

Merhameti ve iyiliği yazdın önce..

Sonra bir gün; 

Adaleti ve onuru da ekleyince…..

Demirin soğuk bir yüzü vardır..

Ama onun kadar işe yarayan 

Başka bir maden yoktur yeryüzünde…

Bazen ağza giden bir kaşık olur

Bazen yüreğe saplanan kurşun..

Bazen yaşatmak için kullanılır

Bazen öldürmek için..

Bazense..

Yaşamakla öldürmek arasında bir yerlere hapseder insanı..

Demir parmaklıklar bunun için yapılmıştır..

O parmaklıkların ardında

Hayatın içinde ne varsa

Her şey özlemek adını alır..

Dostlarını özler,arkadaşlarını özler,

Sahilde kızarmış balık kokusunu,

Yanından geçen kamyon gürültüsünü,

Ağlayan bir çocuk sesini…

Evet gözyaşı döken bir çocuk sesini bile özler..

Özlemektir hayat içerde ki adam için..

Saate bakmaktan,

Takvime göz atmaktan tiksinir..

Ertelediği

Ve gelirken yol üstünde

Bir sabahçı kahvesinde 

Masanın üstünde bıraktığı umutlarını düşünmekten kaçar hep..

Zaman durur,

İnsan

Voltaların ardından

Zamansız bir mekana yürür mahpus da..

Saat başlarının bir önemi yoktur,

Güneşin doğması yada batması aynı yöndedir aslında..

İnsan hep aynı vaktin secdesine eğilir gibi durur,

Her sabah ezanında…

Zordu elbet..

Kolay olmadı zincire vurmak sevdalarını..

Seni değil sevdiklerini sürdüler hayatından..

Kol saatinin döngüsünü çaldılar içinde duran yelkovanından..

Zordu elbet..

Kolay olmadı bir zamanlar babana verdiğin sözde durmak..

Ve onlar….. 

Hiçbir şey eksiltemediler adamlığından…

Ve şimdi ben…

Her gün yeniden şükrediyorum sahilde rastlaştığımız o güne..

Bana anlamayı öğrettin..

Bildiklerimi,hayatın kirinden pasından saklamayı..

Dost olmayı,

Bunca düşmanlığın kol gezdiği memleket içinde,

Kendinle hep dost kalmayı..

El uzatmayı yaşlı bir kadının güçsüzlüğüne,

Ar etmeyi genç bir kızın masumiyetine 

Ve meydan okumayı 

Alçak onursuz bakışların bu yalancı düzenine..

Ama yine de..

Yine de erken gittin be abi..

Vakitsiz oldu gidişin de dünyadan

Tıpkı gelişin gibi....

Yarım kaldı bir şeyler aramızda..

Çay demleyecektim sana yine,

Yine bir sigara tüttürecektik karşılıklı

Ve ben yine en olmadık sorular soracaktım bilgeliğine..

Ekmek arası balık yiyecek 

Yine derinden bir Elif türküsü mırıldanacak 

Yine ertesi güne uykusuz sabahlayacak günlerimiz olacaktı..

”Bak evlat,görüyor musun? ” diyecektin..

”Neyi? ” diye sorduğumda 

“İnsanların görmediklerini..” deyip yine anlatacaktın..

”Göründüğü gibi değil hiçbir şey..

Bir bakışa rastlarsın bazen bir gülüşe..

Çoğumuz farkında olmadan yenik düşeriz bu aldanışa..

Neden gülümser bu insan,anlamalısın..

Parası mı çoktur,

Karısı mı güzeldir,

Mutlu mudur ondan mı gülmektedir karşındakine..

Yoksa bu tebessümle

Bir şeyler mi satmak istemektedir,böyleyse nedir sattığı? 

Dikkatle bak mutlaka görürsün..Kendini ele verir..

Uymayanı gözle,uyuşmayanı anlamaya çalış..

Aslında nedir sana anlattığı? ..

Takım elbise ama ütüsüz,

Ütülü ama mavi,

Mavi ama lekeli..

Ne satmaktadır adam anlamalısın..

Konuşman gerekmez,sorman gerekmez..

Bakarsan anlarsın..

Nedir bu tebessümün nedeni..

Esrar olabilir sattığı

Ya da şu gördüğün,

Ayaküstü yapılan bir kadın pazarlığı..

Kadın dediğim aslında çocuk..

Muhtemelen öğrenci..

Bu gülen adam tecrübeli bir pezevenk..

Gülüşünde merhamet yok,

Fazla samimi fazla rahat,fazla sırnaşık..

Her gün gelir ve her gün bu parkta saatlerce dolanır durur..

Devamlı telefonla konuşur……

Düzgün elbiseli ama işi gücü olmayan bir insan..

Sevecen ve yardımsever görünen..

Bazen buraya gelen ailelerin

Küçük çocuklarına şeker çukulata alır büfeden..

Başlarını okşar..

İnsanlarla oturur konuşur..

Ve yüzünde ki bu gülüşle yanıltır

Yanından geçen yüzüne bakan

Onu fark eden yada fark etmeyen insanları..

Ama Sen..

Yanılmamalısın…”

Ve hayat devam ede durur güzeli ve çirkini yan yana..

En yakınımızda ve bazen çok uzağımızda

Yeşerir insanların acıları,mutlulukları yüreklerinden..

Yarım kalır bazen söz dudağında insanın..

Hoşça kal diyememek

Çok daha ağır basar söylenen onca merhabadan..

Ama gidenler hep bir iz bırakır geride..

Dostsa eğer

Her daim sahici tebessümle gülümser durur yüreklerde…

Zaten budur böyle zamanlarda ağlatan insanı…

Sonra..Kendi gözyaşıyla büyür insan…

Diyemedim lakin şimdi söylüyorum..

Hoşça kal abi..

Hep sen kızardın arada bir kaytarmalarıma

Biliyorsun..

Bozulma ama,

Bu sefer ben kızıyorum yokluğuna…

Hem de çok fena…', '“Ama bir şeyler biter…Yoğun da olsa,güçlü de olsa yenilir zamana…Yeni başlangıçlardır tesellimiz.. Eksik yada yarımda kalsa yaşadıklarımız,s...', ARRAY['Türk Edebiyatı','Şiir','Uğur Deniz Ülkegül']::text[], 8.5, '{"poet":"Uğur Deniz Ülkegül","poet_slug":"ugur-deniz-ulkegul","theme":"Türk Şiiri","is_hero":false,"total_lines":226,"source_url":"https://www.antoloji.com/hoscakal-abi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeyh Şamil', 'seyh-samil-necmiye-sarpkaya-gmd3j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her şeyden üstündü  senin için 

İzzet ve haysiyet cesaret fedakarlık

Yiğitlik acı ve hicran

Gözyaşları katıktı ekmeğine 

Hürriyet ve istiklal denince 

İlk senin adın gelirdi akla

Hayat sayfan başlar ilim ve savaşla

Sınavın zor olarak hazırlanmıştı

Mertlikle devam eder hayat defterin

Hocan Mevlana Halid-i Bağdadi 

İlim ve irfan yuvası Bağdat dan 

Yetmedi  ilimleri tahsil etmek Şeyh olmak 

Edebiyat tarih fen bilimleri ile devam ederdi 

Vazgeçemedin savaş da barış da asla kitaplardan... 

Neydi hayat senin için neydi 

Bazıları için rahat ve tatlı olan hayat 

Savaş kan sıkıntı cefa zulüm çile

Düşmanların için 

Korku panik ölüm yiğit

Gözüpek kahraman kararlı ve azimli

Bir komutan bir ateş parçası bir arslan

Tehlikedeydi artık vatanın milletin

Bütün mukaddes değerler

Asır xıx. asır başları 

Sanayi devriminin ardından 

Yağma sömürge talan 

Sıcak denizlere açılma hayali 

Kafkasları geçerek inmek Anadolu 

Üzerinden Akdenize

Dikildin dimdik düşmanın karşısına

Göğsündeki süngü durduramazdı seni asla

Yirmi beş günlük baygınlıktan sonra 

İlk sorun ''Ana namaz vakti geçti mi ''oldu

Seni milletini ayakta tutan neydi 

İnanç mıydı azim miydi

Kararlılık mıydı 

Cesaret miydi

Kahramanlık mıydı 

Alimlik miydi 

Bunlar sende doğuştan mevcuttu

Dağıstanlıları Çerkezleri Çeçenleri Avarları

Topladın tek ülkü etrafında

Savunma ve Hürriyet 

Birliği beraberliği sağladın.

Sen zor günlerin zor dönemlerin 

Adamı değil miydin ne olsa

Kar etmedi sana asrın 

Topu tüfeği süngüsü askeri siyaseti

Ekonomisi Lojistiği 

Hiçbir şey kar etmedi sana 

Hile kurnazlık entrikalarayak oyunları 

Kar etmedi sana... Satın alınamadın asla 

Hiçbir değerle... 

Sana Hürriyetine milletine 

Karşılık sulh teklifi geldi 

En kıramayacağın anandan yarinden.. 

Oysa mecbur bırakılmıştı mübarek

Eli öpülesi senin gibi evlat yetiştiren

Şanlı...Ana

Karar kesin hüküm verildi 

''Annem cezalandırılacak 

Bir tarafta ana can dost.. 

Diğer tarafta

Namus İstiklal Mücadelesi 

Haysiyet ve onur sınavı

Çözümü buldun pratik müthiş zekan ile

Gösterdin karlılığını ve azmin zaferini

Kendini kırbaçlatarak dosta düşmana.

Medine de uydun son çağrıya

Ebedi aleme gel çağrısına 

Defnedildin Kahraman asker

Kahraman Komutan Şeyh Şamil

Sevgili Peygamberime komşu oldun

Cennetül Baki Kabristanında

Sen rahat ol cesur yürek 

Sen rahat ol 

Hala ayaktayız 

Hala Anadolu’ya Birileri inemedi 

Sıcak Denizlere 

Geçilemez Anadolu asla 

Sen rahat ol

Necmiye Sarpkaya', 'Her şeyden üstündü  senin için  İzzet ve haysiyet cesaret fedakarlık Yiğitlik acı ve hicran Gözyaşları katıktı ekmeğine  Hürriyet ve istikla...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/seyh-samil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı Gül', 'kirmizi-gul-osman-ufuk-yildirim-m5uty', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülü seviyor diye bülbül; Diken saplanır bağrına, kan gelir.

Ve aşk''ı temsil etsin diye bu kan; Gül''e kanın rengini verir..', 'Gülü seviyor diye bülbül; Diken saplanır bağrına, kan gelir. Ve aşk''ı temsil etsin diye bu kan; Gül''e kanın rengini verir.....', ARRAY['Türk Edebiyatı','Şiir','Osman Ufuk Yıldırım']::text[], 8.5, '{"poet":"Osman Ufuk Yıldırım","poet_slug":"osman-ufuk-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/kirmizi-gul-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Abdal', 'abdal-ela-somit-tihzb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '............kimbilir..............

Aşk...

Aşkı yaşıyor muyuz acaba? 

Ya da hissedebiliyor muyuz? 

Hissedemediğimizde olan ne? 

Bilmem...

Ben göremiyorum....

Çalışıyorum; 

Çabalıyorum

ama.....

HAYIR! ! ! 

Olmuyor,

Ağlıyorum çünkü başaramıyorum....

Ben aptal mıyım

yoksa abdal mıyım? 

Nedir içinde kaybolduğum boşluk,

Ve de nedir tırmalamaya çalıştığım bu amansızlık...

Bilmem duyuyor musun bu hıçkırıkları

Bu karın kasılmalarını...

İşte burda başlar ufak ufak dokunmalar

VE

İşte burda devam eder acı acı gülümsemeler

Belkide burdadır asıl bitiş

Asıl inciniş....

.................belkide................', '............kimbilir.............. Aşk... Aşkı yaşıyor muyuz acaba?  Ya da hissedebiliyor muyuz?  Hissedemediğimizde olan ne?  Bilmem... Ben...', ARRAY['Türk Edebiyatı','Şiir','Ela Somit']::text[], 8.5, '{"poet":"Ela Somit","poet_slug":"ela-somit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/abdal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ZiNA', 'zina-mine-ozdemirtas-mpgc2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'seni gidi küçük adam

seni gidi püsküllü bela

pis rotgenci,

takiyeci,külliyeci zırtapoz

ne işin var yatak odamda? 

kalbi bozuk / aklı uçkurunda.

işgüzar,ukala

hayrola? 

özelime bu ne alaka? 

yoksa! 

kilidi senmi vuracaksın sandığıma? 

hangi hakla? 

eğilde bir bak kendi çıkınına.

sakın ola

bir gün dönüp te

boğazındaki yağlı ilmiğin 

sebebini bana sorma.

onun adını 

şimdiden takdimimdir ki

o ilmiğin adı:

ZİNA.

ve sen hala

yüzsüzce durabiliyorsan ayakta.

yuh sana alkış tutana.

ışıkları kim söndürdü? 

bu ne karanlık bir dünya.

16/09/2004..(susmayı başaramadım)', 'seni gidi küçük adam seni gidi püsküllü bela pis rotgenci, takiyeci,külliyeci zırtapoz ne işin var yatak odamda?  kalbi bozuk / aklı uçkurun...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/zina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An', 'an-zeynep-karabagli-2oa10', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AN

 Çok yazdım senin için

           gündüz gece

                dün yarın gibi

      Alev renkli pelerinle nöbet tuttum kapında,

      Kimi zaman   gözlerini kör etmek  için kızgın demirle

                                                                     bekledim seni…

       Focutcon’  nun  kitabından cımbızla çekildim deli olarak

       Zamanı bir sandık  içine tıktım

       Ferajemle gözlerimi kapatmıştım.

       Cami tabutu yorgun ölü taşımaktan mezara

      Tohumların  üzerine atom santrelleri kurulmuş 

      Doğmak sıkı bir bohça içinde

      Alev renkli pelerinle nöbet tuttum kapında,

      Kimi zaman  gözlerini kör etmek için kızgın demirle 

                                                                    bekledim seni…

      Çöp yığınları arasında   rüzgar oldum koklamak için gövdeni

      Hiç elveda olmadın sen hep merhabaydın sokakta 

      Şu koca Dünyada nar taneleri gibi sıkışıktık

      Yan yana düşmüştük işte öyle…..

       Leyla,Jülyet,Aslı  yerlerinden fırladılar 

       Tüm aşık mezarları açıktı o saba

       Tekrar  bulduk diye aşkı  eğlence yaptık

                               Babilde asma bahçelerde 

        Kuyruklu yıldız ışığıydı,

        Yıllar sonra tenimize  deyen sıcaklıktı o

        O ışık altında  bir kez kalmak yetiyordu insana

        İşte aşıktı o hayata

        Aşk ışığıydı

        Sadece  an da.

                                       ZEYNEP KARABAĞLI', 'AN  Çok yazdım senin için            gündüz gece                 dün yarın gibi       Alev renkli pelerinle nöbet tuttum kapında,       Kimi...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Karabağlı']::text[], 8.5, '{"poet":"Zeynep Karabağlı","poet_slug":"zeynep-karabagli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/an-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hataydı Affına Kaldı', 'hataydi-affina-kaldi-hakan-ayaz-5xucw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'göz yaşlarımdan boğulmazsam 

anlatıcam sana herşeyi 

neydi ve ben ne halde

seni aradım bilmediğin meyde

saklamanın bi anlamı yok

yitiriyoruz birbirimizi 

anlatmalı sana bu adamı

sen ne kadar desen de çocuk olan adamı

hiç bilmediğim ve tanımadığım bi mevsimdi

kış değilk yaz hiç değildi

ben ağlıyordum veremediğim borcuma

tek tesellim dostlardı mey içtiğim

bilseydeim ne kapısından geçer 

nede sokağına girerdim

ben bilmiyordum beni 

ne kadar dağınık olduğumu

şimdi anlatıyorum sana

ben ben değil beni çoktan geçmiş

bilmediğim bi yerde bilmediğim birileriyle

seni anlattım ilk ama anlamadılar beni

ben benden ne kadar uzakmışım 

bilemdim düşmanları

dost gördüğüm ahinleri

şimdi anlamsız 

anlatmak bu kuçuk adamı

bilseydim eğer hiç batırmazdım 

tutmazdım elini kirletmezdim seni

seni çok seviyorum 

inanmazsın bu adama belki

peki ben bi çocuğum

ve çocukken aşık oldum 

senin ellerinde adam oldum 

çok seviyorum seni

ne olur anla beni', 'göz yaşlarımdan boğulmazsam  anlatıcam sana herşeyi  neydi ve ben ne halde seni aradım bilmediğin meyde saklamanın bi anlamı yok yitiriyoruz...', ARRAY['Türk Edebiyatı','Şiir','Hakan Ayaz']::text[], 8.5, '{"poet":"Hakan Ayaz","poet_slug":"hakan-ayaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hataydi-affina-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
