INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Seninle Sevgili Olamadık Sevgili', 'biz-seninle-sevgili-olamadik-sevgili-ahmet-aksoy-e0xby', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '................''Beni terk ettiğin gün anladım

