INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecemi Sarıya Boyamam', 'gecemi-sariya-boyamam-baykal-kaanalp-j2ci2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'suyun akışına sakinim

dalgalansada ruhum

ne kervanlar geçer önümden

ne ben yol geçenim

uğramaz olur ocağıma

sıkıntılı beklentiler

ben de eklemem zaten

yeni bir soğukluk sıcağıma

taşırmam yokluğunu dışarıya

alamasamda boşluğuna yumruğu

bir bezginlik yok inan ki

boyamam gecemi sarıya

ya tilkiler bulamaz yolumu

başımda ağrır başlıbaşına

kanlı geceler sinemalar bomboş

kaptırırım yalnızlığa kolumu', 'suyun akışına sakinim dalgalansada ruhum ne kervanlar geçer önümden ne ben yol geçenim uğramaz olur ocağıma sıkıntılı beklentiler ben de ekl...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecemi-sariya-boyamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
