INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kârda Gibiyim!', 'k-rda-gibiyim-zulfikar-yapar-kaleli-5ticq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

“Ben de sevdiğimi kimseye söylemem..”

Uğraştım, aradım bulmadım iyi

Bilmiyorum kaçırdım mı ölçüyü

Çok aradım yare giden elçiyi

Boşa iz sürsem de, kârda gibiyim.

Her sabah, her seher kalkarım erken

Yanık yanık ağlamışım gülerken

Karşılık olmasın, severim derken

Ham hayal kursam da, kârda gibiyim.

Arzum nedir, efkarım ne sezen yok

Bağlarımda baykuş öter, gezen yok

Anlayan yok, ıstırabım yazan yok

Kalemi kırsam da, kârda gibiyim.

Yollar kar, mevsim kış bitiremem ki 

Yük ağır, yol yokuş götüremem ki

Yaralar bir bakış, yatıramam ki

Uzaktan görsem de, kârda gibiyim.

Gönlümde bir telaş, ruhumda darlık

Hayalime sığmaz dünyalık, varlık

Verseler neylerim sultanlık, yarlık

Yerlere girsem de, kârda gibiyim.

Ak dediğin ak etmedi yüzümü

Garip kulum, tutan olmaz sözümü

Gün karardı ağ bürüyor gözümü

Bin gönül versem de, kârda gibiyim.

Eylül 2004', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' “Ben de sevdiğimi kimseye söylemem..” Uğraştım, aradım bulmadım iyi Bilmiyorum kaçırdım m...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karda-gibiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hesap Sor...', 'hesap-sor-i-mdat-ozcan-qy46u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün yesin tüm vurgunları

Sen hesap sor

Haykır dağa-taşa

Haykır deli dolu hoyratlarca

Hesap sor

Terketmeden gülüşleri

Yakalayıp umutları yakasından

Haykır karanlığa

Çınlasın sesin 

Varsın yarılsın gök

Varsın delinsin yer

Takılı kalsın resmin gölgelerde

Adımla sevdanın sokağını

Haykır kaldırımlara

Yakar mı seni bu ateş

Kanatır mı yüreğini kahpe bıçağı

Kör kurşunlara sal tebessümünü

Hesap sor...', 'Gün yesin tüm vurgunları Sen hesap sor Haykır dağa-taşa Haykır deli dolu hoyratlarca Hesap sor Terketmeden gülüşleri Yakalayıp umutları yaka...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hesap-sor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekler', 'gercekler-abdullah-atay-3rfj9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kadın 

elbisesi lime lime... 

beti benzi açlıktan solmuş 

bir elinde aç çıplak bebesi 

bir elinde de boş pazar filesi. 

akşamın dar saatinde 

derdini içine 

çöpteki kırıntıları da 

torbaya atıyordu... 

aynı saatlerde 

bir başka kadın 

yırtmaçlı 

şık dekoltesiyle 

