INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük Marşları Okuyun marşlarımızı dağlarda', 'ozgurluk-marslari-okuyun-marslarimizi-daglarda-yusuf-ter-x2ws1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özgürlük türkülerini söyleyin

Okuyun marşlarımızı dağlarda

Dur durak bilmeden yolu boylayın

Okuyun marşlarımızı dağlarda

Vietnamlı Kübalıdır yoldaşlar

Çinli çekik gözlüdür arkadaşlar

Ne olur söyleyin yine gardaşlar

Okuyun marşlarımızı dağlarda

Afganlı çocuklarımızın dünü

Orta Doğu kanlı şiirler günü

Hem kanıyor hem ağlıyor her yanı

Okuyun marşlarımızı dağlarda

Elinde silahlar dilinde marşı

Hürriyet kavgalarında dır aşı

Unutmayın sakın böyle yoldaşı

Okuyun marşlarımızı dağlarda



II

Bir tek türküler vardır yanlarında

Viran Mahpushane zindanlarında

Ağıtlar yıkanıyor kanlarında

Okuyun marşlarımızı dağlarda

Dara koyulur düşüncelerimiz

İşkence doludur gecelerimiz

Durmadan söyle der hocalarımız

Okuyun marşlarımızı dağlarda

Filistin de örülüdür duvarlar

İsrail oğullarını döverler

Doğru söyleyeni köyden kovarlar

Okuyun marşlarımızı dağlarda

Devrimindir altmış sekiz kuşağı

Aydınlık ister memleket uşağı

Hile yalana banmayız kaşığı

Okuyun marşlarımızı dağlarda



III

Tüm kore dağlarımız yankılanır

Kızıl bayraklarımız dalgalanır

İnsanımız her yerde sorgulanır

Okuyun marşlarımızı dağlarda

Sarıkamış Yemende dır ölümler

Doksan bin yiğit te yatar kalımlar

Ne zaman bitecek bunca zulümler

Okuyun marşlarımızı dağlarda

Amerika hep Irak’a vuruyor

İnsanlar gözünü dikmiş duruyor

Her bir yanımızı acı sarıyor

Okuyun marşlarımızı dağlarda

Yusuf ‘um yürekte türküler bitmez

Yol verin haydi bize yollar yetmez

Bir gün gelir canlar bunları yutmaz

Okuyun marşlarımızı dağlarda

Yusuf Ter 28.09.04

Saat.15:41 İsviçre', 'Özgürlük türkülerini söyleyin Okuyun marşlarımızı dağlarda Dur durak bilmeden yolu boylayın Okuyun marşlarımızı dağlarda Vietnamlı Kübalıdır...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ozgurluk-marslari-okuyun-marslarimizi-daglarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun', 'kursun-mehmet-halil-wlqep', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğitim özel, sağlık özel, yol özel,

Ülkeyi idare etmek; ah! Ne güzel.

Ödenen vergiler, silaha  yeterli.

Gücümüz, sıkılan kurşuna bedel.', 'Eğitim özel, sağlık özel, yol özel, Ülkeyi idare etmek; ah! Ne güzel. Ödenen vergiler, silaha  yeterli. Gücümüz, sıkılan kurşuna bedel....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Halil']::text[], 8.5, '{"poet":"Mehmet Halil","poet_slug":"mehmet-halil","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kursun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam', 'adam-sami-akman-zyydv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adam bitap düşmüştü

Bedeni yorgundu

Düşünceleri çaresiz.

Usulca uzanıverdi, yastığına

Kimse yoktu yanında

Belli birini arıyordu....

Ama boştu yanındaki yastık

Sonra birden titredi dudakları

Gözleri dolu verdi

Süzülüverdi gözlerinden

Yaşlar şuursuzca

Islandı başını koyduğu yastık

Ağlıyordu yalnızlığa,çaresizliğe

Ağlıyordu sevgisizliğe

Belli ki  seviyordu birini..

Belki bir hayal di

Belki bir gerçek

Ama seviyordu işte

Umutsuzluğa kapılıyordu bazen

Düşüyordu çaresizliğin girdabına

Gel diyordu uzaklardan

Gel de paylaş beni

Sevgini ver bana

Boş kalmasın yastığım

Umutlarım kırılmasın

Öldürme beni sevgisizlikten

Diyordu.....

Öldürme beni SENSİZLİKTEN

Biliyordu gelmeyecek

Biliyordu seviyorum demeyecek

Ve biliyordu sevmeyecek...

Adam bitap düşmüştü

Bedeni yorgundu

Düşünceleri çaresiz

Öldürme beni sevgisizlikten

Diyordu....

Öldürme beni SENSİZLİKTEN.......

®©', 'Adam bitap düşmüştü Bedeni yorgundu Düşünceleri çaresiz. Usulca uzanıverdi, yastığına Kimse yoktu yanında Belli birini arıyordu.... Ama boşt...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/adam-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adı Aşk', 'adi-ask-sami-akman-rj8ao', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gülüşle bir öpüş

İkisi de sıcacık

Süzülen bir bakış

Kalpten kalbe giden

Sonra bir ürperiş

Tatlı bir titreyiş

Ve içinde bir heyecan

Dayanılmaz yakıp kavurur

Alıp seni bir rüzgar gibi

Oradan oraya savurur

Sonra okşar saçlarını

Teninin yumuşaklığını

Kokunu alır içine

Derinden alınmış bir nefes gibi

İçin titrer ürperirsin

Dayanılmaz ve karşı konulmaz

Bir istek sarar benliğini

Oysa istediğin erişilmez

Adını koyamazsın

Adı Aşk.......

®©', 'Bir gülüşle bir öpüş İkisi de sıcacık Süzülen bir bakış Kalpten kalbe giden Sonra bir ürperiş Tatlı bir titreyiş Ve içinde bir heyecan Dayan...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/adi-ask-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Düşün', 'beni-dusun-akin-tekin-xztnn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni düşününce

Bir tebessüm gelip yerleşiyorsa yüzüne

Hep beni düşün

Yüreğinde tatlı kıpırtılar hissediyorsan

Gözlerin ışıldıyorsa bir anda

Sana mutluluk veriyorsa beni düşünmek

Hep beni düşün

Zor anlarında düşün beni

Sıkıldığın

Ya da öfkelendiğin zamanlar

Müsekkin etkisi yapıyorsa beni düşünmek

(ki bana oluyor bu)

Ne olacağını düşünmeden düşün beni

Brezilya yemekleri yerken düşün beni Rodizio''da

Dilindeki pas tadının silindiğini hisset

Bir kaçış planının son durağı gibi düşün beni

Bir dağın gözlerinde patlayan tomurcuk gibi

Fesleğen kokularıyla yürürken düşün beni

Sesinde serçeler uçuşsun

Kelebekler konsun ipek  saçlarına

Gökyüzü gibi düşün beni,mavi

Ki fırtınakuşlarının rengidir

Çevir gözlerini denize doğru

Gemiler görürsün mavi sularda

Gemiler

Musa''nın asasına benzetirim ben gemileri

Onlardan birine yükleyip hasretini-ne kadar varsa-

Bir selamınla birlikte yollarsın bana

Bütün gemiler bana gelir çünkü

Ne kadar rüzgar, ne kadar yalnızlık varsa

Toplayıp okyanuslardan getirip atarlar önüme

Sevmek yalnızlıktır derdi eski bir dostum

Senden gelecekse yalnızlık, başım gözüm üstüne

Beni hep sevgiyle düşün', 'Beni düşününce Bir tebessüm gelip yerleşiyorsa yüzüne Hep beni düşün Yüreğinde tatlı kıpırtılar hissediyorsan Gözlerin ışıldıyorsa bir anda ...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/beni-dusun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatan Sevgi', 'aglatan-sevgi-sami-akman-93qr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlayan sesin var kulaklarımda, halâ çınlayan,

Deli esen rüzgarın uğultusu gibi,

Gözpınarlarından süzülüp akan göz yaşların,

Saplanıyor yüreğime, paslı bir hançer gibi.....

Gözlerinden süzülüp yanaklarına akan yaşları,

Silemedim, uzanamadı sana, kırılası ellerim, 

Sen yüreğindeki sesi dinledin, bense ağlayan sesini,

Yüreğim kan ağladı, dokunamadım sana.....

Ağlayan sesin var kulaklarımda, halâ çınlayan,

İçindeki sevgiyi gözyaşlarından akıtan,

Yüreğin var, sıcacık aşkını içinde saklayan,

Sevgi var damarlarında dolaşan.....

Hasret var hıçkırıklara yansıyan,

Özlem var şarkılarda giderilmek istenen,

Gözler var hayâllere dalan,

Kulaklar var andıkça adını çınlayan.....

Yâr var; özlemle, hasretle anılan,

Sevgili var; delicesine sevilen, ulaşılamayan,

Bir sen varsın; benden öte de bir can,

Ağlayan sesin var kulaklarımda, halâ çınlayan.....

®©', 'Ağlayan sesin var kulaklarımda, halâ çınlayan, Deli esen rüzgarın uğultusu gibi, Gözpınarlarından süzülüp akan göz yaşların, Saplanıyor yüre...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aglatan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ama Yüreğim', 'ama-yuregim-sami-akman-7x800', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bak ağlıyorum işte

Bu gece son gecemiz

Belki bir daha görüşemeyiz

Sabahı bekleyemeyiz buralarda...

Bak ağlıyorum işte

Umudun tükenişinde, yaşamı düşünüyorum

Seninle birlikte! 

Bazen tebessümle, bazen surat asarak

Sabahın ilk ışıklarıyla, gideceğini bekliyorum

Gülümsüyorum sen giderken ardından

Ama yüreğim! 

Yüreğim parçalanıyor sanki her ayrılıkta

Geleceğin akşamı bekliyorum umutla

Saatleri birbirine doluyorum

Sanki bir demet çiçek yapar gibi

Gökyüzüne bakıyorum

Gecenin karanlığında

Gökkuşağını  görür gibi

Yıldızlara bakıyorum dilek tutar gibi

Bak ağlıyorum işte....

®©', 'Bak ağlıyorum işte Bu gece son gecemiz Belki bir daha görüşemeyiz Sabahı bekleyemeyiz buralarda... Bak ağlıyorum işte Umudun tükenişinde, ya...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ama-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlarmısın', 'anlarmisin-sami-akman-u0m0w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlarmısın gölgelerde 

Ayak izlerini aramayı

Savrulup giden toz bulutlarında

Saçlarından  bir tel bulmayı

Anlarmısın

Rüzgarlarda öpüşmeyi aramayı

Dudaklarında gül koklamayı

Anlarmısın... 

Yüreğinden  giden

Kan kırmızı sevdayı

Anlarmısın...

®©', 'Anlarmısın gölgelerde  Ayak izlerini aramayı Savrulup giden toz bulutlarında Saçlarından  bir tel bulmayı Anlarmısın Rüzgarlarda öpüşmeyi ar...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlarmisin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatsam', 'anlatsam-sami-akman-fs8v5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana anlatsam

İçimdekini olduğu gibi

Dilimin döndüğü

Kalemin yazdığı

Gökyüzünden

Yıldızların kaydığı gibi

Hani güneş

Nazlı doğar ya,

Hani bülbül

Güle nazlanır ya,

Hani şelalede

Sular çağlar ya

Hep söz verirdin

Arayacaktın

Uçan kuşa

Yıldızlara soracaktın

Her gün özlemini,

Sevdiğini yazacaktın

Sana anlatsam

Olduğu gibi

®©', 'Sana anlatsam İçimdekini olduğu gibi Dilimin döndüğü Kalemin yazdığı Gökyüzünden Yıldızların kaydığı gibi Hani güneş Nazlı doğar ya, Hani bü...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anlatsam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Karanlık', 'ay-karanlik-sami-akman-1iyf2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzaklardan gelir sesin

Nefesini duyarım rüzgarlarda

Sanki okşar gibi yüzümü

Saçlarına değmiştir diye koklarım....

Bulutlara bakarım ellerindir diye

Bembeyaz tenini anımsatır okşarım

Yıldızlara bakarım gözlerindir diye

Sağanak yağmurlar gözyaşındır diye silerim....

Ay karanlık, geceler uzun

Sessiz gecelerde beklediğim sensin

Kalbim deli gibi attığında, kulakların uğuldarsa

Bil ki çok özlenmişsin....

Özlemin güneş gibi yakıyorsa

Hasretin karlar gibi eritiyorsa

Bu can sevgini istiyorsa

İzin ver vuslata sensiz ermesin....

Uzaklardan gelir sesin

Ellerini tutmak isterim nerdesin

Bilirsin kalbimin en derin yerindesin

Seviyorum seni canım nerdesin? ? 

®©', 'Uzaklardan gelir sesin Nefesini duyarım rüzgarlarda Sanki okşar gibi yüzümü Saçlarına değmiştir diye koklarım.... Bulutlara bakarım ellerind...', ARRAY['Türk Edebiyatı','Şiir','Sami Akman']::text[], 8.5, '{"poet":"Sami Akman","poet_slug":"sami-akman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ay-karanlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hünkarım Var Benim', 'hunkarim-var-benim-ali-riza-unal-cwooo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevda denizine çekme, kaptanım var benim

Gönlümde o derya bir tekne, efkârım var benim

Meşkhane gönlüm şirin olmuş Leyla gibi Mecnun’a

Sineyi tahtıma hükmeden, hünkârım var benim', 'Sevda denizine çekme, kaptanım var benim Gönlümde o derya bir tekne, efkârım var benim Meşkhane gönlüm şirin olmuş Leyla gibi Mecnun’a Siney...', ARRAY['Türk Edebiyatı','Şiir','Ali Rıza Ünal']::text[], 8.5, '{"poet":"Ali Rıza Ünal","poet_slug":"ali-riza-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hunkarim-var-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Darıxma', 'darixma-ahmet-hani-hldgn', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yatmayın zaman geder

ölkeden kervan geder.

gözlerim darıxmayın

dağlardan duman geder.', 'yatmayın zaman geder ölkeden kervan geder. gözlerim darıxmayın dağlardan duman geder....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/darixma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-sair-ahrazi-cbe60', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Devranla batan varsa bahtıyla yatan benim,

Bahtıyla yatan varsa devranlı vatan benim,

Sırdan haber alsan da hem sırla nişan veren,

Hem sırdaki perdeyle gözler kapatan benim.

***', 'Devranla batan varsa bahtıyla yatan benim, Bahtıyla yatan varsa devranlı vatan benim, Sırdan haber alsan da hem sırla nişan veren, Hem sırda...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sir-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşq eli', 'esq-eli-ahmet-hani-57ecq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'salamıma cavab ver

eşq elile şerab ver.

ürekden el çek ay qem

sen allah az ezab ver.', 'salamıma cavab ver eşq elile şerab ver. ürekden el çek ay qem sen allah az ezab ver....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/esq-eli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-serdar-atasever-utjkz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Beş para etmez bir dünya

Değersiz bir aşk,

Sokakta bedenini satan kadınlar

Koltuk başındakilerinin yalanları.

Ve bir yanda emperyalizm 

Diğer yandan barış diyerek; 

Dünyaya pislik yayan para babaları

Sinmiş herşeyi sinesine çekmiş halk

Durdurulmaz olan yalanlar

Kendisini mutluluğa adamış 

Fakat kendiside mutluluğa inanmamış insanlar

Sürekli gelen ezan sesi

Ve sahte müslümanlar.

Bir de bunlar yetmiyormuş gibi.

Sürgün insan,sürgün beden ve ben,

Utanmaz bir aşkın peşinden koşmuş.

Yalnızlığımda ise yaralı kalbimle...

Hayatı yazmışım.

Şimdi herşey boşluktan öte.

Söyleyin yer gök ve inandıkları tanrı,

Benim varmı size zararım.', 'Beş para etmez bir dünya Değersiz bir aşk, Sokakta bedenini satan kadınlar Koltuk başındakilerinin yalanları. Ve bir yanda emperyalizm  Diğe...', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yalan-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Başımda', 'aklim-basimda-erol-dal-2jzw9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulut hafiften kararmaya başladı evlat.

Yağmur düştü düşecek.

Kapanmadan kapısı göğün

Varsam iyi olacak. 

Önde giden

Önce. Vurulur.

Kalan, iki dirhem leblebi,

Tomar, tomar yazılmış mısralar

Isınmak için artık.

Şiir yanıyor

Isının, yanın hatta 

Ey insanlar.

Göğün arka kapısından girdim.

Aklım hala,

Başımda…

…

Başımda da insanlar.

/87/Mekan', 'Bulut hafiften kararmaya başladı evlat. Yağmur düştü düşecek. Kapanmadan kapısı göğün Varsam iyi olacak.  Önde giden Önce. Vurulur. Kalan, i...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aklim-basimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Utanıyorum', 'utaniyorum-serdar-atasever-g9hvs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimde hayalinin yorgunluğu,

Yüreğimde sensizliğin bitkinliği,

Hala kalbimdeki solgunluğu,

Sana söylememiş olduğum için.

Bu bitmez tükenmez aşkı

Sıralara, defterlere yazdığım için

Seni senden daha çok sevdiğim için

Kendimden utanıyorum', 'Gözlerimde hayalinin yorgunluğu, Yüreğimde sensizliğin bitkinliği, Hala kalbimdeki solgunluğu, Sana söylememiş olduğum için. Bu bitmez tüken...', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/utaniyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aradım', 'seni-aradim-serdar-atasever-s8pco', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonu olmaz bir ufkun akşamında...

Özleminle yanarken.

Avuçlarımda ayrılık.

Sokaklarımda hüzün.

Seni aradım.

Bulamadım...', 'Sonu olmaz bir ufkun akşamında... Özleminle yanarken. Avuçlarımda ayrılık. Sokaklarımda hüzün. Seni aradım. Bulamadım......', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/seni-aradim-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı Sevda', 'yalanci-sevda-serdar-atasever-ccvva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kavuşmaksa,

Biz seninle hiç kavuşmadık.

Sevmekse,

Biz birbirimizi hiç sevmedik.

Yaşamaksa.

Biz birbirimiz için yaşamadık.

Ölmekse,

Biz birbirimiz için ölmedik.

Yalansa,

Gözlerimize rağmen hep yalan söyledik.

Birleşmekse,

Bizde o cesaret yok.

Aşksa,

O sadece bende var 

Ağla şimdi sabaha kadar 

Sende yok', 'Kavuşmaksa, Biz seninle hiç kavuşmadık. Sevmekse, Biz birbirimizi hiç sevmedik. Yaşamaksa. Biz birbirimiz için yaşamadık. Ölmekse, Biz birbi...', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yalanci-sevda-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhumun Sessizliği', 'ruhumun-sessizligi-serdar-atasever-nf5ip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Önce umutsuzluğa düştüm.

Sonra karanlığa,

Ve şimdi aydınlıktayım.

Tek başıma yalnızım

Hasret yüklü bir gemiyim.

Olmayan limanlarda 

Olmayan kişileri arıyorum

Nerde bir ışık görsem

Yelken açıyorum oraya doğru.

Belki sensin diye

Ama yanılmışım...

Seni ben zaten geminin içinde kaybetmişim..', 'Önce umutsuzluğa düştüm. Sonra karanlığa, Ve şimdi aydınlıktayım. Tek başıma yalnızım Hasret yüklü bir gemiyim. Olmayan limanlarda  Olmayan ...', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ruhumun-sessizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-serdar-atasever-qoya4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çıkar kırmızılarını üzerinden...

Kimse görüp seni sevmesin,

Aşkı bir roman gibi yazıp.

Önüne koysam..

Biliyorum sen yine beni sevmezsin...', 'Çıkar kırmızılarını üzerinden... Kimse görüp seni sevmesin, Aşkı bir roman gibi yazıp. Önüne koysam.. Biliyorum sen yine beni sevmezsin......', ARRAY['Türk Edebiyatı','Şiir','Serdar Atasever']::text[], 8.5, '{"poet":"Serdar Atasever","poet_slug":"serdar-atasever","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirmizi-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Telaşa Düşmüş', 'can-telasa-dusmus-i-lhami-arslantas-uagbb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Can telaşa düşmüş

Dünya koridorunda,

Bir o yana bir bu yana

Daracık bir yerdeyim.

Keyfe keder mi dersin,

Yok...! babam yok

Yok kimseye nazım,

Açsam da açıksam da.

Can telaşa düşmüş,

Her gün bir başka hüsran,

Yaşamak bin türlü külfet.

Yarınların bitmiş,

Bitmiş kadife karanfiller.

Can telaşa düşmüş,

Artık ne yazık,

Bir çavlan değilim.

Köpük köpük

Berrak berrak.

Islak bir güneş,

Karanlık bir maviyim

Yaşama muhtaç 

Yaşama aç gibi.

Can telaşa düşmüş,

Umudun bir gözü şaşı

Ah...! derken dökülür

Yorgu bedenimden ifrazat

Yıllarımı yontan

Bir bıçak, 

Bir keser,

Bir rende,

Bir hızar

Ve bir tırpan biçer yeşillerimi.

Biliyorum,

Hakkım yok sevenlerimi üzmeye.

Onlara umutlar üstü

Özgürlükler dilerim,

Sevgili umudu ak; 

Umudu pembe; 

Umudu mavilerim.', 'Can telaşa düşmüş Dünya koridorunda, Bir o yana bir bu yana Daracık bir yerdeyim. Keyfe keder mi dersin, Yok...! babam yok Yok kimseye nazım...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/can-telasa-dusmus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah', 'allah-ahmet-hani-z2flg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu bağları yaradan,

Allah Allah ay Allah.

Bu dağları yaradan,

Allah Allah ay Allah.

Ayrı salma elimden,

Nazlı qara telimden,

Gözel Çenlibel''imden,

Allah Allah ay Allah.

Üeryimde imanı,

Derdler üçün dermanı,

Saxla Azerbaycan''ı,

Allah Allah ay Allah.

Söylemezsen yalan sen,

Can verib can alan sen,

Ölen menem qalan sen,

Allah Allah ay Allah.

28    september  2004', 'Bu bağları yaradan, Allah Allah ay Allah. Bu dağları yaradan, Allah Allah ay Allah. Ayrı salma elimden, Nazlı qara telimden, Gözel Çenlibel''...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/allah-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geldim Kabul Buyur', 'sana-geldim-kabul-buyur-koksal-akar-5jpn4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cümle zevki öte ettim, 

Sana geldim kabul buyur. 

Yoklukta bir sırra yettim, 

Sana geldim kabul buyur. 

Dört mevsimde, yılda, ayda

Her ırmakta ve her çayda...

Boşa gezmişim ne fayda, 

Sana geldim kabul buyur. 

Azat ettim tenden aklı, 

Her sır bu gerçekte saklı. 

Çok hâl gördüm farklı farklı, 

Sana geldim kabul buyur. 

Çok kazançta çok servette. 

Sılada cümle gurbette. 

Gönül beşerden nefrette, 

Sana geldim kabul buyur. 

Ömrüm beyhude geçse de, 

Aktan karayı seçse de, 

İnsanlık benden kaçsa da, 

Sana geldim kabul buyur. 

Nasûhî', 'Cümle zevki öte ettim,  Sana geldim kabul buyur.  Yoklukta bir sırra yettim,  Sana geldim kabul buyur.  Dört mevsimde, yılda, ayda Her ırmak...', ARRAY['Türk Edebiyatı','Şiir','Köksal Akar']::text[], 8.5, '{"poet":"Köksal Akar","poet_slug":"koksal-akar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sana-geldim-kabul-buyur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-*- øAldattın...Aldandın...Çiçeksiz Kaldın...! (Akrostiş)', 'aldattin-aldandin-ciceksiz-kaldin-akrostis-metin-eser-e7urj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çöle inkılâp eder, çiçeksiz kalan bahçe,

İsmini öper O''nun, isyana durur lehçe.

Çılgın gece cezbeder, namusun merakını,

Esrar sarar afakı, düşünmez firakını.

Kelâm yalana dosttur, ''doğru'' zindanda hapis,

Vefa atılmış dama, sadakat resmen habis.

Elinden ayağına, vücut başka bir beden,

Aşkın fahişesine, elbet bulunur neden.

Lânet olası nefis, tutunmuş dizginlere,

Dirayet ehline ve kırbacı bezginlere.

Alûde olur ceset, nisyan kalın bir perde,

Tuşa gelmiş irade, hani cesaret nerde. 

Mazi bahçen gül ise, eğlencen köçeksizdir,

Aldatıyorsan eğer, bahçen de çiçeksizdir.

28.09.04 / Zürich - Schweiz

***Samanyolu grubunun; 2K1Ş ''İki Kelime Bir Şiir'' aktivitesi için kaleme alınmıştır.', 'Çöle inkılâp eder, çiçeksiz kalan bahçe, İsmini öper O''nun, isyana durur lehçe. Çılgın gece cezbeder, namusun merakını, Esrar sarar afakı, d...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aldattin-aldandin-ciceksiz-kaldin-akrostis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık', 'yazik-hasim-turker-o5saz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gül bahçelerinde dolaşırken,

güzel kokular alamazsa insan,

uçsuz bucaksız kırlarda,

yaşayamazsa özgürlüğü,

ve en önemlisi,

onun yanındayken

sevgiyi tadamazsa,

yazık geçen zamana,

yaşanan hayata...', 'gül bahçelerinde dolaşırken, güzel kokular alamazsa insan, uçsuz bucaksız kırlarda, yaşayamazsa özgürlüğü, ve en önemlisi, onun yanındayken ...', ARRAY['Türk Edebiyatı','Şiir','Haşim Türker']::text[], 8.5, '{"poet":"Haşim Türker","poet_slug":"hasim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yazik-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemiyorum...', 'bilemiyorum-hasim-turker-v1c21', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hani yağmurdan önce,

gökyüzünü kaplar ya bulutlar,

ve fırtınadan önce,

olur ya ölümcül bir sessizlik; 

işte güzelim,

benim halim buna benziyor.

fakat bilemiyorum,

yağmur yağar mı,

fırtına kopar mı,

bilemiyorum...', 'hani yağmurdan önce, gökyüzünü kaplar ya bulutlar, ve fırtınadan önce, olur ya ölümcül bir sessizlik;  işte güzelim, benim halim buna benziy...', ARRAY['Türk Edebiyatı','Şiir','Haşim Türker']::text[], 8.5, '{"poet":"Haşim Türker","poet_slug":"hasim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bilemiyorum-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istırap', 'istirap-hasim-turker-bf4oz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'söylemek istediklerimi bir söyleyebilsem,

döksem içimdekileri yazdıklarıma,

kalemim ruhumun melodilerini bir mırıldansa,

kağıtlar isyan eder içimdeki ıstıraba.', 'söylemek istediklerimi bir söyleyebilsem, döksem içimdekileri yazdıklarıma, kalemim ruhumun melodilerini bir mırıldansa, kağıtlar isyan eder...', ARRAY['Türk Edebiyatı','Şiir','Haşim Türker']::text[], 8.5, '{"poet":"Haşim Türker","poet_slug":"hasim-turker","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/istirap-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fener', 'fener-mehmet-yilmaz-m5ybl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fenerini tuttugum zaman göge,

Isığı sana vurur. gölgesi bana düşer.

Şimdi bir leylek misali,korunun yanındaki bataklıkta,

Gölgenin düştüğü yerde duruyorum.

Anlamını bekliyorum gecemin durgunlugunda.

Ses ver bana, ben sana herseyi sunuyorum.

Aydınlıgın o essiz ısıltısını verdim sana,

Karanlıga hapsetme beni.

Fırtınalar kopmaya basladı,

Aydınlıgımı kaybediyorum, sen gelmeyince

İstersen söndür fenerini,

Öğrenirim karanlıgı,ama yine severim seni.

Nedensiz cağırıyorum şimdi seni,

Isıgını yak, gir gönlüme Sevi...', 'Fenerini tuttugum zaman göge, Isığı sana vurur. gölgesi bana düşer. Şimdi bir leylek misali,korunun yanındaki bataklıkta, Gölgenin düştüğü y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yılmaz']::text[], 8.5, '{"poet":"Mehmet Yılmaz","poet_slug":"mehmet-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/fener-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Yağmur', 'bir-damla-yagmur-caglar-akarsu-551kn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir damla yağmur,, 

... 

Bir sonbahar mevsimde,gökten yağmur taneleri inmeye başlayınca, hüzünlü bir yalnızlık sarmıştı her yeri. 

.. 

Hani, gelmiş ve gitmiş nice anılarımıza sığınırdık bazı vakitler, 

Her yeri sarmış hüzünlerimizi bırakmak isterdik,yavaşça sığınırdık bir çaresiz kapıya,paylaşırdık tüm sözcüklerimizi, 

Sen  ise,.. 

Her zaman ki  gibi,topladığın müzik arşivlerinden bir demet gül gibi bırakırdın,ruhuma. 

“”Ne önemi vardır “diye, düşünürdüm,” binlerce tane beyaz ve kırmızı gülleri bahçelerden koparsan bir demet çiçek yapsan,elime tutuştursan” ne önemi vardı ki.. 

... 

Şimdi o vakitleri ve bulduğumuz her nağmenin arkasın da ne kadarda mutlu olurduk,zaman döner dururdu. 

.. 

Sen bir denizci  edası ile, alabora olmuş tüm insanlara geminde bir yer verirken,en güzel sözcüklerini yazarda gönderirdin “ gönül defterinden” 

Ne bitmez sayfalardı onlar, 

......

Bulduğumuz her minik” kelime” devler gibi büyür durur,senin içinde yaşadığın denizlere bile sığmazdı, 

Yükselirdik birden bire o kadar çok ufuklara doğru, 

Bir gün anlatmıştım “ gezegenleri” gülmüştük ne de çok, 

Dünya bize hep “ dar “ geliyordu.. 

Denizleri de içimize aldık yetmiyordu ki.. 

Uçuyorduk sanki, her ayrı nağmenin arkasından, 

.. 

Bitmez bir deniz tutkun vardı biliyordum, bir “ can simit “ bulmuş gibi sımsıkı tutundum.Boğulmak riskini  bile düşünmüyordum. 

Binlerce insan dolardı çevremize, hiç biri umurumuzda bile değildi,”nostaljik”  katrelerden  bir umman yapmıştık kendimizi,dilini kaybetmiş, insanlar gibi. Kelimelerin ve nağmelerin coşkusunda  ne kadarda mutlu olduk. 

.. 

Bir damla yağmur gibiydik, 

.. 

Bir gün posta kutuma senden bir paket bıraktılar, üzerinde iki tane renkli pullar ilave etmişlerdi,Deniz ortasında kalmış “martı kuşları” gibi üzerine doğru  uçtum Bir minik paket içine ne  kadarda çok hatıralar almıştı. Geçmişte kalmışlar, ve yaşayanlar. 

Bazen düşlerimize sığınırdık anılar arkasında ki, 

O çok sevdiğimiz, bizden olan değerleri varlıklarımızı paylaşırdık, 

Minik ve şirin bir kız çocuğunun gülücükleri gibi orta yere dökülürdü, 

.. 

Bir yağmur tanesi nasıl toprak üzerine düşerse, sen de ona bir bereket vermek için azimle hep mücadele  ederdin,.. 

Sözcüklerimiz hiçbir zaman olmadı.. 

En güzeli özümü,paylaştık. İçimde binlerce coşku  akar dururdu. 

Hiçbir sözcük gelmediği vakitler anlardık,bazı çaresiz günlerin içinde yaşadığımızı, yine sessiz kaldık,sormaya bile korkardık, 

Düğümler içinde yaşarken,sen bir şarkı çalardın,Karadeniz dalgaları gibi oynak ve hareketli tempolarda, 

Dinlerken çok uzak bir köşede ..düşünürdüm, 

Bir şeyler mırıldanıyor mu..diye, 

.. 

Çok özlediğim zaman, bir “şiir” rica ederdim,hiçbir zaman kırmazdın,İnsanlar ve onlara karşı yakınlığına hayran olmuştum.. 

Her insan, karşıdan gelen istekler karşında, ilk önce kendini düşünürdü.. 

Sen ise o kadar başka idin ki,, 

İlk önce “insana,insanca değer verirdin” 

Mahcupça bir mutluluk kaplardı içimi.” Değer” verilmek ne kadarda güzelmiş, diyerek, 

Toprağa düşmüş,bir yağmur tanesinin mutluluğunu    yakalardım, 

Tepemde denize doğru uçan, 

Martılara “ selam “ gönderirdim, 

... 

Bu gece, “ gecekusu” gelmedi. 

Özgürce yaşamasını çok sevdiğini biliyorum,Gittiği diyarlardan, kanatlarına aldığını, nice yağmur tanelerini,ne nağmelerini, bırakacak, 

Biliyorum. 

... 

2004-08-11', 'Bir damla yağmur,,  ...  Bir sonbahar mevsimde,gökten yağmur taneleri inmeye başlayınca, hüzünlü bir yalnızlık sarmıştı her yeri.  ..  Hani,...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/bir-damla-yagmur-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suya Düşen Yolcu', 'suya-dusen-yolcu-erol-dal-w131y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdilerde uzağım gerçekten

Sevdiğim kadınlardan da uzak

Hayal meyal gelir de adları, 

Atlar eğersiz

Bu sanki bir tuzak.

Ağlarım, 

Haykırırım

Gün doğmadan ayrılırım…

Faka basmam 

Kör kızak.

Buzulu benden iyi

………. ancak

Su bilir.', 'Şimdilerde uzağım gerçekten Sevdiğim kadınlardan da uzak Hayal meyal gelir de adları,  Atlar eğersiz Bu sanki bir tuzak. Ağlarım,  Haykırırı...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/suya-dusen-yolcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Turkuaz Renkli İstiridyeler', 'turkuaz-renkli-i-stiridyeler-caglar-akarsu-tuh50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Turkuaz Renkli  İstiridyeler,.. 

...

Geceler üzerimize, örtüsünü sererken, 

Turkuaz renginin, derinliklerinde, 

Buzul mavisinin, solgunluğunda, 

Daldık gittik, renkler alemlerine, 

Her rengin, ayrı bir sevecenliği, 

Mavinin aks ettiği tüm şekiller, 

Okyanus dalgalarında,coşarken, 

Uzak bir kumsalın, son noktasında, 

Bulduğumuz, en güzel sanatların, 

Her duruşuna, ayrı renk eklenmiş. 

.. 

Turkuaz akşamları, üzerine çökerken, 

Tasmadan zincirleri takmayı,sevmedik, 

Boynumuzda hiç taşımadık”para” torbalarını, 

Damıtılmış,her damlada bulduğumuz, 

Akıp da geleceğe,doğru uzanan, 

Her işin,karşılığında bir bedel, 

Yükü ağırlığında, ezilen kişilikler, 

Paradoks düşüncelerin arkasından, 

Buruk bir tebessüm bıraktık. 

.. 

Denizlerin içinde,sonsuz bir yaşamsa! 

Yaşayanlar bilinmezleri,bilirken 

Yaşamayanlar,istiridye kabuklarında, 

Kaybettiler, ruhlarında ki lezzetleri, 

Her mavi nüans,koyulaşmış tonlarında, 

Siyahın bırakıp gittiğini, bilerek, 

Güneşin tepemizde ki, ışıkları, 

Oksijeni bol,köy topraklarından, 

Her satırın içine, sakladığımız manaları, 

Yükleyerek... bu gece limandan, 

Sevinçler ve hüzünlerimizi, bırakarak, 

Yola çıktık... 

.. 

Turkuaz rengi,yansımıştı yüzüne, 

Dalgın sevinçlerin, ortasında insanlar, 

Baku gecelerinde, Azeri Müzikler, 

“yaman ayrılık” şarkısını söylerken, 

Başka bir turkuaz; buluşmasında, 

Sözcükler, pare-pare olmuşsa ruhunda, 

“yoğsam ki ne” derken, 

Var... olduğumuz için, 

Bütünleştik. 

.. 

2004-09-20', 'Turkuaz Renkli  İstiridyeler,..  ... Geceler üzerimize, örtüsünü sererken,  Turkuaz renginin, derinliklerinde,  Buzul mavisinin, solgunluğun...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/turkuaz-renkli-istiridyeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunmasınlar', 'dokunmasinlar-mehmet-sogut-f7rmk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ulvi duygularla geldim, gül

İtina ile dokunsam yarana

İnsan güldür desem mesela

Ki; gül insan

Akan bir nehir

Düşün, güller olmadan,

Arş-ı alem ne işe yarar

Herakleitos''u utandırma

Devinim

Sefih  olamadım alev

Alevlenir yüreğim

Kırık cam, kevgir

Hatırla yangın izini (y) ekin

Zalim, zalimler geliyor

Dilleri ağızlarında birer çıyan

Bırak eyup sabrını

Katar katar zulüm ordusu

Gayri güllerime, çiçeklerime dokunmasınlar

Yeter.', 'Ulvi duygularla geldim, gül İtina ile dokunsam yarana İnsan güldür desem mesela Ki; gül insan Akan bir nehir Düşün, güller olmadan, Arş-ı al...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sögüt']::text[], 8.5, '{"poet":"Mehmet Sögüt","poet_slug":"mehmet-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dokunmasinlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprağın buluta sevdası...', 'topragin-buluta-sevdasi-emirhan-bala-ta5rr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yaban kısrağın sırtındayım, 

yağmurla beraber sana koşuyorum. 

__________________sen ufukta savruk bulutlara 

__________________kanatlı beyaz kısraklarla.

ben peşinde nemli topraktan,

çiğ çiğ yağıyorum yanaklarına... 

__________________saklı yıldızın parlaklığına,

__________________umutsuz sevdaya sabırla...', 'yaban kısrağın sırtındayım,  yağmurla beraber sana koşuyorum.  __________________sen ufukta savruk bulutlara  __________________kanatlı beya...', ARRAY['Türk Edebiyatı','Şiir','Emirhan Bala']::text[], 8.5, '{"poet":"Emirhan Bala","poet_slug":"emirhan-bala","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/topragin-buluta-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedikodu', 'dedikodu-cafer-yilmaz-e6dm0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir duvara yazılmış adım....

Gelen giden tükürür...

Ne zaman gece olsa

Hep o sarhoş şarkı söyler dibimde

Dibimde binbir küfür....

Ne zaman gece olsa

Ben yine şair olurum

Ben dursam da 

Kelimeler yürür....

Mahallenin manşeti olmuşuz 

Bakkalından berberine

Yani kucak kucak dolaşır adım.

Birde beceriksiz olmuş 

Daha kaç tane lakap var

Bak onu sayamadım...

Yani şimdi hep ben mi buldum

Yürürken yolda 

Takılsın diye bir taş...

yani hep ben mi beceriksiz

hep ben mi ayyaş...

adına belediye denen zevatın

hiç mi suçu yok arkadaş! 

Sabaha güneş lazım

Martıya ekmek...

Gemiye yolcu, bakkala siftah! 

Siz sevmeseniz de beni

Ne zaman vakit gece olsa,

Ben severim sizi 

Birazdan gün ağaracak,

Hadi bana eyvallah! 

          Cafer YILMAZ

               29.08.04', 'Bir duvara yazılmış adım.... Gelen giden tükürür... Ne zaman gece olsa Hep o sarhoş şarkı söyler dibimde Dibimde binbir küfür.... Ne zaman g...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dedikodu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fasülyeden şiirler', 'fasulyeden-siirler-cafer-yilmaz-of54a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her insan kendi şiirini yazar aslında...

ilham denen şey palavra...

her ayrılık bir şiir 

her kavuşma...

sadece kalemle

ve sadece sandığında sakladığın kelimelerle

yıllarca kullanmadığın belki de

tozlanmış,

örümcek ağı kaplamış

cümlelerle dost olmalı biraz.

Nasıl yazdığın değil neyi yazdığın

Ve yazarken 

En sevdiğin şarkıyı duyar gibi heyecanlandığındır önemli olan.

Eğer şiir yazmak istiyorsan

Gece olmalı

Sessiz olmalı her yer...

dünyada yapayalnız kalmış gibi 

derin bir karanlık kapladığında geceyi

al eline kağıdı ve kalemi...

ne yazacağım der gibi bakma bana.

Hiç mi sevmedin yürekten bir şeyi.

Hiç bir bakış hoplatmadı mı yüreğini...

Ya da göz yaşların olmadı mı senin

Ya seni burada bırakıp ta gidenin? 

Aşk şiiri yazamam diyorsan

Anneni anlat,

Öğretmenini anlat,

Arkadaşlarını, dostlarını...

Korkma kalemden al eline.

Hani hatırlarsın 

İlkokulda ilk harfleri fasulyelerle yazardık 

Sıraların üstüne....

Korkma gülmez kimse şiirlerine

Sen de fasulyeden şiirler yaz bu gece

Karanlığın en derin yerine...

                                            Cafer Yılmaz

                                            07-09-2004', 'Her insan kendi şiirini yazar aslında... ilham denen şey palavra... her ayrılık bir şiir  her kavuşma... sadece kalemle ve sadece sandığında...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/fasulyeden-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Irmak', 'irmak-pervin-cankaya-o9c09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ırmak uzanır dağların arasında; 

İnceciktir, zariftir,

İçten içe sevdiğini düşünür.

Beli kıvrık, boynu büküktür,

Ulaşmaktır tüm arzusu

İçten içe düşündüğü sevdiğine...

Dağlar dosttur, yol gösterir.

Ama yollar uzundur! 

Sabırsızlanır dingin ırmak; 

Coşar, dalgalanır, köpürür...

Vakit tamamdır; 

Bitmez dediği yollar bitmiş,

Çekilmez dediği azap dinmiştir.

Usulca süzülür sevdiğinin koynuna...

Ama ne ırmak bulabilmiştir kendini sevdiğinin koynunda,

Ne sevdiği anlamıştır

   içten içe sevildiğini aslında...

Nazlı ırmak,

Zarif ırmak,

Ne''ne gerek senin engin denize sevdalanmak?', 'Bir ırmak uzanır dağların arasında;  İnceciktir, zariftir, İçten içe sevdiğini düşünür. Beli kıvrık, boynu büküktür, Ulaşmaktır tüm arzusu İ...', ARRAY['Türk Edebiyatı','Şiir','Pervin Cankaya']::text[], 8.5, '{"poet":"Pervin Cankaya","poet_slug":"pervin-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/irmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herkes Uyumuş', 'herkes-uyumus-bekir-mutlu-gokcesu-yvs4e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Günlerden sonra

Çıktım şu balkona

Yıldızlar yabancı sanki

Gece yabancı bana

Baktım uzaklara

Baktım boş bakışlarla

Işıklar dışladı beni

Sokaklar ilgisiz bana

Bir insan aradım karanlıkta

Bir siluet hani, yoktu

Herkes uyumuş

Kalmışım yine bir başıma...', 'Günlerden sonra Çıktım şu balkona Yıldızlar yabancı sanki Gece yabancı bana Baktım uzaklara Baktım boş bakışlarla Işıklar dışladı beni Sokak...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/herkes-uyumus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu musun?', 'mutlu-musun-bekir-mutlu-gokcesu-ibeff', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oysa 

Karşıydık savaşa

Peki neden? 

Savaştık yıllarca

Ben kazanacakken

Aydım mutsuzluğa

Kaybettim ve bittim

Kurtuldum

Sen kazandın

Mutlu musun?', 'Oysa  Karşıydık savaşa Peki neden?  Savaştık yıllarca Ben kazanacakken Aydım mutsuzluğa Kaybettim ve bittim Kurtuldum Sen kazandın Mutlu mus...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mutlu-musun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hemen Sabah Olsa', 'hemen-sabah-olsa-bekir-mutlu-gokcesu-93lxx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şimdi

Bir çınar altı olsa

Aklım gibi hani havada

Bir ucu bulutlarda

Ayaklarım gibi hani toprakda

Bir ucu yerin altında

Bir bardak çay olsa

Şimdi bir çınar altında

Tahta masa ve sandalye

Şöyle derme çatma

Korkularım hiç olmasa

Eski zamanlardaki ben

Hemen beni kokumdan bulsa

Halden anlar bir bilge

Hani gelip karşıma otursa

Baksa çocuk gözlerime

Beni okuyup anlasa

Ben dinlesem, o anlatsa

Anlatsa, anlatsa...

Şimdi

Hemen güneş doğsa

Her yanım sabah koksa

Bir bardak çay, sıcak

Ve korkularımdan kurtulacak

Bir çınar altı olsa...', 'Şimdi Bir çınar altı olsa Aklım gibi hani havada Bir ucu bulutlarda Ayaklarım gibi hani toprakda Bir ucu yerin altında Bir bardak çay olsa Ş...', ARRAY['Türk Edebiyatı','Şiir','Bekir Mutlu Gökçesu']::text[], 8.5, '{"poet":"Bekir Mutlu Gökçesu","poet_slug":"bekir-mutlu-gokcesu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hemen-sabah-olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşluk Vakti', 'kusluk-vakti-ali-gencay-g1we2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anne

Ört üzerimi 

ninniler söyle

okşa saçlarımı

uyanmamalıyım

sabah 

düşler toplayan

bırak 

daha uyanamadım

kumruları sayıyor

ihtiyar kadın

kuzgun

çık aradan

bahsi kazanacak

gıcırdayan sandalyede 

sallanan 

bıyık altından sırtaran adam

dönüp duruyorum 

yatağım 

dünyam

üşüyor bir yanım

açık kalmış pencerem

kuşluk vakti doluyor odama 

okunan ezan

utanıp da gizlendim

müstehcen rüyam

üstüm yorgan

çanlar çalıyor

sıvışıyor yanımdan

yılan kadın

şah meran

ne çabuk

hiç çıkmadı ki üzerimden

urbam

beyim uyan

doldu zaman

süpürülecek düşlerden kalan', 'Anne Ört üzerimi  ninniler söyle okşa saçlarımı uyanmamalıyım sabah  düşler toplayan bırak  daha uyanamadım kumruları sayıyor ihtiyar kadın ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/kusluk-vakti-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ASlRLARA BlRAKlYORUM...YAŞANMlŞLlKLARlMl...', 'aslrlara-blraklyorum-yasanmlsllklarlml-baki-son-qce5l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kıpırtı var...

...................Dursam da,

...................Yürüsem de

Bir hareket hissediyorum,

Tüm hücrelerimde...

Sevdiğimi söylesem,

...................Biliyorsun.! 

Bin yıl önce de,

Parlıyordu yıldızlar...

Bin yıl önce de,

Güzeller yaşamıştı...

Bir tebessüm bıraktılar

...................Zamanlara...

Tek silemediği saniyelerin...

İşte dizelere işledim ellerini

Şimdi şairim...

Asırlara bırakıyorum 

...................Yaşanmışlıklarımı...................

Bin yıl sonra da

Parlıyacak yıldızlar,

Belki daha mutlu bir gök kubbeye,

Seni yazacağım...

Dize,dize...

Sevdiğimiz kadarcık,

Biz de yaşıyacağız.

Geçen zamanı anlamıyorsun..! 

Bin yıl sonra da

...................Yalnızız işte.! 

Sen ve ben kadar uzak...

O kadar kısa ki zaman

Ve öylesine güzel ki

...................Sevgimiz...................

...................Seviştiğimiz...................', 'Bir kıpırtı var... ...................Dursam da, ...................Yürüsem de Bir hareket hissediyorum, Tüm hücrelerimde... Sevdiğimi söyle...', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aslrlara-blraklyorum-yasanmlsllklarlml-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayallerim', 'hayallerim-melek-ozgoz-e8r88', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayallerim kırıldı kesti elimi umutlarım

Kanım masmavi aktı avuçlarıma

Belli sakladığım gözyaşlarım

Küf yapmış kalp kapaklarıma', 'Hayallerim kırıldı kesti elimi umutlarım Kanım masmavi aktı avuçlarıma Belli sakladığım gözyaşlarım Küf yapmış kalp kapaklarıma...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayallerim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Yalnızım', 'cok-yalnizim-melek-ozgoz-l1m22', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben birçok hiçin içinde

Tüm varlığımla yaşamaya çalışırken

Nedenli nedensiz ağlamaklıyken

Çok yalnızım

Ben sahte gözlerin içinde

Yalanın koynundan uyanmak isterken

Ve gerçekle yüzyüze çarpışmışken

Çok yanlızım

Sigaramı yakıp geçmişe

Acılar içinde can çekişirken

Nankörlüğün çukuruna batıp kurtulamazken

Çok yanlızım

Kor bir hasreti yüreğimde saklarken

Duyduklarımın soğukluğunda donmuşken

Yardım uzatacak bir ele muhtaçken 

Çok yanlızım

Sayfalarımda ki sancımı

Anlatmaya niyet etmişken

Kelime bulamayıp pes etmişken

Çok yalnızım', 'Ben birçok hiçin içinde Tüm varlığımla yaşamaya çalışırken Nedenli nedensiz ağlamaklıyken Çok yalnızım Ben sahte gözlerin içinde Yalanın koy...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cok-yalnizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bende Saklı', 'bende-sakli-melek-ozgoz-lh3oc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende saklı sanmıştım

Dolunayın

Tek tek ismi vardı mesela

Nefes veren her rüzgarın

Güneşin rengi beyaz gibiydi

Geceninse kara

Bir sürü kalbim vardı sevgi dolu

Atardı yıldızlarda

Benimle ağlayan yağmurlarım

Hüznüme misafir olan bulutlarım vardı

Hıçkırıklarımla dost olan şimşek kardeş

Çok vefalıydı

Bir gün kararıp  kaldı gökyüzüm

Güneşim dolunayım tüm yıldızlarım

Kaçtılar benden

Yarınıma yalancı çıktı yüzüm....', 'Bende saklı sanmıştım Dolunayın Tek tek ismi vardı mesela Nefes veren her rüzgarın Güneşin rengi beyaz gibiydi Geceninse kara Bir sürü kalbi...', ARRAY['Türk Edebiyatı','Şiir','Melek Özgöz']::text[], 8.5, '{"poet":"Melek Özgöz","poet_slug":"melek-ozgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bende-sakli-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Sen', 'oyle-bir-sen-oguzkan-bolukbasi-eh4xg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'var mı öyle bir sen

ki

her nefesimde konuveresin camına hayatın

öyle bir sen var mı

ki

her sayfasında adını okuduğum bir kitabın

kalemi oluveresin

öyle bir sen

böyle bir ben

gelsen de 

görsen', 'var mı öyle bir sen ki her nefesimde konuveresin camına hayatın öyle bir sen var mı ki her sayfasında adını okuduğum bir kitabın kalemi oluv...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/oyle-bir-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hasan'' a Mektup / 3 (Hasan’ la Hasbihal)', 'hasan-a-mektup-3-hasan-la-hasbihal-ahmet-turan-altunsu-n6y1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '(son geliyor karındaşım; vedaya hazır mısın?)    

Aklım başımda mı soruver hele,

Gönlümün gurbette işi ne Hasan? 

Çekmişim lâhavle, bir de besmele; 

Etmişim yazgımın içine Hasan! 

Hakkâri, Siirt, Van… yeterdi bana,

Niyedir yazgıma düşmüş Adana? 

Rastlayamadıysam yârin adına; 

Bunda bu fakîrin suçu ne Hasan? 

Bu fakîre bunca zaman aratmış,

Bir âfet ki Tanrı övmüş, yaratmış,

Tellerini hûrilere taratmış; 

Meftun oldum yârin saçına Hasan! 

Aman bre Hasan; bıktım usandım,

Baktım ki olmuyor; giydim, kuşandım,

Elimde kalemim; yola döşendim:

De hele; yolumun ucu ne Hasan? 

Önümde bir kâğıt, elimde kalem; 

Ne zaman bitecek bilmem bu elem, 

Olur da gülerse halime alem; 

Gitmesin yârimin gücüne Hasan! 

Etmişim yazgımın içine diye,

Bunda bu fakîrin suçu ne diye,

Sorduysam yolumun ucu ne diye:

Gitmesin yârimin gücüne Hasan,

Talip oldum âşık tacına Hasan! 

                              28.09.2004 / Ankara', '(son geliyor karındaşım; vedaya hazır mısın?)     Aklım başımda mı soruver hele, Gönlümün gurbette işi ne Hasan?  Çekmişim lâhavle, bir de b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Turan Altunsu']::text[], 8.5, '{"poet":"Ahmet Turan Altunsu","poet_slug":"ahmet-turan-altunsu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hasan-a-mektup-3-hasan-la-hasbihal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ambulans Sesleri', 'ambulans-sesleri-aynur-baydar-7zd7g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Orucu kuyruğundan tutmayla

Özentimi, yarım günle giderdin

Tokların, açlığı bilmesi gerek dedin

Tekbirle kurbanı kesip alnıma sürerken

Ağlama kızım bu boğazlamak değil

Fakirlerle yardımlaşma 

Daha ne incelikler var kurbanlıkta

Dinimizi hep sevgiyle verdin

Yavru kediyi yıkadık birlikte

Topal tavuk yumurtladığında

Elimizde solucanla ödüllendirdik

İğrenç gelmedi bir şey seninle

Güzelden bakmasını öğrettin bize

Felçli yaşlı kadın, utancından ağlarken

Bende senin evladınım, ninemle

Koca gövdeyi oturturken lazımlığa 

Pek komik gelmişti kızına

Verdiğin bana, yaşlıya şefkatmiş oysa

Komşu kızına laf atanın

Ağzını burnunu dağıttığında

Ödüm de patlamıştı ama

Yürek varmış namus da

Her işi anneme danışırken

Ona hep canısı derken

Hayat arkadaşlığını gösterdin

Sırtındaki yeni yün ceketi

Verirken muhtaca, kızmıştım sana

Üniversiteli senden daha okumuşum ya

Kusura bakma eşeklik yapmışım oysa

Ayırmadın abimden

Kız erkek değil insanız, tekizle

Yetiştik elinden

Delikanlılık maceralarını

Kızlarla Kore hatıralarını

Annem de gülerek dinlerdi bizle

Kızmamasına şaşardım 

Meğer eminmiş sevginden

Haksızda, yanlışta susma

Sakın mazluma tepeden bakma

Bize vasiyetinmiş aslında

Bol salçalı pembe ıspanağı

Demlediğim imamın abdes suyu çayı

Ev halkı yüzünü buruştururken

Pek keyifli yedin, içtin

Küçük kızına da güven verdin

Gece aniden kalp krizi geçirdin

Güven yerde yatıyordu, 

Abim yoktu, annem korkmuştu

Kızında daha on dokuzunda toydu

BABAM…

Deliler gibi çıktım sokağa

Bana öğrettiğin ama bir türlü yapamadığım

Islık çıktı dudaklarımdan 

Gecenin ıssızında, taksiye duyurduğumda

Kızın büyüdü, ayaklarının üstünde durdu

Hiç ağlamadım, bir yıl sonra ambulansla

Gene hastane yollarında

Geniş omuzlarının arasında, kabarmış kalbine

Kalp masajı yapan genç kız doktor 

Dayan amca dedi ağladı 

Belki babası aklına geldi

Yada sen ilk hastasıydın

Ağlamadım babam, el ağlarken

Dualarımla birlikte 

Robot gibi yapılması gerekeni yaptım

Ertesi gün morgda, beyaz çarşafın altında

Gördüm ayaklarını, tanıdım 

İnandım öldüğüne

Öğrettiğin gibi feryat figan etmedim

Gözümden inenlere de söz geçiremedim

Her ambulans sireni duyduğumda

Acele kaçıp, hemen yol veririm

Allah yardımcıları olsun derim

Koca kadın halimle, bir de kendimleysem

Hem sürerim arabamı, hayatıma

Hem ağlarım 

Özlediğim için ağlarım

Seni kızdırdığım için ağlarım

Utandırmayıp, gururlandırdığım için

Mutluluktan ağlarım

Artık ambulans sirenleri

Sana hasret gözyaşlarımın

Dökülme sesi…', 'Orucu kuyruğundan tutmayla Özentimi, yarım günle giderdin Tokların, açlığı bilmesi gerek dedin Tekbirle kurbanı kesip alnıma sürerken Ağlama...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":83,"source_url":"https://www.antoloji.com/ambulans-sesleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Sahipsizlik', 'vah-sahipsizlik-murat-demir-0hulm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özlem kurşun, hasret hançer

Keser biçer deler geçer

Almış ele tartar ölçer

Sanki bilmez miş hiç mi hiç beni

Normal sanıyor ettiklerini

Kahrolası talihsizlik

Yaptıkları değil ki ilk

Ah sahipsizlik

Vah sahipsizlik

Neşe nerde, hep dert keder

Neyin varsa getir ver der

Talan eder çeker gider

Sanki hiç bilmez miş sevda arını

Normal sanıyor yaptıklarını

Kahrolası talihsizlik

Çektiklerim değil ki ilk

Ah sahipsizlik

Vah sahipsizlik!', 'Özlem kurşun, hasret hançer Keser biçer deler geçer Almış ele tartar ölçer Sanki bilmez miş hiç mi hiç beni Normal sanıyor ettiklerini Kahro...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vah-sahipsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gene Yetmezdi Aşkımı Yazmak İçin', 'gene-yetmezdi-askimi-yazmak-i-cin-huseyin-erdogan-rqkm8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ay,güneş ve dünya ederler bir üçgen

gözlerin nokta,kaşların yay,kalbin köşegen

Sen hüzün nedir biliyorsan,sebepsiz içiyorsan

bu üçgeni bir daireye sığdır lütfen

ormanlar kalem,okyanuslar mürekkep olsaydı

gene yetmezdi aşkımı yazmak için

ırmaklar sen,ovalar ben olsaydım

gene yetmezdi sana doymak için

trenleri eklesem uç uca olurdu dev bir yılan

lakin bulamazdım onu öldürecek bir zehiri

gülsen de,ağlasan da,yesen de,içsen de hepsi yalan

lakin bir gölge,bir ruh da olsan sen başkasın

Köpürmüş bira gibiyim,sığmam fıçıya

içmeye teşebbüs etme içinden çıkmam

masam güzel,bir duble rakı,bir dilim elma vesaire

ne de olsa eksik var.o da sen ve gene de sen...', 'ay,güneş ve dünya ederler bir üçgen gözlerin nokta,kaşların yay,kalbin köşegen Sen hüzün nedir biliyorsan,sebepsiz içiyorsan bu üçgeni bir d...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gene-yetmezdi-askimi-yazmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SONBAHARDA AŞK ŞİİRLERİ...(Düz Yazı)', 'sonbaharda-ask-si-i-rleri-duz-yazi-naime-erlacin-8opui', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genellikle düşünce şiirleri yazar ve aşk şiirlerinden uzak dururum. Son günlerde ise elimden geldiği ve dilimin döndüğünce aşk temasını işlemeye çalışıyorum.

Öyle bir mevsimdeyiz ki doğa uykuya çekilirken, ruh ve bedenlerimiz bu değişime kaçınılmaz olarak ayak uyduruyor. Metabolizmalarımız eskisinden farklı çalışıyor; hormonlarımız dinlenmeye geçiyor. Hayata şehlâ bakmamıza neden oluyor sonbahar. Adeta yaprak döküyoruz. Ruhlarımıza sarı hüzünler hükmediyor. Ve bu bana, biraz zaman kaybı biraz da haksızlık gibi geliyor. Belki de yaşım icabı öyledir, kim bilir. Gençlerin önünde yaşanacak pek çok ilk ve sonbahar varken bizim vaktimiz oldukça sınırlı artık.

İçimde bir ses, onlara ve kendime umudu ve aşkı hatırlatmam gerektiğini söylüyor. Şairin bir görevi de tanıklık ederek belgelemek; kendince bir isyan unsuru olan haksızlığa karşı bir tavır-duruş yüklenmek olduğuna göre, ben de kendimce - doğanın tabii akışından kaynaklanıyor olsa bile -  bu duraganlık ve onun doğurduğu hüzne karşı koyuyorum. İşte bu yüzden aşk yazıyorum. Özellikle de zamanı hızla tükenenler için…

Hüzün şiirlerini severim. Acılı şiirleri ve toplumcu olanları da…Yanlış anlaşılmasın. Onları yadsımak değil amacım. İyi olanlar ruhta daima derin ve eşsiz bir tat bırakırlar. Ancak aşk yadsınırsa ya da geçici bir dönem için dahi unutulursa eğer, işte buna itirazım olur. Ölümsüzlüğü arayan ve ararken direnen kişidir şair. Ölümsüzlüğü ise yalnızca aşkta bulur.

Aşk elbette her sorunu halletmez  ama pek çok yaraya merhem olduğu gibi şiire de ivme kazandırır. Ruhları tamir eder; akort eder; onarır. Bazen de akort bozar! Varsın olsun. Yine de sevilesi bir duygudur o; sevmenin ötesinde sayılası…

Aşk yazışım, sarı hüzünlere teslim olmak istemeyişin ve direncin somut bir örneği. İçinizde mutlaka aşkla doğmuş; aşktan beslenen, size canlılık veren ve hayatiyet kazandıran hücreler vardır. Küçücük bir kırıntısı bile bir gün bulaşmıştır ellerinize. Yüreğinizde fırtınalar estirmiştir. “O halde onları yazın” demiyorum tabii ki. Görevim vaaz vermek değil. Ben ancak kendi içimi, kendi aşkımı yazabilir ve ürünlerimi sizlerle paylaşabilirim. Unutmayalım ki, her şeyin “başka”sı yazılabilir ama aşkın yalnızca “kendi”si. Benim yapmaya çalıştığım da bu….

Pandora’nın kutusunda mahpus kalmış tüm umutlarla “aşk küre”yi kaplayan o anlamlı ve hâkim duygu adına aşk yazıyorum şimdi.

Aşkın güzüne değil –  bir güzü olduğuna inanmıyorum çünkü - ama ruhuma sahip çıkmaya çalışan güze karşı direniyor ve sizi de direnmeye davet ediyorum. Hüznümde bile aşk yazmalıyım ki, sahipsiz kalmasın sonbaharlar.

İnsanı daima yeşil tutan bu duygunun açtığı yolda şiirlerle çoğalmayı umuyorum. Çünkü o varsa, diğer bütün ince duygular peşinden koşarak gelir. 

Dört mevsimin baş efendisidir aşk! 



(29 Eylül 2004)   

(''BİR TUTAM TUZ'', Hayal Yay. Ekim 2010, Sayfa 70)', 'Genellikle düşünce şiirleri yazar ve aşk şiirlerinden uzak dururum. Son günlerde ise elimden geldiği ve dilimin döndüğünce aşk temasını işle...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sonbaharda-ask-siirleri-duz-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşıda Kaldın', 'karsida-kaldin-burak-killioglu-h58zc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık saklar seni...

Ne gecenin, ne gündüzün

Ne hayatın, ne ölümün

Gizlisi saklısı mı var ki,

Senin olsun.

Serin, sakin dalgaların

Eskimiş ya da yeni mi yeni

Çarpık ya da düzenli,

Bir şekilde İstanbul gibi kokan

Bin bir çeşit binanın ardındasın.

Her akşam ardımda,

Ve her an aklımdasın.

Bilsen, ne kadar yakınsın

Ve bir o kadar da uzak...

Akşamın gelişiyle deniz ayırırken bizi

Bir de bakmışım ki, 

Ben buradayım hala

Sen karşı yakadasın.', 'Karanlık saklar seni... Ne gecenin, ne gündüzün Ne hayatın, ne ölümün Gizlisi saklısı mı var ki, Senin olsun. Serin, sakin dalgaların Eskimi...', ARRAY['Türk Edebiyatı','Şiir','Burak Kıllıoğlu']::text[], 8.5, '{"poet":"Burak Kıllıoğlu","poet_slug":"burak-killioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/karsida-kaldin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Gülüşünü Bana Sakla...', 'gulusunu-bana-sakla-naime-erlacin-ag9r7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'henüz vedalaşmadım yaşamla

uçurumda bir dal var düşerken tutunduğum

o sensin işte 

ne çok ertelendik ama biz 

ezber edilmiş şarkılarda kaldı mavi günlerimiz

insanı nereye götürürse gölge oradayım şimdi

buna elbet bir ad biçeceğiz

kafanı karıştıracağım inan 

öyle karıştıracağım ki şaşıracaksın 

en iyi yaptığı ikinci şey var ya insanın 

''gülmek'' diyorlar adına hani

en çok onu özlemişim 

bir gün mutlaka

bir gün 

bir sigara molasında 

birlikte güleceğiz

o halde dayan

gülüşünü bana sakla 

benim olan benimdir

sakın unutma!

(29 Eylül 2004)', 'henüz vedalaşmadım yaşamla uçurumda bir dal var düşerken tutunduğum o sensin işte  ne çok ertelendik ama biz  ezber edilmiş şarkılarda kaldı...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gulusunu-bana-sakla-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız', 'kayan-yildiz-ahmet-dasdan-8gez6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Öylesine baktım zaten boş boş

Anlam vermeye bile çalışmadım

Sen vardın gözümün önünde

Hani trenin camına bakarken

Diğer görüntülere dikkat etmezsin ya

Bende dikkat etmedim, 

Biliyorum ki 

Senin kadar parlak bir yıldızın

Kalbimden kayamasına izin vermeyeceğim

Kayarsan eğer

Ben o kalple artık yaşamayacağım.', 'Öylesine baktım zaten boş boş Anlam vermeye bile çalışmadım Sen vardın gözümün önünde Hani trenin camına bakarken Diğer görüntülere dikkat e...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Daşdan']::text[], 8.5, '{"poet":"Ahmet Daşdan","poet_slug":"ahmet-dasdan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kayan-yildiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşça Kal', 'hosca-kal-ali-osman-donmez-nr16s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın? 

Bir mecnun edasıyla dolaşırdım

Vahavari sokaklarında

Seninle tek yürek gibi

Bitişikti tenlerimiz

Bak şimdi nasıl da mahzun akıyor

Kıyısında ilân-ı aşk ettiğim nehir

İçimde volkan misali bir ateş...

Ayrılıyorum senden sevdiğim şehir

Ben ilk aşkı sende tattım

Son aşkımı bir güz hüznüyle gömdüm

Sevgime mezar olan parklarına

Bu yüzden titrersin gözümde tir tir

Her adımına bir anımı kazıdığım şehir

Bu soluk eylül akşamında

En içli şarkılarla veda ederken sana

Hüznün bin tonuyla çalkalanır sokakların

İçimdeki ateşle

Buz tutar dilimde kelimeler

Saçlarıma hapsettiğim kavak yelleriyle

Uzayan bir ömürdür önümde yollar

Simsiyah bir hüzünle beraberim şimdi

Uzaklardan ıslak bakışlarla tararım

Sırılsıklam saçlarını

Bulutlar, bendeki sana ağlar

Bense sendeki beni ararım

Titrek bir hayaldir durmadan erir

Hoşça kal

Hoşça kal sevdiğim şehir

(Celal Bayar Üniversitesi Fen Edebiyat Fakültesi 1997 Yıllığı)', 'Hatırlar mısın?  Bir mecnun edasıyla dolaşırdım Vahavari sokaklarında Seninle tek yürek gibi Bitişikti tenlerimiz Bak şimdi nasıl da mahzun ...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Dönmez']::text[], 8.5, '{"poet":"Ali Osman Dönmez","poet_slug":"ali-osman-donmez","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hosca-kal-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmiyor Geceler', 'bitmiyor-geceler-huseyin-erdogan-kccdo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bitmiyor geceler,geçmiyor zaman

sen gelirsin diye beklerim her an

gözlerim kalmasın ıssız yollarda

çıkıp gel bir sabah güneş doğmadan

göz yaşım akmasın yoruldum artık

gözlerim buğulu her yer karanlık

ağlarım her gece yüreğim yanık

ne olur sevgilim geri dön artık

düşlerimde bile bırakma beni

okşa yanağımı meltem misali 

istiyorum seni bir nefes gibi

özledim sevdiğim özledim seni...

Beste:Mustafa Malay  Makam:Muhayyer Kürdi', 'bitmiyor geceler,geçmiyor zaman sen gelirsin diye beklerim her an gözlerim kalmasın ıssız yollarda çıkıp gel bir sabah güneş doğmadan göz ya...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Erdoğan']::text[], 8.5, '{"poet":"Hüseyin Erdoğan","poet_slug":"huseyin-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bitmiyor-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annem....', 'annem-ahmet-dasdan-6hwsx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün rüyamda gördüm anne

Bayrakla sarılmış bir tabut vardı

Hiç düşünmedim girdim içine 

Bir görebilseydin içini 

Ancak cennet bukadar olurdu

Anlayamadım annem

Sen neden ağlıyordun

Üzerime kapanmış göz yaşını dökerken

Cennet bahçesinden sana bakıyordum

Ölmezdim belki alnımdan vursalardı

Sırtımdan vurdular annem bilemezdim

Ne olursun ağlama dökme gözün yaşını

Tutmak sana nasipmiş

Tek oğlunun yasını

Değişmezdim gözyaşının tek damlasını

Ama arkadan vurdular anam

Gözlerim dolmuş, kızma bana nolur

Kızacaksın biliyorum 

Seni çok seviyorum 

Ayrılamıyorum mezarının başından

Seni çok özlüyorum 

Başımı okşamanı, bağrına basmanı

Uyurken saatlerce beni seyretmeni,

Yavrum derken sesinin titretmesini

Her hatamda ki  merhametini

Herşeyini ama herşeyini özledim anne.

Canım Anneme..........', 'Dün rüyamda gördüm anne Bayrakla sarılmış bir tabut vardı Hiç düşünmedim girdim içine  Bir görebilseydin içini  Ancak cennet bukadar olurdu ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Daşdan']::text[], 8.5, '{"poet":"Ahmet Daşdan","poet_slug":"ahmet-dasdan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/annem-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
