INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nazlı Çiçekler', 'nazli-cicekler-ahmet-hakan-yilmazturk-dl3p2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çiçekler nazlıdır

barışla büyür

demokrasiyle açarlar

bir gün

............ ezilebilirler

1988', 'çiçekler nazlıdır barışla büyür demokrasiyle açarlar bir gün ............ ezilebilirler 1988...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nazli-cicekler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiten Umut', 'yiten-umut-ahmet-hakan-yilmazturk-c0ira', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ten

ürperir de

hoplarsa şu yürek

boğaz da kurur

ağız da

doyurmaz aksa da

kana kana

içilse de

çağlayanlar

dindirmez teskin

ve teselliler

hapsedince yüreğine

arsız umutsuzluğu

burgu burgu

çeker içine

kaos

her rüya

avutucu bir kesit

hayatından

her iç çekiş

bir özlem

yaşanacak

bir dönem

açıp da gözlerini

uyanınca yeni güne

farkediverirsin

dün, bugün, yarın

yok bir şey değişen.

ten

ürperir de

hoplarsa şu yürek,

boğaz da kurur

ağız da.

1994', 'ten ürperir de hoplarsa şu yürek boğaz da kurur ağız da doyurmaz aksa da kana kana içilse de çağlayanlar dindirmez teskin ve teselliler haps...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yiten-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayran Delisi', 'ayran-delisi-halil-pazarli-cgbd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Halbuki

yastığımın altında

küçücük, şirin bir bahçe vardı

gönlümde sevdan..

Sessizdi, sakindi, özeldi

in cin top oynardı..

Sadece sana ayırdığım

kimseyi koymadığım..

Ağzı açık ayran delisi miyim be! 

gel de şenlendir burayı..', 'Halbuki yastığımın altında küçücük, şirin bir bahçe vardı gönlümde sevdan.. Sessizdi, sakindi, özeldi in cin top oynardı.. Sadece sana ayırd...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ayran-delisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazık Oldu Ömrüme', 'yazik-oldu-omrume-halil-pazarli-x0wjq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne güzeldi o günler tatlı sevda sırları

tertemiz arzularla geçti çocuk yılları

bir koltuğa oturup albümlere bakarken

birden canlandı sanki o gençlik anıları

Yazık oldu sevdama yazık oldu gönlüme,

yazık oldu ferdama yazık oldu ömrüme..

Şöyle bir düşündüm de bir baktım ki maziye

neşeyle, üzüntüyle geçmiş kırk iki sene

nerde yaşam kavgası orda ekmek parası

hayat olmuş bir okul, hayat üniversite

Yazık oldu sevdama yazık oldu gönlüme,

yazık oldu ferdama yazık oldu ömrüme..', 'Ne güzeldi o günler tatlı sevda sırları tertemiz arzularla geçti çocuk yılları bir koltuğa oturup albümlere bakarken birden canlandı sanki o...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yazik-oldu-omrume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayna Kompleksi', 'ayna-kompleksi-halil-pazarli-jjrdx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allah kahretsin! .

bugün de

çok yakışıklıyım..', 'Allah kahretsin! . bugün de çok yakışıklıyım.....', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ayna-kompleksi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-halil-pazarli-s3j9x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hışmıyla dalga dalga

kadehlerde bir deniz

ahh! . derdimi sormayın

söylersem gülersiniz..', 'Hışmıyla dalga dalga kadehlerde bir deniz ahh! . derdimi sormayın söylersem gülersiniz.....', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-280-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanç', 'i-nanc-ahmet-hakan-yilmazturk-cl4yk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurumuşsa göz pınarların

Çatlamışsa toprak gibi, dudakların

Yitip gitmişse tüm umutların

İnan, Işk seni ayakta tutar

Bin var bin yoka dönmüşse

Tutunduğun her dal kurumuşsa

Yüreğin kor gibi yanmışsa

İnan, Işk seni ayakta tutar

Hasreti arkadaş edinmişsen

Çaresizliği koynuna almışsan

Geceden güne nöbetteysen

İnan, Işk seni ayakta tutar

Bin yok bin vara değişir

Yiten umutlar yeniden filizlenir

Dallar sabırla, duayla yeşerir

İnan, Işk seni ayakta tutar

1994', 'Kurumuşsa göz pınarların Çatlamışsa toprak gibi, dudakların Yitip gitmişse tüm umutların İnan, Işk seni ayakta tutar Bin var bin yoka dönmüş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/inanc-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahane', 'bahane-halil-pazarli-xn9ht', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oynamam

ısrar etme

oynamam

yemin verme

oynamam

İlla söyletme beni

yerim dar

oynayamam', 'Oynamam ısrar etme oynamam yemin verme oynamam İlla söyletme beni yerim dar oynayamam...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahane-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Artık Tokat''a Dönmeliyim', 'ben-artik-tokat-a-donmeliyim-halil-pazarli-wk34q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Halbuki o sıcacık ellerini tutmak isterdim

yırtılan gecenin çöl çığlığı karanlığında

sonra uykumu getirmeliydi kulağıma söylediğin ninniler

ve üstümü örterken masum bir öpücük kondurmalıydın yanağıma

Derken horozlar ötmeli sabah olmalıydı aniden

kocaman caddelerde insanlar koşuşmalıydı

depreme alışmış dünyanın dengesini bozmadan

Sokak lambaları sönerken bir bir sıcacık

ben hala seni hissetmeliydim içimde

ve sarılmalıydım o şefkat yumağı kucağına

Hayat dersi çıkartmak elbette zordu

beton yığınlarının arasından

Kayıp giden zamana yazık..', 'Halbuki o sıcacık ellerini tutmak isterdim yırtılan gecenin çöl çığlığı karanlığında sonra uykumu getirmeliydi kulağıma söylediğin ninniler ...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-artik-tokat-a-donmeliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün', 'dun-ahmet-hakan-yilmazturk-6c6rz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düne bak

Olduğunca zor inanmak

Sen miydin,

O zevk-ü sefayı süren? 

Özgür bir sinek gibi

Bir boka batıp,

Bir göğe yükselen? 

Sen miydin

Ölesiye lezzet alan

Ve hiç kıymet bilmeyen? 

İnanılası değil

İçinde bulunduğun sefalet

Üstün pas, çamur

Bedenin kirli ve aç

Hayatınsa,

Gerçek vehamet.

Düne bak

Olduğunca zor inanmak.

Peki ya yarın? 

Kimbilir neler getirecek? 

Belki üzecek, belki güldürecek

Mümkünse öldürecek.

Değilse de senden,

Çok şeyler götürecek

Tevekkülü getirecek.

Hay Allah! 

Düne bak düne...

1994', 'Düne bak Olduğunca zor inanmak Sen miydin, O zevk-ü sefayı süren?  Özgür bir sinek gibi Bir boka batıp, Bir göğe yükselen?  Sen miydin Ölesi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilgisayar da Bilgisayarmış Ha', 'bilgisayar-da-bilgisayarmis-ha-halil-pazarli-k8iij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adam internet sevinci içinde

bilgisayara programlarını koydu

belgelerim klasörüne resimlerini koydu

wordünü excelini koydu

monitörden sızan ışığı koydu

modem sesini disket sesini

jpg.nin gif.in hafifliğini koydu

adam bilgisayara

aklında olan bitenleri koydu

ne yapmak istiyordu hayatta

işte onu koydu

kimi chatleşiyordu kimi icqlaşıyordu

adam onları da koydu bilgisayara

superonline eşiittir 9 dolardı

adam koydu bilgisayara 9 doları

klavye yanındaydı mause yanında

uzandı bilgisayara 24 bit çözünürlüğü koydu

bir web sayfası yapmak istiyordu kaç gündür

bilgisayara sayfanın süzülüşünü koydu

uykusunu koydu uyanık saatlerini koydu

açlığını koydu tokluğunu koydu

Bilgisayar da bilgisayarmış ha

bana mısın demedi bu kadar yüke

bir iki kilitlendi durdu

adam ha babam koyuyordu', 'Adam internet sevinci içinde bilgisayara programlarını koydu belgelerim klasörüne resimlerini koydu wordünü excelini koydu monitörden sızan ...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bilgisayar-da-bilgisayarmis-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aşk Masalı', 'bir-ask-masali-halil-pazarli-sk771', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerim ellerine dokununca üşürdün

gözlerine bakardım yüzünü düşürürdün

bozuk saz telaşıyla ben türkümü söylerken

sen bu aşk masalını efkarsız düşünürdün

Doğru inkar edememem bana değer vermiştin

seni kırmak istemem dost kalalım demiştin

bir kırmızı gül verdim işveli sohbetine

ya ben yanlış anladım ya sen yalan söyledin', 'Ellerim ellerine dokununca üşürdün gözlerine bakardım yüzünü düşürürdün bozuk saz telaşıyla ben türkümü söylerken sen bu aşk masalını efkars...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-ask-masali-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Delik', 'delik-halil-pazarli-e0m6u', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ha ozan tabakası

ha ozon tabakası

Gel bir harf için

kırma beni

e mi', 'Ha ozan tabakası ha ozon tabakası Gel bir harf için kırma beni e mi...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/delik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter artık...!', 'yeter-artik-musfik-saltik-ydrgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bayram ziyaretlerinin yerini 

Tatil kaçamakları aldı

Kandiller için şiirsel mesajlar hazırlandı

Herkes bunlara dadandı

Eli öpülecek büyükler yollara baka kaldı

Teknoloji bize bir numara büyük geldi galiba

Geleneklerimizi unutturdu bağlarımızı kopardı

Her geçen gün  birbirimizden daha çok kopuyoruz

Sanal dünyanın içinde bizlerde sanallaşıp yok oluyoruz

Korkuyorum  yakında mezarlıklara da  bilgisayarlar koyacağız

Ölüm yıldönümlerinde yitirdiklerimize 

Dualarımızı, e-mail le yollayacağız..

                                                                   Eylül 2004', 'Bayram ziyaretlerinin yerini  Tatil kaçamakları aldı Kandiller için şiirsel mesajlar hazırlandı Herkes bunlara dadandı Eli öpülecek büyükler...', ARRAY['Türk Edebiyatı','Şiir','Müşfik Saltık']::text[], 8.5, '{"poet":"Müşfik Saltık","poet_slug":"musfik-saltik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yeter-artik-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vişne Festivali', 'visne-festivali-halil-pazarli-7jn1e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Almus''ta

Tufantepe''nin altında

vişne güzeli olmuşsun amma

küçükhanım küçükhanım

henüz ham sayılırsın

alçak dağları ben yarattım diye hava basma

bir beddua ederim

kız kurusu sevdam gibi

sende evde kalırsın', 'Almus''ta Tufantepe''nin altında vişne güzeli olmuşsun amma küçükhanım küçükhanım henüz ham sayılırsın alçak dağları ben yarattım diye hava ba...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/visne-festivali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gakkk (Ciddi Tavsiye)', 'gakkk-ciddi-tavsiye-halil-pazarli-1iy39', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağlar yücedir ama 

merhamet çıkmaz taştan

Sakın dostluk bekleme 

hançeri gizli puşttan

Kuşlar küçük ve zarif diye

aman ola aldanma

Yarana melhem sürmez

karga mıçtığı moktan', 'Dağlar yücedir ama  merhamet çıkmaz taştan Sakın dostluk bekleme  hançeri gizli puşttan Kuşlar küçük ve zarif diye aman ola aldanma Yarana m...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gakkk-ciddi-tavsiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Bitti', 'ask-bitti-halil-manap-086z8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gökyüzü usulca 

……….naz eden gelin gibi 

…………………..karanlığa gömülüyor

Ve çıplak tenime düşen 

………………….çiy damlaları 

………………………….içime kan olup 

……………………………………..akıyor 

Sen yoksun 

……….maceralarımın 

.................................sessiz 

.......................................kahramanı 

Aşk bitti 

Gürültülü şehirler 

....................beynimi kemirdi 

........................................sonsuzluğa 

..........................................akan bir yıldız gibi 

Sessiz dingin bir hayattır ölüm 

Güneşin 

...göz kamaştıran 

........................ışıltıları 

................................saçlarımı 

................................okşamayacak 

Ve havayı içirtmeyeceğim 

……………yaşarken ölmüş bedenime

Çaresi Y O K 

A Ş K  B İ t t İ 

…………..sen yoksun diye 

……………………….şiirler yazıyorum 

……………………………………. Kendime

Bunu bil ki sevgili 

................senin yerine 

...............................toprağı 

...................................sereceğim 

................................................tenime', 'Gökyüzü usulca  ……….naz eden gelin gibi  …………………..karanlığa gömülüyor Ve çıplak tenime düşen  ………………….çiy damlaları  ………………………….içime kan ol...', ARRAY['Türk Edebiyatı','Şiir','Halil Manap']::text[], 8.5, '{"poet":"Halil Manap","poet_slug":"halil-manap","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ask-bitti-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Dokunuşu', 'sevginin-dokunusu-yasar-yildiz-d5529', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşkın ezgileri

gözbebeklerimizde dillendiğinde,

Can sevginin dokunuşu oldu

kıpır kıpır yüreğimizde.

Ürkütülmüş bir ardıçkuşunun

aceleci kanat titremelerinde.

Buruk sevinçler bulaştırdığımız zaman,

Akdeniz mavisinden çalınmış,

bir avuç ak köpüktü ellerimizde.

Hüzünler, korkular katıp,

harmanlamıştık bir yerlerinde.

Tutamadık, tutunamadık,

parmaklarımızın arasından akıp gitti işte.

Silmiştik geri dönüşsüzce

ayrı yaşanmışlıkları.

Gözlerinin adı konmamış

yeşillerine boyamıştık 

yaşamdan geri kalanları.

Aysarısından tenimize

damla damla seviler akıttık.

Lacivert gecelerin yaşamsız kuytularında,

ayrılıkların, bırakıp gidişlerin

hain pusular kurduklarını anlayamadık.

Yine de; 

Her ışıltısına yakamozun

umutlarımızdan bir dilek yazdık.

Herbir yıldıza yarınlardan,

yaşanası bir gün asıp bıraktık.

Ayrıldık...', 'Aşkın ezgileri gözbebeklerimizde dillendiğinde, Can sevginin dokunuşu oldu kıpır kıpır yüreğimizde. Ürkütülmüş bir ardıçkuşunun aceleci kana...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sevginin-dokunusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Daha Ne İsterim!', 'baska-daha-ne-i-sterim-ahmet-refik-tavsanli-7qrgr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok Şükür! Hayattayız Bak!  	 

Başka Daha Ne İsterim! 	 

Bin Şükür! Ayaktayız Çaak!     	 

Başka Daha Ne İsterim! 	 

	

Yaşıyoruz Bu Gün Yine	 

Diyecek Yok Morâlime 	

Şükürler Olsun Rabbime 	

Başka Daha Ne İsterim! 

Sağlık-Sıhhât İçindeyim 	

Tutuyor Ayağım Elim 	

Kimseye Muhtaç Değilim	 

Başka Daha Ne İsterim! 	

Sevgi Dolu Şu Yüreğim	

Kimseye Yok Hiç bi’ Kin’im 	

İçim Rahat Müsterîhim 	 

Başka Daha Ne İsterim! 	 

		

Selâm Gelsin, Selâm Gitsin 

Kimse Benden İncinmesin	

Eşim-Dostum Eksilmesin 	

Başka Daha Ne İsterim! 	 

	

Olmasa Param-Pulum da 	 

Hattâ Bir Çift Pabucum da 	 

Ölüm Yok’ ya Son’Ucun’da        	

Başka Daha Ne İsterim! 	

Allah Vekîl Allah Kerîm! 

Ben Hiç İsyân Eder’miyim 

Akşama da Var Ekmeğim 

Başka Daha Ne İsterim! 

Hiç Bir Şeyi Dert Etmeyin 

Beteri Var Her Bir Şeyin

Bu da Geçer Elbet Deyin 

Başka Daha Ne İsterim! 

Say Bak! Neler’in Var Şükret

Değer’mi Çekmeye Mihnet 

Elde Var’ken Bun’ca Nimet 

Başka Daha Ne İsterim! 

Kahredenler Deli’mi Ne?   

Kim Cep Dikmiş Kefen’ine

Kanâat Et’Sen Elde’kine 

Başka Daha Ne İsterim! 

Hayatta Hep bi’ Bardağın

Dolu Tarafına Bakın… 

Mutlu Olun! Çok Yaşayın

Başka Daha Ne İsterim! 

Ahretahû Sağolasın! 

Dostlar Seni Unutmasın! 

Her Şey Yarın Böyle Kalsın! 

Başka Daha Ne İsterim! 

(AH) met-(RE) fik-(TA) vşanlı-(HÛ) 

Ahretahû.

09.09.2002.(10.10) 

27.07.2011.(15.45) .

Karşıyaka', 'Çok Şükür! Hayattayız Bak!  	  Başka Daha Ne İsterim! 	  Bin Şükür! Ayaktayız Çaak!     	  Başka Daha Ne İsterim! 	  	 Yaşıyoruz Bu Gün Yine...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Refik Tavşanlı']::text[], 8.5, '{"poet":"Ahmet Refik Tavşanlı","poet_slug":"ahmet-refik-tavsanli","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/baska-daha-ne-isterim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükendi', 'tukendi-baykal-kaanalp-bayzi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir çok mutluluk 

damıttığımız

elma şekerlerimiz

tükendi

biz sadece

ona bakmakla

yükümlü olmadığımız

düşlerimizi kaybettik

kesin olan bir şey varsa

kuramadığımız saatimizde

oda gerçek olması

gerçekleşmeyecek

buluşlarımızın

sonuna kadar

ilerleyemeyecek oluşu

tatlılığımızın

(tatlandırmaya çalıştığımız

tatsız damak

tadımızın)', 'bir çok mutluluk  damıttığımız elma şekerlerimiz tükendi biz sadece ona bakmakla yükümlü olmadığımız düşlerimizi kaybettik kesin olan bir şe...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tukendi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşimiz Ne Bugünle?', 'i-simiz-ne-bugunle-baykal-kaanalp-xivpu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'işimiz ne bugünle? 

biz dünü yaşamıyor muyduk? 

seninle

ve kumsalsız denizimizle

ateşli aşkların

yaşandığını zannettiğimiz

ama farkında olmadığımız

işimiz ne bugünle? 

yarışmalar bitmedi mi? 

hala üzerimizde oynanan

alay konusu mu? 

bütün bunlar

hedeflediğimiz varamadığımız

işimiz ne bugünle?', 'işimiz ne bugünle?  biz dünü yaşamıyor muyduk?  seninle ve kumsalsız denizimizle ateşli aşkların yaşandığını zannettiğimiz ama farkında olma...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/isimiz-ne-bugunle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Hayata Umutsuz Değilim', 'hala-hayata-umutsuz-degilim-baykal-kaanalp-s76y1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'çılgınlık bu biliyorum

ama olmasını dilemiyorum

ipin ucunun kaçmış olmasını

hala kabullenemiyorum

hala hayata umutsuz değilim

farkındayım bu yanlış bir eğilim

ipin ucu kaçabilir bu sorun değil

aslolan mutsuzlukdur sevgilim', 'çılgınlık bu biliyorum ama olmasını dilemiyorum ipin ucunun kaçmış olmasını hala kabullenemiyorum hala hayata umutsuz değilim farkındayım bu...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hala-hayata-umutsuz-degilim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* * * ÜÇ YüREK * * *', 'uc-yurek-baki-son-kwp3k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Üç yürek, bir sevdayken

Üç yürek...! ! ! 

Sen çok şeyden habersiz,

Bir şiir okunurken, bir şarkı söylenirken

Ve bir ağız susarken 

..........................GÜNEŞ BATIMINDA

.........................................

Sen çok şeyden habersiz

Dalarken şiire, şarkıya, sessizliğe

Özgür bir kuş misali semalarda...

Kon artık sevdiğim, bir sevdanın kollarına

Belki de okunacaktır artık şiirler başkalarına

Belki de söylenecektir türküler birilerine 

Ve ufukta beklenirken hayalinle sonsuzlukta...

Ama bil ki! ..

Mutluluk gözlerin en derininde...', 'Üç yürek, bir sevdayken Üç yürek...! ! !  Sen çok şeyden habersiz, Bir şiir okunurken, bir şarkı söylenirken Ve bir ağız susarken  ............', ARRAY['Türk Edebiyatı','Şiir','Baki Son']::text[], 8.5, '{"poet":"Baki Son","poet_slug":"baki-son","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uc-yurek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anneciğim', 'annecigim-i-lhan-palali-tdo9q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-Bütün Annelere-

Buğulu hayalin rüyama beşik,

Olur da sallanır, durur annecim...

Dertlerim, gönlümü çaresiz, kırık,

Bulur da çullanır, durur annecim...

Böylece girerim yeni günlere,

Mutluluğa veda, veda dünlere...

Ruhumsa yaklaşan kötü sonlara,

Bakar da dellenir, durur annecim...

Yokluğun ıstırap vermekten öte,

Bir kurşun sıkarak, sermekten öte,

Canımı ateşle sarmaktan öte,

Yakar da küllenir, durur annecim...

Bana ettiğini, gör de dünyanın,

Titresin oğlunu her seven yanın...

Şafakta giderek ağaran anın; 

Çöker de pullanır, durur annecim...

Yalnızım; gözümü korkutur şehir,

Aşkımı etmişim sonsuza tehir...

İçimin mecnunu dağlara şiir,

Okur da dillenir, durur annecim...

Gördün ya; hasretle geçiyor zaman,

Sitemle, nefretle, ümitle... yaman! 

Gözyaşım gözümden boşanıp, aman,

Akar da sellenir, durur annecim...', '-Bütün Annelere- Buğulu hayalin rüyama beşik, Olur da sallanır, durur annecim... Dertlerim, gönlümü çaresiz, kırık, Bulur da çullanır, durur...', ARRAY['Türk Edebiyatı','Şiir','İlhan Palalı']::text[], 8.5, '{"poet":"İlhan Palalı","poet_slug":"i-lhan-palali","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/annecigim-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Speech-dome', 'speech-dome-akin-akca-3qp5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '1. 

Strength on fingers of hands in strings

while mouth gives Tongue; 

Star particules, you fertilize - 

Upon the dommes 

~~ (periphery for any diameter, 

~~ that these music can not help; 

~~ dommes are, by itself: 

~~ to be here, it’s so far..)

there and there, on their road: 

an angle will alwais 

have been known … 

2. 

Is freedom, speech-dome? 

i, so, am getting been bitten 

by the silence of the snake. 

Thus, golden, activated, gets 

shiner and with herself, 

standing when it''s holden. 

It’s precious to be calm, sincerely; 

in such a difficult situation: 

For any destination, no hesitation - 

with all the hazardous garbage stuff. 

Needless to say: 

Consideration’s our thoughts, 

when our droughts, are ours... 

* 

Whereas your speech, 

are your sentences; 

Hugging the bridge gates - 

~ Riders on the storm, like The Doors; 

~ Pink Floyd are us, like it seems 

- Comes from such dreams: 

you caught a toon, 

named honeymoon. 

çeviri: 

1. 

~~ (Ağız, dili verdiğince, 

~~ Parmaklar, kapanan, el için, kuantum titreşenlerinde)

Edilgenliği bir karış dilin, 

Yıldız tozlarıydı - 

~ dökülen 

- Üzerine kubbelerin, 

~~ (çeperine nota biçemeyen kubbeler, 

~~ kendi olan kubbeler, 

~~ fazlaca yakındı, kubbeler)

Kendinde, oraya buraya 

bakanın ilerisinde … 

2. 

Söyleme kabiliyeti midir, özgürlük? 

Yılanın sessizliğince, ısırılıyorum öyleyse. 

Böylece, altın cinsinden, hareket verilmiş; 

Kendisi ile ve, o; parlarken daha da; 

ayakta dimdik, anladığınca tutulduğunu. 

Samimi biçimde, değerli yeterince - 

~ serinkanlı, temas kurulmuşluğunu... 

~: Duraksama yok, varışlar için 

- Zararlı atıklardan doğru, uzağa gidin! 

Gereksiz bir söylem olur: 

Kuraklıklarımız bizimdir de; 

Düşüncenin düşünmediklerimiz 

Olduğunu söylemek, bu vakitler. 

* 

Söyleme becerin olduğunda, senin cümlelerin; 

Kucaklıyorken köprü geçiş noktalarını; 

Nezaketin ufkunda, arkadan gelir: 

rüyalara … 

Rüyalarında, Pink Floyd’vari; 

Fırtınanın üstü sürücüleri, kapı gibi! 

: yüksek umutların’da, işte; 

birini çağırdın, çizgi filmlerden … 

~~ (İninde uyumadığında, ayı; bal mı yer? - 

~~ Üstünde arıların, çiçeklerin koşuştuğu?)

Renkli sayfalarda; balayı, adına denen …', '1.  Strength on fingers of hands in strings while mouth gives Tongue;  Star particules, you fertilize -  Upon the dommes  ~~ (periphery for ...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/speech-dome-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşe doğru yüzüm', 'gunese-dogru-yuzum-burhan-kucuk-fz2oy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşe doğru yüzüm

	

Yemyeşil ormandayım

Sevincim...

Takılır kursağımda

Çiğ tanesi gibi

Kalakalırım...

Karanlığın tam ortasında

Dört duvar etrafım

Yankılanmaz sesim

Bir gecelik ıslaklıkla

Ki..

Kalkıp gideceğim

Güneşe doğru yüzüm

Burhan KÜÇÜK

Kdz.Ereğli-30.09.2004', 'Güneşe doğru yüzüm 	 Yemyeşil ormandayım Sevincim... Takılır kursağımda Çiğ tanesi gibi Kalakalırım... Karanlığın tam ortasında Dört duvar e...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gunese-dogru-yuzum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berat Gecesi', 'berat-gecesi-bayram-tunca-3wvjt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugece karar gecesi

Beratlarını alır nicesi

Yüzüne vurur neşesi

Bazıların da endişesi

Bulutlar rahmetin habercisi

Cemreler baharın müjdecisi

Berat Ramazan’ın müjdecisi

Öyle diyor Rabb’imizin elçisi

Gecelerin her birinin ayrı özelliği

Farklıdır ayların özelliği/güzelliği

Beratın da farklı özelliği/güzelliği

Bugece dua diler ümmetine Nebi

Bugece hakkımızda karar verilecek

Beratını alanlar, sevince boğulacak

Alamayanlar üzüntüye gark olacak

Yapılacak hasbi dualar etkili olacak

Berat bizler için tanınan en iyi bir fırsat

Bu fırsatı değerlendirmek için gafleti at

Bulunmaz hiçbir gecede böyle bir fırsat

İhtimal cennete gitmek için verilir kırat

29.09.2004-09.29', 'Bugece karar gecesi Beratlarını alır nicesi Yüzüne vurur neşesi Bazıların da endişesi Bulutlar rahmetin habercisi Cemreler baharın müjdecisi...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/berat-gecesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağ Üstüme', 'yag-ustume-tunahan-ermihan-3h3qk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Küstüm sana sevdiğim kelimeler anlamını yitirdiği için

Her satıra seni anlatırdım sayfalar yetmezdi

Kelimelere adını gizlerdim sır olurlardı

Araya giren nedir bilmem ama mana gitti cümlelerden

Küstüm sana sevdiğim yağmurlar daha başlamadığı için

Oysa ben sana hep yağmur yağdığında kavuşmuştum

Yaz sıcaklarından hep korktum sensizlik oldukları için

Topraklar kurumaya başladı ben yağacağım ey baharım

Küstüm sana sevdiğim gecelerim sensiz karabasanlara mahkum kaldığı için

Oysa sen rüyalar ülkesinin prensesisin

Ve öyle alıştırdın ki her gece rüya tadında ki geçeklere

Bu dolap canavarları dar getiriyor geceyi yağ üstüme sevdiğim', 'Küstüm sana sevdiğim kelimeler anlamını yitirdiği için Her satıra seni anlatırdım sayfalar yetmezdi Kelimelere adını gizlerdim sır olurlardı...', ARRAY['Türk Edebiyatı','Şiir','Tunahan Ermihan']::text[], 8.5, '{"poet":"Tunahan Ermihan","poet_slug":"tunahan-ermihan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yag-ustume-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçiyor Ömrüm Bomboş', 'geciyor-omrum-bombos-caner-kuru-gm55e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayaller içindeyim,

Gerçek olan yanım yok.

İstesem de olmuyor,

Sevmeye hiç canım yok.

Geçiyor ömrüm bomboş,

Bir tek tatlı anım yok.

Benim garip halimi,

Anlatacak tanım yok.

Beni aşka coşkuya,

Taşıyacak kanım yok.

Ömrümün baharında,

Yeşermiş bir dalım yok.', 'Hayaller içindeyim, Gerçek olan yanım yok. İstesem de olmuyor, Sevmeye hiç canım yok. Geçiyor ömrüm bomboş, Bir tek tatlı anım yok. Benim ga...', ARRAY['Türk Edebiyatı','Şiir','Caner Kuru']::text[], 8.5, '{"poet":"Caner Kuru","poet_slug":"caner-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/geciyor-omrum-bombos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şuurdan Damıtmalı Şiirlerim', 'suurdan-damitmali-siirlerim-mehmet-ozcelik-hcu2y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ŞUURDAN   DAMITMALI   ŞİİRLERİM



                                               İ   M   Z   A

         Ö mür durmaz,geçer gider.

         Z aman kalmaz,göçüp gider.

         Ç aylar akar,nehir gider.

         E bed ister,uçup gider.

         l akin gitmez,kalır bir şey.

         İ nsanlık,iman,fazilet,ihsan.

         K alır bunlar,cesed gider.



         M ü’mine olur imanı yar.

         E bedi cenneti,Allah’ı var.

         H alıkdan ğayrısı ona bar.

         M ümkinat olur,insana dar.

         E vren ma’rifetine temaşagah.

         T oprak mebde’ ve müntehagah.



                   O LA B İ L M E K

         Yunus olup,konuşabilmek,sevgiyle sevebilmek.

         Mevlâna olup dönebilmek,aşkıyla yanabilmek.

         Bediüzzaman olup haykırabilmek,azimle yürüyebilmek.

         Sahabe olup anlayabilmek,Kur’an-a muhatab olabilmek.          

         Ne mutlu,onları bilmek,onları anlayabilmek.

         Onlar gibi olup,onların yolunda yürüyebilmek.



         Aşmak istiyorum engin dağları.

         Taşmak istiyorum zengin gönüllere

         Dermek istiyorum kökünden gülleri.

         Gelmek istiyorum bahçendeki bülbüllere.



         İstiyorum Yunus gibi şakımak.

         İstiyorum Mevlâna gibi yanmak.

         İstiyorum Mevlâna gibi kucak açmak.

         Yunus gibi bağra basmak.



         İstiyorum Hallac gibi yanmak

         İstiyorum Mevlâna gibi kucak açmak.

         İstiyorum Yunus gibi şakımak.

         Yunus gibi bağra basmak...







                   KAFAYI    KAYBETMİŞ

         Kol kola yürümekte iki keş

         İçleri ise dopdolu leş.

         Birbirlerinden olmuşken sefil

         Sarmaş-dolaş,sanki birbirlerine kefil

         Utanmadan,getirmedeler şehadet

         Halleri kendilerine etmede şehadet

         Bir yandan aileni ez-ezil

         Ahirette Allah’a,dünyada halka rezil.



                            HATIRA

         Hatıra hatır içindir.

         Şükrümüz Fâtır içindir.

         Hatır içindir hatıra.

         Şükrümüz ancak Fâtıra.

         Zaman akar sel gibi.

         Ömür geçer yel gibi...



                            BATASICA  BATI

         Tüm batı birbiriyle birleşdi

         Oysa onlar ki tam bir leşdi.



                            NAMAZ

         İmandan sonra ilk namaz.

         Aciz insanın sermayesi ona niyaz.

         Her ne mikdar yapsak da,az.

         Ey Rabbim! birimizi bin yaz.

       

         İnsanı insan yapar namaz.

         Namazsız iş,işe yaramaz.

         Namazsız amel aranmaz.

         Olmadıkça namazdan nasibi biraz.



         Ebed yolculuğunda bilet.

         Parlatır alnında nuru müebbet.

         Yirmi dört saatten birini sarfet.

         Fani ömrü,bakiye kalbet.



         Kazandırır insana define

         Şaşarım senin bu haline.

         Yan gelip bak bakalım keyfine.

         Girersin tek başına kabrine.



         Münker-Nekir halin sorar.

         İyiden iyiye iyice sorar.

         Paçavraların içinde cevher arar.

         Fakat nafile,-yok- ki,boşuna arar.



         Bir ip ve küfenin hesabını veremezken fakir.

         Bunca ömrü nasıl geçirirsin hakir.

         Kıyamet kopar,bitmez hesab.

         Hesab için açılır,açılır ikinci bab.



         Her şeyden önce sen bir insansın.

         Yaratılmadın hoplayasın,zıplayasın.

         Sürülür beşer mahşere.

         İster Peygamber,ister Aşere-i Mübeşşere.



         Nefsi nefsi der,feryad eder.

         Son andaki pişmanlık ne eder? 

         Mizan terazi kurulur.

         Kâfir durur mu,kudurur.



         Sened yok elde,herkes me’yus.

         Derse; -zalimlerden oldum-  Yunus.

         İnce elekten elenir.

         Düşünürüm,bana ne denir? 



         “Ey Mücrimler,bu gün ayrılınız.”

         “Mü’minler cennetim de kalınız.”

         Sırat köprüsünden geçilir.

            Namazsız yol,çileli geçilir.



         Namaz kişiye bilet ve azık.

         Namazsıza dünyada ve ukbâda olur elbet yazık.

         Ancak,bozmuştur Allah’a verdiği sözü.

         Görünce binlerce cezbedeni,gözü.



         Ya Rab! her ne kadar ettiysem gaflet.

         Sen affedicisin,bizleri affet.

         Günde beş defa huzuruna yapılırken gaflet.

         Durmam,koşarım,kılarım elbet.

         Vardır bunlarda binlerce hikmet.

         Ya Rab! Bizi namaz ve rasulünle haşret...





                            C İ M R İ

         Pek de bağlı ve sıkıdır cebine

         Sebeb olur,güzel hasletin selbine...



                            İ B R E T

                Deme, ne kıymete sahib insanlar.

         İnsanlara ancak ins anlar.





         İnsana ibretle bakanlar.

         İnsanı o zaman anlar.



         Her insan ayar ayara

         Kimi beyaz,kimi kara.

         Kiminin tapınağı para

         Kimininkiyse Moskova.

       

Kalp kara,vicdan kara,fikir kara.

İbret...Toplum için en büyük yara...



                   S O N   -    B A Ş L A N G I Ç

Ne gariptir kalbler harabe.

Cevherler kalbolmuş turabe.

Ötmekte etrafta bir sürü yarasa.

Bir sürüsü,bir işe yarasa.



Ötmeli bu ilahi sarayda bülbül.

Çınlatmalı etrafı gümbür gümbür.

Aydınlatmalı,saçmalı etrafa nur.

Bilinmeli artık kim doğru,kim kambur.



Kur’an-ın etrafında halelenmeli sur.

Kenetlenmekle olur İslâm mansur.

Zaman son,sermaye son,oynasa da son kozunu,

İmandan almalı dozunu,savurmalı son tozunu.



İmanla süregelen küfre demeli artık dur.

Senaryo bitti,artık oyun sondur.

İbretle bak,düşün,gittiklerinin izine.

Ya bir küpdür veya bir düzine.



Vakit geçdi,dönelim artık saadet asrına

İlk ve son menzil,Allah’ın kasrına.

Düşsek de zamanın şiddetli kışına

Kavuşuruz inşaallah,o bahar faslına.



Beklemede bizi Ömer’ler,Osman’lar,Hamza’lar.

Teklemede bizi Devrimler,Savaşlar,zamaneler.

Geri bırakan ne seni,Hak din ile,Din mi? 

Tekleyip teşvişi,Hakikat,Hak dinledin mi? 





Sürdü devran Ebu Cehiller de? 

Sürer mi gönüllerde,ebedlerde? 

Saldırsalar Kur’an-a,dini vurub,

İşte,evet işte,gelmede Devri  Mev’ud.



Haktır. İslâmiyet güneş gibi doğmada şimdi.

Küfrün son hamlesi,çırpınmada deli gibi.

Son. Küfrün ne hazin kapanışı.

Başlangıç. Mü’mine cennetin açılışı...

                           

                                      ZULMET    VE   NUR

         Gök yüzünü kaplamış çepe çevre sis.

         Yer yüzünü doldurmuş lebâleb is

         Maddi alemi kaplarken bunca felaket

         Akıl,kalb ve ruhun hastalığı ne büyük felaket.

         Bu duygular iman ve Kur’an-dan olurken bi-behre

         İç alemini dışa aksettirmede çehre

         Düşmanımızdır yeis,me’yus değiliz.

         “Lâ taknatu min rahmetillah”deriz.

         Kur’an der:asrı zulmet,asrı nur.

         Kalb,kalıbı ve kabri zulmet veya nur.

         Allahım! Eyle semamızı-arzımızı nur.

         Nifak ve küfrü,hem de zulmü eyle, dur.

         Mü’min uyansın,nura boyansın.

         Kur’an denizine dalsın,imanda kalsın.

         Allah,rasul ve kitabın aşkıyla yansın.

         Gaflet,dalalet,cehaleti cephe alsın. 

         Şükürler olsun Rabbim. Gönderdin o nuru.

         Bunalan milletin âfakı buldu süruru.

         Birlik,beraberlik; atık teşviş ve gururu.

         Dünyanın cennet asa baharı,İslâmın gururu...



                 



         ASRI   BEDİ’  -      SAHİBİ   BEDİ’

         Gerek işde,gerek sözde

         İlim ve kemâlâtı ederken elde.

         İnsanlığa lazım,kısa ve salim öz-ler.

         Bin senedir böyle bir hakikatı öz-ler.

         Bekler bir nuru Bedi’,zuhurunu gözler.

         Ancak görür basar ve basiretli gözler.

         Yarasa tabiatlı olan görür mü gözler? 

         Önünde dururken Mektûbat,Lem’alar,Sözler.

          Ne garib bir asırdayız üstadım.

         Deriz; olayım ÜST,duyulsun ADIM.

         Rabbim,nusretinle bize ol zahir.

         Zira halimiz,sana zahir.



                   O Ğ L U M A

         Severim oğlumu,çünki yazar.

         Her ne kadar yazsa da sonra bozar.

         Öğretiriz öğrenir,azar azar.

         İlgilenmeyince,ilgilendirmek için azar.



         Sorarım,tabiatı kim yarattı? 

         Sararan yaprağı,kim sararttı? 

         Vücudu kimden aldın,kim sattı? 

         Der; elbet Allah yaptı.



         Yaratılışı İslâm fıtratı.

         Fıtratı Allah hilkatı

         Film gibi her şeyi çeker.

         Elbet insan aslına çeker.

       

         O fidana bir şeyler vermeli

         Vermeli ki; verileni dermeli.

         O fide ailenin göz ve eli

         O’na Rabbisini bildirmeli.



         Bildirmeli,ta ki Allah desin

         Niçin yaratıldığını bilsin.

Bilsin ki kendisine gelsin.

Geldiğinin şuuruna ersin.



Ermeli Ma’rifete.

Gelmeli Hakikate.



Girmeli Şeri’ate

Varmalı Rü’yete.



Koydum adını Muhammed Fatih

Ecdadı gibi yapsın diye fetih.

Rabbimden dileğim hıfzetsin onu.

Hüsnü Hatimeyle neticelensin sonu...

                                                                  17-12-1992 / Malatya



                            HUKUK    İLE    GUGUK

Etmeyin,acıyın,kıymayın bize.

Babamın halini arz edeyim size.

Babamın babasının  arsası vardı

Çıktı biri,dedi; bu bana babamdan kaldı.



Başladı dava gel-gitle.

Pek alâkası yok bitmekle.

Dosyalar doluyor,kapanıyor.

Geceler gündüzleri kovalıyor.



Babamın öz malı,nasıl olur? 

Bir başkasına mal olur? 

Köylerden geliyor mahkemeye.

Bilmem; mahkeme mi,yoksa hapishane? 



Beş sene,on sene bitmedi.

Bu nasıl mahkeme,bitirmedi.

Olsun mu herkes başkasına sahib? 

Peki bu devlet,mahkeme kime sahib? 



Bıktım,usandım,vaz geçeceğim.

Vazgeçip nerdeyse delireceğim.

Şahit çok,herkes lehimizde.

Netice yok,çünkü biri aleyhimizde.



Delil,şahit,hep bizden yana.

Peki bu mahkeme kimden yana.

Bir türlü vermiyor karar.

Aleyhimize de olsa,olmaz böyle zarar.



Kaç kere geldiler,baktılar yerimize.

Gene de hiçbir şey geçmedi elimize.



Yük üzerine yük oldu belimize

Mezardaki dedem gülmede halimize.



Hâkim Beg! Acaba hâla gelecem mi? 

İnsan bir kere ölür,girer mezara.

Ben yine mezara girecem mi? 

Adâlet mülkün temeli,diyecem mi? 





Vallâhi hakim beg,bu mal benim.

Eğer onunsa vercem,etsin yemin.

Şahitlerde söylemişti demin,o benim.

Hiçbir şeyi olmayan,olur mu emin? 



Kaç dane hâkim değişdi.

Bizim iş ise değişmedi.

Babam gitdi,bende gideceğim.

Bu işi oğluma devredeceğim! 



Acaba oda kazanır mı? 

Yoksa benim gibi kazıklanır mı? 

Bu tarla babamı götürdü,beni de götürecek.

Benden sonra oğlumu da öğüdecek.



Bu iş süreceh mi,yoksa sileceh mi? 

Çoğumuzu silecek,ne kadar sürecek? 

Bu iş bitmeyecek,bitirecek.

Kimleri bitirecek,kimleri götürecek? 



Olacak mı ne,olacak mı ne? 

Hâkim bana bakdı,verecek mi ne? 

Ohh. Mahkeme bitecek,biz de bittik.

Bir değil yüz gittik,ne elde ettik? 



Yine hâkim değişti,ne olacak şimdi? 

Bu ne diyecek,bahacah mı imdi? 

Ayağıma karasular indi.

Bizim iş tam bir filimdi..



Dosyalar doldu,sürdü yıllar.

Okunması ise,aldı aylar.

Karalar,karalar üstüne karalar.

Bunca yıl o kadar harcadım paralar.



Bu hâkim Beg,kaldı çokça.

Dinledi bizi,bol bolca.

Dosyalar tozlandı,yıllar boyunca.

Ya ondadır,ya bunda,olunca...



Eeh. Helal malmış,düşdü bize.

Geçdi tapumuz elimize.

Mütaide verdik,geçdik evimize.

Başınızı ağrıttık,selâm hepinize... 





                            A Ş K I    H A K İ K İ

Bir koltukta oturur mu iki sultan? 

Biri hak ise diğeri yalan.

Bir kalbe girmez iman-küfür.

Birini ko,diğerini sür.

Gerçek olmaz,hem Allah,hem dünya sevgisi.

Biri kalır ise durmaz diğer birisi...





                            M Ü F L İ S

Haramı yeme,olmuşsa da beleş.

Çalış,didin,al eline bel,toprağı eş.

Azığını yükle,oymasın heybe leş.

Yoksa derler; ne yüzle geldin be,leş...





                            500  SENELİK   UYKU

Uyuttular bizi söyleyerek bir sürü masal-anı.

Yutturdukları şeyin hiç de yok tutar yanı.

Sudan ucuz oldu müslümanın akan kanı.

Ya Rab! İslah veya kahreyle İslâma yan bakanı...



                            A N A M A

S elam olsun sana ey vefakar ana

A si oğluna dua et,feda et yaradana.

L akin karşı geldim affeyle,bağırdım sana.

İ sterim insanca insan olayım,insandan yana.

S efih nefis bırakmaz ki,ruh,akıl Allah için yana.

E sas gayemi anlıyamadım,varıncaya kadar bu ana..





                                      GÜLLER   VE   DİKENLER

         Sarılın toprağa,esmekte yeller.

         Salın kökleri,götürmesin seller.

         Küfrün yayılmasına seçilmiş tren.

         Taze güllerin ezilmesine geçilmiş neden? 

         Maksad..köküyle ilgisini kesip soldurmak.

         Demir kıskaçlar arasında boğdurmak.

         Körpe fidanlara saldırıp ezmekte tren.

         Ne takos dinliyor,ne de fren...



                                      TEKERLEME

         Zaman sanki tekerlek.

         İnsan gider tek tek.

         Hayat şimşek şimşek.

         İnsan gidicidir,yok şüphe-şek.

         İnsan akan bir su.

         Varlıkların en ulusu.

         Bir bulut gibi oda akar gider.

         Son durakta oda iner.

         Dünya bir okul.

         Sadece orada o kul.

         Ömür kurulmuş bir bina.

         Madde ile mâna

         Görülen ile görülmeyen

         Dünya ile ahiret yan yana.

         İnsan defterden bir yaprak.

         Kiminin alnı siyah,kiminin ki ak.

         Hatırasıdır 7-B sınıfının bana

         Talebeleri nedense çok yakındır cana.

         (Bunun üzerine iki talebemin benim için yazdıkları şiirde :) 



                            DİN   HOCAMIZ

         Laf dediler aldırmadı.

         Hiçbir zaman kaçırmadı.

         Tek bir emeli vardı.

         Oda; gururlu olmaktı.



         Melek gibi kalbi vardı.

         Hiçbir kötülüğe yanaşmazdı.

         İyilikleri hep severdi.

         İyilikle muradına erdi.





         Dinlemeliyiz hep onu

         Yararlıdır bunun sonu

         Sevmek yaraşır ona

         Sevelim kana kana.



         Melek yüzlü hocamız.

         Şirin sözlü hocamız.

         Ne kadar da iyisin

         Teşekkürler hocamız.



         Gürültüyü sevmezdi.

         Dürüst ve temizdi.

         Kalbindeki tek şey

         Öğrencilerini sevmekti.



         Amacı ışık tutmaktı bize.

         Öğüt verirdi hepimize

         Gurur verirdi içimize

         Güneştir bizim hocamız.

                                                        Leman,Songül.   25-5-1987



                          

                            K O M Ş U

         Sorumluluk üzere göndermiş insanları Hak.

         İnsanlara muamelesi Adalet ile Hak.

         Merhametiyle affeder her türlü hakkı

         Ancak kalır,komşu ve kul hakkı.



         Komşu komşunun külüne olurken muhtaç

         Müslüman olur mu kendisi tok iken komşusu aç? 

         Hâliyle-kâliyle komşuyu etmek rahatsız

