INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Başkasın', 'sen-baskasin-mustafa-acar-nmm8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sida''ya ithaf

Anladım sen başkasın

Baktığın gördüğün anladığın şeyler başka

Toprağın  suyun başka

Sen başkasın

Anladım sen başkasın

Nasıl vurdun beni 

                            -göğün dibindeyim şimdi-

Bütün yıldızlarımı şarkıların aldı

Aynı yolculukta öpüştük

                         Ben aynıydım

                                              Yol aynı

Sen başka

Anladım sen başkasın

Belki kördür gece ışığında

Dünya bütün kirlenmiştir felçtir

Her şey aynı renge boyanır

Aşk bile

Sen başka

Anladım sen başkasın

Gül yok artık görsen

                              Sevgiler nasıl şaşkın

Kimseler bilmiyor örneğin

                                özlemin gülüşünü

Ve gülmüyor senin gibi

Sen başkasın

Güzel şeyler   yok değil

Baktıkça görüyorum

İşte şurda bir çiçek

                            Şurda bulut şurda su

Bütün zamanlar boyunca güzel 

Ama aynı

Her şey aynı

Sen

       başka', 'Sida''ya ithaf Anladım sen başkasın Baktığın gördüğün anladığın şeyler başka Toprağın  suyun başka Sen başkasın Anladım sen başkasın Nasıl vu...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Acar']::text[], 8.5, '{"poet":"Mustafa Acar","poet_slug":"mustafa-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-baskasin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayın Ondördü', 'ayin-ondordu-zubeyde-yilmaz-vbusq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gece uzun uzun yazabilirim 

Anlatabilirim usanmadan 

Aylardan bir ay ağustos

Ayın ondördü...

Ben çılgınım sevdanda hatırlarmısın

yıldızlarımız var bizimle danseden

hani bir elinde kadeh,bir elinde ben

Şarkılar söylüyorsun durmadan 

yüreğim olan, yüreğin olan..

kadınım,sevdam,hayat pınarım..

hani bir elinde kadeh,bir elinde ben

beklediğim sendin hayalim sendin

ağlamalarım bitti seninle saklandım ben...

giz bahçem,sızılarının bitişi, son durağım

sen söylemiştin yalnız ben olacaktım ben..

hadi bir elinde kadeh bir elinde ben

bekle beni demiştin gözyaşı haram ikimize

hani sevmeye engel değildi mesafeler

hani demiştin seviyorum sevdalıyım ve hatta deliyim

hep seninim...hep seninim...hep seninim..

bu gece uzun uzun yazabilirim

Anlatabilirim usanmadan demiştim

Ama dönmedi sevdam dönmedi geri 

Çok devrildi gözümün önünde.

Ayın ondördü...

Çok yağmurlar düştü üstüme

Çok çiğ  taneleri yüreğime...

ve sevişmeleri unuttum delice...

Hiç düşünmedin hiç sızlamadın 

Hani demiştin ya,ben sevdanla deliyim

Gittin şimdi ben hicranında deliyim..

Ve ben...

yazmıyorum daha fazla vazgeçtim...

ne kadar nefesim kaldı ki....gönlüm kırık...vazgeçtim...', 'Bu gece uzun uzun yazabilirim  Anlatabilirim usanmadan  Aylardan bir ay ağustos Ayın ondördü... Ben çılgınım sevdanda hatırlarmısın yıldızla...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ayin-ondordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Kırılış', 'i-lk-kirilis-mustafa-acar-mumqm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir elim vardı benim

Na  şu kadarcık

Tanrıya tutardım kış geceleri 

şimşek çakardı sık sık

Kafam na şu kadardı  benim

Estiğince giderdim ne güzel giderdim

Bol renkli  uçurtma olurdum  bazen göğümde

Coşunca  bulutum derdim

Ayaklarım vardı benim pamuk  sanarsın

Yakalayıp yakalayıp gıdıklardı babam 

Hele bir çimdiklesin de  görsün gününü

Falakaya yatardı ablam.

İpeğim derdi  okşardı  eve geldim mi annem

Saçlarım  vardı benim  öyle yumuşak

Avlumuz yağmur  kokar ıslanırdık hem

Hiç böyle değildi toprak

    

Bir kalbim vardı benim  arsız  kocaman 

Gökkuşağı olurdu  bana  diyelim ki sıkıldım

Bütün imkandı herşey  renk ve sevgiyle harman

Ben ilk 

Babam  hiç  param yok dediğinde kırıldım', 'Bir elim vardı benim Na  şu kadarcık Tanrıya tutardım kış geceleri  şimşek çakardı sık sık Kafam na şu kadardı  benim Estiğince giderdim ne ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Acar']::text[], 8.5, '{"poet":"Mustafa Acar","poet_slug":"mustafa-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ilk-kirilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına', 'tek-basina-selcuk-sahin-4odks', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Tek Başına

Tek başına yürünür yollardan

bahçelerinde portakal,limon

mandalina olan evler arasından..

Tek başına

restoranın tek masasına

oturulur,

rakı tek başına

yudumlanır,

fava tek başına

yenir.

Tek başına gidilir bu

dünyadan giderken,

tek başına geldiğin gibi..

Şizofren olası gelir insanın

dağıtmak için yalnızlığını,

rakını tokuşturduğun 

su bardağı olmaz 

o zaman.

Böyle dolmazsın bordo örtülü

masanın üzerinde...

Tek başına koşarsın,koşarken.

Kendine vardığında,

kapını çaldığında

içinden dostların

taşarlar...

26.11.2003 Aydın /Söke

(Söke''de meyhanede)', 'Tek Başına Tek başına yürünür yollardan bahçelerinde portakal,limon mandalina olan evler arasından.. Tek başına restoranın tek masasına otur...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Şahin']::text[], 8.5, '{"poet":"Selçuk Şahin","poet_slug":"selcuk-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/tek-basina-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyamız', 'dunyamiz-ahmet-hani-edu3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerinde daş oynar

