INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masa Şiirleri 1', 'masa-siirleri-1-erol-dal-9adpr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kuş uçtu

Kuş Uç Tu

Kuş uçtu MU

Kuş mu Uçtu

Kuş Mu Uç tu.

...

Kuş

U. ç. t. u

...

Kalan

Tünek

...

Kuş 

Şıç TI.', 'Kuş uçtu Kuş Uç Tu Kuş uçtu MU Kuş mu Uçtu Kuş Mu Uç tu. ... Kuş U. ç. t. u ... Kalan Tünek ... Kuş  Şıç TI....', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/masa-siirleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansızdı Gelişin', 'zamansizdi-gelisin-zubeyde-yilmaz-i01cf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamansız gelip oturdun yüreğime

yaz yağmurlarıydı meskenin belli

hiç haberde vermedin 

kuşlarıda göndermedin senden önce...

kaçışlarım vardı oysa benim

tuzaklara yem olmayacaktı sesssizliğim

sessiz çığlıklarımın tek şahidi yine bendim

damarlarımda yıllanmış kahır

yıkık bırakmıştım sevda aynalarında hayellerimi

üşürdü hep unutmuştu ateşi yüreğimin elleri...

çektiğim acılara inat gelme şimdi

kimselere kalp açamam 

devrilmiş güneş çoktan, unut beni

renklerde soldu çoktan, sesler kesildi

büktü boynunu çiçeğim bir ikindi vakti.

gelme şimdi çek ellerini üstümden

benim kuşlarım çoktan başını alıp gitti

gelişin çok zamansız üstümde ıslak toprak

benim gelenim gözyaşıyla yıkanmış ölüm saati....', 'zamansız gelip oturdun yüreğime yaz yağmurlarıydı meskenin belli hiç haberde vermedin  kuşlarıda göndermedin senden önce... kaçışlarım vardı...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zamansizdi-gelisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Yamacımın Kan Kırmızı Gülü', 'sevda-yamacimin-kan-kirmizi-gulu-volkan-yoruc-6td51', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşlerim gökyüzünü

Gök maviyi delerde geçer aşkım

Yıldızlara ulaşırda parıldar

Yakamozlara damlarken ışığı

Aydınlatır yüreğimi

Sevda yamacımın kan kırmızı gülü

Peşi sıra gelir ateş böceklerim

Takınırım aşk çiçeklerini gönlüme

Dilimde sevda türküleri

Yürürde gelirim yanına

Sevda yamacımın kan kırmızı gülü

Gülümsemek nede güzel senle

Koparmaya kıyarmıyım seni

Koklamak bile ölüm gelir bana

İncinirsin diye sakınırım

Seni düşünürken titrer içim

Nasılda yanarım senin için

Kor ateşlere volkanlara denktir sana sevgim

Sevda yamacımın kan kırmızı gülü

Uçurum boylarından çıktım senin için

Yüzyıllarca yollar yürürüm senin için

Boynum büküktür senin yanında

Bakamam ki o tatlı yüzüne

Sevda yamacımın kan kırmızı gülü

Ben senin için yaşarım bu ömrü', 'Düşlerim gökyüzünü Gök maviyi delerde geçer aşkım Yıldızlara ulaşırda parıldar Yakamozlara damlarken ışığı Aydınlatır yüreğimi Sevda yamacım...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevda-yamacimin-kan-kirmizi-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittiğinden beri |', 'gittiginden-beri-zafer-zengin-etnika-c0rny', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ahhh sen

kısa boyun

küçük ellerinle

sarıp sarmalamış

çocuk etmiştin beni

gittiğinden beri

hiç kapamadım gözlerimi

şimdi

mutlu musun dostum

kan sürüyor musun yüzüne

özlüyormusun beni yine

|| yakın demiştin..yollar kısa artık..uçak var tren var

hemen gelirim demiştin demesine de..gelmedin

hiç mi özlemedin ||

ahh sen

gittin gideli

kokun kalmadı bir yerde

|| dertli şarkılarla sırdaşım şimdi..onlarla çalınıyorum nota nota..son gördüğünden beri değişmedim

   ellerim.. azı dişim çürüdü..acısını umursamıyorum..acı öğretiyormuş en çok.acı hatırlatıyormuş..

   demiştim..bir aşkı siliyorum içimden..benim yaşlarımda zor şeyler bunlar..olmayacak işler..

   günler hızlı geçiyor iş güç derken çoğunlukla unutuyorum sabah ne zaman akşam ne zaman oldu diye..

   hala romantik filmlerde eli kadın beline sarılmış adamı kendim sanıyorum

  sohbetler hala bana '' bu salak aşık '' çatalım şunalarla geçiyor..kızıyorum esirgediğim ne kadar küfür varsa ediyorum artık..

  sen gidince terbiyem bile bozuldu.kaç bardak çay içiyorum kaç yazı yazıyorum saymıyorum artık..

  yüzünüde unuttum..yüzümüde..şimdi aşktan yana nasibi olamayanlar benim dostum artık..aşk yok diyenler karşı

  hepimiz kafa kafaya verip beddualar ediyoruz..derdik hani aşk''ı yaşamayan gelmemiş varsaysın kendini dünya''ya diye

  şehre inmiyorum artık..meydanlara çıkınca hamburgerci önlerinde buluşanları gördükçe hayince kıskanıp boğuluyorum

  güzel gülen bir kadın görsem canım deyip sarılasım geliyor..iki günüdür hastayım direncim kırılmış..yataktan cıkasım yoktu..

  zorladım kendimi.. sırf adıma yakışmaz diye kolaya yenilmeyim diyorum..seni ilaç arası vakitlerde düşünüyorum.bir el gelip aç ağzını dedikçe

 sen sanıyorum..ne kadar varsa içesim tutuyor..ateş sonlara gelmiş..geçerse artık yara iyileşecek..dirileceğim yeniden..kendine iyi bak

 yine diyorum..seni düşünmek ne güzel şey..||

şimdiler tutulmuş o düşlerden geriye

adın bile kalmadı

kimse bilmiyor

kimse tanımıyor seni

ismini söylemiyor

hatırını sormuyor

içimin adresleri boş

birşey kalmadı senden geri

keşke biri ismini söyleseydi

bu şarkılar bu kadar acı gelmezdi

gittin gideli

kokun kalmadı bir yerde

sadece içimde

sadece içimde

05.10.2004', 'ahhh sen kısa boyun küçük ellerinle sarıp sarmalamış çocuk etmiştin beni gittiğinden beri hiç kapamadım gözlerimi şimdi mutlu musun dostum k...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/gittiginden-beri-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El obada qem olmasın', 'el-obada-qem-olmasin-ahmet-hani-eq1z7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Savaş marşın çalan ölsün

Ayrılığı salan ölsün

Düzlük qalsın yalan ölsün

El obada qem olmasın

Bağçalarda gül solmasın.

Partlamasınlar bombalar

Dağılmasınlar qalalar

Darıxmasınlar analar

El obada qem olmasın

Bağçalarda gül solmasın.

Göyde bayraqlar oynasın

Telde daraqlar oynasın

Yerde oraqlar oynasın

El obada qem olmasın

Bağçalarda  gül solmasın.

7 october 2004', 'Savaş marşın çalan ölsün Ayrılığı salan ölsün Düzlük qalsın yalan ölsün El obada qem olmasın Bağçalarda gül solmasın. Partlamasınlar bombala...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/el-obada-qem-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşağıdakiler/Yukarıdakiler/Veda/Titrek/Bağıranlar |', 'asagidakiler-yukaridakiler-veda-titrek-bagiranlar-zafer-zengin-etnika-yixte', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'içeri/

kim bilir bu bakışın sahibini

ince elleri

kemiğe tutunmuş etiyle

kim süzer geceyi

aklımızda ihtimaller

ve olanlar

sarmaladı biçereyi

sen burdayken

gitmek olmaz

az zaman katalım içine

unutalım

kim dokunur

dikilmiş yaralara

izi varsa

iz arama

kısa saçları

benzediği şarkıcı kadar kıvrak

şimdi herkes yanlış anlayacak

gel

gece uzun olacak

devriye çıkacak

adam kaçacak

sarıl

öykü bitmesin

laf edilmesin

sesini unutma

yanına bağla

Dışarı/

döner keskilerle

eskimiş çürümüşler kesildi

parcalar toplandıkça araya

ahenk

ve güzün sesi 

hizaya geldi

değişti dışarı

için gibi

iyi dualar sokaklarda şimdi

uzak/

andın vardı

ardılı herşey kadar

sancıları sarmaladığın

kundak sanıp

içine hapsolduğun

o değil

şu değil

dağın ardında

sis içinde

sus içinde

dön dur kendine

dilek tutma

iyiler dönmez geldiği yere

İç/

kapat saati

ışık kalsın

yan/

burası

kesilenin içinde unutulan giriş

sür leylim ellerini

dünya harbi

bir deprem

unutma

ve gürlemedir ayrılık

bırak

susuz kalmasın saçlarımız

ter /

uzun uzadıya yol

tuzuyla yakan

saklan adam

saklan

veda/

hiç sevilmez

bilinmez

bilen söylemez

Titrek/

ellerin rüzgara komşu 

uç aymazında

yakalanma

kavanozlar hapis

geceyi basar yırtıcılar

gözüm çıkar yerinden

göremem doğan çocukları

reis hasta şimdi

talan edilir ova

tutarlar suyun başını

bize karsı yan kalır

koşarken

yüzemez düşlerim

Mola/

dirilmem lazım

ıslat bakışınla yüzümü

kesmesinler dilimi

kuru kabalık rüzgarla

mola

Bağıranlar/

aşağıdakiler

05.10.2004', 'içeri/ kim bilir bu bakışın sahibini ince elleri kemiğe tutunmuş etiyle kim süzer geceyi aklımızda ihtimaller ve olanlar sarmaladı biçereyi ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":97,"source_url":"https://www.antoloji.com/asagidakiler-yukaridakiler-veda-titrek-bagiranlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '* H e P...Y e K....!', 'h-e-p-y-e-k-metin-eser-zbofq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'O

OOO

OOOOOO

OOOOOOOOO

OOOOOOOOOOOO

OOOOOOOOOOOOOOO

OOOOOOOOOOOOOOOOOO

OOOOOOOOOOOOOOOOOOOOO

OOOOOOOOOOOOOOOOOOOOOOOO

Ümidi pul pul yoldun / döktün işi oyuna,

Sonra akraba oldun / Karaman''lı koyuna,

Anlamadığım bir yol, söyle o nasıl haldı,

Sevgiyse can evimde, tutunduğum tek daldı.

Oturdum peşin sıra / bu oyunun başına,

Sonra tutuştu çıra / bakmadın göz yaşına,

Dizdin tek tek pulları, gözüm maziye daldı,

Beyaz pulu sen aldın, kara baht bana kaldı,

Kuralı bozuk baştan / aşk dediğin oyunun,

Yazı göründü kıştan / öğündüğün soyunun,

Galibiyet yok bize, çoktan anladım bunu,

Yeter ki zar tutmayın, düzgün oynayın şunu.

Sen tavlayı okudun / Allah bilir üfledin,

Lafla mekik dokudun / moralimi küfledin,

Şans desen Kaf dağında, bana nasıl ulaşsın,

Bir de uğursuzluklar, yalnız bana bulaşsın.

Eyy güzel söyle hele / şans bunun neresinde, 

Ne atsam hepsi gele / yendin her keresinde, 

Tüm kapılar kapanmış, elimde tam beş kırık,

Üstelik zar hep bir bir, boğazımda hıçkırık.

Yahu zar mı tutarsın / yoksa bir hîle mi var,

Ya da pul mu yutarsın / biraz insaf eyle yâr,

Ateş bastırdın bana, meğer ne de zormuşsun,

Kimbilir benim gibi, kaç adamı yormuşsun.

Daha siftahımız yok / düşeş senin malın mı,

İkiyle bir bende çok / beş beş senin balın mı,

Zaten oyun dört sıfır, bu el de mars mars diyor,

Ben ne şanssız adamım, kız da elden gidiyor.

Zaten ben de baht olsa / oyunu ben alırdım,

Övünülcek taht olsa / çıkıp O''nla kalırdım,

Tavla neyime gerek, oyunu bilmiyorsam,

Bana biraz sus gerek, nasibi biliyorsam.

OOOOOOOOOOOOOOOOOOOOOOOO

OOOOOOOOOOOOOOOOOOOOO

OOOOOOOOOOOOOOOOOO

OOOOOOOOOOOOOOO

OOOOOOOOOOOO

OOOOOOOOO

OOOOOO

OOO

08.10.04 / Frankfurt', 'O OOO OOOOOO OOOOOOOOO OOOOOOOOOOOO OOOOOOOOOOOOOOO OOOOOOOOOOOOOOOOOO OOOOOOOOOOOOOOOOOOOOO OOOOOOOOOOOOOOOOOOOOOOOO Ümidi pul pul yoldun /...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/h-e-p-y-e-k-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derdi  |', 'derdi-zafer-zengin-etnika-kzo6b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'aşk

için 

sevdim

melodileri

kesiyorlar

içi

kısık

olsada

sesleri

büyümek

değil

derdi

derdi

derdim

derdin

değildi

25.04.2004', 'aşk için  sevdim melodileri kesiyorlar içi kısık olsada sesleri büyümek değil derdi derdi derdim derdin değildi 25.04.2004...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/derdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürek II', 'surek-ii-ahmet-aksoy-9pl6m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kanlı belgeler gibiyiz

biz savrulurken göklere yıldızlar

zamanın salgısını bilsek

neşemizi bölemez kör kütük ayrılıklar 

sesimize akan yıldırımlar

küflü gölgemiz kurtlu gövdemiz

hey gidi kocamış yazgılar

sancak kırılmadan ağlamaz bayraklar

yazlar kışlar baharlar salyalar

denize baygın gözlerimiz

içimizde ölü çocuklar

kendine kırık tabutlar

karanlıkta büyüyen sanrılar

acılara sarılmış tenlerimz

kurtulsak yarılır taşlar

sancak kırılmadan ağlamaz bayraklar', 'kanlı belgeler gibiyiz biz savrulurken göklere yıldızlar zamanın salgısını bilsek neşemizi bölemez kör kütük ayrılıklar  sesimize akan yıldı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/surek-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitirmelik sevdalar', 'yitirmelik-sevdalar-gencay-coskun-efykk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yitirmelik sevdalar yüreğimde

Üç kuruşluk adamlar karşımda.

Geç geçebilirsen karşı kıyılara

Hep birileri arkanda kalıyor

Sen bu yerlerden giderken 

Giderken ruhum etime takılıyor 

Canımın çok fena acıyor

Acıtan tenim etim değil aslında 

Asıl acıtan öykümün bitmeyen sonunda 

Öyle güzel gülüyordu 

Saklı kalmış peri bana uzaklardan.

Bugünde değer diyordum 

Nefes almaya 

Adım atmaya 

Yağmurlarda ıslanmaya. 

Yeşilin bin bir tonu vardı

Gözümün yansıma zamanlarında.

Tanıdık bir hikayenin 

Çok uzak figüranıydım.

İstemeden filmde rol alırdım. 

Saman sarıları aklımı alırdı

Saklamanda geri getirirdi

Şeytana ve yardakçılarına 

Kış kış der adamakıllı küfür ederdim 

Malum kibirli salak şeytan ancak bundan anlardı 

Gene de ağzımı bozmamam lazımdı 

Pişman değilim yine olsa yine yapardım.

Öfkenin sarhoşluğu fena ağrıtıyordu

Emanet alınmış bedenleri. 

İkilemden fazla çoklamların arasındaydım

Nefes almak bile ayrı bir hüner isterdi.

Nereye adım atsam 

Hadise çıkacaktı 

En iyisi zamanın durulmasını beklemekti. 

Dibine çöken tortular 

Arasında kaybettiklerim olurdu

Kendine geliş zamanlarında. 

Bir dahaki gidişlere gücüm yetmezdi.

Yitirmelik sevdalarım 

Topraklara karışırdı

Her yağmur yeniden dönüşümdü

Her dönüşüm yeniden hüzündü..', 'Yitirmelik sevdalar yüreğimde Üç kuruşluk adamlar karşımda. Geç geçebilirsen karşı kıyılara Hep birileri arkanda kalıyor Sen bu yerlerden gi...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yitirmelik-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ReKlamLArı izliYorum / yogunum! ! ! ! şiir okumayla yazmayla uğraşamam! ! !', 'reklamlari-izliyorum-yogunum-siir-okumayla-yazmayla-ugrasamam-zafer-zengin-etnika-6vah7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ReKlamLArı izliYorum

boş vaktim olursa

bir şeyler yazarım

keyfim yerindeyse

yazmadan kaçarım

canım çekerse

bazılarına kızarım

belki de kızmam

mesela bir sağıra kızsam duymaz ki beni

yok onlar duyar

bazıları duymaz

kulakları dibinde

elbette zurna çalınmaz

vs. vs.

reklamları izleyip

motive olunca şiir yazacağım

ciddiyim bak sayın duymaz', 'ReKlamLArı izliYorum boş vaktim olursa bir şeyler yazarım keyfim yerindeyse yazmadan kaçarım canım çekerse bazılarına kızarım belki de kızma...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/reklamlari-izliyorum-yogunum-siir-okumayla-yazmayla-ugrasamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-baykal-kaanalp-8zyn0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine kimsecikler yok

kapının arkasında

açıp baktığımda 

kaçıp gidecek

yine üşüyor ellerim

ceplerimde,dışarıdaki

ayaza dayanıklı değil

ayrılığa hiç değil

yine bi hoş oluyor kalbim

kabından çıkardığımda

kabı çok sulu,sudan

çıktığında ölüyor

yine bekliyor gönlüm

çarpılmak için yeniden

bi işgüzar sevene

alıp götürecek yanında', 'yine kimsecikler yok kapının arkasında açıp baktığımda  kaçıp gidecek yine üşüyor ellerim ceplerimde,dışarıdaki ayaza dayanıklı değil ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yeniden-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla Sakızı', 'damla-sakizi-baykal-kaanalp-fe4mv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şarkıların dili yalan

gözlerime dolan

nedir biliyor musun? 

çiğnenmemiş elde

kalmış,bi damla sakızı

şarkıların göze batan

gönül okşayan yanı

nedir biliyor musun? 

dile kolay,gönle hoş

gelmesi namelerin', 'şarkıların dili yalan gözlerime dolan nedir biliyor musun?  çiğnenmemiş elde kalmış,bi damla sakızı şarkıların göze batan gönül okşayan yanı...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/damla-sakizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koyu Çehreler', 'koyu-cehreler-talip-kaplan-g1rxd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tanıyorum artık insanları

Çünkü kendimi öğrendim

Biliyorum artık herkesi

Çünkü kıyaslamayı denedim

Kendi kendini bilmekmiş

İnsanları anlamanın yolu

Yalnızlıkmış insanları bilmek

Nefret etmekmiş semadan

Hangi kapıyı çalsam

Kara bir yüz, simsiyah

Herkes dönek, iki yüzlü

Fırsat düşkünü, hep çirkin

(09 Haziran 1994)', 'Tanıyorum artık insanları Çünkü kendimi öğrendim Biliyorum artık herkesi Çünkü kıyaslamayı denedim Kendi kendini bilmekmiş İnsanları anlaman...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/koyu-cehreler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lalezar', 'lalezar-baykal-kaanalp-j3pgy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'musiki meclislerine 

katılan sazendeler

çalarlar gönlümüzü

bir defle

sözleri belki hoş

belki de yakar bizi

dinlemekten gocunsakda

çalınan sözleri

kurtuluruz bir anda

uzun soluk alışlardan

gam,keder,kasavetten

götürür bizide bir lalezara', 'musiki meclislerine  katılan sazendeler çalarlar gönlümüzü bir defle sözleri belki hoş belki de yakar bizi dinlemekten gocunsakda çalınan sö...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/lalezar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Sen', 'i-cimdeki-sen-tugay-kocak-7j8xu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin var 

Hancerle yaralanmış gibi. 

Gözlerin, 

Buralara ait değil gibi. 

Anlamaz yanık türküler gözlerini. 

Gözlerin bana yakın, 

Mahzun ve kederli. 

Gözlerin, 

Islak ve siyah. 

Yüreğin, 

Sıcak ve günah. 

Yüreğin var 

solgun ve yorgun. 

Yüreğin, 

Bin yıllık yolcu gibi. 

Yüreğin kimsesiz. 

Yüreğin durgun. 

Yüreğimde, 

Yüreğinin acısı gizli 

Yarandan tanıdım seni 

Gözlerin, 

Islak ve siyah. 

Yüreğin, 

Sıcak ve günah.', 'Gözlerin var  Hancerle yaralanmış gibi.  Gözlerin,  Buralara ait değil gibi.  Anlamaz yanık türküler gözlerini.  Gözlerin bana yakın,  Mahzu...', ARRAY['Türk Edebiyatı','Şiir','Tugay Koçak']::text[], 8.5, '{"poet":"Tugay Koçak","poet_slug":"tugay-kocak","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/icimdeki-sen-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahip Olduğumuz Tek Şey', 'sahip-oldugumuz-tek-sey-baykal-kaanalp-leq5t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gri bir gökyüzü

sahip olduğumuz tek şey

bulantılarına katlanabilmenin

erdemini yakalayabildiğimiz

bir parça ilgisizliğin

hani haksızda değiller

gönül koyan vücutlar

bakışlarımıza

artısıyla bir burukluk

eksisiyle bir aymazlık

bir kesit,bir kesir

yaşama tutunabilmenin

abc si saklı duruyor

koridorlarda,karanlık

gökyüzü mü? o hala gri

sahip olduğumuz tek şey', 'gri bir gökyüzü sahip olduğumuz tek şey bulantılarına katlanabilmenin erdemini yakalayabildiğimiz bir parça ilgisizliğin hani haksızda değil...', ARRAY['Türk Edebiyatı','Şiir','Baykal Kaanalp']::text[], 8.5, '{"poet":"Baykal Kaanalp","poet_slug":"baykal-kaanalp","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sahip-oldugumuz-tek-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baktığın Zaman Anlarsın', 'baktigin-zaman-anlarsin-hasan-can-ohxhy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her derdin bir çaresi var,

Her acının bir yarası var,

Bitmeyen her çilenin,

Her isyanın bir bedeli var.

Her yangının bir kül oluşu var,

Her dalganın bir kıyısı var,

Ölüme bir adım kala,

Vurulan her kuşun bir davası var...

Acı hatıralar karşımda durur

İlerde herşey karşılığını bulur,

Bu işkence sanmaki unutulur,

Hesabı elbet birgün sorulur,

Gözümde biriken kanımın son damlası,

Baktığın zaman anlarsın hikayesini...', 'Her derdin bir çaresi var, Her acının bir yarası var, Bitmeyen her çilenin, Her isyanın bir bedeli var. Her yangının bir kül oluşu var, Her ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/baktigin-zaman-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dili Seçeriz', 'dili-seceriz-sabit-i-nce-9cb6a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '-Sevgili Dost Harun''a teşekkürle- 

Hay senin diline kurban olurum, 

Kendimiz bilmeyiz, eli seçeriz. 

Yüreğimi yüreğinde bulurum, 

Seni okudukça dili seçeriz. 

Kendimiz var iken el olmak niye, 

Elin gavuruna dil olmak niye, 

Komplekse kapılıp sel olmak niye, 

Türk''üz kendimizi bil''i seçeriz. 

Nideyim ellerin dilini nidem, 

Türkçe konuşarak taa Çin''e gidem, 

Rümuzu görünce kan ağlar didem, 

Roze, Vart''ı nidem Gül''ü seçeriz. 

Durgun pınarımı çağlattın yine, 

Keyifle başlattın Harun''um güne, 

İncem Karaman da Türkçe düğüne, 

Mehmet Bey uzatmış dal''ı seçeriz. 

Sabit İnce Kayseri 9.10.2004', '-Sevgili Dost Harun''a teşekkürle-  Hay senin diline kurban olurum,  Kendimiz bilmeyiz, eli seçeriz.  Yüreğimi yüreğinde bulurum,  Seni okudu...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dili-seceriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Azap 5 "Üşüyecek miyim Böyle? "', 'azap-5-usuyecek-miyim-boyle-firat-yilmaz-n9wpu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Titreme sardı bedenimi yine

Nedeni ne nedeni? 

Ayırıp gittiğinden  beri

Zangır zangır üşüyecek miyim böyle? 

Üç aşağı beş yukarı

Altı mevsim geçti bu yerden

Yazı da bir kışı da

Ayazı da, mahşer sıcağı da

Zangır zangır üşüyecek miyim böyle? 

Söyle

..........nedeni ne nedeni? 

Ayırıp gittin ikimizi

ölüm ile dirim arasındayım.

Ben kimim? 

.................söyle

nedeni ne  nedeni? 

Eğer öldürmeyeceksen bu garibi

Bir huzur ver

Mektup yada telefonla

Hiç olmazsa hissettir göz ucuyla

söyle

Yeter ki

............söyle

nedeni ne nedeni,

Seni çok sevmem mi? 

2002 / 3', 'Titreme sardı bedenimi yine Nedeni ne nedeni?  Ayırıp gittiğinden  beri Zangır zangır üşüyecek miyim böyle?  Üç aşağı beş yukarı Altı mevsim...', ARRAY['Türk Edebiyatı','Şiir','Fırat Yılmaz']::text[], 8.5, '{"poet":"Fırat Yılmaz","poet_slug":"firat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/azap-5-usuyecek-miyim-boyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmez Bir Yer', 'bilinmez-bir-yer-firat-yilmaz-xibpb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllardır gurbetteyim

Bilemediğim bir uzaklıkta

Ucu ucuna denkleştirdiğim

Birikmiş aşkımla geliyorum sana

Irgatlık, hırsızlık, gaspla biriktirdim bu aşkı.

............omzumdaki semerde hasretinin yükü

............her gece uykumdan çaldığım dakikalar

............ve gasp ettiğim hayalimde mahremini

.............tutsak ettim her gece 

.............yanıma uzandırdığım çıplak bedenini

sen uyaya biliyor musun, kirli fikrimin tesirinden? 

Bekle beni.............

Vereceğim senden aldığım her şeyi

Gasp ettiğim senliğini

Alacaksın benden

borçlu olduğum uykusuz gecelerini

Ölüm garında rehin kalmasaydı

Aşk yüklü bavulum

Çoktan tutmuştum ya ellerini

Sabret.

Mahşer yakın.

O gün

Kavuşturacak sen ile beni.

2004 / 10', 'Yıllardır gurbetteyim Bilemediğim bir uzaklıkta Ucu ucuna denkleştirdiğim Birikmiş aşkımla geliyorum sana Irgatlık, hırsızlık, gaspla birikt...', ARRAY['Türk Edebiyatı','Şiir','Fırat Yılmaz']::text[], 8.5, '{"poet":"Fırat Yılmaz","poet_slug":"firat-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilinmez-bir-yer-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duyduğum Ses Değil / SEN OLSAN...', 'duydugum-ses-degil-sen-olsan-zubeyde-yilmaz-kbg2q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir ses duysam  gece yarısı

kör dumanlı dağlarından çırılçıplak

uzak... çok uzak bir ses...

yırtsa lacivert geceyi çılgınca

 düşse mercan mercan yıldızların içinden

kararsa her yer sönse ışıklar

ve ben gözlerimi yumsam

rüyam değil gelen sen olsan...

_______________________sen olsan....', 'bir ses duysam  gece yarısı kör dumanlı dağlarından çırılçıplak uzak... çok uzak bir ses... yırtsa lacivert geceyi çılgınca  düşse mercan me...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/duydugum-ses-degil-sen-olsan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Vardım Bir Yoktum 3', 'bir-vardim-bir-yoktum-3-mehmet-emin-ozturk-syejn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genç yüreğini verdi kıza

Kızdan ise bir tebessüm belirdi

Ve öylesine bakışlar atıyordu ki kız

Genç alamıyordu kendini ondan

Kız bu olanlardan habersiz 

Bakıyordu olup bitene

Bir seslenişle genç sordu kıza

Genç: 

Af edersiniz sizi daha önce hiç görmemiştim 

Buralı mısınız acaba? 

Kız:

Evet buralıyım ama okulum nedeniyle yoktum

Üniversitede okuyorum

Genç:

Sizinle tanışmak isterim umarım beni yanlış anlamazsınız

Kız: 

Yok hayır, neden olmasın, memnuniyetle olur tabii

Genç:

Peki o zaman, müsait bir zamanınız da birer kahve içmeye ne dersiniz

Kız:

Olabilir memnun kalırım; 

Diyerek genç kız ilerlemeye başladı

Öylesine bir tebessüm ediyordu ki

Genç kendini alamıyordu

O gülen yüzünden

Kızda öylesine dalmıştı ki gencin bakışlarına

Adeta o bakışlara takışmıştı 

Gözünden gitmeyen bir bakışlar

Çok değişik duygulara bürünmüştü kız

Kendini o büyüleyen bakışlara bırakmıştı

Kızın tarafından; 

O ne denli bakışlar ne güzel bir iltifat

Ve çok hoş bir sıcaklık veriyor diyordu

Beni öylesine keşfediyordu ki ne tuhaf

Gencin tarafından; 

Allah’ım bu ne güzel bir gülümseme

Bu ne hoş tebessüm

O ne bakışlar beni bana hatırlattı

Ne tuhaf

Kız gence takılıyor,onu düşünüyor

Genç kıza gönlünü veriyor

Ve onu düşünmeden edemiyordu

Büyük bir aşk başlangıcının başlarındaydılar

Kontrolü olmayacak bir sıcaklığın ilk basamaklarını 

Tırmanmaktaydılar

Usul usul yavaş yavaş...

14/09/2004 		02:33 suları', 'Genç yüreğini verdi kıza Kızdan ise bir tebessüm belirdi Ve öylesine bakışlar atıyordu ki kız Genç alamıyordu kendini ondan Kız bu olanlarda...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/bir-vardim-bir-yoktum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitişin Başlangıcı', 'bitisin-baslangici-mehmet-emin-ozturk-heumi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir bitişin ertesindeki başlangıç

Apansız ve aniden gelen, beklemeden

Yaprakların savrulmasıyla hatırlanan 

Mevsim değişikliği yaşanmakta

Esintilerin eşiğinde yaz 

Lakin vedalaşıyor bizimle

O sıcaklığını yavaşça çekiyor

Ne sessiz bir geçiş sonbahara

Geceler üşütüyor şimdilerde

Gel gelelim sevdalara

O kadar yakıyorki insanı

Üşüyüşlerin içindeki bir alev

Yalan oldu yaralar doldu

Çakıl taşlarını düşünmek

Düşlerinden koparılmak var 

Akıllarda yalvarış ve yakarış

İçinden savaşmak var 

Sevda yaşlanmış yorgun yollarda

Karşı kıyıda hatırlatır kendini sevda

Kişinin kaçışları var, kaçabilirse ne ala

Ne alaka yüz çevirmek karşı kıyıya

Karşı kıyıda bıraktığı bir sevda var

Varlar var, varda, varlar olacakmı yanında

Yoksa yok oluşun ardından aranılanmı olacak 

Yoksa her bir yana bakışta,

Hatırlardamı kalacak,

Yada onu çok mu üzecek hatıralar,

Yaşatılacakmı anılar,

Yoksa anlarda mı bırakılacak,

Sabahlara dair beklenenmi olacak,

Ben çözemedim, özgürlüğün takıntısında

Özgürce teslimiyetini bırakacak karşı kıyıya

Bırakacakmı, yada martının kanatlarında

Yollaramı düşecek, 

Göz pınarlarında gizlediği

Umut dolu düşünceler

Çakıl taşlarını sayacak teker teker

17/09/2004-            02:57 suları', 'Bir bitişin ertesindeki başlangıç Apansız ve aniden gelen, beklemeden Yaprakların savrulmasıyla hatırlanan  Mevsim değişikliği yaşanmakta Es...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Emin Öztürk']::text[], 8.5, '{"poet":"Mehmet Emin Öztürk","poet_slug":"mehmet-emin-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bitisin-baslangici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
