INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasûhi', 'nas-hi-sair-ahrazi-m3z20', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyan ey Nasûhim,ey insanlık nûrum uyan,

Uyan da fark et artık,anlayan var mı seni? 

Eğlense de boş ver,ya bir câhildir uluyan,

Ya da seyre dalmıştır semâdaki cüsseni…

* * *

Tevbe-i nusuh:asla bozulmayan tevbe

Not:Bu sözler,Nasûhi haricinde hiç kimseye ithafen yazılmamıştır.', 'Uyan ey Nasûhim,ey insanlık nûrum uyan, Uyan da fark et artık,anlayan var mı seni?  Eğlense de boş ver,ya bir câhildir uluyan, Ya da seyre d...', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nasuhi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1965''in Beyazı', '1965-in-beyazi-peri-han-o6231', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1965''in Beyazı 

Tepebaşı yokuşunun 

Herhangi bir sokağın 

Küflenmiş köşesinde

Siyahı solumakta

ve

Puslu bir Taksim günü 

Ana renkler 

Ellerinde umutları 

Kırmızı ışıkta

kırmızı burunlarıyla

Yarı ıslak yarınlarını

Bencilliğe satmakta', '1965''in Beyazı  Tepebaşı yokuşunun  Herhangi bir sokağın  Küflenmiş köşesinde Siyahı solumakta ve Puslu bir Taksim günü  Ana renkler  Elleri...', ARRAY['Türk Edebiyatı','Şiir','Peri Han']::text[], 8.5, '{"poet":"Peri Han","poet_slug":"peri-han","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/1965-in-beyazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Termosumda Yarın kokulu', 'termosumda-yarin-kokulu-peri-han-ujy0e', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Termosumda  yarın kokulu

Geleceğin korkulu sıcak buğusu

Saat emeği  beş geçe’ye ayarlı

Her gün  5 geçe’de

Solmuş İstanbul güneşinin

Kızıla boyanan yakamozlarına doğru

Acı  bir düdük sesi inler

Saat emeği beş geçe

Termosumda kahvem

Bedenimde 5 günün yorgun sesi

Alın terinin yarınlara ağlaması

Yudum yudum çaresizliğin üzerine

Bir acı kahve daha

İç  iç bee

Nasırlı ellerinle', 'Termosumda  yarın kokulu Geleceğin korkulu sıcak buğusu Saat emeği  beş geçe’ye ayarlı Her gün  5 geçe’de Solmuş İstanbul güneşinin Kızıla b...', ARRAY['Türk Edebiyatı','Şiir','Peri Han']::text[], 8.5, '{"poet":"Peri Han","poet_slug":"peri-han","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/termosumda-yarin-kokulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerede Nerdesin', 'nerede-nerdesin-i-hsan-uncuoglu-n13r3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Vatan uğrunda onurlu eşsiz aşk sevgi 

Baştan aşağı yetenek emek gücü alınteri 

Saygın kuvvetli ney varsa bilgi eserlerle 

Ne oluyor neredeyiz nerde, 

*** 

Yaşattığın kutlu kutsal varlıklar çiçeğin 

Milletin bayrak sancak elinde zaman durur 

Vatanda taşını toprağını yücelten o hamur 

Can su ya gökte ya yerde nerdesin nerde, 

*** 

Bilgi varsa saygın eseri millet bakar izler 

Başta can kutlu kutsal varlık güzel sözler 

Satıp savar hiç bir kılı kıpırdamaz efendiler 

Ne oluyoruz neredeyiz nerdesiniz beyler, 

*** 

Ülkende Milli Ruhun örfün adetin geleneğin 

Ayaklar altına alınsa da umursamaz bendelerin 

Avrupa yasa her dakika ayakta nazar değmesin 

Ne oluyoruz neredeyiz nerdesin kardeşim, 

*** 

Baştan başa kutlu kutsal varlıklar havada uçsun 

Paran pul olmuş sağlık olsun bilki neden pulsun 

Uygar parya’da insani sıfatlar ama sen’de kurşun 

Ne oluyoruz neredeyiz dostlar koşun, 

*** 

Nam şeref haysiyet paramparça arsızlara aldırma 

Ne olursun efendi efendilerini seyret ses çıkarma 

Uykuda renkli rüya görüyor kapitalim teknolojim 

Ne oluyoruz neredeyiz nerdesin kardeşim,', 'Vatan uğrunda onurlu eşsiz aşk sevgi  Baştan aşağı yetenek emek gücü alınteri  Saygın kuvvetli ney varsa bilgi eserlerle  Ne oluyor neredeyi...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/nerede-nerdesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uygun Ninni İleri', 'uygun-ninni-i-leri-i-hsan-uncuoglu-udjme', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçen masaldı geçti

Zaman denilen neyki 

Öne bir iki biraz geri 

Babalarsa önde gider 

Az buçuk bir güç ister 

İnsanlar dalgalı denizli 

Havadan esen yel gibi 

Haydi Türkiyem,İleri!', 'Geçen masaldı geçti Zaman denilen neyki  Öne bir iki biraz geri  Babalarsa önde gider  Az buçuk bir güç ister  İnsanlar dalgalı denizli  Hav...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uygun-ninni-ileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir sevda uğruna', 'bir-sevda-ugruna-mustafa-i-lhan-guldemir-26k7x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir sevda uğruna

bir ömür bitirdim

bir sevgili yoluna

bir hayat bıraktım

bu son demde anladım

yetmez verilenler

daha fazlasını ister 

ister bu aşifteler

sever görünseler

sarılıp öpseler

sahtedir aldıkları

sevgiler onlar için sahte

bir kadeh içkidir

iki yalan söz,yalan sevgi

hayat,sevgi budur

versende almaz unutur

varsa paran,pulun hepsi kulun

aşk,sevgi nedir

ne verirsen ver unutulur

gün bu gündür

yarın her şey unutulur

gün doğunca yeni mesken

yeni dünya kurulur

sahtedir dünya,sahtedir yaşam

onlar sahte yaşam için

yeniden doğar her sabah

bir kadeh içki,bir avuç akçe uğruna

yaşar sahte dünyalarında

alamazlar verdiğin sevgini

anlamazlar aşkını

yaşar kendi dünyalarında

kısacık ömrü bitirir

dar yaşamlarında

bir sevgi uğruna

bir ömürü bağışladım

bir sevda yolu uğruna 

bir hayat bıraktım

son kadehte anladım

yetmez verdiklerim

daha fazla ister 

dişi denen bu aşifteler.', 'bir sevda uğruna bir ömür bitirdim bir sevgili yoluna bir hayat bıraktım bu son demde anladım yetmez verilenler daha fazlasını ister  ister ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa İlhan Güldemir']::text[], 8.5, '{"poet":"Mustafa İlhan Güldemir","poet_slug":"mustafa-i-lhan-guldemir","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bir-sevda-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Saati', 'kum-saati-bekir-gedikoglu-ooekp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Rızgını bulanlar var, bela arayanlar var

Asker gibi ölen var, köpek gibi giden var

Yalanı gerçek sanıp, uğruna ölenler var

Kumarı meslek sanıp, ruhunu satanlar var

Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Dostunu satanlar var, düşmanı dost sayan var

Hak yoluna giren var,  ateşperestler de var

Aşkını satanlar var, yürekten sevenler var

Prangayı kıranlar, kelepçeyi atan var

Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Sanata önem veren, onu körletenler var

Uğruna ölmek için, bayrağını seven var

Onu bez sayanlar var, kara vicdanlılar var

Tarihi yerenler, onu sevenlerde var

Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Kendini adam sanıp, ahkam kesenler de var

Haksız yere işgaller, zulüm edenler de var

Örgütsüz toplumları, işgal eden devlet var

Hayırsızca bir cana, kasteden çok insan var

Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Bir nebze düşünmeyen, dünyada insanlar var

Fikri cihana bedel, çok akıllı insan var

Ey dostum bu dünyada, ne ararsan hepsi var

Fani dünya demişler, göç edecek insan var

Durduramaz zamanı, dünyadaki insanlar

Gök kubbenin altında ne ararsan hepsi var

Kum saatinde kum var

Zaman aktıkça akar

Ankara 12 Ekim 2004', 'Gök kubbenin altında ne ararsan hepsi var Kum saatinde kum var Zaman aktıkça akar Rızgını bulanlar var, bela arayanlar var Asker gibi ölen v...', ARRAY['Türk Edebiyatı','Şiir','Bekir Gedikoğlu']::text[], 8.5, '{"poet":"Bekir Gedikoğlu","poet_slug":"bekir-gedikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kum-saati-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '..ağıt', 'agit-orhan-demirtas-qhzeh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '1.

al yazmalı bir dalganın seyrinde

.........sessizlik vurgunudur yüreğim                        

meczup dur, rüzgarım karadır benim

yüzünün suları dökülürken içime

..dayanamam

..............yenilirim yüzünün yakıcı kasvetine

bedeninin haritalarını, 

...........talihsiz yağmurlara sürgün çizerim 

hayalini yontar, yontar da 

............tüm kayıp sevdalara anıt dikerim

                 

                2.

bakarsam  yüzüne, kirpiklerin  kederim olur

çığlıklarım cinnet geçirir

................................ağlarım, ıslanırım

bakmazsam

....militan olurum bastığı toprakları acıtan

kalbini rendeleyen kum fırtınası olurum 

............ölürsün 

.......................ölürüm

cesedimde yıkarlar bedenini

oysa sen gözlerimde karanfil açmıştın

......dokunsam sana bahar gelecekti

                 

               3.

sorgusuz, sualsiz bir ölümün yanı başında

.........................hüznüm geceden çıplak

ve kırgın şarkılarda öksüz kuşlar ötüşür

esmerdir tenim, yüreğimi yakar kuşların sesi

topal bir rüzgar beni kalbimden vurur, 

ölümcü, kirli yüzüyle çıkıp gelmiştir

.....................................ayrılıktan bahseder

öksüz kuşlar ağlaşır ince bir keder içinde

ve ben,

......kanlı bir çiçekle, tabuta bürünürüm	

                  

                 4.

hangi sevdaya sığınsam bakışların devrilir üstüme

ağıtlarım, dağ gibi yalnızdır, suskundur

uslu heceler dökülür içime

sürgününden döner örselenmiş cümleler

.........................................büyür yangın tenimde

kaygılıdır sevdalar dinlerken yeryüzünü 

toprağın

...............suyun

........................havanının kokusu 

ağır bir yük gibi kırılır omuzlarımda

bir ölü düş geçer önümden

.................................bir de yenildiğim gözlerin

                 

                   5.

ruhumda sana varmak isteyen

.........................sonsuz bir ateş yükselmekte

içinde yağmur olmayan mezarlar

çıplak ayaklı bir fahişe gibi duruyor aramızda

ve sen, asırlar boyu geçmişten

ve sen, asırlar boyu gelecekten

hasretimin perdesini aralayarak

.............................yüzüme bakıyorsun

cehennemin ahı mı tuttu bilmem

....şifresini çözemiyorum yalnızlığımın

                 

                     6.

bir çift gözün laneti var üzerimde

ölü kuşların gövdesinden geçiyorum

gecenin kan çanağı saçlarında ise

....................esmer bir çocuk ağlar içime

gün biter, kelebekler keder içinde ölür

..............................ve tükenir hayallerim

duy beni, 

ey güzelliğine vurgun olduğum kırmızı sardunyam

duy beni,

ey yüzünü kalbimde biriktirdiğim benzeri olmayan

uğruna çürüyen kemiklerime 

................................yüzünün ılık heceleri çizilsin

ve gökyüzüne yazılsın aşkımız                                 

........................................ölümsüz bir metin gibi 

Orhan DEMİRTAŞ', '1. al yazmalı bir dalganın seyrinde .........sessizlik vurgunudur yüreğim                         meczup dur, rüzgarım karadır benim yüzünün...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/agit-280-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam -   Kadın', 'adam-kadin-orhan-demirtas-wsa18', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'adam, 

İsa''nın çarmıhına gerilmiş gibi

...acıyan yanlarına çığlığını gömerek

....uzun etekli bir dağı tırmanırken

yıpranmış kayaların sesi uğulduyordu

....ayaklarının izinde

uzun, kara kirpikler saklıyordu 

....lekeli düşlerinde

yorulmuyordu

...gökyüzünde parlayan bir yıldızı kokluyordu

kadın, 

el değmemiş yüreğiyle

alnına  paslı bir çivi gibi çakılı kederli tohumların kulübesinden

aynı yıldızı kokluyordu

adam ve kadın ayrılığın iliğinde çürüyordu

Orhan DEMİRTAŞ', 'adam,  İsa''nın çarmıhına gerilmiş gibi ...acıyan yanlarına çığlığını gömerek ....uzun etekli bir dağı tırmanırken yıpranmış kayaların sesi u...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adam-isa-kadin-carmih-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öğüt', 'ogut-abdullah-atay-cpkcu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'vurdum duymaz kişiye olursan kefil

tanımaz  seni işi görülen gafil.

insanlık,hayır hasenat yaptım derken

ne yazık çoluk çocuk olursun sefil...', 'vurdum duymaz kişiye olursan kefil tanımaz  seni işi görülen gafil. insanlık,hayır hasenat yaptım derken ne yazık çoluk çocuk olursun sefil....', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ogut-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Layla -ı-', 'layla-i-orhan-demirtas-iwpxo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'inan ki suçsuzum ben

                  ve çok masumum Layla

 muson rüzgarlarının etkisinde kalan

................ülkeler kadar, suçsuz ve masum

tropikal iklimlerde yaşanan sevdaların

..........sıcaklığını taşıdım yüreğimden yüreğine

İnanna''nın gözlerinde büyüttüm seni

isminde unuttum sesimi Layla

benden başkasını yakmaz, benden başkasını ateşin

sana olan duygularımı anlatacak bakire bir söz bulamıyorum

yüzü güzel,

................ruhu zifir bir gecenin esiri olmuşum

Alamut''da zincire vurulmuş bir köleyim şimdi

yada hayatın insanlığa armağan eli gibi

.........................................bir sevdanın tutkunu

bahara duran güller gibi,

......yüzünün, yeryüzünde bulunmayan

..........................gölgesine hasret kaldım Layla

gel ne olur

gel de, düşlerin derinliğine süzülen

.................................mavi bir yüz gibi 

....................................dökül avuçlarıma ansızın

Nil nehri gibi sessiz

......sessiz aksın bana ayak seslerin

gel de, bitsin karanlık gecelerde ayağıma giydiğim

...................................................tek kişilik ölümler-im

gel de, kırılsın gökyüzünün daracık sokaklarında

....................................sessiz ve sensiz üşümeler-im

                  bırak 

Afrikalı büyücüler ölümü bekleye dursun Layla

damarlarım yüzünün hayatını içmekte

gel, geleceğim ol

bakışlarında  yıka beni, temizleneyim

bana geleceğin yolları gözlerimle öpeyim

gel, seven kalbimi öksüz bırakma

bir hayal ülkesi gibi bekleyişim-sin

....sen, görüntümün sesisin

..................sen, kızıl ziyaret efsanesi-sin

sen, yedi milyar insan soyunun arasında

...................................bir tek beklediğimsin

hangi yağmurdan ödünç aldın gözlerini

kirpiklerin cennet kaçkını gibi Layla

bakışlarına bir yol seç

...............................gözlerime batıyor

sen hangi aşkın dikeni-sin

geleceği ve geçmişi olmayan sarhoşlar gibi

.................kendi soğuk gecelerimde sızılı-yorum

gözlerinin hasretinde

.........dostun ve düşmanın ihanetine uğramışım

...............en yalın, en yalnız köşelerde

unutmaz baktığı yüzleri

.........................pas tutan aynalar bile Layla

sen kaç dünya öncesinin yaşlı ruhu-sun

kaç kenti yıkıp geldin de, şimdi önümde durursun

sevgi yapraklarım içimde titrer

sen hangi hırçın rüzgarın adına beni vurursun

ey, incin-dikçe çoğalan bakışlarım

....ey, savunmasız çırılçıplak yanlarım

........ey, ömrünün her anında acının içinden geçen anılarım

sen hüzünler ekmeye devam et dünyaya

çölün gül açacak, çölün gül açacak

deniz diplerinde unutulmuş cesetlerin

mezar taşlarına duyduğu özlemi taşıyorum Layla

gök kuşağının bütün renklerini boğacak

........................hüzünler biriktiriyorum yüreğimde

batağına batmışım lanetli bir kentin

bedenimin iki yanı intihar saklar

gönlüm kimsesiz kirli bir çocuk gibi

dört duvar arasında karanlığa ağlar, karanlığa ağlar

gel ne olur 

fırtınalara maruz kalmışım Layla

kirli bir yalnızlık göğsüme saplandı

ölümün sınırındayım

tüm yüzyılları yakacak

.............................bir hasret ateşinin

.........................................ağlama tufanındayım

Layla, gel göz yaşlarımı sil

Orhan DEMİRTAŞ', 'inan ki suçsuzum ben                   ve çok masumum Layla  muson rüzgarlarının etkisinde kalan ................ülkeler kadar, suçsuz ve ma...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/layla-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Ruh', 'asi-ruh-orhan-demirtas-2fc0m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hala 

.....olirik bakışlarının kırıkları

..............................aç ve susuz

bir dilenci soluğu gibi

..............batıyorsa düşlerime

bil ki

.......ilahi bir engel var

...................sana gelmemi istemeyen

sus.. konuşma...

.........konuşma ne olur

keder bulaşmış cesedim-de-ki

.................asi ruhumu uyandıracaksın

Orhan DEMİRTAŞ', 'hala  .....olirik bakışlarının kırıkları ..............................aç ve susuz bir dilenci soluğu gibi ..............batıyorsa düşlerime...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asi-ruh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairin Kumbarası', 'sairin-kumbarasi-bayram-tunca-8ebr1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç olmadı ki hayatta onun kumbarası

Çünkü yoktu onun ne anası/ne babası

Vardı baykuş dünekli virane bir yuvası

Kalbiydi onun en muazzam kumbarası

Sır verir gibi verdi dostlarına anahtarını

Görenler bayılacaktı neredeyse yarasını

Yara bereyle doluydu garibin kumbarası

Çünkü o peşin almıştı felekten harçlığını

Kumbarasındakiler ya yazdan, ya kıştan

Ya güzden, ya bahardan hepsi kainattan

Kimi arzdan, kimi arştan hepsi tabiattan

Kimi eşten, kimi dosttan hepsi hayattan

Döktü ortaya şair, kumbarasında neyi varsa

Çok seviyordu paylaşmayı azığını dostlarıyla

Kumbarasındakiler, kimisi acı, kimisi tatlıydı

İsteyen istediğinden tattı, her birisi farklıydı

10.10.2004-10.10', 'Hiç olmadı ki hayatta onun kumbarası Çünkü yoktu onun ne anası/ne babası Vardı baykuş dünekli virane bir yuvası Kalbiydi onun en muazzam kum...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sairin-kumbarasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sularda Sırmasın', 'sularda-sirmasin-i-smet-barlioglu-ow9tl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sularda sırmasın ay ışığından,

Dalgada köpüksün, kayada yosun.

Başımda çelenksin defne dalından,

Bırak da gözlerim seyredip dursun.

Seni anımsarım ılık yağmurda,

Koyu yalnızlığı dağıtan nurda,

Nereye bakarsam sen varsın orda,

Her neyi görürsem sen işte osun.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 51-51/100)', 'Sularda sırmasın ay ışığından, Dalgada köpüksün, kayada yosun. Başımda çelenksin defne dalından, Bırak da gözlerim seyredip dursun. Seni anı...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sularda-sirmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürümek', 'yurumek-onur-karatas-06y1e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dünyanın hertürlü bakiliklerine  karşı umursamadan 

yaşamak...

yürümek

yürümeyenleri arkanda 

boş sokaklar gibi bırakarak yürümek

yürümek 

yürekten gülerekten yürümek...', 'dünyanın hertürlü bakiliklerine  karşı umursamadan  yaşamak... yürümek yürümeyenleri arkanda  boş sokaklar gibi bırakarak yürümek yürümek  y...', ARRAY['Türk Edebiyatı','Şiir','Onur Karataş']::text[], 8.5, '{"poet":"Onur Karataş","poet_slug":"onur-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yurumek-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdinmi Birini', 'sevdinmi-birini-i-smet-barlioglu-gjcle', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevdinmi birini candan, yürekten

Aklın maklın kalmaz, ten sarhoşlanır,

Asılacak olsan değer vermezsin,

Son solukta bile can sarhoşlanır.

Sanırsın bulutlar ipek mendildir,

Yıldızlar başında birer kandildir,

En dikenli çalı en körpe güldür,

Zira damarlarda kan sarhoşlanır.

Güneş sanki batmaz, batarken doğar,

Gökten yağmur değil, renktir ki yağar,

Bir zerre içine binbir renk sığar,

Yolcu sarhoşlanır, han sarhoşlanır.

Çirkini görürsün melekten güzel,

Kanadı görürsün telekten güzel,

Ekmeği görürsün börekten güzel,

Dakika, saniye, an sarhoşlanır.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 52-53/100)', 'Sevdinmi birini candan, yürekten Aklın maklın kalmaz, ten sarhoşlanır, Asılacak olsan değer vermezsin, Son solukta bile can sarhoşlanır. San...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdinmi-birini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan ve Çığlık', 'kan-ve-ciglik-orhan-demirtas-p1kl0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'benliğim 

...........kalbim 

......................ve aşkım

soysuzların köle pazarında satıldı

ve ben şimdi ağlayan şiirler yazıyorum

ve süzülüyorum dünyadan büyük düşlerime

ruhumun kanatlarını kızgın ateşler yakıyor

ve çırılçıplak giriyorum

.......kış gibi soğuk, içimde uyuyan koynuna

ve matemli bir köylünün yüzünden düşüyorum

yağmura susayan topraklar yalıyor kederimi

ay ışığı altında, siyah bir rüzgar, 

........................aç it gibi uluyor penceremde

ve sen içimdeki tek yolcusun

ne sevgili olaydın 

......nede sana hasret ölümler yaşayaydım

           

.....ben Adem değildim

.....yinede ateş aylasından değil

.....Meryem yüzünden yedim sürgünümü

ilk insan kadar çıplağım

......................ilk ölüm kadar utangaç

gövdemde çatlıyor gecenin yüzü

cellatlarım geliyor üstüme ölüm kokan nefesleriyle

ağzımdaki aşk, kinli bir kurşuna yenilir

kanım yayılır çiçekli dağlara

parlar gün gibi, yazgısız sevdalara

hangi ölünün gövdesiyim ben

............ve ruhumu kim geçirebilir bu nehirden

               

........ben Mecnun değildim

........kesik bir başla döndüm

........Leyla’ nın çölünden

sen sesime bağışlanan keskin bir cam kırığıydın

................................................aklıma batıyordun

unutmadım, unutamadım seni

çağlar ötesi kederler var bende

.................................çağlar ötesi hüzünler

hasretindir kanatan yalnızlığımı

...ve hala

..............sen yoksun

............................çimen yeşili sesin yok

içimde susuyor çıplak adımlarının izi

ağır, ağır kanıyor çarmıha gerilen sevdam

bir diken gibi batıyor çığlıklarım güneşe

hani, yalnızlığıma ipeksi akışların olmasa

........ve serilmese üstüme yağmur gibi saçların

bir gece yarısı acısına

.............................yenik düşer,

.............................................intihar olurdum

           

.......ben Zeus değildim

.......hırçın mavi gözlerim yoktu

.......yinede kan sıçrayan bir yüreğin içinden

.......elmastan yontulmuş bir aşk getirmiştim sana

yanmış sözlerime astım hatıralarını

yok oldum cehennemden gelen sesinde

gözlerinin yarısıdır kutsal bir kitap gibi taşıdığım

yarısıdır gözlerin narin bir kelebek ölüsü saklayan

ah, o menekşe dağlar

..............yüreğimin çaresiz savaşçıları dağlar

dumanlı ırmaklarının eteklerinde 

............kanla yoğrulmuş çiçekler açarlar

eriyip dökülür nereye bilmem kirli sakallı eşgalim

kül rengi kederler, mezar kazıcıları gibi

...............................................yontarlar benliğimi

ak yüzün solar gölgemde

ve gövdemi taşlarken şairler

...........yüreğimin bütünü sen olursun

........................................senin yarın gök yüzü

            

..........ben Bo-Han değildim

..........sen Sungari değildin

...........yinede ateşlerin efendisi ettin beni

içimde dolaşırsın

saçları tanrıların mücevheri bir kız gibi

gülüşlerin ise kimsenin bilmediği bir lisan

ve sıcaklığının kokusu siner üstüme

ve yıkar gökyüzümü körpe sesin

ve tutuşur gölgene vurgun beklemelerim

saklarım seni içimde bir düş hançeri gibi

duyuyorum sesini hayalinin

kansız bir güneşin içinden geçiyorsun

uykusuz bir mızrak saplanır göğsüme

ve dökülür parçalarım isminin tüm harflerine

vurur cansız bedenim 

.................kefensiz, ölü ışıkların kıyılarına

kan ve çığlık olurum dünyanın kıpkızıl haritalarına

nefesimde titrer esmer bir öfke

nereme dokunsam, kanarım acı içinde

ve ipini boynuma atar yosma bir cesaret

unutulmuşum

.....................halsizim

ağzımda, tuz tadı bırakan bir anı

kilitledi beni küf tutmuş ranzasına

sevgisizim

.................kimsesizim

ruhum, öpülmeyi bekleyen bir fahişe kadar aç

Öpülen ar kadar utangaç

	

.......ben Nuh değildim

.......nevroz alazlarına değil

.......gözlerinin tufanına yenildim

kederim uyanır kirpiklerime değdikçe hayalin

..yinede saklarım seni umudun gövdesinde

....çürüyene dek zamanın kemikleri

.............kan ve çığlık içinde

	

Orhan DEMİRTAŞ', 'benliğim  ...........kalbim  ......................ve aşkım soysuzların köle pazarında satıldı ve ben şimdi ağlayan şiirler yazıyorum ve süz...', ARRAY['Türk Edebiyatı','Şiir','Orhan Demirtaş']::text[], 8.5, '{"poet":"Orhan Demirtaş","poet_slug":"orhan-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":103,"source_url":"https://www.antoloji.com/kan-ve-ciglik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Diye', 'deli-diye-i-smet-barlioglu-iys5o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın gülme üstüme bu da bir deli diye,

Gözündeki yaş değil, ilkbahar seli diye,

Senin aşkın kalbimi öldükçe diriltiyor,

Ömrüm sona erse de ağlama ölü diye.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 54-54/100)', 'Sakın gülme üstüme bu da bir deli diye, Gözündeki yaş değil, ilkbahar seli diye, Senin aşkın kalbimi öldükçe diriltiyor, Ömrüm sona erse de ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deli-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş de Bak', 'dus-de-bak-i-smet-barlioglu-seelh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hele aşka düş de bak

Yüz nasıl mahzunlaşır.

Hele bade iç de bak

Dert nasıl yakınlaşır.

İnsan sevdimi bir kez

Deli zanneder herkes,

Akşamlar iner inmez

Her şey yabancılaşır.

Boşa koyarsın dolmaz,

Doluya koysan almaz,

Yürek hiç avunamaz,

Yaşantı durgunlaşır.

Yandığını sanırsın,

Herkesten utanırsın,

Diplere saklanırsın,

Elemin sağlamlaşır.

Ömrün bir anlık olur,

Gönlün külhanlık olur,

İniltin çığlık olur,

Kainat sağırlaşır.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 55-56/100)', 'Hele aşka düş de bak Yüz nasıl mahzunlaşır. Hele bade iç de bak Dert nasıl yakınlaşır. İnsan sevdimi bir kez Deli zanneder herkes, Akşamlar ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dus-de-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşardı Gözlerim', 'yasardi-gozlerim-i-smet-barlioglu-ec5nw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşardı gözlerim, sızladı kalbim,

Gönlüm yine düştü ıssız yollara.

Ne olacak böyle bilmem ki halim,

Çilem kafa tuttu uzun yıllara.

Ne gönlüm bıkıyor, ne yol bitiyor,

Ruhum her adımda onu görüyor,

Aldandıkça kalbim feryat ediyor,

Gömülüyor içim kara yaslara.

Uğrunda tükendim, umursamadı,

Varmışım, yokmuşum, hiç aldırmadı,

Aklım yüreğimi durduramadı,

Boyun eğip gitti boş heveslere.

Her soluk alışta anımsıyorum,

Anmasam kalbimden utanıyorum,

Bir ömür boyudur aldanıyorum,

Gönlümü hapsettim tel kafeslere.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 57-58/100)', 'Yaşardı gözlerim, sızladı kalbim, Gönlüm yine düştü ıssız yollara. Ne olacak böyle bilmem ki halim, Çilem kafa tuttu uzun yıllara. Ne gönlüm...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasardi-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana ''Leyla'' Desem', 'sana-leyla-desem-i-smet-barlioglu-d0ec9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz gecelerde sabah mı olur? 

Yaralı kalbime felah mı olur? 

Sana ‘Leyla’ desem günah mı olur? 

Mecnun ‘u mahveden Leyla değil mi? 

Çile döner durur garip başımda,

Dertler fırsat bekler yanıbaşımda,

Feryatlarım gizli her gözyaşımda,

Mehtabın varlığı ayla değil mi? 

Ha aşka düşmüşüm, ha da tuzağa,

Bakamaz olmuşum güle, yaprağa,

Kum gibi sürünüp düştüm uzağa,

Kumun sürünmesi suyla değil mi? 

Aradığın olmaz, sorduğun olmaz,

Neler çektiğimi gördüğün olmaz,

Ölsem de farkına vardığın olmaz,

İnsafın ölçüsü huyla değil mi? 

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 59-60/100)', 'Sensiz gecelerde sabah mı olur?  Yaralı kalbime felah mı olur?  Sana ‘Leyla’ desem günah mı olur?  Mecnun ‘u mahveden Leyla değil mi?  Çile ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-leyla-desem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Yolcu', 'yorgun-yolcu-i-smet-barlioglu-0vsjp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapandı yanağım mermer masaya,

Kaldı gözyaşlarım sisler içinde.

Koskoca bir ömür gitti havaya,

Yoruldu yüreğim yaslar içinde.

Unutur giderim sanmıştım seni,

Oysa tüm varlığın kuşattı beni,

Unutmak mümkün mü tutsak edeni? 

Kaldı zincirlerim paslar içinde.

Bir yorgun yolcuyum bir eski handa,

Gözlerim yollarda, ellerim kanda,

Bir yer arıyorum senin yanında,

Umuttur içtiğim taslar içinde.

Mermer masalarda tesellilerim,

Dumanlar içinde iniltilerim,

Uzandı hayale yine ellerim,

Düşmana sığındım dostlar içinde.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 61-62/100)', 'Kapandı yanağım mermer masaya, Kaldı gözyaşlarım sisler içinde. Koskoca bir ömür gitti havaya, Yoruldu yüreğim yaslar içinde. Unutur giderim...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yorgun-yolcu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '...Barut Yeşili*', 'barut-yesili-naime-erlacin-0c2jb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yunmadıkça gayya kuyusunda

suyunda bir kez yosun tutmadıkça

bilemez insan

yüreğinde açan kış veya

yaz yeşili midir tetik çekildiğinde

baruta söz mü keser yoksa yazgı

elbette ağlar

karaya vurduğunda küf yeşili 

resmin öteki yüzünde 

yaşamın sırrını çözer fresko

üstüne yürür de duvarlar

bir renk ustası biliyorum 

bin yıllar ötesinden 

yemyeşil! 

sürgün toplar bıkmaksızın

yırtılır barutu 

grinin buğulanmış teninden 

umut doğurmak 

yosuna seçtiği eylem

anası olmak yeşilin

ah yosun! 

bir gayya kuyusu olsaydı sürgün yeri

nasıl da yeşerirdi evren

…….

(*)     “Aslında biz sürgündük, çekilince tetik. Öyle de kokuyoruz, yosunlu karaya vuruşlarda. Barut gibi yeşil…” – Ömer Serdar

Not: Şiir, 2004 yılının Ekim ayı başında, onun bir yazısından edinilen fikirler doğrultusunda yazıldığı için ve esinlenmenin hakkını teslim etmek adına, önce değerli dostum Ömer Serdar''a sunularak ve onun izni alındıktan sonra kaydedilmiştir.

(12 Ekim 2004)', 'yunmadıkça gayya kuyusunda suyunda bir kez yosun tutmadıkça bilemez insan yüreğinde açan kış veya yaz yeşili midir tetik çekildiğinde baruta...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/barut-yesili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El Gibi', 'el-gibi-talip-kaplan-dghq2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Doyamadım sana kara gözlüm

Yetmedi onca uzun yıllar

Basamadım bağrıma kızım gibi

Kucak açıp saramadım kollarıma

Sevemedim seni doya doya

Oğlumun ellerinden tutupta

Esmer tenine sokulup

Kaşını gözünü öpemez gibi

Kışta kalmış kuş gibi

Gurbet elde sürgün gibi

Yalnız ağlamakta varmış

Bir yabancı, el gibi...

(25 Kasım 1994)', 'Doyamadım sana kara gözlüm Yetmedi onca uzun yıllar Basamadım bağrıma kızım gibi Kucak açıp saramadım kollarıma Sevemedim seni doya doya Oğl...', ARRAY['Türk Edebiyatı','Şiir','Talip Kaplan']::text[], 8.5, '{"poet":"Talip Kaplan","poet_slug":"talip-kaplan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/el-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Giz', 'giz-hakki-hakan-kaya-6ufwp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bildiğim yoldur

yürüdüklerim

ardımdan gelir

ayak izlerim 

...

dünya tanıdığım

ışığıdır nesnelerin

cüce kalır yanında

gizemli devlerin

...

kabuğumu sıyırır

eremediklerim

karanlıkta kalır

göremediklerim...', 'bildiğim yoldur yürüdüklerim ardımdan gelir ayak izlerim  ... dünya tanıdığım ışığıdır nesnelerin cüce kalır yanında gizemli devlerin ... ka...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Hakan Kaya']::text[], 8.5, '{"poet":"Hakkı Hakan Kaya","poet_slug":"hakki-hakan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/giz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin Ekvatoru', 'sevginin-ekvatoru-selim-bayrak-kfx8i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ninnilerden gelen güzel bir ses kulağıma 

Aşkı çağrıştırıyor

Uyku zamanı gelince gözlerime bir anda

Aklım masallara dalıyor

Düşlerde renklerin hepsi bulunur

İster siyaha beyaza maviye boya

Ama yalnızlık hep karşında durur

İstersen renkleri hayatta ara

Gerçek yeşil pembe kırmızı budur

Bırak essin yönsüz rüzgarlar

Vazgeçilmeyince bazı duygulardan

Sapsa da bir taraflara

Sevginin ekvatoruna ulaşırlar

Merak etme

Kutupların soğuğunu duyumsarsın iliğinde

Dört mevsim de gelir ardından ümitle

Ve yakıcı sıcağındasın zaten aşkın

1992 - Bolu', 'Ninnilerden gelen güzel bir ses kulağıma  Aşkı çağrıştırıyor Uyku zamanı gelince gözlerime bir anda Aklım masallara dalıyor Düşlerde renkler...', ARRAY['Türk Edebiyatı','Şiir','Selim Bayrak']::text[], 8.5, '{"poet":"Selim Bayrak","poet_slug":"selim-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sevginin-ekvatoru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar 3 (28)', 'dalgalar-3-28-i-brahim-arslan-h7xoq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir meçhul uğultu gelir kulağıma,

İçim hep bir ürpermeyle dolar,

Bir soluk daha katılır soluğuma,

Sevincim bende dirilir bende donar...

Hep tenha yerleri seçerim ben,

Her tarafımda rüzgarlar eser,

Yok hiçbir yanımda,

Riyadan ve yalanlardan eser...

Kah daralır gönlüm,

Kah kalbim daha hızlı atar,

Bazen sona erer ömrüm,

Bazen cesedimi alıp götürür dalgalar...

Dalgaları aşıp gelirim birgün,

Cesaretimin bittiği,

Umudumun söndüğü gün gelirim...

Artık bitse sana olan hasretim,

Çıkıp geliversen kabuslarımın arasından,

Yahut denizi aş desen ben gelsem,

Cesedimi olsa  getirse sana,

                                        dalgalar...

2004', 'Bir meçhul uğultu gelir kulağıma, İçim hep bir ürpermeyle dolar, Bir soluk daha katılır soluğuma, Sevincim bende dirilir bende donar... Hep ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Arslan']::text[], 8.5, '{"poet":"İbrahim Arslan","poet_slug":"i-brahim-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dalgalar-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut Çocukları/Güzel Günlere Şiir', 'umut-cocuklari-guzel-gunlere-siir-semra-sahin-pqapo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut olmalı! 

Tüm sokakların

Umut olmalı tüm okulların, semtlerin, şehirlerin 

Umut olmal! 

Tüm çocukların adları

Kaldırılmalı! 

Yeryüzünden, gökyüzünden

Kaldırılmalı! 

Sözlükten, dilden, benlikten,yürekten

Kaldırılmalı! 

Tüm olumsuzluk ekleri, kelimeleri

Vs...leri...leri...leri

Güne durmalı! 

Güne bakmalı! 

Gün görmeli! 

Umut şehrinin, umut semtinin,

Umut okullarında okuyan

Umut çocukları...

22/05/2004

C.tesi/Okmeydanı', 'Umut olmalı!  Tüm sokakların Umut olmalı tüm okulların, semtlerin, şehirlerin  Umut olmal!  Tüm çocukların adları Kaldırılmalı!  Yeryüzünden...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/umut-cocuklari-guzel-gunlere-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıçak Attım Kanamadı Gece...', 'bicak-attim-kanamadi-gece-i-mdat-ozcan-s7ns0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine takındın dudaklarına 

Hoşçakal tebessümünü 

Sancılandı yine zaman 

Belli belirsiz yükler bindi sırtıma 

Dalından kopan yaprak kadar 

Hüzün çöktü güne 

Yar ne olur 

Gitme 

Bilirmisin sen bıçaklanmış uykular ağrısını 

Zehirli düşleri 

Kelepçeyi 

Mahpusluğu bilirmisin 

Çıkarma gözlerinden hayallerimi 

Zebanilere pazarlama yüreğimi 

Ne olur gitme 

Gitme yarım kalmasın umutlar 

Şafakları zindan olmasın dünyanın 

Yaşamak sancıları kalır bedenimde 

Dinle kal diyen tarafını 

Dur ne olur gitme 

Bak bütün bebekler sensizliğime ağlıyor 

Bak gökyüzü hüznüme ağlıyor 

Kaybolmuş resimler 

Tedirgin gölgeler gezer peşimde 

Karabasan geceler sıkar boğazımı 

Ateş ettim kanamadı gece 

Bıçak attım kanamadı gece 

Gül kokusu duydum 

Kanadı yüreğim 

Vuslatları zehir etme 

Yar 

Dur 

Ne olur 

...Gitme....', 'Yine takındın dudaklarına  Hoşçakal tebessümünü  Sancılandı yine zaman  Belli belirsiz yükler bindi sırtıma  Dalından kopan yaprak kadar  Hü...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bicak-attim-kanamadi-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-hakan-i-lhan-dagci-sa4pz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her gece seni düşünerek,

Hep o günün hayalini kurarak; 

Fakat sadece yırtık resmine 

Ve gecemi aydınlatan hayaline

Haykırdığım o iki kelimeyi

İki Eylül sen giymeden kefeni

Bağıra bağıra söyleyebilseydim,

Keske Seni Seviyorum diyebilseydim.', 'Her gece seni düşünerek, Hep o günün hayalini kurarak;  Fakat sadece yırtık resmine  Ve gecemi aydınlatan hayaline Haykırdığım o iki kelimey...', ARRAY['Türk Edebiyatı','Şiir','Hakan İlhan Dağcı']::text[], 8.5, '{"poet":"Hakan İlhan Dağcı","poet_slug":"hakan-i-lhan-dagci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/keske-71-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Bir Ada/Terkeden Hayaller', 'issiz-bir-ada-terkeden-hayaller-semra-sahin-nlgkt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Issız Bir Ada/Terkeden Hayaller

Issız bir adadaydık

Sen, ben ve minik elleriyle minik gülüşleriyle düş çocukları...

Geri kalanlar 

Sırtlanlar, çiyanlar

Elbet çiçeğimiz de vardı, börtü böceğimiz

Küçük bir kara parçasıydı

Sen, ben bir de uçsuz bucaksız deniz

Issız bir ada, küçük bir kara...

Yeter sanıyorduk hayallerimiz

Issız bir ada ya düştüğünüzde

Ne alırsınız? demişlerdi

Sen beni....

Ben seni...

Uçsuz bucaksız bir deniz...

Bir de ömrümüzün sonuna kadar yetecek hayalleri...

Issız bir adaya düştük.

Aldık yanımıza

Seni, beni bir de hayalleri

Aşk sonsuzluktu

Ada yalnızlık

Deniz ıssızlık

Heyyy! 

Ufukta görünen koca bacalı 

Kara dumanlı bir gemi..

Adayı terkeden sen mi ben mi? 

Aşk yalnızlıktı

Ada ıssızlık

Deniz sonsuzluk

El salla

Terk eden sen mi ben mi? 

El salla

Terkeden hayallerdi

22/05/2004

C.tesi/okmeydanı', 'Issız Bir Ada/Terkeden Hayaller Issız bir adadaydık Sen, ben ve minik elleriyle minik gülüşleriyle düş çocukları... Geri kalanlar  Sırtlanla...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/issiz-bir-ada-terkeden-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-sair-errool-50yey', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer bir gün olurda

Anımsarsan beni

Sakın unutma

Bu şiir sana

Eğer hala

yankılanıyorsa sesim

Kulaklarında

Ve süzülüyorsa gözyaşların

Yanaklarında

Beni düşündüğünde

hızlı hızlı çarpıyorsa kalbin

Beni hatırla

Unutma sakın

Ben bir tek sana 

Gülüm dedim.', 'Eğer bir gün olurda Anımsarsan beni Sakın unutma Bu şiir sana Eğer hala yankılanıyorsa sesim Kulaklarında Ve süzülüyorsa gözyaşların Yanakla...', ARRAY['Türk Edebiyatı','Şiir','Şair Errool']::text[], 8.5, '{"poet":"Şair Errool","poet_slug":"sair-errool","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gulum-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan beni', 'sevdan-beni-burhan-kucuk-diec5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duyarım rüzgarın sesini

Kulaklarıma fısıldar adını

Gölgen düşer usuma

Terk etmemiş sevdan beni

İçiyorum efkar kahvesini

Ne tarafa baksam sen

her taraf dolu hayalin

Terk etmemiş sevdan beni

Yazsın diye adının ilk harfini

Salıyorum sigaramın dumanını

Açık havada bulut gibi

Terk etmemiş sevdan beni

Burhan Küçük

Kdz.Ereğli-10.10.2004', 'Duyarım rüzgarın sesini Kulaklarıma fısıldar adını Gölgen düşer usuma Terk etmemiş sevdan beni İçiyorum efkar kahvesini Ne tarafa baksam sen...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevdan-beni-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Bekleme Gel Sende Vur', 'gel-bekleme-gel-sende-vur-murat-demir-6s4ic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hergün beni yüreğimden

Kurşun değil hasret vurur

Sanki olmuş top mermisi

O gün bugün patlar durur

Gel bekleme gel sende vur

Öldürsende dememki dur

Al eline diyar diyar

Bir sen kaldın sende savur 

Şu sevdamın kurağına

Sevgi diye dolu yağar

Ben yandıkça can evime

Katmer katmer acı yığar

Gel bekleme gel sende vur

Öldürsende dememki dur

Al eline gurbet gurbet

Bir sen kaldın sende savur

Olamadığın dünyamda

Her yanımı sardı hışım

Bir hasret ki ortasında

Koydu beni kara kışın

Gel bekleme gel sende vur

Öldürsende dememki dur

Al eline yurttan yurda

Bir sen kaldın sende savur!', 'Hergün beni yüreğimden Kurşun değil hasret vurur Sanki olmuş top mermisi O gün bugün patlar durur Gel bekleme gel sende vur Öldürsende demem...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gel-bekleme-gel-sende-vur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sever misin?', 'sever-misin-can-ozcan-ozkan-8lcpo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzündeki yıldızlar adını yazar

Işıltısında gözlerim parlar

Her dudak büküşün yüreğimi dağlar

Küs gitme gülüm bu can ağlar

Bu acı kalbimi sarar

Haydi bir gül gelsin bahar

Vakit geçiyor üzülmek neye yarar

Bu deli gönül yaşlı gözlerle hep sana bakar

Sen ki gönlümde açacak bir tomurcuk

Sevgiyi senle yoğurduk

Bir bahar akşamı Duru’şu senle doğurduk

Can oğlumuzu avucumuzda okuttuk

Düşmanı olduğu yerde kudurttuk

Sen adımın gizli gülü

Evimin her vakit öten bülbülü

Rüzgarlara kokunu veren sümbülü

Gel gidelim sonsuza yık bu kültürü

Bakışların boğar beni

Yokluğum üzer mi seni? 

Yaş dökerek heder etme kendini

Özledim yakamozla gülen denizi

Bizdik mavilikte yüzen yelken

Parmakta yüzük gözlerle söz verirken

Aşkımız bitmez birbirimizi severken

Öpüşürdük seninle aşk balığını çekerken

Haydi gel benim nazlı papatyam

Seni yüreğime sarsam

Gözlerini yüreğimde avuçlasam

Koca bir sevda bahçesi sunsam

Sever misin? Beni......

21.03.2003', 'Gökyüzündeki yıldızlar adını yazar Işıltısında gözlerim parlar Her dudak büküşün yüreğimi dağlar Küs gitme gülüm bu can ağlar Bu acı kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Can Özcan Özkan']::text[], 8.5, '{"poet":"Can Özcan Özkan","poet_slug":"can-ozcan-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sever-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Gerçeği...', 'askin-gercegi-i-brahim-ethem-bingul-i23g6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Severim sevgi nöbetlerini

Açlığı, susuzluğu,yokluğu

Aşkla an be an dolu geçiyorsa

Sevilen, sevilmeye değiyorsa

Sessiz seslenişlerimi duyuyorsa

O da o anda,

O ânı yaşıyorsa

Bu aşkın gerçeğidir

Bu aşkın kendisidir....', 'Severim sevgi nöbetlerini Açlığı, susuzluğu,yokluğu Aşkla an be an dolu geçiyorsa Sevilen, sevilmeye değiyorsa Sessiz seslenişlerimi duyuyor...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/askin-gercegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Aşk! Elma Dersem Çık', 'ey-ask-elma-dersem-cik-semra-sahin-pwy3b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Aşk!  Elma Dersem Çık! 

Kendini bilmezken aşkı yazmak istersen

Ey aşk elma dersem çık! 

Asır oldu sanki

O kadar yaşlı ve yorgun ki yürek

Belki dolu yaşamış beden, 

Dinginlik demiş akıl, aşk demiş yürek

Fırtınalara boğulmuş bir bütün; yani ben

Ben kim? Kimim ben? 

Öykü böyle başladı.

Sanki o gün doğmuştum.

Ama bir cinayet işleyerek,

Birinin bedenine girerek,

Olmayan beni yakalamıştım.

Ne yazacağımı gerçekten bilemiyorum? 

Bu bana mı mektup? 

Sana mı mektup? 

İtiraf mı, kanıt mı, öykü mü, masal mı? 

Ey Aşk elma dersem çık! 

Ey Aşk elma dersem çık! 

Ama elmaaaa diye bağırıyorum

Ya o kelime öyle söylenmiyor/ya da sesim çıkmıyor

Belki de beni duymak istemiyor.

Aşk elma dersem çık! 

Hayatım boyunca bağırmaktan korkuyorum! 

Bu hazin öykü, bu yaşanmışlık, bu yaşlanmışlık

Nerde başlıyor? Tanrım ne zaman bitecek? 

Kim olduğunu bilmezken aşka nasıl seslenebilirsin ki? 

O nu nasıl tanımlayıp, nasıl seçebilirsin ki? 

Aşk... Ey aşk... elma dersem çık! 

Aşk mı? 

Nefes almaktı ölümü kucaklarken

Sessizlikte sese yalvarmak

yalnızlığa cansız mankenlerle kılıftı.

Teni tatmak onun esiri olup terini tüketmekti.

Kursağında bebeği hissedip onu neştere teslim etmekti.

Ah aşk...

Denizi keşfetmekti/ruhu denizde kaybetmekti.

Emeği tanıyıp/haksızlığa gözyummaktı.

Kirlenmemesi için susmaktı.

Karşılığı umarsızlıktı hayınlıktı ihanetti yalandı.

Sevdim ama taparcasına

Bir tanrı yarattım o da beni yaşatsın diye

Biri isyan ediyor ben kimim diye

Ey aşk..aşk...duymuyormusun

Ey aşk ben kimim/tamamda

O kim sen misin ben miyim

Biz evet biz....

Biz aşk/aşk biz

Elma dersem çık! 

Uzunca matematik işlemleri

Kafa karıştıran bölmeler, çıkarmalar, çarpmalar

Başka rakkamlar başka insanlar

Ve eşittir 

Ben, sen o da biz

Ey aşk

O değil miydi

Seni ben /beni sen yapan

Bizi yüreğin rahmine dölleyen

Sonra büyüten

Sonra konuşmayı, sonra dokunmayı, sonra gülmeyi

Sonra keşfetmeyi öğreten

Sonra...Sonra

O değil miydi mahpusluğa kendini yakıştıran

O değil miydi Küçücük yalnızlık kokan bir odayı

Bir beşiktaş iskelesi kalabalığına dönüştüren.

Evet oydu

Elele tutuşmak için korkularla şehri terkedip

Bir kuytu buldurtan.

O değilmiydi hem suçlu hemde zeytinyağı olan

suyun yüzünde yüzsüzce dolaşıp beni unutturan

Ey aşk elma dersem çık

Ya o söz öyle söylenmiyor

Ya da sesim çıkmıyor

Belki de beni duymak istemiyor

Aşk ey aşk elma dersem çık

Seni daha önce tatmışmıydım ilk misin

Doğrusunu istersen beni asıl korkutan

Son olman

Ey aşk elma dersem çık

Ve sonsuza kadar elma.........

04/08/2002

Gazi Mah.

(Başlarken...bitmişti/Bir aşkın anısına/2)', 'Ey Aşk!  Elma Dersem Çık!  Kendini bilmezken aşkı yazmak istersen Ey aşk elma dersem çık!  Asır oldu sanki O kadar yaşlı ve yorgun ki yürek ...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":84,"source_url":"https://www.antoloji.com/ey-ask-elma-dersem-cik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemem..!', 'soyleyemem-hasan-basri-kale-s4l6i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir ses aydınlatır içimi

gecenin 

ıssız bir anında

yalnızlığı solurken..

yıldızların peşinden

renk renk dökülür 

konfeti gibi

gökkuşağı

siyahtan laciverte döner ufkum.. 

düş mü gerçek mi

bilemem

uzattığım eli 

tutar sımsıkı

gözlerime bakar 

ağlamaklı

.........tam sırası derim

.........hadi şimdi

.........söyleee..! 

dilim tutulur...söyleyemem..!', 'bir ses aydınlatır içimi gecenin  ıssız bir anında yalnızlığı solurken.. yıldızların peşinden renk renk dökülür  konfeti gibi gökkuşağı siya...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/soyleyemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*G ü l...D u d a k l a r ı n....(Aktivite)', 'g-u-l-d-u-d-a-k-l-a-r-i-n-aktivite-metin-eser-xiiwj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aklıma her düştüğünde,

..........gözlerim dolar, yutkunamam,

ve içimde derin bir sızı çağlar,

gözyaşımı istesem de tutamam.

tek isteğim ahh bir karşımda olsan,

nağme-i kalbimi bir duysan,

ve o gül dudaklarından

..........çatlamış dudaklarıma 

....................ıslak bir öpücük kondursan.

sonra hayalim bitse,

bütün gecem kâbus olsa ne çıkar,

hayat bitse, 

..........nefes bitse, 

....................ölsem ne çıkar.

12.10.04 / Frankfurt

***Samanyolu Grubunun 2K1Ş ''İki Kelime Bir Şiir'' Aktivitesi için kaleme alınmıştır. Kelimeler: NAĞME ve GÜL', 'Aklıma her düştüğünde, ..........gözlerim dolar, yutkunamam, ve içimde derin bir sızı çağlar, gözyaşımı istesem de tutamam. tek isteğim ahh ...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/g-u-l-d-u-d-a-k-l-a-r-i-n-aktivite-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü Dudaklarımda', 'turku-dudaklarimda-emel-manav-cig9j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Duvarlar örüldü üstüme 

Ne eşim anladı, ne kardaş 

Benim içimdeki beni! ! ! 

Dinlersen anlatırım sana arkadaş 

Kurudu akmıyor gözümde yaş 

Benim yaşadıklarımı yaşasa 

Ağlardı dağ ile taş. 

Bastırdım duygularımı 

Attım hep içime sıkıntımı 

Yalvardım baştan yaz benim yazımı 

Diye yaratanıma 

Kader bu değişmez deseler de. 

İnatla savaştım değiştirmeye 

Duvarlar örüldü üstüme 

Geçen yıllardan kalan bir türkü dilimde 

Cefa çektim, sefaya ulaşamadım 

Ben dengimi aradım, bulamadım 

Hayatta varsın olsun zorluklar 

Nasılsa kışın sonu bahar 

Öyle değilmiş canlar, 

Öyle değil mi dostlar? 

Bitiyor içimde heyecan 

Bitiyor kıpırtılar 

Baharın ardından yaz gelse 

Neye yarar. 

Çoktan başıma bağlamışım karalar. 

Nasılda çabucak geçmiş yıllar 

Bir türkü kalmış dudaklarımda 

Oy oy dumanlı dağlar! ! !', 'Duvarlar örüldü üstüme  Ne eşim anladı, ne kardaş  Benim içimdeki beni! ! !  Dinlersen anlatırım sana arkadaş  Kurudu akmıyor gözümde yaş  B...', ARRAY['Türk Edebiyatı','Şiir','Emel Manav']::text[], 8.5, '{"poet":"Emel Manav","poet_slug":"emel-manav","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/turku-dudaklarimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aramızdaki Fark', 'aramizdaki-fark-abdurrahim-karakoc-4afio', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen dünden gelirsin, ben yarından gelirim

Doğmadık bebekler diyarından gelirim.

Sen müebbet inkârda kılmışsın kararı

Ben Kalubelâ’nın ikrarından gelirim.

Akıl Karaya Vurdu', 'Sen dünden gelirsin, ben yarından gelirim Doğmadık bebekler diyarından gelirim. Sen müebbet inkârda kılmışsın kararı Ben Kalubelâ’nın ikrarı...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/aramizdaki-fark-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecazım Ben', 'mecazim-ben-semra-sahin-jsf1b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Mecazım Ben

Mecazım ben

Aynaya baktığımda

bana bakıldığında görünen

Bildiğiniz et kemik kaş göz

Bildiğiniz bir dişi

bilmediğiniz bir insan

Mecazım ben

Bazen buzullarda bazen çöl yangınında

Evet her yerde herdaim atan bir yürekte var bende

Mecazım ben

Bazen akıllı

Bazen akıllı deli

Mecazen yarım akıllı

Ne kader ne de kederim ben

Bazende hicaz

Mecazen hicaz

26/09/2003

ist.okmeydanı', 'Mecazım Ben Mecazım ben Aynaya baktığımda bana bakıldığında görünen Bildiğiniz et kemik kaş göz Bildiğiniz bir dişi bilmediğiniz bir insan M...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/mecazim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayfin Keyfine Varmak Sendin', 'kayfin-keyfine-varmak-sendin-semra-sahin-5d60w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Keyfin Keyfine Varmak Sendin

Bir rüya görmeye benziyordu benim için sana dokunmak

Uyanmadan bittiğini anlamıyorsun.

Son dönem o kadar yığın halinde yaşamışım ki

Acıdır anlatmakta zorlanıyorum.

Aşk olarak kapımı çalmadan 

Seninle dost olmak benim için bir keyifti.

Çılgınlar gibi kelimeler, sözler, sözcükler tüketiyorduk.

Seni dinlemek... Bir şarkının sürekli tekrarını arzulamaktı.

Melodisini ruhuna almaktı.

Günü sana bölmek, seni güne bölmek heyecanını

Yürek çarpıntılarını...offfff....

Offff derin bir offfff çekiyorum...

Yüreğim sonunda bir kuş olduğunu hatırladı.

Aradı-arayacak, geldi-gelecek....

Sanki sendin o ana kadar beklediğim/ve gelmiştin.

Bizi senden önce keşfetmiştim.

Hayır asla günah değildi...

Suçluluk duymuştum evet

Ama yaramazlık yapmış bir çocuktu bendeki.

Bana sarılmanın tedını hangi kelime ifade edebilir ki

Biz seninle keşfetmiştik o kelimeyi ''Keyif''

Evet ya keyif hemde offfff... ya keyif.

Birbirimizden beklediklerimiz tavlada zarla dillenirdi

Ya kazanmak...ne keyif

Açtık çok aç 

Ve ruhlarımız yüzyıllarca o anı beklemiş gibi saldırgan

Terimizi tenimize kattık.İçtik...içtik içtik

Şarabımızla balığımızdı önümüzdeki

Ama sarhoşluk şiirlerden paylaşımdan aşktandı.

Yıldızlı ev, sinema, mahpus her yer keyif

Geleceğini bilmek....geldiğin an keyif.

Seninle sevişmek, gülüşmek, konuşmak keyif..

Seni keyifli görmek keyif.

Yüzün, sesin,

Sana adadığım şiir, şarkı, gözün, sözün, elin,tenin

İçine kattığımız gözyaşı...

offfff.....hepsi keyif.

04/08/2002

Gazi Mah.

(Başlarken....Bitmişti/Bir aşkın Anısına/3)', 'Keyfin Keyfine Varmak Sendin Bir rüya görmeye benziyordu benim için sana dokunmak Uyanmadan bittiğini anlamıyorsun. Son dönem o kadar yığın ...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kayfin-keyfine-varmak-sendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecenin Üşüyen Elleriyle Sar Beni', 'gecenin-usuyen-elleriyle-sar-beni-tulay-sustam-8iliv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dün gece...

yine hayalinle uyudum 

bu sabah...

yine yokluğunla uyandım 

değişen bir şey yok

anlayacağın hayatımda

yine gözyaşı

yine yalnızlık

yine sol yanımın sancısı

yine sen, hep sen

ve yine... 

gündüzün yanan elleriyle

kol gezerken senli düşlerim

gecenin üşüyen elleriyle sar beni

ancak o zaman biter sana özlemim

.

.

.

çıplak elle ateşe dokundum

ellerim değil yüreğim yandı...', 'dün gece... yine hayalinle uyudum  bu sabah... yine yokluğunla uyandım  değişen bir şey yok anlayacağın hayatımda yine gözyaşı yine yalnızlı...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gecenin-usuyen-elleriyle-sar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sağım Solum Önüm Arkam Hırsız', 'sagim-solum-onum-arkam-hirsiz-semra-sahin-9jz82', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sağım Solum Önüm Arkam Hırsız

Çekip çalmışlardı seni ve gitmiştin

Tarifi imkansız geceler ve yalnızlıklardı geride bıraktığın.

Asıl beni tüketen bilmediğim bir yerde beni nasıl yaşadığındı

Ne olduysa gidişinle oldu.

Bastığım toprak sürekli deprem halinde

Ve ben tutunduğum bizin elimden kaydığını duyumsadım.

Çalmışlardı bizi aşk yoksulları

yalnızlık kokan beşiktaş iskelesi odamız,

Düşlerimizle dolu sokaklar ıpıssız.

Sağım-solum, önüm-arakam hırsız! 

Gece karanlığı ve sabah ayazı sahneleri o zaman başlamıştı.

Kim hırsız? 

Düşlerimi çalan sen, seni çalan onlar

Aşkı çalan biz.

Sağım-solum, önüm-arkam hırsız

Özlüyorum doyamıyorum derdim ya

Sense ''bir geçiş'' diyordun.

Düşlerimi önüne katıp,dört nala giden bir yabancı gibi

Sözlerime, gözyaşlarıma, tenime basıyordun

Acıyordu-Acıtıyordum.

Artık çok geç yabancı

Dostların vardı yalnızlığıma hapsettiğim dostumu çalan

Sendeki kadınlığıma göz koyan

Bense sana sitem edecek kadar arsız

Sağım-solum, önüm-arkam hırsız

04/08/2002

Gazi Mah.

(Başlarken...Bitmişti/ Bir Aşkın Anısına/7)', 'Sağım Solum Önüm Arkam Hırsız Çekip çalmışlardı seni ve gitmiştin Tarifi imkansız geceler ve yalnızlıklardı geride bıraktığın. Asıl beni tük...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sagim-solum-onum-arkam-hirsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İş İşten Geçince', 'i-s-i-sten-gecince-abdurrahim-karakoc-cwgs5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başkasını yakan zulüm seni de 

Yakar amma neden sonra anlarsın.

Sahtekârın imanı da, dini de

Kokar amma neden sonra anlarsın.

Gün gelir gözlerin dalar yokuşa

Şartlar yorgunları salar yokuşa

Umulmadık yerde sular yokuşa

Akar amma neden sonra anlarsın.

Öfke her gün ölür, aşk eceliyle

Akıl arkadaşlık etmez deliyle

Yanlış yapan yaptığını eliyle

Yıkar amma neden sonra anlarsın.

Yıllarca gül diye koklarsın taşı

Akşamı yaşarsın sabaha karşı

Sabır sarı yaprak, umut gözyaşı

Döker amma neden sonra anlarsın.

Fikirsizlik gol atarsa fikire

Altın diye sarılırsın bakıra

Güvendiğin eller seni çukura

Çeker amma neden sonra anlarsın.

Aman deyim bilir misin amanı

Boş hayale kurban etme zamanı

Müjde dağlarına eyvah dumanı

Çöker amma neden sonra anlarsın.

Çorbaya sallarsın taş dolar kaşık

Dört adım öteye şavk vermez ışık

Kör inada sarılmaktan sarmaşık

Bıkar amma neden sonra anlarsın.

Hakikatler üzücü ha, katı ha

Delinirse su koyverir çatı ha

Zaman zaman gizli kirler satıha

Çıkar amma neden sonra anlarsın.

Kurnaz emer budalanın kanını

Böyle yürür hokkabazın kanunu

Doğru karar eğri dostun canını 

Sıkar amma neden sonra anlarsın.

Eylül-1992

(Akıl Karaya Vurdu)', 'Başkasını yakan zulüm seni de  Yakar amma neden sonra anlarsın. Sahtekârın imanı da, dini de Kokar amma neden sonra anlarsın. Gün gelir gözl...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/is-isten-gecince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Olmanın Yüküydü Sırtımdaki', 'kadin-olmanin-yukuydu-sirtimdaki-semra-sahin-qlgdg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadın olmanın yüküydü sırtımdaki asırlardır biriken

Oysa koynumdaki anasının şımarık oğluydu.

Tenim hiç et olmadı.

Çocuk yaşta kanamıştım.

Kadın olmak kanamakmış,kanamak kadın olmak.

Bense reddercesine top oynardım kadın olmaktan kaçarak.

''Sen yaşındayken ağbini doğurmuştum'' derdi anam.

Ah anam ağbeyimi büyüten, beni yetiştiren anam.

Yasak aşklarını, gizli sevdalarını bilemediğim 

Bilemeyeceğim anam

Uğruma gurbet çekilmiş,dağlar delinmişti

Sevdanın çiçeği ben

Reyhan oldu adım çiğdem gül..lale

Tenim hiç et olmadı

Düşlerimdi onu öyle gösteren

Sevdanın çiçeği ben

Sen çocuğum, yurdum, yoldaşım, yarenim

Nasıl anlatayım ki sana

Beyazlar katarak pembeye dönüştürdüğüm

Düş kadınını

Kadının düşlerini

İnanki tarihten sorumlu değilim 

Yarındır kaygım...

Benki sevda çiçeği

Yaşamadıklarını yaşamak isterken yaftası doyumsuzluktu

Nasıl isterdim bir bilsen

Deli bir sevdadan bir oğlum olsa

Ve ben ona çiçek ismi takacak kadar sevdalı deli

Sen değilmiydin ey aşk koynumdaki....

Anasının biricik gülü...

Tenim hiç et olmadı,

Keşfimizin kanıtıydı,temastı, elektrikti

Kadın olmanın yüküydü terim...

Haylazca kokladın

Her dokunuşun beni milyonlarca yıl öteye götürdü

Çocukça erkek oldun

Erkek olurken bile sen

Anasının şımarık oğluydun

Semra Şahin

04/08/2002

Gazi Mah.

(Başlarken...Bitmişti/ Bir Aşkın Anısına/8)', 'Kadın olmanın yüküydü sırtımdaki asırlardır biriken Oysa koynumdaki anasının şımarık oğluydu. Tenim hiç et olmadı. Çocuk yaşta kanamıştım. K...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/kadin-olmanin-yukuydu-sirtimdaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk 4', 'ask-4-halil-pazarli-x9st9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uzaklar ki hep yerinde

sevda gezer en derinde

Kerbela''ya sefer düzdüm

ateş düştü yüreğime? 

Bana bakma ben kötüyüm

dağda, taşta ben öteyim

hünkâr ola canım kurban

bahçe, bağban ben öleyim..

Aşk aşk diye aşk aradım

ak gönüle yol bağladım

ben Ali''yi sevdim diye

hançer yedim kan ağladım..

Yollar eğri devran muzır

Pir Sultan''ım takmam Hızır

bir ölsekte bin geliriz

Aşk bulmadan varmam huzur..', 'Uzaklar ki hep yerinde sevda gezer en derinde Kerbela''ya sefer düzdüm ateş düştü yüreğime?  Bana bakma ben kötüyüm dağda, taşta ben öteyim h...', ARRAY['Türk Edebiyatı','Şiir','Halil Pazarlı']::text[], 8.5, '{"poet":"Halil Pazarlı","poet_slug":"halil-pazarli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-4-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elde Var Bir', 'elde-var-bir-nalan-kazazoglu-ep09w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel-git akıllıyım elimde olmadan,

Cinnetimi tutmalıyım kimselere bulaşmadan,

Lafın gelişini dua ile bulmadan..

İz düşülmüş yüreğime şiir

Yine elde var bir..

Köşe bucak dolandım,

En çok varlığımı sorguladım..

Güneş nerdeyse ben ordaydım..

İz düşülmüş yüreğime şiir

Yine elde var bir...

Acınası aynalarda hayalgücü bulup,

Gecelerce hindi gibi düşünüp,

Yüreğimdeki izlere döndüm..

Sonun belirsizliğinden korkup...

İz düşülmüş yüreğime şiir...

Yine elde var bir..

Boşa çarptı durdu zavallı yüreğim..

Girmeden kışa yoruldum,

Bunca yaşa geldim,

Ne kestim sesini ruhumun,

Ne de hayatımı ellerimle yoğurdum..

Varsın olsun,

İz düşülmüş yüreğime şiir..

Yine elde var bir....', 'Gel-git akıllıyım elimde olmadan, Cinnetimi tutmalıyım kimselere bulaşmadan, Lafın gelişini dua ile bulmadan.. İz düşülmüş yüreğime şiir Yin...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/elde-var-bir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapın Her Çaldığında', 'kapin-her-caldiginda-tayyip-sag-9pucx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapın her çaldığında,

Ben geldim sanacaksın,

Sevgiye susadıkça,

Hep beni anacaksın.

Ansızın gelir diye,

Bu sevda yokuşunda,

Yollarımı gözleme,

Her güneş batışında.

Bilirsin ki imkansız,

O yollarda görünmem,

Bitti artık bu sevda,

Ölsem de geri dönmem.

Kopunca sevda ipi,

Yokluğuma sarılma,

Rüyalar da gibisin,

Uyanınca darılma.

Bir güneş daha battı,

Yarasalar uyandı,

Bu sevda ateşine,

Bilmem kaç gönül yandı.

Ben yanmak için değil,

Sevmek için sevmiştim,

Meğer sevmek yanmakmış,

Kor ateşler de piştim.

   12.10.2004', 'Kapın her çaldığında, Ben geldim sanacaksın, Sevgiye susadıkça, Hep beni anacaksın. Ansızın gelir diye, Bu sevda yokuşunda, Yollarımı gözlem...', ARRAY['Türk Edebiyatı','Şiir','Tayyip Sağ']::text[], 8.5, '{"poet":"Tayyip Sağ","poet_slug":"tayyip-sag","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kapin-her-caldiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşın Artık', 'asin-artik-mehmet-aslan-q583q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sıkıntın mı var, örfle, töreyle, ananeyle,

Yoksa istediler de vermediler mi bu bahaneyle,

Töreleriniz çok mu zıttı birbirlerine,

Yoksa çok fazlamı dokundu birilerine.

Azaldı artık bunları uygulayan yöreler,

Bu yüzyılda sizde hala devamı ederler.

Neden karartırlar insanların geleceklerini,

Anlayamadım da bu devirde niyetlerini.

Acılı, gözü yaşlı, kanlı oluyor sonları,

Kınıyorum artık böyle yaşayan toplumları.

Yeni bir yüzyıla girdi dünyamız,

Bitsin artık ne kadar varsa kan davamız.

Huzur içinde uyumak varken geceleri,

Kabusla uyandırıyor insanı böyleleri.

Bizler çoktan aşıp geçtik bu yolları,

Sizlerde aşın artık sevgi dostları.', 'Bir sıkıntın mı var, örfle, töreyle, ananeyle, Yoksa istediler de vermediler mi bu bahaneyle, Töreleriniz çok mu zıttı birbirlerine, Yoksa ç...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiysen Kalsaydın', 'sevdiysen-kalsaydin-mehmet-aslan-k24lf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çözemedim seni sır küpümüsün,

Kaçtın sürekli, yoksa küsmüsün,

Bağladın beni kendine büyülümüsün,

Öyleyse neden görmezsin körmüsün.

Sen benim için bir başkaydın,

Ama sen yüksek bulutlardaydın,

Sevdiysen buraları kalsaydın,

Kalabilirdin cesaretini toplasaydın.

Ben bazen hep böyle saçmalarım,

Hayaller üzerine kuruludur aşklarım,

Üzerine kurulur geceleri hayallerim,

Sonunda kâbusa döner rüyalarım.

Senin için hayat toz pempedir,

Benim içinse yalnız gül pembedir,

Hayat sence her zaman gülmedir,

Gerçekse bizde gözyaşı silmedir.', 'Çözemedim seni sır küpümüsün, Kaçtın sürekli, yoksa küsmüsün, Bağladın beni kendine büyülümüsün, Öyleyse neden görmezsin körmüsün. Sen benim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevdiysen-kalsaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tekrar Başladı Endişem', 'tekrar-basladi-endisem-mehmet-aslan-phoha', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unutmuştum ben tüm dertlerimi,

Gömmüştüm bir kenara bütün sevdiklerimi,

Kendi kendime yazardım hayat gerçeklerimi,

Kalemimle dizelerime iletirdim dileklerimi.

Bugüne kadar bir kez gönülden sevmiştim,

Kendimce çok doğru karar vermiştim,

Onunla hayatın mutsuzluklarını yenmiştim,

Sonunda en büyük darbeyi de ondan yedim.

Bu darbeden sonra ben eridim bittim,

Unutmak için bir süre buraları terk ettim,

Bitmek bilmedi darbeleri, bende yemin ettim,

Üç yılımı aldı sonunda ona hayatı zehir ettim.

Yapayalnızdım, bir sigaram, bir şişem birde ben,

Kalmamıştı hayatta ne zevkim nede neşem,

Bir masam vardı, birde onu koyduğum köşem,

Ancak unutmuştum ki seninle tekrar başladı endişem.', 'Unutmuştum ben tüm dertlerimi, Gömmüştüm bir kenara bütün sevdiklerimi, Kendi kendime yazardım hayat gerçeklerimi, Kalemimle dizelerime ilet...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Aslan']::text[], 8.5, '{"poet":"Mehmet Aslan","poet_slug":"mehmet-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tekrar-basladi-endisem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İsteme', 'sen-i-steme-servet-suner-c5fja', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ummanlarda dalga olsan,

Boğamazsın beni.

Yüce dağ bayında esen yel olsan,

Savuramazsın beni.

Kor alevden kopan köz olsan,

Kavuramzsın beni.

Çabalama, harcama olmayan gücünü,

Rüzgarlı günün kuytusu olursun.

Yağmurlu günün uykusu olursun.

Fırtına sonrası doğan güneş olursun.

Yürekten istersem BEN.', 'Ummanlarda dalga olsan, Boğamazsın beni. Yüce dağ bayında esen yel olsan, Savuramazsın beni. Kor alevden kopan köz olsan, Kavuramzsın beni. ...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-isteme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bıraksam Uçacağım Sonsuzluğa…!', 'biraksam-ucacagim-sonsuzluga-nazife-abayli-josf5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana öylesine ihtiyacım var ki bugün.

Yokluğunda eriyip bittiğimi hissediyorum.

Seni seviyorum deyip kayboldun karanlıkta.

Uzattım elimi şimdi,karanlığın eteğine tutunuyorum..

Mahkum ettin sensizliğe,günler bitmek bilmiyor,

Bunun için mi sevdin beni, artık sabrım tükeniyor.

Her gece düşlerimdesin,gözlerim yaş  döküyor.

Uzattım elimi şimdi,karanlığın eteğine tutunuyorum..

Yıllarca bekledim seni,günleri gecelere ekledim.

Gözden uzak olan,gönülden de uzak olur demedim.

Hani baştacın,iki gözün olmuştum,şimdi nerdesin? 

Uzattım elimi şimdi,karanlığın eteğine tutunuyorum..

Bıraksam Uçacağım Sonsuzluğa…! 

Sen beni sensizliğe mahkum etmek için sevmedin değil mi?', 'Sana öylesine ihtiyacım var ki bugün. Yokluğunda eriyip bittiğimi hissediyorum. Seni seviyorum deyip kayboldun karanlıkta. Uzattım elimi şim...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biraksam-ucacagim-sonsuzluga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de sevebilecek misin beni?', 'yine-de-sevebilecek-misin-beni-nazife-abayli-4zenu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Canım,

Koca Çınar’ım.

Gün gelipte kapımı çaldığında,

Gün gelipte telefonumu aradığında,

Ulaşılmazlarda der ise bir ses,

Bil ki son nefesimi vermiş,

Ruhum bedenimi terk etmiş,

Yaşama veda etmiş,

Kara toprağın altından sana gülümseyen,

Çürümüş bir kadın olacağım.

İşte sen o zaman,

Yağmur sonrası toprağın kokusunu severdi ama,

Kara toprağın altına girmeyi sevmezdi,

Hapsolduğunda nefes alamazdı,

Kefen de sıkar onu,açın diyeceksin..

Bil ki o zaman,

Börtü böceğe yem olmuş,

Bedeninde ne gözü,ne de yüreği kalmış,

Sadece kuru bir iskelet olacağım..

Açmak isteyeceksin toprağı,

Görmek isteyeceksin son bir kez,

Dokunmak isteyeceksin gecikmiş zamanlardan bedenime,

Ama bir torba kemik yığını zafer işereti ile selamlayacak seni,

O zaman da şimdi olduğu gibi,

Yine de sevebilecek misin beni?', 'Canım, Koca Çınar’ım. Gün gelipte kapımı çaldığında, Gün gelipte telefonumu aradığında, Ulaşılmazlarda der ise bir ses, Bil ki son nefesimi ...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yine-de-sevebilecek-misin-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Seni Seviyorum Ya!', 'simdi-seni-seviyorum-ya-nazife-abayli-ml9yl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir oku dediler bu gece bana.

Şairmişim,okuyacakmışım..

Nerde? 

Hiçbir şiirim yok ki ezberimde..

Ama seni sorsalardı bana..

Bülbül gibi nasıl da şakırdım onlara..

Örneğin; 

Bir tek senin telefon numaran var ezberimde.

Bir de kızımın,lazım olur diye..

Ha bu arada,

Ayakkabı numaran,

Gömlek bedenin,

Hatta iç çamaşır rengin.

Onları sorsalar,

Söylerdim bir çırpıda..

Bir tek senin saç rengin,

Göz rengin var aklımda.

Seviyorum ya seni….

Tutamam ki  diğerlerinin rengini aklımda.

Unuttum hepsini…

Diğerleri derken,

Eşlerimi,sevgililerimi…

Geçmişte yüreğimi verdiklerimi..

Unuttum dedim ya..

Şimdi sadece sen varsın aklımda..

Bir tek senin telefonun ezberimde.

Bir de sevgi dolu sözlerin..

İsteseler söylerdim bir çırpıda..

Şimdi seni seviyorum ya.!', 'Şiir oku dediler bu gece bana. Şairmişim,okuyacakmışım.. Nerde?  Hiçbir şiirim yok ki ezberimde.. Ama seni sorsalardı bana.. Bülbül gibi nas...', ARRAY['Türk Edebiyatı','Şiir','Nazife Abaylı']::text[], 8.5, '{"poet":"Nazife Abaylı","poet_slug":"nazife-abayli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/simdi-seni-seviyorum-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son bahar', 'son-bahar-goksel-akkaya-fkjxr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Camdan dışarı baktığımda 

Yollar bom boş nedense

Ama sorun değil 

Biliyorum aşıklar yine 

Deliler gibi gezdiklerini biliyorum 

Tek birşeye üzülüyorum 

Oda ağaçların yaprak gökmesine

Güllerin solmasına 

Bir çok güzellik 

Sonbahalla birlikte kayboluyor

Bu işin kütü yanı 

Ama doğanın kanunu 

Bunu biliyoruz

Her mevsimde yapılacak 

Bişi olduğunuda biliyoruz', 'Camdan dışarı baktığımda  Yollar bom boş nedense Ama sorun değil  Biliyorum aşıklar yine  Deliler gibi gezdiklerini biliyorum  Tek birşeye ü...', ARRAY['Türk Edebiyatı','Şiir','Göksel Akkaya']::text[], 8.5, '{"poet":"Göksel Akkaya","poet_slug":"goksel-akkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-bahar-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İdik', 'biz-i-dik-umut-gungor-9um8v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güneşle doğan,

Akşamla batan,

Sevgiyle coşan,

Kalpler biz idik.

Kızardık geceye,

Bölerdik heceye,

Söcükleri cümleye,

Sıralayan biz idik.

Dolunayla konuşan,

Yıldızlarla oynaşan,

Gökkuşağına karışan,

Şafakla doğan biz idik.

Bülbül ile dertleşen,

Turna ile söyleşen,

Dalga ile devleşen,

Akarsular biz idik.

Altaylara koşturan,

Tunayı''da coşturan,

Çin''e zehir kusturan,

Kürşat''larda biz idik.', 'Güneşle doğan, Akşamla batan, Sevgiyle coşan, Kalpler biz idik. Kızardık geceye, Bölerdik heceye, Söcükleri cümleye, Sıralayan biz idik. Dol...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-idik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızgınlığım Sana Değil', 'kizginligim-sana-degil-semra-sahin-wrkpd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seninle vedalaşmak kolaydı bitti demek

Kendimle vedalaşmayı beceremedim

Kızgınlığım sana değil

Sana kızmayı beceremeyen kendime

Bitirmek istiyorum başlarken bitirmek

Yorgun düştüm yaren...

Sen, ben...düşümdeki çocuk

Kız olursa özlem Yaren, erkek olursa Hasret Yaren

İsmi ne farkeder düşümden düştü,döşümden düştü çocuk

Çok isimli sen

İsmine alışamamışken ben..

Elimden tutmuş dünyayı kurtaracaktık

Elimden tutmuş eylemlerde coşacaktık

Sessizlerin sesi olacaktık

Sesimi çalan yar

Kızgınlığım sana değil sana kızmayı beceremeyen kendime

Ben aç, ben açıkta, ben yalnız bir o kadar edepsiz

Günah değildi aynaya bakarken seni görmek

Tanrı olmayı sevdirdiğim yar

Biricik kullarına hak dağıtırken sen

yasalarını kendimde yasakladığım diğer tanrılar kadar arsız

Bizim için devrimi unutturan sen

Günahkar hırsız

Kızgınlığım sana değil sana kızmayı beceremediğim kendime

Ben kurak toprak,

Ben bez bağlanan yalancı dilek ağacı

Dostunu çaldıran ben

Seni çalan ben

Sana kızmayı beceremezken yeni baştan diyecek kadar arsız

Yaşanan biri-bin bini-bir günlerin sıradanlaşan öyküsü

mecazen''beklemekti''sözlükteki ifadesi

Çok acımasız, amansız kararsız bu tüketen gel gitler

Telefonunu, gelişini, gidişini, karanlığı, sabahı

Günün tükenen ve tüketen dününü beklemekti bendeki katil

Ve ben hala beklemekte otobüs saatlerini hesaplarken

Sanki dün bugündü bugün dün

bir cinayet sahnesiydi tüylerimi ürperten

Seninle vedalaşmak kolaydı bitti demek

Kendimle vedalaşmayı beceremedim

Kızgınlığım Sana değil sana kızmayı beceremezken kendime

Hiç uyanmamayı beceremediğim rüyaydın belki

Senin kanıtın seninle yaşananlar değil

Yaşayamadıklarım olacak

Özümde sen, gözümde hasret, düşümde sensizlik

Ve koynumda sadece ellerim düne bağlı...sana bağlı

Avcılar da geçen otobüsleri seyrederken

Yıldızlar vardı seni bekleyen gözlerimde

Geç gelmiştin eve /hayatıma

Erken gittin sökeye /gidecektin ve bitecekti

Hırsız olarak girdiğin evde ben ahmakça otobüs bekliyorum

Kızgınlığım sana değil sana kızmayı beceremediğim kendime

Seninle vedalaşmak kolaydı 

Kendimle vedalaşmayı beceremedim

Hırsız olarak çıktığın evde ben ahmakça otobüs bekliyorum

Seni bekler gibi otobüs bekliyorum

Seni getirecekken giden ben

Kızgınlığım sana değil sana kızmayı beceremediğim kendime

04/08/2002

Gazi Mah.

(Başlarken Bitmişti/Bir Aşkın Anısına/9)', 'Seninle vedalaşmak kolaydı bitti demek Kendimle vedalaşmayı beceremedim Kızgınlığım sana değil Sana kızmayı beceremeyen kendime Bitirmek ist...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/kizginligim-sana-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış...', 'arayis-derin-deniz-jjv5o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güller içinde yakaladım

Teninin kokusunu ararken kendimi

Gülün adı vardı (karşımda)

Senin tadın(dilimde)

Bir uzaklığa hapsolmuş

Yaralı bir cerendir yüreğim

Ahh anlatılmaz bir gülün

Bat(a)  mayan dikeniyim...', 'Güller içinde yakaladım Teninin kokusunu ararken kendimi Gülün adı vardı (karşımda) Senin tadın(dilimde) Bir uzaklığa hapsolmuş Yaralı bir c...', ARRAY['Türk Edebiyatı','Şiir','Derin Deniz']::text[], 8.5, '{"poet":"Derin Deniz","poet_slug":"derin-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arayis-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü', 'oyku-oguzkan-bolukbasi-k7m7d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nasıl bilecektim

Bir vesile olmasaydı

Rüzgarın yoluna itmesi beni

Çılgınca eserken

Darmadağınık saçlarını  mı tutsaydı ellerin

Uçuşan eteklerini mi

Ya da yere düşen çantana mı uzanmalıydın

Ben oradaydım

İki el benden yaşamının rüzgarına sunulmuş

Çantanı kurtardım

Sen eteklerini

Saçların ikimiz arasında gidip geldiğinde

Kokunun bana yapacaklarını daha bilmiyordum

Gülümsedin

Teşekkürler dedin

Yardım etmek isterdim dediğimde

Vargısı belirsiz bir başlangıcın ucundaydım

İddiasız başlayan aşkların ne olduğunu bilmekle ilgili söylediklerim

Sıfırdan zirveye çıkması

Aklına gelmeyenlerin yüreğine düşmesi

Heyelan

Deprem

Sel

Fırtına

Ateşe yürümek bile bile

Safça

Ve çocukça

Sen ne güzelmişsin dediğimde

Hayretle baktığın andır

Yüreğimin savrulmaya başlaması

Hangi çıkar ilişkisiydi 

Beni sana bağlayan dediğimde de

Aynı bakışı atmıştın üzerime

Sen aşk nedir bilmiyorsun diyerek

Üzülerek

Billurunu elimde tutuğumda gözyaşının

Anladım ki

Budur tarifi zor olan

Sebepsiz ağlayan bir göz gördüğümde aşk gelir aklıma

Sende bıraktığım 

Sensin andığım dizelerde

Sensin yandığım gecelerde

Seni anlatmayan hecelerde

Ben de yokum', 'Nasıl bilecektim Bir vesile olmasaydı Rüzgarın yoluna itmesi beni Çılgınca eserken Darmadağınık saçlarını  mı tutsaydı ellerin Uçuşan etekle...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/oyku-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damlacık Olayım', 'damlacik-olayim-aynur-baydar-5a2g1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Su olayım, damlacık

Tıp diye tıplayayım

Gecekondunun teneke çatısına

Sonra tıpırdayayım kulaklarında

Zor hayatlarına renk vereyim

Çocuklar tempo tutsun notalarıma

Yağmayayım 

Korkutmadan geçip gideyim

Sokaktaki birikintiye katılayım

Kedi içsin beni şap şap

Susuzluğunu gidereyim

Küçük kızın kırmızı pabucuna düşeyim

Kızsın, bıraktığım lekeye

Silsin yumuşacık eliyle

Hınzırca güleyim

Koca adam ağlıyorsa sokakta

Gözyaşlarına eşlik edip, örteyim

Utanmasın, utanmazlardan

Şıp şıp düşeyim kabir topraklarına

Mezar taşlarındaki ünvanlara makamlara

Bakmaksızın eşitce…', 'Su olayım, damlacık Tıp diye tıplayayım Gecekondunun teneke çatısına Sonra tıpırdayayım kulaklarında Zor hayatlarına renk vereyim Çocuklar t...', ARRAY['Türk Edebiyatı','Şiir','Aynur Baydar']::text[], 8.5, '{"poet":"Aynur Baydar","poet_slug":"aynur-baydar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/damlacik-olayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaban', 'yaban-hasan-koca-2-uqj5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düştü bu,sakince ama şiddetli bir oyundu 

Yagmurumsu güzellikte ama haindi

Uçutma sevgisiydi bendeki çocukta

Yalındı bir o kadar, zalimse bile önceleri

Darmadagın olmuştum sevmekten 

Adalet yok aşkta bi daha gördüm

Kimi sevsem yalan ben özgürlüğümü seviyorum

Aşk tutsaklığın ta kendisi, biliyorum

Tutsaklık güzeldir sonbaharda

Ya ben bilmiyorum ya yaban bana

Ya yaban ya yabancı bana aşk! 

Uzaklardan bir yabancı sevmiştim 

öz yurdumda yaban kaldım, napalım..

yabancı ben oldum', 'Düştü bu,sakince ama şiddetli bir oyundu  Yagmurumsu güzellikte ama haindi Uçutma sevgisiydi bendeki çocukta Yalındı bir o kadar, zalimse bi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Koca 2']::text[], 8.5, '{"poet":"Hasan Koca 2","poet_slug":"hasan-koca-2","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yaban-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumbara', 'kumbara-cigdem-bir-genc-o7rqc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dalgalar çekildi...

deniz  dingin...

ve dakikalar  akıp gitmekte bir yerlere 

saat kulelerinden kaçıp kaçıp...

anlar kalıyor geride

yada anılar mı demeli bilmem

kumbaralara atılan bozuk paralar gibi birikiyor bir yerlerde  yüzyıllar

tarih...

insanlık...

aşklar... 

savaşlar...

hikaye başlar...

hikaye biter...

ne mutlu bir iz bırakıp göçene...', 'dalgalar çekildi... deniz  dingin... ve dakikalar  akıp gitmekte bir yerlere  saat kulelerinden kaçıp kaçıp... anlar kalıyor geride yada anı...', ARRAY['Türk Edebiyatı','Şiir','Çiğdem Bir Genç']::text[], 8.5, '{"poet":"Çiğdem Bir Genç","poet_slug":"cigdem-bir-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kumbara-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sokak Lambası', 'sokak-lambasi-husamettin-gunacti-00c0k', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gecelerin sonsuz yalnızlığını

bir sokak lambasıyla paylaştınız mı hiç? 

sokak lambası deyip geçmeyin.

sarhoşlar gece karanlığında,

ıssız sokaklarda

kiminle dertleşirler sanıyorsunuz.

güçlü gövdesine yaslanıp,

biraz soluklanmak için

her gece ona uğrarlar.

sonra da geçim sıkıntılarını,

karılarının dırdırlarını,

âmirlerinin kaprislerini,

karşılıksız aşklarının ve

karşılıksız çeklerinin

hesaplarını ondan sorar,

hesap sormakla kalmayıp

ağıza alınmayacak küfürler ederler.

zavallı sokak lambası

bir, gece boyu

başında dönen pervanelere,

bir de ayağının dibinde dönen

sarhoşlara bakıp

umutsuzca başını sallar.

bu sırada güler mi,

ağlar mı,

yoksa kızar mı

bana sormayın,ben bilemem.

bildiğim tek şey var o da; 

onca gürültü ve hakarete rağmen,

sabırla davetsiz misafirlerini dinlediğidir.

tek taraflı sohbetlerinin sonunda

içlerindeki her şeyi

ayağının dibine dökseler bile...

hüsamettin GÜNAÇTI', 'gecelerin sonsuz yalnızlığını bir sokak lambasıyla paylaştınız mı hiç?  sokak lambası deyip geçmeyin. sarhoşlar gece karanlığında, ıssız sok...', ARRAY['Türk Edebiyatı','Şiir','Hüsamettin Günaçtı']::text[], 8.5, '{"poet":"Hüsamettin Günaçtı","poet_slug":"husamettin-gunacti","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sokak-lambasi-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir(ey) in Yalnızlığı', 'bir-ey-in-yalnizligi-tulay-sustam-x8654', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'önüne bir sıfır koysam

değerin düşer..

yanına bir sıfır koysam

değerin artar...

''bir'' tek başına hiçbir şeysin...

sıfır mıdır? 

biri değerli kılan... 

yoksa bir midir? 

sıfırın değerini artıran...

önüme seni katarım

beni arkanda unutursun

yanıma seni katarım

beni ayakta uyutursun

''birey'' tek başına hiçbir şeysin...

sen misin? 

beni değerli yapan...

yoksa ben miyim? 

senin değerini artıran...

anladım ki..

ne sıfırın ''bir''siz, ne de bir''in sıfırsız değeri var

ne benim sensiz, ne de senin bensiz değerin var... 

''ne seninle, ne de sensiz olmuyor işte...''

bir(ey) in yalnızlığıyla yaşıyorum...', 'önüne bir sıfır koysam değerin düşer.. yanına bir sıfır koysam değerin artar... ''bir'' tek başına hiçbir şeysin... sıfır mıdır?  biri değerli...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-ey-in-yalnizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ve Ölüm', 'sen-ve-olum-erdogan-ergin-lzoob', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '''Ağabeyim Mahir Ergin''in ardından, onu anmak adına

Bir olduğundaydı, yıllar önce

Beklenmedik bir selamlaşma,

İkimiz bir yatağın önünde

İkincisi, olduğunda köyümüzde

Veda, zor gelmişti yüreğime

Aradan, yıllar geçmişti belki

Seni alıp gittiğinde Azrail

Verilen görevi yapmasaydın, 

Diyesi geliyor insanın

Ne zor oluyormuş, gittğinde sevgili

Yüzyıllar var ki, aynı görev

Çamurdan yapılmış evler

Sırası gelince yıkılıyor, birer birer

Sevgiliyi aldınya, gitti en sevdiğim değer

Ne çok anlattılar seni,

Limandan kalktı Sessiz Gemi

Bekleşenlerin arasında ben varken,

Sen yolcusuyken,

Göremedim, sallayamadım elimi', '''Ağabeyim Mahir Ergin''in ardından, onu anmak adına Bir olduğundaydı, yıllar önce Beklenmedik bir selamlaşma, İkimiz bir yatağın önünde İkinc...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-ve-olum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlarken Bitmişti', 'baslarken-bitmisti-semra-sahin-0hcbu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben sadece oniki yaşımda kaybettim benden bir parçayı

Ve ben şimdide oniki yaşımdayım

Oniki kere oniki yaş yaşamışken

Çok yaralı zamanlar atlattık

Gözyaşları yaren oldu

Yaren hayal

Hayal umutsuzluk

Yazıda emanet duruyor söz anlamını yitirmişken

Tıpkı yaprağın üstünde duran titrek çiy tanesi gibi

Anlatmayı milyonlarca yaşanmışlığı 

Bir hamal küfesinde taşırken titriyor

Ha düştü ha düşecek

Titrek çiğ tanesi/hammal küfesi

Karalı bir hayattan kareli bir sayfaya

Bir cenazem vardı yerde duran

Oniki yaşımda babaannemi kaybettiğimde.

Çocuk aklıydı inanmamayı seçmek

Şimdi yine o çocuk bir şeyin yitikliği başında gözyaşı döküyor

En çok o çocuktu kırılan

Hiç bu kadar yüreği titrememişti

Bir oniki yaşında ağlamıştı

Elinden sıyrılana düşünden düşene

bir de şimdi

O hala oniki yaşında oniki kere oniki yaş yaşamışken...

04/08/2002

Gazi Mah.

(Başlarken...Bitmişti/Bir Aşkın Anısına/1)', 'Ben sadece oniki yaşımda kaybettim benden bir parçayı Ve ben şimdide oniki yaşımdayım Oniki kere oniki yaş yaşamışken Çok yaralı zamanlar at...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/baslarken-bitmisti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, Seni Sevdiğimi Kaybettim', 'ben-seni-sevdigimi-kaybettim-cafer-yilmaz-tvaon', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben, seni sevdiğimi kaybettim.

O, sis kokan ilkbahar sabahlarının

beni sana iten rüzgarlarını...

Minik pastanede içtiğimiz çayın,

sen olan tadını kaybettim.

O çay için kaç dersi astım üstelik...

Ben, seni sevdiğimi kaybettim.

Soğuk kış akşamlarında

fakültenin önüne koşup

bank kapma savaşını kaybettim.

Üşüdüğümüzde arka kapılardan sessizce girip,

hırsız gibi fakülteye,

kalorifer peteklerinin sıcaklığını,

senin sıcaklığını kaybettim.

Ben, o bitmesini hiç istemediğim

şehrin gecelerini de kaybettim.

Ben, seni sevdiğimi kaybettim.

telefon açmak için sana

uğruna savurduğum yalanlarımı kaybettim.

Kavga ettiğimiz günlerde,

barışmak için

sayfalar dolusu sana yazdığım af mektuplarını

barışık olduğumuz günlerde,

gittiğimiz o koruluğun yeşil yapraklarını kaybettim.

Ben, seni sevdiğimi kaybettim.

Ayrı geçen yaz günlerinde

nefes nefes sen diye çektiğim

sigaranın dumanını,

yaprakların bile sarardığı Eylül ayında

herşeyi yemyeşil gördüğüm gözlerimi kaybettim.

Okullar açılırdı,

ve insanlar gelirdi şehre binlerce...

ben seni beklerken terminal saatlerimde,

seni sevdiğimi,

kalabalıkta seni kaybettim.

Ben, seni sevdiğimi kaybettim.

                              

                                     Ocak 1998', 'Ben, seni sevdiğimi kaybettim. O, sis kokan ilkbahar sabahlarının beni sana iten rüzgarlarını... Minik pastanede içtiğimiz çayın, sen olan t...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yılmaz']::text[], 8.5, '{"poet":"Cafer Yılmaz","poet_slug":"cafer-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/ben-seni-sevdigimi-kaybettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak İsterdim', 'yasamak-i-sterdim-semra-sahin-ymn0v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok mu konuştum dercesine 

Çok mu yazdım diyorum yine kendime

Evet çok yazmıştım yine konuşurcasına

Oysa ben konuşmak ve yazmak yerine

Delice yaşamak isterdim seninle

Şimdiyse sensizliğe yaslanıp

Ne yaşıyorum, ne konuşuyorum, ne de yazıyorum

04/08/2002

Gazi Mah.

(Başlarken... Bitmişti/Bir Aşkın Anısına/10)', 'Çok mu konuştum dercesine  Çok mu yazdım diyorum yine kendime Evet çok yazmıştım yine konuşurcasına Oysa ben konuşmak ve yazmak yerine Delic...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yasamak-isterdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-ahmet-hani-22qs3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanar şem''in kenarında yanar pervaneler gördüm

Sörüşdüm yanmağın sırrın eşiddim ha! neler gördüm.

Qerarın kuçesin birde seherden axşama gezdim

Dönüb her yane ki baxdım uçuq meyxaneler gördüm.

Soyuq yel canıme düşdü saraldı qırmızı rengim

Sınıq insan kenarında sınıq peymaneler gördüm.

Uca sesle seni birden ürekden sesledim çünkü

Gezirler sen gezen yerde yene biganeler gördüm.

Yene Mecnun''la Leyla''dan yazarken ağlayırdım ey

Nağılarda çöle düşmüş deli divaneler gördüm.

Deyirler yazma day besdi şerar-i hicriden '' Hani''

Elinden bu belanın men ne çox viraneler gördüm.

1993', 'Yanar şem''in kenarında yanar pervaneler gördüm Sörüşdüm yanmağın sırrın eşiddim ha! neler gördüm. Qerarın kuçesin birde seherden axşama gezd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gordum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnce Hastalıktı Benimki', 'i-nce-hastalikti-benimki-semra-sahin-d8mtn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnce hastalıktı benimki inciten seni

Oysa medet umdu sensizlikten

Benim için hastalık diye tarif ediyordum seni

Bilemezdin ki sensizliğin beni yataklara düşürdüğünü

Batarken o yatak bana

Sen ki yazabilsen aşkın sevdanın kitabını yazardın

Formüllerle yaşayın diyerek

Yaşamıştın okur gibi derin sevdaları

Yaralıydın biliyorum

Çırpınışında yoktum ama bak eriyorum ve sen varsın

İlacım reçetem doktorum

Bak iğneli yatak

Ne gece gece, ne gündüz gün dolu

Ben ki senin koynunda uyanmayı tatmışken

Nasıl sensiz uyanmalara sarılayım ki

Doktorum...

Belki aşk acısıydı sana bu dalı seçmende ön ayak

Bak içim titriyor..nefes alamıyorum

İlerledi bu illet

Bizi soruyor, kırılıyor, kızıyor kızdırıyor...

Belki de ameliyat masanda bir hastanı kaybettin

Belki de suçluydun

İlacım...

Bak aman diyorum

Yüreğim kağıt gibi

Bende suçlu olmak istemiyorum

Yaşadın hastalığın incesini

Biliyorum benimki de ince hastalıktı inciten seni

Sensizlikti onu büyüten

O derinleşti yedi kat yerin dibine girdi

Derinleştikçe sessizleşti

Sessizleştikçe ne tuhaftır ki

''Medet umdu sensizlikten''

04/08/2002

Gazi Mah.

(Başlarken...Bitmişti/Bir Aşkın Anısına/4)', 'İnce hastalıktı benimki inciten seni Oysa medet umdu sensizlikten Benim için hastalık diye tarif ediyordum seni Bilemezdin ki sensizliğin be...', ARRAY['Türk Edebiyatı','Şiir','Semra Şahin']::text[], 8.5, '{"poet":"Semra Şahin","poet_slug":"semra-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ince-hastalikti-benimki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyler bu can', 'neyler-bu-can-i-lhami-arslantas-ligne', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dost ben beni sende buldum,

Sensen ırak neyler bu can.

Niyaz edip hayran oldum,

Senden ırak neyler bu can.

Varlığım yokluğum bildin,

Açlığım tokluğum bildin,

Azlılığım çokluğum bildin,

Senden ırak neyler bu can.

Hissettim her an yanımda,

Yüreğin gezdi yanımda,

Canın sanki bu canımda,

Senden ırak neyler bu can.

İlhami''yim dosta kurban, 

Olam giyindiğin urban,

Dolsun dağarcığın, torban,

Senden ırak neyler bu can.', 'Dost ben beni sende buldum, Sensen ırak neyler bu can. Niyaz edip hayran oldum, Senden ırak neyler bu can. Varlığım yokluğum bildin, Açlığım...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neyler-bu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlara Badal....', 'yildizlara-badal-fatih-taskin-adg1s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ekmek arası bir aşk tadı 

...........oldum dudaklarında

Vuslat güneşi gibi

Yanaklarında doğup; 

Hüzün akşamlarında battım.....

Karanlık girdaplarda kayboldum.

İç içe geçmiş hesaplaşmalarım 

Vardı benim......

Geleceğe dair olmayan umutlar; 

Ve....

Yitirdiğim,ulaşamadığım davalar....

Artık yoruldum

Bıktım....

Acımaktan...kanamaktan.....

.......ben gidiyorum.......

Kavuşamadığım umutlarımı,

Sisler ardındaki sevdalarımı,

Çile çektiğim aşklarımı,

Hep beni acıtan sırlarımı,

Kanayan gözyaşları akıtmadan,

Ardıma birkez daha bakmadan; 

Cami avlusuna piç bırakırcasına

Terk edip; 

.......gidiyorum................

.................gidiyorum.............

Yıldızlara  badal vurmaya gidiyorum....

Siyah Bereli...

ekim 2004..', 'Ekmek arası bir aşk tadı  ...........oldum dudaklarında Vuslat güneşi gibi Yanaklarında doğup;  Hüzün akşamlarında battım..... Karanlık gird...', ARRAY['Türk Edebiyatı','Şiir','Fatih Taşkın']::text[], 8.5, '{"poet":"Fatih Taşkın","poet_slug":"fatih-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/yildizlara-badal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizlenmiş Çakılın Zaferi', 'gizlenmis-cakilin-zaferi-erol-dal-guxch', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ulu Orta Dibek gözlü bir koyun geçti buradan.

Gizlendi.

Gizlendiği sanki Giz di

Çakıl taşlarını takip et yabancı.

Evi bulacaksın.

Orda mı sahi kocaman pasta? 

...

Çakıl taşları gizlendi.

Orman ıssızdı.

Giz, aniden belirdi.

Mısralar, mısralardan izlendi.

Çakıl taşının zaferi 

Kirlendi.', 'Ulu Orta Dibek gözlü bir koyun geçti buradan. Gizlendi. Gizlendiği sanki Giz di Çakıl taşlarını takip et yabancı. Evi bulacaksın. Orda mı sa...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gizlenmis-cakilin-zaferi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık limanı', 'yanlizlik-limani-ercan-urcar-0fup0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu limandan hep yanlızlıklar kalkar,

Alırgötürür bizi hayaller ülkesine,

Dolu dolu yaşarız hayallerimizi bir  anlıkta olsa,

Taki uyanıncaya kadar hayallerden düşlerden,

Bu liman yanlızlıklar  limanı,

Yasak sevdaların yanlış tohumları gibi,

Hep yanlızlıklar  hep kederler kalkar bu limanda,

Açılır okyanuslara gönüllerdeki kaderli sevdalar,

Düşer akıllara sevdalar yaşar anılarla,

Hiç tükenmek bilmez hayaller burada,

Bitmek bilmeyen ihanenetlerle,

Sorgular her  zaman en güzel yerinde,

Yakarlar gözlerinde loş ışıkları,

Suçluymuş gibi davranırlar kendilerine,

İşte yanlızlığı kaldırırlar  o an gemileriyle,

Bu yanlızlık limanından okyanusa,

Onlara yasaktır  sevdalar aşklar,

Sokaklarda elele gezmek,

Kanun suçudur sevdalar onlara,

İhanete açıktır kapılar bu sevda limanında,

Aşık olmak kelepçe  takmaktır,

İhanet yanlızlık limanına çıkmaktır,

Belki kederlerini okyanusa bırakmaktır,

İşte  bu yanlızlık limanında.

ERCAN URÇAR', 'Bu limandan hep yanlızlıklar kalkar, Alırgötürür bizi hayaller ülkesine, Dolu dolu yaşarız hayallerimizi bir  anlıkta olsa, Taki uyanıncaya ...', ARRAY['Türk Edebiyatı','Şiir','Ercan Urçar']::text[], 8.5, '{"poet":"Ercan Urçar","poet_slug":"ercan-urcar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yanlizlik-limani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu Görmeyince...', 'onu-gormeyince-hasan-can-uftzf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ayrılığın acısını anlatmak,

Bir dakika sürmez.

Aşkı anlatmaksa,

Kelimelere sığmaz.

Uzun bir yoldur aşk,

Yürüdükçe yorulursun.

Biraz kederlidir aşk,

Hüzünde durulursun.

Günler geçer sevgili gelmez,

Acılar artar dermanı olmaz.

Görmeyince sevgiliyi yüzün gülmez,

Canını sıkar hayat onsuz olmaz...', 'Ayrılığın acısını anlatmak, Bir dakika sürmez. Aşkı anlatmaksa, Kelimelere sığmaz. Uzun bir yoldur aşk, Yürüdükçe yorulursun. Biraz kederlid...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/onu-gormeyince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-i-hsan-dinibutun-d5h5d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gün giderim demiştin,

gittin..! 

bir demet hüzün kaldı senden

bir de yara yüreğimde

nefes aldıkça yakan

nefes aldıkça kanayan bir yara

bir gün giderim demiştin,

gittin..!', 'bir gün giderim demiştin, gittin..!  bir demet hüzün kaldı senden bir de yara yüreğimde nefes aldıkça yakan nefes aldıkça kanayan bir yara b...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yara-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haraya', 'haraya-ahmet-hani-azv40', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Men aşığam yaraya

XanÇobanam Saraya.

Kardı Beşer çağırma

Gelmeyecek haraya.', 'Men aşığam yaraya XanÇobanam Saraya. Kardı Beşer çağırma Gelmeyecek haraya....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/haraya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabus', 'kabus-i-hsan-dinibutun-03dkj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gözlerinde korkular

yüreğinde fırtınalar

ruhundaki yangınlar

bil ki o benim

gece sessiz telefonlar

uykundaki kabuslar

arkandaki adımlar

bil ki o benim

uykuların kaçacak

çok acı çekeceksin

kulakların çınlayacak

beni hissedeceksin', 'gözlerinde korkular yüreğinde fırtınalar ruhundaki yangınlar bil ki o benim gece sessiz telefonlar uykundaki kabuslar arkandaki adımlar bil ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kabus-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayacaksın', 'aglayacaksin-i-hsan-dinibutun-bfgro', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'seni nasıl sevdiğimi

bir gün anlayacaksın

sende benim gibi sızlayacaksın

pişman olup beni arayacaksın

bulmayacaksın beni

ağlayacaksın', 'seni nasıl sevdiğimi bir gün anlayacaksın sende benim gibi sızlayacaksın pişman olup beni arayacaksın bulmayacaksın beni ağlayacaksın...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aglayacaksin-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanarım', 'yanarim-i-hsan-dinibutun-7r9pp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben gönlümü bir çocuğa vermişim

beyhude bade şerbet içmişim

sen bu yolda gider iken dönmüşüm

çile nedir? sevda nedir? çekmişim

çekmişim gülüm

ben aşk''ımdan yola düştüm yanarım

sevdam için dağlar taşlar aşarım

ben bu aşk''ı yere göğe yazarım

yarim gelmez söz dinlemez yanarım

yanarım gülüm', 'ben gönlümü bir çocuğa vermişim beyhude bade şerbet içmişim sen bu yolda gider iken dönmüşüm çile nedir? sevda nedir? çekmişim çekmişim gülü...', ARRAY['Türk Edebiyatı','Şiir','İhsan Dinibütün']::text[], 8.5, '{"poet":"İhsan Dinibütün","poet_slug":"i-hsan-dinibutun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yanarim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kafer!', 'kafer-ahmet-hani-ncr7b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül iyi bahar iyi

ne xoş olar nar iyi.

Hani öldü yumayın

Canı tütb yar iyi.

................................Note:İyi kokusu anlamındadır.', 'Gül iyi bahar iyi ne xoş olar nar iyi. Hani öldü yumayın Canı tütb yar iyi. ................................Note:İyi kokusu anlamındadır....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kafer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sukût', 'suk-t-fatih-ozkonyali-mug1f', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çölde sudur, kendini bilene göldür sukût,

Gönül bahçemde açan nadide güldür sukût.

Sonsuz sermaye câna, canana giden yöndür,

Sözleri paydos ettir, heceleri bir bir söndür.

Sabrın dile buyruğu hükmü niyazı sukût,

Aklın sardığı yumak, ömrün feyyazı sukût.

Boş sözle eğleşenin nihayetidir figan,

Hesap tutulmaz, hele nefse uyarsa o an.

Görmedim hiç eşini hüsnü tutumdur sukut,

Arlı dünya meskenim, sırlı kutumdur sukut.

                 12/10/2004', 'Çölde sudur, kendini bilene göldür sukût, Gönül bahçemde açan nadide güldür sukût. Sonsuz sermaye câna, canana giden yöndür, Sözleri paydos ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özkonyalı']::text[], 8.5, '{"poet":"Fatih Özkonyalı","poet_slug":"fatih-ozkonyali","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sukut-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Şimdi*', 'simdi-kubilay-enginol-6hv72', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi, seninle sahilde olmak vardı

Kayaların üzerinde.

Ayaklarımız çıplak, suda

Sıcaklıklar gözlerimizde

Sen, ben, gökyüzü,deniz

Birbirimize hikayeler anlatsaydık

Kibritimizin bitmesine aldırmadan

Sigarayı sigaraya yıldızı yıldıza ekleseydik

Türkülerden kayıklar yapıp

Salıverseydik denize

Sen oluverseydin şimdi yanımda

Islanmışım, ağlamışım kimin umurunda...', 'Şimdi, seninle sahilde olmak vardı Kayaların üzerinde. Ayaklarımız çıplak, suda Sıcaklıklar gözlerimizde Sen, ben, gökyüzü,deniz Birbirimize...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apışıp Kalacaksın', 'apisip-kalacaksin-i-lyas-ozmen-lxcrf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi hoş kokulu bir gülsün amma

Hazanın yakındır solacaksın sen

Seçtiğin yolların bir bir muamma

Çıkınca apışıp kalacaksın sen

Seni kahredecek olmayan sabah

Boyunu geçecek ettiğin günah

Servetin pişmanlık sermayen eyvah

Olunca apışıp kalacaksın sen

Duyanlar gülecek düştüğün hale

Tüm gizli sırların düşecek dile

Sonunda ben gibi kucağın çile

Dolunca apışıp kalacaksın sen

Geriye tepince gurur silahın

Gökleri yırtacak feryadın ahın

Sonunda kendini ortada şaşkın

Bulunca apışıp kalacaksın sen

Bugün çağıranlar seni gel diye

Yarın dert vercek sana hediye

Ortada kalıpta adın kötüye

Düşünce apışıp kalacaksın sen

Edene elbette eden bulunur

Geriye dönersin heryanın çamur

Beni sordukların sizlere ömür 

Deyince apışıp kalacaksın sen', 'Şimdi hoş kokulu bir gülsün amma Hazanın yakındır solacaksın sen Seçtiğin yolların bir bir muamma Çıkınca apışıp kalacaksın sen Seni kahrede...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/apisip-kalacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-umut-karakas-eji2z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni ne çok sevdim ben. Ne çok gözyaşı döktüm senin için. Geceleri sen yatağında meleklerin kanatlarıyla uçarken ben penceremin önünde senin rüyana girmek için dua ederdim. Bir bakışına, bir dudak kıvrımında titreşen gülüşüne ulaşmak için dünyanın bütün çiçeklerini önüne sererdim. 

Şiirler, şarkılar, sevgiler içimde tutuşan bir ateş, onun yangınında senin için kül kesildim. Ağır hastalar geceyi zor geçirir. Sabahı bekler kırgın yürekler, hasta umutlar, yalnız ruhlar. Yalnızdı gecelerim. Hastaydı gecelerim. Kan kaybından giden bir yaralı gibi umarsızdı gecelerim. Bir uçurumun kenarına beni taşıyan karabasandı gecelerim. Adına yalnızlık dedim. Sensizlik dedim.. Sen beni bilmedin, beni tanımadın, beni sevmedin.. Bu bir ölümdü, bu bir fermandı.. Bıçak kesmez artık beni, ip asmaz, çeküller yüreğimi taşımaz. Yaşamak mümkün değil, yalnızlık karanlık kapılarıyla üstüme kapandı. Amansız acılar içindeyim. 

Ey Sevdiğim.. Ben seni ne çok sevdim. Dünya bildi, bir sen bilmedin. Yalnızlığın diğer adı aşka karşılık almamaktır. Kaçılamayacak kadar yakın, tutulamayacak kadar uzak bir yerdesin.. Benim aşkıma yalnızlık kucak açtı. Senin yokluğuna dokundum, içim yandı. Odamın çıldırtan sessizliğinde sana seslendim. Yankısı döndü dolaştı, senin kapıların bana kapalı. Kendi sesim yine bana ulaştı.seni seviyorum.', 'Seni ne çok sevdim ben. Ne çok gözyaşı döktüm senin için. Geceleri sen yatağında meleklerin kanatlarıyla uçarken ben penceremin önünde senin...', ARRAY['Türk Edebiyatı','Şiir','Umut Karakaş']::text[], 8.5, '{"poet":"Umut Karakaş","poet_slug":"umut-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/seni-seviyorum-212-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-umut-karakas-4tg13', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YALNIZLIĞIN KARANLIĞI

Yalnızsın şimdi karanlığın gölgesinde ruhundaki sessizliği dinliyorsun seni bekleyen sonu görüyorsun aynada yalnızca senin sonun. seni bekleyen şeye bakıyorsun aralıksız, gözlerinde parlıyor yaşamın sınırında sana sunulan ölüm. kendi ormanında yavaş adımlar atıyorsun dolunaylı bir gecede, yalnızca sen varsın,karanlık ağaçların arasından süzülüyorsun, bir gölge gibi seni takip ediyor ruhun, karanlığın derinliğinden gelen sesleri duyuyorsun. Öyle bir ses ki bu tüm vücudun titriyor yerden kesilircesine, belli etmek istemiyorsun korkunu, kaçmaya başlıyorsun yavaşça, koşmak istemiyorsun artık, yüzleşmeyi geciktirircesine yürüyorsun sinsice, kusmaya başlıyorsun içindeki her karanlığı,seni aydınlıktan uzak tutan karanlığı boşaltıyorsun korkunu düşünceni içindeki tüm pisliğini atıyorsun, burası senin ormanın, senin çıkmazın, asla kaçamadığın boşluğun, senin karanlığın burası gerçek özgürlüğün tüm sırların burada. Kendi çöplüğündesin şimdi, çıkar içindekileri. buraya, seviyorsun, bir o kadarda korkuyorsun. kendinle yüzleştiğin yer burası her şeyin bu ormanda gizli, kimsenin bilmediği kaçmaya çalıştığın günahların burada gizli, asla kaçamıyorsun bu ormandan nereye gidersen git seninle gelecektir kendi karanlık ormanın, karanlığın aklının bir köşesine tamamiyle yerleşmiş bir şekilde zamanla seni sorgulamaya ve yüzleşmeye çağıracak. Buraya alışman zaman alacak, önceleri korkacaksın kendinden, içindeki pisliklerden, yalnız kendi ruhunla olduğun ormandan bile gizlemek isteyeceksin önceleri ama içinde biriken pislik biriktikçe dayanılmaz olmaya başlayacak senin için yaşam, hiçbirşey sana güzel görünmemeye başlayacak artık.kaçmaya başladığın zaman kendinden, acı çekmek hayatının bir parçası olduğu zaman, kendinle kalacaksın zamanla.işte burada kaçınılmaz ormanına girmek istersin çünkü onu yaratan sensin aklının biryerinde kendince düzenlenmiş ormanındır orası.Orası senin yaşam kaynağın, arınma yerindir. kendi günahlarını gördüğün temizlendiğin yer bu orman, senin aynaya her bakışında gördüğün iç yüzün, tek sığınağın, kendi karanlığın, buradan kaçamazsın! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! 

umut''espoir''', 'YALNIZLIĞIN KARANLIĞI Yalnızsın şimdi karanlığın gölgesinde ruhundaki sessizliği dinliyorsun seni bekleyen sonu görüyorsun aynada yalnızca s...', ARRAY['Türk Edebiyatı','Şiir','Umut Karakaş']::text[], 8.5, '{"poet":"Umut Karakaş","poet_slug":"umut-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/yalnizlik-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Sevdam', 'benim-sevdam-i-lhami-arslantas-5jat7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'değil Ayşe''nin endamı

değil gözlerindeki güzellik 

bu sevda başka güzele

bu sevda başka sevda

aç karnına

tok teselli verecek

zamanım yok hiç

ne de avutulmaya tahammülüm

bir kurtuluş özlemidir bu sevda

ve de özgürlük

demedim varımı yok

yokumu var

ne de başka bir sevda düşündüm aç aç

hep ona söyledim türkülerimi

onsuzluğun özlemini duydum yüreğimde

yatağımda

işimde 

soframda

hep onun hayaliyle yaşadım

kurtuluştur özlemim

kurtuluştur hasretim

özgürlüğün kollarında

ölebilmektir benim sevdam

                                                     1999', 'değil Ayşe''nin endamı değil gözlerindeki güzellik  bu sevda başka güzele bu sevda başka sevda aç karnına tok teselli verecek zamanım yok hiç...', ARRAY['Türk Edebiyatı','Şiir','İlhami Arslantaş']::text[], 8.5, '{"poet":"İlhami Arslantaş","poet_slug":"i-lhami-arslantas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/benim-sevdam-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Paspartu', 'paspartu-ahmet-aksoy-3mcuy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yılanlar dolanırken uzuvlarımıza salyangoz

hüzne yenilmiş aslanlar gibi titrek

''merhamet ceylanlar ölmesin demek''

biz ki bir vejeteryan kadar aziz

biz ki bir keşiş kadar sessiz

geçtik binlerce savaştan ürkek

dört yana gerilmek aslında çarmıhta

.................bir kasnak demek

iyiler de ölür evet!', 'yılanlar dolanırken uzuvlarımıza salyangoz hüzne yenilmiş aslanlar gibi titrek ''merhamet ceylanlar ölmesin demek'' biz ki bir vejeteryan kada...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Aksoy']::text[], 8.5, '{"poet":"Ahmet Aksoy","poet_slug":"ahmet-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/paspartu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyleyim', 'neyleyim-selvi-celik-4e9ly', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genclik gitmis,

ömür neyleyim seni.

Gönül viran olmus,

Bahar neyleyim seni.

Asklarim ölmüs,

Hülyalar neyleyim sizi.

Dostluklar coktan bitmis.

Neyleyim...

Dünya seni neyleyim.', 'Genclik gitmis, ömür neyleyim seni. Gönül viran olmus, Bahar neyleyim seni. Asklarim ölmüs, Hülyalar neyleyim sizi. Dostluklar coktan bitmis...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neyleyim-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gösterendir', 'gun-gosterendir-serif-erginbay-bprsd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırılgandır gün

ışık gergin.

Bir yaydır usulcacık

kanatır, kanatır, kanatır

çalgısını yüreğin.

Gün gösterendir

hain aynasında yitikleri.

Ve taşır durur kederi

bir bedenin ıssız değirmenine.

Gergin ışık:

artık gecedir

eksik gündüz

dönüşsüz yolları aydınlatır hep

taşınır devrimcinin gizli cebinde.', 'Kırılgandır gün ışık gergin. Bir yaydır usulcacık kanatır, kanatır, kanatır çalgısını yüreğin. Gün gösterendir hain aynasında yitikleri. Ve ...', ARRAY['Türk Edebiyatı','Şiir','Şerif Erginbay']::text[], 8.5, '{"poet":"Şerif Erginbay","poet_slug":"serif-erginbay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gun-gosterendir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apışıp Kalacaksın-II-', 'apisip-kalacaksin-ii-i-lyas-ozmen-9r9xv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen sıkı dur güzelim

Bak gör neler olacak

Bana ettiklerini

Dünya alem duyacak

Gazeteler olayı 

İlk sayfada yazacak

Üç beş satırla değil

Manşetten duyuracak

                         O zaman yaptığına

                          Bin pişman olacaksın

                          Eserini görünce 

                          Apışıp kalacaksın

Alt köşede küçücük

Fotoğrafın olacak

Duygusuz gözlerini

Siyah bant kapatacak

Televizyon haberi

Son dakika verecek

Adını duyan herkes

Merhametsiz diyecek

                          Bütün bu olanlara

                          Sebep sen olacaksın

                          Eserine bakınca

                          Apışıp kalacaksın

Haberi duyduğunda

Ağzın açık kalacak

Taştan farksız kalbini

Bin pişmanlık saracak

Bu sondan hiç kaçış yok

Yakında yaşanacak

Hakikatlar yüzüne 

Tokat gibi çarpacak

                      Büyük küçük herkesten

                      İntizar alacaksın

                      Eserine bakınca 

                      Apışıp kalacaksın', 'Sen sıkı dur güzelim Bak gör neler olacak Bana ettiklerini Dünya alem duyacak Gazeteler olayı  İlk sayfada yazacak Üç beş satırla değil Manş...', ARRAY['Türk Edebiyatı','Şiir','İlyas Özmen']::text[], 8.5, '{"poet":"İlyas Özmen","poet_slug":"i-lyas-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/apisip-kalacaksin-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyan Masallar (öykü-şiir-masal)', 'uyan-masallar-oyku-siir-masal-serif-erginbay-i8u9u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '“Seni özleyeceğim..! ”

“Özleme soluksuz kalırsın..” dedi kadın.

Kadının, bakışlarını uzaklarda, denizin üstünden dağların gökyüzüyle buluştuğu çizgide gezdirişini izledi uzun süre adam. Güzel iri gözlerinin derinlerinden gelen sorgulayan umutsuz boşluğa seslendi:

“Ben masalımızı istiyorum.”

“Bu masal seni uyutmaz... Uyanışımızın masalı olur ancak. Uyanman kötü. Cinleri lambadan çıkartmaya zorlama. Uyumalısın sen.! ”

“Saçlarının, kırmızı güllerinin kokusu böyle büyürken bende, nasıl uyuyabilirim? ”

“Göğsümde uyu. Anne kollarımın sıcağında. Masalımız tümüyle tozpembe değil, devler var, haramiler var.. Hepsiyle başa çıkamazsın..”

“Sen yanımda ol..”

“Söz veremem. Biliyorsun yarınsız geldim sana. Şimdiki an’da karşılaştık seninle.” dedi kadın.

“Ellerimiz ve dudaklarımız suç ortağı bu masalın. Eğer korkarsak bu masalı kimler okuyacak. Masalımızdan sorumluyuz biz. Kaçamayız, bu masal kendini yazdırtacak tohumları ekti ruhumuza çoktan.”

Kadın:

“Yaşanmamışlıkların örselediği yüreğinin sarhoşluğu bu. Özgürlüğünle sarhoşsun, yenik düşüyorsun. Ben kabuk bağlamış yaralarımla geldim, senin açık yaralarını sarmaya. Yarın kanamaktan korkuyorum.”

“Eteklerimizde taşlar ve ruhumuzda yaralar var, böyle karşılaştık biz.”

“Taşlarımızı ayaklarımıza düşürmeden, kanamadan geçebilir miyiz bu masalın içinden. Kimseler incinmeden? ”

“Herkesin, her şeyin avukatı var, ama aşkın yok..! ” dedi adam.

Kadın:

“Olması gerekenle, bizim istediklerimiz arasında uçurum olmamalı.”

“Değerlerimiz var, gençlik yıllarımızdan süzülüp gelen.. Onlar hem gündüzümüze hem de gecemize dahil.” dedi adam.

“Seni özleyeceğim..! ”

“Özleme soluksuz kalırsın..” dedi kadın.

“Yanlışlara da ihtiyacım var.. Ama sığda yaşanacak şeyler değil. Derinlerde soluksuz kalabileceğim yanlışlıklar istiyorum ben.” dedi adam.

Kadın:

“Ya beni sığların ışıltılı renkleri kendine çekerse.. Soluğum yetmezse o kadar çok diplerde kalmaya.. Belleğimi acıtırsa kabuk bağlamış yaralarım.”

“O masala sığındım çoktan.” dedi adam.

“Şu an’ın masalında kalmalıyım. Yarın düşlerimden vazgeçmeyi öğrenmem için bir hayat yaşadım ben.” dedi kadın.

“Seni özleyeceğim..! ”

“Özleme soluksuz kalırsın..” dedi kadın.

Adam:

“Bir dere kenarında gökyüzüne bakarak uykuya dalarken düşleyeceğim seni.”

“Yıllardır geceleri avuçlarımda parlattığım taşı vereceğim eline. Taşları severim, renk renk, büyüklü küçüklü taşlar koyarım yastığımın altına, yatağa. Onlarla uyurum.” dedi kadın.

Adam:

“Parmaklarım ürperiyor sedefinden.”

“Masalın ortasından geçiyoruz çünkü..”

“Ellerimizle düşünüyoruz; ellerimizle düş görüyoruz da ondan.” dedi adam.

“Yıldızları boyuyorsun içimde. Direnemem bu akıntıya, bu renklere artık.”

“İnce yüzünün gülümseyen yerlerine damlıyorum, dağılıyorum sende.”

“Yağmur yağacak..! ” dedi kadın.

“Evet.. Ama çıplak omzuna altın rengiyle vuran gün ışığı nedir ki böyle? ” dedi adam.

Kadın:

“Düş görüyorsun... Bir masal bu. Sana uyan bir masal. Daha çok göreceksin..! ”', '“Seni özleyeceğim..! ” “Özleme soluksuz kalırsın..” dedi kadın. Kadının, bakışlarını uzaklarda, denizin üstünden dağların gökyüzüyle buluştu...', ARRAY['Türk Edebiyatı','Şiir','Şerif Erginbay']::text[], 8.5, '{"poet":"Şerif Erginbay","poet_slug":"serif-erginbay","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/uyan-masallar-oyku-siir-masal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avukat / Bir / Kul hakkı', 'avukat-bir-kul-hakki-zafer-zengin-etnika-4smob', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'duydum ki; 

avukatı

olmuşsunuz

savunmasız

bir''in

o

kadar

güçlüsünüz

kim

atar

göreve

sizi

nerdedir

başınız

akıl

var mı

içinde

düşünür mü

anlamaz mısınız

söyleleni

istese çeker kılıncını devirir kelleleri

gücü var

çocuk değil ki

sizden beklesin iyiliği

/__________||xxxxxxx

görünce

