INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Yer', 'i-ki-yer-tolga-ayla-gksh2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yorgun yokuşu çıktım bu akşam,

Resmini denize attığım o uçurumun kenarında

ince bir papatya açmış,

Senin yüzünü papatya bahçesiyle çizmiştim,

Durgunlaştı yüreğim, titredi elim papatyada...

Sana geldim bu gece mutlu yoldan,

Kalbimde dalgaların hırçın gümbürtüsü çınladı,

Adım seslerimle korku dolmuş gecenin şeytanından

ine bir papatyayla sığındım sevgine...

Sana yolumu bir papatya ile çizmiştim.

Cesur dizlerim dizginledi saniyeleri.

Neler neler geçiyor aklımdan sen konuşurken; 

... oysa hiç bir şey.

Bir papatyanın yaptığı iki aşk...

biri uçurumda

diğeri ağaçlı yolda...

Bu gece elimde bir papatya sen konuşurken

İçime sığdıramadığım sen

O''na sığdıramadığım sevgim...', 'Yorgun yokuşu çıktım bu akşam, Resmini denize attığım o uçurumun kenarında ince bir papatya açmış, Senin yüzünü papatya bahçesiyle çizmiştim...', ARRAY['Türk Edebiyatı','Şiir','Tolga Ayla']::text[], 8.5, '{"poet":"Tolga Ayla","poet_slug":"tolga-ayla","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/iki-yer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-adulera-ayza-8m4f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karşı kaldırma geçirirken bir amayı

İçimde hain bir gülümseme vardı

Dedim zamanın da

Çok beddua almış galiba

“Gözün kör olsun”  diye

Sıkıca tuttu elimi

Düşüncen yanlış 

Hastalıktan yada /sevdadan dedi

Üzgünüm kızma düşüncem için dedim

Güldü bana 

Dedim seni bu hale sokanlara senin bedduan nedir

Duyduğum en büyük beddua 

“Gönlün kör olsun” gözün değil dedi.', 'Karşı kaldırma geçirirken bir amayı İçimde hain bir gülümseme vardı Dedim zamanın da Çok beddua almış galiba “Gözün kör olsun”  diye Sıkıca ...', ARRAY['Türk Edebiyatı','Şiir','Adulera Ayza']::text[], 8.5, '{"poet":"Adulera Ayza","poet_slug":"adulera-ayza","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gonul-72-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alıştırma', 'alistirma-banu-ciftci-zdfaq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biraz sessiz yürü,

Sessiz konuş,

Sessiz gel işten eve,

Bu alışmalar hayra alamet değil.

Sesini al benden,

Kokun mesken tuttu zaten hücrelerimi

İşledi sanki tel tel

Usta bir nakkaşın eli.

Bir de, bir de sesinle uğraştırma beni.

Ne çığlığın olsun gecelerimi yırtan

Ne de içimi ürperten fısıldayışın.

Olabildiğince sessiz ol

Koca bir boşluk bırak kulaklarıma,

Varsın uğultular sarsın her yanı.

Yokluğunda ne kadar acı verebilir

Ne kadar canımı yakabilir ki.

Biraz sessiz uyu,

Sessiz ağla,

Sessiz dokun bana,

Bu alışmalar hayra alamet değil.

				15/Ekim/’03', 'Biraz sessiz yürü, Sessiz konuş, Sessiz gel işten eve, Bu alışmalar hayra alamet değil. Sesini al benden, Kokun mesken tuttu zaten hücreleri...', ARRAY['Türk Edebiyatı','Şiir','Banu Çiftçi']::text[], 8.5, '{"poet":"Banu Çiftçi","poet_slug":"banu-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/alistirma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bittiği Gün', 'bittigi-gun-banu-ciftci-gp7rj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olmadığın zamanlarda oturdum iki büklüm yatağıma

Kahve içtim, sigara içtim.

Sana armağan ettiğim şarkıları dinledim

Çok konuştum

Kendi kendime değil, seninle.

Sen sustun, hep sustun.

Zaman zaman gökyüzüne baktım 

Minik odamın dev penceresinden,

Gökyüzü zifir kara, 

Hiç yıldız yok ki bakıp dilek tutayım, kaymasına da gerek yok.

Bazen bir yürüyorum, pir yürüyorum

Islık çala çala,

Gören deli diyor, omuz silkiyorum.

Bir de ıslanıyorum yağmurdan, ben hala yürüyorum

Ege’yi sende sevdim,

Zeybeği, denizi, tütünü, kömürü, günü, geceyi

Renklerin sende ki dansını sevdim

Melodilerin seni bana emanetini

Emeklemeyi bir bebek tadında seninle,

Yavaş yavaş büyümeyi

Ve seninle dirilmeyi ayrı dünyalara.

Güneş ışığı senin yüzüne yansır, ben güzelleşirim,

Sen seversin, ben gülümserim.

Tırnaklarım bile acır olmuş olmadığın bu zamane kentte

Tadını yitirmiş tavlamın pulları, zarları

Dü-bara gelmez olmuş cilasız oyun bahçeme

Çünkü dü-bara sen demek, bir de yanında ben demek.

Her gece bir gözüme akrep batıyor, diğerine yelkovan

Sensizlik betondan, çividen yatak

Hasretin üşütüyor odamı.

Sana aşık olmak garip bir şey

Düşündürüyor günün ilk ışıklarına kadar

Uyutmuyor bu meret…', 'Olmadığın zamanlarda oturdum iki büklüm yatağıma Kahve içtim, sigara içtim. Sana armağan ettiğim şarkıları dinledim Çok konuştum Kendi kendi...', ARRAY['Türk Edebiyatı','Şiir','Banu Çiftçi']::text[], 8.5, '{"poet":"Banu Çiftçi","poet_slug":"banu-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bittigi-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bence Lazım', 'bence-lazim-banu-ciftci-wl9na', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana kızmam mı lazım

Yoksa seni uyarmam mı.

Hala gözlerine sevgiyle bakmam mı lazım

Yoksa günleri sana bırakıp gecelerle gitmem mi.

Tıka basa doldu iliklerim

Şöyle bir güzel içsem ya,

İçip de sarhoş olsam ya.

İşte o an öleceğimi bilsem 

Dilimin ucuna gelse en yaramaz kelimelerim,

Benim kelimelerim,

Hani o arsız kelimelerim…

Derin bir nefes alsam

Ama bu kez sessiz, parçalamadan göğsümü.

Her taşınmamda bir eşyamı kaybediyorum,

Anlaşılan ben taşınmayı beceremiyorum.

Bu defa ise tariflerimi koyduğum

Ardıçtan yapılmış antika sandığımı kaybettim.

Benim tariflerim,

İksirli, cılız, kırgın tariflerim…

Bir tutam, göz kararı, bir ölçek.

Benim sevgi tariflerim,

Benim hayat tariflerim…

Seni büyütmem mi lazım

Seninle beraber büyümem mi.

Gidersem eğer, taşınırsam yani gecelere

Bu defa kaybetmeyeceğim hiç bir şeyimi.

Kilitledim sıkıca sandığımın kapağını,

Hani o ardıçtan yapılmış antika sandığımı.

Sevdirdiğin renk var içinde, 

Ateşkes imzaladığım bedenim, umutlarım var.

Kokunu doldurdum,

Nefesinden çaldım, sakladım diplere.

Seni soldurmam mı lazım

Bende ki solan yaprakları atmam mı.

İki kere tapıyorum Tanrı’ya,

İki kere inanıyorum.

Sen bir tesadüf olamazsın

Tanrı’nın benim boynumu eğen en güzel kanıtısın.

Şimdi seni sevmem mi lazım

Bu kanıtı inkar etmem mi.

						15/Ekim/’03', 'Sana kızmam mı lazım Yoksa seni uyarmam mı. Hala gözlerine sevgiyle bakmam mı lazım Yoksa günleri sana bırakıp gecelerle gitmem mi. Tıka bas...', ARRAY['Türk Edebiyatı','Şiir','Banu Çiftçi']::text[], 8.5, '{"poet":"Banu Çiftçi","poet_slug":"banu-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/bence-lazim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Bir Gül', 'tek-bir-gul-yusuf-ter-lpmvq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kalbimden çıkartıp sana uzattım

Ellerinle Tek Bir Gül’ü alasın diye

Kollarımı  açıp seni bekledim

Koşarak yanıma gelesin diye

Tek Bir Gül adını anar dururum

Gurbet elde sensiz her an kururum

Kalbim muma döndü daim eririm

Yusuf’un halini bilesin diye

Yusuf Ter  04.10.04

Saat.01:15 İsviçre

http://yusufter.tripod.com', 'Kalbimden çıkartıp sana uzattım Ellerinle Tek Bir Gül’ü alasın diye Kollarımı  açıp seni bekledim Koşarak yanıma gelesin diye Tek Bir Gül ad...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Ter']::text[], 8.5, '{"poet":"Yusuf Ter","poet_slug":"yusuf-ter","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/tek-bir-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik...', 'sensizlik-i-brahim-ethem-bingul-yh2jm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani insanın dişi sızlarda

Canı acır ya

İçten içe parçalanır

Köşe bucak kıvranır ya

Sensizlik,işte böyle bir şey...

Acı senin gözünden yaş döktürür

Yaşlar akar acılardan,kendiliğinden

Yatıp uyumak istersin

Uyuyamazsın

Sensizlik, işte böyle bir şey...

Çölde kalırsın, susuz

Kuyu bulursun, kurumuştur

Susuz

Dudakların çatlar susuzluktan

Nefes almakta zorlanırsın

Sensizlik, işte böyle bir şey...

Bir ana,

Sancılarla

Bir bebeği doğurur

Doğan bebek ölüdür

Ana yıkılır, ağlar, perişan olur

Sensizlik, işte böyle bir şey...

Aşk kafesimdeki

Gönül kuşum

Bana,senin sensizliğin

Diri diri bir mezara gömülmekten

Daha beter,buna inan', 'Hani insanın dişi sızlarda Canı acır ya İçten içe parçalanır Köşe bucak kıvranır ya Sensizlik,işte böyle bir şey... Acı senin gözünden yaş d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sensizlik-139-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmaz', 'kalmaz-bayram-tunca-4rcvx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kalmamıştır dünya ne Karun’a, ne Süleyman’a

İnan ki kalmaz şu fani dünya ne sana ne bana

Esasında bizleri verilen her şey birer emanettir

Eğer yerinde kullanmazsak, en büyük ihanettir

Kalmaz, ne sana ne bana bu mekan bu makam

Gel etme eyleme ahretimizi kurtarmaya bakam

Olsak da şu fani dünyada en muteber bir bakan

Eğer yoksa kulluğumuz olmaz yüzümüze bakan

02.09.2004-09.02', 'Kalmamıştır dünya ne Karun’a, ne Süleyman’a İnan ki kalmaz şu fani dünya ne sana ne bana Esasında bizleri verilen her şey birer emanettir Eğ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kalmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Son Gidiş.', 'bu-son-gidis-gokhan-karaduman-npih3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönüşüme bir kibrit çakın

Gidişim sizde kalsın

Ben sürgün bir sevda keş

Bu gidişim ölüme eş

Siyah saçlarının gölgesinde

Güneşli bir güne koynunda uyanmak için 

Vakit çok geç..

Ben firari bir oğul

Hüzünlü bir kardeş

O sevdalı, çilekeş

Yaşayan bir ölüyüm

                  İnadına çılgın

                  İnadına üryan aşık.

Gözlerine gülerek bakabilmem için

Vakit çok geç...

Bileylenmiş acılarımız

Erimiş umutlarımız

Ve bu kan kırmızısı gözlerle

Uyku kokan bir geceye

Birlikte girebilmek için

                      Vakit çok geç...

Hangi düşe yazmalı ikimizi

Ki – yaşasın bu sevda.

Ben sürgün bir sevda keş

O Kahve gözleri

Siyah dalgalı saçları ile

Gözleri yaşlı  çilekeş. 

Ah bu geç kalmışlığım

Kendi kendimle yarışım

Her gülene dostça sarılışım

“ Yanılışım, yıkılışım”

Mutluluk trenine varamayışım

Tekillikler içinden

İki kişilik bir acı yaradışım

Ne kadar boş şimdi

Diktatör planlarıma 

Protest  bir duygusal hal ile kafa tutuşum.

Şimdi gidiyorum ya

Dönüşüme bir kibrit çakın diyorum ya hani

Aşktan böylesine kaçarcasına

Ondan vazgeçmiş görünüyorum ya 

Kanmayın bu tirata

Bu gidişim kendimi unutturmak için – de

Kal dese kalacağım hani.

Dönüşüme bir kibrit çakın

Gidişim sizde kalsın

Kim bilir ne çok özleyeceğim

Bakışımdan susadığımı anlayıp

Su getiren ellerini.

O birden çocuklaşan sesini

Kızdığında o tatlı sert küfürlerini

Sağ kolumda bıraktığın

                                      Dişlerinin sızısını.

Ben firar etmiş duygularımla

Sürgün bir sevda keş

O kahve gözleri hüzünlü çilekeş

Haykırsa da İbrahim Sadri

“ Geç değil bir şey için hiçbir şey” diye

Bu gidiş için bile

Vakit çok geç..

İşte zafer sizin

Yakın meşalenizi

Bu aşkı göre göre

Gonca güle diken takan tutku perest ler

Çay davetine kurban edilen bir gecede

Gonca aşk-ı kopartan ey sizler.

Şimdi kiminiz 

Nikahın eşiğinde

Kiminiz kendi düşlerinde

Kiminiz genzine takılan bir düğümle

Utanıp bakamıyor geçmişe.

Hepiniz kalın

Bedirhan Gökçe’nin 

3.sayfasına konu olmasa da

Ayrılıkların Şairi Ahmet Selçuk 

“Bir Pazar gecesi”

Bu dizeleri haykırmasa da 

Başucunuzdaki radyoda...

Duyarsınız elbet

Pişmanlığın sancısını

Saçınıza düşen aklar

Hatırlatır belki bu “ Hep Kahır” dolu akşamlarımızı.

Ben hüzünlü bir sevda keş

O küskün bir çiçek, çilekeş

Siz kalın burada

Onu bensizliğe

Beni onsuzluğa sürgün edip

Provake bir terk ediş ile gidiyorum

Size armağan olsun

Dönüşüme bir kibrit çakın

Gidişim sizde kalsın

Bu Son gidiştir

Belki ölüme

Belki sürgüne

Bu SON gidiştir...

Gökhan Karaduman

“ Dönüşüm Muhteşem Olacak, 

   Ve o gün siz yer bulamayacaksınız kaçacak”', 'Dönüşüme bir kibrit çakın Gidişim sizde kalsın Ben sürgün bir sevda keş Bu gidişim ölüme eş Siyah saçlarının gölgesinde Güneşli bir güne koy...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/bu-son-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Güzeldi Aşk  O Zamanlar', 'ne-guzeldi-ask-o-zamanlar-ali-arslan-h8swm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden kokladığım güllerin kokusu kaldı.

Aşk o zamanlar, 

içimizde pembe kanatlı bir rüzgârdı.

Uçuşur giderdi.

Kirpiklerinin arasındaki esrarlı her bir bakış 

bir rüyadan henüz kalkmış gibi, 

gülümseyen yüzünde şaşkın şaşkın dolanırdı.

Şimdi o dumanlı dağların,

akşam kızıllığıyla beliren 

hüzün tepelerinde yanık türküleriyle, 

bir adın, bir de hayâlin kaldı.

Hala parıldıyorlar mı? 

İçine düşen her bir yağmur damlasıyla, 

iç içe halkalarla gittikçe büyüyen;

bir zamanlar içimi ürperten o yeşil gözlerin.

Kızıl kanatlı fırtınalarla şimdi ömrümüze dolanır;

senden bana, benden sana bir gidip bir gelen,

aşk o zamanlardı dedirten;

bir sende bir bende saklanan,

hâtıralar.

Ne güzeldi.

Aşk o zamanlar?', 'Senden kokladığım güllerin kokusu kaldı. Aşk o zamanlar,  içimizde pembe kanatlı bir rüzgârdı. Uçuşur giderdi. Kirpiklerinin arasındaki esra...', ARRAY['Türk Edebiyatı','Şiir','Ali Arslan']::text[], 8.5, '{"poet":"Ali Arslan","poet_slug":"ali-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-guzeldi-a-s-k-o-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çığlık! ...', 'ciglik-ozan-si-ar-agdasan-cvagb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanlık gemisi batıyor suya

Haydi bire DURMA zamanı değil

Ateş sardı baca, dalma uykuya

Boşa hayal KURMA zamanı değil

Nakarat: Feryat ediyorum duyun sesimi

                Çığlığımı alın, son nefesimi...! 

''Adalet'' yaralı, ''Sevdalar'' kesir

Barış-Kamber tutsak, Arzular esir

Kafiye ahenksiz, boşlukta nesir...

Geç peşrevi, ZURNA zamanı değil

Beş kıt''ada siyah, beyaz, al, sarı

Doğsun güneş, erisin kışın karı

Gel ağlatma, dağlatma Can Şiar''ı

Boş boşuna YORMA zamanı değil

Feryat ediyorum, duyun sesimi

Alın çığlığımı, son nefesimi! ...

Söz ve Müzik: Ozan ŞİAR Ağdaşan   www.siarcan.com  ŞİARımız Sanat 

Düzenleme ve yorum: Aşık ŞAHTURNA  İnt. Kadın  Platf. www.sahturna.com

Vokaller: ŞİRİN ve ŞAFAK Ağdaşan Evrensel Müzik Grubu www.siarcan.com', 'İnsanlık gemisi batıyor suya Haydi bire DURMA zamanı değil Ateş sardı baca, dalma uykuya Boşa hayal KURMA zamanı değil Nakarat: Feryat ediyo...', ARRAY['Türk Edebiyatı','Şiir','Ozan ŞİAR Ağdaşan']::text[], 8.5, '{"poet":"Ozan ŞİAR Ağdaşan","poet_slug":"ozan-si-ar-agdasan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ciglik-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Çömez Şaireyim', 'ben-comez-saireyim-tulay-sustam-kqva2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aşk da çırak...

dostluk da ustayım...

aşk şiiri yazar ÇÖMEZ olurum

dost şiiri yazar ŞAİRE olurum

ben çömez şaireyim...

günlerce aç, susuz kalıp dolaşsam

bir kalleş, bir kahpe tarafından

kurtlar sofrasına davet edilsem

bir şey yemeden kalkarım, ben hep TOK''um

dostu sırtından vurmayı bilmem 

aşkı iki kuruşa satmayı bilmem, ben hiç YOK''um

hoşçakalın yâr...

hoşçakalın dostlar...

çömezliğim bana kalsın GİDİYORUM...', 'aşk da çırak... dostluk da ustayım... aşk şiiri yazar ÇÖMEZ olurum dost şiiri yazar ŞAİRE olurum ben çömez şaireyim... günlerce aç, susuz ka...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ben-comez-saireyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isıtan Işıltılar Ramazan', 'isitan-isiltilar-ramazan-kubilay-enginol-j0k4w', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mahyalar asıldı minareden minareye

“Ramazan-ı Şerif  Hoş Geldi “ diye

Sahura kalkıldı, oruçlar tutuldu.

İftar vaktinde çeşnilere gark olundu.

Çatlak pencereden sızan ışık,

Hayat bu, nede karışık.

Karşıda ayakta zor duran kâgir ev

Aileyi barındırmak bu yaşta kutsal bir görev.

Top atıldı, eller açıldı duaya,

Sonrasında eda olundu sofraya.

Bir yanda mükellef sofralar,

Kâgir evde ise talim olundu çorbaya.

Şikayet edilmedi, şükredildi hep

Gurur vardı, haya vardı, müsaade etmezdi edep.

Komşun aç yatarken tok yatamazsın der peygamberimiz

Debdebeli masalarda kendimizi kaybetmişiz

Torbaları bıraktı kâgir evin sessizce kapısına

İhtiyacı yoktu komşunun hayır duasına

Kâgir evden sevinç çığlıkları yükseliyordu

O, arkasında ısıtan ışıltıları,gidiyordu.

Bu Şiir yardımsever insan SN.AHMET TEMEL''E  ithaf edilmiştir.', 'Mahyalar asıldı minareden minareye “Ramazan-ı Şerif  Hoş Geldi “ diye Sahura kalkıldı, oruçlar tutuldu. İftar vaktinde çeşnilere gark olundu...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/isitan-isiltilar-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Yanlış, Bir Doğru', 'uc-yanlis-bir-dogru-tulay-sustam-8r8qt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni sevmiyorum (y)

seni özlemiyorum (y)

seni kıskanmıyorum (y)

________________ seni istiyorum (d)

seni istemiyorum (y)

seni beklemiyorum (y)

seni sayıklamıyorum (y)

_________________seni seviyorum (d)

şunu bil ki sevgili...

benim yaptığım hiçbir hesapta

üç yanlış bir doğruyu götürmez 

ama bir doğru bütün yanlışları götürür...', 'seni sevmiyorum (y) seni özlemiyorum (y) seni kıskanmıyorum (y) ________________ seni istiyorum (d) seni istemiyorum (y) seni beklemiyorum (...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uc-yanlis-bir-dogru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön artık', 'don-artik-omer-ocak-kg1dx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni paylaşmak istemiyorum

Seni kimse olmadan,yalnız sevmek istiyorum

Uzaklarda durma yeter gel diyorum

Bitsin bu hasret dön artık

Ben sensiz ölmek istemiyorum

Ben seninle yaşlanmak istiyorum

Senin yanıma gelmen için yalvarıyorum

Bitsin bu hasret dön artık

Güzelliğini resimlerde görmek istemiyorum

Sıcak nefesini yanımda hissetmek istiyorum

Ölürken de olsa gelmeni bekliyorum

Bitsin bu hasret dön artık

Allah’tan bizi ayırmasını istemiyorum

Seni bana geri göndermesini istiyorum

Ondan hep ama hep seni diliyorum

Bitsin bu hasret dön artık', 'Seni paylaşmak istemiyorum Seni kimse olmadan,yalnız sevmek istiyorum Uzaklarda durma yeter gel diyorum Bitsin bu hasret dön artık Ben sensi...', ARRAY['Türk Edebiyatı','Şiir','Ömer Ocak']::text[], 8.5, '{"poet":"Ömer Ocak","poet_slug":"omer-ocak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/don-artik-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir''in İntiharı', 'siir-in-i-ntihari-tulay-sustam-2yi4t', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kalem; kağıda küsmüş

kağıdın haberi olmamış

kağıt; kaleme küşmüş

kalemin haberi olmamış

ikisinin arasında ki dargınlığın 

faturasını ŞİİR ödemiş...

o gün, bugündür İSİMSİZ kalmış...

o yüzden hiç anlaşılmamış...', 'kalem; kağıda küsmüş kağıdın haberi olmamış kağıt; kaleme küşmüş kalemin haberi olmamış ikisinin arasında ki dargınlığın  faturasını ŞİİR öd...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siir-in-intihari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sesin Sesime Değdiği Vakit*', 'sesin-sesime-degdigi-vakit-zubeyde-yilmaz-al1gx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesin sesime değdiği vakit

Yandı yürek ateşler titredi

Kirlenmişlikler bulutlara tutsak

Geçti...Eskilerin namertliği...

Çok ümitler kaynattım kazanında gecenin

Ateşi yalazlandıran yalnızlığım içinde ben

Gözlerim görmez yemişti  gözlerimi karanlık

çok kezde çığ inmişti sevdaya tepelerden

hasret sarmış,kuşanmıştı dört yanı ayrılık...

Sesin sesime değdiği vakit...

yandı yürek ateşler titredi

Kirlenmişlikler bulutlara tutsak

geçti kanlı gözyaşların tendeki izleri...

Yaktım ne varsa... ihanetin kurtlanmış benzi

kılıçlar indi göğsüne,delik deşik

iniltili sevda türküleri,hapsolmuş kahırlı matemleri...

sesin sesime değdiği vakit

ışıksız değil artık gemiler seyrü-seferde

sevda,sevi zindanlarından firarda

 parçalandı paslanmış zincirleri tam yol ileri...

bulutlar tutsak, onda bendeki önceler

sesin sesimde, deniz toprakta, aşk kadehte

içelim gayri düştük ciğerine,mızrak yedi gönül

sesin sesime değdiği vakit

yandı yürek ateşler titredi

kirlenmişlikler bulutlara tutsak

geçti...yalnızlık..

_________________geçti sessizlik...

_______________________Bitti  dökülen inci taneleri....', 'Sesin sesime değdiği vakit Yandı yürek ateşler titredi Kirlenmişlikler bulutlara tutsak Geçti...Eskilerin namertliği... Çok ümitler kaynattı...', ARRAY['Türk Edebiyatı','Şiir','Zübeyde Yılmaz']::text[], 8.5, '{"poet":"Zübeyde Yılmaz","poet_slug":"zubeyde-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sesin-sesime-degdigi-vakit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair''in Şiir''in İntiharına Cevabı', 'sair-in-siir-in-i-ntiharina-cevabi-tulay-sustam-nww4s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ey kalem dinle beni...

kağıda küstün,oturup yazmak yerine

üzerine gözyaşı döktün

ey kağıt dinle beni...

kaleme küstün, yazılanı göstermek yerine

sakladın kalemi üzdün

hiç düşündünüz mü? 

ne kağıt kalemsiz olabilir

ne de kalem kağıtsız

ikinizin meyvesi şiirler

ayrıldınız onlar artık isimsizler

eğer ben şairsem! ...

bir daha ikinize içimi dökmem

şimdi ister barışın, ister küsün

umurumda bile değil...

ben ikinize de küstüm...

yoksunuz artık hayatımda üzgünüm...', 'ey kalem dinle beni... kağıda küstün,oturup yazmak yerine üzerine gözyaşı döktün ey kağıt dinle beni... kaleme küstün, yazılanı göstermek ye...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sair-in-siir-in-intiharina-cevabi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye', 'niye-seyhan-sevgili-ooldc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün geçtikçe külleniyor ayrılığın.

Zavallı yüreğim yağmuru bekler oldu.

İki damlaya hasret yaşıyorum vefayla.

Zaman ilaç değil anladım,çaresi unutmak,

temeli zaman onuda geçtim.

Bir başkasını arıyorum.

Sevmek istiyorum korkusuzca.

İçimde saklamaktan usandım,derinliklere itmek,

düşünmemek,karanlıklara mahkum edip bulamamak

tek temennim.

Böylesi çok ağır güzelim.

Kavuşmak,aşk''ı yazmak dururken ölemek,

biri var iken başkasını aramak niye?', 'Gün geçtikçe külleniyor ayrılığın. Zavallı yüreğim yağmuru bekler oldu. İki damlaya hasret yaşıyorum vefayla. Zaman ilaç değil anladım,çares...', ARRAY['Türk Edebiyatı','Şiir','Seyhan Sevgılı']::text[], 8.5, '{"poet":"Seyhan Sevgılı","poet_slug":"seyhan-sevgili","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/niye-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sandalcı', 'sandalci-sahin-yenilmez-jhgdu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hava biraz daha kararır

Gece artık zifiri olmuştur

Gündüzden bir eser kalmasa da

Aydınlık düşünceler vardır hep aklımızda.

Bir sandal açılır okyanusa

Binlerce balığın

Azgın dalgaların arasına

Hani derler ya:

Boğulursan büyük denizde boğulacaksın diye

Denizin küçüğü olur mu? 

Biz mi küçüğüz yoksa? 

Hiç bir şey belli değil

Ve artık fırtınanın çıkması beklenir

Büyük deniz kehanetinin doğrulanması için.

Soyutlanan düşünceler ile birlikte 

Somut bir hayata başlar insan her yeni gün ile

Ve her yeni günde

Yeni yeni yaşlanma metodları öğrenilir.

Umursamıyor kimse sandalcıyı

Herkes kendi denizinde korsan

Herkes kendi limanında gemi.

Ne zaman konuşacağız sustuklarımızın bedelini

Ecel kapıya dayanınca mı?', 'Hava biraz daha kararır Gece artık zifiri olmuştur Gündüzden bir eser kalmasa da Aydınlık düşünceler vardır hep aklımızda. Bir sandal açılır...', ARRAY['Türk Edebiyatı','Şiir','Şahin Yenilmez']::text[], 8.5, '{"poet":"Şahin Yenilmez","poet_slug":"sahin-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sandalci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalsın', 'kalsin-i-smet-barlioglu-n9cjo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Varsa kabullendim alınyazımı,

Hayatım böylece yerinde kalsın.

Razıyım çekmeye her bir sızımı,

Yüreğim bir onun elinde kalsın.

Ne güzel şeydir ki onu sevmişim,

Dünyaya göz açıp onu görmüşüm,

Kaldırıp canımı ona vermişim,

Elinde bugün de, yarın da kalsın.

Gelsin tüm çileler, çekmesi benden,

Tümünü çekerim isyan etmeden,

Asla ah etmeden, inildemeden,

Kalbim gözlerinin nurunda kalsın.

Dünyalar bir yana, o bir yanadır,

Aşkı yüreğimde derin yaradır,

Onsuz dünya bana beş-on paradır,

Razıyım yüreğim narında kalsın.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 92-93/100)', 'Varsa kabullendim alınyazımı, Hayatım böylece yerinde kalsın. Razıyım çekmeye her bir sızımı, Yüreğim bir onun elinde kalsın. Ne güzel şeydi...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kalsin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölürüm Uğrunda', 'olurum-ugrunda-i-smet-barlioglu-mjymd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ha seni özledim, ha çölde suyu,

Unuttum geceyi, derin uykuyu,

Atıp yüreğimden binbir korkuyu

Gelip alevinde tutuşacağım.

Uğraşlarım sensin, amaçlarım sen,

Ölürüm uğrunda feryat etmeden,

Geriye bir avuç kül kalsa benden

Savrulup ardından uçuşacağım.

Aşacağım bir gün hudutlarımı,

Savurup çevreye bulutlarımı,

Bırakıp rüzgara umutlarımı

Sana ki dört elle yapışacağım.

Sen bir atlısın ki; menzil bilmeyen,

Ben bir yolcuyum ki; geri dönmeyen,

Bir umudum var ki; hiç tükenmeyen; 

Seninle mutlaka buluşacağım.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 94-95/100)', 'Ha seni özledim, ha çölde suyu, Unuttum geceyi, derin uykuyu, Atıp yüreğimden binbir korkuyu Gelip alevinde tutuşacağım. Uğraşlarım sensin, ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olurum-ugrunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çık Dışarıya Oynayalım..!', 'cik-disariya-oynayalim-hasan-basri-kale-pg5hp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kolay değil

damdan düşmek

acıyor insanın 

bir yerleri..

halbuki ne keyifliydi

değil   mi

damdaki villadan

boğaza melül melül bakıp

zap suyuna 

ağıt yakma fikirleri..

takke zaten yok

hani düşse de kel görünse..

kusar kinini

ısıtıp ısıtıp tekrarlar

bekler popüleriteyi..

aşktan bahseder

sevmekten sevilmekten

insanlıktan güzellikten

bilmez ki

görmez gözü,duymaz kulağı

mühürlü kalbi

lâl olmuş dilleri..

adaşları,candaşları

salaşları,talaşları

basit küme tarzında içtimada

hep birileri..

alkış bol..çık oyna / kıvır

giy eteği,tak zilleri

.........

çık hadi canım...korkma..! 

*herkes gidecek..sen de ben de

bu dünya kimseye kalmaz

en azından; 

gittiğimiz yerde, hiç karşılaşma ihtimalimizin olmayışına seviniyorum', 'kolay değil damdan düşmek acıyor insanın  bir yerleri.. halbuki ne keyifliydi değil   mi damdaki villadan boğaza melül melül bakıp zap suyun...', ARRAY['Türk Edebiyatı','Şiir','Hasan Basri Kale']::text[], 8.5, '{"poet":"Hasan Basri Kale","poet_slug":"hasan-basri-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/cik-disariya-oynayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesin', 'oylesin-i-smet-barlioglu-ht62a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül aşırı kanlıdır,

Kaktüs hafakanlıdır,

Itır heyecanlıdır,

Sen de işte öylesin.

……….Sen de tıpkı öylesin,

……….Gönül nasıl sevmesin? 

Papatyalar sarı saç,

Nilüfer kulaç kulaç,

Gelincikler utangaç,

Sen de işte öylesin.

……….Sen de tıpkı öylesin,

……….Gönül nasıl sevmesin? 

Zambak kabarık olur,

Şebboy şımarık olur,

Lale kızarık olur,

Sen de işte öylesin.

……….Sen de tıpkı öylesin,

……….Gönül nasıl sevmesin? 

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 96-97/100)', 'Gül aşırı kanlıdır, Kaktüs hafakanlıdır, Itır heyecanlıdır, Sen de işte öylesin. ……….Sen de tıpkı öylesin, ……….Gönül nasıl sevmesin?  Papaty...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/oylesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öte', 'ote-emre-gumusdogan-qsle2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'öte...

gece farklı başlar eleğin altında, yanı-

başında iğne yapraklı orman karanlık...

hiçbir yere kayıtlı değildir nehirler! .. 

kendini besleyen mavisinde akar-

kentler kusurludur doğma büyüme...

kaç izmarit limitim! ..

kaç iz! ..

ka! ..

bir midyenin heybesinde uyku-

sudur, sarıp sarmalar mahmurluğunu

göğün penceresinden geçen martı 

bilmese de olur kuleyi uçurumu

''mutlaka bilir bir taş yontucusu''

rapunzel saçların kısa! ..

rapunzel saç! ..

ra! ..

vurur gecenin duvarına tik taklarını

ateş çemberinde akrep beynim! 

garip bir dille konuşur eski rüya, eksik-

açar derin dekoltesini ölüm! .. emzirir

kızarmayı bekleyen nar sabahta...

öte durak intihar! ..

öte dur-

-ak!', 'öte... gece farklı başlar eleğin altında, yanı- başında iğne yapraklı orman karanlık... hiçbir yere kayıtlı değildir nehirler! ..  kendini b...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ote-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-emre-gumusdogan-5jelu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'özlem

ışık kanatlı kelebeğe gebe ay; eşiğinde

dur öylesine, bak kendine ve bana 

yeni adlar bul, yeni bir gün doğsun

ellerimize...  yürünmemiş 

bir sokağı yürümek belki de en zoru, 

hem okyanus olmak, hem bir bardak su! ..

su dedim de, aklıma  takıldı yine o göl! .. 

yağmurun açık bıraktığı kapıdan geldi,

kamp düşünü ertelediğimiz bahar.

yuvalar kırlangıç, göl bizi bekliyor...

bırak sırt çantanı, sevgiyi çeyiz al 

yüreğin sandık odası, küfleniyor...

yatağı olmayan nehir dokunuşun,

ben mi nehre akıyorum, nehir mi bana

sesim mavi; tortusuz, içimin utangaç gülüşü.

herkes bir şeyler diyor sakarlığıma,

onu sorumlu tutuyor her şeyden,

bari sen deme, bunun aşk olduğunu...', 'özlem ışık kanatlı kelebeğe gebe ay; eşiğinde dur öylesine, bak kendine ve bana  yeni adlar bul, yeni bir gün doğsun ellerimize...  yürünmem...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ozlem-190-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Gözüyle', 'dunya-gozuyle-i-smet-barlioglu-mzg6y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sabah erkenden gel vur kapımı,

Seni bir göreyim dünya gözüyle.

Eşikler üstünde söyle adımı,

Seni bir göreyim dünya gözüyle.

Gölgen fidan gibi düşsün içeri,

Sarsılsın gönlümün derinlikleri,

Önünde eğilip öperken yeri

Seni bir göreyim dünya gözüyle.

Geçmiş canlanırken dudaklarında,

Yaşlar belirirken yanaklarında,

Kul kurban olayım ayaklarında,

Seni bir göreyim dünya gözüyle.

Seni yüreğime buyur edeyim,

Gönlümün tahtında yer göstereyim,

Sevinçten ağlayıp yaşlar dökeyim,

Seni bir göreyim dünya gözüyle.

(SANA LEYLA DESEM isimli Hece Şiirleri ''nden > 99-100/100)', 'Bir sabah erkenden gel vur kapımı, Seni bir göreyim dünya gözüyle. Eşikler üstünde söyle adımı, Seni bir göreyim dünya gözüyle. Gölgen fidan...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/dunya-gozuyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların Işıkta Sırmalaşıyor', 'saclarin-isikta-sirmalasiyor-i-smet-barlioglu-eqpnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözyaşın mehtapta kristal gibi,

Işığa değdikçe billurlaşıyor.

Bakmaktan yorulan melekler gibi

O güzel gözlerin mahmurlaşıyor.

Mehtap yanağında parıldamakta

Deniz gözlerinde mırıldanmakta,

Bahar dudağında kımıldamakta,

Saçların ışıkta sırmalaşıyor.

Gül yaprağı kadar narin ellerin,

Rüzgara karıştı iniltilerim,

Gözlerinin içi ne kadar serin,

Baktıkça bakışın sevdalaşıyor.

Yine aşık olduk birbirimize,

Yine döndük eski günlerimize,

Ruhlarımız indi ellerimize,

Kalbimiz hasretle vedalaşıyor.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden >7-8 /100)', 'Gözyaşın mehtapta kristal gibi, Işığa değdikçe billurlaşıyor. Bakmaktan yorulan melekler gibi O güzel gözlerin mahmurlaşıyor. Mehtap yanağın...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saclarin-isikta-sirmalasiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykünmeler 7', 'oykunmeler-7-zeki-ergin-7ayak', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dümeni kırık 

bir teknede oldun mu sen hiç

ey sevgili

saçların sakalına karıştı mı

tuzlu sularda 

acı poyrazlarda yandı mı yüzün

kaç yıldız saydın 

gün doğumlarına kadar

uykulu yorgun gözlerini

açamadığın oldu mu 

şafak sökerken

ey sevgili

açık denizlerde

tutsak oldun mu  sen hiç

_erenköy 16ek''04

_şarkılar savrulur Ege''den yt; mar''14 pencere yayınları', 'dümeni kırık  bir teknede oldun mu sen hiç ey sevgili saçların sakalına karıştı mı tuzlu sularda  acı poyrazlarda yandı mı yüzün kaç yıldız ...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oykunmeler-7-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sararmış izler...', 'sararmis-izler-kadir-mustafa-turken-tk9xz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerede pecete kağıtlarım? 

Duygularımla dolu...

Gözyaşları damlamış.

İzleride sararmış.

Kimbilir nerde yazmışım...

Tarihleri silinmiş.

Bazen parfüm kokusu,

Bazen içki  kokusu,

Şiirlerime sinmiş.

Okudukça onları,

Tarihleri  yaşanmış,

Mekanları canlanmış.

Ne çok yer gezmişim,

Ne çok ağlamışım,

Ne kadar kederlenmişim,

Kimlerden duygu almışım; 

Bazen bir tren vagonundaki,

Yorgun ihtiyardan.

Bazen gardaki sarhoştan.

Ötebüsteki kadından.

Yada parktaki çocuktan.

Hepsini peçetelere yazmışım.

Buruşturup cebime atmışım.

Bir koca zaman olmuş onlar,

Benle yaşlanmış.

Yazarken yaşadığım o anlar; 

Şimdi okurken yaşlanmış.

Elimin hızına yetişemezken,

Şimdi okurken titrer olmuş...

Ya gözlerim; 

Yıllardır aradı durdu özleneni

Bir nehir gibi,

Ulaşmak için bir an önce denize,

Ebedi…', 'Nerede pecete kağıtlarım?  Duygularımla dolu... Gözyaşları damlamış. İzleride sararmış. Kimbilir nerde yazmışım... Tarihleri silinmiş. Bazen...', ARRAY['Türk Edebiyatı','Şiir','Kadir Mustafa Türken']::text[], 8.5, '{"poet":"Kadir Mustafa Türken","poet_slug":"kadir-mustafa-turken","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sararmis-izler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Öyle İhtiyacım Varki', 'sana-oyle-i-htiyacim-varki-volkan-yoruc-h586c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen gül yüzüme

Bir sen gel yanıma

Tut ellerimden bırakma

Sıkıca sarıl bana

Gözünü ayırma benden

Bak sonsuza dek 

Sen gülümse gül yüzünle

Sadece sen ol yanımda

Diğerleri gibi olma

Asla yalan atma

Ben oyuncak değilim

Benimle oynama

Bilirsin benimde bir kalbim var

Kırılmış paramparça olmuş

Nedenini sorma

Sen gel sadece yanıma

Ve sarıl sıkıca bana

Sana ihtiyacım var

Aşk de bana sevgi de bana

Sarı mavi bakışımı vereyim ben sana

Yeterki sen sev beni yalnız bırakma

Bilirmisin ne sevgiler aradım

Ne kızlar geldi karşıma

Biri bile sevmedi oynadılar benle

Sevgiye hasret şu gönlümü

Teker teker tekmelediler kırdılar parçaladılar

Sen onlar gibi olma

Öldürme sende beni

Hadi gel gül yüzünle gülümse

Ve sıkıca ama çok sıkıca sarıl 

Bırakma beni artık şu yalnızlığın karanlığına

Bir seni bilirim artık

Maziler ağlasada arkamdan

Gözlerim yollardada kalsa

Bir seni severim artık

Saklama gülüşünü benden

Tut şu yalnız ellerimi

Gör şu yorgun gözlerimi

Ve sarıl şu yapayalnız koynuma

Sana öyle ihtiyacım varki', 'Sen gül yüzüme Bir sen gel yanıma Tut ellerimden bırakma Sıkıca sarıl bana Gözünü ayırma benden Bak sonsuza dek  Sen gülümse gül yüzünle Sad...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/sana-oyle-ihtiyacim-varki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mevlana', 'mevlana-atil-kesmen-3l1y6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanrım seni özenip özenip''te yaratmış 					

Gündüz ve gecelere dağıtmış					

Sevgi hamuruyla yoğurmuş					

İnsanlığa armağan etmiş........					

					

Gönlünde durmadan yanan					

Mevla sevgisidir muhakkak					

Sonsuzluklara ışık saçan, acılara meydan okuyan					

Güzelliklere mekan kuran 					

İyilik diye coşan					

Döndükçe taşan sevgi düşüncelerinden					

Kendimizi alamıyorum...........					

					

Hep açıkmı tuttun mevla''nam, gönül kapılarını					

Durmadan dönen bu dünya çemberinde					

Gönlünde ulaşılmaz bir sevgi tufanı esiyor					

Kol kola omuz omuza girmişler					

Gözlerini kapatmışlar, Işık tutuyorlar devri aleme........					

					

Dönüyor senin dünyan dönüyor mevla sevgisiyle					

Saygı ve hak yolunda					

Ama.....iyi					

Ama.....kötü					

Ama.....güzel					

Ama.....çirkin					

Ne olursa olsun					

Dönüyor senin dünyan dönüyor mevla sevgisiyle........					

					

Sevgi saygı dolu ulaşılmaz düşüncelerinle					

İnsanlık gemisine					

İnsanlık sevgisine					

Dem tutmuş nefesinle					

Yönmü veriyorsun...... Dalga alıp batmasın diye.........					

					

Mevla''nam......					

Geldim gönül kapına, dönüyorum bir oyana bir buyana					

Senin......Işığın ne kadar net					

Düşüncelerin ne kadar taze					

Bakamıyorum gözlerim kamaşıyor					

Ama yine''de senin güzelliklerinden gözlerimi,gönlümü alamıyorum.......					

					

Durmadan,usanmadan,yorulmadan hiç yılmadan					

Güzel mis gibi kokan gönlünde dönüyorsun					

Tanrı aşkıyla yanıyorsun					

Tanrı aşk''ı dağıtıyorsun					

İnsanlığa tanrı sevgisini aşılıyorsun.........					

					

Senin güzelliklerinden dilim çözülüyor					

Gözlerimi sevgi bürüyor					

Düşüncelerimden senin sıcaklığın akıyor					

Gönlüm...... senin bu güzelliklerinle coşuyor					

Sel oluyor bir nehir oluyor ve sana akıyor.........					

					

Mevla''nam ne güzel					

Tanrı sevgisiyle yanıyorsun, alev alev					

İnsan can değeri biliyorsun					

Yol gösterip hak diliyorsun					

Gönüllerde dolaşıp sevgi veriyorsun........					

					

Seni........ sen''de görmek isterdim					

Sevginin sen''de şekillenip,Tanrı sevgisiyle sararken					

Ben''de sen''de dönmek isterdim					

Hak''kı bulup					

Tanrı sevgisinde ölmek için........					

					

Dönsün senin güzel gönlün dönsün					

İnsanlık düşüncelerine umut, mutluluk saçsın					

Alsın bizi''de götürsün					

Biz''de bu sevgide yanıp dönelim					

Ulaşılmaz Tanrı aşk''ı için.........					

					

Mevlana''nam..					

Senin bu ince çizğinde					

Gönlünde hiç bitmeyen sevginde					

Yanıp''ta hiç sönmeyen ateşinde					

Duramam					

Durup''ta sen''de yanan 					

Sevgi ateşinde olamam diye korkuyorum					

Senin gönlün Tanrı aşk''ı kokuyor					

Hak yolu biliyor sevgi diye dileniyor					

Ben neyimki..					

Senin dönen bu sevgi aleminde					

Yükün ağır bu dünya nefesinde					

Sen....MEVLANA''SIN.....					

Hak yardım diye dönüyorsun					

Sevginle tüm insanlığı sarıyorsun					

SANA.......SEN YAKIŞIYORSUN					

Bana ise...					

Senin yanında....dönüp dönüp					

Sana bakmak yakışıyor..........', 'Tanrım seni özenip özenip''te yaratmış 					 Gündüz ve gecelere dağıtmış					 Sevgi hamuruyla yoğurmuş					 İnsanlığa armağan etmiş........		...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":79,"source_url":"https://www.antoloji.com/mevlana-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ali Servet diye bir cocuk', 'ali-servet-diye-bir-cocuk-vecdet-baysal-gunter-ae1tz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ALI YINE SOZLUDE

Hey millet dinle sende,

Ali yine sozlude.

Insallah kalkmam dedi,

hoca yine dinlemedi.

Yeter artik daha ne,

bir sozlu daha kaldirmaz bunye.

Hocam ben yapmadim,

yapan Timur Hakan Emre.', 'ALI YINE SOZLUDE Hey millet dinle sende, Ali yine sozlude. Insallah kalkmam dedi, hoca yine dinlemedi. Yeter artik daha ne, bir sozlu daha k...', ARRAY['Türk Edebiyatı','Şiir','Vecdet Baysal Gunter']::text[], 8.5, '{"poet":"Vecdet Baysal Gunter","poet_slug":"vecdet-baysal-gunter","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ali-servet-diye-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda cicegi', 'sevda-cicegi-vecdet-baysal-gunter-c7bpd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'SEVDA CICEGI

Sessiz sedasiz,

acardin gecelerde.

Kimse bilemez,

goremez kuytularda.

Sonsuz ve dipsiz,

sevdalarda,duygularda.

Sakin kimsesiz ve sahipsiz,

uykularimda.

Simdi artik,

seni koklar yanlizligim.

Seni arar seni sorar, 

sevda cicegi.', 'SEVDA CICEGI Sessiz sedasiz, acardin gecelerde. Kimse bilemez, goremez kuytularda. Sonsuz ve dipsiz, sevdalarda,duygularda. Sakin kimsesiz v...', ARRAY['Türk Edebiyatı','Şiir','Vecdet Baysal Gunter']::text[], 8.5, '{"poet":"Vecdet Baysal Gunter","poet_slug":"vecdet-baysal-gunter","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevda-cicegi-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalaylı bakır', 'kalayli-bakir-hande-caner-akngh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KALAYLI BAKIR 

Sabahları orada

Kalaylı bakır

Gibi ufuklar aktır

Dağlara düşen Güneş

Elmastan da parlaktır

Bahçelerin çiçekleri

Arıları böcekleri

Vadilerin meyveleri

Mis kokulu Gülleri

Dallardaki Bülbülleri

Kırların kekikleri

Birbirine aşık eder

Kadınlarla erkekleri

Dudaklardaki gülüşleri

Uykudaki düşleri

Kalpten kalbe uçuşlar

Utanarak kaçışlar

İnsanların kalplerini kaynatır

Yürekleri oynatır

Her birisi bunların

Damla damla birer bakır

Kızıla yakın tunca benzer

Bu diyarda dağ, bağ kır

Suları renkli akar

Sarı,mavi,kırmızı

Şakır şakır

Siyah bukleli saçlar üstünde

Yemeninin oyaları kırmızı

Gül pembe ten üstünde

Al yanaklıdır kızı

Delikanlıları da

Bakır kadar yumuşak huylu

Fidan gibi uzun boylu

Ve gayet gürbüz

Çatık kaşlar altında

Hoş görülü yağız yüz

Aşıklar gece damda

Yıldız sayar stare''nin altında

Bu memleket çok zengin

Milyonlarca ton bakır var

İnsanlar ne hikmet arar

Bulacağı bir damlacık altın da

Gurupta bakırlaşan göğe

Geceler pastır

Bakır tepsi olan aya

Kızıl bulutlar yastır

Meyvalar bakır damla gibi durur dallarda

Gam gider,neşe gelir

Yolcu budur yollarda

Buralı olan babama

Gelin etmişler annemi

Bu memleketin adı

Ergani Bakır Madeni...

pimp myspace', 'KALAYLI BAKIR  Sabahları orada Kalaylı bakır Gibi ufuklar aktır Dağlara düşen Güneş Elmastan da parlaktır Bahçelerin çiçekleri Arıları böcek...', ARRAY['Türk Edebiyatı','Şiir','Hande Caner']::text[], 8.5, '{"poet":"Hande Caner","poet_slug":"hande-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/kalayli-bakir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sosyal Aptal', 'sosyal-aptal-vecdet-baysal-gunter-i1yds', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SOSYAL APTAL

Galeri gezersin cig et yersin,

soranlara aktivistlik edersin.

Gosterilerde basi cekersin,

sarabida sushiyle icersin.

Yaptigin sanata taparsin,

kendini en iyi sen satarsin.

Oysa resimin resim degil,

ya sen ne bicim adamsin? 

Topluma tepeden bakarsin,

kendini otorite sanarsin.

Is fular takmakta degil,

Elbet bunu anlarsin.

Beyninde yeller essin,

zaten heptende kelsin.

Silkin de kendine gel,

en buyuk sosyal aptal sensin.', 'SOSYAL APTAL Galeri gezersin cig et yersin, soranlara aktivistlik edersin. Gosterilerde basi cekersin, sarabida sushiyle icersin. Yaptigin s...', ARRAY['Türk Edebiyatı','Şiir','Vecdet Baysal Gunter']::text[], 8.5, '{"poet":"Vecdet Baysal Gunter","poet_slug":"vecdet-baysal-gunter","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sosyal-aptal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Çiçeği', 'kalbimin-cicegi-kamil-aydemir-bmv8e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerimde nü tablon

kendime özel çizdim

sevgiden fırçamla

sensiz yarımım ben bensiz yarımsın sen

durma ikimizi bire tamamla

ölüler sevildiğini duymaz

ne de gözyaşını görür

beni sevdiğini söylemeye

ne olursun geç kalma

öksüz koyarsan sevdam ağlar

sana söylemedi mi turnalar

tanığımdır kekik kokulu dağlar

firar ettim sensizliğin şehrinden

yaşamak kurşun bana hasretinden

unutma sensin

bu şairin düşlerindeki geleceği

ömrünün son noktasına kadar seveceği

ah kalbimin çiçeği

şiirlerimin ortasına yangın düşüyor

ana rahmindeki cenin bile üşüyor

çocuklar sevinçlerine küsüyor

sen susunca hayat susuyor gözlerinde

dertlerini daha ne kadar yığacaksın zullarına

umutların olmalı seni taşıyacak yarına

istiyorum ki ışıkları sönmesin gönlümdeki yıldızın

ömrüm kararır

gönlümün mahzeninde sana sakladığım

sevda türküleri sararır

içindeki denizler neden dalgalı

hayatın kaç yerinden yaralı

düşlerine ne oldu selvi boylu kızın

hep hüzün ırmaklarına mı yataklık edecek

memleketimin resmi yüzün

ve hep kanıyacak mısın dünyamız gibi

sen kanadıkça acılar işgal eder içimi

aşkımın koynuna sokul hayatın acı gerçeği

sevgimde aç kalbimin çiçeği

izin verde gözlerin gözlerimle konuşsun

beni sevdiğini söylemeye 

geç kalma ne olursun

uçup giderken hayat kelebeğin kanadında

sana göre değil hazanlar

zemherinin ne işi var kapında

sevgisiz yüreklerde dinmez fırtına

o yaşlar senden mi düşüyor günlerin suratına

hep yarınsızlık mı büyüteceksin

daha ne kadar kendini öğüteceksin

kuruyup gideceksin

   bakmadan mutluluğun tadına

sana göre değil berbatlar

bir yaprağına bile dokunamaz acılar hüzünler

gölgende bile gezinemez hoyrat eller

gel aşkımın koynuna

sevgimde aç kalbimin çiçeği

sana çektirenlerin inadına

mutluluğunu kolyeliğe asalım günlerin boynuna

yarınlarımın adresi

çiçeklerin nadidesi

kalbimin çiçeği

soldurur muyum seni

seni soldurmam

karakışın avuçlarına bırakmam demektir kalbimi

öldürmem demektir

dünyanın en güzel kadınını 

     ve kendimi

kendime kıyarım da kıyamam sana oy

kalbimin çiçeği

beni bal gülüşlerinde soy

sana güzellikler

sana mutluluklar

v e    ö z g ü r l ü k    v a r

içim hep bahar

kalbimde aşk mevsimi', 'gözlerimde nü tablon kendime özel çizdim sevgiden fırçamla sensiz yarımım ben bensiz yarımsın sen durma ikimizi bire tamamla ölüler sevildiğ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Aydemir']::text[], 8.5, '{"poet":"Kamil Aydemir","poet_slug":"kamil-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/kalbimin-cicegi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun Yine', 'gidiyorsun-yine-cansu-deniz-50s31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun yine yüreğimi yanına alarak,

 Gidiyorsun, bana dayanılmaz sancılar bırakarak

 Gitme desem? 

 Ya da, beni de götür desem? 

 Sevdam hiç bitmedi sana karşı

 Sanırım ölene dek bitmeyecek de

 Biliyorum yollar seni bekler,

 Biliyorum ''O'' seni bekler

 Olsun varsın varlık sebebim 

 Varsın olsun, gideceksin ya mutlu ol

 Mutluluk gideceğin yerlerde sarsın şehri

 Gidiyorsun yine ve ben derbeder, gözü yaşlı...', 'Gidiyorsun yine yüreğimi yanına alarak,  Gidiyorsun, bana dayanılmaz sancılar bırakarak  Gitme desem?   Ya da, beni de götür desem?   Sevdam...', ARRAY['Türk Edebiyatı','Şiir','Cansu Deniz']::text[], 8.5, '{"poet":"Cansu Deniz","poet_slug":"cansu-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidiyorsun-yine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyor musun', 'biliyor-musun-atila-gunal-jr206', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Asırlar geçti gibi aradan

Bana seni soruyorlar hala

Daha dün gibi her şey

Ama iki gözüm kadar uzaksın bana

Biliyor musun? 

Herkese yalan söylüyorum artık

Seni unuttuğumu söylüyorum

Umursamadığımı söylüyorum

İnanıyorlar

Çünkü inanmıyorlar böylesi bir sevdaya

Biliyor musun? 

El ele hiç yürüyemediğimizi kimse bilmiyor

Hep kuytularda seviştiğimizi

Kimse bilmiyor

Biliyor musun? 

Gözlerindeki buğuyu

Dudaklarındaki alaycı gülümseyişi

Minicik ellerini

Kabadayı yürüyüşünü

Kimseler göremedi benim kadar

Biliyor musun? 

Seni sevmediğime inanıyor herkes

Gönül eğlendirdim seninle

Artı bir sanıyorlar bende seni

O zaman neden yüreğim

Her atışında adını heceliyor

Bilmiyorsun ki

Duymuyorsun ki

Görmüyorsun ki...', 'Biliyor musun?  Asırlar geçti gibi aradan Bana seni soruyorlar hala Daha dün gibi her şey Ama iki gözüm kadar uzaksın bana Biliyor musun?  H...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/biliyor-musun-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyse', 'neyse-serkan-karabulut-u4d5j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Koşturamam istersen gel

Uzanamam öyle uzağına

Katlanamam böyle ayrılığa

Dostmuyuz sevgili mi

Ben gocunmam da öyle elin dilinden

Lakin sevmem ayrı gayrılığı 

Uzak yollar bize 

Ayırtır ikimizi

Sen başka şehirde ben başka

Kim bilir sen ne alemde

Darda mısın açıktamı

Seviyorsan düşündürme acı içinde beni

Ya gel dur bu şehirde yada 

Neyse............', 'Koşturamam istersen gel Uzanamam öyle uzağına Katlanamam böyle ayrılığa Dostmuyuz sevgili mi Ben gocunmam da öyle elin dilinden Lakin sevmem...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neyse-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-serkan-karabulut-nasf2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kulaklara seslenirken aşkın çağrısını,

Duymayanlar düşünsün,

Kapıları açıkken kalplerin,

İçeri girmeyenler düşünsün', 'Kulaklara seslenirken aşkın çağrısını, Duymayanlar düşünsün, Kapıları açıkken kalplerin, İçeri girmeyenler düşünsün...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ask-290-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa adanmış', 'yalnizliga-adanmis-serkan-karabulut-1d96w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her zaman yürüdüğüm yollardan geçtim

Koyu hüzün renginde giriydi

Siyah yalnızlık çöktü etrafa

O an hissettim ellerimde ellerinin yokluğunu

O an hissetmiştim yalnızlığımı

Kim bilir kaç kere yaşadım ben bunları

Yürüyemez oldum durmuştum sokaklarda

Ağlayamaz düşünemez tuhaf ikilemde

Yüzümü çevirdim yağmur damlalarına

Hızlı adımladım o son anlarda

Bir ışık görmüş bir umut bulmuş gibi

Geçici limanlarda

Ama hep yalnızlığa adanmış gibi', 'Her zaman yürüdüğüm yollardan geçtim Koyu hüzün renginde giriydi Siyah yalnızlık çöktü etrafa O an hissettim ellerimde ellerinin yokluğunu O...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizliga-adanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garip oyun', 'garip-oyun-serkan-karabulut-fvr3b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Garip oyun şu aşk.

Hem elendim,

Hem davet edildim.

Geniş bir problem,

Çözemedim.

Fakat çok uğraştım.

Hangisi doğru,

Hangisi yanlış? ...

Hatalarım doğrularımı,

Doğrularım da hatalarımı örttü...

Ya sen sevgili,

Ne anladın aşk’tan?', 'Garip oyun şu aşk. Hem elendim, Hem davet edildim. Geniş bir problem, Çözemedim. Fakat çok uğraştım. Hangisi doğru, Hangisi yanlış? ... Hata...', ARRAY['Türk Edebiyatı','Şiir','Serkan Karabulut']::text[], 8.5, '{"poet":"Serkan Karabulut","poet_slug":"serkan-karabulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/garip-oyun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atamın Türküsü', 'atamin-turkusu-orhan-turhan-frvcv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“Burası Huş’tur 

Yolu yokuştur

Giden gelmiyor 

Acep ne iştir? ” 

Diye babama sorduğum çok olmuştur. 

Her defasında Atamızla söze başlar,

Samsun’da  demir atar,

Oradan İzmir’e korkusuz gözlerle bakar,

Ve artık tüm damarlarda Cumhuriyet akar diye eklerdi.

Babam bu türküyü çok severdi.

Bu O’nun türküsü derdi.

Ve kızıl bir güneşin Anadolu’yu boyadığı  bir sabah,

O, Tanyerini aydınlatıverdi diye devam ederdi.

Babam bu türküyü çok severdi.

Kolay değil geçmişi unutmak derdi.

Tüm umutlarımızın tükendiği bir anda,

Postacı, özgürlük getirdi

Uzun boylu, sarışın, 

Deniz gözlü bir adamdan diye de eklerdi.

Babam bu türküyü çok severdi.

Bu bizim türkümüz derdi.

Bu topraklar hürriyet uğruna 

Yürekleri sevgi dolu nice şehitler verdi.

Karargahlarda ve savaş meydanlarında 

O yüce komutanın da çizme izleri var derdi.

Babam bu türküyü çok severdi.

Bana hep onu hatırlatıyor derdi. 

Ve geliyor yine sonbahar ertesi, ekimin sonu

Evde kışlık yakacak henüz olmasa bile 

29 Ekimler mutlu ederdi hep onu. 

Kulakları sağır eden top seslerini, 

Etrafa saçılan şarapnel parçalarını hatırlar,

Bağımsızlık ateşinde ısınarak 

Fazla önemsemezdik bu sorunu.

Babam bu türküyü çok severdi.

O’nun için, benim eşsiz Cumhuriyetim derdi.

Eminim ki sevgili babam,

Bu kutsal topraklar seni de bağrına bastığında

Yani Atamın  yanına  vardığında 

Geçmişi  tebessümle anıyor,

Geleceğe Kocatepe’den bakıyor,

Birlikte Yemen Türküsünü mırıldanıyorsunuzdur.

Atam da babam da bu türküyü çok severdi.

Her duyduğumda onlar aklıma geldi.

Biliyorum artık Atam,

Biliyorum artık babam; 

Yemene, Çanakkale’ye, Sakarya’ya gidenlerin özgürlük uğruna gittiğini

Kalanların emaneti her pahasına koruması gerektiğini,

Ekim akşamlarında  sizsiz üşürken,

Cumhuriyetin sizi gönlüme düşürdüğünü

Biliyorum artık.', '“Burası Huş’tur  Yolu yokuştur Giden gelmiyor  Acep ne iştir? ”  Diye babama sorduğum çok olmuştur.  Her defasında Atamızla söze başlar, Sam...', ARRAY['Türk Edebiyatı','Şiir','Orhan Turhan']::text[], 8.5, '{"poet":"Orhan Turhan","poet_slug":"orhan-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/atamin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüyalar Yaşanmaz', 'ruyalar-yasanmaz-hasan-can-niz0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat bir rüya aslın da,

Sen gördüğünü sandan da,

Hayat bir hayal aslın da,

Yaşandığını sansan da,

Bir düş kurarsın sonu olmaz,

Bir aşk yaşarsın yaşanan kalmaz,

Giden hiçbir şeyin yeri şimdi dolmaz,

Gündüzler gece de yaşanmaz.

Bulutsuz yağmur yağmaz,

Gecesiz ay doğmaz,

Alevsiz ateş yanmaz,

Mısrasız şiir olmaz.

Öyle bir hayal kur ki,

Hep beni yaşıyorsun san,

Öyle bir rüya gör ki,

benimle uyandığını san...', 'Hayat bir rüya aslın da, Sen gördüğünü sandan da, Hayat bir hayal aslın da, Yaşandığını sansan da, Bir düş kurarsın sonu olmaz, Bir aşk yaşa...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruyalar-yasanmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TeNiNdeKi KıZıL NokTa', 'tenindeki-kizil-nokta-mine-ozdemirtas-drdju', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', ''' '' '' '' '' '' Kızıl acılarla geldi ve 

              uzun sürdü pigmentlerine yerleşmem 

              artık                                     

              Neştersiz kazıyamayacağın 

              bir parçayım senden. 

             Adim (BEN)   “ '' '' '' '' '' ''

Dışının buz dağına gizlenen sen

İrisimin sıcağında erirken

Seni,

volkanlarının lavlarında 

bekliyor olacağım

dudağımda hep asılı kalacak

dudağından ödünç alınmış

gülümsemem

ve bende 

hiç kaybolmayacak

çoktan çözüp ezberime yazdığım

genetik şifren

bir tek damla göz yaşına

sıkışıp kalsa da ömür

bu benim tercihim

inmeyeceğim ipten

Teninde, 

minik bir noktayım artık

adım “BEN”

“alnımdan öpeceğin”güne kadar

sendeyim.

.................seninle geleceğim

................”her nereye gidersen”

16/10/2004.... Çamlıca', ''' '' '' '' '' '' Kızıl acılarla geldi ve                uzun sürdü pigmentlerine yerleşmem                artık                                  ...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tenindeki-kizil-nokta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birisini Sevdiğin Zaman', 'birisini-sevdigin-zaman-gursel-colak-k2mhj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tüm kalbinle seversen birisini

O'' nun için herşeyi yaparsın

Güneşi söndürür ay''ı karatırsın

Birisini sevdiğin zaman

Gerçekleri inkar eder

Yalanlara inanırsın

Bazende gerçekten uçtuğunu sanırsın

Ama yalnız gecelerin henüz yeni başlıyor 

Birisini sevdiğin zaman

Büyük bir duygu doğar içinde

Ve, ve hiç birşey fikrini değiştiremez

Birisini sevdiğin zaman

Sevdiğin için herşeyi feda edersin

Hiç düşünmeden herşeyi verirsin

Ne olacağını bilmeden her riske girersin

Birisini sevdiğin zaman

Birisine kalbini verdiğin zaman.......', 'Tüm kalbinle seversen birisini O'' nun için herşeyi yaparsın Güneşi söndürür ay''ı karatırsın Birisini sevdiğin zaman Gerçekleri inkar eder Ya...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/birisini-sevdigin-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emelsizliğim...', 'emelsizligim-volkan-ates-llzl3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırılmış aynaların ardında ellerin

Gün doğumundan gelme zamansız gülüşlerin

Suyun toprağa verdiği candan öte varlığın

Anlamsızlıkların anlam buluşu  ellerinde

Emelsizliğim ümitsizliğim 

Sarmış dört bir yanımı gözlerin 

Sen 

Deniz kızı

Gönlümde açtığın 

Kapanmayan hasretinden haberin var mı

Kırılmış aynaların ardına sinmiş yüzün

Eksikliğim bundan

Aramaktan bıkmadım seni

Özür göğünde vatanımın

Kanatlarımın gücünün yettiği kadarıyla değil

Varlığımın tümüyle aramaktan bıkmadım seni

Bilmezsin sen

Bilemezsin içimdeki kara kışa nasıl dolduğunu

Bilmezsin sen

Bilemezsin uykusuzluğuma giren kabusları

Aynaların ardında gözlerin

Bilmezsin sen 

Bilemezsin içimde çıkan yangınları

Dünya var olur mu güneş olmadan 

Dünyam var olur mu gülüşün olmadan 

Kırılmış aynaların ardına sinmiş 

Emelsizliğim

Seni anlatmak seni

İçime sinen bahar kokusundan 

Gözlerime dolan gözlerinden başka ne olabilir ki

Deniz toprak ateş hava su olmuşum

Yalan hepsi yalan 

Leyla olduğum Mecnun olduğum da yalan 

Sakınmışım çaresizliğimden seni

Seni anlatmak seni

Bir gecenin tek bir sabahı

Bir sevdanın tek bir anahtarı

Emelsizliğim

Eksikliğim

Yalnızlığım

Kırılmış aynaların ötesinde kalbin 

Zamansız kırılmış sonsuza yazılmış 

Barış güvercininin kanadına düş olmuş

Sen

İçime dolan bahar yağmuru

Sen

Emelsizliğim

Eksikliğim 

Yalnızlığım

Yarım kalmış yanlarım korkularım 

Sonsuzluğun kapısında senli sabahlar

Ve 

İçimde dinmek bilmeyen fırtınam

Seni anlatmak seni

Sen

Her gece yüreğine melekler konan 

Sen

Emelim

Sen 

Sonsuzluğum başlangıcım bitişim', 'Kırılmış aynaların ardında ellerin Gün doğumundan gelme zamansız gülüşlerin Suyun toprağa verdiği candan öte varlığın Anlamsızlıkların anlam...', ARRAY['Türk Edebiyatı','Şiir','Volkan Ateş']::text[], 8.5, '{"poet":"Volkan Ateş","poet_slug":"volkan-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/emelsizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesiniz?', 'nerdesiniz-mustafa-ceylan-ves01', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devlere kafa tutan

Cüceler nerdesiniz? 

Güneşi bile yutan

Geceler nerdesiniz? 

Çığ olup dağdan kopan

Peygamber gülü kokan

Hak deyu zikir yapan

Heceler nerdesiniz? 

Ey beni saran kucak

İçimde tüten ocak

Güneşten daha sıcak

Eceler nerdesinz? 

Karınca olup gülen

Uykularımı bölen

Büyüdükçe küçülen

Yüceler nerdesiniz? 

Yazlar, kışlar, baharlar

Unutulan diyarlar

Toprak olan milyarlar

Niceler nerdesiniz?', 'Devlere kafa tutan Cüceler nerdesiniz?  Güneşi bile yutan Geceler nerdesiniz?  Çığ olup dağdan kopan Peygamber gülü kokan Hak deyu zikir yap...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ceylan']::text[], 8.5, '{"poet":"Mustafa Ceylan","poet_slug":"mustafa-ceylan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nerdesiniz-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tuhafım Ben Bugün', 'bir-tuhafim-ben-bugun-ahmet-atmaca-m44ph', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir tuafım ben bugün anlat demeyin sakın

Gerçek okadar uzak, bir okadarsa  yakın

El uzatsam değecek, gelin kadere bakın

Sadece bakın diyor  ama sadece bakın', 'Bir tuafım ben bugün anlat demeyin sakın Gerçek okadar uzak, bir okadarsa  yakın El uzatsam değecek, gelin kadere bakın Sadece bakın diyor  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Atmaca']::text[], 8.5, '{"poet":"Ahmet Atmaca","poet_slug":"ahmet-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-tuhafim-ben-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serparesi Güzün', 'serparesi-guzun-i-brahim-ozcan-b9fc8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'her karesi hüzün

her paresi güzün

ince nar sızı gibi

ayrık arsızı gibi

yandaklar yatağım

palaklar otağım

can pazarı yaşam 

yaşansa da bu akşam

ne saz alır ahımı

ne de söz günahımı

kapanır kara kapılar

kanadı sırtımdan saplılar

gurbetimde misket oynar

vay yavrum malatyalılar! ..

her haresi yüzün

serparesi güzün

8 Ekim 04 Malatya', 'her karesi hüzün her paresi güzün ince nar sızı gibi ayrık arsızı gibi yandaklar yatağım palaklar otağım can pazarı yaşam  yaşansa da bu akş...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Özcan']::text[], 8.5, '{"poet":"İbrahim Özcan","poet_slug":"i-brahim-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/serparesi-guzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen iyi birisin Bianca', 'sen-iyi-birisin-bianca-erzincanli-kurt-bwkmk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen bianca çok iyi bir insansın 

sen adam gibi adamsın bianca', 'sen bianca çok iyi bir insansın  sen adam gibi adamsın bianca...', ARRAY['Türk Edebiyatı','Şiir','Erzincanlı Kurt']::text[], 8.5, '{"poet":"Erzincanlı Kurt","poet_slug":"erzincanli-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sen-iyi-birisin-bianca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol (Adımsız)', 'yol-adimsiz-salih-demirci-51a5t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Balat''taydım 

Gözüme bir cumba düştü 

Ayırınca sancımı gölgemden 

Fener''e, yokuşa döndüm 

Yine de çıkamadım 

Nedensizliğimin içinden 

Cibali''de bir sigara yaktım 

Dumanında mest öldüler kıraçeler 

O saatte konuşabileceğim 

Tek düşkün Hazarfen''di 

Galata''da beni beklerdi 

Ama 

Yeni köprü susturunca adımlarımı 

Susuzluğumda derbeder 

Düşümde naçar 

Öylesine ölgün 

Kalakaldım', 'Balat''taydım  Gözüme bir cumba düştü  Ayırınca sancımı gölgemden  Fener''e, yokuşa döndüm  Yine de çıkamadım  Nedensizliğimin içinden  Cibali...', ARRAY['Türk Edebiyatı','Şiir','Salih Demirci']::text[], 8.5, '{"poet":"Salih Demirci","poet_slug":"salih-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yol-adimsiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuşların Efendisi(1)', 'kuslarin-efendisi-1-necmiye-sarpkaya-cksn3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyordu dillerini

Kurtların kuşların 

Hükmediyordu Süleyman 

Efendisiydi bütün  hayvanların

Ve cinlerin rüzgarların

Öter horoz nazlı nazlı o sırada

Biliyor musunuz ne dediğini 

Ey! Gafiller zikredin  Rabbinizi

Ötünce Bülbül 

Yarım hurma yedim dünyada

Tavus kuşu ötünce 

Nasıl yaratıldıysan öyle ölürsün 

Sonra sevimli hüdhüd kuşu

Esirgenmez mahluku esirgemeyen

Ötünce üveyik kuşu

Hayır işleyin hayır bulun

Ötünce güvercin 

Yaratılmasaydı bu yaratıklar 

Ötünce kuzgun

Sübhane Rabbiyel Ala 

Ötünce akbabalar 

Susan kurtulur

Kuşların Efendisi bütün kuşların 

Teker teker anlatır söylediklerini 

Rüzgarlar tatlı tatlı eser 

Getirirler emirlerini yerine

Yapılan yürüyüş sırasında yemene 

Gelinince  karınca vadisine

Sultan karınca giriniz evlerinize ey karıncalar 

Ezip geçmesin Süleyman ve ordusu sizi 

Süleyman gülümser sultan karıncaya

Maiyetine sahip çıkıyor 

Hayvanlar alemi liderleri der 

Necmiye Sarpkaya', 'Biliyordu dillerini Kurtların kuşların  Hükmediyordu Süleyman  Efendisiydi bütün  hayvanların Ve cinlerin rüzgarların Öter horoz nazlı nazlı...', ARRAY['Türk Edebiyatı','Şiir','Necmiye Sarpkaya']::text[], 8.5, '{"poet":"Necmiye Sarpkaya","poet_slug":"necmiye-sarpkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/kuslarin-efendisi-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burcu', 'burcu-selcuk-ozdemir-pxanr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göz kamaştıran güzelliğinin altında 

Gizli, saklı bambaşka bir güzellik var 

Duvarların var senin kocaman, yüksek 

Kimselerin aşamadığı, kendinin bile 

Çığlık çığlığa sessizliklerin var 

Anlatmadığın onlarca şeye sustuğun 

Sert bir kabuğun var, erişilmesi zor 

O masum, kırılgan kızı koruyan 

Bir duruşun var erişilmez, uzaklarda 

Kimse bulaşmasın sana ulaşmasın ister gibi 

Büyük kısmı kilitli bir kalbin var 

Kırılıp incitilmesinden korktuğun 

Acıyı, sıkıntıyı yüklenmiş ellerin var 

Sımsıkı avuçlanmak isteyen 

Benim kalbimde bir sen var 

Bir de ümidim; 

Senin kalbinde aşk olmak', 'Göz kamaştıran güzelliğinin altında  Gizli, saklı bambaşka bir güzellik var  Duvarların var senin kocaman, yüksek  Kimselerin aşamadığı, ken...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Özdemir']::text[], 8.5, '{"poet":"Selçuk Özdemir","poet_slug":"selcuk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/burcu-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulurum Seni', 'bulurum-seni-mehmet-asim-2e11x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sen şimdi nerdesin

ellerin üşüyormu be yarim

korkuyormusun 

şehirlerin sessizliğinde

şimdi dolaşır oldu

yanlızlığın

benim şehrimde

alışırım sandım 

sanmalarım ardınca 

ağlayışlarım

yeryüzü bu kadar büyükmü be yarim

nasıl gizleneceksin benden

denizlermi aşacaksın

şehrin gürültüsünemi saklanacaksın

benim olanı nasıl 

gizleyeceksin benden....,

ah be yarim 

yarım kaldım 

yürek yarım.....

ahbe yarim.....', 'sen şimdi nerdesin ellerin üşüyormu be yarim korkuyormusun  şehirlerin sessizliğinde şimdi dolaşır oldu yanlızlığın benim şehrimde alışırım ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bulurum-seni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik', 'sensizlik-ali-gencay-j32n5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'açılır kapılar,açılır da 

ben kilitli kalırım

güneşi kovalarım,

sevda düşer peşime

gecede tutuklu kalırım

düşerim yollarında

dizlerim kan içinde

tut ellerimden

üzerime basıp geçerler diye

çok korkarım

senlik! ! 

giydiğim kalın urba

yalnızlığımda çıplak kalırım

hasret eser deli,deli

üşür tenim,donarım

ışığını ver yıldızlara

yırtılmazsa gecenin siyah perdesi

yolumu kaybeder izsiz kalırım

çocukluğumda vurduğum serçeler

kanatlarını takıp korkuluklara

çıkarlar karşıma

büzüşüp yatağımın bir kenarına 

ağlarım! ! 

o an tut ellerimden,gir koynuma

isyanlardayım

anlıyor musun! ! 

sensizlik de yargılardayım

köşeye kurulmuş örümcek 

ağı yağlı ilmek

geçirip kendi ellerimle boynuma

idamlarımdayım', 'açılır kapılar,açılır da  ben kilitli kalırım güneşi kovalarım, sevda düşer peşime gecede tutuklu kalırım düşerim yollarında dizlerim kan iç...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sensizlik-140-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara', 'ara-erol-dal-5sxu5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neyi ararsan

Onu aramak için düş yollara.

Neyi bulmak istersen; 

Onu bul.

Zira her şey 

Mevcuttur.

ED/92/Mekân', 'Neyi ararsan Onu aramak için düş yollara. Neyi bulmak istersen;  Onu bul. Zira her şey  Mevcuttur. ED/92/Mekân...', ARRAY['Türk Edebiyatı','Şiir','Erol Dal']::text[], 8.5, '{"poet":"Erol Dal","poet_slug":"erol-dal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ara-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tuz yürüyüşü |', 'tuz-yuruyusu-zafer-zengin-etnika-aomns', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kumunu sattık yolların

aşk taşırken 

elimizden kaçırdık

şimdi

sahibinden almak için

çocuk edip kendimizi

büyüdüğümüze inanmayıp

tuz yürüyüşlerine çıkıyoruz*

sancılı elbet

ağlıyoruz

| bir karışı için yüzbinler verdik |

demişti 

pos bıyıklı dede

aşk düşerse içe

taş döşersin yollara

hem gündüz

hem gece

hadi kalk

gömülecek yürek var

alınacak aşk

beklemez tuz yürüyüşü

koşalım

tabanları kalçalarımıza vura vura

yenisine

daha yenisine kavuşmadan

elmayı çalmayalım

tuz alalım

yürüyüşünü yapalım

| İnsan olmak tercihle başlıyor..bilinç yol gösteriyor |

sonra kavurma çıkarırız

bak yaralarımı sana göstermeden

kavurmam lazım

kokusu

aç kedi kadar hızlı alınır

| asla bizden olmayacaksınız..siz ki ezenden yanasınız..ezilmiş kalacaksınız..

sizin iktidarınız çeşit çeşit..haklıyız dedikçe kiralık katil gibi düşüyorsunuz yollara.. hep linç hep yağma hep yakma adınız.. bizden sakının hep karşınızda olacağız |

yürüyelim

ölüleri almayalım içimize

gelirlerse

uçurumlardan atarız gizlice

dışa vururuz

derimi yakmasaydın keşke

tuza saklamıştım

madem güneş yok

bulutlarla yanacağım

hadi gidelim 

tuz yürüyüşüne düşelim

orada aşkıda

acılarıda üleşelim

gülmek bize yakışır

gerekirse ölelim

bir gidelim

bin gelelim

| Aşk için yürüyenler görmedim.bencil.. sencil şey bu aşk

kibrit olsa yürek yakar..olmasa kimin umurunda..tuz varya çorbada

ya yoksa..ayaklanmazmıyız imparatorluğa |

tuz için yürüyelim

aşkı sevmeyelim

aşk için yürümeyelim

değersizdi

ekmeğimize katık etmeyelim

yürüyelim

| Devrim içinde direnme..sana gönderilenlerin yaptığı şeydir..kuvvet ve iktidar daima onda..adını ananları kılıçtan geçirip tutup kellesini nefret ettiğin şeytana** adama..sonun başlangıcı onda gelip oturacak yanına..sen olsanda olmasanda |

hadi gidelim

medem ki sertiz 

ve kıracağız zincirleri

şimdi gürle

dök teslim olduğun

sorgulamadın düşünceleri

yürümeyi bilmeyen dizlerinin dibine

neyi sınarsın

kime sınanırsın

düştüğün yerde

debelenme

haydi gidelim

06.10.2004

* Tuz yürüyüşü; Gandhi ve arkadaşlarının 1930''da, tuzun britanya''nın tekelinde

bulunmasını protesto etmek amacıyla gerçekleştirdikleri 24 gün süren yürüyüş

| Hayvan Dergisi | ekim 2004 Sayısı

**şeytan kötü.. melek insan aklının başardıkları yanında olgunlaşmamış arada kalmış..ezip geçemedi bilinci..yıkamadı çeperlerini.. sorgulamadan yapan insan belki..', 'kumunu sattık yolların aşk taşırken  elimizden kaçırdık şimdi sahibinden almak için çocuk edip kendimizi büyüdüğümüze inanmayıp tuz yürüyüşl...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":80,"source_url":"https://www.antoloji.com/tuz-yuruyusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Senden İbaretmiş', 'hayat-senden-i-baretmis-ali-akceken-u1yuh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokluğunda anladım bu kadar zor olduğunu

Meğer her şeyimmişsin ceylan bakışlım.

Ekmek gibi,su gibi,aldığım nefes gibi

Tütünden betermiş inan alışkanlığın

Hayat senden ibaretmiş.

Bütün kuşlar göç ettiler ardından

Denizler kuma,renkler siyaha dönüştü.

Bir tek insan kalmadı mı dünyada,

Aklıma gelmezdi böylesi bir yalnızlık

Hayat senden ibaretmiş

Tadı kalmadı doğan günün sabahlarımda

Artık ısıtmıyor güneş buz kutbu avuçlarımı

Düşlerim silik,ümitlerim mum gibi erimekte

Hâyâllerim yetmiyor beni avutmaya gülüm

Hayat senden ibaretmiş.

Nerde o eski gülüşlerim,o coşku,o mutluluk

O kara gözlerine bağladığım çılgın  gençliğim

Dokunmaya kıyamadığım,koklamaya doyamadığım

Bütün hücrelerimi sarsan o heyecan, o aşk

Hayat senden ibaretmiş

Zaman makası daralmakta ve sen yoksun yanımda

Beni hayata bağlayan o can simidim yok

Meğer bomboş bir yalanmış bu kahpe dünya 

Tek gerçek senmişsin ömrümce yaşadığım

Hayat senden ibaretmiş…', 'Yokluğunda anladım bu kadar zor olduğunu Meğer her şeyimmişsin ceylan bakışlım. Ekmek gibi,su gibi,aldığım nefes gibi Tütünden betermiş inan...', ARRAY['Türk Edebiyatı','Şiir','Ali Akçeken']::text[], 8.5, '{"poet":"Ali Akçeken","poet_slug":"ali-akceken","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayat-senden-ibaretmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-muhsine-i-pek-yov0n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bütün kalbimle

Tanrıya yakarıyorum

Yunak taşında dövülmüş şu yüreğimle

Yakarıyorum

Maviş gözlerin buğulanmasın

Hep gülsün

Solmasın gülen yüzün

Baharları yaşasın

Aşk yangınların yansın

Yansın yansın bitmesin

Yüreğindeki gönül tellerin

Gönül tellerin rüzgarsızda titresin

Gönlünün yerini bulması için 

Bırak

Bırak bırak da yüreğin kendisi bulsun

Sen canım

Sen var ya  canım oğlum

Maviye tutkun ebedi olsun', 'Bütün kalbimle Tanrıya yakarıyorum Yunak taşında dövülmüş şu yüreğimle Yakarıyorum Maviş gözlerin buğulanmasın Hep gülsün Solmasın gülen yüz...', ARRAY['Türk Edebiyatı','Şiir','Muhsine İpek']::text[], 8.5, '{"poet":"Muhsine İpek","poet_slug":"muhsine-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/dua-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz Gözlüm', 'deniz-gozlum-muhsine-i-pek-mefaq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Falezlerden bir çığlık geldi kulağıma

Yağmur çocuk yağıyordu koylara

Ateş de yanan güller gibi yüreği

Haykırıyordu Akdeniz semalarına

Sevgisi kızıl bir şarap

Yüreğinde sunuyordu sevdalılara

Gönül gözü açık

Kavi gönüllüm sevdalım

Yüreği çoşkun bir ırmak

Bazen engin bir deniz

Bazende sığ bir koy

Yağmur çocuk unutma beni

Beni de  yüreğine koy', 'Falezlerden bir çığlık geldi kulağıma Yağmur çocuk yağıyordu koylara Ateş de yanan güller gibi yüreği Haykırıyordu Akdeniz semalarına Sevgis...', ARRAY['Türk Edebiyatı','Şiir','Muhsine İpek']::text[], 8.5, '{"poet":"Muhsine İpek","poet_slug":"muhsine-i-pek","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/deniz-gozlum-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özet', 'ozet-olcay-kose-x3a0t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kime inat ediyorki

bu sevda

kalbi kırık

yüzü yaralı

kime', 'kime inat ediyorki bu sevda kalbi kırık yüzü yaralı kime...', ARRAY['Türk Edebiyatı','Şiir','Olcay Köse']::text[], 8.5, '{"poet":"Olcay Köse","poet_slug":"olcay-kose","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ozet-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suyu çeker |', 'suyu-ceker-zafer-zengin-etnika-9gzv3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'martılar

çarpar mı

ellerime

büyüsem

gözlerinde

görmem 

lazım

dön 

bak

kızkulesine

uzak

koşamam

suyu

çeker

boğazın

ayaklarımda

uyuşmalar

| her gidenin öyküsü var biliyorsun..

uzağa gitmesede kimi yazarlar öykülere..

anlamadım büyümek için acelen ne |

bu şarkı bitsin

günde düşsün denize

bu karanlıkta

kimse tanımaz 

ışıklı şehirde

beni bu yalnızlıkla

sen de git kalma

04.09.2004', 'martılar çarpar mı ellerime büyüsem gözlerinde görmem  lazım dön  bak kızkulesine uzak koşamam suyu çeker boğazın ayaklarımda uyuşmalar | he...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/suyu-ceker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Bulmak', 'dost-bulmak-abbas-yurt-dabnz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimisi var bir dost için can verir,

Kimisi de içten vurur devirir,

Tutar seni doğru yoldan çevirir,

Bu asırda bir dost bulmak güç olur.

Kimisi her an korur dostunu,

Kimisi de yüzer satar postunu,

Sevmez ise alır senin gastını,

Bu asırda bir dost bulmak güç olur.

Arkadaştır hiç bimezsin huyunu,

Birden yapar ali cengiz oyunu,

Bir bakarsın paran çekmiş suyunu,

Bu asırda bir dost bulmak güç olur.

Kardeş derde sarılırsa boynuna,

Açıkgöz olur sakın gelme oyuna,

Birgün yılan olur akar koynuna,

Bu asırda bir dost bulmak güç olur.

Kapını açar götürürsün evine,

Elin değer boş kazanın dibine,

O sende yer bakar kendi keyfine,

Bu asırda bir dost bulmak güç olur.

Demez ulan bu arakdaştır yazık,

Becerirse hergün koparır azık,

Öz kardeşinde bile yersin kazık,

Bu asırda bir dost bulmak güç olur.

Yobaz, bilmez insanın kıymetini,

Ne edecem böyle insanın methini,

Yamyam gibi yerler insan etini,

Bu asırda bir dost bulmak güç olur.

Geçer isen birgün dostun rastında,

Dost kazığı yersin hemen dostundan,

Vallahi çarık yaparlar postundan,

Bu asırda bir dost bulmak güç olur.

Fukaraysan çıkarmazsın sesini,

Hergün alır senden nevalesini,

Bir çırpıda keserler nefesini,

Bu asırda bir dost bulmak güç olur.

İyi insana kapımızı açarız.,

Kötülerden uzaklaşır kaçarız,

Bir dost bulamadık çabuk kocarız,

Bu asırda bir dost bulmak güç olur.

Abbas''ım insanı mert ederim,

Vallahi doğrudur dediklerim,

Beğenmezsen sazım alıp giderim,

O zaman emeklerim hiç olur.

18.04.1978', 'Kimisi var bir dost için can verir, Kimisi de içten vurur devirir, Tutar seni doğru yoldan çevirir, Bu asırda bir dost bulmak güç olur. Kimi...', ARRAY['Türk Edebiyatı','Şiir','Abbas Yurt']::text[], 8.5, '{"poet":"Abbas Yurt","poet_slug":"abbas-yurt","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/dost-bulmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Gelir', 'an-gelir-ergun-terzioglu-gx9yv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'An gelir; 

      Asırlar saniye, saniyeler asır olur,

      Var olan yok olur, yok zaten yoklukta...

An gelir; 

      Dil kırılır kuytuda, göz topal olur,

      ''Hiç'' gibi kalıverir sevdan ortada...', 'An gelir;        Asırlar saniye, saniyeler asır olur,       Var olan yok olur, yok zaten yoklukta... An gelir;        Dil kırılır kuytuda, g...', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/an-gelir-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-asim-kisbet-2i74a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karahallıda doğmuşum

Soğuk eylül sabahında

Anamdan dinledim

Yağlı tezgahları

Simav da bıraktım

Gençliğimin baharını

Anılarımın asılı bulunduğu

Hisar duvarlarında

Akpınara dilek tuttum

Bir mayıs sabahı

Duygularımı yıkadım

Gölcük yaylasında

Elleri ellerimde kayboldu

Karıştım simav çayına

Umutlarımla aktım marmara ya

Bir bahar sabahı karşıyakadan

Güvercinleri saldım eynal''a

Zaman olup simav dağlarını aştım

Yol verdi simav dağları', 'Karahallıda doğmuşum Soğuk eylül sabahında Anamdan dinledim Yağlı tezgahları Simav da bıraktım Gençliğimin baharını Anılarımın asılı bulundu...', ARRAY['Türk Edebiyatı','Şiir','Asım Kısbet']::text[], 8.5, '{"poet":"Asım Kısbet","poet_slug":"asim-kisbet","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-128-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkular', 'korkular-metehan-bilmem-z5zhn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatında bir yığın insan olsada yalnızsın aslında

Ama sen bunun adını koyamasın

Başada öıkamasın yalnızlığınla

Sen duvarlarla konuşamasın usata

Kendini acımasızca eleştiremez

Yerden yere vuramasın iç dünyanı

Sen korkularınla yüzleşemesin korkarsın korkularında 

Sabahı bekleyen saatlarde

Sabahları yalnız uyuyamasın sen

bir ten ararsın hep

Ve o ten için hercarsın

Hayatının en güzel yıllarını

Sen özgürlüğü bedelsiz istiyorsun dostum 

İşte tam bu noktada 

Yalnızlık uymuyorsana

Yalnızlıktamamıyla kendine güvendir usta

Kendi kendini eleştirmek,

Kendi kendinle konuşmak,

Kendini yargılamak,

Kendini anlamaktır aslında.

Sen sesizliktende korkarsın biliyorum.

Gece yarısının ötesinde yoksun sen

Saattin sabahı hatırlattığında 

Kim bilir  kaçıncı mutluluk rüyasında bulursun kendini

Ve sen bana aşkı bulamadığından yakınıyorsun 

Ne zaman karşılaşsak 

Sen aşkı bulamasın usta 

Kıytırık derinliği olmayan, 

Mantığın her zaman en önde yer aldığı 

İlişkiler düşecektir senin payına

Çünkü aşk yalnız gezer ve ancak 

Gece kadar ıssız kalplere sızar', 'Hayatında bir yığın insan olsada yalnızsın aslında Ama sen bunun adını koyamasın Başada öıkamasın yalnızlığınla Sen duvarlarla konuşamasın u...', ARRAY['Türk Edebiyatı','Şiir','Metehan Bilmem']::text[], 8.5, '{"poet":"Metehan Bilmem","poet_slug":"metehan-bilmem","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/korkular-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitemin...', 'sitemin-osman-guzelgoz-6p7dq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sitemin kurşun gibi ağır

bakışın dağlar kadar yüce

ben ürkek

ben garip 

ben mahzun

beklerim sokaklarda her gece

günahımı bilmeden sessizce

sabahlara uzanır ellerim

gözüme uyku girmeden

sitemin kurşun gibi ağır

bakışların dağlar kadar yüce

istersen...

çekilirim bu meydan savaşından

sessiz ve gizlice

ben yaralı

ben şaşkın

ben pişman

dolaşırım sokakları her gece

günahamı bilmeden sessizce...', 'sitemin kurşun gibi ağır bakışın dağlar kadar yüce ben ürkek ben garip  ben mahzun beklerim sokaklarda her gece günahımı bilmeden sessizce s...', ARRAY['Türk Edebiyatı','Şiir','Osman Güzelgöz']::text[], 8.5, '{"poet":"Osman Güzelgöz","poet_slug":"osman-guzelgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sitemin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Kaldırış ! ! !', 'bas-kaldiris-zafer-zengin-etnika-j71gd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BAŞ KALDIRIŞ (sezer nişancının yasaklanan şiiri)

bu şiir sezer nişancının antoloji yetkilileri tarafından yasaklanan şiiridir.... 

İbadeti uluorta yapmak da neyin nesi? 

Gülüyor batılı sana,çıkar başından fesi. 

Cumhuriyet için şehit oldu,müftüsü –efesi 

Devrim! adını anmayanlar için yazacağım her bir dizemi. 

Görünürse saçın teli caiz olmazmış. 

Dört karı bir evde günah olmazmış. 

Şeriatın kestiği parmak acımazmış. 

Öldürülen,kalem parmaklar için yazacağım her bir dizemi. 

Ata’ma kinin dizenden belli. 

Başındaki türban neyin sembolü? 

Elinde tespih değil,kalem olmalı 

Layık olmayan ellere düşen,milletim için yazacağım her bir dizemi. 

Sultan alkışlamaktan patladı avucunuz. 

Kurtuluş savaşımı benden önce övdünüz. 

Devrim! Lafında arkalarda kaldınız. 

Cumhuriyetim-devrimlerim için yazacağım her bir dizemi. 

Yüzseler derimi Nesimi gibi 

Kesseler başımı Kubilay gibi. 

Eğmeyeceğim başımı,sarıklıya,mir’e-pir’e. 

Aydınlık yarınım için yazacağım her bir dizemi. 

Söz söyleme hürriyetimi kullandım. 

İnsan ayırımı yapan kuldan huylandım. 

Cumhuriyet kadınıyım,elim kalem tutuyor. 

Meydan size mi kaldı? 

Uyan Ey Halkım! 

Laik Vatanım elden gidiyor. 

Yurdumu satanlar için yazacağım her bir dizemi. 

SEZER NİŞANCI

*Çoğunluğun kararıyla azınlığı ezerseniz demokrasiyi lekelersiniz..dikkat! ! ! 

Bu vatana birşey olmaz kolay kolay sezer hanım..sahipsiz değil..ayrıca bence onore olmalısınız..epey tepki almış..suya sabuna dokunmayan şiir yazsaydınız kimse yasaklatmazdı şiirinizi..sonra şairin ozanın işi sorgulamak hesap sormak uyarmaktır..ben bildim bileli böyle..MEMLEKETİM SAHİPSİZ DEĞİL..Sansüre..küfre ve linçe hayır! !', 'BAŞ KALDIRIŞ (sezer nişancının yasaklanan şiiri) bu şiir sezer nişancının antoloji yetkilileri tarafından yasaklanan şiiridir....  İbadeti u...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/bas-kaldiris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen benim aşkım olduğun günden beri', 'sen-benim-askim-oldugun-gunden-beri-selcuk-ozdemir-4omi6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hayatımı sana endekslemişim 

Sen vazgeçilmez tutkum olduğun günden beri 

Yaşam gâyesini sana bağlamışım 

Kaptırdım kendimi fenâ bir şekilde 

İçimdeki coşkuların, duyguların esiri olmuşum 

Seni düşünmek mi diyorsun? 

Güldürme! ... 

Acabâ aklımdan çıkarıyor muyum? 

Dalıyorum öyle derinlere 

Şaşkınlık denilen kelimeyle arkadaş olmuşum 

Sükûnet, yaa işte o sükûnet 

Varlığınla erişebileceğim bir hal olsa gerek... 

Kalbe önlenemez çarpıntı veren, hasret ve özlem 

Bir de yüzümdeki acı tebessüm 

Mırıldanıyorum sessizce 

İki dudağımdan dökülen iki kelime 

Seni seviyorum... 

Çoğu zaman haykırmak istiyorum bunu 

Lâkin olmuyor... 

Duyuramıyorum kimselere 

Gülüm, nâzenin yârim... 

Çün ki sen yoksun yanımda 

Ama olsun 

En azından içimde kopan fırtınalara 

Fâsıla bulmayan şiddetli kasırgalara 

Kucak açıp, yüklenen kâğıdım var önümde 

Bir de sırdaşım, özümün tercümânı kalemim 

Âh bir bilsen; 

Sensiz geçen dakikalarda, saatlerde, günlerde 

Neler yazıyoruz kalemimle... 

Ne hayaller kuruyoruz kavuşmak uğruna 

Tabi sen bunların hepsinden habersizsin 

Yalnız şu var ki; 

Bence kalemimi dâhi kıskanır dereceye getiriyor bu duygu yükü 

Bazen de üzüyor kanaatimce 

Ve her şeye rağmen, o şaşmaz gerçek çıkıyor ortaya 

Gönlümün sultânı, biliyor musun? 

Ben var ya ben, 

Seni çok seviyorum be burcu', 'Ben hayatımı sana endekslemişim  Sen vazgeçilmez tutkum olduğun günden beri  Yaşam gâyesini sana bağlamışım  Kaptırdım kendimi fenâ bir şeki...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Özdemir']::text[], 8.5, '{"poet":"Selçuk Özdemir","poet_slug":"selcuk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/sen-benim-askim-oldugun-gunden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünyaya Yolculuk ve İlkler', 'dunyaya-yolculuk-ve-i-lkler-mehmet-lutfu-aydin-vfcu1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yoktum önceleri; ezeldeydim, daha doğmamış 

Görmüyordum; işitmiyordum; ağzım var, dilim yoktu; konuşamıyordum

Saftım; bir melektim; yaşıyordum kendimce mutlu, doğmadan önce

Bırakmadılar

Fırlatıldım bir dünyaya, tanımadığım

Sormamışlardı bana; bir hiçtim, hiçe sayılmıştım

Küçülmüştüm

Binlerce felâketin habercisiydi ilk çığlığım 

Sevince boğulmuştu çığlığımı duyanlar; gelecekten habersiz

İlk soluğum korkunçtu; bir devasa hortumdu; yutmuştum tüm evreni

Bir anda

Yapışmıştı ciğerime salkım saçak pislikler

Kötülükler yerleşti, yurt edindi içimi; serpildi, büyüdü ağır ağır

Şişti, olgunlaştı giderek; bir volkana dönüştü; patladı kükreyerek

Yer, gök aydınlandı kıpkızıl; kötülük tohumları saçıldı dört bir yana

Tutuştu iyi olan ne varsa; yandı küle döndü 

Bir mini Big Bang’di yaşanan 

Karardı her yer sonra 

Sessizliğin sesi çınlıyordu kulaklarımda

Şaşkındım

Masumdu ilk bakışım; aldanmıştım sevinçlere 

Boşaymış kaygılarım; kanmıştım; inanmıştım çevremde fır dönenlere

Emeklemeler; ilk adımlar; ilk yürüyüşler

İlk konuşmamda havalara uçmuştu babam; annem üzülmüştü biraz 

Anne demediğim için ilk

İlk kez pişman değildim dünyaya geldiğime

Hayat hep böyle güzel geçecek sanmıştım

Yanılmıştım

Bebekliğim geride kalmış

Büyümüştüm

Okula ilk gidişim, ilk ayrılışımdı annemden

Ağlamıştım

Mahinur öğretmenim yatıştırmıştı beni; sevmiştim onu

Bağlanmıştım

Delikanlılık çağım; ilk kez âşık olmuştum; ilk kez el el eydik

Ihlara vadisinde

Söz kesmiştik; okul bitince evlenecektik

Tez bitmişti ne yazık; sadakati anlamadan ihaneti tatmıştım

Kahırlanmıştım

Gün güne, günler aya eklendi; yıllar su gibi aktı geçti

Fışkırttığım kötülükler yine bana dönmüştü

Ne Zeus ne Olympos’un tanrıları görmüştü öldüğümü

Gaflet uykusundaydılar

Üşüşmüştü virüsler; susuz kalmış aç çakaldan arsızdılar

Düşüyordu organlarım birer birer; zapt edilmiş kaleden farksızdılar

Umarsızlık büküyordu belimi

Tek umudum kalmıştı; geldiğim yere dönmek

Hiç olmadığım yerde bir hiç olduğum yere yani

Yani yok olduğum; sayılmadığım yere 

Yani bildiğiniz üzere

O sonsuz ezele

Mutlu olduğum yere yani

Bir melektim hani

Saf

 …', 'Yoktum önceleri; ezeldeydim, daha doğmamış  Görmüyordum; işitmiyordum; ağzım var, dilim yoktu; konuşamıyordum Saftım; bir melektim; yaşıyord...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Lütfü Aydın']::text[], 8.5, '{"poet":"Mehmet Lütfü Aydın","poet_slug":"mehmet-lutfu-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/dunyaya-yolculuk-ve-ilkler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Isla gözlerinle |', 'isla-gozlerinle-zafer-zengin-etnika-7ipe2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'korkardın

sessiz 

gecelerden

ağlardın

gül

kokusu

dokunsa

kurumasın

hasretin

gözlerinde

sula

emanet

bıraktım

mektupları

turnalara

okurken

gözlerinle

ısla

boyama

ellerimi

ölümle

gel

de

04.10.2004', 'korkardın sessiz  gecelerden ağlardın gül kokusu dokunsa kurumasın hasretin gözlerinde sula emanet bıraktım mektupları turnalara okurken göz...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/isla-gozlerinle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Varsın', 'sen-varsin-ahmet-altintas-nltf2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum

Gün doğar iken gözlerimi açtığımda

Belki uyuyorsundur 

Saflık ve güzelliğinle

Mutfakta kahvaltı masamda

Seni düşünüyorum

Gözlerimi açtığımda 

Seninle olmak isterdim

Sende düşünüyormusun

Derslerinde teneffüs saatlerinde

Düşünüyormusun

Bir resmin olsa idi elimde

Seni düşünüyorum tüm benliğimle

Akşamın hüznü çöktüğünde

Hissediyorum seni her an yüreğimde

Sende düşünüyormusun

Seni görüyorum gökyüzünde

Gözlerin yıldızlar kadar uzak olsada

Seni düşünüyorum

Ya sen birtanem....', 'Seni düşünüyorum Gün doğar iken gözlerimi açtığımda Belki uyuyorsundur  Saflık ve güzelliğinle Mutfakta kahvaltı masamda Seni düşünüyorum Gö...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-varsin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İki Dostuz', 'biz-i-ki-dostuz-hasan-can-8nwvg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biz iki dostuz,

Kardeşten öteyiz,

Bizi kimse ayıramaz,

Ölene dek beraberiz.

Biz iki dostuz,

Biraz duygusal biraz sefiliz,

Sevdamızı yüreğimizde taşırız,

Biraz serseriyiz ama ölümüne severiz.

Biz iki dostuz,

Sessiz esen rüzgarız,

Dalgalarla savaşırız,

Çığlıklarda uyanırız.

Biz iki dostuz,

Hayat nereye iterse oradayız,

Gittiğimiz yerde kalmayız,

Ömür boyu sürgün yaşarız...

Biz iki dostuz,

Dostluk sevdamız,

Tesbih silahımız,

Sevgili namusumuzdur...', 'Biz iki dostuz, Kardeşten öteyiz, Bizi kimse ayıramaz, Ölene dek beraberiz. Biz iki dostuz, Biraz duygusal biraz sefiliz, Sevdamızı yüreğimi...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can']::text[], 8.5, '{"poet":"Hasan Can","poet_slug":"hasan-can","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/biz-iki-dostuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümse', 'gulumse-songul-ucar-y236o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gülümse..! 

Sende hasretsin biliyorum,

En az benim kadar...

....İçten,

........sıcak,

............umutla dolu gülücüklere..

Öyle hasretimki çocuk yüreğimle,

........doyasıya gülmelere...

Öyle hasretimki..! 

........ciğerlerim yırtılırcasına koşmalara

Haydi koş! 

Sende hasretsin biliyorum...

Koş çocuklar gibi! 

.........korkma! 

Öyle hasretimki savunmasız bir dost yüreğine...

Haydi dost ol benimle! 

Güven bana..! 

.........Korkmadan, 

............. utanmadan güven bana,

..................yormayacak dostluğum seni.

......................Yıkmayacak yok etmeyecek güvenini.

Öyle hasretimki deliksiz bir uyku çekmeye sabaha kadar...

Saçma sapan rüyalar görmeye...

Haydi kolkola yatalım,

.........yürek yüreğe,

............. korkma ısırmam...

...................Sarılırım ama sıkmam.

Ne olur dönelim çocuklumuza korkma ağlamam.

Sarılırım umuda,

Safbe saf duygulara...

Sevgilere...

Birdaha asla bırakmam...', 'Gülümse..!  Sende hasretsin biliyorum, En az benim kadar... ....İçten, ........sıcak, ............umutla dolu gülücüklere.. Öyle hasretimki ...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gulumse-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ahmet-altintas-haqlm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle güzel ki gözlerin

Yakut gibi,zümrüt gibi,inci gibi

Lale gibi,gül gibi, sanki kır çiçeğim

Eşin hiç yok benzerin olamaz

Geldiğinde tomurcuklar gül olup açar

Üzmezsin hiçbir an gülümsemen mutluluk saçar

Zaman akıp giderken,gönüllere su saçarsın

Ellerinde mutluluk var,hep sende yaşarsın

Lal olup susarın anlatamam seni sana

Keşke deyip susarım, acizlikten 

İsterdim bir ömür birlikte seninle 

Sendedir güzellikler mutluluk, dünyamsın

Ellerin dert görmesin yüreğin hiç yanmasın

Versin dilerim yaratandan,yüreğinin isteğini 

Dudağımdan dökülürken kelimeler

Allah’a yalvarırken diz çöküp niyazımda

Ne olur sağlık mutluluk ver dualarımda', 'Öyle güzel ki gözlerin Yakut gibi,zümrüt gibi,inci gibi Lale gibi,gül gibi, sanki kır çiçeğim Eşin hiç yok benzerin olamaz Geldiğinde tomurc...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-463-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mucize', 'mucize-songul-ucar-tn4sx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir mucize olsa çıksan karşıma,

Ağaçlar çiçek açardı, çiçeklerde SEN! 

Bir mucize olsa, gelsen yanıma,

Mevsimler bahar olurdu, baharlarda SEN! 

Bir mucize olsa baksan gözlerime, 

Yürekler sevgi dolardı, sevgilerde SEN! 

Bir mucize olsa, öpsen dudağımdan,

Bedenim alev alırdı, alevlerde SEN! ! !', 'Bir mucize olsa çıksan karşıma, Ağaçlar çiçek açardı, çiçeklerde SEN!  Bir mucize olsa, gelsen yanıma, Mevsimler bahar olurdu, baharlarda SE...', ARRAY['Türk Edebiyatı','Şiir','Songül Uçar']::text[], 8.5, '{"poet":"Songül Uçar","poet_slug":"songul-ucar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mucize-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boran Boran', 'boran-boran-yavuz-agir-ijxdy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmem halim kime soram

Yağmur yağar boran boran

Bülbüller boyun bükmüş 

Bilmem halim kime soram

Hazan gelmiş buram buram

Düşen yapraklara soram

Güller hep seni sormuş

Bilmem bunu neye yoram', 'Bilmem halim kime soram Yağmur yağar boran boran Bülbüller boyun bükmüş  Bilmem halim kime soram Hazan gelmiş buram buram Düşen yapraklara s...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/boran-boran-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Beriye', 'gel-beriye-yavuz-agir-6ofhx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökkuşağı görünür mü

Al yeşile bürünür mü

Saçın yerde  sürünür mü

Gel beriye, dön geriye

Gün batımı bir hoş olur

Aşk şarabı içenler sarhoş olur

Kendinden geçenler bir hoş olur

Gel beriye, dön geriye', 'Gökkuşağı görünür mü Al yeşile bürünür mü Saçın yerde  sürünür mü Gel beriye, dön geriye Gün batımı bir hoş olur Aşk şarabı içenler sarhoş o...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-beriye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suna Boylum', 'suna-boylum-yavuz-agir-c6abg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hangi gönlün sultanısın 

Gah konarsın, gah göçersin

Bilmem kime için dökersin

Suna boylum, güzel huylum

Giyinirsin güzel elbiseleri

Renk renk olur desenleri

Bakmaya kıyamıyorum

Suna boylum, güzel huylum

Ardın sıra koşmaktan yoruldum

O mahmur bakışlarına vuruldum

Çok bulanıktım şimdi duruldum

Suna boylum, güzel huylum', 'Hangi gönlün sultanısın  Gah konarsın, gah göçersin Bilmem kime için dökersin Suna boylum, güzel huylum Giyinirsin güzel elbiseleri Renk ren...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/suna-boylum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-yavuz-agir-lluye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekledim yolunu hiç gelmez oldun

Yaşaran gözyaşımı silemez oldum

Hasretlik çok uzak geldi bize

Gönlümü gönlüne katamaz oldum 

Serhatlar büyüdü, baş edemez oldum

Elveda deyip gidemez oldum

Yemekten içmekten kesildim, kara gözlüm

Derdimi kimseye dökemez oldum

Sıla bize oldukça zor geliyor

Ekmeğimiz aşımız az geliyor

Çok çileler çeksek de 

Eksikliğin bize ar geliyor

Dön artık karagözlüm dön! 

Serhat senin, gün senin, yar senin

Koyma bizi bu yerlerde

Çünkü ölüm bize az geliyor.', 'Bekledim yolunu hiç gelmez oldun Yaşaran gözyaşımı silemez oldum Hasretlik çok uzak geldi bize Gönlümü gönlüne katamaz oldum  Serhatlar büyü...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Ağır']::text[], 8.5, '{"poet":"Yavuz Ağır","poet_slug":"yavuz-agir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kara-gozlum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağ başlarında asi bir gülsem', 'dag-baslarinda-asi-bir-gulsem-ozkan-yildirim-apgy5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dağ başlarında asi bir gülsem

Yargülü,   bir  sana  hasretsem

Şafakta  sevda canı vermişsem

Yar, seni vatan diye sevmişsem

Bu can sana, vatan kadar hasret.

.. .. .. .. .. .. .. .. .. .. .. .. .

Mapuslarda   filize  durmuşsam

Sürgünde sevda  gülü açmışsem

Kavgada Gürkan`ımla akmışsam

Yarim, vatanda  seni  sevmişsem

Bu can  sana  vatan  kadar hasret', 'Dağ başlarında asi bir gülsem Yargülü,   bir  sana  hasretsem Şafakta  sevda canı vermişsem Yar, seni vatan diye sevmişsem Bu can sana, vata...', ARRAY['Türk Edebiyatı','Şiir','Özkan Yıldırım']::text[], 8.5, '{"poet":"Özkan Yıldırım","poet_slug":"ozkan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dag-baslarinda-asi-bir-gulsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cihân', 'cih-n-sair-ahrazi-4mmty', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu gördüğüm gâibse,gezdiğim yer de nesi? 

Altımda bir cihan var ayyuksa kum tanesi…

* * *

Ayyuk: Göğün en yüksek yeri.', 'Bu gördüğüm gâibse,gezdiğim yer de nesi?  Altımda bir cihan var ayyuksa kum tanesi… * * * Ayyuk: Göğün en yüksek yeri....', ARRAY['Türk Edebiyatı','Şiir','Şair Ahrazi']::text[], 8.5, '{"poet":"Şair Ahrazi","poet_slug":"sair-ahrazi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/cihan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-ahmet-altintas-krk0x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaman zaman sensizliğe alışmak 

Senden bi haber olmak istiyorum

Sadece seni üzdüğümü düşünerek

Yapamıyorum biriciğim

Zaman zaman lanetler ediyorum kendime

Set çek der gönül yüreğinin bendine

Yapamıyorum biriciğim

Belli ki yılların verdiği özlemle

Yalnızlığımın sonucu bağlandım sana

Mutluluk veriyorsun varlığınla

Yanımda olmasanda her an bana

Kendimi anlatamıyorum inan sana', 'Zaman zaman sensizliğe alışmak  Senden bi haber olmak istiyorum Sadece seni üzdüğümü düşünerek Yapamıyorum biriciğim Zaman zaman lanetler ed...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sitem-107-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suç Öyle mi', 'suc-oyle-mi-nedim-saatcioglu-qrqrx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rüya bitti vakit artık 

Geç diyorsun geç öyle mi

Şimdi sana geri dönmem

Güç diyorsun güç öyle mi

Dünde kaldı güzel anlar

Dünde kaldı heyecanlar

Aramızda yaşananlar

Hiç diyorsun hiç öyle mi

Bana dair her bir cümle

Yasaklandı bundan böyle

Hayalimi kurman bile

Suç diyorsun suç öyle mi

Ben an dedim sen geç dedin

Ben dön dedim sen güç dedin

Ben dün dedim sen hiç dedin

Hep suç dedin suç öyle mi

========================================== 

Beste ; Gülsen Yurdakul Kürkçü

Albüm ; Yusuf Dede', 'Rüya bitti vakit artık  Geç diyorsun geç öyle mi Şimdi sana geri dönmem Güç diyorsun güç öyle mi Dünde kaldı güzel anlar Dünde kaldı heyecan...', ARRAY['Türk Edebiyatı','Şiir','Nedim Saatcioğlu']::text[], 8.5, '{"poet":"Nedim Saatcioğlu","poet_slug":"nedim-saatcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/suc-oyle-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin', 'bilirmisin-ahmet-altintas-xojer', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilir misin sevgiyi

Yaşadın mı hiç

Sevebildin mi

Yakalayabildin mi mutluluğu

Yaşıyor musun an be an erirken

Sevdiğinden haber alamamayı

Onun yokluğunu hissettin mi

Söyle bir tanem

Biliyorum ağlama ne olur meleğim

Seviyorsun sende umarsızca

Ama korkuyorsun gülüm

Hep yüreğini cezalandırıyorsun

Unutma emi zarar gelmez benden sana

Gitme ver sendeki seni bana

Bern teslim olup verdim kendimi sana

Sen öğrettin sevgiyi mutluluğu yaşattın

Birlikte tatmadık mı birbirimizden uzak

Yoksunlukta hislerimizde...', 'Bilir misin sevgiyi Yaşadın mı hiç Sevebildin mi Yakalayabildin mi mutluluğu Yaşıyor musun an be an erirken Sevdiğinden haber alamamayı Onun...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altıntaş']::text[], 8.5, '{"poet":"Ahmet Altıntaş","poet_slug":"ahmet-altintas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilirmisin-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kınalı Bahtı Karam', 'kinali-bahti-karam-ahmet-hakan-yilmazturk-wlffk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gecenin sıcağı

bağrıma dayandı

soluksuz düşler

gözüme saplandı

süzüldü boynumdan

birkaç damla ter

üşüdü sırtım

titredi her yer

uyandım birden

karanlık odamda

boşuna gezindi

seni arayan gözler

siyahtı eller

siyahtı yüzler

çığlık çığlığa

ölüydü sesler

giyindim gittim

Ortaköy’de iskeleye

seni sordum çınara

sahildeki kediye

siyahtı bulutlar

siyahtı umutlar

çığlık çığlığa

pervasız martılar

kırıldı filizlerim

zamansız fırtınanla

uçtun elimden

kınalı bahtı karam

28.09.1993', 'gecenin sıcağı bağrıma dayandı soluksuz düşler gözüme saplandı süzüldü boynumdan birkaç damla ter üşüdü sırtım titredi her yer uyandım birde...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hakan Yılmaztürk']::text[], 8.5, '{"poet":"Ahmet Hakan Yılmaztürk","poet_slug":"ahmet-hakan-yilmazturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kinali-bahti-karam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ismi lazim degil', 'ismi-lazim-degil-nurten-kederoglu-k1wwc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ismi lazim degil 

Ismi lazim degil cünki fark etmiyor

Hepsinin hikayesi birbirine benziyor

Nicin kimse bir türlü durun demiyor

Secim yoksa kimse ortaya cikmiyor

Ayseler yada fatmalardir satilanlar

Biri dokuz digeri ise onbir yasindalar 

Iki minik yavru  baslik parasi davasina

Alindi verildi yavrucaklar sözde takasina

Sapik babalarinin cirkin cani emellerine

Kurban edildiler karsi cikmadi kimsede

Dördüncü kari oldular amca dediklerine

Daha acilmamis gonca güldüler ikiside

Hani kalpler dayanabilecekmi bu acilara 

Feryadi duyarim agitlarinin nagmesinde

Töre diye birde ad vermisler sapikliklara

Insan haklari varsa hani bunun  neresinde 

siir_ce', 'Ismi lazim degil  Ismi lazim degil cünki fark etmiyor Hepsinin hikayesi birbirine benziyor Nicin kimse bir türlü durun demiyor Secim yoksa k...', ARRAY['Türk Edebiyatı','Şiir','Nurten Kederoğlu']::text[], 8.5, '{"poet":"Nurten Kederoğlu","poet_slug":"nurten-kederoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ismi-lazim-degil-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşlerim Ölüm Üstüne', 'duslerim-olum-ustune-yasar-yildiz-0bso4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamsız diplerin,

kahredici sessizliğinde,

üstüme, kurşun gibi çöker gece.

Karanlığında gözlerim üşür.

Boğulurum, umarsız çırpınışlar içinde.

Yalnızlığım ustura keskinliğinde.

Yalızlık - gece, umutların ötesinde,

ölümcül pusular kurarlar.

Sensizliği ecel gibi

bırakıp gittiğin yerde.

Herbiri, ayrı ayrı

saplanır bedenime.

Etlerim acı içinde - lime lime.

Sensiz uykularımda şimdi,

düşlerim bile,

ölüm üstüne.', 'Yaşamsız diplerin, kahredici sessizliğinde, üstüme, kurşun gibi çöker gece. Karanlığında gözlerim üşür. Boğulurum, umarsız çırpınışlar içind...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yıldız']::text[], 8.5, '{"poet":"Yaşar Yıldız","poet_slug":"yasar-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duslerim-olum-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
