INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem Niye IV', 'bilmem-niye-iv-gunday-duman-6yjkf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tutam göz yaşı ve hayata dair neyin varsa alınmış

Elinden,  elimizden.

Bilmem

Sende nedendir ki 

Kendimi buluyorum

İnsana dair herşeyinle…', 'Bir tutam göz yaşı ve hayata dair neyin varsa alınmış Elinden,  elimizden. Bilmem Sende nedendir ki  Kendimi buluyorum İnsana dair herşeyinl...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bilmem-niye-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Şiir', 'mavi-siir-tulay-sustam-cagp7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ay; 

Yıldızları koluna takıp

Güneş''in saçlarından tutup

bir gün bana geldiler...

bende ki yalnızlığı

karanlığı, karamsarlığı gidermek için

ben Güneş''i sevdiklerime

Ay''ı sevdiğime verdim.

yıldızları kendime aldım

o yüzden gündüzleri hep yalnız

geceleri umut doluyum

o yüzden her gece dilek tutuyorum

.

.

Herkes mutluysa bende mutluyum

(bu şiirimi adaşım, sevdasına kurban olduğum Tülay Köse ablama ve canım dostum Sevgi Damlaları Dila''cığıma hediye ediyorum.)', 'Ay;  Yıldızları koluna takıp Güneş''in saçlarından tutup bir gün bana geldiler... bende ki yalnızlığı karanlığı, karamsarlığı gidermek için b...', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-siir-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutki', 'tutki-gunday-duman-8zj3d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tutki gecedir

Elim eline,

Tenim tenine değmiştir…

Bir olup üşümüş

Çoğul olup kavrulmuş

Kedere düşmüşüz

Heder olmuşuz.

Bir olup

Çoğul olup

Düş olmuşuz…', 'Tutki gecedir Elim eline, Tenim tenine değmiştir… Bir olup üşümüş Çoğul olup kavrulmuş Kedere düşmüşüz Heder olmuşuz. Bir olup Çoğul olup Dü...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/tutki-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir şey var aramızda', 'bir-sey-var-aramizda-burhan-kucuk-oz1p4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şey var aramızda

Seni gördüm göreli ben böyleyim

Her gün kaleme sarılıyorum

Bir şey var aramızda,biliyorum

Kelimeleri birbirine karıştırıyorum

Bir şey var aramızda,yaklaşıyorum

Giydiremiyorum kelimelere giysi

Anlatamıyor,yutkunuveriyorum

Çözemedim gitti ben bu sihri

Burhan KÜÇÜK

Kdz.Ereğli-10.10.2004', 'Bir şey var aramızda Seni gördüm göreli ben böyleyim Her gün kaleme sarılıyorum Bir şey var aramızda,biliyorum Kelimeleri birbirine karıştır...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sey-var-aramizda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka I', 'aska-i-gunday-duman-geggo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Güzelliğin on para etmez bendeki bu aşk olmasa! ''

Bu işin sonu…

Aşkın sonu…

Gel tut ellerimizi, zira bende hal yok…

Kuytulara götür

Gözlerimizi

Kimseler görmesin

Halimizi.

Sırlaşalım, 

Tenin tenimde yitirsin

Suskunluğu…

Saçın süpürsün  gövdemi…

Uysun ritmine…

Gecenin…

Gel tutma ellerimizi, zira halim yok…

Kuytularda bırak

Gözlerimizi

Kimseler görmesin

Halimizi…

Sırlaşmamızı, 

Sevişmelerimizi…', '''Güzelliğin on para etmez bendeki bu aşk olmasa! '' Bu işin sonu… Aşkın sonu… Gel tut ellerimizi, zira bende hal yok… Kuytulara götür Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aska-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka II', 'aska-ii-gunday-duman-bkyhl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözün bittiği yerde 

Aşk, suskunluğu kucaklar...', 'Sözün bittiği yerde  Aşk, suskunluğu kucaklar......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/aska-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka III', 'aska-iii-gunday-duman-zzlbr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklın sustuğu yerde başlar; 

Şiddet…

Peki ya aşk?', 'Aklın sustuğu yerde başlar;  Şiddet… Peki ya aşk?...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/aska-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka IV', 'aska-iv-gunday-duman-9obuy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Delimiyim? 

Belki…

Ama yüreğinin yarısı kendi adına

Yarısınıda ülkesi  adına 

Bin parçaya bölmüş bir adam deliden çok

Aşıktır…', 'Delimiyim?  Belki… Ama yüreğinin yarısı kendi adına Yarısınıda ülkesi  adına  Bin parçaya bölmüş bir adam deliden çok Aşıktır…...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aska-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şımark Kadın', 'simark-kadin-gunday-duman-ewgdi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nasılda şımarık şu karşıdaki

Kadın:

Hani bej paltolu olan.

Beyaz eşarbı anlatır bana

Bileğindeki halhalı cabası

Güzel desem

Ne çok güzele haksızlık ederim kimbilir

İlla güneş üstüme gelsin

Boğaz bana baksın

Diyerek oturdu karşıma

Bunun şımarıklığı bana değil deniz/Deniz’e

Uzun boylu zayıf çocuğa', 'Nasılda şımarık şu karşıdaki Kadın: Hani bej paltolu olan. Beyaz eşarbı anlatır bana Bileğindeki halhalı cabası Güzel desem Ne çok güzele ha...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simark-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Perdeler ve Anahtar', 'perdeler-ve-anahtar-gunday-duman-t52nm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zana’lamalardan

Toplama perdelerle kapamış

Evin camlarını

Biri bizim eski evden.

Kimseler görmesin diye.

Kocaman yüreğini

Kilitlemiş

Binbir kilitle

Anahtarları orda burda

Birisi bizim eski evde.', 'Zana’lamalardan Toplama perdelerle kapamış Evin camlarını Biri bizim eski evden. Kimseler görmesin diye. Kocaman yüreğini Kilitlemiş Binbir ...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/perdeler-ve-anahtar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cevapsız Çağrıların Ardındaki Sır', 'cevapsiz-cagrilarin-ardindaki-sir-gunday-duman-fvjk0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Genç adam insanı büyüleyen, 

Parlak ışıklarıyla herkesi kendine çeken 

Kalabalık ama bir o kadarda yanlız Beyoğlu caddesinde yürüyordu... 

Aklına gülümsemek geldi... çevirdi numarasını ve aradı onu... cevap yok

Ve o an dudağında asılı kalan gülümsemeyle yürüdü...

Kalabalık mı onu içine aldı yoksa o mu katıldı ona...

Bilmiyorum...

Ama  hep bu tür hikayeler yüzünden genç,  kalacak adam...', 'Genç adam insanı büyüleyen,  Parlak ışıklarıyla herkesi kendine çeken  Kalabalık ama bir o kadarda yanlız Beyoğlu caddesinde yürüyordu...  A...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cevapsiz-cagrilarin-ardindaki-sir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Zaruri Ara Veren Adama Şiirler I', 'hayata-zaruri-ara-veren-adama-siirler-i-gunday-duman-8a6qz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zana’lamalardan

Dostum,

Bilmelisin ki...

Seni bekler hasırda içilecek bir bardak demli çay,

Seni bekler dostların, sevdiklerin.

Masada tuketilecek raki, beyaz peynir, cigara, dost sohbetleri...

Ve hepsinden önemlisi...

Seni  bekler biri bizim eski evden olan toplama  perdelerin.

Dostum,

Bilmelisin ki...

Yaşam tum ictenligiyle, cirkinligiyle, celiskileriyle...

Seni bekler...

Bizi bekler...

Onurlu bir direnişi bekler...

Dostum,

Bilmelisin ki

Umut olacak hepimize

Yoldaşlığımız.', 'Zana’lamalardan Dostum, Bilmelisin ki... Seni bekler hasırda içilecek bir bardak demli çay, Seni bekler dostların, sevdiklerin. Masada tuket...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hayata-zaruri-ara-veren-adama-siirler-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dal Gibi, Yol Gibi...', 'dal-gibi-yol-gibi-gunday-duman-skvuu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dal gibiydi.

Yanlız,

Ve mağrur...

Denek''in eteklerindeki rüzgar kadar asi

Ve bir asi kadar kırılgan... 

Dağdaki yol gibiydi

Bir yanı yamaç, bir yanı dağ eteği

Düş(i) se kolay...

Değilse; 

Dağın yamaçları...

Umut Denek''in karlı eteğinde...

Umut; 

Savruk bir asi dağ rüzgarının

Yolu erkan eylemesindeki yaman çelişkide,

Umut:

Aşk''ta...', 'Dal gibiydi. Yanlız, Ve mağrur... Denek''in eteklerindeki rüzgar kadar asi Ve bir asi kadar kırılgan...  Dağdaki yol gibiydi Bir yanı yamaç, ...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dal-gibi-yol-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyrut''a Varan Turna', 'beyrut-a-varan-turna-gunday-duman-o2s09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dostum Serhan Baykan''a

Olsun gözüm...

Varsin bize beteri düşsün... 

Sen yine de yanıbaşımda

Ve taaa yüreğimin derinliklerinde değil misin? 

Değil miyim? 

Sen benim gözümden bile sakındığım...

Dostum.

Varsın öyle olsun.

Sen ülkemin bir yanına

Ben diğer yanına savrulayım...

Yine de sen ben değil misin? 

Yine de ben sen değil miyim?', 'Dostum Serhan Baykan''a Olsun gözüm... Varsin bize beteri düşsün...  Sen yine de yanıbaşımda Ve taaa yüreğimin derinliklerinde değil misin?  ...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/beyrut-a-varan-turna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erciyes Etekleri', 'erciyes-etekleri-gunday-duman-l9gbo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '– fistanlım-

Yanlızlığımdır, üstümdeki yer gök

Cesaretimdir, tek nefeslik cigara

Belamdır, uçurumlara tutunmuş yollar

Sevdamdır; 

Dumanlı dağ eteklerin					 

Heybetli, keşif bekleyen kuytulukların

Uçuruma bakan yüzün

Pusuda bekleyen binbir korku

Ve susuşumuzdur sessizliğin....', '– fistanlım- Yanlızlığımdır, üstümdeki yer gök Cesaretimdir, tek nefeslik cigara Belamdır, uçurumlara tutunmuş yollar Sevdamdır;  Dumanlı da...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/erciyes-etekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimi Sürgüne Gönderdim', 'yuregimi-surgune-gonderdim-gunday-duman-zg9ah', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karadeniz’in hırçın  dalgalarını yüreğine saklayan adam, belam

						Ördüğün dalgakıranlar yetmez birgün

						Söyle,

						Nereyi döver o zaman hırçın dalgaların... 

                                                                                               Değerli Dostum Peyami Sefa''ya

Yüreğini sürgüne gönderdin

Yine hasret, yine uykusuz geceler

Kadan alam

Keşke kederin bana düşse

Sonra yitip gitsem.

Bilirsin

Döner her sürgün bir gün

Gel etme eyleme

Yitip gitme

Gel! 

Kadan alam

Sürgün yürekli belam.', 'Karadeniz’in hırçın  dalgalarını yüreğine saklayan adam, belam 						Ördüğün dalgakıranlar yetmez birgün 						Söyle, 						Nereyi döver o z...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yuregimi-surgune-gonderdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Zaman Yitik', 'o-zaman-yitik-gunday-duman-balpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O senin yanında daha güzel duruyor...

Yüreğine söz geçiremediğinde,

Aklın yitik, sevdan pusuda

Bekle-(let) -me

Yitik akıl, pusuda sevda

Kucak açmış bekler

Yitikliklerin kıyısında.', 'O senin yanında daha güzel duruyor... Yüreğine söz geçiremediğinde, Aklın yitik, sevdan pusuda Bekle-(let) -me Yitik akıl, pusuda sevda Kuca...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/o-zaman-yitik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız adanın mahkumuyum.', 'issiz-adanin-mahkumuyum-ali-osman-yilmaz-uraw9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Issız bir adaya,

Mahkum ettiler beni,

Yanına üç şey,

Alabilirsin dediler.

Bir mavi gözlerini,

Sen gülerken,

Yanağında oluşan,

Davetkar gamzeni,

Ve sana olan özlemimi,

Aldım yanıma.

Gözlerini hayal edip,

Mavi enginlere açılmak,

Gamzelerinde çiçek açmak,

Çiçeklerden yelken yapıp,

Özleminle tutuştuğumda,

Hasret rüzgarlarıyla dolup,

Gizlice yelken açarak,

Yeniden sana kavuşmak,

Issız bir adada bir başıma,

Başka ne isterim ki;', 'Issız bir adaya, Mahkum ettiler beni, Yanına üç şey, Alabilirsin dediler. Bir mavi gözlerini, Sen gülerken, Yanağında oluşan, Davetkar gamze...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/issiz-adanin-mahkumuyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönerdik', 'donerdik-gunday-duman-lexsb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hoyratça tükettiğimiz sigaralara dönerdik

Sabaha karşı

Yanına tavşan kanı çaylarımız

Hoyratça tükettiğimiz sevdalara dönerdik

Geceye karşı

Yanında bulanık anılarımız.', 'Hoyratça tükettiğimiz sigaralara dönerdik Sabaha karşı Yanına tavşan kanı çaylarımız Hoyratça tükettiğimiz sevdalara dönerdik Geceye karşı Y...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/donerdik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yanımda Olmadan', 'sen-yanimda-olmadan-ali-osman-yilmaz-r0te3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen yanımda olmadan,

Cennete giremem asla,

Sensiz cennet,

Cehennemdir bana.

Ne yaşarken,

Ne ölürken yanımda,

Sen yoksan eğer,

Bak pencerenden,

Geceleri gökyüzünde,

Kuyruklu yıldız olup,

Evrenden evrene,

Kayar giderim.

Seni bulurum,

Ümidiyle.', 'Sen yanımda olmadan, Cennete giremem asla, Sensiz cennet, Cehennemdir bana. Ne yaşarken, Ne ölürken yanımda, Sen yoksan eğer, Bak pencerende...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-yanimda-olmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-gunday-duman-xd9gv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Karım’a-

Beni boşver...

Asıl bu şehir sensiz ne yapar.

Bu şehir ki sensiz bozuk.

Bu şehir ki göz yaşlarımda boğuk

Sen beni boşver

Asıl bu şehir bizsiz  ne yapar.', '-Karım’a- Beni boşver... Asıl bu şehir sensiz ne yapar. Bu şehir ki sensiz bozuk. Bu şehir ki göz yaşlarımda boğuk Sen beni boşver Asıl bu ş...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bu-sehir-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökkuşağını Uçuruyorum.', 'gokkusagini-ucuruyorum-ali-osman-yilmaz-788y1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hani uçurtmamı,

Salmıştım ya çocukken.

Özgürlüğe doğru,

Özgür aşklara uçsun,

Özgür sevdalar yaşasın,

Bir tek sana,

Senin aşkına köle,

Çocukluğumun düşlerine,

Kuyruğunda umutlarım,

Gitsin diye,

Bırakmıştım ya; 

Bir akşam vakti şimdi,

Yine ellerimde,

Uçurtmanın ipi,

Gökyüzünde uçurtmam,

Ucuna bağladım gök kuşağını,

Uçurmaktayım şimdi.

Uçurtmamda; 

Kır papatyalarının,

Ve saçlarının sarısı,

Kiraz dudaklarının,

Sevda gül’ünün kırmızısı,

Muhteşem gözlerinin,

Enginlerin mavisi,

Göz göze olduğumuzda,

Umutlarımızın yeşili,

Aşk bahçelerindeki,

Tüm çiçeklerin renkleri,

Yaşayacağımız,

Güzel günlerin habercisi,

Bize el sallamakta.

İşte ellerim sevgilim,

İşte gökkuşağı uçurtmam,

Tut umudun renklerini,

Birlikte uçuralım,

Esen yelin rüzgarında,

Yelkenimizi doldurup,

Gök kuşağımıza,

Aşkımızı yaşamak için,

Birlikte gidelim,

Ne dersin?', 'Hani uçurtmamı, Salmıştım ya çocukken. Özgürlüğe doğru, Özgür aşklara uçsun, Özgür sevdalar yaşasın, Bir tek sana, Senin aşkına köle, Çocukl...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/gokkusagini-ucuruyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilsen', 'bilsen-gunday-duman-g1kze', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilsen felaketim olur

Bilmesen kederim.

Sana biriken özlemim olur gözlerim

Bilmesen,

Aramasan,

Kederim olur.

Yazsam sessizlik

Yazmasam biz olur

Sana dair tutkum olur sözcüklerim

Yazmasam.

Okumasan,

Beter olur.', 'Bilsen felaketim olur Bilmesen kederim. Sana biriken özlemim olur gözlerim Bilmesen, Aramasan, Kederim olur. Yazsam sessizlik Yazmasam biz o...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilsen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen, Görsen', 'gelsen-gorsen-gunday-duman-vccqo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen ülkemin ve yüreğimin aydınlık yüzü

Gittiğim günden beri

Biraz eksik

Biraz savruk

Hepsinden beteri

Yarım kalmış sessizlik

Artık

Gittiğin günden beri

Ülkemin türküleri daha kavruk

Biraz aç,

Biraz tok,

Hepsinden beteri; 

Yarım kalmış 

gülüşümüz bile hüzünlü', 'Sen ülkemin ve yüreğimin aydınlık yüzü Gittiğim günden beri Biraz eksik Biraz savruk Hepsinden beteri Yarım kalmış sessizlik Artık Gittiğin ...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gelsen-gorsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Mahrem', 'mahrem-kemal-sume-tk28g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'MAHREM

Mahremin yüzü berrak,

helâlliği altındır.

Dilde sükût,

gözde âma,

gönülde hamd- u senadır. 

***

Müşkül bir âh,

gamlı bir sabah,

tamâhsız bir revâdır.

......................Nâmahrem sâfa,

garip kalmış hevâdır.

bir gurebanın sol yanında...

Mahremin özü gülden,

kokusu paktır.

Gökte şems,

yerde meşk,

gönülde mizândır.

Mahrem,

bir sevdânın en yegân adıdır.

Kemal SÜME / Ekim-2004', 'MAHREM Mahremin yüzü berrak, helâlliği altındır. Dilde sükût, gözde âma, gönülde hamd- u senadır.  *** Müşkül bir âh, gamlı bir sabah, tamâh...', ARRAY['Türk Edebiyatı','Şiir','Kemal Süme']::text[], 8.5, '{"poet":"Kemal Süme","poet_slug":"kemal-sume","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mahrem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saf Aşk', 'saf-ask-gunday-duman-xfj30', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hep böyle gül

Çoçuksu.

Yüreğini aydınlığa dön.

Hep böyle ilk günkü gibi

Çoçuğunu kucaklar gibi

Bir aşkın saflığını korur gibi.', 'Hep böyle gül Çoçuksu. Yüreğini aydınlığa dön. Hep böyle ilk günkü gibi Çoçuğunu kucaklar gibi Bir aşkın saflığını korur gibi....', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/saf-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkutamazsınız', 'korkutamazsiniz-bayram-tunca-17wgt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Asla ölümle korkutamazsınız her an ölüp ölüp dirilen birisini

O zilletle yaşamaktansa, çoktan göze almıştır izzetle ölmeyi

18.10.2004-10.18', 'Asla ölümle korkutamazsınız her an ölüp ölüp dirilen birisini O zilletle yaşamaktansa, çoktan göze almıştır izzetle ölmeyi 18.10.2004-10.18...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/korkutamazsiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-gunday-duman-ruqxz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayata dair sözcükler biriktiriyorum

Sana ait olmayan  defterimde.

Göz yaşları biriktiriyorum, gözlerinde

Kederli bir günün sonunda; 

Aşk biriktiriyorum.

Bana - sana ait olmayan düşler ülkesinde.', 'Hayata dair sözcükler biriktiriyorum Sana ait olmayan  defterimde. Göz yaşları biriktiriyorum, gözlerinde Kederli bir günün sonunda;  Aşk bi...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sana-85-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma!', 'kizima-gunday-duman-hzi4e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hep bir kızım var olsun isterim

Gel kızım seveyim seni

Canım kızım,

Varlığımın öbür yarısı', 'Hep bir kızım var olsun isterim Gel kızım seveyim seni Canım kızım, Varlığımın öbür yarısı...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kizima-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyükada’dan Sedef’e', 'buyukada-dan-sedef-e-gunday-duman-vpiig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir vapurun üst güvertesinden martılara atılan simit...

Rüzgara bırakılan sigaranın dumanı...

Büyükada’dan  Sedef’e kadar tarifi imkansız yolculuk...

Merhaba gençliğim,

Merhaba dostluk,

Merhaba Aşk...', 'Bir vapurun üst güvertesinden martılara atılan simit... Rüzgara bırakılan sigaranın dumanı... Büyükada’dan  Sedef’e kadar tarifi imkansız yo...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/buyukada-dan-sedef-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-gunday-duman-ee6u8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Neyse ki çok beklemedik tozları silkelemek için....

Kucaklaştık ve sustuk 

Eski günlerdeki gibi.', 'Neyse ki çok beklemedik tozları silkelemek için.... Kucaklaştık ve sustuk  Eski günlerdeki gibi....', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/isimsiz-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Şiire', 'i-simsiz-siire-gunday-duman-nu9lz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dostuma Ergün ‘e....

Sofrada rakı, kavun ve beyaz peynir...

Kulağımızda Ahmet’in sesi

Bakalım  bir dahakine ne zaman 

Ve nerede kucaklaşıp sileceğiz

Tozlarımızı? 

“mademki ben taşıyamam al derdimi vur sırtına”', 'Dostuma Ergün ‘e.... Sofrada rakı, kavun ve beyaz peynir... Kulağımızda Ahmet’in sesi Bakalım  bir dahakine ne zaman  Ve nerede kucaklaşıp s...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/isimsiz-siire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunsan Ağlarım', 'dokunsan-aglarim-gunday-duman-uyseq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dolu bir bulut gibi çatacak başka bir yoğunluk ararım

Dokunsan. 

Sorsan solarım

Dolu bir bulut gibi hüznümü dökecek bir ıssızlık ararım

Dokunsan

Ağlarım.', 'Dolu bir bulut gibi çatacak başka bir yoğunluk ararım Dokunsan.  Sorsan solarım Dolu bir bulut gibi hüznümü dökecek bir ıssızlık ararım Doku...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dokunsan-aglarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-gunday-duman-w9p37', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgili Gündüz hocama...

ve verilen çoğu yeminde ilk ölüme gönderilendir anamız, ''Yalanın varsa anan ölsün mü? '' ''Ölsün''

ve ölüm yanıbaşımızdayken ilk sığındığımızdır anamız, '' ah anam ah ''', 'Sevgili Gündüz hocama... ve verilen çoğu yeminde ilk ölüme gönderilendir anamız, ''Yalanın varsa anan ölsün mü? '' ''Ölsün'' ve ölüm yanıbaşımız...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/anam-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Saf Bakışı', 'askin-saf-bakisi-cafer-kurtoglu-3lk3l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gül tomurcuğunda berrak damlasın 

aşkın saf bakışını gönder bana

yanağında buse açsın kızların

aşkın saf bakışını gönder bana

sevdamızı çalar saçın telleri

dudağından akar aşkın sözleri

bende kokar gönlünün çiçekleri

aşkın saf bakışını gönde bana

güneşler süzüldü gözlerinden gönle

yüreğim tutuştu ateşli gülle

gönlümün aybergi erir sevginle

aşkın saf bakışını gönder bana

sendeki sevda kavurdu içimi

aşk ile gül ancak anlar beni

bülbüller söyler hep yanık sevgimi

aşkın saf bakışını gönder bana', 'gül tomurcuğunda berrak damlasın  aşkın saf bakışını gönder bana yanağında buse açsın kızların aşkın saf bakışını gönder bana sevdamızı çala...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-saf-bakisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüm', 'uzum-gunday-duman-l8vv4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yokluğun eksikliğim olur

Savrulurum

Başkasına fazlalık olur

Unuturum...', 'Yokluğun eksikliğim olur Savrulurum Başkasına fazlalık olur Unuturum......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uzum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutun/ma', 'tutun-ma-gunday-duman-8j1vy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mutluluk yanıbaşımda 

Ve ben artık daha sıkı tutunuyorum yaşama

Örneğin artık bulaşık biriktirmiyorum yarınlarıma

Ya da çamışırlarımı savurmuyorum odanın rastlantısal kordinatlarına

Çiçek aldım mesela sulamak için 

Akşam yalnızlığında

Her akşam yıldızları sayıyorum matematik hocama inat

Aşkı düşünüyorum her zamankinden daha sık

Ve sık sık özlüyorum hüzünlü çoçukluğumu...', 'Mutluluk yanıbaşımda  Ve ben artık daha sıkı tutunuyorum yaşama Örneğin artık bulaşık biriktirmiyorum yarınlarıma Ya da çamışırlarımı savurm...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/tutun-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Buluşma-ma', 'bulusma-ma-gunday-duman-pkt92', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her buluşamama

Bir kalp sızısı.

Birikintisi ise kalp sektesi.

Alınan her nefeste söylenilemeyen her sözcük

Bir hüzün sağnağı

Ve her hüzün 24 ayar bir gözdamlasına takabül', 'Her buluşamama Bir kalp sızısı. Birikintisi ise kalp sektesi. Alınan her nefeste söylenilemeyen her sözcük Bir hüzün sağnağı Ve her hüzün 24...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bulusma-ma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğime Dokunabilsen', 'yuregime-dokunabilsen-cafer-kurtoglu-v5qqr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gittin bu günü mahsun bırakarak

ah yüreğime bir dokunabilsen

gittin hazin sevdayı ağlatarak

ah yüreğime bir dokunabilsen

gönülde beslediğin şuh yiğidin

aslı''nın içinde yanar kerem''in

gerçekten ben değildim reddettiğin

ah yüreğime bir dokunabilsen

sundum aşkımı davudi sesimle

göğüm iniler sevda nağmesiyle

mektuplar hasret sunar dilekçeyle

ah yüreğime bir dokunabilsen

gönlümde yakup''un lalezar gözü

züleyha''yı yakan aşkın yüzü

gönlümde bulunur yusuf''un özü

ah yüreğime bir dokunabilsen

dönmemek için gemileri yaktın

bulursun bende ah''ını tarık''ın

endülüs gibi bir sevda bıraktın

ah yüreğime bir dokunabilsen', 'gittin bu günü mahsun bırakarak ah yüreğime bir dokunabilsen gittin hazin sevdayı ağlatarak ah yüreğime bir dokunabilsen gönülde beslediğin ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Kurtoğlu']::text[], 8.5, '{"poet":"Cafer Kurtoğlu","poet_slug":"cafer-kurtoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yuregime-dokunabilsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İllaki Sen', 'i-llaki-sen-gunday-duman-bfc6i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Esma Ablama

Nereye baksam sen! 

Kimi sevemesem sen! 

Neye küssem sen!', 'Esma Ablama Nereye baksam sen!  Kimi sevemesem sen!  Neye küssem sen!...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/illaki-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-gunday-duman-o5ukw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözyaşlarımı biriktirsem

Sen sorduğunda

Balığım için tuzlu su gerekliydi desem; 

Ve sana dair hiç bir söz demesem

Sen yinede...', 'Gözyaşlarımı biriktirsem Sen sorduğunda Balığım için tuzlu su gerekliydi desem;  Ve sana dair hiç bir söz demesem Sen yinede......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sana-dair-29-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlkel Ezgim', 'i-lkel-ezgim-gunday-duman-p9seb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen dünyaya daha güzel bakan gözlerim

Ruhumu asiliğe taşıyan sözlerim

Sen tutsaklığım sebebi.

Öyle bir çırpıda nereye! 

Düşlerime ilkel Pan’ı davet eden bedenim – ki ilkelliği tartışılır

Bedenimden yayılan sessiz ezgim.', 'Sen dünyaya daha güzel bakan gözlerim Ruhumu asiliğe taşıyan sözlerim Sen tutsaklığım sebebi. Öyle bir çırpıda nereye!  Düşlerime ilkel Pan’...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ilkel-ezgim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Hüznüm Bana', 'benim-huznum-bana-gunday-duman-hcj1d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi camları şiddetle döven yağmurun eşliğinde

Kullanmaktan yıpranmış sarı bataniyeme sarılıp

Yalnızlığımı gözyaşlarımla paylaşmak istiyorum.

Elimde sonu hüsranla bitmiş; eski zamanlardan kalma bir kitap.

Hüznümü bana  terkedin.

Beni eksikliğime bırakın.', 'Şimdi camları şiddetle döven yağmurun eşliğinde Kullanmaktan yıpranmış sarı bataniyeme sarılıp Yalnızlığımı gözyaşlarımla paylaşmak istiyoru...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/benim-huznum-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Defa', 'i-lk-defa-gunday-duman-2uqb4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerine sormak gerek seni

Gözlerine hangi sözler denk düşer, bilsen...

Gözlerine aşk,

Gözlerine özlem,

Gözlerine keder...', 'Gözlerine sormak gerek seni Gözlerine hangi sözler denk düşer, bilsen... Gözlerine aşk, Gözlerine özlem, Gözlerine keder......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ilk-defa-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-gunday-duman-ykp6b', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Oktay’a

Daha gün bitmeden,

Şair kuytuya çekilip ağlamadan

Hüzün’den bana düşen payımı aldım

Yine sıra beklemeden, ilkten

Ve

Herkes gibi en büyüğünü... 

Ve

Herkese gibi aynı soruyu sordum:

Neden?', 'Oktay’a Daha gün bitmeden, Şair kuytuya çekilip ağlamadan Hüzün’den bana düşen payımı aldım Yine sıra beklemeden, ilkten Ve Herkes gibi en b...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-87-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'On Yedi Ağustos İki Bin Dört Salı', 'on-yedi-agustos-i-ki-bin-dort-sali-aydan-ortulu-xk6q9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '..ve; 

karanlıktan çekilen bıçaktı

o an bütün zamanlar

ve büyük gürültülerle,

ardına kadar kapandı kapılar.

..gidecektin...

 

keskin bağırtıların şarkısı geçecekti

penisiline boğulmuş damarlarından.

kanadından vurup mülteci kuşları,

hançerledin

yıldızlara belenmiş geceyi,

..ve gittin...

artık bana kalacaktı

yenilgisiz sözlerin,

çalınan şarkılar,

sesinde anlamlı öyküler,

 bütün iyi dilekler,

ve şizofren caddelerinde kentin

gölgeler yitirdiğimiz

gidişler; 

..bana kalacaktı.

şimdi; 

bana kaldı,

kendime kundak bildiğim

gecelerin sabahında

binlerce şairin

bıçak sırtındaki sancısı.

 

..gidişin,

belki de ardına bile bakmayarak,

ve bir dağ ateşinin alazını

ciğerime damlatarak; 

bir kahroluştu bu.

ismin nakışlanmış

ses vermeyen duvarlara,

istasyonlara,

taksi duraklarına,

mezar taşlarına,

ateşe,

suya.

yüzünün sarışın sıcaklığında,

kulak kabartmak

yüreğimin yangınına,

ve kefenleyerek uykuları,

sabahın alacasında

uyumak yokluğuna.

artık; 

aşinalığını yitirmiş

bir kumrallık olacaktı yüzüm,

kesindi,

ve gülüşünü de unutacaktım

masamda.

saçlarında bir teli daha

dökülecekti fırtınanın,

nehirler bulutlara taşınacaktı,

böyle bir vakitte

kışa duracaktı nar çiçekleri,

ve şakaklarımı ablukaya alan

zemheri beyazı,

kaburgama çöreklenen ağrısı,

ve daha da derine gidecekti

yokluğunun yarası.

gidişinle ülkesiz kalmıştım,

yurtsuz,

kentsiz.

dilimi de unutmuştum,

ki feryadım yürüdüğün yollardaydı.

kentin ışıkları

sönüyordu birer birer,

evlerin çatısına

yıldızlar yağıyordu,

Aydan

ışık ve gölgeler yağıyordu,

ve doğduğum şehir

artık kayboluyordu.

kimliksizdim,

çaresizdim,

boşa arıyordu

taşını toprağını ellerim; 

sen,benim şehrim değil miydin? 

 

iyi de; 

biz bu kavgalara bilememiş miydik

hasretimizi? 

bu kahrolası aydınlığa,

kalabalıkların kirlettiği sabahlara,

ve etrafımızı kuşatan duvarlara

yaylım ateşti ya

en içtenlikli,

en sıcak şarkılarımız:

“gecenin matemini 

aşkımıza örtüp sarayım,

gittin; 

şimdi ben,

seni nerede bulup yalvarayım”

..dağlar devrilirdi üzerime,

sen söylerdin,

ve yakamozları ağlatırdı

nağmelerin süslediği sesin.

ellerimizi vermiş de

yakmıştık ıslak kumları,

“akşamın olduğu yerde

bekle diyorsun,

gelmiyorsun; 

çünkü,

seni çok sevdiğimi biliyorsun” ezgili,

ve o şarkılarla

ağlamıştık ya sevgili.

dişimi dişime dayarcasına

ısırdım dudaklarımı,

vaktim olmadı bunu unutmaya

ne yazık ki...

bu kentte voltalar yitikti,

ve hiçliğimize anı şarkılar; 

veda idi.

o, iki gözün acısına kapaklanmış,

ölü köpek bakışlarıyla

gelincikti iki gözüm.

yollarını beklemek var ya,

o dönüşü olmayan yollarını; 

belaydı.

yokluğunun beynime çöreklenen acısı; 

belaydı.

ve beni ablukaya alan

dört duvar; 

belaydı.

ve yıldızlar

gecenin alacasına göz ederken

baktım,

yine hüzün içindeydi gülüşün,

çok içtendi,

ve çok güzeldi.

yüzünde,

buz tanrıçasının ebemkuşağı vardı,

selamın bildirge,

gidişin,

ve geceden güneş gibi yitişin

öyle mağrur,

öyle diktin.

ve yüreğine yakışan sevdayı

savunmuştu,

çıplak gözlerin.

 

..ve; 

karanlıktan çekilen bıçaktı

o an bütün zamanlar,

ve büyük gürültülerle

ardına kadar kapandı kapılar.

..gitmiştin...

gidişinle ülkesiz kalmıştım,

şehirsizdim.

yurtsuz,

kentsiz,

memleketsiz.

oysa; 

nabzı avuçlarımda atardı bu şehrin,

ki yaşanacak zamanları

bir kalemde silip ömrümden,

gitmemen için dönüşsüz yollara

seve seve ölebilirdim.

ve yerim senin yanındı,

..bilirdin...

şaşkın,

telaşlı,

ve ürkektim,

ve sana mülteciydim.

boşa arıyordu

artık bağını,bahçesini gözlerim; 

sen,benim şehrim değil miydin? 

01.Temmuz.2000 / İstanbul', '..ve;  karanlıktan çekilen bıçaktı o an bütün zamanlar ve büyük gürültülerle, ardına kadar kapandı kapılar. ..gidecektin...   keskin bağırt...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":171,"source_url":"https://www.antoloji.com/on-yedi-agustos-iki-bin-dort-sali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-gunday-duman-m5vz0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Susturmak için çığlığını

Kalem en iyisidir

Kimi zaman dişlerin arasında

Kimi zaman parmaklarının...', 'Susturmak için çığlığını Kalem en iyisidir Kimi zaman dişlerin arasında Kimi zaman parmaklarının......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kalem-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Zaman Hikayesi', 'eski-zaman-hikayesi-gunday-duman-vj23n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir eski zaman hikayesi olmak isterim

Bir varmış bir yokmuş ile başlayan...

Gökten düşen 3 elma ile biten

Bir sana,

Bir bana,

Bir ona

Ve hepimize.', 'Bir eski zaman hikayesi olmak isterim Bir varmış bir yokmuş ile başlayan... Gökten düşen 3 elma ile biten Bir sana, Bir bana, Bir ona Ve hep...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/eski-zaman-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalleme', 'hayalleme-aydan-ortulu-rjtxx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'akşam,

kül rengi kollarını açarak

gecenin canevine yol alıyordu.

sahiller,

ıssızlığın sokaklarında kaybolurken; 

deniz,

kadife tenli bir ayışığı ile

yıkanıyordu.

gözlerin,

dudakların,

avuçlarımı yakarcasına sıcak

yanakların,

başın.

bütün bu güzelliklerin

tanrısal titizlenmelerle

yüzüne işlendiği başın,

omuzumun üzerinde,

bir kedi sıcaklığında; 

suskunduk.

bakışlarımız,

yakamozda yıkanan 

ayışığı altında erirken

savmıştık bütün kötülükleri

tarihin izbe kovuklarına,

sevdalıydık ölesiye,

hürdük,

ve ateş çemberinde bile acıların

mutluyduk.

birden fesleğen kokulu yağmurlar indi

gecenin çatısına,

ortalık anne koktu

toprak çatlarken kurumuşluğunda,

ve ağaçların

yangın yeriyken kökleri

susuzluğunda,

kuraklık çeşitlenip çeşitlenip

dünyanın yakasına yapışıyordu.

ve tabiat,

bütün sevecenliğiyle bana,

seni armağan ediyordu.

bütün tanrılar

kıskançlıkla bakıyordu bana,

ve gökkuşağı renginde çiçekler,

ayağının bastığı yerlerde açıyordu.

alıp götürmüştü,

kokun gibi güzel yağmur

denizin tüm hırçınlığını.

ve suskunluğunda dans ediyordu

bütün ışıklar.

rüzgar tenimize değiyordu,

gözlerinin bebeklerinde gönençli

pırıltılar dans ediyordu.

..ve çok uzaklarda

tanrılar ağlıyordu.

ayışığı emzirmiş yağmur damlaları

yavaşça saçlarını okşayarak,

bin bir renk yansıması altında

yanaklarına süzülüyordu.

içimde bir çocuk,

senin olduğun yere

düşe kalka koşuyordu,

ve ölürcesine seviyordu.

ve pembesini kırmızıya yayan

yanakların

büyüleyici güzelliğinle

ışıl ışıl yanıyordu.

çocuk; 

içimdeki,

ölürcesine seviyordu.

bağrıma ok ok saplanan

kirpiklerinin ucunda

buluşan su damlacıkları,

çiçeği dalına zorlayan

badem ağaçları gibi

gözlerini süslüyordu.

gözlerin denizleri,

gözlerin sensizliğimle boş,

sensizliğimle anlamsız bedenimi,

ve çocuğun büyüttüğü hayalleri...

sıcaklığın,

kulaç kulaç gövdeme yayılırken,

büyülenmiş gibi

huşu içinde seyrediyordum seni.

aynı; 

yağmur ve ayışığı gibi,

çocukla anne gibi,

su gibi,

dostane ve davetkardı bakışların.

ama,

eğilip de öpmeye kıyamıyordum

dudaklarını, gözlerini,

ve o harika güzelliğini...

 

büyü bozulacak diye korkuyordum! 

30.Haziran.2000 / İstanbul', 'akşam, kül rengi kollarını açarak gecenin canevine yol alıyordu. sahiller, ıssızlığın sokaklarında kaybolurken;  deniz, kadife tenli bir ayı...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":95,"source_url":"https://www.antoloji.com/hayalleme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik', 'matematik-ahmet-agdere-tveh5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masa başı curcuması,

Alır ömrü yara sürer.

Tanjant, sinüs, kotantjanı,

Emel eden sefa sürer.

Maruf talih şu cebirin,

Aldatmaz hiç dostluk sürer.

Tık tık çalışan saatin,

İbresini Hakk''a sürer,

Kemalini, şaha sürer.', 'Masa başı curcuması, Alır ömrü yara sürer. Tanjant, sinüs, kotantjanı, Emel eden sefa sürer. Maruf talih şu cebirin, Aldatmaz hiç dostluk sü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/matematik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '(S) us', 's-us-gunday-duman-sqdcx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sus,

Usulca sokul düşlerime

Ben ürkek tavşan uykularımda...

Aşk,

Derindeki yaram

Sızım, sızım uykularımda...

Us:

Uslanmıyanım...

Suslanmayanım...

Düşlenmiyenim...', 'Sus, Usulca sokul düşlerime Ben ürkek tavşan uykularımda... Aşk, Derindeki yaram Sızım, sızım uykularımda... Us: Uslanmıyanım... Suslanmayan...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/s-us-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sözü Yine Sen Söyledin', 'son-sozu-yine-sen-soyledin-aydan-ortulu-aqw5s', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yavru ağzı şafaklarda,

sabahın alacasında

ayaklarının ucundayım,

istemem kıyıcıları,

bir işaret ver; 

ben kendimi kurşuna dizerim.

 

yüzümü hep sert rüzgarlara tuttum.

çatıma vurur denizlerin fırtınası.

..ve seni sevdim,

ve gönül koymadım sana.

doğa uyurken kar altında,

birer birer patlayan

kardelen çiçeğiydim.

seni sevdim.

ben,bir ışık demetiyle muştulanan

yıldırımlar gibiydim

gözlerimdeki acıların

nasırını yumuşatarak

koştum yaylaların baharına,

sana gelen bütün sulara,

ve akan pınarlara kulaç attım.

şimdi yelkovanın bakışlarına,

akrebin kuyruğuna takılı

ölümleri bekleyemem.

iki dudağının arasındayım,

istemem kıyıcıları,

bir işaret ver; 

ben kendimi kurşuna dizerim.

 

yaşanacak onca yıllar duruyorken,

ömrümün kalanının

yalımındayım

..ve seni sevdim.

yaşamak,

kaldıramadığım bir kahkahadır

sırtımda.

yaralanmış zamanların,

ağustos serinliğidir

kan ter içinde yüzüme şamarlanan.

ve yarım kaldı artık

size dair sevdam; 

posta adresleri,

Spil dağları,

Soma,

Yırca,

şehri Manisa,

..ve doyamadım sana.

yaşamımın binlerce yıllık serüveni,

ve içini bezeyen

milyonlarca öyküyü süregeldim.

ayaklarının altındayım,

istemem kıyıcıları,

bir işaret ver; 

ben kendimi kurşuna dizerim.

 

tenini öpen toprağa

yüzüm sürdüm.

dileklerimin gerçekleşmesi için

dumanından halkalar yapıp

içtim sigaramı,

..ve seni sevdim.

bütün dudaklarda,

ve bütün yüreklerde

aynı ağırlığı bulan sözleri söyledim,

ve değiştirdim yaşamı sözlerimle.

yüzümün bir yarısı sana bakar,

diğer yarısı ölüme.

ayaklarının altında,

parmaklarının ucundayım.

istemem kıyıcıları,

bir işaret ver; 

ben kendimi kurşuna dizerim.

 

Anka gibi,

kendimi yeniden yarattığım külleri

Gediz’in sularına savurdum,

ve çağıltılarına dağıldım.

..ve seni sevdim.

sevdim seni,

sevdim,

sev...', 'yavru ağzı şafaklarda, sabahın alacasında ayaklarının ucundayım, istemem kıyıcıları, bir işaret ver;  ben kendimi kurşuna dizerim.   yüzümü...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":82,"source_url":"https://www.antoloji.com/son-sozu-yine-sen-soyledin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldatılan İçinde', 'aldatilan-i-cinde-ahmet-agdere-hcuay', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aldanmak bize göre değil,

Aldatılan içinde.

Seveceksen ben gibi, 

Sevmeyeceksen el gibi,

Çekip gideceksin bu düzenden.

Çekmez kahrını geceler,

Aşkı iliğine kadar işlemeyenin.

Ve içmeye benzemez,

Aşk şarabından içmek.

Dikenleri sert ve diktir bu yolun,

Ve bir günahkara ait,

Sırat köprüsünden daha dar..

İlah''ın içinde ilah olmak,

Kolay olmasa gerek! 

Bir Anka Kuşu gibi,

Küllerinden doğacak,

Tüylerini evrene silkeleyecek,

Ve evreni sevdasıyla uyutup,

Başka bir evrene kanatlanacak,

Bir çift aşık olmak gerek.

Dedim ya,

Aldanmak bize göre değil,

Aldatılan içinde..', 'Aldanmak bize göre değil, Aldatılan içinde. Seveceksen ben gibi,  Sevmeyeceksen el gibi, Çekip gideceksin bu düzenden. Çekmez kahrını gecele...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ağdere']::text[], 8.5, '{"poet":"Ahmet Ağdere","poet_slug":"ahmet-agdere","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/aldatilan-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Soonraki Gün', 'bir-soonraki-gun-cihan-firat-nh47n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçtiğim yollarda belirgin izler vardı

Ansızın duruşumun yola kazıdığı simgeler

Duruşumun ön camdan fırlarcasına

Bin bir köşe bucağa saçılan düşüncelerim

Düşlerimden silkilinimişim 	

Bir kenara toplamadığım kırıntılar ve

Onlardan kaçarcasına varışım vardı

Gaz pedalına asılırcasına kaçışım

Kovalarcasına yolları benliğime varışım vardı

Ertesi gün bir çok gastenin ön sayfasında

Yazmayı düşündüklerim vardı.

Firene basmakta geç kalışım,

Kırmızı bir allık gibi yüzüme vuran

Beyazların göz bebeğimin içine doğan

Gecenin karanlığında beyazdan kaçamadığım

Bir an vardı geç kalmıştım

Bir sonraki güne varışımda

                     Geç kaldım...', 'Geçtiğim yollarda belirgin izler vardı Ansızın duruşumun yola kazıdığı simgeler Duruşumun ön camdan fırlarcasına Bin bir köşe bucağa saçılan...', ARRAY['Türk Edebiyatı','Şiir','Cihan Fırat']::text[], 8.5, '{"poet":"Cihan Fırat","poet_slug":"cihan-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-soonraki-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Husumetin Diğer Adı:Kameo', 'husumetin-diger-adi-kameo-gunday-duman-dbqqk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir sabah ansızın aşkı bulacak olan adama...

Erkek sordu: Nedir aramızdaki husumete sebep? 

Kadın cevapladı: Benim Kameo

Yok olamaz dediler...

Olmasın gözlerin...

Yok olamaz dediler...

Olmasın sözlerin...

Yok olamaz dediler...

Hep bir ağızdan kadın, erkek ve diğerleri

Yok olsa olsa Kameo dediler

Bir tek Kameo söyledi kısık sesiyle

-Ki kimselerin bilmediği gizemli bir eskiçağ diliyle-

Olmasın aranızdaki husumete sebep:

Herkesin kendi aşk-ı bakışı...', 'Bir sabah ansızın aşkı bulacak olan adama... Erkek sordu: Nedir aramızdaki husumete sebep?  Kadın cevapladı: Benim Kameo Yok olamaz dediler....', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/husumetin-diger-adi-kameo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aspirin', 'aspirin-gunday-duman-ad4aj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sana ekmek gibisin diyorum… 

bazıları için hiç olmayan 

bazıları içinde başkası olmayan.

sana ekmek gibisin diyorum… 

sana aşk diyorum

sen susuyorsun

sana sen oldum

içimde koca bir devrim oldu diyorum

sen başka telaşlardasın

görüyorum...

aklımı yitirdim

yapay hücrelerde

kanata kanata yüreğimi

öğrendim ki

sen başka hayatlardasın', 'sana ekmek gibisin diyorum…  bazıları için hiç olmayan  bazıları içinde başkası olmayan. sana ekmek gibisin diyorum…  sana aşk diyorum sen s...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aspirin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neylerim', 'neylerim-gunday-duman-ixkez', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben gözlerin olmadan neylerim, neylerim

Dünyanın kalanını...

Ya kırmızı karanfilleri neylerim...

Gözlerin gözlerime değmediğinde...', 'Ben gözlerin olmadan neylerim, neylerim Dünyanın kalanını... Ya kırmızı karanfilleri neylerim... Gözlerin gözlerime değmediğinde......', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/neylerim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-gunday-duman-c8pyj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fakat yalnızlık ürkütücüdür…

Ya Ölüm? 

Onu bilmiyorum…

- ki bu topraklarda ölüm o kadar uzak değilken sana ve bana

Ölüm sonrası toplanılan hesap gününde

-ki kim kime soracak hesabı bilinmez...

Koca kalabalıkta yalnız hem de hiç olmadığımız kadar yalnız olmamız 

Belki de ölümü ürkütücü kılandır…', 'Fakat yalnızlık ürkütücüdür… Ya Ölüm?  Onu bilmiyorum… - ki bu topraklarda ölüm o kadar uzak değilken sana ve bana Ölüm sonrası toplanılan h...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizlik-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Failsiz Aşk Mı?', 'bir-failsiz-ask-mi-gunday-duman-xheqf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep gülen gözlerin suskun

Bugünün dünden farkı ne

-bir faailsiz aşk mı? 

Hüznün daha mı derinlerden gelir

Bügünün yarından farkı ne

-bir failsiz aşkın kurbanı mısın? 

Yoksa biz mi öyle biliriz...

Yoksa biz ondan mı daha çok ağlarız....', 'Hep gülen gözlerin suskun Bugünün dünden farkı ne -bir faailsiz aşk mı?  Hüznün daha mı derinlerden gelir Bügünün yarından farkı ne -bir fai...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-failsiz-ask-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-servet-suner-xuaj9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Siz siniz; 

Yok kimseden gizlim,saklım yok diyen.

Saklanan ben,

Gizlenen ben,

Ben mahkum, 

Ben üzgün,

Sol yanımdan aldım yara.

Taa.! derinden

Elimi kaldırdım,

Kolum ağrıdı.

Başımı kaldırmı, 

Başım ağrıdı.

Aklımı aldırdım,

Gönlüm ağrıdı.

Yüreğimi kaptırdım,

Bütünüm ağrıdı.

Saklanan ben,

Gizlenen ben,

Var olduğu halde.

Yok gibi yaşayan ben.', 'Siz siniz;  Yok kimseden gizlim,saklım yok diyen. Saklanan ben, Gizlenen ben, Ben mahkum,  Ben üzgün, Sol yanımdan aldım yara. Taa.! derinde...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maske', 'maske-gunday-duman-xdjtx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sürekli mutsuz insan maskesini, takmış suratına

Bazen yorulup el değiştirirken

Tutmak için maskeyi

Görebiliriz gerçek yüzünü

Acaba kessek mi ellerini (?) 

Sonsuza dek görmek için güleç yüzünü...', 'Sürekli mutsuz insan maskesini, takmış suratına Bazen yorulup el değiştirirken Tutmak için maskeyi Görebiliriz gerçek yüzünü Acaba kessek mi...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/maske-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Küçük Bir Çoçuğum', 'ben-kucuk-bir-cocugum-gunday-duman-tbeko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ellerimle büyüttüğüm

Başka bir çocuk barınır içimde

Büyüklüğümün korkularıyla maskelenmiş

Ben küçük bir çoçuğum

Dünümle örselenmiş

Gündüz uykularındayım

Çocukluğumun yarım kalmış gülüşleri dudaklarımda

Çocuğun korkuları da büyür mü onunla? 

Ben küçük bir çoçuğum

Yarınımla örselenmiş', 'Ellerimle büyüttüğüm Başka bir çocuk barınır içimde Büyüklüğümün korkularıyla maskelenmiş Ben küçük bir çoçuğum Dünümle örselenmiş Gündüz uy...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-kucuk-bir-cocugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanıbaşındaki/lerimize', 'yanibasindaki-lerimize-gunday-duman-7e8h6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kızgınlık zaman meselesidir

Geçer, 

Hatta bazen yarım bir gülüş bırakır yüzünde.

Kenetlenmiş dişlerin eşliğinde bilenmiş öfke de

Geçer,

Ama, kalbine açılmış bir yaranın acısını iliştirir yüzüne.

İyi bilmek lazım

Hangisini beslediğini yanıbaşındaki/lerimize yüze…', 'Kızgınlık zaman meselesidir Geçer,  Hatta bazen yarım bir gülüş bırakır yüzünde. Kenetlenmiş dişlerin eşliğinde bilenmiş öfke de Geçer, Ama,...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanibasindaki-lerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-gunday-duman-pi7o1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her sabah 

Şehrin geceden kalıntılarını süpürür çöpçüler

Ürkek uykulardaki kediler kaçışırken 

Uyku sersemi evsizlerin küfürleri serpişir caddelere

Ve aşk bozgunu yürekler sendeler kaldırımlarda

Hayat tekrardan mı ibarettir.

Bir sabah çöpçülerden erken uyanmıştı yağmur

Kediler ve evsizler koyun koyuna merdiven diplerinde

Dillerinde eski bir aşk şarkısı 

Ve aşk bozgunu yürekler göz yaşlarıyla ritim tutarlar

Hayat bozgunlardan mı ibarettir.

Bir aşk bozgunu yürek taşırım 

Kimi zaman kaldırımlarda sendelerim 

Kimi zaman ritim tutarım evsizler ve kedilerin aşk şarkılarına

Merhem çalarım yüreğime

Gözlerimi ararım bozgunlardan sonra

Hayat aramaktan mı ibarettir.', 'Her sabah  Şehrin geceden kalıntılarını süpürür çöpçüler Ürkek uykulardaki kediler kaçışırken  Uyku sersemi evsizlerin küfürleri serpişir ca...', ARRAY['Türk Edebiyatı','Şiir','Günday Duman']::text[], 8.5, '{"poet":"Günday Duman","poet_slug":"gunday-duman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/hayat-159-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '- A k r e p...v e...Y e l k o v a n....(1)', 'a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-1-metin-eser-3qj36', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yer Los Angeles şehri, saat gecenin dördü, 

Ve aylardan Haziran, sıcak ayın ondördü, 

Şehrin tam sessizliğe, büründüğü saatler, 

Kimbilir kaç masuma, veriliyor vaatler. 

Geçen yıla oranla, suç oranı katlanmış, 

Cinayetler sahipsiz, failler kanatlanmış, 

Genç kızların bedeni, etten bile değersiz, 

Herkes kendi derdinde, dolu dizgin eğersiz. 

Derin uykuda iken, bu şehrin rahipleri, 

Caddelere hâkimdir, serseri sahipleri, 

Cesaret ister elbet, şimdi sokakta olmak, 

Korkaklık değildir ki, gece yatakta olmak. 

Kuş misâli yükselip, şehre bir bakabilsen, 

Sihirli bir değnekle, bir ampül yakabilsen, 

Nerede ne yapılır, kim nereye atılır, 

Görebilirsin elbet, gece kaça satılır. 

Kimi yerler sessizken, kimisinde hareket, 

Kimi sinek avlarken, kimisinde bereket, 

Kimi bilmez canının, değer ve kıymetini, 

Kiminin hayat yükü, zorluğun en çetini. 

Ortalık sakin iken, birden sese bürünür, 

Belki silahlar patlar, biri yerde sürünür, 

Alkol duvarı ne ki, aşan yataklık olmuş, 

Sabaha karşı şehir, tam bir bataklık olmuş. 

Ambulansın sireni, yırtar birden geceyi, 

Ardından sert fireni, dilde tutar heceyi, 

Açılan kapılara, bütün bakışlar döner, 

Bir karanlık haberle, canlı hayaller söner. 

Sedye''de çıktı adam, heryeri kan içinde, 

Kendi can telaşında, millet ''Neden Niçin'' de, 

Büyük bir dikkat ile dışarıya aldılar, 

Sonra hızla iterek, içeriye daldılar. 

Önce ameliyata, götürdüler bu zâtı, 

Şehir hastanesinin, ondokuzuncu katı, 

Üstünde kimliği yok, kimbilir kimin nesi, 

Belki de sokakların, isimsiz çingenesi. 

Birkaç saat geçipte, sabırlar tükenince, 

Meraklı gasteciler, soruyla yüklenince, 

Doktorun biri çıktı, dedi ki ''sessiz olun'', 

''Burası bir hastane, birazcık dilsiz olun''.

...............Sorularsa peş peşe, yağmur gibi dizildi,

...............Şüphelerin herbiri, cevaplarla çizildi,

...............Doktorsa devam etti, “akıbeti gizemli”,

...............”Hasta yoğun bakımda, ilk günü çok önemli”.

14 Haziran / Los Angeles

*** ''Akrep ve Yelkovan'', 2. bölümüyle Salı günü devam edecek...', 'Yer Los Angeles şehri, saat gecenin dördü,  Ve aylardan Haziran, sıcak ayın ondördü,  Şehrin tam sessizliğe, büründüğü saatler,  Kimbilir ka...', ARRAY['Türk Edebiyatı','Şiir','Metin Eser']::text[], 8.5, '{"poet":"Metin Eser","poet_slug":"metin-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/a-k-r-e-p-v-e-y-e-l-k-o-v-a-n-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda uğruna', 'sevda-ugruna-burhan-kucuk-auses', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevda uğruna

Açmıştım kalbimi

Sonuna kadar

Gökyüzü gibi

Saf ve temiz

Bir sevda uğruna

Harcadım yüreğimin

Cömertçe her karesini

Ah.. ayrılık

Başladığı gibi değil şimdi

Karardı ortalık

Böyle gelmemişti aşk

Böyle de gidilmez

Burhan KÜÇÜK

Kdz.Ereğli-17.10.2004', 'Sevda uğruna Açmıştım kalbimi Sonuna kadar Gökyüzü gibi Saf ve temiz Bir sevda uğruna Harcadım yüreğimin Cömertçe her karesini Ah.. ayrılık ...', ARRAY['Türk Edebiyatı','Şiir','Burhan Küçük']::text[], 8.5, '{"poet":"Burhan Küçük","poet_slug":"burhan-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevda-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkulu Rüyalar Görüyorum Anne', 'korkulu-ruyalar-goruyorum-anne-aydan-ortulu-pq2m8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'eskiler; 

“kapanırken kapının biri,

açılırmış bir diğeri” diyorlar.

yani; 

kötü de olsa başa gelen,

“her işten bir hayır” bekliyorlar.

ama; 

bu iş hep böyle olmuyor,

her işten bir hayır doğmuyor

ve,

yüzümüze kapanan kapıların ardından

başka kapılar açılmıyor.

hani; 

başına gelmeyen bilmezmiş,

ve, açın halini ancak

aç olanlar bilirmiş.

demem o ki; 

denize düşen sarılırmış yılana.

ve ben açım.

ve başımda bin bir türlü hal var,

her işte bir hayırsızlık

ve başka yerden açılmamacasına

birer birer kapanıyor kapılar.

yüzme bilmiyorum,

ve yüksekten de korkuyorum,

ve düştüm bir yarısında gecenin

karanlık sularına denizlerin.

boğuluyorum,

ama sarılmayacağım yılanlara

takıp da şarkıları saçlarının sarısına

..el vermesi için; 

bekliyorum.

sırılsıklam,

ve her yanımdan kanıyorum.

uykusuz, yorgun, viran

ve yanıyor ciğerimin ortası.

sesini getirir bilmediğim bir şarkı,

gözlerinin yaşını getirir:

“okyanus mu iki şehrin arası

kaç saatlik yol ki şunun şurası? ”

azgın dalgalar, ölümcül

Aydan

ve yıldızlardan gözlerimize konuk

yakamozları boğan

ve kuşatmışlığında azgın dalgaların,

okyanusta kaybolan gemilerin

imdadına yüzen yunuslar misali

bekliyorum,

depremlerle yitirdiğimi.

20.Haziran.2000/İstanbul', 'eskiler;  “kapanırken kapının biri, açılırmış bir diğeri” diyorlar. yani;  kötü de olsa başa gelen, “her işten bir hayır” bekliyorlar. ama; ...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/korkulu-ruyalar-goruyorum-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarhoşun Mektubu', 'sarhosun-mektubu-aydan-ortulu-ypsev', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sana gelmek istedim dün gece.

hasretin,

bulutlarda bağdaş kurmaktaydı,

ve kanımda da şarap vardı.

mendilci çocuklar oynuyordu

otobüs durağında; 

geçip de gözlerimdeki kalabalıklardan

kapına gelmek istedim.

bütün otobüsler boştu,

ve bütün duraklar.

adını bile bilmediğim birinin

yatağındaydım,

ve dürbünlüyordu gölgemi

dikbaşlı bakışlar. 

gecenin zulasında

yola çıkmıştı uğrular,

ay karanlık; 

unutmuşum ayaklarımı kapı önünde,

çalmışlar...

 

ellerini tutmak istedim dün gece.

çöplükler sokak kedilerine

güneşli bir demet sunmaktaydı,

ve kanımda da konyak vardı.

kuş soluğu kokulu

yağmurlar yağıyordu sokağına,

derip de yediveren şiirleri

yürek soframdan

pencerene ürkek serçeler getirdim.

bütün evler boştu,

ve bütün apartmanlar.

insancıl olan her duyguyu

hesapsızca paylaşmalardaydım,

ve umudun rengine bürünüyordu

asi şiirler,

senli yazılar.

oysa,aşkını

çalmaya hırsızlanmıştı ellerim

birden doğdu geceye ay,

aydınlık; 

yakalandım polise,

ellerimi kesip atmışlar...

 

gözlerini görmek istedim dün gece.

bir sokağın kuytusunda

ölüler kurşunlanmaktaydı,

ve kanımda da votka vardı.

gökyüzünde birer birer

yıldızları söndürüyordu Hera.

serip de bıçaklanmış uykuları

urbasından,

kirpiklerinin parmaklığında,

gözlerinde tutuklanmak istedim.

bütün mezarlar boştu,

ve bütün tabutlar.

karaları değil,

yıldızları kuşanmalardaydım,

ve tenceresinde

tehlikeli şiirler pişirmekteydi

sarhoşlar.

zamanın bilinmezinde durmuştu

bütün saatler

saklamıştım cüzdanımda,

şanssızlık; 

düşürmüşüm bilmediğim bir yerde

gözlerimi,

kaybolmuşlar.

 

şimdi; 

ne el, ne ayak,

ne de göz kaldı.

gökdelenlerin görkemli şahikasının

gölgelendiği yerde,

baltalanmış çınar gibi

ayrı düşmelerdeyim.

bir ceset,

şişiyor parkın ortasında yavaş yavaş

kara gözlüklü,

kara gölgeli adamlar

yarın,

onu sehpada asacaklar.

başı puşilenmiş korkulardayım,

ve bu gece,

içkiyi böyle karıştırmamalıydım.

gelemiyorum sana,

yok işte ellerim,

ayaklarım,

ve gözlerim yok işte.

göremiyorum, yokluklardayım.

oysa,

yüreğimizden hüzün dolu 

çiçekler derlemiştik; 

damarlarımda alkol,

damarlarımda kara gölgelerin

ayak sesleri; 

kopardılar.

yetiş! 

bir yüreğim kaldı bende,

..emanetin.

ihanetsiz soluklarla,

ölü köpek bakışlarındayım.

25.Haziran.2000/İstanbul', 'sana gelmek istedim dün gece. hasretin, bulutlarda bağdaş kurmaktaydı, ve kanımda da şarap vardı. mendilci çocuklar oynuyordu otobüs durağın...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":102,"source_url":"https://www.antoloji.com/sarhosun-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sübjektif', 'subjektif-aydan-ortulu-5axdr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'altın kafeslere de olsa,

kuşların kapatılmalarını istemiyorum.

..ve akvaryumlara balıkların.

sevmiyorum dar yerleri! 

çünkü,

özgürlüğe dair sevdalar büyütüyorum.

ama; 

birkaç zamandır

gecelerin en alacasında,

en olur olmazında yani,

dev bir akvaryumun 

renkli ışıklarınca,

geçip de karşısına

radyomu seyrediyorum.

..ve saati gelince,

gelince vakti zamanı,

okyanusların maviliğince kara radyomdan

türkülerin çağıltılarını

takıp da saçlarına,

“bana armağan”

annemin,tıka basa şefkat dolu

sesinde seyrediyorum.

..gözlerimi ayırmadan.

 

çocukların; 

merakla ve sevinçle

toplanıp da başına akvaryumun,

camına küçük parmak darbeleriyle

vurmaları gibi

..balıkları çağırmak için...

..el ediyorum.

18.Haziran.2000/İstanbul', 'altın kafeslere de olsa, kuşların kapatılmalarını istemiyorum. ..ve akvaryumlara balıkların. sevmiyorum dar yerleri!  çünkü, özgürlüğe dair ...', ARRAY['Türk Edebiyatı','Şiir','Aydan Örtülü']::text[], 8.5, '{"poet":"Aydan Örtülü","poet_slug":"aydan-ortulu","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/subjektif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenen', 'ozlenen-ahmet-kurt-5q1k6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Muhabbet deminde, unutma sakın,

Ya özlenen ol ya da gözlenen.

Gözlerden gönüle başlasın akın,

Ya özlenen ol ya da gözlenen.

Hoyrat gecelere yorma düşünü,

Vakitsiz diyerek koyma işini,

Kapat gözlerini, gör gidişini,

Ya özlenen ol ya da gözlenen.

Unutmak ağrısız kalbin sızısı,

Unutulmak ömrün kara yazısı,

Yürekte başlarken en son kazısı,

Ya özlenen ol ya da gözlenen.

Al sana hazine, al sana varlık,

Yanan gönülleri görsün insanlık,

Hayatlar geçici, hevesler anlık,

Ya özlenen ol ya da gözlenen.

Kurdoğlu bugünden yarını besle, 

İrkilme duyduğun o yanık sesle,

Sarıl ümidine bin bir hevesle,

Ya özlenen ol ya da gözlenen.', 'Muhabbet deminde, unutma sakın, Ya özlenen ol ya da gözlenen. Gözlerden gönüle başlasın akın, Ya özlenen ol ya da gözlenen. Hoyrat gecelere ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ozlenen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğuş', 'dogus-gulsah-suder-uzunmehmetoglu-bkmlv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her şey bir nefes alışla başladı.

Gözlerinde ilk ışıklar

Dudaklarında ilk kıpırtılar

Nefesi bahardı

Sesi rüzgar

Saçlarında denizlerin meltemi

Teninde alevlerin yedi rengi

''Merhaba''dedi

Dünyaya,insanlara

Ve sevgiye

Doyumsuz tatlara

Ölesiye aşklara

Bitimsiz acılara

''Merhaba''dedi.', 'Her şey bir nefes alışla başladı. Gözlerinde ilk ışıklar Dudaklarında ilk kıpırtılar Nefesi bahardı Sesi rüzgar Saçlarında denizlerin meltem...', ARRAY['Türk Edebiyatı','Şiir','Gülşah Süder Uzunmehmetoğlu']::text[], 8.5, '{"poet":"Gülşah Süder Uzunmehmetoğlu","poet_slug":"gulsah-suder-uzunmehmetoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/dogus-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen de Sevdalara Karış...', 'sen-de-sevdalara-karis-i-brahim-ethem-bingul-xnfd3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sev

Sevil

Sevdiğinle sevgili ol

Küs kalmak yok hesapta 

Dargınsan hemen barış...

Yaklaş 

Yakınlaş

Severken de,sevilirken de güçlü ol

Sevgisizlikten uzaklaş

Sevdaya alış...

Gör

Görüş

Süslesin günlerini

Senden bir tebessüm

Ondan bir gülüş

Sevdalı bir sarılış...

Bazen sevmede yarış

Bazen '' çok sevsin'' diye

İçten,derinden gelsin

En içli yakarış...

Bazen yol boyu koşu

nefes nefese kalış

Bazen kalakalıp sararıp

Yol alamamak bir karış...

Bunlar aşka çeker seni

Ne olursa olsun,hepsi sevdadır

Sönen bir ateşin kalan külünde

Bir kıvılcım görsen

Adı sevdadır

Sen de sevdalara karış...  

www.iebingül.com', 'Sev Sevil Sevdiğinle sevgili ol Küs kalmak yok hesapta  Dargınsan hemen barış... Yaklaş  Yakınlaş Severken de,sevilirken de güçlü ol Sevgisi...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-de-sevdalara-karis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öykü', 'oyku-guler-ilgaz-f9pgv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tepelerin birinde

Yalnız bir ağaç yaşarmış

Kökleriyle toprağa

Sıkı sıkı bağlıymış

Toprak onu pek cömertçe beslermiş

Gel zaman git zaman

Serpildikçe serpilmiş

Geliştikçe gelişmiş

...........

Arasıra kuşlar konar dallarına

Zaman zaman rüzgar dolaşır

Yaprakları arasında

''Bir tablo kadar güzelsin'' derlermiş

...........

Bir gün yıldırımlardan önce

İnsan bakışlarının dikkatini çekmiş

Gelmişler, kesmişler, biçmişler

Yoğurmuşlar,

Hamurundan 1. sınıf kağıt yapmışlar

Güzel mi güzel bir masanın üstüne koyup

Üzerine şöyle yazmışlar

''ÇOK ÖNEMLİ''', 'Tepelerin birinde Yalnız bir ağaç yaşarmış Kökleriyle toprağa Sıkı sıkı bağlıymış Toprak onu pek cömertçe beslermiş Gel zaman git zaman Serp...', ARRAY['Türk Edebiyatı','Şiir','Güler Ilgaz']::text[], 8.5, '{"poet":"Güler Ilgaz","poet_slug":"guler-ilgaz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/oyku-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşünmek Saadeti', 'seni-dusunmek-saadeti-oktay-celep-mo8qj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ruhumun her zerresine siner

varlığı bilmek, hissetmek, düşünmek saadeti

bu saadet ki; 

turkuvaz renkli dalların baharında

rengârenk kelebek kanatları gibi özgür olmaktır

bu saadet ki; 

yalnızlığa, umutsuzluğa, mutsuzluğa meydan okuyan,

alabildiğince güzelliklerle dolu bir yürek taşımaktır

bilsen bende ki bu saadeti,

bilsen bendeki bu seni

ne denli eşsiz bir varlık yarattığımı

ne denli sevdiğimi seni; 

işte o zaman anlardın beni

sende severdin “o” seni', 'ruhumun her zerresine siner varlığı bilmek, hissetmek, düşünmek saadeti bu saadet ki;  turkuvaz renkli dalların baharında rengârenk kelebek ...', ARRAY['Türk Edebiyatı','Şiir','Oktay Celep']::text[], 8.5, '{"poet":"Oktay Celep","poet_slug":"oktay-celep","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-dusunmek-saadeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'El de Sarhoş Ama Sevenler Her Gün', 'el-de-sarhos-ama-sevenler-her-gun-i-smet-barlioglu-b3b5z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevda ne tatlı şey, ne tatlı ahenk,

Hem ılık, hem güzel, hem de rengarenk,

Sanki baş üstünde bir altın çelenk,

Derdi de çekilir mihnetleri de.

Sevdalı gönüller nasıl da garip,

Sadece kalplerde ararlar nasip,

Kalbin tutuşması ne de acaip; 

Ölümü de ister, cinnetleri de.

El de sarhoş ama sevenler her gün,

Her akşam tedirgin, her akşam üzgün,

Aşk bir fırtına ki tayfundan azgın,

Yağdırır dertleri, illetleri de.

Kalp seveni görür karanlıkta da,

Yakında da sever, en uzakta da,

Gönül bir kaldımı öyle ortada

Derdi de benimser, illetleri de.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 21-22/100)', 'Sevda ne tatlı şey, ne tatlı ahenk, Hem ılık, hem güzel, hem de rengarenk, Sanki baş üstünde bir altın çelenk, Derdi de çekilir mihnetleri d...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/el-de-sarhos-ama-sevenler-her-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feryadım Eklendi Feryatlarıma', 'feryadim-eklendi-feryatlarima-i-smet-barlioglu-ynvso', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapanmaya görsün kapılar bir kez

Kapanır her biri ardı ardına.

Kalbimi dört yandan çevirdi herkes,

Feryadım eklendi feryatlarıma.

Kaynaklar içinde kalmışım susuz,

Zenginlik içinde parasız pulsuz,

Uğrunda bir ömrüm geçti uykusuz,

Yine gelemedin imdatlarıma.

Kalbimi elimle sana terk ettim,

Sanki terk ettim de iyi mi ettim? 

Sen vurup kanattın, bense seyrettim

Özlemler duyarak rahatlarıma.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 23-23/100)', 'Kapanmaya görsün kapılar bir kez Kapanır her biri ardı ardına. Kalbimi dört yandan çevirdi herkes, Feryadım eklendi feryatlarıma. Kaynaklar ...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/feryadim-eklendi-feryatlarima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cellat', 'cellat-muammer-hacioglu-u0ocx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bugün salı

bir ay oldu onu asalı

solmuştur şimdi

karısının, mezarına koyduğu çiçek

vücudu yavaş yavaş çürüyordur

yakında burnu düşecek

oysa

ne bir kötülüğü oldu bana

ne de kendini tanıyorum

birkaç kuruş için geçirdim ipi boğazına

parmaklarımdan utanıyorum', 'bugün salı bir ay oldu onu asalı solmuştur şimdi karısının, mezarına koyduğu çiçek vücudu yavaş yavaş çürüyordur yakında burnu düşecek oysa ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Hacıoğlu']::text[], 8.5, '{"poet":"Muammer Hacıoğlu","poet_slug":"muammer-hacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/cellat-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tren Sesi Duysam Kalbim Ayaklanıyor', 'bir-tren-sesi-duysam-kalbim-ayaklaniyor-i-smet-barlioglu-wismc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm karanlık tüneller bana ümit kapısı,

Sanki bir tren çıkıp hep seni getirecek.

her biri zalimlikte birbirinin tıpkısı,

Beklemekten yüreğim ha öldü, ha ölecek.

Bir tren sesi duysam kalbim ayaklanıyor,

Yüreğim hançereme çıkarak dayanıyor,

Ruhum bayram etmeye nasıl hazırlanıyor,

Sendeki zalimliği kalbim nerden bilecek? 

Her tren sessiz çıkar yorgun, argın tünelden,

Durgun birer geçişle uzaklaşır gözlerden,

Senle gelecek tren çıkmıyorsa gönülden

Onu ordan hangi el çıkaracak, silecek? 

Geçer bomboş trenler birbirinin ardından,

Kim anlar bir yaralı yüreğin feryadından,

Kimbilir hayalimin hangi battal hattından

Bir tren ıslık çalıp seninle görünecek.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 24-25/100)', 'Tüm karanlık tüneller bana ümit kapısı, Sanki bir tren çıkıp hep seni getirecek. her biri zalimlikte birbirinin tıpkısı, Beklemekten yüreğim...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-tren-sesi-duysam-kalbim-ayaklaniyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zavallı Yüreğimi', 'zavalli-yuregimi-i-smet-barlioglu-l1sm0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saçın yangın içinde,

Sanki güneş gücünde,

Yaktı ilk gördüğümde

Zavallı yüreğimi.

Seni gördüm ve sevdim,

Beğendim, önemsedim,

Derhal eline verdim

Zavallı yüreğimi.

Niçin, neden acaba

Sürüklendim azaba? 

Düşürdün ızdıraba

Zavallı yüreğimi.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 26-26/100)', 'Saçın yangın içinde, Sanki güneş gücünde, Yaktı ilk gördüğümde Zavallı yüreğimi. Seni gördüm ve sevdim, Beğendim, önemsedim, Derhal eline ve...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zavalli-yuregimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtaplar Altında Durmuş Gibiydin', 'mehtaplar-altinda-durmus-gibiydin-i-smet-barlioglu-5xheb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece uyurken seni seyrettim,

Masallardan gelen bir kuş gibiydin.

Yüzünün rengini güle benzettim,

Yorulup renklere konmuş gibiydin.

Sanki dört yanında gelincik vardı,

Alnında bir eski öpücük vardı,

Yüzünde tatlı bir gülücük vardı,

Mehtaplar altında durmuş gibiydin.

Uzun kirpiklerin sanki sırmadan,

Saçların kaymıştı omuzlarından,

Yavaşça seyrettim seni doymadan,

Derin bir uykuya varmış gibiydin.

Yanındaydım ama sen bilemedin,

Yaşlı gözlerimi hiç göremedin,

Ne beni fark ettin, ne irdeledin,

Masmavi göllere dalmış gibiydin.

(ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 27-28/100)', 'Dün gece uyurken seni seyrettim, Masallardan gelen bir kuş gibiydin. Yüzünün rengini güle benzettim, Yorulup renklere konmuş gibiydin. Sanki...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mehtaplar-altinda-durmus-gibiydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Öyle Bakma Karşılaştıkça', 'bana-oyle-bakma-karsilastikca-i-smet-barlioglu-yn8fr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana öyle bakma karşılaştıkça; 

Gördükçe yüreğim yaralanıyor.

Bayramlar-seyranlar içinde olsa

Yine yas tutuyor, karalanıyor.

Yağmurda altına sindiğin saçak,

Bir yandan bir yana uçan salıncak,

Çalıdan-çırpıdan yaktığın ocak

Gözümün önünde sıralanıyor.

Böyle mi koparmış tırnak etinden? 

Kalbim hançerlenmiş binbir yerinden,

O bakış geçtikçe o gözlerinden

Yüreğim yanıyor, hırpalanıyor.

Yanıp gidiyorum mahzun haline,

Acımı tarife yetmez kelime,

O halle ne zaman baksan yüzüme

Kanayan yüreğim tırmalanıyor.

(Hikmet BARLIOĞLU (1933-2003)  ''nun

ZEYTİNLER ALTINDA isimli Hece Şiirleri ''nden > 29-30/100)', 'Bana öyle bakma karşılaştıkça;  Gördükçe yüreğim yaralanıyor. Bayramlar-seyranlar içinde olsa Yine yas tutuyor, karalanıyor. Yağmurda altına...', ARRAY['Türk Edebiyatı','Şiir','İsmet Barlıoğlu']::text[], 8.5, '{"poet":"İsmet Barlıoğlu","poet_slug":"i-smet-barlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bana-oyle-bakma-karsilastikca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MumAlev', 'mumalev-atanur-memis-reuh4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bizim yaşadığımız

hayatı mı yaşıyorsun..

durduramazsın ellerini 

onlar hep istedikleri yerlerde olacaklar 

bir akrep boyuna zehir akıtacak ağzına 

bir yelkovan üstünden geçecek ömrümüzün 

dokunup kaçacaksın ateşten 

elde avuçta bu

ve ölümden 

bir defter şiir öncesi 

yatak dağınık 

yanmak güzeldi 

kendilerini karartıyor mumlar şimdi 

ve hayata çakıyor 

paslı çiviler mısraları daha bir

çöller 

ve yağmurlar ötesi 

sus pustum 

çekilmişti denizler midye kabuk 

karanlığım ve ben 

kırık dökük kitapların 

boynumda izi 

mısralar geliyordu senin ülkenden

mumalev! 

yandı kağıtlar 

- küller

seni onlara bırak 

avuçlarında karartılmış odalar 

kurumuş güller 

savurmak savurmak savurmak

günler ve geceler boyunca 

mısralar geliyordu senin ülkenden

hele iniyordu ay 

neşter geceden! 

mart

1997', 'bizim yaşadığımız hayatı mı yaşıyorsun.. durduramazsın ellerini  onlar hep istedikleri yerlerde olacaklar  bir akrep boyuna zehir akıtacak a...', ARRAY['Türk Edebiyatı','Şiir','Atanur Memiş']::text[], 8.5, '{"poet":"Atanur Memiş","poet_slug":"atanur-memis","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mumalev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Samanyolu', 'samanyolu-nalan-kazazoglu-vk3im', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çağırırım içimdeki sesi dizimin dibine,

Pencereme sığan yıldızların önüne..

Saçlarından tutunurum dünyaya...

Elim kolum bağlı yönü belirsiz yolda

Ağır dizelerin dizginleri boşta...

Dökülür ipini koparan mısralar masama,

Sarhoş rüzgar onları kaçırır, verir aya..

Kovalar rüzgarı yıldızlar..

Samanyolu gelir uzanır siyaha

Takılır geceye gerili ağa...', 'Çağırırım içimdeki sesi dizimin dibine, Pencereme sığan yıldızların önüne.. Saçlarından tutunurum dünyaya... Elim kolum bağlı yönü belirsiz ...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/samanyolu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karabatak Aşkımız', 'karabatak-askimiz-gokhan-karaduman-1mr2p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kadıköy''ün bu ılık gecesinde

Yanımda sen varsın

İçimde aşkın

Dalgaların her vuruşunda Kayalara

İçimden seviyorum diye 

Haykırmak geliyor  Şahikalara.

Bir vapur daha geçiyor

Rıhtımda bıraktığı adamın

Umutlarını alarak pervazına.

İşte bak

Karabataklarda aşkımız gibi

Batıp, çıkıyor Dalgalaraın arasında.

Ve bir martı uçuşuyor başımıazda

Aşkımızı alıp kaçmak için

Belki çok uzaklara

Belki yep yeni umutlara.', 'Kadıköy''ün bu ılık gecesinde Yanımda sen varsın İçimde aşkın Dalgaların her vuruşunda Kayalara İçimden seviyorum diye  Haykırmak geliyor  Şa...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Karaduman']::text[], 8.5, '{"poet":"Gökhan Karaduman","poet_slug":"gokhan-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karabatak-askimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanrım Sevgilimi Geri Ver.', 'tanrim-sevgilimi-geri-ver-ali-osman-yilmaz-n13od', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birazdan güneş,

Çat kapı penceremden,

Girecek içeri.

Ben yine yalnız,

Uyanacağım.

Yastığımda başının izi,

Duruyor hala,

Sarı saçlarından,birkaç tel,

Gülerek bana bakıyor.

Yastığıma sinen,

Kokusu bile duruyor.

Güneş şimdi,

Çat kapı girecek içeri,

Ortalık aydınlanacak,

Gözlerim yeni güne,

Yine O''nsuz açılacak.

Minarelerden sala’lar,

Sabah ezanları okunacak,

Ellerim semaya dönecek,

Dualar edeceğim tanrıya,

Tanrım ne olur,

Sevgilimi geri ver,

Cennetinde ‘O’ olmasa da olur,

‘O’ nun yerine tanrım,

Ne olur beni al.

İstersen beni,

Cehennem ateşinde odun yap,

Ama ne olur tanrım,

Bana ‘O’nu,

Geri ver.', 'Birazdan güneş, Çat kapı penceremden, Girecek içeri. Ben yine yalnız, Uyanacağım. Yastığımda başının izi, Duruyor hala, Sarı saçlarından,bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Osman Yılmaz']::text[], 8.5, '{"poet":"Ali Osman Yılmaz","poet_slug":"ali-osman-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/tanrim-sevgilimi-geri-ver-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin İle Buluşmak', 'gozlerin-i-le-bulusmak-engin-namli-7de2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevgilim her gün hayeline dalıp

El ele verip dolaşmak ne güzel

Ardın sıra hep gülücükler saçıp

Gözlerin ile buluşmak ne güzel

Sevginle yanıp tükenircesine

Aşk ateşine verilmek ne güzel

Tutuşan gönlüm küllenircesine

Aşk ateşinde kül olmak ne güzel

Gönül ufkumdan ümitle bakarken

Aşkın seyrine yol almak ne güzel

Yokluğuna tüm zamanlar akarken

Seni sabırla beklemek ne güzel

Derdi tasayı yüreğimden atıp

Yerine aşkı işlemek ne güzel

Üstünde gönül uykusuna yatıp 

Seni her gece düşlemek ne güzel

Engin NAMLI   13:43 17.10.2004', 'Sevgilim her gün hayeline dalıp El ele verip dolaşmak ne güzel Ardın sıra hep gülücükler saçıp Gözlerin ile buluşmak ne güzel Sevginle yanıp...', ARRAY['Türk Edebiyatı','Şiir','Engin Namlı']::text[], 8.5, '{"poet":"Engin Namlı","poet_slug":"engin-namli","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gozlerin-ile-bulusmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakış Açısı', 'bakis-acisi-tulay-sustam-gtbel', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kahverengi olsa da gözlerim

hayatı hep mavi görürüm...', 'kahverengi olsa da gözlerim hayatı hep mavi görürüm......', ARRAY['Türk Edebiyatı','Şiir','Tülay Sustam']::text[], 8.5, '{"poet":"Tülay Sustam","poet_slug":"tulay-sustam","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/bakis-acisi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapadok''ya', 'kapadok-ya-ufuk-nazim-30ymc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sus

Zaman dursun

Yalnız şu derenin

Şırıltısını

Ve göğe ağan

Şu söğüd yapraklarının 

Hışırtısını

Duyuyorum.

Sus

Gölgeler küçülsün

Derede çimen

Şu yeşil dalların gölgesi

Nasılda serin 

Nasılda dingin.

Sessizlik ve göğün çığlıkları

Sudaki huzur dolu mavide saklı.

Sus

Büyülü bu an

Üzüm bağlarından

Sağılan şıralar

Süzülsün peri bacalarına

İlahiler yayılsın Kapadok''yaya

Erciyes''e selam versin

Hasan Dağ''ı,sussun volkanlar.', 'Sus Zaman dursun Yalnız şu derenin Şırıltısını Ve göğe ağan Şu söğüd yapraklarının  Hışırtısını Duyuyorum. Sus Gölgeler küçülsün Derede çime...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Nazım']::text[], 8.5, '{"poet":"Ufuk Nazım","poet_slug":"ufuk-nazim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kapadok-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacı Bektaş Veli', 'haci-bektas-veli-atil-kesmen-9jjrs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin yüreğin nasıl çarpıyordu					

Kanın damarlarından sevgi olarak''mı akıyordu					

Bakışların ne anlatıyordu					

Gönlün ise ne dağıtıyordu					

Şeklin bize benzeyen beden dilinde........					

					

Sonsuzluklara ait bir nefesmidir bu 					

Soluyup soluyup''ta gönüllere verdiğinde hiç bitmeyen 					

Seni sen''de düşünmek					

Seni sen''de görmek					

Seni sen''de sevmek muhteşem olmalı					

Senin düşüncelerin					

Adalet, sevgi, saygı dağıtıyor					

Gönlünde yer bulmuş 					

Kor haline dönmüş, hak ateşinle					

					

Senin sevgi, saygı ile bütünleşmiş hak ateşini					

Tarif etmek ne mümkün					

Sen..					

Ben yalnızım kimsesizim					

Düştüm acı çekiyorum diyenlerin prensisin					

Sana ulaşmak ne mümkün					

Senin elini tutup					

Merhaba, merhaba demek ne mümkün.......					

					

Yanıyor düşüncelerin bir güneş gibi hak ocağında					

Acıları mutluluğa çevirdiğin					

Muhabbet dolu bu sofrada					

Akıyor huzur veren suların, gönül pınarlarından					

Sevgi adalet ise fışkırıyor bütün duvarlarından......					

					

Ne düşüncelerde ne muhabbettir bu					

Sevgi saygı mutluluk kokuyor tüm odaların					

Ne yenilir ne içilirdi bu hak ocağında					

Hangi derde çare bulunurdu, 					

Nur olmuş bu sevgi yumağında.......					

					

Seni gezip tanıdıkça kendimde bölündüm					

Önümü daha net görüyorum					

Yürüdüğüm sana ait bu sevgi yolunda					

Bedenim terliyor,hislerim ise kanat çırpıyor					

Gözlerim daha net görüyor					

Gönlüm bir hoş oldu					

Soğudukça ısındığım, ısındıkça yandığım					

Bu HACI BEKTAŞ  VELİ yanında....					

					

Kadersin asla diyemem sana					

Demem mümkün değil bu gönül yolcularına					

Taş olurum, nefessiz kalırım					

Ölüp yok olurum onların yanında					

Ne diyebilirim					

Hak''kı hak bellemiş, gönülden ses vermiş					

Düşüncelerinde sel olmuş					

Kendinde, kendini eğitirirken, sonsuzluğu hak etmiş					

Bu düşünce ocağına.....					

					

Senin muhabbet dolu bir yudum suyunu içmeye geldim					

Eşiğine basarken					

Titreyen ayağımla, senin güzelliklerini görmeye geldim					

Sen''de yanan gözlerimle					

Çağ''lara damgasını vurmuş					

Duvarlarında yazılı düşüncelerini okumaya geldim					

Gönlüme ise..					

Sen''de yanan sevgiyi, saygıyı, hak''kı yazmaya geldim....					

					

Affet, affet ne olur					

Farkında olmadan senin güzelliklerine deydim					

Şükürler olsun sana HACI BEKTAŞ VELİ					

Biz''de senin güzelliklerini bilelim					

Sevgi, saygı,hak yolunda ilerliyelim..........', 'Senin yüreğin nasıl çarpıyordu					 Kanın damarlarından sevgi olarak''mı akıyordu					 Bakışların ne anlatıyordu					 Gönlün ise ne dağıtıyor...', ARRAY['Türk Edebiyatı','Şiir','Atıl Kesmen']::text[], 8.5, '{"poet":"Atıl Kesmen","poet_slug":"atil-kesmen","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/haci-bektas-veli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tan Yeri Yüreğimin...', 'tan-yeri-yuregimin-i-mdat-ozcan-3414e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '........sen: Tan yeri yüreğimin 

..........sen: Katran karası gecelerde hilalim 

Irgatlığım baharda tarlada 

Meydanlarda yiğitliğim 

Zalime karşı isyanı gözlerimin 

Uğruna ölümler kuşandığım 

Tılsımım aşktan yana 

Ve tomurcuğum dalda 

Yağmur ardı toprak kokusu 

Çatayan dudaklarıma bir yudum su 

Yüreğime akan ırmak 

Düşlerimin çocuksu yanı 

En masum hayalim 

................sen: Serabım 

....................sen: Muradım 

Acemi yanı sevmelerimin 

Yüzümdeki solmayan tebessüm 

Deliliğim kavgada 

Mahsunluğum sevdada 

Sen: Güneşim 

Sen: Işığım 

Ustam hayata dair 

Şiirim 

En sevdiğim türkü 

Yakılmış mektubu görüş günümün 

Gözlerimde fer 

Aynada yansımam 

..................sen: Cennetim 

.....................sen: Kevserim 

Pusatım kahpe pusularında 

Dağlarda haykırışım 

Var olma sebebim 

Hayatımın anlamı 

Ve sen: Sevdiğim 

Yoluna baş koyduğum 

Benden ötesi 

Ve sen: İSTANBUL '' u 

Yüreğimdeki FATİH '' in....', '........sen: Tan yeri yüreğimin  ..........sen: Katran karası gecelerde hilalim  Irgatlığım baharda tarlada  Meydanlarda yiğitliğim  Zalime ...', ARRAY['Türk Edebiyatı','Şiir','İmdat Özcan']::text[], 8.5, '{"poet":"İmdat Özcan","poet_slug":"i-mdat-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/tan-yeri-yuregimin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedinya |', 'gelmedinya-zafer-zengin-etnika-3za1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'rüzgarlı bugün hava

çarpıyor ağacın kovuğa

yaprağın rengi

teknelerin içi

kadınların eteği

denizde yosunun teki

yalnızlığın sesi

sallanıyor

şaşırtmaman gibi

bardak uçuyor çayın etrafından

şeker kaçıyor tatsızlığa

rüzgarlı bugün mizah dergileri

sümer yazıları turuva destanı

gömütler bilim adamları

sallanıyor

şaşırtmıyorlar 

rüzgarlı bugün hava

hıncını saklıyor meydana

denizde balığa küfrediyor

gün boyu koy gezenler

gelmedinya

şimdi sana ne demeli

derin nefes alıp

türkü söylemeli

'' geleydin geleydin

   yüzüme güleydin

   bahcemde meyva

   yüreğimde sevda ''

gelmedinya

türküm yarım hala

kabuk atmış buğday

ne cana

ne toprağa

yaramaz aslında

gül bile olsa

budanmazda

23 08 2004 datca | dinlence |', 'rüzgarlı bugün hava çarpıyor ağacın kovuğa yaprağın rengi teknelerin içi kadınların eteği denizde yosunun teki yalnızlığın sesi sallanıyor ş...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelmedinya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyku', 'uyku-sair-orcun-3lj15', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yine kaçak uykular satıyor sabahlar

sarılıp güneşe yanmak için

                 en iyisi duvarlar,

                  yaslandığında

sert bir yastık ama serin.

Uyku tıpkı bir fahişe gibi

yavaş yavaş satıyor kendini...', 'yine kaçak uykular satıyor sabahlar sarılıp güneşe yanmak için                  en iyisi duvarlar,                   yaslandığında sert bir ...', ARRAY['Türk Edebiyatı','Şiir','Şair Orçun']::text[], 8.5, '{"poet":"Şair Orçun","poet_slug":"sair-orcun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uyku-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Ve Ölüm', 'dogum-ve-olum-yelda-akcos-sobcx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonsuzluğa ayak bastığın gündü şiirlerimin doğduğu gün,

Doğum ve ölüm, ilk kez dost oldu bugün,

Bir deste mum ve yanında kör kandil,

İkisine de armağan bir demet gül.

Doğum sancısı, ölüm sancısı,

İkisi de yürek yangısı,

Sensiz geçen her saniye,

Şiirlerimin yazgısı.

			

(17.08.2004, Ankara)', 'Sonsuzluğa ayak bastığın gündü şiirlerimin doğduğu gün, Doğum ve ölüm, ilk kez dost oldu bugün, Bir deste mum ve yanında kör kandil, İkisine...', ARRAY['Türk Edebiyatı','Şiir','Yelda Akcoş']::text[], 8.5, '{"poet":"Yelda Akcoş","poet_slug":"yelda-akcos","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogum-ve-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eceli Soluyorum', 'eceli-soluyorum-yelda-akcos-a37yg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dondu herşey,

Gün durdu, gece durdu,

İçimde yangın dondu, kan dondu,

Ölüler inliyor,

Ölüm sarıyor bedenimi,

Gönlümün yangını, mahşer alanı,

Kırılıp dökülecek birşey kalmadı,

Sensizlik! 

Boş yaşıyorum,

Gün, gün değil; ölüm azap değil,

Eceli soluyorum.

			

(09.08.2004, Ankara)', 'Dondu herşey, Gün durdu, gece durdu, İçimde yangın dondu, kan dondu, Ölüler inliyor, Ölüm sarıyor bedenimi, Gönlümün yangını, mahşer alanı, ...', ARRAY['Türk Edebiyatı','Şiir','Yelda Akcoş']::text[], 8.5, '{"poet":"Yelda Akcoş","poet_slug":"yelda-akcos","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eceli-soluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni topraktan yaptık; Kibele |', 'seni-topraktan-yaptik-kibele-zafer-zengin-etnika-9zuhc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'özümle yıktım askerlerini

liğme liğme şimdi etleri

gözlerine bulandı

kan ceken

saklayandı

şimdi sen

kutsal ana

mabedine saldıran

bu ölümden korkmaz

sevdalara aldırmaz

bu asker

bu derviş ile ne yapacaksın

ahhh sen değil

ölüm bile onu anlamaz

ihanet ettin tarihe

yalan yazılsa bile

şimdi

baba tanrı kolunda mı

nerede bıraktın adamını

nerde kellesi

nerde şimsekleri

nerde

omuzuna taş verdiği efendisi

sen

kadın

yumuşak başınla

sert kaya parçalayan

sakla çocuklarını

ölüm var

bizden ileri

bizden geri

şimdi mızrak hepsinin elleri

ağu kadar düşleri

bir bir yıkacak kaleni

saklanma

madem ki kader dersin

ilmine çıra sürmeden

bilgim

ve öldürdüklerimden güçlüyüm

onları ben var ettim dersin

işte o zaman

işte o zaman

sen ölümü hakettin

ıssız çölde selam vermediğin

ağacın gövdesi içinde

yolun basında belki

yeşil otun içinde

hangi böceği sevdin

güzel değildin

güzelleri istedin

şimdi 

yağız delikanlılar

kucağına bakar

sen taht yaparsın uzun saçlarına

tok dokunuşlarınla

kaç kol kırdın

sular akça

zehir attın

pişman mısın

o ki zehir sürdün yüreğe

acıma 

ve deki

ben aşk istemiştim

ben sevmiştim

kızımda sevmiş

nerden bilecektim

ve oğlum

ölüm istemedi benden

özgürlüğü çaldı elimden

kibele

anadolum kadar tanıdık

anadolum kadar açsın ona

çayır çimen kokulu

burnu yamuk

çiğ tutan saat

liman kapanması

geç saat

işte

çıkar karşına

kan kusturduğun insanlar

hesap sorar

tapınak yıkarlar

| devrim su kadar lazım insana..tazelenmek kurumuş dal kadar yeşermek |

hangi yangınla yakarım

hangi ateşle kutsarım

bir kök geliyor

lüğat 

ve tarih

ve şan şöhret yokken daha

kutsal doğmamışken

biz vardık toprakta

dön 

kibri bırak

bitti görevin

yeter artık

bu denizi kirlettiğin

o ki 

kale durmaz karşısında

o bizim aslanımız

kılavuzumuz

o varlığımız

o başkanımız

o padişahımız

dayanamaz işte

seytan ve burçlarınız

yıkacağız

kötü keşilmiş taşlarınızı

çocuklar büyüyor

nasırları sabırlı

dağ taş un

diclemde

fıratımda

kızılırmağımda

biz yıkanıp temizleneceğiz

| hayali kahramanlarınız kağıtlara biz çizip biz sileceğiz

  biz gerçeğiz ve çelikten keskiniz. biz hissedeniz |

şimdi gitme vakti

iri meme

zor düşman

kulu 

doğudan batıya dönenin

zift süreceğiz gözlerine

topraktan yaptık seni

kiline su

toprağına döl

kibrine us

şekline hayat koyduk

fetbaz güller açtın

şimdi onlarla öl

unutma

şimdi dön yurduna

al çocuklarını

dokunma umuda

az kalan can değil

çok kalan yol

döner ehil içinde

her şey

yürekte

sevdada

şimdi yıkılacaksın

bekle kibirli kale

tek bile olsan

mutluluk vermedin bize

ve bedduamızdır

yüzün gülmesin seninde

13.09 2004

*kibele; Tek tanrılı dinlerden önce insanlar çok tanrılı inanışlara sahipti. İlkel insanlar doğada gördükleri ama açıklayamadıkları güçlere tanrılık atfettiler. Gökyüzü, yıldızlar, ateş, Güneş ya da onları etkileyen herhangi bir doğa gücü onlar için tanrısaldı. Bilinen en eski inançlardan biri “ana tanrıça” kültüdür. Doğurganlığı, bolluğu ve bereketi temsil eden ana tanrıça fikri, isimleri bölgelere göre değişse de aynıydı. Kibele, Artemis, İştar, Astoreth ya da İnanna, ana tanrıçanın isimlerinden yalnızca birkaçı. Çok tanrılı inanışların en çok bilinen örnekleri Eski Mısır ve Eski Yunan’da karşımıza çıkıyor. Doğa güçlerinin kişileştirildiği bu dinlerde her tanrı ya da tanrıça ayrı bir gücü simgeliyordu. Eski Mısır’da Osiris, İsis, Seth, Hathor, Ra, Amon gibi büyük tanrıların yanında firavunların da tanrı olduğuna inanılırdı. Eski Yunan’daki belli başlı tanrıçalar ve tanrılarsa Zeus, Hera, Apollon, Poseidon, Hades, Afrodit, Hermes idi. Benzeri çoktanrılı inanışlar farklı tanrı ya da tanrıça isimleriyle dünyanın her yerinde görülür. Eski Türklerse şamanist inanca sahipti. Buna göre iyiliğin temsilcisi, en büyük tanrı olan Gök Tanrı’ydı. Kötülükse, yer altında yaşayan Erlik Han adıyla kişileştirilmişti. 

Tek tanrı inancının yerleşip yaygınlaşmasıyla bu dinler terkedildi...

kaynak:bilim ve teknik yayınları

*catalhoyuk civarindaki yontma tas devri kalintilarinda rastlanan, insanliga bereket, bolluk ve can verdigine inanilan (tabii eski zamanlarda) , matriarsik toplumlar hakkindaki dusuncelerimizi degistiren, ve degisik donemlerde degisik isimlerle anilan (mesela cybele, kybele, kubaba)   varlik.

bkn; eksi sözlük

777. şiirimle varacağım yere  vardım..iç sesimi paylaşanlara selam olsun..beğenenler sağolsun beğenmeyenler benden daha güzel yazsın mutlu olsun..bundan sonra yazacaklarım kendi kendime sohbetin derinleşmesi olur ancak..ya da iplemediğim zamanı değerlendirmek..insandan yana ısrarla beklediğim bir şey kalmadı ne olacaksa kendiliğinden olacak..bu birazda zirveye çıkan dağcının hissettiği boşluk gibi..yeniden bir hedef lazım yoksa durağanlık çöküyor..amaçsızlık gibi bir şey..selam ve saygıyla..', 'özümle yıktım askerlerini liğme liğme şimdi etleri gözlerine bulandı kan ceken saklayandı şimdi sen kutsal ana mabedine saldıran bu ölümden ...', ARRAY['Türk Edebiyatı','Şiir','Zafer Zengin Etnika']::text[], 8.5, '{"poet":"Zafer Zengin Etnika","poet_slug":"zafer-zengin-etnika","theme":"Türk Şiiri","is_hero":false,"total_lines":152,"source_url":"https://www.antoloji.com/seni-topraktan-yaptik-kibele-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kale', 'son-kale-tevfik-karinca-00hk4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kandırmalarına izin verdim, beni; 

Tüm insanların

İhanetlerine direnmedim

İzdüşümünde yakaladım yalanları

gözlerinde

Dağladım yüreğimi acırken içim

Aptal olmak yada sanılmak umurumda değil

Ama bil ki

Sen son kalesisin inançlarımın

Yıkılırsa eğer

Kalmayacak anlamı yaşamın', 'Kandırmalarına izin verdim, beni;  Tüm insanların İhanetlerine direnmedim İzdüşümünde yakaladım yalanları gözlerinde Dağladım yüreğimi acırk...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/son-kale-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara', 'ara-selcuk-ozdemir-4o2x6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sadece onu bil ve ona eğil, 

Solmaz ve eskimez o sözü ara 

Ama bakışıyla bakanı değil 

Ruhları hisseden o gözü ara… 

Halil İbrahim Özdemir', 'Sadece onu bil ve ona eğil,  Solmaz ve eskimez o sözü ara  Ama bakışıyla bakanı değil  Ruhları hisseden o gözü ara…  Halil İbrahim Özdemir...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Özdemir']::text[], 8.5, '{"poet":"Selçuk Özdemir","poet_slug":"selcuk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ara-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erzincan', 'erzincan-selcuk-ozdemir-6i93t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şu yüce dağları duman kaplamış

Yinemi gurbetten kara haber var

Seher vakti bu yerlerde kimler ağlamış

Çimenler üstünde gözyaşlarım var

Gönlümüz gamlanır böyle günlerde

Önüme çekilmiş bir kara perde

Yar senin aşkından tutuldum derde

Yinemi gurbetten kara haber var...

  Ali Ekber Çiçek', 'Şu yüce dağları duman kaplamış Yinemi gurbetten kara haber var Seher vakti bu yerlerde kimler ağlamış Çimenler üstünde gözyaşlarım var Gönlü...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Özdemir']::text[], 8.5, '{"poet":"Selçuk Özdemir","poet_slug":"selcuk-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/erzincan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış……! ! ! ! ! ! ! ! ! ! ! !', 'arayis-hikmet-feridun-demir-bm0ww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir Liman arıyorum,

barınacak.

Bir aşk arıyorum,

ısıtacak.

Bir Kalb arıyorum,

sımsıcak.

Bir dünya arıyorum,

yaşanacak.

Bitmez arayışım benim! 

Bir düşer, bir kalkarım.

Yaşam böyledir! 

Fark etmez benim için.

İster Olumlu olsun.

İster Olumsuz olsun.

Var olmaktır,

Düşünebilmektir,

Ayakta kalabilmektir,

Yaşayıp, yaşatabilmektir.

Asıl güzel olan.

Farkındamısın bunun! 

BİR den geldim,

BİR e giderim....', 'Bir Liman arıyorum, barınacak. Bir aşk arıyorum, ısıtacak. Bir Kalb arıyorum, sımsıcak. Bir dünya arıyorum, yaşanacak. Bitmez arayışım benim...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Feridun Demir']::text[], 8.5, '{"poet":"Hikmet Feridun Demir","poet_slug":"hikmet-feridun-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/arayis---siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güvercinli Yakınmalar', 'guvercinli-yakinmalar-yasin-mortas-7cgtm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yalnızlığımın kanlı gömleklerini çıkarıp

gözlerimi güne seriyorum

gözyaşının şefkâtli kollarında ki beni

zamanın tarifsizliğiyle süslüyorum

duvarlarını söktüm namlumla özleyişin

dişlerimi tan yerinin göğsüne geçirdim

duâları panzehiri yaptım hayatın

beyaz güvercinli yakınmaları

iki insan gibi dinledim

gülleri adını kötülemekle küstürdüm

arkamdan ince küfürler yağdırılır

ben boynunu bükerim aldanmaların

uzaktan kulaklarım çekilir bilirim

bağırmam suskun bir zamandır

elinden tuttuğum ölümün gözlerindeyim

taşın diyordu orada sevgi var

kapadım zihnimde ki beyaz uzakları

dizlerimin bağı çözülmüş

inceden yağan karlara ve dağlara dönüyorum

kayıp hücrelerini tamamladığım yılların

kopyasını alır taş gebeli işçiler

kahkahaların yüzsüzlüğü mavi ile boyanırken

ayaklarıma sızar seslenişler

yaz''87', 'yalnızlığımın kanlı gömleklerini çıkarıp gözlerimi güne seriyorum gözyaşının şefkâtli kollarında ki beni zamanın tarifsizliğiyle süslüyorum ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/guvercinli-yakinmalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dumanlı Hava', 'dumanli-hava-yasin-mortas-xgb93', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kar

yurt eder kalbin alacakaranlığını

ıssız bir düş aklımı çeler

bir kurdun gözünden alınan düşüncesi

keskince boğazımızı keser

kış''96', 'kar yurt eder kalbin alacakaranlığını ıssız bir düş aklımı çeler bir kurdun gözünden alınan düşüncesi keskince boğazımızı keser kış''96...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dumanli-hava-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kısrak', 'kisrak-yasin-mortas-rjuj1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kısraklar uzaklarda

kusurlarını yakmış kadar

                    esmerdir

bir su kaynağı

vadilerine kilitlenir kısrağın

                     bu vâdedir

koşmaları bir toz bulutunun

karanlığını unutturur nal türküsüyle

                     kişnemesi sâadettir

ağırlığını sınırı bekleyen nöbetçi kadar

sadık taşır,aşındırır yolları

                     koşması güne mühlettir

geçmiş zaman

kipinin içindeydi onlar

şimdi gelecek zaman dışında

                     kısraklar

güz''95', 'kısraklar uzaklarda kusurlarını yakmış kadar                     esmerdir bir su kaynağı vadilerine kilitlenir kısrağın                     ...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kisrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Dalgası', 'ruzgar-dalgasi-yasin-mortas-medzy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kış dağa çekti damarlarımızın

bahar akışlarını

yarınlar akşamın arkasından geçitini

güneşe yıktı

günlerimiz yorgun bir tay gibi

terledi uzun yollara

saçlarımız son bir defa rüzgarda dalgalanıp

foğraflarda kaldı

güz''93', 'kış dağa çekti damarlarımızın bahar akışlarını yarınlar akşamın arkasından geçitini güneşe yıktı günlerimiz yorgun bir tay gibi terledi uzun...', ARRAY['Türk Edebiyatı','Şiir','Yasin Mortaş']::text[], 8.5, '{"poet":"Yasin Mortaş","poet_slug":"yasin-mortas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ruzgar-dalgasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Rengi Siyah mı Leyla', 'sevdanin-rengi-siyah-mi-leyla-i-brahim-cam-srovt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevdanın Rengi Siyah mı Leyla

Sevdanın Rengi Siyahmı Leyla

Siyah mı ecelin apansız eli

Çileler devşiren gecenin kalbi

Kör olası matemin gözü

Siyah mı Siyah mı Leyla

Ben ömrü eksik uykularla boğuştum

Bilmedim gece safasını

Hasreti olan aşka kırmızı diyorlar

Vuslatı olan aşk siyah mı Leyla

Saklanır yeşil gecelerde 

Bir mermer düzünde yüzün saklanır

Kalbime ince ince değen

Bir hüzün saklanır

Ördüm uzun ıslak salgın saçlarını aşkın

İçinde bin bir başlı ejder saklanır 

Ve düştüm yalnızlık dehlizine

Aklıma dolaşıyorsun her dem gizlice

Senden başkasıyla paylaşamadığım

Yalnızlığın rengi,Siyah mı Siyah mı Leyla', 'Sevdanın Rengi Siyah mı Leyla Sevdanın Rengi Siyahmı Leyla Siyah mı ecelin apansız eli Çileler devşiren gecenin kalbi Kör olası matemin gözü...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çam']::text[], 8.5, '{"poet":"İbrahim Çam","poet_slug":"i-brahim-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdanin-rengi-siyah-mi-leyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulut Kuş -I-', 'bulut-kus-i-meltem-kaya-dw5o4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulut Kuşum! 

Bir soluk kadar uzun zamanda

Güneşi paylaştık yıldız çokluğunda

Sevdamızdan geçerek sevdik

Kavgayı ve aşkı...

Kardelenlerle dansa durur gibi

Uyandırdık geceleri

Ve şafak tohumuyla ektik

Aydınlık günlere başak umutlarımızı...

Günışığım, çağlayan gülüşlüm

Okyanus sevdaların maviliği

Gündoğumlarının kızıllığında

Hasretin rüzgarı dağıtsa da saçlarını

Unutma! 

Yarım kalmış bir şarkıyı söyleyecek her sabah

Bir meltem rüzgarı!', 'Bulut Kuşum!  Bir soluk kadar uzun zamanda Güneşi paylaştık yıldız çokluğunda Sevdamızdan geçerek sevdik Kavgayı ve aşkı... Kardelenlerle da...', ARRAY['Türk Edebiyatı','Şiir','Meltem Kaya']::text[], 8.5, '{"poet":"Meltem Kaya","poet_slug":"meltem-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bulut-kus-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HoŞgElDiN', 'hosgeldin-sair-serkan-baydere-d64yn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tamam sen kazandın

Ayrılmanın ardında gelen göz yaşlarımı

Rüzgara bırakıp

Titreyen bacaklarımın isyanlarına kulak asmadan 

Öylece koştum

Taki bir sekteye uğrayıp

Boylu boyunca yere uzanana kadar

Alışık olmadığın bir sevdaydı bu 

Yoğunlaştırılmış saf sevgi ağır geldi sana

Öyleki sen; 

İsyan bayraklarını çıkaracak

Soysuz,umarsamaz ilgilere alışıksın

Koştunmu peşinden sevdim diyorsun

Oysaki yalın ve ben kokan sevdam

Dağları kıskandıracak kadar yüceydi

Ve hiç bir aşk romanında konu olmayacak kadar özeldi

Ben dünde kalan hatırlarıma baktıkça 

O diyorum! 

O kadar doğaldı ki

Öpüştüğümüz anlarda gece daha bir kararırdı

Sırf sevdamızı başkalrı kıskanmasın diye

Ne tuhaf ki

Bunlar için hep geçmiş diyorum

Acı diyorum,azap diyorum.

Sen diyorum:

Yoksunluk geliyor aklıma.

Herşeyden, her güzel diye bahsedilenden

Uzak geliyor bana

Şayet birgün

Bir zaman arası 

Çıkıp girersen hayatıma

Sana söyleyebileceğim tek şey

Hayatım tekrardan hoşgeldin.', 'Tamam sen kazandın Ayrılmanın ardında gelen göz yaşlarımı Rüzgara bırakıp Titreyen bacaklarımın isyanlarına kulak asmadan  Öylece koştum Tak...', ARRAY['Türk Edebiyatı','Şiir','Şair Serkan Baydere']::text[], 8.5, '{"poet":"Şair Serkan Baydere","poet_slug":"sair-serkan-baydere","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/hosgeldin-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seneler Öncesinden', 'seneler-oncesinden-ceyhun-yildirim-m4rak', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün görücem seni 

Seneler geçmiş olucak üzerinden

Ve aşkımız zaman aşımına uğrayıp tozlu raflara kaldırılmış olucak çoktan

Seviyorum diyemiycem desem bile duramıycam sesimi seneler öncesinden

Ve bakamıycam yüzüne korkudan

Başkalarının dudak izlerini görürüm diye

Bir gün mahkümiyetim bitecek

İyi halimden dolayı beraat edicem tutsaklığından

Ama suçsuzluğum hala kanıtlanmamış olucak

Ve inanabiliyomusun yüzündeki gayri mechül dudak izleri delil olarak sayılmıycak

O seviyorum diyemiycem desem bile duramıycam sesimi seneler öncesinden

O zaman sevdiğim haykırıyorum şimdi

Seviyorum seviyorum seni', 'Bir gün görücem seni  Seneler geçmiş olucak üzerinden Ve aşkımız zaman aşımına uğrayıp tozlu raflara kaldırılmış olucak çoktan Seviyorum diy...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yıldırım']::text[], 8.5, '{"poet":"Ceyhun Yıldırım","poet_slug":"ceyhun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seneler-oncesinden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşaram', 'yasaram-ahmet-hani-sg67g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'çaylar kimi daşaram

qayaları aşaram

kimseye qul olmaram

azad azad yaşaram.', 'çaylar kimi daşaram qayaları aşaram kimseye qul olmaram azad azad yaşaram....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Hani']::text[], 8.5, '{"poet":"Ahmet Hani","poet_slug":"ahmet-hani","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yasaram-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-ergun-terzioglu-c7eua', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir kuş gibisin; 

Avcumda...

Açsam; 

Uçacak...

Yumsam; 

Ölecek...', 'Bir kuş gibisin;  Avcumda... Açsam;  Uçacak... Yumsam;  Ölecek......', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-464-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefesim', 'nefesim-ceyhun-yildirim-g0n7o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gidiyoruz farklı yollara, farklı yerlere

Kimisi çakıl kimisi asfalt kimisi de arnavut kaldırım yollara

Benim yolumu bulmak istersen güzelim

Gözyaşlarımı takip et ve çıglığıma gel

İçime akıttığım gözyaşlarımı ve sessiz çığlıklarımı yanlız sen duyabilirsin

Hissedeyim seni, varlığından umut ediyim güzel günleri

Gel, gel ki yeniden seveyim seni

Yanaklarına dokunayım ki ellerimin bozkırını hisset

Gel be canım, bi kere gel sonra yeniden git

Aslında gitme, yine soluksuz bırakma beni

Nefesim olmuşsun bir kere 

Gitme...', 'Gidiyoruz farklı yollara, farklı yerlere Kimisi çakıl kimisi asfalt kimisi de arnavut kaldırım yollara Benim yolumu bulmak istersen güzelim ...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yıldırım']::text[], 8.5, '{"poet":"Ceyhun Yıldırım","poet_slug":"ceyhun-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nefesim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Kırık hayatlar 2 **', 'kirik-hayatlar-2-kubilay-enginol-tp9gk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşlıtarla''da tahta ev,yağmur yağıyor çılgınca

Alların,pulların kadını,yatıyor boylu boyunca

Kare çantası başında,yok başka yastık

Her yer buz gibi,rüzgar çalıyor gönlünce ıslık

Hastalanmış pek fena,yok sigortası

Kenarda komşunun azıcık yenmiş sefertası

Tüm benliğini sarmış acı sefalet

Belliydi,yaşam zaten kötüye delalet

Gözünden akan damla,yanağını ısıttı

Üniversiteli bir genç kızla yaşıttı

Hani iltifatlar,meyvalar içkiler

Posa kalınca bırakıp gittiler

Taşlıtarla''da tahta ev,rüzgar ıslık çalıyordu

O,boylu boyunca geçmişiyle hesaplaşıyordu.', 'Taşlıtarla''da tahta ev,yağmur yağıyor çılgınca Alların,pulların kadını,yatıyor boylu boyunca Kare çantası başında,yok başka yastık Her yer b...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-hayatlar-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ben...', 've-ben-ergun-terzioglu-5hfvb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Genzime sinmiş bir koku nefesin,

Damağım terinin kel tiryakisi.

Bir meltemdir kulağımda eser sesin,

Ve ben... Gül dudakların kölesi.', 'Genzime sinmiş bir koku nefesin, Damağım terinin kel tiryakisi. Bir meltemdir kulağımda eser sesin, Ve ben... Gül dudakların kölesi....', ARRAY['Türk Edebiyatı','Şiir','Ergün Terzioğlu']::text[], 8.5, '{"poet":"Ergün Terzioğlu","poet_slug":"ergun-terzioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ve-ben-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzlerce Kadın', 'yuzlerce-kadin-orhun-basat-z1qei', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yüzlerce kadınsınız

ne olur

yalnızlığımı alıp koynunuza

birer gece yatsanız

ya da 

alıp kendi yalnızlığınızı

gelip bende kalsanız..', 'yüzlerce kadınsınız ne olur yalnızlığımı alıp koynunuza birer gece yatsanız ya da  alıp kendi yalnızlığınızı gelip bende kalsanız.....', ARRAY['Türk Edebiyatı','Şiir','Orhun Basat']::text[], 8.5, '{"poet":"Orhun Basat","poet_slug":"orhun-basat","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yuzlerce-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-mehmet-asim-nooga', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni düşlemek 

baharı düşlemek gibi 

yağmuru,yeşeren yaprakları 

yeşertmek,yaşatmak gibi... 

seni düşlemek 

seni hayal etmek 

ansızın esen rüzgarlar gibi 

denizin enginliği gögün maviligi gibi 

seni hayal etmek sevgili 

bir coçuğun korkudan anasına sokuluşu gibi 

bir kurşunun yürekteki sızısı gibi 

seni düşlemek ve hayal etmek sevgili, 

yaşam gibi,gerçek gibi 

ölüm gibi 

apansız ve amansız 

ve vazgeçilmez olan 

sen sevgili......', 'seni düşlemek  baharı düşlemek gibi  yağmuru,yeşeren yaprakları  yeşertmek,yaşatmak gibi...  seni düşlemek  seni hayal etmek  ansızın esen r...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Asım']::text[], 8.5, '{"poet":"Mehmet Asım","poet_slug":"mehmet-asim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sadece-sen-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
