INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Bir Halime', 'bak-bir-halime-fatih-konuk-razop', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'BAK BİR HALİME

Gitmeden bak bir halime

Sensizliğe alışacak gibi halim varmı diye

Bak bir halime

Acına dayanacak gibi gücüm varmı diye

Dönde bir bak halime

Giderken bak bir halime

Gözlerime bak bak bir anlatsın herşeyi

Ne kadar gözyaşı dökeceğini göstersin

Göstersin ki anla

Bırakırken bak bir halime

Uykusuz kalacağım günleri 

Uğrunda ağlayacığım günleri

Düşünde öyle git

Şöyle bak bir halime

Sensiz öleceğimi anlada öyle git

Gideceksen

.......................................................................................

