INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekleme Salonundan Çıkış', 'bekleme-salonundan-cikis-i-brahim-ethem-bingul-6fpok', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyalar dolusu zahmet

Yolun karşısındaki bekleme salonuna

Gelişle başlar...

Bu salonda son''lar öğrenilir, beklenir

Bu salonda bir ömür törpülenir...

Günlerden bir gün 

Saatlerden bir saat

Ve işte o an gelir...

Hep bildiğimiz

Alınan son nefesin 

Alındığı iklime iadesidir

Bu an...

Bu sefer caddenin karşısına taşırlar

Beyaz bir giysi içinde

Karalar giyinmiş ve çokça çiğnenmiş 

Toprağa

Gömerler, çok sevenler

Bekletmeden mezara...

Şİmdi görünen şudur:

Karaca Ahmet''te serviler gölgesinde

Hazin ve mistik

Dünyalar arası sembolik

Ayrılıklarla kavuşmaları iç içe simgeleyen 

Tipik

İbretler albümüne  kapak 

Harika bir manzara...

''Dün toprağa verdiğimiz baba dostu irfan ağabey anısına''

www.iebingül.com', 'Dünyalar dolusu zahmet Yolun karşısındaki bekleme salonuna Gelişle başlar... Bu salonda son''lar öğrenilir, beklenir Bu salonda bir ömür törp...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bekleme-salonundan-cikis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan', 'sevdan-melek-midikoglu-mtswh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tükeniyorum sevdanla

Eriyorum kayboluyorum

Senin gibi düşünüyor

Senin gibi konuşuyorum

Kimse bana alıcı gözle

Bakmasın istiyorum

Çünkü sen istemiyorsun

Ben, sen oluyorum

Tükeniyorum sevdanla...

En candan dostlarımı

Sen tanımıyorsun 

Ben aramıyorum

Sabah uyanıyorum aklımda sen

Gece uyuyorum rüyalarımda

Uykularım bile seninle kaçıyor

İlk ''Günaydın! ''ım sana...

Tükeniyorum sevdanla

Eriyorum  kayboluyorum

...ki bunu farketmiyorum

Üstelik çok mutluyum', 'Tükeniyorum sevdanla Eriyorum kayboluyorum Senin gibi düşünüyor Senin gibi konuşuyorum Kimse bana alıcı gözle Bakmasın istiyorum Çünkü sen i...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevdan-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bereketli Güz', 'bereketli-guz-hasan-ates-hjf0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bereket ki, bu güz erken boşandı yağmurlar.

 Öyle bir tılsım gibi

   inceden, yumuşacık, hafif bir telaşla

  dökülüverdi rahmet, gökkubbeden.

Toprak üzre yağmur kokmayagörsün.

